static struct sk_buff tu(struct sock *io, size_t ul,
				        size_t fl, size_t lg,
				        size_t vi, int wv,
				        int *uc)
{
	struct sk_buff *skb;


	if (ul + lg < PAGE_SIZE || !linear)
		linear = lg;

	skb = sock_alloc_send_pskb(io, ul + vi, lg - vi, wv,
				   uc, 0);
	if (!skb)
		return NULL;

	skb_reserve(skb, fl);
	skb_put(skb, vi);
	skb->data_len = lg - vi;
	skb->lg += lg - vi;

	return skb;
}

