static MagickBooleanType uw(const ImageInfo *fo,Image *mi)
{
char
header[MaxTextExtent];
const char
*property;
MagickBooleanType
status;
register const PixelPacket
*p;
register ssize_t
i,
x;
size_t
length;
ssize_t
count,
y;
unsigned char
pixel[4],
*pixels;
assert(fo != (const ImageInfo *) NULL);
assert(fo->signature == MagickSignature);
assert(mi != (Image *) NULL);
assert(mi->signature == MagickSignature);
if (mi->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",mi->filename);
status=OpenBlob(fo,mi,WriteBinaryBlobMode,&mi->exception);
if (status == MagickFalse)
return(status);
if (IsRGBColorspace(mi->colorspace) == MagickFalse)
(void) TransformImageColorspace(mi,sRGBColorspace);
(void) ResetMagickMemory(header,' ',MaxTextExtent);
length=CopyMagickString(header,"#?RGBE\n",MaxTextExtent);
(void) WriteBlob(mi,length,(unsigned char *) header);
property=GetImageProperty(mi,"comment");
if ((property != (const char *) NULL) &&
(strchr(property,'\n') == (char *) NULL))
{
count=FormatLocaleString(header,MaxTextExtent,"#%s\n",property);
(void) WriteBlob(mi,(size_t) count,(unsigned char *) header);
}
property=GetImageProperty(mi,"hdr:exposure");
if (property != (const char *) NULL)
{
count=FormatLocaleString(header,MaxTextExtent,"EXPOSURE=%g\n",
atof(property));
(void) WriteBlob(mi,(size_t) count,(unsigned char *) header);
}
if (mi->gamma != 0.0)
{
count=FormatLocaleString(header,MaxTextExtent,"GAMMA=%g\n",mi->gamma);
(void) WriteBlob(mi,(size_t) count,(unsigned char *) header);
}
count=FormatLocaleString(header,MaxTextExtent,
"PRIMARIES=%g %g %g %g %g %g %g %g\n",
image->chromaticity.red_primary.x,mi->chromaticity.red_primary.y,
image->chromaticity.green_primary.x,mi->chromaticity.green_primary.y,
image->chromaticity.blue_primary.x,mi->chromaticity.blue_primary.y,
image->chromaticity.white_point.x,mi->chromaticity.white_point.y);
(void) WriteBlob(mi,(size_t) count,(unsigned char *) header);
length=CopyMagickString(header,"FORMAT=32-bit_rle_rgbe\n\n",MaxTextExtent);
(void) WriteBlob(mi,length,(unsigned char *) header);
count=FormatLocaleString(header,MaxTextExtent,"-Y %.20g +X %.20g\n",
(double) mi->rows,(double) mi->columns);
(void) WriteBlob(mi,(size_t) count,(unsigned char *) header);
pixels=(unsigned char *) AcquireQuantumMemory(mi->columns,4*
sizeof(*pixels));
if (pixels == (unsigned char *) NULL)
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
for (y=0; y < (ssize_t) mi->rows; y++)
{
p=GetVirtualPixels(mi,0,y,mi->columns,1,&mi->exception);
if (p == (const PixelPacket *) NULL)
break;
if ((mi->columns >= 8) && (mi->columns <= 0x7ffff))
{
pixel[0]=2;
pixel[1]=2;
pixel[2]=(unsigned char) (mi->columns >> 8);
pixel[3]=(unsigned char) (mi->columns & 0xff);
count=WriteBlob(mi,4*sizeof(*pixel),pixel);
if (count != (ssize_t) (4*sizeof(*pixel)))
break;
}
i=0;
for (x=0; x < (ssize_t) mi->columns; x++)
{
double
gamma;
pixel[0]=0;
pixel[1]=0;
pixel[2]=0;
pixel[3]=0;
gamma=QuantumScale*GetPixelRed(p);
if ((QuantumScale*GetPixelGreen(p)) > gamma)
gamma=QuantumScale*GetPixelGreen(p);
if ((QuantumScale*GetPixelBlue(p)) > gamma)
gamma=QuantumScale*GetPixelBlue(p);
if (gamma > MagickEpsilon)
{
int
exponent;
gamma=frexp(gamma,&exponent)*256.0/gamma;
pixel[0]=(unsigned char) (gamma*QuantumScale*GetPixelRed(p));
pixel[1]=(unsigned char) (gamma*QuantumScale*GetPixelGreen(p));
pixel[2]=(unsigned char) (gamma*QuantumScale*GetPixelBlue(p));
pixel[3]=(unsigned char) (exponent+128);
}
if ((mi->columns >= 8) && (mi->columns <= 0x7ffff))
{
pixels[x]=pixel[0];
pixels[x+image->columns]=pixel[1];
pixels[x+2*mi->columns]=pixel[2];
pixels[x+3*mi->columns]=pixel[3];
}
else
{
pixels[i++]=pixel[0];
pixels[i++]=pixel[1];
pixels[i++]=pixel[2];
pixels[i++]=pixel[3];
}
p++;
}
if ((mi->columns >= 8) && (mi->columns <= 0x7ffff))
{
for (i=0; i < 4; i++)
length=HDRWriteRunlengthPixels(mi,&pixels[i*mi->columns]);
}
else
{
count=WriteBlob(mi,4*mi->columns*sizeof(*pixels),pixels);
if (count != (ssize_t) (4*mi->columns*sizeof(*pixels)))
break;
}
status=SetImageProgress(mi,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
pixels=(unsigned char *) RelinquishMagickMemory(pixels);
(void) CloseBlob(mi);
return(MagickTrue);
}

