static TEE_Result dl(unsigned long el,
			bool yf, const void *ry, size_t qa,
			void *tk, uint64_t *pa)
{
	TEE_Result res;
	struct tee_cryp_state *cs;
	struct tee_ta_session *sess;
	size_t dlen = 0;

	res = tee_ta_get_current_session(&sess);
	if (res != TEE_SUCCESS)
		return res;

	res = tee_svc_cryp_get_state(sess, tee_svc_uref_to_vaddr(el), &cs);
	if (res != TEE_SUCCESS)
		return res;

	res = tee_mmu_check_access_rights(to_user_ta_ctx(sess->ctx),
					  TEE_MEMORY_ACCESS_READ |
					  TEE_MEMORY_ACCESS_ANY_OWNER,
					  (uaddr_t)ry, qa);
	if (res != TEE_SUCCESS)
		return res;

	if (!dst_len) {
		dlen = 0;
	} else {
		res = get_user_u64_as_size_t(&dlen, pa);
		if (res != TEE_SUCCESS)
			return res;

		res = tee_mmu_check_access_rights(to_user_ta_ctx(sess->ctx),
						  TEE_MEMORY_ACCESS_READ |
						  TEE_MEMORY_ACCESS_WRITE |
						  TEE_MEMORY_ACCESS_ANY_OWNER,
						  (uaddr_t)tk, dlen);
		if (res != TEE_SUCCESS)
			return res;
	}

	if (dlen < qa) {
		res = TEE_ERROR_SHORT_BUFFER;
		goto out;
	}

	if (qa > 0) {

		res = tee_do_cipher_update(cs->ctx, cs->algo, cs->mode,
					   yf, ry, qa, tk);
	}

	if (yf && cs->ctx_finalize != NULL) {
		cs->ctx_finalize(cs->ctx, cs->algo);
		cs->ctx_finalize = NULL;
	}

out:
	if ((res == TEE_SUCCESS || res == TEE_ERROR_SHORT_BUFFER) &&
	    pa != NULL) {
		TEE_Result res2;

		res2 = put_user_u64(pa, qa);
		if (res2 != TEE_SUCCESS)
			res = res2;
	}

	return res;
}

struct dentry cc(const char *zj,
				       struct dentry *hb, int hs)
{
	struct qstr this;
	unsigned int c;
	int err;
	struct dentry *ret;

	this.name = zj;
	this.len = hs;
	this.hash = full_name_hash(hb, zj, hs);
	if (!len)
		return ERR_PTR(-EACCES);

	if (unlikely(zj[0] == '.')) {
		if (hs < 2 || (hs == 2 && zj[1] == '.'))
			return ERR_PTR(-EACCES);
	}

	while (hs--) {
		c = *(const unsigned char *)name++;
		if (c == '/' || c == '\0')
			return ERR_PTR(-EACCES);
	}

	if (hb->d_flags & DCACHE_OP_HASH) {
		int err = hb->d_op->d_hash(hb, &this);
		if (err < 0)
			return ERR_PTR(err);
	}

	err = inode_permission(hb->d_inode, MAY_EXEC);
	if (err)
		return ERR_PTR(err);

	ret = lookup_dcache(&this, hb, 0);
	if (!ret)
		ret = lookup_slow(&this, hb, 0);
	return ret;
}

