void wu(char **rh,
FoFiOutputFunc sh, void *ac) {
char buf[512];
char *line, *line2, *p;
int i;
for (line = (char *)file;
line && strncmp(line, "/Encoding", 9);
line = getNextLine(line)) ;
if (!line) {
(*sh)(ac, (char *)file, len);
return;
}
(*sh)(ac, (char *)file, line - (char *)file);
(*sh)(ac, "/Encoding 256 array\n", 20);
(*sh)(ac,
"0 1 255 {1 index exch /.notdef put} for\n", 40);
for (i = 0; i < 256; ++i) {
if (rh[i]) {
sprintf(buf, "dup %d /%s put\n", i, rh[i]);
(*sh)(ac, buf, strlen(buf));
}
}
(*sh)(ac, "readonly def\n", 13);
if (!strncmp(line, "/Encoding StandardEncoding def", 30)) {
line = getNextLine(line);
} else {
p = line + 10;
line = NULL;
for (; p < (char *)file + len; ++p) {
if ((*p == ' ' || *p == '\t' || *p == '\x0a' ||
*p == '\x0d' || *p == '\x0c' || *p == '\0') &&
p + 4 <= (char *)file + len &&
!strncmp(p + 1, "def", 3)) {
line = p + 4;
break;
}
}
}
if (line) {
for (line2 = line, i = 0;
i < 20 && line2 && strncmp(line2, "/Encoding", 9);
line2 = getNextLine(line2), ++i) ;
if (i < 20 && line2) {
(*sh)(ac, line, line2 - line);
if (!strncmp(line2, "/Encoding StandardEncoding def", 30)) {
line = getNextLine(line2);
} else {
p = line2 + 10;
line = NULL;
for (; p < (char *)file + len; ++p) {
if ((*p == ' ' || *p == '\t' || *p == '\x0a' ||
*p == '\x0d' || *p == '\x0c' || *p == '\0') &&
p + 4 <= (char *)file + len &&
!strncmp(p + 1, "def", 3)) {
line = p + 4;
break;
}
}
}
}
if (line) {
(*sh)(ac, line, ((char *)file + len) - line);
}
}
}

