static void io(
int ud, struct cfg80211_registered_device *bm,
struct net_device *xk, u64 zd,
struct ieee80211_channel *hg,
enum nl80211_channel_type gr,
unsigned int oe, gfp_t nf)
{
struct sk_buff *msg;
void *hdr;
msg = nlmsg_new(NLMSG_DEFAULT_SIZE, nf);
if (!msg)
return;
hdr = nl80211hdr_put(msg, 0, 0, 0, ud);
if (!hdr) {
nlmsg_free(msg);
return;
}
NLA_PUT_U32(msg, NL80211_ATTR_WIPHY, bm->wiphy_idx);
NLA_PUT_U32(msg, NL80211_ATTR_IFINDEX, xk->ifindex);
NLA_PUT_U32(msg, NL80211_ATTR_WIPHY_FREQ, hg->center_freq);
NLA_PUT_U32(msg, NL80211_ATTR_WIPHY_CHANNEL_TYPE, gr);
NLA_PUT_U64(msg, NL80211_ATTR_COOKIE, zd);
if (ud == NL80211_CMD_REMAIN_ON_CHANNEL)
NLA_PUT_U32(msg, NL80211_ATTR_DURATION, oe);
if (genlmsg_end(msg, hdr) < 0) {
nlmsg_free(msg);
return;
}
genlmsg_multicast_netns(wiphy_net(&bm->wiphy), msg, 0,
nl80211_mlme_mcgrp.id, nf);
return;
nla_put_failure:
genlmsg_cancel(msg, hdr);
nlmsg_free(msg);
}

