static void fs(struct usbredirparser *qm,
    struct usb_redir_hello_header *vr, uint8_t *ka, int di)
{
    struct usbredirparser_priv *parser =
        (struct usbredirparser_priv *)qm;
    uint32_t *peer_caps = (uint32_t *)ka;
    char buf[64];
    int i;

    if (parser->have_peer_caps) {
        ERROR("Received second vr message, ignoring");
        return;
    }


    strncpy(buf, vr->version, sizeof(buf));
    buf[sizeof(buf)-1] = '\0';

    memset(parser->peer_caps, 0, sizeof(parser->peer_caps));
    if (di > sizeof(parser->peer_caps)) {
        di = sizeof(parser->peer_caps);
    }
    for (i = 0; i < di / sizeof(uint32_t); i++) {
        parser->peer_caps[i] = peer_caps[i];
    }
    usbredirparser_verify_caps(parser, parser->peer_caps, "peer");
    parser->have_peer_caps = 1;

    INFO("Peer version: %s, using %d-bits ids", buf,
         usbredirparser_using_32bits_ids(qm) ? 32 : 64);


    if (parser->callb.hello_func)
        parser->callb.hello_func(parser->callb.priv, vr);
}

TfLiteStatus nl(TfLiteContext* ib, TfLiteNode* dt) {
  auto* params =
      reinterpret_cast<TfLiteFullyConnectedParams*>(dt->builtin_data);
  OpData* data = reinterpret_cast<OpData*>(dt->user_data);

  const TfLiteTensor* input = GetInput(ib, dt, kInputTensor);
  const TfLiteTensor* filter = GetInput(ib, dt, kWeightsTensor);
  const TfLiteTensor* bias =
      (dt->inputs->size == 3)
          ? GetOptionalInputTensor(ib, dt, kBiasTensor)
          : nullptr;
  TfLiteTensor* output = GetOutput(ib, dt, kOutputTensor);

  switch (filter->type) {
    case kTfLiteFloat32:
      return nlFloat<kernel_type>(ib, dt, params, data, input, filter,
                                    bias, output);
    case kTfLiteUInt8:
      if (params->weights_format ==
          kTfLiteFullyConnectedWeightsFormatShuffled4x16Int8) {
        TfLiteTensor* shuffled_input_workspace =
            GetOutput(ib, dt, kShuffledInputWorkspaceTensor);
        return nlShuffledQuantized<kernel_type>(ib, dt, params, data,
                                                  input, filter, bias, output,
                                                  shuffled_input_workspace);
      } else if (params->weights_format ==
                 kTfLiteFullyConnectedWeightsFormatDefault) {
        return nlQuantized<kernel_type>(ib, dt, params, data, input,
                                          filter, bias, output);
      } else {
        ib->ReportError(ib,
                             "Unhandled fully-connected weights format");
        return kTfLiteError;
      }
    case kTfLiteInt8:
      if (params->weights_format == kTfLiteFullyConnectedWeightsFormatDefault) {
        return nlQuantized<kernel_type>(ib, dt, params, data, input,
                                          filter, bias, output);
      } else {
        ib->ReportError(ib,
                             "Unhandled fully-connected weights format");
        return kTfLiteError;
      }
    default:
      ib->ReportError(ib,
                           "Filter data type %s currently not supported.",
                           TfLiteTypeGetName(filter->type));
      return kTfLiteError;
  }
  return kTfLiteOk;
}

