static int vu(HEVCContext *ra, int jj, int gn,
int zs, int tu, int ko, int oo,
int vg, int qp,
int zz, int xf, int *vc, int *jq)
{
HEVCLocalContext *lc = ra->HEVClc;
const int log2_trafo_size_c = qp - ra->ps.sps->hshift[1];
int i;
if (lc->cu.pred_mode == MODE_INTRA) {
int trafo_size = 1 << qp;
ff_hevc_set_neighbour_available(ra, jj, gn, trafo_size, trafo_size);
s->hpc.intra_pred[qp - 2](ra, jj, gn, 0);
}
if (xf || vc[0] || jq[0] ||
(ra->ps.sps->chroma_format_idc == 2 && (vc[1] || jq[1]))) {
int scan_idx   = SCAN_DIAG;
int scan_idx_c = SCAN_DIAG;
int cbf_chroma = vc[0] || jq[0] ||
(ra->ps.sps->chroma_format_idc == 2 &&
(vc[1] || jq[1]));
if (ra->ps.pps->cu_qp_delta_enabled_flag && !lc->tu.is_cu_qp_delta_coded) {
lc->tu.cu_qp_delta = ff_hevc_cu_qp_delta_abs(ra);
if (lc->tu.cu_qp_delta != 0)
if (ff_hevc_cu_qp_delta_sign_flag(ra) == 1)
lc->tu.cu_qp_delta = -lc->tu.cu_qp_delta;
lc->tu.is_cu_qp_delta_coded = 1;
if (lc->tu.cu_qp_delta < -(26 + ra->ps.sps->qp_bd_offset / 2) ||
lc->tu.cu_qp_delta >  (25 + ra->ps.sps->qp_bd_offset / 2)) {
av_log(ra->avctx, AV_LOG_ERROR,
"The cu_qp_delta %d is outside the valid range "
"[%d, %d].\n",
lc->tu.cu_qp_delta,
-(26 + ra->ps.sps->qp_bd_offset / 2),
(25 + ra->ps.sps->qp_bd_offset / 2));
return AVERROR_INVALIDDATA;
}
ff_hevc_set_qPy(ra, ko, oo, vg);
}
if (ra->sh.cu_chroma_qp_offset_enabled_flag && cbf_chroma &&
!lc->cu.cu_transquant_bypass_flag  &&  !lc->tu.is_cu_chroma_qp_offset_coded) {
int cu_chroma_qp_offset_flag = ff_hevc_cu_chroma_qp_offset_flag(ra);
if (cu_chroma_qp_offset_flag) {
int cu_chroma_qp_offset_idx  = 0;
if (ra->ps.pps->chroma_qp_offset_list_len_minus1 > 0) {
cu_chroma_qp_offset_idx = ff_hevc_cu_chroma_qp_offset_idx(ra);
av_log(ra->avctx, AV_LOG_ERROR,
"cu_chroma_qp_offset_idx not yet tested.\n");
}
lc->tu.cu_qp_offset_cb = ra->ps.pps->cb_qp_offset_list[cu_chroma_qp_offset_idx];
lc->tu.cu_qp_offset_cr = ra->ps.pps->cr_qp_offset_list[cu_chroma_qp_offset_idx];
} else {
lc->tu.cu_qp_offset_cb = 0;
lc->tu.cu_qp_offset_cr = 0;
}
lc->tu.is_cu_chroma_qp_offset_coded = 1;
}
if (lc->cu.pred_mode == MODE_INTRA && qp < 4) {
if (lc->tu.intra_pred_mode >= 6 &&
lc->tu.intra_pred_mode <= 14) {
scan_idx = SCAN_VERT;
} else if (lc->tu.intra_pred_mode >= 22 &&
lc->tu.intra_pred_mode <= 30) {
scan_idx = SCAN_HORIZ;
}
if (lc->tu.intra_pred_mode_c >=  6 &&
lc->tu.intra_pred_mode_c <= 14) {
scan_idx_c = SCAN_VERT;
} else if (lc->tu.intra_pred_mode_c >= 22 &&
lc->tu.intra_pred_mode_c <= 30) {
scan_idx_c = SCAN_HORIZ;
}
}
lc->tu.cross_pf = 0;
if (xf)
ff_hevc_hls_residual_coding(ra, jj, gn, qp, scan_idx, 0);
if (ra->ps.sps->chroma_format_idc && (qp > 2 || ra->ps.sps->chroma_format_idc == 3)) {
int trafo_size_h = 1 << (log2_trafo_size_c + ra->ps.sps->hshift[1]);
int trafo_size_v = 1 << (log2_trafo_size_c + ra->ps.sps->vshift[1]);
lc->tu.cross_pf  = (ra->ps.pps->cross_component_prediction_enabled_flag && xf &&
(lc->cu.pred_mode == MODE_INTER ||
(lc->tu.chroma_mode_c ==  4)));
if (lc->tu.cross_pf) {
hls_cross_component_pred(ra, 0);
}
for (i = 0; i < (ra->ps.sps->chroma_format_idc == 2 ? 2 : 1); i++) {
if (lc->cu.pred_mode == MODE_INTRA) {
ff_hevc_set_neighbour_available(ra, jj, gn + (i << log2_trafo_size_c), trafo_size_h, trafo_size_v);
s->hpc.intra_pred[log2_trafo_size_c - 2](ra, jj, gn + (i << log2_trafo_size_c), 1);
}
if (vc[i])
ff_hevc_hls_residual_coding(ra, jj, gn + (i << log2_trafo_size_c),
log2_trafo_size_c, scan_idx_c, 1);
else
if (lc->tu.cross_pf) {
ptrdiff_t stride = ra->frame->linesize[1];
int hshift = ra->ps.sps->hshift[1];
int vshift = ra->ps.sps->vshift[1];
int16_t *coeffs_y = (int16_t*)lc->edge_emu_buffer;
int16_t *coeffs   = (int16_t*)lc->edge_emu_buffer2;
int size = 1 << log2_trafo_size_c;
uint8_t *dst = &ra->frame->data[1][(gn >> vshift) * stride +
((jj >> hshift) << ra->ps.sps->pixel_shift)];
for (i = 0; i < (size * size); i++) {
coeffs[i] = ((lc->tu.res_scale_val * coeffs_y[i]) >> 3);
}
s->hevcdsp.add_residual[log2_trafo_size_c-2](dst, coeffs, stride);
}
}
if (lc->tu.cross_pf) {
hls_cross_component_pred(ra, 1);
}
for (i = 0; i < (ra->ps.sps->chroma_format_idc == 2 ? 2 : 1); i++) {
if (lc->cu.pred_mode == MODE_INTRA) {
ff_hevc_set_neighbour_available(ra, jj, gn + (i << log2_trafo_size_c), trafo_size_h, trafo_size_v);
s->hpc.intra_pred[log2_trafo_size_c - 2](ra, jj, gn + (i << log2_trafo_size_c), 2);
}
if (jq[i])
ff_hevc_hls_residual_coding(ra, jj, gn + (i << log2_trafo_size_c),
log2_trafo_size_c, scan_idx_c, 2);
else
if (lc->tu.cross_pf) {
ptrdiff_t stride = ra->frame->linesize[2];
int hshift = ra->ps.sps->hshift[2];
int vshift = ra->ps.sps->vshift[2];
int16_t *coeffs_y = (int16_t*)lc->edge_emu_buffer;
int16_t *coeffs   = (int16_t*)lc->edge_emu_buffer2;
int size = 1 << log2_trafo_size_c;
uint8_t *dst = &ra->frame->data[2][(gn >> vshift) * stride +
((jj >> hshift) << ra->ps.sps->pixel_shift)];
for (i = 0; i < (size * size); i++) {
coeffs[i] = ((lc->tu.res_scale_val * coeffs_y[i]) >> 3);
}
s->hevcdsp.add_residual[log2_trafo_size_c-2](dst, coeffs, stride);
}
}
} else if (ra->ps.sps->chroma_format_idc && zz == 3) {
int trafo_size_h = 1 << (qp + 1);
int trafo_size_v = 1 << (qp + ra->ps.sps->vshift[1]);
for (i = 0; i < (ra->ps.sps->chroma_format_idc == 2 ? 2 : 1); i++) {
if (lc->cu.pred_mode == MODE_INTRA) {
ff_hevc_set_neighbour_available(ra, zs, tu + (i << qp),
trafo_size_h, trafo_size_v);
s->hpc.intra_pred[qp - 2](ra, zs, tu + (i << qp), 1);
}
if (vc[i])
ff_hevc_hls_residual_coding(ra, zs, tu + (i << qp),
log2_trafo_size, scan_idx_c, 1);
}
for (i = 0; i < (ra->ps.sps->chroma_format_idc == 2 ? 2 : 1); i++) {
if (lc->cu.pred_mode == MODE_INTRA) {
ff_hevc_set_neighbour_available(ra, zs, tu + (i << qp),
trafo_size_h, trafo_size_v);
s->hpc.intra_pred[qp - 2](ra, zs, tu + (i << qp), 2);
}
if (jq[i])
ff_hevc_hls_residual_coding(ra, zs, tu + (i << qp),
log2_trafo_size, scan_idx_c, 2);
}
}
} else if (ra->ps.sps->chroma_format_idc && lc->cu.pred_mode == MODE_INTRA) {
if (qp > 2 || ra->ps.sps->chroma_format_idc == 3) {
int trafo_size_h = 1 << (log2_trafo_size_c + ra->ps.sps->hshift[1]);
int trafo_size_v = 1 << (log2_trafo_size_c + ra->ps.sps->vshift[1]);
ff_hevc_set_neighbour_available(ra, jj, gn, trafo_size_h, trafo_size_v);
s->hpc.intra_pred[log2_trafo_size_c - 2](ra, jj, gn, 1);
s->hpc.intra_pred[log2_trafo_size_c - 2](ra, jj, gn, 2);
if (ra->ps.sps->chroma_format_idc == 2) {
ff_hevc_set_neighbour_available(ra, jj, gn + (1 << log2_trafo_size_c),
trafo_size_h, trafo_size_v);
s->hpc.intra_pred[log2_trafo_size_c - 2](ra, jj, gn + (1 << log2_trafo_size_c), 1);
s->hpc.intra_pred[log2_trafo_size_c - 2](ra, jj, gn + (1 << log2_trafo_size_c), 2);
}
} else if (zz == 3) {
int trafo_size_h = 1 << (qp + 1);
int trafo_size_v = 1 << (qp + ra->ps.sps->vshift[1]);
ff_hevc_set_neighbour_available(ra, zs, tu,
trafo_size_h, trafo_size_v);
s->hpc.intra_pred[qp - 2](ra, zs, tu, 1);
s->hpc.intra_pred[qp - 2](ra, zs, tu, 2);
if (ra->ps.sps->chroma_format_idc == 2) {
ff_hevc_set_neighbour_available(ra, zs, tu + (1 << (qp)),
trafo_size_h, trafo_size_v);
s->hpc.intra_pred[qp - 2](ra, zs, tu + (1 << (qp)), 1);
s->hpc.intra_pred[qp - 2](ra, zs, tu + (1 << (qp)), 2);
}
}
}
return 0;
}

