static int iy(struct net_device *sg,
			     struct ethtool_coalesce *ow)
{
	struct bnxt *bp = netdev_priv(sg);
	bool update_stats = false;
	struct bnxt_coal *hw_coal;
	int rc = 0;
	u16 mult;

	if (ow->use_adaptive_rx_coalesce) {
		bp->flags |= BNXT_FLAG_DIM;
	} else {
		if (bp->flags & BNXT_FLAG_DIM) {
			bp->flags &= ~(BNXT_FLAG_DIM);
			goto reset_coalesce;
		}
	}

	hw_coal = &bp->rx_coal;
	mult = hw_coal->bufs_per_record;
	hw_coal->coal_ticks = ow->rx_coalesce_usecs;
	hw_coal->coal_bufs = ow->rx_max_coalesced_frames * mult;
	hw_coal->coal_ticks_irq = ow->rx_coalesce_usecs_irq;
	hw_coal->coal_bufs_irq = ow->rx_max_coalesced_frames_irq * mult;

	hw_coal = &bp->tx_coal;
	mult = hw_coal->bufs_per_record;
	hw_coal->coal_ticks = ow->tx_coalesce_usecs;
	hw_coal->coal_bufs = ow->tx_max_coalesced_frames * mult;
	hw_coal->coal_ticks_irq = ow->tx_coalesce_usecs_irq;
	hw_coal->coal_bufs_irq = ow->tx_max_coalesced_frames_irq * mult;

	if (bp->stats_coal_ticks != ow->stats_block_coalesce_usecs) {
		u32 stats_ticks = ow->stats_block_coalesce_usecs;


		if (stats_ticks)
			stats_ticks = clamp_t(u32, stats_ticks,
					      BNXT_MIN_STATS_COAL_TICKS,
					      BNXT_MAX_STATS_COAL_TICKS);
		stats_ticks = rounddown(stats_ticks, BNXT_MIN_STATS_COAL_TICKS);
		bp->stats_coal_ticks = stats_ticks;
		if (bp->stats_coal_ticks)
			bp->current_interval =
				bp->stats_coal_ticks * HZ / 1000000;
		else
			bp->current_interval = BNXT_TIMER_INTERVAL;
		update_stats = true;
	}

reset_coalesce:
	if (netif_running(sg)) {
		if (update_stats) {
			rc = bnxt_close_nic(bp, true, false);
			if (!rc)
				rc = bnxt_open_nic(bp, true, false);
		} else {
			rc = bnxt_hwrm_set_coal(bp);
		}
	}

	return rc;
}

