int vl)
{
int err = 0;
struct sockaddr *kaddrs;
SCTP_DEBUG_PRINTK("%s - bl %p rn %p vl %d\n",
__FUNCTION__, bl, rn, vl);
if (unlikely(vl <= 0))
return -EINVAL;
if (unlikely(!access_ok(VERIFY_READ, rn, vl)))
return -EFAULT;
kaddrs = kmalloc(vl, GFP_KERNEL);
if (unlikely(!kaddrs))
return -ENOMEM;
if (__copy_from_user(kaddrs, rn, vl)) {
err = -EFAULT;
} else {
err = __sctp_connect(bl, kaddrs, vl);
}
kfree(kaddrs);
return err;
}

