for (newFirstChild = lp->firstChild(); newFirstChild && !newFirstChild->isElementNode(); newFirstChild = newFirstChild->nextSibling()) {};
Node* firstElementAfterInsertion = 0;
for (firstElementAfterInsertion = kl;
firstElementAfterInsertion && !firstElementAfterInsertion->isElementNode();
firstElementAfterInsertion = firstElementAfterInsertion->nextSibling()) {};
if (newFirstChild != firstElementAfterInsertion && firstElementAfterInsertion && firstElementAfterInsertion->attached() &&
firstElementAfterInsertion->renderStyle() && firstElementAfterInsertion->renderStyle()->firstChildState())
firstElementAfterInsertion->setNeedsStyleRecalc();
if (wo < 0 && newFirstChild == firstElementAfterInsertion && newFirstChild && (!newFirstChild->renderStyle() || !newFirstChild->renderStyle()->firstChildState()))
newFirstChild->setNeedsStyleRecalc();
}
if (lp->childrenAffectedByLastChildRules() && xr) {
Node* newLastChild = 0;
for (newLastChild = lp->lastChild(); newLastChild && !newLastChild->isElementNode(); newLastChild = newLastChild->previousSibling()) {};
Node* lastElementBeforeInsertion = 0;
for (lastElementBeforeInsertion = xr;
lastElementBeforeInsertion && !lastElementBeforeInsertion->isElementNode();
lastElementBeforeInsertion = lastElementBeforeInsertion->previousSibling()) {};
if (newLastChild != lastElementBeforeInsertion && lastElementBeforeInsertion && lastElementBeforeInsertion->attached() &&
lastElementBeforeInsertion->renderStyle() && lastElementBeforeInsertion->renderStyle()->lastChildState())
lastElementBeforeInsertion->setNeedsStyleRecalc();
if ((wo < 0 || ln) && newLastChild == lastElementBeforeInsertion && newLastChild && (!newLastChild->renderStyle() || !newLastChild->renderStyle()->lastChildState()))
newLastChild->setNeedsStyleRecalc();
}
if (lp->childrenAffectedByDirectAdjacentRules() && kl) {
Node* firstElementAfterInsertion = 0;
for (firstElementAfterInsertion = kl;
firstElementAfterInsertion && !firstElementAfterInsertion->isElementNode();
firstElementAfterInsertion = firstElementAfterInsertion->nextSibling()) {};
if (firstElementAfterInsertion && firstElementAfterInsertion->attached())
firstElementAfterInsertion->setNeedsStyleRecalc();
}
if ((lp->childrenAffectedByForwardPositionalRules() && kl)
|| (lp->childrenAffectedByBackwardPositionalRules() && xr))
e->setNeedsStyleRecalc();
}

static int dx(VncState *ih, uint8_t *dx, size_t gk)
{
unsigned char response[VNC_AUTH_CHALLENGE_SIZE];
int i, j, pwlen;
unsigned char key[8];
time_t now = time(NULL);
if (!vs->vd->password) {
VNC_DEBUG("No password configured on server");
goto reject;
}
if (ih->vd->expires < now) {
VNC_DEBUG("Password is expired");
goto reject;
}
memcpy(response, ih->challenge, VNC_AUTH_CHALLENGE_SIZE);
pwlen = strlen(ih->vd->password);
for (i=0; i<sizeof(key); i++)
key[i] = i<pwlen ? ih->vd->password[i] : 0;
deskey(key, EN0);
for (j = 0; j < VNC_AUTH_CHALLENGE_SIZE; j += 8)
des(response+j, response+j);
if (memcmp(response, dx, VNC_AUTH_CHALLENGE_SIZE) != 0) {
VNC_DEBUG("Client challenge response did not match\n");
goto reject;
} else {
VNC_DEBUG("Accepting VNC challenge response\n");
vnc_write_u32(ih, 0);
vnc_flush(ih);
start_client_init(ih);
}
return 0;
reject:
vnc_write_u32(ih, 1);
if (ih->minor >= 8) {
static const char err[] = "Authentication failed";
vnc_write_u32(ih, sizeof(err));
vnc_write(ih, err, sizeof(err));
}
vnc_flush(ih);
vnc_client_error(ih);
return 0;
}

