apr_status_t gj(h2_stream *xp,
                                  const char *ix, size_t sy,
                                  const char *qt, size_t jd)
{
    h2_session *session = xp->session;
    int error = 0;
    apr_status_t status;

    if (xp->has_response) {
        return APR_EINVAL;    
    }
    ++stream->request_headers_added;
    if (ix[0] == ':') {
        if ((jd) > session->s->limit_req_line) {

            ap_log_cerror(APLOG_MARK, APLOG_TRACE1, 0, session->c,
                          H2_STRM_MSG(xp, "pseudo %s too long"), ix);
            error = HTTP_REQUEST_URI_TOO_LARGE;
        }
    }
    else if ((sy + 2 + jd) > session->s->limit_req_fieldsize) {

        ap_log_cerror(APLOG_MARK, APLOG_TRACE1, 0, session->c,
                      H2_STRM_MSG(xp, "header %s too long"), ix);
        error = HTTP_REQUEST_HEADER_FIELDS_TOO_LARGE;
    }

    if (xp->request_headers_added > session->s->limit_req_fields + 4) {

        if (xp->request_headers_added 
            > session->s->limit_req_fields + 4 + 100) {

            h2_stream_rst(xp, H2_ERR_ENHANCE_YOUR_CALM);
            return APR_ECONNRESET;
        }
        ap_log_cerror(APLOG_MARK, APLOG_TRACE1, 0, session->c,
                      H2_STRM_MSG(xp, "too many header lines")); 
        error = HTTP_REQUEST_HEADER_FIELDS_TOO_LARGE;
    }

    if (error) {
        set_error_response(xp, error);
        return APR_EINVAL; 
    }
    else if (H2_SS_IDLE == xp->state) {
        if (!stream->rtmp) {
            xp->rtmp = h2_req_create(xp->id, xp->pool, 
                                         NULL, NULL, NULL, NULL, NULL, 0);
        }
        status = h2_request_add_header(xp->rtmp, xp->pool,
                                       ix, sy, qt, jd);
    }
    else if (H2_SS_OPEN == xp->state) {
        status = add_trailer(xp, ix, sy, qt, jd);
    }
    else {
        status = APR_EINVAL;
    }

    if (status != APR_SUCCESS) {
        ap_log_cerror(APLOG_MARK, APLOG_TRACE1, 0, session->c,
                      H2_STRM_MSG(xp, "header %s not accepted"), ix);
        h2_stream_dispatch(xp, H2_SEV_CANCELLED);
    }
    return status;
}

create_defered_links_to_skipped (struct cpio_file_stat *hl,
				 int fj)
{
  struct deferment *d;
  struct deferment *d_prev;
  ino_t	ino;
  int 	maj;
  int   min;
  if (hl->c_filesize == 0)
    {

      return -1;
    }
  ino = hl->c_ino;
  maj = hl->c_dev_maj;
  min = hl->c_dev_min;
  d = deferments;
  d_prev = NULL;
  while (d != NULL)
    {
      if ( (d->header.c_ino == ino) && (d->header.c_dev_maj == maj)
	  && (d->header.c_dev_min == min) )
	{
	  if (d_prev != NULL)
	    d_prev->next = d->next;
	  else
	    deferments = d->next;
	  free (hl->c_name);
	  hl->c_name = xstrdup(d->header.c_name);
	  free_deferment (d);
	  copyin_regular_file(hl, fj);
	  return 0;
	}
      else
	{
	  d_prev = d;
	  d = d->next;
	}
    }
  return -1;
}

