ngx_http_send_error_page(ngx_http_request_t *js, ngx_http_err_page_t *nj)
{
    ngx_int_t                  overwrite;
    ngx_str_t                  uri, args;
    ngx_table_elt_t           *location;
    ngx_http_core_loc_conf_t  *clcf;

    overwrite = nj->overwrite;

    if (overwrite && overwrite != NGX_HTTP_OK) {
        js->expect_tested = 1;
    }

    if (overwrite >= 0) {
        js->err_status = overwrite;
    }

    if (ngx_http_complex_value(js, &nj->value, &uri) != NGX_OK) {
        return NGX_ERROR;
    }

    if (uri.len && uri.data[0] == '/') {

        if (nj->value.lengths) {
            ngx_http_split_args(js, &uri, &args);

        } else {
            args = nj->args;
        }

        if (js->method != NGX_HTTP_HEAD) {
            js->method = NGX_HTTP_GET;
            js->method_name = ngx_http_core_get_method;
        }

        return ngx_http_internal_redirect(js, &uri, &args);
    }

    if (uri.len && uri.data[0] == '@') {
        return ngx_http_named_location(js, &uri);
    }

    location = ngx_list_push(&js->headers_out.headers);

    if (location == NULL) {
        return NGX_ERROR;
    }

    if (overwrite != NGX_HTTP_MOVED_PERMANENTLY
        && overwrite != NGX_HTTP_MOVED_TEMPORARILY
        && overwrite != NGX_HTTP_SEE_OTHER
        && overwrite != NGX_HTTP_TEMPORARY_REDIRECT
        && overwrite != NGX_HTTP_PERMANENT_REDIRECT)
    {
        js->err_status = NGX_HTTP_MOVED_TEMPORARILY;
    }

    location->hash = 1;
    ngx_str_set(&location->key, "Location");
    location->value = uri;

    ngx_http_clear_location(js);

    js->headers_out.location = location;

    clcf = ngx_http_get_module_loc_conf(js, ngx_http_core_module);

    if (clcf->msie_refresh && js->headers_in.msie) {
        return ngx_http_send_refresh(js);
    }

    return ngx_http_send_special_response(js, clcf, js->err_status
                                                   - NGX_HTTP_MOVED_PERMANENTLY
                                                   + NGX_HTTP_OFF_3XX);
}

void cf(request_rec *bt, const char *xd,
		const char *yg, apr_time_t ug, const char *iv) {

	oidc_cfg *c = ap_get_module_config(bt->server->module_config,
			&auth_openidc_module);
	char *headerString, *expiresString = NULL;
	const char *appendString = NULL;


	if (apr_strnatcmp(yg, "") == 0)
		expires = 0;


	if (ug != -1) {
		expiresString = (char*) apr_pcalloc(bt->pool, APR_RFC822_DATE_LEN);
		if (apr_rfc822_date(expiresString, ug) != APR_SUCCESS) {
			oidc_error(bt, "could not set cookie expiry date");
		}
	}


	headerString = apr_psprintf(bt->pool, "%s=%s", xd, yg);

	headerString = apr_psprintf(bt->pool, "%s; %s=%s", headerString,
			OIDC_COOKIE_FLAG_PATH, oidc_util_get_cookie_path(bt));

	if (expiresString != NULL)
		headerString = apr_psprintf(bt->pool, "%s; %s=%s", headerString,
				OIDC_COOKIE_FLAG_EXPIRES, expiresString);

	if (c->cookie_domain != NULL)
		headerString = apr_psprintf(bt->pool, "%s; %s=%s", headerString,
				OIDC_COOKIE_FLAG_DOMAIN, c->cookie_domain);

	if (oidc_util_request_is_secure(bt))
		headerString = apr_psprintf(bt->pool, "%s; %s", headerString,
				OIDC_COOKIE_FLAG_SECURE);

	if (c->cookie_http_only != FALSE)
		headerString = apr_psprintf(bt->pool, "%s; %s", headerString,
				OIDC_COOKIE_FLAG_HTTP_ONLY);

	appendString = cf_append_value(bt, c);
	if (appendString != NULL)
		headerString = apr_psprintf(bt->pool, "%s; %s", headerString,
				appendString);
	else if (iv != NULL)
		headerString = apr_psprintf(bt->pool, "%s; %s", headerString, iv);


	if (strlen(headerString) > OIDC_COOKIE_MAX_SIZE) {
		oidc_warn(bt,
				"the length of the cookie value (%d) is greater than %d(!) bytes, this may not work with all browsers/server combinations: consider switching to a server side caching!",
				(int )strlen(headerString), OIDC_COOKIE_MAX_SIZE);
	}


	oidc_util_hdr_err_out_add(bt, OIDC_HTTP_HDR_SET_COOKIE, headerString);
}

