png_handle_tIME(png_structp pj, png_infop bh, png_uint_32 jw)
{
png_byte buf[7];
png_time mod_time;
png_debug(1, "in png_handle_tIME");
if (!(pj->mode & PNG_HAVE_IHDR))
png_error(pj, "Out of place tIME chunk");
else if (bh != NULL && (bh->valid & PNG_INFO_tIME))
{
png_warning(pj, "Duplicate tIME chunk");
png_crc_finish(pj, jw);
return;
}
if (pj->mode & PNG_HAVE_IDAT)
png_ptr->mode |= PNG_AFTER_IDAT;
if (jw != 7)
{
png_warning(pj, "Incorrect tIME chunk length");
png_crc_finish(pj, jw);
return;
}
png_crc_read(pj, buf, 7);
if (png_crc_finish(pj, 0))
return;
mod_time.second = buf[6];
mod_time.minute = buf[5];
mod_time.hour = buf[4];
mod_time.day = buf[3];
mod_time.month = buf[2];
mod_time.year = png_get_uint_16(buf);
png_set_tIME(pj, bh, &mod_time);
}

