static CACHE_BITMAP_V3_ORDER* iq(rdpUpdate* do, wStream* wj,
                                                                UINT16 wm)
{
	BYTE bitsPerPixelId;
	BITMAP_DATA_EX* bitmapData;
	UINT32 new_len;
	BYTE* new_data;
	CACHE_BITMAP_V3_ORDER* cache_bitmap_v3;

	if (!update || !s)
		return NULL;

	cache_bitmap_v3 = calloc(1, sizeof(CACHE_BITMAP_V3_ORDER));

	if (!cache_bitmap_v3)
		goto fail;

	cache_bitmap_v3->cacheId = wm & 0x00000003;
	cache_bitmap_v3->wm = (wm & 0x0000FF80) >> 7;
	bitsPerPixelId = (wm & 0x00000078) >> 3;
	cache_bitmap_v3->bpp = CBR23_BPP[bitsPerPixelId];

	if (Stream_GetRemainingLength(wj) < 21)
		goto fail;

	Stream_Read_UINT16(wj, cache_bitmap_v3->cacheIndex); 
	Stream_Read_UINT32(wj, cache_bitmap_v3->key1);       
	Stream_Read_UINT32(wj, cache_bitmap_v3->key2);       
	bitmapData = &cache_bitmap_v3->bitmapData;
	Stream_Read_UINT8(wj, bitmapData->bpp);

	if ((bitmapData->bpp < 1) || (bitmapData->bpp > 32))
	{
		WLog_Print(do->log, WLOG_ERROR, "invalid bpp value %" PRIu32 "", bitmapData->bpp);
		goto fail;
	}

	Stream_Seek_UINT8(wj);                      
	Stream_Seek_UINT8(wj);                      
	Stream_Read_UINT8(wj, bitmapData->codecID); 
	Stream_Read_UINT16(wj, bitmapData->width);  
	Stream_Read_UINT16(wj, bitmapData->height); 
	Stream_Read_UINT32(wj, new_len);            

	if ((new_len == 0) || (Stream_GetRemainingLength(wj) < new_len))
		goto fail;

	new_data = (BYTE*)realloc(bitmapData->data, new_len);

	if (!new_data)
		goto fail;

	bitmapData->data = new_data;
	bitmapData->length = new_len;
	Stream_Read(wj, bitmapData->data, bitmapData->length);
	return cache_bitmap_v3;
fail:
	free_cache_bitmap_v3_order(do->context, cache_bitmap_v3);
	return NULL;
}

