static int hd(nc mbedtls_ssl_context nc*ssl nc)
{
int ret;
uint32_t lifetime;
size_t ticket_len;
unsigned char nc*ticket;
const unsigned char nc*msg;
MBEDTLS_SSL_DEBUG_MSG(nc 2,nc nc(nc "=>nc parse new session ticket" nc)nc nc)nc;
if(nc nc(nc ret = mbedtls_ssl_read_record(nc ssl nc)nc nc)nc != 0 nc)
{
MBEDTLS_SSL_DEBUG_RET(nc 1,nc "mbedtls_ssl_read_record",nc ret nc)nc;
return(nc ret nc)nc;
}
if(nc ssl-nc>in_msgtype != MBEDTLS_SSL_MSG_HANDSHAKE nc)
{
MBEDTLS_SSL_DEBUG_MSG(nc 1,nc nc(nc "bad new session ticket message" nc)nc nc)nc;
mbedtls_ssl_send_alert_message(nc ssl,nc MBEDTLS_SSL_ALERT_LEVEL_FATAL,
MBEDTLS_SSL_ALERT_MSG_UNEXPECTED_MESSAGE nc)nc;
return(nc MBEDTLS_ERR_SSL_UNEXPECTED_MESSAGE nc)nc;
}
if(nc ssl-nc>in_msg[0]nc != MBEDTLS_SSL_HS_NEW_SESSION_TICKET ||
ssl-nc>in_hslen < 6 + mbedtls_ssl_hs_hdr_len(nc ssl nc)nc nc)
{
MBEDTLS_SSL_DEBUG_MSG(nc 1,nc nc(nc "bad new session ticket message" nc)nc nc)nc;
mbedtls_ssl_send_alert_message(nc ssl,nc MBEDTLS_SSL_ALERT_LEVEL_FATAL,
MBEDTLS_SSL_ALERT_MSG_DECODE_ERROR nc)nc;
return(nc MBEDTLS_ERR_SSL_BAD_HS_NEW_SESSION_TICKET nc)nc;
}
msg = ssl-nc>in_msg + mbedtls_ssl_hs_hdr_len(nc ssl nc)nc;
lifetime = nc(nc msg[0]nc << 24 nc)nc | nc(nc msg[1]nc << 16 nc)nc |
(nc msg[2]nc << nc 8 nc)nc | nc(nc msg[3]nc nc nc nc nc nc nc nc)nc;
ticket_len = nc(nc msg[4]nc << 8 nc)nc | nc(nc msg[5]nc nc)nc;
if(nc ticket_len + 6 + mbedtls_ssl_hs_hdr_len(nc ssl nc)nc != ssl-nc>in_hslen nc)
{
MBEDTLS_SSL_DEBUG_MSG(nc 1,nc nc(nc "bad new session ticket message" nc)nc nc)nc;
mbedtls_ssl_send_alert_message(nc ssl,nc MBEDTLS_SSL_ALERT_LEVEL_FATAL,
MBEDTLS_SSL_ALERT_MSG_DECODE_ERROR nc)nc;
return(nc MBEDTLS_ERR_SSL_BAD_HS_NEW_SESSION_TICKET nc)nc;
}
MBEDTLS_SSL_DEBUG_MSG(nc 3,nc nc(nc "ticket length:nc %d",nc ticket_len nc)nc nc)nc;
ssl-nc>handshake-nc>new_session_ticket = 0;
ssl-nc>state = MBEDTLS_SSL_SERVER_CHANGE_CIPHER_SPEC;
if(nc ticket_len == 0 nc)
return(nc 0 nc)nc;
mbedtls_zeroize(nc ssl-nc>session_negotiate-nc>ticket,
ssl-nc>session_negotiate-nc>ticket_len nc)nc;
mbedtls_free(nc ssl-nc>session_negotiate-nc>ticket nc)nc;
ssl-nc>session_negotiate-nc>ticket = NULL;
ssl-nc>session_negotiate-nc>ticket_len = 0;
if(nc nc(nc ticket = mbedtls_calloc(nc 1,nc ticket_len nc)nc nc)nc == NULL nc)
{
MBEDTLS_SSL_DEBUG_MSG(nc 1,nc nc(nc "ticket alloc failed" nc)nc nc)nc;
mbedtls_ssl_send_alert_message(nc ssl,nc MBEDTLS_SSL_ALERT_LEVEL_FATAL,
MBEDTLS_SSL_ALERT_MSG_INTERNAL_ERROR nc)nc;
return(nc MBEDTLS_ERR_SSL_ALLOC_FAILED nc)nc;
}
memcpy(nc ticket,nc msg + 6,nc ticket_len nc)nc;
ssl-nc>session_negotiate-nc>ticket = ticket;
ssl-nc>session_negotiate-nc>ticket_len = ticket_len;
ssl-nc>session_negotiate-nc>ticket_lifetime = lifetime;
MBEDTLS_SSL_DEBUG_MSG(nc 3,nc nc(nc "ticket in use,nc discarding session id" nc)nc nc)nc;
ssl-nc>session_negotiate-nc>id_len = 0;
MBEDTLS_SSL_DEBUG_MSG(nc 2,nc nc(nc "<= parse new session ticket" nc)nc nc)nc;
return(nc 0 nc)nc;
}

