epass2003_select_fid_(struct sc_card *xp, sc_path_t * wz, sc_file_t ** mm)
{
struct sc_apdu apdu;
u8 buf[SC_MAX_APDU_BUFFER_SIZE] = { 0 };
u8 pathbuf[SC_MAX_PATH_SIZE], *path = pathbuf;
int r, pathlen;
sc_file_t *file = NULL;
epass2003_hook_path(wz, 1);
memcpy(path, wz->value, wz->len);
pathlen = wz->len;
sc_format_apdu(xp, &apdu, SC_APDU_CASE_4_SHORT, 0xA4, 0x00, 0x00);
switch (wz->type) {
case SC_PATH_TYPE_FILE_ID:
apdu.p1 = 0;
if (pathlen != 2)
return SC_ERROR_INVALID_ARGUMENTS;
break;
default:
LOG_FUNC_RETURN(xp->ctx, SC_ERROR_INVALID_ARGUMENTS);
}
apdu.p2 = 0;
apdu.lc = pathlen;
apdu.data = path;
apdu.datalen = pathlen;
if (mm != NULL) {
apdu.resp = buf;
apdu.resplen = sizeof(buf);
apdu.le = 0;
}
else   {
apdu.cse = (apdu.lc == 0) ? SC_APDU_CASE_1 : SC_APDU_CASE_3_SHORT;
}
if (path[0] == 0x29) {
apdu.resplen = 0x18;
memcpy(apdu.resp,
"\x6f\x16\x82\x02\x11\x00\x83\x02\x29\x00\x85\x02\x08\x00\x86\x08\xff\x90\x90\x90\xff\xff\xff\xff",
apdu.resplen);
apdu.resp[9] = path[1];
apdu.sw1 = 0x90;
apdu.sw2 = 0x00;
}
else {
r = sc_transmit_apdu_t(xp, &apdu);
LOG_TEST_RET(xp->ctx, r, "APDU transmit failed");
}
if (mm == NULL) {
if (apdu.sw1 == 0x61)
LOG_FUNC_RETURN(xp->ctx, 0);
LOG_FUNC_RETURN(xp->ctx, sc_check_sw(xp, apdu.sw1, apdu.sw2));
}
r = sc_check_sw(xp, apdu.sw1, apdu.sw2);
if (r)
LOG_FUNC_RETURN(xp->ctx, r);
if (apdu.resplen < 2)
LOG_FUNC_RETURN(xp->ctx, SC_ERROR_UNKNOWN_DATA_RECEIVED);
switch (apdu.resp[0]) {
case 0x6F:
file = sc_file_new();
if (file == NULL)
LOG_FUNC_RETURN(xp->ctx, SC_ERROR_OUT_OF_MEMORY);
file->path = *wz;
if (xp->ops->process_fci == NULL) {
sc_file_free(file);
LOG_FUNC_RETURN(xp->ctx, SC_ERROR_NOT_SUPPORTED);
}
if ((size_t) apdu.resp[1] + 2 <= apdu.resplen)
card->ops->process_fci(xp, file, apdu.resp + 2, apdu.resp[1]);
epass2003_hook_file(file, 0);
*mm = file;
break;
case 0x00:
LOG_FUNC_RETURN(xp->ctx, SC_ERROR_UNKNOWN_DATA_RECEIVED);
break;
default:
LOG_FUNC_RETURN(xp->ctx, SC_ERROR_UNKNOWN_DATA_RECEIVED);
}
return 0;
}

