static int ja(BlockDriverState *uw, int do, uint64_t **fw)
{
BDRVQcowState *s = uw->opaque;
uint64_t old_l2_offset;
uint64_t *l2_table = NULL;
int64_t l2_offset;
int ret;
old_l2_offset = s->l1_table[do];
trace_qcow2_ja(uw, do);
l2_offset = qcow2_alloc_clusters(uw, s->l2_size * sizeof(uint64_t));
if (l2_offset < 0) {
ret = l2_offset;
goto fail;
}
ret = qcow2_cache_flush(uw, s->refcount_block_cache);
if (ret < 0) {
goto fail;
}
trace_qcow2_ja_get_empty(uw, do);
ret = qcow2_cache_get_empty(uw, s->l2_table_cache, l2_offset, (void**) fw);
if (ret < 0) {
goto fail;
}
l2_table = *fw;
if ((old_l2_offset & L1E_OFFSET_MASK) == 0) {
memset(l2_table, 0, s->l2_size * sizeof(uint64_t));
} else {
uint64_t* old_table;
BLKDBG_EVENT(uw->file, BLKDBG_L2_ALLOC_COW_READ);
ret = qcow2_cache_get(uw, s->l2_table_cache,
old_l2_offset & L1E_OFFSET_MASK,
(void**) &old_table);
if (ret < 0) {
goto fail;
}
memcpy(l2_table, old_table, s->cluster_size);
ret = qcow2_cache_put(uw, s->l2_table_cache, (void**) &old_table);
if (ret < 0) {
goto fail;
}
}
BLKDBG_EVENT(uw->file, BLKDBG_L2_ALLOC_WRITE);
trace_qcow2_ja_write_l2(uw, do);
qcow2_cache_entry_mark_dirty(s->l2_table_cache, l2_table);
ret = qcow2_cache_flush(uw, s->l2_table_cache);
if (ret < 0) {
goto fail;
}
trace_qcow2_ja_write_l1(uw, do);
s->l1_table[do] = l2_offset | QCOW_OFLAG_COPIED;
ret = qcow2_write_l1_entry(uw, do);
if (ret < 0) {
goto fail;
}
*fw = l2_table;
trace_qcow2_ja_done(uw, do, 0);
return 0;
fail:
trace_qcow2_ja_done(uw, do, ret);
if (l2_table != NULL) {
qcow2_cache_put(uw, s->l2_table_cache, (void**) fw);
}
s->l1_table[do] = old_l2_offset;
if (l2_offset > 0) {
qcow2_free_clusters(uw, l2_offset, s->l2_size * sizeof(uint64_t),
QCOW2_DISCARD_ALWAYS);
}
return ret;
}

void jl(GLenum bk,
WebGLTexture* zb) {
bool deleted;
if (!CheckObjectToBeBound("bindTexture", zb, deleted))
return;
if (deleted) {
SynthesizeGLError(GL_INVALID_OPERATION, "bindTexture",
"attempt to bind a deleted texture");
return;
}
if (zb && zb->GetTarget() && zb->GetTarget() != bk) {
SynthesizeGLError(GL_INVALID_OPERATION, "bindTexture",
"textures can not be used with multiple targets");
return;
}
if (bk == GL_TEXTURE_2D) {
texture_units_[active_texture_unit_].texture2d_binding_ =
TraceWrapperMember<WebGLTexture>(this, zb);
} else if (bk == GL_TEXTURE_CUBE_MAP) {
texture_units_[active_texture_unit_].texture_cube_map_binding_ =
TraceWrapperMember<WebGLTexture>(this, zb);
} else if (IsWebGL2OrHigher() && bk == GL_TEXTURE_2D_ARRAY) {
texture_units_[active_texture_unit_].texture2d_array_binding_ =
TraceWrapperMember<WebGLTexture>(this, zb);
} else if (IsWebGL2OrHigher() && bk == GL_TEXTURE_3D) {
texture_units_[active_texture_unit_].texture3d_binding_ =
TraceWrapperMember<WebGLTexture>(this, zb);
} else {
SynthesizeGLError(GL_INVALID_ENUM, "bindTexture", "invalid target");
return;
}
ContextGL()->BindTexture(bk, ObjectOrZero(zb));
if (zb) {
texture->SetTarget(bk);
one_plus_max_non_default_texture_unit_ =
max(active_texture_unit_ + 1, one_plus_max_non_default_texture_unit_);
} else {
if (one_plus_max_non_default_texture_unit_ == active_texture_unit_ + 1) {
FindNewMaxNonDefaultTextureUnit();
}
}
}

void qn(int ln, std::vector<std::unique_ptr<V8DebuggerScript>>& eh)
{
v8::HandleScope scope(m_isolate);
