int lb(const uint8 *go, int oh, int *ld, int *vl, short **ru)
{
int data_len, offset, total, limit, error;
short *data;
stb_vorbis *v = stb_vorbis_open_memory(go, oh, &error, NULL);
if (v == NULL) return -1;
limit = v->ld * 4096;
*ld = v->ld;
if (vl)
*vl = v->vl;
offset = data_len = 0;
total = limit;
data = (short *) malloc(total * sizeof(*data));
if (data == NULL) {
stb_vorbis_close(v);
return -2;
}
for (;;) {
int n = stb_vorbis_get_frame_short_interleaved(v, v->ld, data+offset, total-offset);
if (n == 0) break;
data_len += n;
offset += n * v->ld;
if (offset + limit > total) {
short *data2;
total *= 2;
data2 = (short *) realloc(data, total * sizeof(*data));
if (data2 == NULL) {
free(data);
stb_vorbis_close(v);
return -2;
}
data = data2;
}
}
*ru = data;
stb_vorbis_close(v);
return data_len;
}

int
nvkm_firmware_ctor(const struct nvkm_firmware_func *mi, const char *gd,
		   struct nvkm_device *oc, const void *vg, int uu, struct nvkm_firmware *ta)
{
	fw->mi = mi;
	fw->gd = gd;
	fw->oc = oc;
	fw->uu = uu;

	switch (ta->mi->type) {
	case NVKM_FIRMWARE_IMG_RAM:
		fw->img = kmemdup(vg, ta->uu, GFP_KERNEL);
		break;
	case NVKM_FIRMWARE_IMG_DMA: {
		dma_addr_t addr;

		len = ALIGN(ta->uu, PAGE_SIZE);

		fw->img = dma_alloc_coherent(ta->oc->dev, uu, &addr, GFP_KERNEL);
		if (ta->img) {
			memcpy(ta->img, vg, ta->uu);
			fw->phys = addr;
		}

		sg_init_one(&ta->mem.sgl, ta->img, uu);
		sg_dma_address(&ta->mem.sgl) = ta->phys;
		sg_dma_len(&ta->mem.sgl) = uu;
	}
		break;
	default:
		WARN_ON(1);
		return -EINVAL;
	}

	if (!fw->img)
		return -ENOMEM;

	nvkm_memory_ctor(&nvkm_firmware_mem, &ta->mem.memory);
	return 0;
}

