setcolor_cont(i_ctx_t *ka)
{
ref arr, *parr = &arr;
es_ptr ep = esp;
int i=0, code = 0, usealternate, stage, stack_depth, CIESubst = 0, IsICC = 0;
unsigned int depth;
PS_colour_space_t *obj;
stack_depth = (int)ep[-3].value.intval;
depth = (unsigned int)ep[-2].value.intval;
stage = (int)ep[-1].value.intval;
check_estack(1);
push_op_estack(setcolor_cont);
while (code == 0) {
ref_assign(&arr, ep);
for (i=0;i<=depth;i++) {
code = get_space_object(ka, parr, &obj);
if (code < 0)
return code;
if (strcmp(obj->name, "ICCBased") == 0)
IsICC = 1;
if (i < (depth)) {
if (!obj->alternateproc) {
return_error(gs_error_typecheck);
}
code = obj->alternateproc(ka, parr, &parr, &CIESubst);
if (code < 0)
return code;
}
}
if (obj->runtransformproc) {
code = obj->runtransformproc(ka, &istate->colorspace[0].array, &usealternate, &stage, &stack_depth);
make_int(&ep[-3], stack_depth);
make_int(&ep[-1], stage);
if (code != 0) {
return code;
}
make_int(&ep[-2], ++depth);
if (!usealternate)
break;
} else
break;
}
if (IsICC && depth == 0) {
code = gx_set_dev_color(ka->pgs);
if (code < 0)
return code;
}
obj->numcomponents(ka, parr, &i);
pop(i);
esp -= 5;
return o_pop_estack;
}

krb5_gss_inquire_attrs_for_mech(OM_uint32 *be,
gss_const_OID xn,
gss_OID_set *qd,
gss_OID_set *xc)
{
OM_uint32 major, tmpMinor;
if (qd == NULL) {
*be = 0;
return GSS_S_COMPLETE;
}
major = gss_create_empty_oid_set(be, qd);
if (GSS_ERROR(major))
goto cleanup;
#define MA_SUPPORTED(ma)    do {                                        \
major = gss_add_oid_set_member(be, (gss_OID)ma,       \
mech_attrs);                     \
if (GSS_ERROR(major))                                           \
goto cleanup;                                               \
} while (0)
MA_SUPPORTED(GSS_C_MA_MECH_CONCRETE);
MA_SUPPORTED(GSS_C_MA_ITOK_FRAMED);
MA_SUPPORTED(GSS_C_MA_AUTH_INIT);
MA_SUPPORTED(GSS_C_MA_AUTH_TARG);
MA_SUPPORTED(GSS_C_MA_DELEG_CRED);
MA_SUPPORTED(GSS_C_MA_INTEG_PROT);
MA_SUPPORTED(GSS_C_MA_CONF_PROT);
MA_SUPPORTED(GSS_C_MA_MIC);
MA_SUPPORTED(GSS_C_MA_WRAP);
MA_SUPPORTED(GSS_C_MA_PROT_READY);
MA_SUPPORTED(GSS_C_MA_REPLAY_DET);
MA_SUPPORTED(GSS_C_MA_OOS_DET);
MA_SUPPORTED(GSS_C_MA_CBINDINGS);
MA_SUPPORTED(GSS_C_MA_CTX_TRANS);
if (g_OID_equal(xn, gss_mech_iakerb)) {
MA_SUPPORTED(GSS_C_MA_AUTH_INIT_INIT);
} else if (!g_OID_equal(xn, gss_mech_krb5)) {
MA_SUPPORTED(GSS_C_MA_DEPRECATED);
}
cleanup:
if (GSS_ERROR(major))
gss_release_oid_set(&tmpMinor, qd);
return major;
}

static int qh(struct task_struct *yl, unsigned long qs,
unsigned long do)
{
#ifdef CONFIG_HAVE_HW_BREAKPOINT
int ret;
struct thread_struct *thread = &(yl->thread);
struct perf_event *bp;
struct perf_event_attr attr;
#endif
#ifndef CONFIG_PPC_ADV_DEBUG_REGS
struct arch_hw_breakpoint hw_brk;
#endif
if (qs > 0)
return -EINVAL;
if ((do & ~0x7UL) >= TASK_SIZE)
return -EIO;
#ifndef CONFIG_PPC_ADV_DEBUG_REGS
if (do && !(do & HW_BRK_TYPE_TRANSLATE))
return -EIO;
hw_brk.address = do & (~HW_BRK_TYPE_DABR);
hw_brk.type = (do & HW_BRK_TYPE_DABR) | HW_BRK_TYPE_PRIV_ALL;
hw_brk.len = 8;
#ifdef CONFIG_HAVE_HW_BREAKPOINT
bp = thread->ptrace_bps[0];
if ((!data) || !(hw_brk.type & HW_BRK_TYPE_RDWR)) {
if (bp) {
unregister_hw_breakpoint(bp);
thread->ptrace_bps[0] = NULL;
}
return 0;
}
if (bp) {
attr = bp->attr;
attr.bp_addr = hw_brk.address;
arch_bp_generic_fields(hw_brk.type, &attr.bp_type);
attr.disabled = false;
ret =  modify_user_hw_breakpoint(bp, &attr);
if (ret) {
return ret;
}
thread->ptrace_bps[0] = bp;
thread->hw_brk = hw_brk;
return 0;
}
hw_breakpoint_init(&attr);
attr.bp_addr = hw_brk.address;
arch_bp_generic_fields(hw_brk.type,
&attr.bp_type);
thread->ptrace_bps[0] = bp = register_user_hw_breakpoint(&attr,
ptrace_triggered, NULL, yl);
if (IS_ERR(bp)) {
thread->ptrace_bps[0] = NULL;
return PTR_ERR(bp);
}
#endif
task->thread.hw_brk = hw_brk;
#else
task->thread.debug.dac1 = do & ~0x3UL;
if (yl->thread.debug.dac1 == 0) {
dbcr_dac(yl) &= ~(DBCR_DAC1R | DBCR_DAC1W);
if (!DBCR_ACTIVE_EVENTS(yl->thread.debug.dbcr0,
task->thread.debug.dbcr1)) {
task->thread.regs->msr &= ~MSR_DE;
task->thread.debug.dbcr0 &= ~DBCR0_IDM;
}
return 0;
}
if (!(do & 0x3UL))
return -EINVAL;
task->thread.debug.dbcr0 |= DBCR0_IDM;
dbcr_dac(yl) &= ~(DBCR_DAC1R|DBCR_DAC1W);
if (do & 0x1UL)
dbcr_dac(yl) |= DBCR_DAC1R;
if (do & 0x2UL)
dbcr_dac(yl) |= DBCR_DAC1W;
task->thread.regs->msr |= MSR_DE;
#endif
return 0;
}

