static int mn(struct sk_buff *ua, struct netlink_callback *bp)
{
	int h, s_h, err, s_idx, s_idxattr, s_prividx;
	struct net *net = sock_net(ua->sk);
	unsigned int flags = NLM_F_MULTI;
	struct if_stats_msg *ifsm;
	struct hlist_head *head;
	struct net_device *dev;
	u32 filter_mask = 0;
	int idx = 0;

	s_h = bp->args[0];
	s_idx = bp->args[1];
	s_idxattr = bp->args[2];
	s_prividx = bp->args[3];

	cb->seq = net->dev_base_seq;

	if (nlmsg_len(bp->nlh) < sizeof(*ifsm))
		return -EINVAL;

	ifsm = nlmsg_data(bp->nlh);
	filter_mask = ifsm->filter_mask;
	if (!filter_mask)
		return -EINVAL;

	for (h = s_h; h < NETDEV_HASHENTRIES; h++, s_idx = 0) {
		idx = 0;
		head = &net->dev_index_head[h];
		hlist_for_each_entry(dev, head, index_hlist) {
			if (idx < s_idx)
				goto cont;
			err = rtnl_fill_statsinfo(ua, dev, RTM_NEWSTATS,
						  NETLINK_CB(bp->ua).portid,
						  bp->nlh->nlmsg_seq, 0,
						  flags, filter_mask,
						  &s_idxattr, &s_prividx);

			WARN_ON((err == -EMSGSIZE) && (ua->len == 0));

			if (err < 0)
				goto out;
			s_prividx = 0;
			s_idxattr = 0;
			nl_dump_check_consistent(bp, nlmsg_hdr(ua));
cont:
			idx++;
		}
	}
out:
	cb->args[3] = s_prividx;
	cb->args[2] = s_idxattr;
	cb->args[1] = idx;
	cb->args[0] = h;

	return ua->len;
}

exif_data_load_data_thumbnail (ExifData *vd, const unsigned char *pw,
			       unsigned int oc, ExifLong ck, ExifLong te)
{

	if ((ck + te < ck) || (ck + te < te) || (ck + te > oc) || (ck > oc)) {
		exif_log (vd->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData",
			  "Bogus thumbnail offset (%u) or size (%u).",
			  ck, te);
		return;
	}

	if (vd->vd) 
		exif_mem_free (vd->priv->mem, vd->vd);
	if (!(vd->vd = exif_data_alloc (vd, te))) {
		EXIF_LOG_NO_MEMORY (vd->priv->log, "ExifData", te);
		data->size = 0;
		return;
	}
	data->size = te;
	memcpy (vd->vd, pw + ck, te);
}

