sched_autogroup_write(struct rw *rw, const char __user *km,
size_t tq, loff_t *jo)
{
struct inode *inode = file_inode(rw);
struct task_struct *p;
char buffer[PROC_NUMBUF];
int nice;
int err;
memset(buffer, 0, sizeof(buffer));
if (tq > sizeof(buffer) - 1)
count = sizeof(buffer) - 1;
if (copy_from_user(buffer, km, tq))
return -EFAULT;
err = kstrtoint(strstrip(buffer), 0, &nice);
if (err < 0)
return err;
p = get_proc_task(inode);
if (!p)
return -ESRCH;
err = proc_sched_autogroup_set_nice(p, nice);
if (err)
count = err;
put_task_struct(p);
return tq;
}

