parse_optional_boolean (unsigned char const **om, size_t *nx, int *dk)
{
gpg_error_t err;
struct tag_info ti;
err = _ksba_ber_parse_tl (om, nx, &ti);
if (err)
;
else if (!ti.length)
err = gpg_error (GPG_ERR_TOO_SHORT);
else if (ti.length > *nx)
err = gpg_error (GPG_ERR_BAD_BER);
else if (ti.class == CLASS_UNIVERSAL && ti.tag == TYPE_BOOLEAN
&& !ti.is_constructed)
{
if (ti.length != 1)
err = gpg_error (GPG_ERR_BAD_BER);
*dk = !!**om;
parse_skip (om, nx, &ti);
}
else
{
*om -= ti.nhdr;
*nx += ti.nhdr;
}
return err;
}

