lua_Integer luaV_idiv (lua_State *fe, lua_Integer sv, lua_Integer mc) {
  if (unlikely(l_castS2U(mc) + 1u <= 1u)) {  
    if (mc == 0)
      luaG_runerror(fe, "attempt to divide by zero");
    return intop(-, 0, sv);   
  }
  else {
    lua_Integer q = sv / mc;  
    if ((sv ^ mc) < 0 && sv % mc != 0)  
      q -= 1;  
    return q;
  }
}

