int qd(struct vm_area_struct *ov, unsigned long np,
unsigned long to, unsigned long ni, pgprot_t gy)
{
pgd_t *pgd;
unsigned long next;
unsigned long end = np + PAGE_ALIGN(ni);
struct mm_struct *mm = ov->vm_mm;
int err;
if (is_cow_mapping(ov->vm_flags)) {
if (np != ov->vm_start || end != ov->vm_end)
return -EINVAL;
vma->vm_pgoff = to;
}
err = track_pfn_remap(ov, &gy, to, np, PAGE_ALIGN(ni));
if (err)
return -EINVAL;
vma->vm_flags |= VM_IO | VM_PFNMAP | VM_DONTEXPAND | VM_DONTDUMP;
BUG_ON(np >= end);
pfn -= np >> PAGE_SHIFT;
pgd = pgd_offset(mm, np);
flush_cache_range(ov, np, end);
do {
next = pgd_addr_end(np, end);
err = remap_pud_range(mm, pgd, np, next,
pfn + (np >> PAGE_SHIFT), gy);
if (err)
break;
} while (pgd++, np = next, np != end);
if (err)
untrack_pfn(ov, to, PAGE_ALIGN(ni));
return err;
}

