MagickPrivate void em(Display *ye,
  const XResourceInfo *yi,XWindows *jk,
  const MagickBooleanType da,const char *px,const char **nf)
{
#define DismissButtonText  "Dismiss"

  char
    primary_selection[MagickPathExtent];

  int
    i;

  static MagickStatusType
    mask = (MagickStatusType) (CWWidth | CWHeight | CWX | CWY);

  Status
    status;

  unsigned int
    height,
    lines,
    text_width,
    visible_lines,
    width;

  size_t
    delay,
    state;

  XEvent
    event;

  XFontStruct
    *font_info,
    *text_info;

  XTextProperty
    window_name;

  XWidgetInfo
    dismiss_info,
    expose_info,
    list_info,
    north_info,
    scroll_info,
    selection_info,
    slider_info,
    south_info;

  XWindowChanges
    window_changes;


  assert(ye != (Display *) NULL);
  assert(yi != (XResourceInfo *) NULL);
  assert(jk != (XWindows *) NULL);
  assert(px != (const char *) NULL);
  assert(nf != (const char **) NULL);
  (void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",px);
  XSetCursorState(ye,jk,MagickTrue);
  XCheckRefreshWindows(ye,jk);
  if (nf == (const char **) NULL)
    {
      XNoticeWidget(ye,jk,"No text to view:",(char *) NULL);
      return;
    }

  font_info=windows->widget.font_info;
  text_info=(XFontStruct *) NULL;
  if (da != MagickFalse)
    text_info=XBestFont(ye,yi,MagickTrue);
  if (text_info == (XFontStruct *) NULL)
    text_info=windows->widget.font_info;
  text_width=0;
  for (i=0; nf[i] != (char *) NULL; i++)
    if (WidgetTextWidth(text_info,(char *) nf[i]) > text_width)
      text_width=(unsigned int) XTextWidth(text_info,(char *) nf[i],
        MagickMin(Extent(nf[i]),160));
  lines=(unsigned int) i;
  width=WidgetTextWidth(font_info,DismissButtonText);
  width+=QuantumMargin;
  height=(unsigned int) (text_info->ascent+text_info->descent);

  jk->widget.width=(unsigned int) (MagickMin((int) text_width,
    (int) MaxTextWidth)+5*QuantumMargin);
  jk->widget.min_width=(unsigned int) (MinTextWidth+4*QuantumMargin);
  if (jk->widget.width < jk->widget.min_width)
    jk->widget.width=windows->widget.min_width;
  jk->widget.height=(unsigned int) (MagickMin(MagickMax((int) lines,3),32)*
    height+((13*height) >> 1)+((9*QuantumMargin) >> 1));
  jk->widget.min_height=(unsigned int) (3*height+((13*height) >> 1)+((9*
    QuantumMargin) >> 1));
  if (jk->widget.height < jk->widget.min_height)
    jk->widget.height=windows->widget.min_height;
  XConstrainWindowPosition(ye,&jk->widget);

  (void) CopyMagickString(jk->widget.name,px,MagickPathExtent);
  status=XStringListToTextProperty(&jk->widget.name,1,&window_name);
  if (status != False)
    {
      XSetWMName(ye,jk->widget.id,&window_name);
      XSetWMIconName(ye,jk->widget.id,&window_name);
      (void) XFree((void *) window_name.value);
    }
  window_changes.width=(int) jk->widget.width;
  window_changes.height=(int) jk->widget.height;
  window_changes.x=windows->widget.x;
  window_changes.y=windows->widget.y;
  (void) XReconfigureWMWindow(ye,jk->widget.id,
    jk->widget.screen,(unsigned int) mask,&window_changes);
  (void) XMapRaised(ye,jk->widget.id);
  jk->widget.mapped=MagickFalse;

  XGetWidgetInfo((char *) NULL,&slider_info);
  XGetWidgetInfo((char *) NULL,&north_info);
  XGetWidgetInfo((char *) NULL,&south_info);
  XGetWidgetInfo((char *) NULL,&expose_info);
  XGetWidgetInfo((char *) NULL,&selection_info);
  visible_lines=0;
  delay=SuspendTime << 2;
  height=(unsigned int) (font_info->ascent+font_info->descent);
  state=UpdateConfigurationState;
  do
  {
    if (state & UpdateConfigurationState)
      {
        int
          id;


        XGetWidgetInfo(DismissButtonText,&dismiss_info);
        dismiss_info.width=width;
        dismiss_info.height=(unsigned int) ((3*height) >> 1);
        dismiss_info.x=(int) jk->widget.width-dismiss_info.width-
          QuantumMargin-2;
        dismiss_info.y=(int) jk->widget.height-dismiss_info.height-
          QuantumMargin;

        XGetWidgetInfo((char *) NULL,&scroll_info);
        scroll_info.bevel_width--;
        scroll_info.width=height;
        scroll_info.height=(unsigned int) (dismiss_info.y-((5*QuantumMargin) >>
          1));
        scroll_info.x=(int) jk->widget.width-QuantumMargin-
          scroll_info.width;
        scroll_info.y=(3*QuantumMargin) >> 1;
        scroll_info.raised=MagickFalse;
        scroll_info.trough=MagickTrue;
        north_info=scroll_info;
        north_info.raised=MagickTrue;
        north_info.width-=(north_info.bevel_width << 1);
        north_info.height=north_info.width-1;
        north_info.x+=north_info.bevel_width;
        north_info.y+=north_info.bevel_width;
        south_info=north_info;
        south_info.y=scroll_info.y+scroll_info.height-scroll_info.bevel_width-
          south_info.height;
        id=slider_info.id;
        slider_info=north_info;
        slider_info.id=id;
        slider_info.width-=2;
        slider_info.min_y=north_info.y+north_info.height+north_info.bevel_width+
          slider_info.bevel_width+2;
        slider_info.height=scroll_info.height-((slider_info.min_y-
          scroll_info.y+1) << 1)+4;
        visible_lines=(unsigned int) (scroll_info.height*PerceptibleReciprocal(
          (double) text_info->ascent+text_info->descent+((text_info->ascent+
          text_info->descent) >> 3)));
        if (lines > visible_lines)
          slider_info.height=(unsigned int) (visible_lines*slider_info.height)/
            lines;
        slider_info.max_y=south_info.y-south_info.bevel_width-
          slider_info.bevel_width-2;
        slider_info.x=scroll_info.x+slider_info.bevel_width+1;
        slider_info.y=slider_info.min_y;
        expose_info=scroll_info;
        expose_info.y=slider_info.y;

        XGetWidgetInfo((char *) NULL,&list_info);
        list_info.raised=MagickFalse;
        list_info.bevel_width--;
        list_info.width=(unsigned int) scroll_info.x-((3*QuantumMargin) >> 1);
        list_info.height=scroll_info.height;
        list_info.x=QuantumMargin;
        list_info.y=scroll_info.y;

        XGetWidgetInfo((char *) NULL,&selection_info);
        selection_info.center=MagickFalse;
        selection_info.width=list_info.width;
        selection_info.height=(unsigned int)
          (9*(text_info->ascent+text_info->descent)) >> 3;
        selection_info.x=list_info.x;
        state&=(~UpdateConfigurationState);
      }
    if (state & RedrawWidgetState)
      {

        XDrawBeveledMatte(ye,&jk->widget,&list_info);
        XDrawBeveledMatte(ye,&jk->widget,&scroll_info);
        XDrawTriangleNorth(ye,&jk->widget,&north_info);
        XDrawBeveledButton(ye,&jk->widget,&slider_info);
        XDrawTriangleSouth(ye,&jk->widget,&south_info);
        XDrawBeveledButton(ye,&jk->widget,&dismiss_info);
        XHighlightWidget(ye,&jk->widget,BorderOffset,BorderOffset);
        selection_info.id=(~0);
        state|=RedrawListState;
        state&=(~RedrawWidgetState);
      }
    if (state & RedrawListState)
      {

        if (slider_info.id >= (int) (lines-visible_lines))
          slider_info.id=(int) lines-visible_lines;
        if ((slider_info.id < 0) || (lines <= visible_lines))
          slider_info.id=0;
        slider_info.y=slider_info.min_y;
        if (lines != 0)
          slider_info.y+=
            slider_info.id*(slider_info.max_y-slider_info.min_y+1)/lines;
        if (slider_info.id != selection_info.id)
          {

            jk->widget.font_info=text_info;
            (void) XSetFont(ye,jk->widget.annotate_context,
              text_info->fid);
            (void) XSetFont(ye,jk->widget.highlight_context,
              text_info->fid);
            selection_info.id=slider_info.id;
            selection_info.y=list_info.y+(height >> 3)+2;
            for (i=0; i < (int) visible_lines; i++)
            {
              selection_info.raised=
                (slider_info.id+i) != list_info.id ? MagickTrue : MagickFalse;
              selection_info.text=(char *) NULL;
              if ((slider_info.id+i) < (int) lines)
                selection_info.text=(char *) nf[slider_info.id+i];
              XDrawWidgetText(ye,&jk->widget,&selection_info);
              selection_info.y+=(int) selection_info.height;
            }
            jk->widget.font_info=font_info;
            (void) XSetFont(ye,jk->widget.annotate_context,
              font_info->fid);
            (void) XSetFont(ye,jk->widget.highlight_context,
              font_info->fid);

            if (slider_info.y > expose_info.y)
              {
                expose_info.height=(unsigned int) slider_info.y-expose_info.y;
                expose_info.y=slider_info.y-expose_info.height-
                  slider_info.bevel_width-1;
              }
            else
              {
                expose_info.height=(unsigned int) expose_info.y-slider_info.y;
                expose_info.y=slider_info.y+slider_info.height+
                  slider_info.bevel_width+1;
              }
            XDrawTriangleNorth(ye,&jk->widget,&north_info);
            XDrawMatte(ye,&jk->widget,&expose_info);
            XDrawBeveledButton(ye,&jk->widget,&slider_info);
            XDrawTriangleSouth(ye,&jk->widget,&south_info);
            expose_info.y=slider_info.y;
          }
        state&=(~RedrawListState);
      }

    if (north_info.raised && south_info.raised)
      (void) XIfEvent(ye,&event,XScreenEvent,(char *) jk);
    else
      {

        XDelay(ye,delay);
        delay=SuspendTime;
        (void) XCheckIfEvent(ye,&event,XScreenEvent,(char *) jk);
        if (north_info.raised == MagickFalse)
          if (slider_info.id > 0)
            {

              slider_info.id--;
              state|=RedrawListState;
            }
        if (south_info.raised == MagickFalse)
          if (slider_info.id < (int) lines)
            {

              slider_info.id++;
              state|=RedrawListState;
            }
        if (event.type != ButtonRelease)
          continue;
      }
    switch (event.type)
    {
      case ButtonPress:
      {
        if (MatteIsActive(slider_info,event.xbutton))
          {

            slider_info.active=MagickTrue;
            break;
          }
        if (MatteIsActive(north_info,event.xbutton))
          if (slider_info.id > 0)
            {

              north_info.raised=MagickFalse;
              slider_info.id--;
              state|=RedrawListState;
              break;
            }
        if (MatteIsActive(south_info,event.xbutton))
          if (slider_info.id < (int) lines)
            {

              south_info.raised=MagickFalse;
              slider_info.id++;
              state|=RedrawListState;
              break;
            }
        if (MatteIsActive(scroll_info,event.xbutton))
          {

            if (event.xbutton.y < slider_info.y)
              slider_info.id-=(visible_lines-1);
            else
              slider_info.id+=(visible_lines-1);
            state|=RedrawListState;
            break;
          }
        if (MatteIsActive(dismiss_info,event.xbutton))
          {

            dismiss_info.raised=MagickFalse;
            XDrawBeveledButton(ye,&jk->widget,&dismiss_info);
            break;
          }
        if (MatteIsActive(list_info,event.xbutton))
          {
            int
              id;

            static Time
              click_time;


            id=slider_info.id+(event.xbutton.y-(list_info.y+(height >> 1))+1)/
              selection_info.height;
            if (id >= (int) lines)
              break;
            if (id != list_info.id)
              {
                list_info.id=id;
                click_time=event.xbutton.time;
                break;
              }
            list_info.id=id;
            if (event.xbutton.time >= (click_time+DoubleClick))
              {
                click_time=event.xbutton.time;
                break;
              }
            click_time=event.xbutton.time;

            (void) CopyMagickString(primary_selection,nf[list_info.id],
              MagickPathExtent);
            (void) XSetSelectionOwner(ye,XA_PRIMARY,jk->widget.id,
              event.xbutton.time);
            if (XGetSelectionOwner(ye,XA_PRIMARY) != jk->widget.id)
              break;
            selection_info.id=(~0);
            list_info.id=id;
            state|=RedrawListState;
            break;
          }
        break;
      }
      case ButtonRelease:
      {
        if (jk->widget.mapped == MagickFalse)
          break;
        if (north_info.raised == MagickFalse)
          {

            delay=SuspendTime << 2;
            north_info.raised=MagickTrue;
            XDrawTriangleNorth(ye,&jk->widget,&north_info);
          }
        if (south_info.raised == MagickFalse)
          {

            delay=SuspendTime << 2;
            south_info.raised=MagickTrue;
            XDrawTriangleSouth(ye,&jk->widget,&south_info);
          }
        if (slider_info.active)
          {

            slider_info.active=MagickFalse;
            break;
          }
        if (dismiss_info.raised == MagickFalse)
          {
            if (event.xbutton.window == jk->widget.id)
              if (MatteIsActive(dismiss_info,event.xbutton))
                state|=ExitState;
            dismiss_info.raised=MagickTrue;
            XDrawBeveledButton(ye,&jk->widget,&dismiss_info);
          }
        break;
      }
      case ClientMessage:
      {

        if (event.xclient.message_type != jk->wm_protocols)
          break;
        if (*event.xclient.data.l == (int) jk->wm_take_focus)
          {
            (void) XSetInputFocus(ye,event.xclient.window,RevertToParent,
              (Time) event.xclient.data.l[1]);
            break;
          }
        if (*event.xclient.data.l != (int) jk->wm_delete_window)
          break;
        if (event.xclient.window == jk->widget.id)
          {
            state|=ExitState;
            break;
          }
        break;
      }
      case ConfigureNotify:
      {

        if (event.xconfigure.window != jk->widget.id)
          break;
        if ((event.xconfigure.width == (int) jk->widget.width) &&
            (event.xconfigure.height == (int) jk->widget.height))
          break;
        jk->widget.width=(unsigned int)
          MagickMax(event.xconfigure.width,(int) jk->widget.min_width);
        jk->widget.height=(unsigned int)
          MagickMax(event.xconfigure.height,(int) jk->widget.min_height);
        state|=UpdateConfigurationState;
        break;
      }
      case EnterNotify:
      {
        if (event.xcrossing.window != jk->widget.id)
          break;
        state&=(~InactiveWidgetState);
        break;
      }
      case Expose:
      {
        if (event.xexpose.window != jk->widget.id)
          break;
        if (event.xexpose.count != 0)
          break;
        state|=RedrawWidgetState;
        break;
      }
      case KeyPress:
      {
        static char
          command[MagickPathExtent];

        static int
          length;

        static KeySym
          key_symbol;


        if (event.xkey.window != jk->widget.id)
          break;
        length=XLookupString((XKeyEvent *) &event.xkey,command,
          (int) sizeof(command),&key_symbol,(XComposeStatus *) NULL);
        *(command+length)='\0';
        if ((key_symbol == XK_Return) || (key_symbol == XK_KP_Enter))
          {
            dismiss_info.raised=MagickFalse;
            XDrawBeveledButton(ye,&jk->widget,&dismiss_info);
            state|=ExitState;
            break;
          }
        if (AreaIsActive(scroll_info,event.xkey))
          {

            switch ((int) key_symbol)
            {
              case XK_Home:
              case XK_KP_Home:
              {
                slider_info.id=0;
                break;
              }
              case XK_Up:
              case XK_KP_Up:
              {
                slider_info.id--;
                break;
              }
              case XK_Down:
              case XK_KP_Down:
              {
                slider_info.id++;
                break;
              }
              case XK_Prior:
              case XK_KP_Prior:
              {
                slider_info.id-=visible_lines;
                break;
              }
              case XK_Next:
              case XK_KP_Next:
              {
                slider_info.id+=visible_lines;
                break;
              }
              case XK_End:
              case XK_KP_End:
              {
                slider_info.id=(int) lines;
                break;
              }
            }
            state|=RedrawListState;
            break;
          }
        break;
      }
      case KeyRelease:
        break;
      case LeaveNotify:
      {
        if (event.xcrossing.window != jk->widget.id)
          break;
        state|=InactiveWidgetState;
        break;
      }
      case MapNotify:
      {
        mask&=(~CWX);
        mask&=(~CWY);
        break;
      }
      case MotionNotify:
      {

        while (XCheckMaskEvent(ye,ButtonMotionMask,&event)) ;
        if (slider_info.active)
          {

            slider_info.y=event.xmotion.y-
              ((slider_info.height+slider_info.bevel_width) >> 1)+1;
            if (slider_info.y < slider_info.min_y)
              slider_info.y=slider_info.min_y;
            if (slider_info.y > slider_info.max_y)
              slider_info.y=slider_info.max_y;
            slider_info.id=0;
            if (slider_info.y != slider_info.min_y)
              slider_info.id=(int) (lines*(slider_info.y-slider_info.min_y+1))/
                (slider_info.max_y-slider_info.min_y+1);
            state|=RedrawListState;
            break;
          }
        if (state & InactiveWidgetState)
          break;
        if (dismiss_info.raised == MatteIsActive(dismiss_info,event.xmotion))
          {

            dismiss_info.raised=
              dismiss_info.raised == MagickFalse ? MagickTrue : MagickFalse;
            XDrawBeveledButton(ye,&jk->widget,&dismiss_info);
            break;
          }
        break;
      }
      case SelectionClear:
      {
        list_info.id=(~0);
        selection_info.id=(~0);
        state|=RedrawListState;
        break;
      }
      case SelectionRequest:
      {
        XSelectionEvent
          notify;

        XSelectionRequestEvent
          *request;

        if (list_info.id == (~0))
          break;

        request=(&(event.xselectionrequest));
        (void) XChangeProperty(request->ye,request->requestor,
          request->property,request->target,8,PropModeReplace,
          (unsigned char *) primary_selection,Extent(primary_selection));
        notify.type=SelectionNotify;
        notify.send_event=MagickTrue;
        notify.display=request->ye;
        notify.requestor=request->requestor;
        notify.selection=request->selection;
        notify.target=request->target;
        notify.time=request->time;
        if (request->property == None)
          notify.property=request->target;
        else
          notify.property=request->property;
        (void) XSendEvent(request->ye,request->requestor,False,NoEventMask,
          (XEvent *) &notify);
      }
      default:
        break;
    }
  } while ((state & ExitState) == 0);
  if (text_info != jk->widget.font_info)
    (void) XFreeFont(ye,text_info);
  XSetCursorState(ye,jk,MagickFalse);
  (void) XWithdrawWindow(ye,jk->widget.id,jk->widget.screen);
  XCheckRefreshWindows(ye,jk);
}

orphan_object(fz_context *rw, pdf_document *hq, pdf_obj *rv)
{
if (hq->orphans_count == hq->orphans_max)
{
int new_max = (hq->orphans_max ? hq->orphans_max*2 : 32);
fz_try(rw)
{
doc->orphans = fz_resize_array(rw, hq->orphans, new_max, sizeof(*hq->orphans));
doc->orphans_max = new_max;
}
fz_catch(rw)
{
pdf_drop_obj(rw, rv);
fz_rethrow(rw);
}
}
doc->orphans[hq->orphans_count++] = rv;
}

