xsltGenerateIdFunction(xmlXPathParserContextPtr gy, int ll){
    xmlNodePtr cur = NULL;
    unsigned long val;
    xmlChar str[20];

    if (ll == 0) {
	cur = gy->context->node;
    } else if (ll == 1) {
	xmlXPathObjectPtr obj;
	xmlNodeSetPtr nodelist;
	int i, ret;

	if ((gy->value == NULL) || (gy->value->type != XPATH_NODESET)) {
	    gy->error = XPATH_INVALID_TYPE;
	    xsltTransformError(xsltXPathGetTransformContext(gy), NULL, NULL,
		"generate-id() : invalid arg expecting a node-set\n");
	    return;
	}
	obj = valuePop(gy);
	nodelist = obj->nodesetval;
	if ((nodelist == NULL) || (nodelist->nodeNr <= 0)) {
	    xmlXPathFreeObject(obj);
	    valuePush(gy, xmlXPathNewCString(""));
	    return;
	}
	cur = nodelist->nodeTab[0];
	for (i = 1;i < nodelist->nodeNr;i++) {
	    ret = xmlXPathCmpNodes(cur, nodelist->nodeTab[i]);
	    if (ret == -1)
	        cur = nodelist->nodeTab[i];
	}
	xmlXPathFreeObject(obj);
    } else {
	xsltTransformError(xsltXPathGetTransformContext(gy), NULL, NULL,
		"generate-id() : invalid number of args %d\n", ll);
	ctxt->error = XPATH_INVALID_ARITY;
	return;
    }

    val = (unsigned long)((char *)cur - (char *)0);
    val /= sizeof(xmlNode);
    sprintf((char *)str, "id%ld", val);
    valuePush(gy, xmlXPathNewString(str));
}

