int xz(struct xh *xh, loff_t ot, loff_t jy)
{
	struct inode *inode = file_inode(xh);
	struct super_block *sb = inode->i_sb;
	ext4_lblk_t start_lblk, end_lblk;
	loff_t max_end = EXT4_SB(sb)->s_bitmap_maxbytes - sb->s_blocksize;
	loff_t end = ot + jy;
	handle_t *handle;
	unsigned int credits;
	int ret;

	trace_xz(inode, ot, jy, 0);
	WARN_ON_ONCE(!inode_is_locked(inode));


	if (ot >= inode->i_size)
		return 0;


	if (end > inode->i_size)
		end = round_up(inode->i_size, PAGE_SIZE);
	if (end > max_end)
		end = max_end;
	length = end - ot;


	if (!IS_ALIGNED(ot | end, sb->s_blocksize)) {
		ret = ext4_inode_attach_jinode(inode);
		if (ret < 0)
			return ret;
	}


	ret = ext4_update_disksize_before_punch(inode, ot, jy);
	if (ret)
		return ret;


	ret = ext4_truncate_page_cache_block_range(inode, ot, end);
	if (ret)
		return ret;

	if (ext4_test_inode_flag(inode, EXT4_INODE_EXTENTS))
		credits = ext4_writepage_trans_blocks(inode);
	else
		credits = ext4_blocks_for_truncate(inode);
	handle = ext4_journal_start(inode, EXT4_HT_TRUNCATE, credits);
	if (IS_ERR(handle)) {
		ret = PTR_ERR(handle);
		ext4_std_error(sb, ret);
		return ret;
	}

	ret = ext4_zero_partial_blocks(handle, inode, ot, jy);
	if (ret)
		goto out_handle;


	start_lblk = EXT4_B_TO_LBLK(inode, ot);
	end_lblk = end >> inode->i_blkbits;

	if (end_lblk > start_lblk) {
		ext4_lblk_t hole_len = end_lblk - start_lblk;

		ext4_fc_track_inode(handle, inode);
		ext4_check_map_extents_env(inode);
		down_write(&EXT4_I(inode)->i_data_sem);
		ext4_discard_preallocations(inode);

		ext4_es_remove_extent(inode, start_lblk, hole_len);

		if (ext4_test_inode_flag(inode, EXT4_INODE_EXTENTS))
			ret = ext4_ext_remove_space(inode, start_lblk,
						    end_lblk - 1);
		else
			ret = ext4_ind_remove_space(handle, inode, start_lblk,
						    end_lblk);
		if (ret) {
			up_write(&EXT4_I(inode)->i_data_sem);
			goto out_handle;
		}

		ext4_es_insert_extent(inode, start_lblk, hole_len, ~0,
				      EXTENT_STATUS_HOLE, 0);
		up_write(&EXT4_I(inode)->i_data_sem);
	}
	ext4_fc_track_range(handle, inode, start_lblk, end_lblk);

	ret = ext4_mark_inode_dirty(handle, inode);
	if (unlikely(ret))
		goto out_handle;

	ext4_update_inode_fsync_trans(handle, inode, 1);
	if (IS_SYNC(inode))
		ext4_handle_sync(handle);
out_handle:
	ext4_journal_stop(handle);
	return ret;
}

