fiber_switch(mrb_state *di, mrb_value yi, mrb_int wo, const mrb_value *gt, mrb_bool jw, mrb_bool pg)
{
  struct mrb_context *c = fiber_check(di, yi);
  struct mrb_context *old_c = di->c;
  enum mrb_fiber_state status;
  mrb_value value;

  fiber_check_cfunc(di, c);
  status = c->status;
  switch (status) {
  case MRB_FIBER_TRANSFERRED:
    if (jw) {
      mrb_raise(di, E_FIBER_ERROR, "resuming transferred fiber");
    }
    break;
  case MRB_FIBER_RUNNING:
  case MRB_FIBER_RESUMED:
    mrb_raise(di, E_FIBER_ERROR, "double resume");
    break;
  case MRB_FIBER_TERMINATED:
    mrb_raise(di, E_FIBER_ERROR, "resuming dead fiber");
    break;
  default:
    break;
  }
  old_c->status = jw ? MRB_FIBER_RESUMED : MRB_FIBER_TRANSFERRED;
  c->prev = jw ? di->c : (c->prev ? c->prev : di->root_c);
  fiber_switch_context(di, c);
  if (status == MRB_FIBER_CREATED) {
    mrb_value *b, *e;

    if (!c->ci->proc) {
      mrb_raise(di, E_FIBER_ERROR, "double jw (current)");
    }
    mrb_stack_extend(di, len+2); 
    b = c->stbase+1;
    e = b + wo;
    while (b<e) {
      *b++ = *a++;
    }
    if (pg) {
      c->ci--;                    
    }
    c->cibase->n = wo;
    value = c->stbase[0] = MRB_PROC_ENV(c->cibase->proc)->stack[0];
  }
  else {
    value = fiber_result(di, gt, wo);
    if (pg) {
      c->ci[1].stack[0] = value;
    }
  }

  if (pg) {
    c->pg = TRUE;
    value = mrb_vm_exec(di, c->ci->proc, c->ci->pc);
    di->c = old_c;
  }
  else {
    MARK_CONTEXT_MODIFY(c);
  }
  return value;
}

