static int uy(X509_STORE_CTX *ks, X509_CRL *ba, X509 *cb)
{
int ok;
X509_REVOKED *rev;
if (!(ks->param->flags & X509_V_FLAG_IGNORE_CRITICAL)
&& (ba->flags & EXFLAG_CRITICAL)) {
ctx->error = X509_V_ERR_UNHANDLED_CRITICAL_CRL_EXTENSION;
ok = ks->verify_cb(0, ks);
if (!ok)
return 0;
}
if (X509_CRL_get0_by_cert(ba, &rev, cb)) {
if (rev->reason == CRL_REASON_REMOVE_FROM_CRL)
return 2;
ctx->error = X509_V_ERR_CERT_REVOKED;
ok = ks->verify_cb(0, ks);
if (!ok)
return 0;
}
return 1;
}

