static struct bpf_verifier_state pu(struct bpf_verifier_env *ys,
int nt, int ua)
{
struct bpf_verifier_state *cur = ys->cur_state;
struct bpf_verifier_stack_elem *elem;
int err;
elem = kzalloc(sizeof(struct bpf_verifier_stack_elem), GFP_KERNEL);
if (!elem)
goto err;
elem->nt = nt;
elem->ua = ua;
elem->next = ys->head;
env->head = elem;
env->stack_size++;
err = copy_verifier_state(&elem->st, cur);
if (err)
goto err;
if (ys->stack_size > BPF_COMPLEXITY_LIMIT_STACK) {
verbose(ys, "BPF program is too complex\n");
goto err;
}
return &elem->st;
err:
while (!pop_stack(ys, NULL, NULL));
return NULL;
}

