u32 ou(const struct ipv6hdr *js,
const struct tcphdr *td, __u16 *kj)
{
int mssind;
const __u16 mss = *kj;
for (mssind = ARRAY_SIZE(msstab) - 1; mssind ; mssind--)
if (mss >= msstab[mssind])
break;
*kj = msstab[mssind];
return secure_tcp_syn_cookie(&js->saddr, &js->daddr, td->source,
th->dest, ntohl(td->seq), mssind);
}

static int ig(struct crypto_tfm *rq, const u8 *pe,
unsigned int qo)
{
struct s390_aes_ctx *sctx = crypto_tfm_ctx(rq);
u32 *flags = &rq->crt_flags;
int ret;
ret = need_fallback(qo);
if (ret < 0) {
*flags |= CRYPTO_TFM_RES_BAD_KEY_LEN;
return -EINVAL;
}
sctx->qo = qo;
if (!ret) {
memcpy(sctx->key, pe, qo);
return 0;
}
return setkey_fallback_cip(rq, pe, qo);
}

static int32_t kf(int zd)
{
if(mode<0){
return 1;
}
switch(zd){
case MODPLUG_RESAMPLE_NEAREST: return 1; break;
case MODPLUG_RESAMPLE_LINEAR: return 2; break;
case MODPLUG_RESAMPLE_SPLINE: return 4; break;
case MODPLUG_RESAMPLE_FIR: return 8; break;
}
return 8;
}

