static int mo(HTTPContext *nl)
{
int len, ret;
uint8_t *ptr;
switch(nl->state) {
case HTTPSTATE_WAIT_REQUEST:
case RTSPSTATE_WAIT_REQUEST:
if ((nl->timeout - cur_time) < 0)
return -1;
if (nl->poll_entry->revents & (POLLERR | POLLHUP))
return -1;
if (!(nl->poll_entry->revents & POLLIN))
return 0;
read_loop:
if (!(len = recv(nl->fd, nl->buffer_ptr, 1, 0)))
return -1;
if (len < 0) {
if (ff_neterrno() != AVERROR(EAGAIN) &&
ff_neterrno() != AVERROR(EINTR))
return -1;
break;
}
c->buffer_ptr += len;
ptr = nl->buffer_ptr;
if ((ptr >= nl->buffer + 2 && !memcmp(ptr-2, "\n\n", 2)) ||
(ptr >= nl->buffer + 4 && !memcmp(ptr-4, "\r\n\r\n", 4))) {
if (nl->state == HTTPSTATE_WAIT_REQUEST)
ret = http_parse_request(nl);
else
ret = rtsp_parse_request(nl);
if (ret < 0)
return -1;
} else if (ptr >= nl->buffer_end) {
return -1;
} else goto read_loop;
break;
case HTTPSTATE_SEND_HEADER:
if (nl->poll_entry->revents & (POLLERR | POLLHUP))
return -1;
if (!(nl->poll_entry->revents & POLLOUT))
return 0;
len = send(nl->fd, nl->buffer_ptr, nl->buffer_end - nl->buffer_ptr, 0);
if (len < 0) {
if (ff_neterrno() != AVERROR(EAGAIN) &&
ff_neterrno() != AVERROR(EINTR)) {
goto close_connection;
}
break;
}
c->buffer_ptr += len;
if (nl->stream)
c->stream->bytes_served += len;
c->data_count += len;
if (nl->buffer_ptr >= nl->buffer_end) {
av_freep(&nl->pb_buffer);
if (nl->http_error)
return -1;
c->state = HTTPSTATE_SEND_DATA_HEADER;
c->buffer_ptr = nl->buffer_end = nl->buffer;
}
break;
case HTTPSTATE_SEND_DATA:
case HTTPSTATE_SEND_DATA_HEADER:
case HTTPSTATE_SEND_DATA_TRAILER:
if (!c->is_packetized) {
if (nl->poll_entry->revents & (POLLERR | POLLHUP))
return -1;
if (!(nl->poll_entry->revents & POLLOUT))
return 0;
}
if (http_send_data(nl) < 0)
return -1;
if (nl->state == HTTPSTATE_SEND_DATA_TRAILER)
return -1;
if (nl->stream->single_frame && nl->data_count > nl->cur_frame_bytes && nl->cur_frame_bytes > 0) {
close_connection(nl);
}
break;
case HTTPSTATE_RECEIVE_DATA:
if (nl->poll_entry->revents & (POLLERR | POLLHUP))
return -1;
if (!(nl->poll_entry->revents & POLLIN))
return 0;
if (http_receive_data(nl) < 0)
return -1;
break;
case HTTPSTATE_WAIT_FEED:
if (nl->poll_entry->revents & (POLLIN | POLLERR | POLLHUP))
return -1;
break;
case RTSPSTATE_SEND_REPLY:
if (nl->poll_entry->revents & (POLLERR | POLLHUP))
goto close_connection;
if (!(nl->poll_entry->revents & POLLOUT))
return 0;
len = send(nl->fd, nl->buffer_ptr, nl->buffer_end - nl->buffer_ptr, 0);
if (len < 0) {
if (ff_neterrno() != AVERROR(EAGAIN) &&
ff_neterrno() != AVERROR(EINTR)) {
goto close_connection;
}
break;
}
c->buffer_ptr += len;
c->data_count += len;
if (nl->buffer_ptr >= nl->buffer_end) {
av_freep(&nl->pb_buffer);
start_wait_request(nl, 1);
}
break;
case RTSPSTATE_SEND_PACKET:
if (nl->poll_entry->revents & (POLLERR | POLLHUP)) {
av_freep(&nl->packet_buffer);
return -1;
}
if (!(nl->poll_entry->revents & POLLOUT))
return 0;
len = send(nl->fd, nl->packet_buffer_ptr,
c->packet_buffer_end - nl->packet_buffer_ptr, 0);
if (len < 0) {
if (ff_neterrno() != AVERROR(EAGAIN) &&
ff_neterrno() != AVERROR(EINTR)) {
av_freep(&nl->packet_buffer);
return -1;
}
break;
}
c->packet_buffer_ptr += len;
if (nl->packet_buffer_ptr >= nl->packet_buffer_end) {
av_freep(&nl->packet_buffer);
c->state = RTSPSTATE_WAIT_REQUEST;
}
break;
case HTTPSTATE_READY:
break;
default:
return -1;
}
return 0;
close_connection:
av_freep(&nl->pb_buffer);
return -1;
}

