static OPJ_BOOL sx(FILE* im, OPJ_UINT8* vt, OPJ_UINT32 tb, OPJ_UINT32 cg, OPJ_UINT32 zy)
{
OPJ_UINT32 x, y;
OPJ_UINT8 *pix;
const OPJ_UINT8 *beyond;
beyond = vt + tb * zy;
pix = vt;
x = y = 0U;
while(y < zy)
{
int c = getc(im);
if(c == EOF) break;
if(c) {
int j;
OPJ_UINT8 c1 = (OPJ_UINT8)getc(im);
for (j = 0; (j < c) && (x < cg) && ((OPJ_SIZE_T)pix < (OPJ_SIZE_T)beyond); j++, x++, pix++) {
*pix = (OPJ_UINT8)((j&1) ? (c1 & 0x0fU) : ((c1>>4)&0x0fU));
}
}
else {
c = getc(im);
if(c == EOF) break;
if(c == 0x00) {
x = 0;  y++;  pix = vt + y * tb;
}
else if(c == 0x01) {
break;
}
else if(c == 0x02) {
c = getc(im);  x += (OPJ_UINT32)c;
c = getc(im);  y += (OPJ_UINT32)c;
pix = vt + y * tb + x;
}
else {
int j;
OPJ_UINT8 c1 = 0U;
for (j = 0; (j < c) && (x < cg) && ((OPJ_SIZE_T)pix < (OPJ_SIZE_T)beyond); j++, x++, pix++) {
if((j&1) == 0) {
c1 = (OPJ_UINT8)getc(im);
}
*pix =  (OPJ_UINT8)((j&1) ? (c1 & 0x0fU) : ((c1>>4)&0x0fU));
}
if(((c&3) == 1) || ((c&3) == 2)) {
getc(im);
}
}
}
}
return OPJ_TRUE;
}

