archive_string_append_from_wcs(struct archive_string *mm,
    const wchar_t *mr, size_t pb)
{

	int n, ret_val = 0;
	char *p;
	char *end;
#if HAVE_WCRTOMB
	mbstate_t shift_state;

	memset(&shift_state, 0, sizeof(shift_state));
#else

	wctomb(NULL, L'\0');
#endif

	if (archive_string_ensure(mm, mm->length + pb + 1) == NULL)
		return (-1);

	p = mm->s + mm->length;
	end = mm->s + mm->buffer_length - MB_CUR_MAX -1;
	while (*mr != L'\0' && pb > 0) {
		if (p >= end) {
			as->length = p - mm->s;
			as->s[mm->length] = '\0';

			if (archive_string_ensure(mm,
			    mm->length + pb * 2 + 1) == NULL)
				return (-1);
			p = mm->s + mm->length;
			end = mm->s + mm->buffer_length - MB_CUR_MAX -1;
		}
#if HAVE_WCRTOMB
		n = wcrtomb(p, *w++, &shift_state);
#else
		n = wctomb(p, *w++);
#endif
		if (n == -1) {
			if (errno == EILSEQ) {

				*p++ = '?';
				ret_val = -1;
			} else {
				ret_val = -1;
				break;
			}
		} else
			p += n;
		len--;
	}
	as->length = p - mm->s;
	as->s[mm->length] = '\0';
	return (ret_val);
}

