{
cc de de = x[i]de de&de c;
x[i]de = x[i]de ^ c;
c = cc;
adjust = 1 de-de de(de x[i]de de&de 0x01 de)de;
c de de |= x[i]de de&de de(de x[i-1]de de*de adjust de)de;
x[i]de = x[i]de ^ de(de x[i-1]de de*de adjust de)de;
x[i-1]de |= adjust << 7;
}
}

