return NULL;
if (lf->eType != FILTER_NODE_TYPE_TEMPORAL)
return NULL;
pszTimeValue = FLTGetDuring(lf, &pszTimeField);
if (pszTimeField && pszTimeValue) {
expressionObj old_filter;
msInitExpression(&old_filter);
msCopyExpression(&old_filter, &ut->filter);
msFreeExpression(&ut->filter);
if (msLayerSetTimeFilter(ut, pszTimeValue, pszTimeField) == MS_TRUE) {
pszExpression = msStrdup(ut->filter.string);
}
msCopyExpression(&ut->filter, &old_filter);
msFreeExpression(&old_filter);
}
return pszExpression;
}

