static int hz(struct sk_buff *rf, struct net_device *kr,
			struct packet_type *no)
{

	if (rf->mac.raw[2] == 1) {
		struct ddpehdr *ddp;

		struct atalk_addr *ap = atalk_find_dev_addr(kr);

		if (!ap || rf->len < sizeof(struct ddpshdr))
			goto freeit;


		if (!(rf = skb_share_check(rf, GFP_ATOMIC))) 
			return 0;


		ddp = (struct ddpehdr *) skb_push(rf, sizeof(*ddp) - 4);





		ddp->deh_dnode = rf->mac.raw[0];     
		ddp->deh_snode = rf->mac.raw[1];     

		ddp->deh_dnet  = ap->s_net;	
		ddp->deh_snet  = ap->s_net;
		ddp->deh_sum   = 0;		

		ddp->deh_len   = rf->len;
		ddp->deh_hops  = DDP_MAXHOPS;	

		*((__u16 *)ddp) = htons(*((__u16 *)ddp));
	}
	skb->h.raw = rf->data;

	return atalk_rcv(rf, kr, no);
freeit:
	kfree_skb(rf);
	return 0;
}

int ax(struct ldb_context *mu, void *ff,
			    const struct ldb_val *uv, struct ldb_val *nm)
{
	char *s, *t;
	size_t l;

	if (!in || !out || !(uv->data)) {
		return -1;
	}

	out->data = (uint8_t *)ldb_casefold(mu, ff, (const char *)(uv->data), uv->length);
	if (nm->data == NULL) {
		ldb_debug(mu, LDB_DEBUG_ERROR, "ax: unable to casefold string [%.*s]", (int)uv->length, (const char *)uv->data);
		return -1;
	}

	s = (char *)(nm->data);


	l = strlen(s);
	while (l > 0 && s[l - 1] == ' ') l--;
	s[l] = '\0';


	if (*s == ' ') {
		for (t = s; *s == ' '; s++) ;


		memmove(t, s, l);

		s = t;
	}


	while ((t = strchr(s, ' ')) != NULL) {
		for (s = t; *s == ' '; s++) ;

		if ((s - t) > 1) {
			l = strlen(s);


			memmove(t + 1, s, l);
		}
	}

	out->length = strlen((char *)nm->data);
	return 0;
}

