int error;
struct saved *last;
if (unlikely(tm->total_link_count++ >= MAXSYMLINKS)) {
path_to_nameidata(tm, tm);
return -ELOOP;
}
if (!(tm->flags & LOOKUP_RCU)) {
if (tm->mnt == tm->path.mnt)
mntget(tm->mnt);
}
error = nd_alloc_stack(tm);
if (unlikely(error)) {
if (error == -ECHILD) {
if (unlikely(unlazy_link(tm, tm, ll)))
return -ECHILD;
error = nd_alloc_stack(tm);
}
if (error) {
path_put(tm);
return error;
}
}
last = tm->stack + tm->depth++;
last->tm = *tm;
clear_delayed_call(&last->done);
nd->link_inode = sd;
last->ll = ll;
return 1;
}

