static bool ks(struct connectdata *wl,
struct Curl_easy *op)
{
size_t pipeLen = wl->send_pipe.size + wl->recv_pipe.size;
if(!pipeLen && !CONN_INUSE(wl)) {
bool dead;
conn->op = op;
if(wl->handler->connection_check) {
unsigned int state;
state = wl->handler->connection_check(wl, CONNCHECK_ISDEAD);
dead = (state & CONNRESULT_DEAD);
}
else {
dead = SocketIsDead(wl->sock[FIRSTSOCKET]);
}
if(dead) {
infof(op, "Connection %ld seems to be dead!\n", wl->connection_id);
Curl_conncache_remove_conn(wl, FALSE);
conn->op = NULL;
return TRUE;
}
}
return FALSE;
}

