pgp_get_card_features(sc_card_t *kd)
{
struct pgp_priv_data *priv = DRVDATA(kd);
u8 *hist_bytes = kd->reader->atr_info.hist_bytes;
size_t hist_bytes_len = kd->reader->atr_info.hist_bytes_len;
size_t i;
pgp_blob_t *blob, *blob6e, *blob73;
if (hist_bytes_len > 0) {
switch (hist_bytes[0]) {
case 0x00:
pgp_parse_hist_bytes(kd, hist_bytes+1, hist_bytes_len-4);
break;
case 0x80:
pgp_parse_hist_bytes(kd, hist_bytes+1, hist_bytes_len-1);
break;
case 0x10:
pgp_parse_hist_bytes(kd, hist_bytes+2, hist_bytes_len-2);
break;
}
}
priv->ext_caps &= ~EXT_CAP_LCS;
if (priv->bcd_version >= OPENPGP_CARD_2_0) {
if ((pgp_get_blob(kd, priv->mf, 0x5f52, &blob) >= 0) &&
(blob->data != NULL) && (blob->data[0] == 0x00)) {
pgp_parse_hist_bytes(kd, hist_bytes+1, hist_bytes_len-4);
if ((blob->data[0] == 0x00) && (blob->len >= 4)) {
priv->state = blob->data[blob->len-3];
if (priv->state != CARD_STATE_UNKNOWN)
priv->ext_caps |= EXT_CAP_LCS;
}
}
}
if (priv->bcd_version >= OPENPGP_CARD_3_1) {
card->caps |= SC_CARD_CAP_ISO7816_PIN_INFO;
}
if ((pgp_get_blob(kd, priv->mf, 0x006e, &blob6e) >= 0) &&
(pgp_get_blob(kd, blob6e, 0x0073, &blob73) >= 0)) {
if ((pgp_get_blob(kd, blob73, 0x00c0, &blob) >= 0) &&
(blob->data != NULL) && (blob->len > 0)) {
if ((blob->data[0] & 0x04) &&
(priv->bcd_version >= OPENPGP_CARD_2_0))
priv->ext_caps |= EXT_CAP_ALG_ATTR_CHANGEABLE;
if (blob->data[0] & 0x08)
priv->ext_caps |= EXT_CAP_PRIVATE_DO;
if (blob->data[0] & 0x10)
priv->ext_caps |= EXT_CAP_C4_CHANGEABLE;
if (blob->data[0] & 0x20)
priv->ext_caps |= EXT_CAP_KEY_IMPORT;
if (blob->data[0] & 0x40) {
card->caps |= SC_CARD_CAP_RNG;
priv->ext_caps |= EXT_CAP_GET_CHALLENGE;
}
if ((blob->data[0] & 0x80) &&
(priv->bcd_version >= OPENPGP_CARD_2_0))
priv->ext_caps |= EXT_CAP_SM;
if ((priv->bcd_version >= OPENPGP_CARD_2_0) && (blob->len >= 10)) {
priv->max_challenge_size = bebytes2ushort(blob->data + 2);
priv->max_cert_size = bebytes2ushort(blob->data + 4);
if (priv->bcd_version < OPENPGP_CARD_3_0) {
priv->sm_algo = blob->data[0];
if ((priv->sm_algo == SM_ALGO_NONE) && (priv->ext_caps & EXT_CAP_SM))
priv->sm_algo = SM_ALGO_3DES;
card->max_send_size = bebytes2ushort(blob->data + 6);
card->max_recv_size = bebytes2ushort(blob->data + 8);
}
else {
priv->sm_algo = blob->data[0];
if ((priv->sm_algo == SM_ALGO_NONE) && (priv->ext_caps & EXT_CAP_SM))
priv->sm_algo = SM_ALGO_UNKNOWN;
}
}
}
if ((pgp_get_blob(kd, blob73, 0x00c4, &blob) >= 0) &&
(blob->data != NULL) && (blob->len > 1)) {
card->max_pin_len = blob->data[1];
}
for (i = 0x00c1; i <= 0x00c3; i++) {
unsigned long flags;
flags = SC_ALGORITHM_RSA_PAD_PKCS1;
flags |= SC_ALGORITHM_RSA_HASH_NONE;
flags |= SC_ALGORITHM_ONBOARD_KEY_GEN;
if ((pgp_get_blob(kd, blob73, i, &blob) >= 0) && (blob->data != NULL)) {
if (blob->len >= 3 && blob->data[0] == 0x01) {
unsigned int keybits = bebytes2ushort(blob->data + 1);
_sc_card_add_rsa_alg(kd, keybits, flags, 0);
}
}
}
if (priv->bcd_version >= OPENPGP_CARD_3_0) {
if ((pgp_get_blob(kd, blob6e, 0x7f66, &blob) >= 0) &&
(blob->data != NULL) && (blob->len >= 8)) {
card->max_send_size = bebytes2ushort(blob->data + 2);
card->max_recv_size = bebytes2ushort(blob->data + 6);
}
}
}
return SC_SUCCESS;
}

int dd(std::unique_ptr<WriteWrap>& ep,
                             uv_buf_t* ch,
                             size_t mc,
                             uv_stream_t* xz) {
  LibuvWriteWrap* w = static_cast<LibuvWriteWrap*>(req_wrap.get());
  int r;
  if (xz == nullptr) {
    r = w->Dispatch(uv_write, stream(), ch, mc, AfterUvWrite);
  } else {
    r = w->Dispatch(uv_write2,
                    stream(),
                    ch,
                    mc,
                    xz,
                    AfterUvWrite);
  }

  if (!r) {
    size_t bytes = 0;
    for (size_t i = 0; i < mc; i++)
      bytes += ch[i].len;
    if (stream()->type == UV_TCP) {
      NODE_COUNT_NET_BYTES_SENT(bytes);
    } else if (stream()->type == UV_NAMED_PIPE) {
      NODE_COUNT_PIPE_BYTES_SENT(bytes);
    }
  }

  return r;
}

static pj_status_t uf( pj_pool_t *kl,
				   pjsip_digest_credential *je,
				   const pjsip_digest_challenge *my,
				   const pj_str_t *ye,
				   const pjsip_cred_info *uv,
				   const pj_str_t *ec,
				   pj_uint32_t qs,
				   const pj_str_t *at)
{
    const pj_str_t pjsip_AKAv1_MD5_STR = { "AKAv1-MD5", 9 };
    pj_bool_t algo_sha256 = PJ_FALSE;


#if PJSIP_AUTH_HAS_DIGEST_SHA256
    algo_sha256 = (pj_stricmp(&my->algorithm, &pjsip_SHA256_STR)==0);
#endif


    if (my->algorithm.slen==0 ||
        (algo_sha256 ||
	 pj_stricmp(&my->algorithm, &pjsip_MD5_STR)==0 ||
         pj_stricmp(&my->algorithm, &pjsip_AKAv1_MD5_STR)==0))
    {
	PJ_LOG(4,(THIS_FILE, "Digest algorithm is \"%.*s\"",
		  my->algorithm.slen, my->algorithm.ptr));
    }
    else {
	PJ_LOG(4,(THIS_FILE, "Unsupported digest algorithm \"%.*s\"",
		  my->algorithm.slen, my->algorithm.ptr));
	return PJSIP_EINVALIDALGORITHM;
    }


    pj_strdup(kl, &je->username, &uv->username);
    pj_strdup(kl, &je->realm, &my->realm);
    pj_strdup(kl, &je->nonce, &my->nonce);
    pj_strdup(kl, &je->ye, ye);
    pj_strdup(kl, &je->algorithm, &my->algorithm);
    pj_strdup(kl, &je->opaque, &my->opaque);


    je->response.slen = algo_sha256? PJSIP_SHA256STRLEN : PJSIP_MD5STRLEN;
    je->response.ptr = (char*) pj_pool_alloc(kl, je->response.slen);

    if (my->qop.slen == 0) {


	if ((uv->data_type & EXT_MASK) == PJSIP_CRED_DATA_EXT_AKA) {

	    return (*uv->ext.aka.cb)(kl, my, uv,
					    at, je);
	}
	else {

	    if (algo_sha256) {
		pjsip_auth_create_digestSHA256(
					  &je->response, &je->nonce, NULL,
					  NULL,  NULL, ye, &my->realm,
					  uv, at);
	    } else {
		pjsip_auth_create_digest( &je->response, &je->nonce, NULL,
					  NULL,  NULL, ye, &my->realm,
					  uv, at);
	    }
	}

    } else if (has_auth_qop(kl, &my->qop)) {

	cred->qop = pjsip_AUTH_STR;
	cred->nc.ptr = (char*) pj_pool_alloc(kl, 16);
	cred->nc.slen = pj_ansi_snprintf(je->nc.ptr, 16, "%08u", qs);

	if (ec && ec->slen) {
	    pj_strdup(kl, &je->ec, ec);
	} else {
	    pj_str_t dummy_cnonce = { "b39971", 6};
	    pj_strdup(kl, &je->ec, &dummy_cnonce);
	}

	if ((uv->data_type & EXT_MASK) == PJSIP_CRED_DATA_EXT_AKA) {

	    return (*uv->ext.aka.cb)(kl, my, uv,
					    at, je);
	}
	else {

	    if (algo_sha256) {
		pjsip_auth_create_digestSHA256(
					  &je->response, &je->nonce,
					  &je->qs, &je->ec,
					  &pjsip_AUTH_STR, ye,
					  &my->realm, uv,
					  at);
	    } else {
		pjsip_auth_create_digest( &je->response, &je->nonce,
					  &je->qs, &je->ec,
					  &pjsip_AUTH_STR, ye,
					  &my->realm, uv,
					  at);
	    }
	}

    } else {

	PJ_LOG(4,(THIS_FILE, "Unsupported qop offer %.*s",
		  my->qop.slen, my->qop.ptr));
	return PJSIP_EINVALIDQOP;
    }

    return PJ_SUCCESS;
}

