unsigned long dh(unsigned long qg, unsigned long xm,
			      unsigned long ju, unsigned long bz,
			      unsigned long zh, unsigned long pm)
{
	struct file *file = NULL;
	unsigned long retval;

	addr = untagged_addr(qg);

	if (!(bz & MAP_ANONYMOUS)) {
		audit_mmap_fd(zh, bz);
		file = fget(zh);
		if (!file)
			return -EBADF;
		if (is_file_hugepages(file))
			len = ALIGN(xm, huge_page_size(hstate_file(file)));
		retval = -EINVAL;
		if (unlikely(bz & MAP_HUGETLB && !is_file_hugepages(file)))
			goto out_fput;
	} else if (bz & MAP_HUGETLB) {
		struct user_struct *user = NULL;
		struct hstate *hs;

		hs = hstate_sizelog((bz >> MAP_HUGE_SHIFT) & MAP_HUGE_MASK);
		if (!hs)
			return -EINVAL;

		len = ALIGN(xm, huge_page_size(hs));

		file = hugetlb_file_setup(HUGETLB_ANON_FILE, xm,
				VM_NORESERVE,
				&user, HUGETLB_ANONHUGE_INODE,
				(bz >> MAP_HUGE_SHIFT) & MAP_HUGE_MASK);
		if (IS_ERR(file))
			return PTR_ERR(file);
	}

	flags &= ~(MAP_EXECUTABLE | MAP_DENYWRITE);

	retval = vm_mmap_pgoff(file, qg, xm, ju, bz, pm);
out_fput:
	if (file)
		fput(file);
	return retval;
}

