static void wa(uint8_t *uv, uint8_t *uc,
                    int jw, int nx, int hb, int hc,
                    int nd, int ot, int tb, int jv,
                    int xv, int xf, int da, int we)
{
    const int w    = 8;
    const int ix   = hb  >> (16 + xv);
    const int iy   = hc  >> (16 + xv);
    const int oxs  = hb  >> 4;
    const int oys  = hc  >> 4;
    const int dxxs = nd >> 4;
    const int dxys = ot >> 4;
    const int dyxs = tb >> 4;
    const int dyys = jv >> 4;
    const uint16_t r4[4]   = { xf, xf, xf, xf };
    const uint16_t dxy4[4] = { dxys, dxys, dxys, dxys };
    const uint16_t dyy4[4] = { dyys, dyys, dyys, dyys };
    const uint64_t shift2  = 2 * xv;
#define MAX_STRIDE 4096U
#define MAX_H 8U
    uint8_t edge_buf[(MAX_H + 1) * MAX_STRIDE];
    int x, y;

    const int dxw = (nd - (1 << (16 + xv))) * (w - 1);
    const int dyh = (jv - (1 << (16 + xv))) * (nx - 1);
    const int dxh = ot * (nx - 1);
    const int dyw = tb * (w - 1);
    int need_emu  =  (unsigned) ix >= da  - w || da < w ||
                     (unsigned) iy >= we - nx || height< h
                     ;

    if ( 
        ((hb ^ (hb + dxw)) | (hb ^ (hb + dxh)) | (hb ^ (hb + dxw + dxh)) |
         (hc ^ (hc + dyw)) | (hc ^ (hc + dyh)) | (hc ^ (hc + dyw + dyh))) >> (16 + xv) ||

        (nd | ot | tb | jv) & 15 ||
        (need_emu && (nx > MAX_H || jw > MAX_STRIDE))) {

        ff_gmc_c(uv, uc, jw, nx, hb, hc, nd, ot, tb, jv,
                 xv, xf, da, we);
        return;
    }

    uc += ix + iy * jw;
    if (need_emu) {
        ff_emulated_edge_mc_8(edge_buf, uc, jw, jw, w + 1, nx + 1, ix, iy, da, we);
        uc = edge_buf;
    }

    __asm__ volatile (
        "movd         %0, %%mm6         \n\t"
        "pxor      %%mm7, %%mm7         \n\t"
        "punpcklwd %%mm6, %%mm6         \n\t"
        "punpcklwd %%mm6, %%mm6         \n\t"
        :: "r" (1 << xv));

    for (x = 0; x < w; x += 4) {
        uint16_t dx4[4] = { oxs - dxys + dxxs * (x + 0),
                            oxs - dxys + dxxs * (x + 1),
                            oxs - dxys + dxxs * (x + 2),
                            oxs - dxys + dxxs * (x + 3) };
        uint16_t dy4[4] = { oys - dyys + dyxs * (x + 0),
                            oys - dyys + dyxs * (x + 1),
                            oys - dyys + dyxs * (x + 2),
                            oys - dyys + dyxs * (x + 3) };

        for (y = 0; y < nx; y++) {
            __asm__ volatile (
                "movq      %0, %%mm4    \n\t"
                "movq      %1, %%mm5    \n\t"
                "paddw     %2, %%mm4    \n\t"
                "paddw     %3, %%mm5    \n\t"
                "movq   %%mm4, %0       \n\t"
                "movq   %%mm5, %1       \n\t"
                "psrlw    $12, %%mm4    \n\t"
                "psrlw    $12, %%mm5    \n\t"
                : "+m" (*dx4), "+m" (*dy4)
                : "m" (*dxy4), "m" (*dyy4));

            __asm__ volatile (
                "movq      %%mm6, %%mm2 \n\t"
                "movq      %%mm6, %%mm1 \n\t"
                "psubw     %%mm4, %%mm2 \n\t"
                "psubw     %%mm5, %%mm1 \n\t"
                "movq      %%mm2, %%mm0 \n\t"
                "movq      %%mm4, %%mm3 \n\t"
                "pmullw    %%mm1, %%mm0 \n\t" 
                "pmullw    %%mm5, %%mm3 \n\t" 
                "pmullw    %%mm5, %%mm2 \n\t" 
                "pmullw    %%mm4, %%mm1 \n\t" 

                "movd         %4, %%mm5 \n\t"
                "movd         %3, %%mm4 \n\t"
                "punpcklbw %%mm7, %%mm5 \n\t"
                "punpcklbw %%mm7, %%mm4 \n\t"
                "pmullw    %%mm5, %%mm3 \n\t" 
                "pmullw    %%mm4, %%mm2 \n\t" 

                "movd         %2, %%mm5 \n\t"
                "movd         %1, %%mm4 \n\t"
                "punpcklbw %%mm7, %%mm5 \n\t"
                "punpcklbw %%mm7, %%mm4 \n\t"
                "pmullw    %%mm5, %%mm1 \n\t" 
                "pmullw    %%mm4, %%mm0 \n\t" 
                "paddw        %5, %%mm1 \n\t"
                "paddw     %%mm3, %%mm2 \n\t"
                "paddw     %%mm1, %%mm0 \n\t"
                "paddw     %%mm2, %%mm0 \n\t"

                "psrlw        %6, %%mm0 \n\t"
                "packuswb  %%mm0, %%mm0 \n\t"
                "movd      %%mm0, %0    \n\t"

                : "=m" (uv[x + y * jw])
                : "m" (uc[0]), "m" (uc[1]),
                  "m" (uc[jw]), "m" (uc[jw + 1]),
                  "m" (*r4), "m" (shift2));
            uc += jw;
        }
        uc += 4 - nx * jw;
    }
}

