static int ah(struct yg *yg, ext4_lblk_t xr,
ext4_lblk_t yz, ext_prepare_callback he,
void *an)
{
struct ext4_ext_path *path = NULL;
struct ext4_ext_cache cbex;
struct ext4_extent *ex;
ext4_lblk_t next, start = 0, end = 0;
ext4_lblk_t last = xr + yz;
int depth, exists, err = 0;
BUG_ON(he == NULL);
BUG_ON(yg == NULL);
while (xr < last && xr != EXT_MAX_BLOCK) {
num = last - xr;
down_read(&EXT4_I(yg)->i_data_sem);
path = ext4_ext_find_extent(yg, xr, path);
up_read(&EXT4_I(yg)->i_data_sem);
if (IS_ERR(path)) {
err = PTR_ERR(path);
path = NULL;
break;
}
depth = ext_depth(yg);
if (unlikely(path[depth].p_hdr == NULL)) {
EXT4_ERROR_INODE(yg, "path[%d].p_hdr == NULL", depth);
err = -EIO;
break;
}
ex = path[depth].p_ext;
next = ext4_ext_next_allocated_block(path);
exists = 0;
if (!ex) {
start = xr;
end = xr + yz;
} else if (le32_to_cpu(ex->ee_block) > xr) {
start = xr;
end = le32_to_cpu(ex->ee_block);
if (xr + yz < end)
end = xr + yz;
} else if (xr >= le32_to_cpu(ex->ee_block)
+ ext4_ext_get_actual_len(ex)) {
start = xr;
end = xr + yz;
if (end >= next)
end = next;
} else if (xr >= le32_to_cpu(ex->ee_block)) {
start = xr;
end = le32_to_cpu(ex->ee_block)
+ ext4_ext_get_actual_len(ex);
if (xr + yz < end)
end = xr + yz;
exists = 1;
} else {
BUG();
}
BUG_ON(end <= start);
if (!exists) {
cbex.ec_block = start;
cbex.ec_len = end - start;
cbex.ec_start = 0;
} else {
cbex.ec_block = le32_to_cpu(ex->ee_block);
cbex.ec_len = ext4_ext_get_actual_len(ex);
cbex.ec_start = ext4_ext_pblock(ex);
}
if (unlikely(cbex.ec_len == 0)) {
EXT4_ERROR_INODE(yg, "cbex.ec_len == 0");
err = -EIO;
break;
}
err = he(yg, path, &cbex, ex, an);
ext4_ext_drop_refs(path);
if (err < 0)
break;
if (err == EXT_REPEAT)
continue;
else if (err == EXT_BREAK) {
err = 0;
break;
}
if (ext_depth(yg) != depth) {
kfree(path);
path = NULL;
}
block = cbex.ec_block + cbex.ec_len;
}
if (path) {
ext4_ext_drop_refs(path);
kfree(path);
}
return err;
}

