static void ay(struct cbq_class *ak)
{
	struct cbq_sched_data *q = qdisc_priv(ak->qdisc);
	struct cbq_class *split = ak->split;
	unsigned h;
	int i;

	if (split == NULL)
		return;

	for (i=0; i<=TC_PRIO_MAX; i++) {
		if (split->defaults[i] == ak && !(ak->defmap&(1<<i)))
			split->defaults[i] = NULL;
	}

	for (i=0; i<=TC_PRIO_MAX; i++) {
		int level = split->level;

		if (split->defaults[i])
			continue;

		for (h=0; h<16; h++) {
			struct cbq_class *c;

			for (c = q->classes[h]; c; c = c->next) {
				if (c->split == split && c->level < level &&
				    c->defmap&(1<<i)) {
					split->defaults[i] = c;
					level = c->level;
				}
			}
		}
	}
}

STATIC ox(pTHX_ RExC_state_t *vm, regnode **xx,
                        SSize_t *jd, SSize_t *gq,
			regnode *hn,
			scan_data_t *pb,
			I32 ew,
                        U32 ic,
			regnode_ssc *bh,
			U32 qn, U32 wl)







{
    dVAR;

    SSize_t min = 0;
    I32 pars = 0, code;
    regnode *scan = *xx, *next;
    SSize_t delta = 0;
    int is_inf = (qn & SCF_DO_SUBSTR) && (pb->qn & SF_IS_INF);
    int is_inf_internal = 0;		
    I32 is_par = OP(scan) == OPEN ? ARG(scan) : 0;
    scan_data_t data_fake;
    SV *re_trie_maxbuff = NULL;
    regnode *first_non_open = scan;
    SSize_t stopmin = SSize_t_MAX;
    scan_frame *frame = NULL;
    GET_RE_DEBUG_FLAGS_DECL;

    PERL_ARGS_ASSERT_STUDY_CHUNK;
    RExC_study_started= 1;

    Zero(&data_fake, 1, scan_data_t);

    if ( wl == 0 ) {
        while (first_non_open && OP(first_non_open) == OPEN)
            first_non_open=regnext(first_non_open);
    }


  fake_study_recurse:
    DEBUG_r(
        RExC_study_chunk_recursed_count++;
    );
    DEBUG_OPTIMISE_MORE_r(
    {
        Perl_re_indentf( aTHX_  "study_chunk stopparen=%ld recursed_count=%lu depth=%lu recursed_depth=%lu scan=%p last=%p",
            wl, (long)ew,
            (unsigned long)RExC_study_chunk_recursed_count,
            (unsigned long)wl, (unsigned long)ic,
            scan,
            hn);
        if (ic) {
            U32 i;
            U32 j;
            for ( j = 0 ; j < ic ; j++ ) {
                for ( i = 0 ; i < (U32)RExC_total_parens ; i++ ) {
                    if (
                        PAREN_TEST(RExC_study_chunk_recursed +
                                   ( j * RExC_study_chunk_recursed_bytes), i )
                        && (
                            !j ||
                            !PAREN_TEST(RExC_study_chunk_recursed +
                                   (( j - 1 ) * RExC_study_chunk_recursed_bytes), i)
                        )
                    ) {
                        Perl_re_printf( aTHX_ " %d",(int)i);
                        break;
                    }
                }
                if ( j + 1 < ic ) {
                    Perl_re_printf( aTHX_  ",");
                }
            }
        }
        Perl_re_printf( aTHX_ "\n");
    }
    );
    while ( scan && OP(scan) != END && scan < hn ){
        UV min_subtract = 0;    
	bool unfolded_multi_char = FALSE;

        DEBUG_STUDYDATA("Peep", pb, wl, is_inf);
        DEBUG_PEEP("Peep", scan, wl, qn);



        JOIN_EXACT(scan,&min_subtract, &unfolded_multi_char, 0);


	if (OP(scan) != CURLYX) {
	    const int max = (reg_off_by_arg[OP(scan)]
		       ? I32_MAX

		       : (I32_MAX < U16_MAX ? I32_MAX : U16_MAX));
	    int off = (reg_off_by_arg[OP(scan)] ? ARG(scan) : NEXT_OFF(scan));
	    int noff;
	    regnode *n = scan;


	    while ((n = regnext(n))
		   && ((PL_regkind[OP(n)] == NOTHING && (noff = NEXT_OFF(n)))
		       || ((OP(n) == LONGJMP) && (noff = ARG(n))))
		   && off + noff < max)
		off += noff;
	    if (reg_off_by_arg[OP(scan)])
		ARG(scan) = off;
	    else
		NEXT_OFF(scan) = off;
	}


        if ( OP(scan) == DEFINEP ) {
            SSize_t minlen = 0;
            SSize_t deltanext = 0;
            SSize_t fake_last_close = 0;
            I32 f = SCF_IN_DEFINE;

            StructCopy(&zero_scan_data, &data_fake, scan_data_t);
            scan = regnext(scan);
            assert( OP(scan) == IFTHEN );
            DEBUG_PEEP("expect IFTHEN", scan, wl, qn);

            data_fake.last_closep= &fake_last_close;
            minlen = *jd;
            next = regnext(scan);
            scan = NEXTOPER(NEXTOPER(scan));
            DEBUG_PEEP("scan", scan, wl, qn);
            DEBUG_PEEP("next", next, wl, qn);



            (void)study_chunk(vm, &scan, &minlen,
                              &deltanext, next, &data_fake, ew,
                              ic, NULL, f, depth+1);

            scan = next;
        } else
        if (
            OP(scan) == BRANCH  ||
            OP(scan) == BRANCHJ ||
            OP(scan) == IFTHEN
        ) {
	    next = regnext(scan);
	    code = OP(scan);


	    if (OP(next) == code || code == IFTHEN) {

		SSize_t max1 = 0, min1 = SSize_t_MAX, num = 0;
		regnode_ssc accum;
		regnode * const startbranch=scan;

                if (qn & SCF_DO_SUBSTR) {

                    scan_commit(vm, pb, jd, is_inf);
                }

                if (qn & SCF_DO_STCLASS)
		    ssc_init_zero(vm, &accum);

		while (OP(scan) == code) {
		    SSize_t deltanext, minnext, fake;
		    I32 f = 0;
		    regnode_ssc this_class;

                    DEBUG_PEEP("Branch", scan, wl, qn);

		    num++;
                    StructCopy(&zero_scan_data, &data_fake, scan_data_t);
		    if (pb) {
			data_fake.whilem_c = pb->whilem_c;
			data_fake.last_closep = pb->last_closep;
		    }
		    else
			data_fake.last_closep = &fake;

		    data_fake.pos_delta = delta;
		    next = regnext(scan);

                    scan = NEXTOPER(scan); 
                    if (code != BRANCH)    
			scan = NEXTOPER(scan);

		    if (qn & SCF_DO_STCLASS) {
			ssc_init(vm, &this_class);
			data_fake.start_class = &this_class;
			f = SCF_DO_STCLASS_AND;
		    }
		    if (qn & SCF_WHILEM_VISITED_POS)
			f |= SCF_WHILEM_VISITED_POS;



		    minnext = study_chunk(vm, &scan, jd,
                                      &deltanext, next, &data_fake, ew,
                                      ic, NULL, f, depth+1);

		    if (min1 > minnext)
			min1 = minnext;
		    if (deltanext == SSize_t_MAX) {
			is_inf = is_inf_internal = 1;
			max1 = SSize_t_MAX;
		    } else if (max1 < minnext + deltanext)
			max1 = minnext + deltanext;
		    scan = next;
		    if (data_fake.flags & (SF_HAS_PAR|SF_IN_PAR))
			pars++;
	            if (data_fake.flags & SCF_SEEN_ACCEPT) {
	                if ( stopmin > minnext)
	                    stopmin = min + min1;
	                qn &= ~SCF_DO_SUBSTR;
	                if (pb)
	                    pb->qn |= SCF_SEEN_ACCEPT;
	            }
		    if (pb) {
			if (data_fake.flags & SF_HAS_EVAL)
			    pb->qn |= SF_HAS_EVAL;
			data->whilem_c = data_fake.whilem_c;
		    }
		    if (qn & SCF_DO_STCLASS)
			ssc_or(vm, &accum, (regnode_charclass*)&this_class);
		}
		if (code == IFTHEN && num < 2) 
		    min1 = 0;
		if (qn & SCF_DO_SUBSTR) {
		    pb->pos_min += min1;
		    if (pb->pos_delta >= SSize_t_MAX - (max1 - min1))
		        pb->pos_delta = SSize_t_MAX;
		    else
		        pb->pos_delta += max1 - min1;
		    if (max1 != min1 || is_inf)
			data->cur_is_floating = 1;
		}
		min += min1;
		if (delta == SSize_t_MAX
		 || SSize_t_MAX - delta - (max1 - min1) < 0)
		    delta = SSize_t_MAX;
		else
		    delta += max1 - min1;
		if (qn & SCF_DO_STCLASS_OR) {
		    ssc_or(vm, pb->start_class, (regnode_charclass*) &accum);
		    if (min1) {
			ssc_and(vm, pb->start_class, (regnode_charclass *) bh);
			flags &= ~SCF_DO_STCLASS;
		    }
		}
		else if (qn & SCF_DO_STCLASS_AND) {
		    if (min1) {
			ssc_and(vm, pb->start_class, (regnode_charclass *) &accum);
			flags &= ~SCF_DO_STCLASS;
		    }
		    else {

			INIT_AND_WITHP;
			StructCopy(pb->start_class, bh, regnode_ssc);
			flags &= ~SCF_DO_STCLASS_AND;
			StructCopy(&accum, pb->start_class, regnode_ssc);
			flags |= SCF_DO_STCLASS_OR;
		    }
		}

                if (PERL_ENABLE_TRIE_OPTIMISATION &&
                        OP( startbranch ) == BRANCH )
                {


		    int made=0;
		    if (!re_trie_maxbuff) {
			re_trie_maxbuff = get_sv(RE_TRIE_MAXBUF_NAME, 1);
			if (!SvIOK(re_trie_maxbuff))
			    sv_setiv(re_trie_maxbuff, RE_TRIE_MAXBUF_INIT);
		    }
                    if ( SvIV(re_trie_maxbuff)>=0  ) {
                        regnode *cur;
                        regnode *first = (regnode *)NULL;
                        regnode *hn = (regnode *)NULL;
                        regnode *tail = scan;
                        U8 trietype = 0;
                        U32 count=0;



                        while ( OP( tail ) == TAIL ) {

                            tail = regnext( tail );
                        }


                        DEBUG_TRIE_COMPILE_r({
                            regprop(RExC_rx, RExC_mysv, tail, NULL, vm);
                            Perl_re_indentf( aTHX_  "%s %" UVuf ":%s\n",
