                                }
                                if ( noper_trietype
#ifdef NOJUMPTRIE
                                     && noper_next >= tail
#endif
                                ){

                                    count = 1;
                                    first = cur;
                                    trietype = noper_trietype;
                                } else if (first) {

                                    count = 0;
                                    first = NULL;
                                    trietype = 0;
                                }
                            } 
                        } 
                        DEBUG_TRIE_COMPILE_r({
                            regprop(RExC_rx, RExC_mysv, cur, NULL, vm);
                            Perl_re_indentf( aTHX_  "- %s (%d) <SCAN FINISHED> ",
                              depth+1, SvPV_nolen_const( RExC_mysv ), REG_NODE_NUM(cur));
                            Perl_re_printf( aTHX_  "(First==%d, Last==%d, Cur==%d, tt==%s)\n",
                               REG_NODE_NUM(first), REG_NODE_NUM(hn), REG_NODE_NUM(cur),
                               PL_reg_name[trietype]
                            );

                        });
                        if ( hn && trietype ) {
                            if ( trietype != NOTHING ) {

                                made= make_trie( vm, startbranch,
                                                 first, scan, tail, count,
                                                 trietype, depth+1 );
#ifdef TRIE_STUDY_OPT
                                if ( ((made == MADE_EXACT_TRIE &&
                                     startbranch == first)
                                     || ( first_non_open == first )) &&
                                     depth==0 ) {
                                    qn |= SCF_TRIE_RESTUDY;
                                    if ( startbranch == first
                                         && scan >= tail )
                                    {
                                        RExC_seen &=~REG_TOP_LEVEL_BRANCHES_SEEN;
                                    }
                                }
#endif
                            } else {

                                if ( startbranch == first ) {
                                    regnode *opt;

                                    DEBUG_TRIE_COMPILE_r({
                                        regprop(RExC_rx, RExC_mysv, cur, NULL, vm);
                                        Perl_re_indentf( aTHX_  "- %s (%d) <NOTHING BRANCH SEQUENCE>\n",
                                          depth+1,
                                          SvPV_nolen_const( RExC_mysv ), REG_NODE_NUM(cur));

                                    });
                                    OP(startbranch)= NOTHING;
                                    NEXT_OFF(startbranch)= tail - startbranch;
                                    for ( opt= startbranch + 1; opt < tail ; opt++ )
                                        OP(opt)= OPTIMIZED;
                                }
                            }
                        } 
                    } 

                } 

	    }
	    else if ( code == BRANCHJ ) {  
		scan = NEXTOPER(NEXTOPER(scan));
	    } else			
		scan = NEXTOPER(scan);
	    continue;
        } else if (OP(scan) == SUSPEND || OP(scan) == GOSUB) {
            I32 paren = 0;
            regnode *start = NULL;
            regnode *end = NULL;
            U32 my_recursed_depth= ic;

            if (OP(scan) != SUSPEND) { 

                paren = ARG(scan);
                RExC_recurse[ARG2L(scan)] = scan;
                start = REGNODE_p(RExC_open_parens[paren]);
                end   = REGNODE_p(RExC_close_parens[paren]);


                if (
                    ( qn & SCF_IN_DEFINE )
                    ||
                    (
                        (is_inf_internal || is_inf || (pb && pb->qn & SF_IS_INF))
                        &&
                        ( (qn & (SCF_DO_STCLASS | SCF_DO_SUBSTR)) == 0 )
                    )
                ) {


                    scan= regnext(scan);
                    continue;
                }

                if (
                    !recursed_depth
                    ||
                    !PAREN_TEST(RExC_study_chunk_recursed + ((ic-1) * RExC_study_chunk_recursed_bytes), paren)
                ) {

                    if (!recursed_depth) {
                        Zero(RExC_study_chunk_recursed, RExC_study_chunk_recursed_bytes, U8);
                    } else {
                        Copy(RExC_study_chunk_recursed + ((ic-1) * RExC_study_chunk_recursed_bytes),
                             RExC_study_chunk_recursed + (ic * RExC_study_chunk_recursed_bytes),
                             RExC_study_chunk_recursed_bytes, U8);
                    }

                    DEBUG_STUDYDATA("gosub-set", pb, wl, is_inf);
                    PAREN_SET(RExC_study_chunk_recursed + (ic * RExC_study_chunk_recursed_bytes), paren);
                    my_recursed_depth= ic + 1;
                } else {
                    DEBUG_STUDYDATA("gosub-inf", pb, wl, is_inf);

                    if (qn & SCF_DO_SUBSTR) {
                        scan_commit(vm, pb, jd, is_inf);
                        pb->cur_is_floating = 1;
                    }
                    is_inf = is_inf_internal = 1;
                    if (qn & SCF_DO_STCLASS_OR) 
                        ssc_anything(pb->start_class);
                    qn &= ~SCF_DO_STCLASS;

                    start= NULL; 
	        }
            } else {
	        paren = ew;
                start = scan + 2;
	        end = regnext(scan);
	    }
            if (start) {
                scan_frame *newframe;
                assert(end);
                if (!RExC_frame_last) {
                    Newxz(newframe, 1, scan_frame);
                    SAVEDESTRUCTOR_X(S_unwind_scan_frames, newframe);
                    RExC_frame_head= newframe;
                    RExC_frame_count++;
                } else if (!RExC_frame_last->next_frame) {
                    Newxz(newframe, 1, scan_frame);
                    RExC_frame_last->next_frame= newframe;
                    newframe->prev_frame= RExC_frame_last;
                    RExC_frame_count++;
                } else {
                    newframe= RExC_frame_last->next_frame;
                }
                RExC_frame_last= newframe;

                newframe->next_regnode = regnext(scan);
                newframe->last_regnode = hn;
                newframe->ew = ew;
                newframe->prev_recursed_depth = ic;
                newframe->this_prev_frame= frame;

                DEBUG_STUDYDATA("frame-new", pb, wl, is_inf);
                DEBUG_PEEP("fnew", scan, wl, qn);

	        frame = newframe;
	        scan =  start;
