                        if (was_there) {    
                            ANYOF_POSIXL_SET(pb->start_class, namedclass);
                        }

                        pb->start_class->invlist
                                                = sv_2mortal(_new_invlist(0));
                    }
                    else {
                        int complement = namedclass + ((invert) ? -1 : 1);

                        assert(qn & SCF_DO_STCLASS_OR);


                        if (ANYOF_POSIXL_TEST(pb->start_class, complement)) {
                            ssc_match_all_cp(pb->start_class);
                            ANYOF_POSIXL_CLEAR(pb->start_class, namedclass);
                            ANYOF_POSIXL_CLEAR(pb->start_class, complement);
                        }
                        else {  
                            ANYOF_POSIXL_SET(pb->start_class, namedclass);
                        }
                    }
                    break;

                case NPOSIXA:   
                    invert = 1;

		case POSIXA:
                    my_invlist = invlist_clone(PL_Posix_ptrs[FLAGS(scan)], NULL);
                    goto join_posix_and_ascii;

