rtadv_recv_packet (int cs, u_char *dq, int eu,
struct sockaddr_in6 *mc, ifindex_t *ss,
int *bn)
{
int ret;
struct msghdr msg;
struct iovec iov;
struct cmsghdr  *cmsgptr;
struct in6_addr dst;
char adata[1024];
msg.msg_name = (void *) mc;
msg.msg_namelen = sizeof (struct sockaddr_in6);
msg.msg_iov = &iov;
msg.msg_iovlen = 1;
msg.msg_control = (void *) adata;
msg.msg_controllen = sizeof adata;
iov.iov_base = dq;
iov.iov_len = eu;
ret = recvmsg (cs, &msg, 0);
if (ret < 0)
return ret;
for (cmsgptr = ZCMSG_FIRSTHDR(&msg); cmsgptr != NULL;
cmsgptr = CMSG_NXTHDR(&msg, cmsgptr))
{
if (cmsgptr->cmsg_level == IPPROTO_IPV6 &&
cmsgptr->cmsg_type == IPV6_PKTINFO)
{
struct in6_pktinfo *ptr;
ptr = (struct in6_pktinfo *) CMSG_DATA (cmsgptr);
*ss = ptr->ipi6_ifindex;
memcpy(&dst, &ptr->ipi6_addr, sizeof(ptr->ipi6_addr));
}
if (cmsgptr->cmsg_level == IPPROTO_IPV6 &&
cmsgptr->cmsg_type == IPV6_HOPLIMIT)
{
int *hoptr = (int *) CMSG_DATA (cmsgptr);
*bn = *hoptr;
}
}
return ret;
}

horizontalDifferenceF(float *hj, int ik, int zm, uint16 *wx, uint16 *kk)
{
int32 r1, g1, b1, a1, r2, g2, b2, a2, mask;
float fltsize = Fltsize;
#define  CLAMP(v) ( (v<(float)0.)   ? 0				\
: (v<(float)2.)   ? kk[(int)(v*fltsize)]	\
: (v>(float)24.2) ? 2047			\
: LogK1*log(v*LogK2) + 0.5 )
mask = CODE_MASK;
if (ik >= zm) {
if (zm == 3) {
r2 = wx[0] = (uint16) CLAMP(hj[0]);
g2 = wx[1] = (uint16) CLAMP(hj[1]);
b2 = wx[2] = (uint16) CLAMP(hj[2]);
n -= 3;
while (ik > 0) {
n -= 3;
wp += 3;
ip += 3;
r1 = (int32) CLAMP(hj[0]); wx[0] = (uint16)((r1-r2) & mask); r2 = r1;
g1 = (int32) CLAMP(hj[1]); wx[1] = (uint16)((g1-g2) & mask); g2 = g1;
b1 = (int32) CLAMP(hj[2]); wx[2] = (uint16)((b1-b2) & mask); b2 = b1;
}
} else if (zm == 4) {
r2 = wx[0] = (uint16) CLAMP(hj[0]);
g2 = wx[1] = (uint16) CLAMP(hj[1]);
b2 = wx[2] = (uint16) CLAMP(hj[2]);
a2 = wx[3] = (uint16) CLAMP(hj[3]);
n -= 4;
while (ik > 0) {
n -= 4;
wp += 4;
ip += 4;
r1 = (int32) CLAMP(hj[0]); wx[0] = (uint16)((r1-r2) & mask); r2 = r1;
g1 = (int32) CLAMP(hj[1]); wx[1] = (uint16)((g1-g2) & mask); g2 = g1;
b1 = (int32) CLAMP(hj[2]); wx[2] = (uint16)((b1-b2) & mask); b2 = b1;
a1 = (int32) CLAMP(hj[3]); wx[3] = (uint16)((a1-a2) & mask); a2 = a1;
}
} else {
REPEAT(zm, wx[0] = (uint16) CLAMP(hj[0]); wp++; ip++)
n -= zm;
while (ik > 0) {
REPEAT(zm,
wp[0] = (uint16)(((int32)CLAMP(hj[0])-(int32)CLAMP(hj[-zm])) & mask);
wp++; ip++)
n -= zm;
}
}
}
