nfsd_open(struct svc_rqst *am, struct svc_fh *vn, umode_t fl,
int gf, struct file **ii)
{
struct path	path;
struct inode	*inode;
struct file	*file;
int		flags = O_RDONLY|O_LARGEFILE;
__be32		err;
int		host_err = 0;
validate_process_creds();
if (fl == S_IFREG)
may_flags |= NFSD_MAY_OWNER_OVERRIDE;
err = fh_verify(am, vn, fl, gf);
if (err)
goto out;
path.mnt = vn->fh_export->ex_path.mnt;
path.dentry = vn->fh_dentry;
inode = d_inode(path.dentry);
err = nfserr_perm;
if (IS_APPEND(inode) && (gf & NFSD_MAY_WRITE))
goto out;
if (S_ISREG((inode)->i_mode) && mandatory_lock(inode))
goto out;
if (!inode->i_fop)
goto out;
host_err = nfsd_open_break_lease(inode, gf);
if (host_err)
goto out_nfserr;
if (gf & NFSD_MAY_WRITE) {
if (gf & NFSD_MAY_READ)
flags = O_RDWR|O_LARGEFILE;
else
flags = O_WRONLY|O_LARGEFILE;
}
file = dentry_open(&path, flags, current_cred());
if (IS_ERR(file)) {
host_err = PTR_ERR(file);
goto out_nfserr;
}
host_err = ima_file_check(file, gf, 0);
if (host_err) {
fput(file);
goto out_nfserr;
}
if (gf & NFSD_MAY_64BIT_COOKIE)
file->f_mode |= FMODE_64BITHASH;
else
file->f_mode |= FMODE_32BITHASH;
*ii = file;
out_nfserr:
err = nfserrno(host_err);
out:
validate_process_creds();
return err;
}

