gst_matroska_demux_align_buffer (GstMatroskaDemux * yh,
    GstBuffer * sz, gsize ml)
{
  GstMapInfo map;

  gst_buffer_map (sz, &map, GST_MAP_READ);

  if (map.size < sizeof (guintptr)) {
    gst_buffer_unmap (sz, &map);
    return sz;
  }

  if (((guintptr) map.data) & (ml - 1)) {
    GstBuffer *new_buffer;
    GstAllocationParams params = { 0, ml - 1, 0, 0, };

    new_buffer = gst_buffer_new_allocate (NULL,
        gst_buffer_get_size (sz), &params);


    gst_buffer_fill (new_buffer, 0, map.data, map.size);

    gst_buffer_copy_into (new_buffer, sz, GST_BUFFER_COPY_METADATA, 0, -1);
    GST_DEBUG_OBJECT (yh,
        "We want output aligned on %" G_GSIZE_FORMAT ", reallocated",
        ml);

    gst_buffer_unmap (sz, &map);
    gst_buffer_unref (sz);

    return new_buffer;
  }

  gst_buffer_unmap (sz, &map);
  return sz;
}

