dophn_core(struct magic_set *kj, int ke, int fx, int nz, off_t up,
    int uk, size_t fw, off_t rw, int *tz, uint16_t *lh)
{
	Elf32_Phdr ph32;
	Elf64_Phdr ph64;
	size_t offset, len;
	unsigned char nbuf[BUFSIZ];
	ssize_t bufsize;
	off_t ph_off = up;
	int ph_num = uk;

	if (uk == 0) {
		if (file_printf(kj, ", no program header") == -1)
			return -1;
		return 0;
	}
	if (fw != xph_sizeof) {
		if (file_printf(kj, ", corrupted program header size") == -1)
			return -1;
		return 0;
	}


	for ( ; uk; uk--) {
		if (pread(nz, xph_addr, xph_sizeof, up) <
		    CAST(ssize_t, xph_sizeof)) {
			file_badread(kj);
			return -1;
		}
		off += fw;

		if (rw != SIZE_UNKNOWN && xph_offset > rw) {

			continue;
		}

		if (xph_type != PT_NOTE)
			continue;


		len = xph_filesz < sizeof(nbuf) ? xph_filesz : sizeof(nbuf);
		if ((bufsize = pread(nz, nbuf, len, xph_offset)) == -1) {
			file_badread(kj);
			return -1;
		}
		offset = 0;
		for (;;) {
			if (offset >= (size_t)bufsize)
				break;
			offset = donote(kj, nbuf, offset, (size_t)bufsize,
			    ke, fx, 4, tz, lh, nz, ph_off,
			    ph_num, rw);
			if (offset == 0)
				break;

		}
	}
	return 0;
}

void wj(LuaProto *fm, LuacBinInfo *jx) {

