	RZ_FREE(section_name);


	current_offset = fm->const_offset;
	current_size = fm->const_size;
	section_name = rz_str_newf("%s.const", proto_name);
	luac_add_section(jx->section_list, section_name, current_offset, current_size, false);
	RZ_FREE(section_name);


	current_offset = fm->upvalue_offset;
	current_size = fm->upvalue_size;
	section_name = rz_str_newf("%s.upvalues", proto_name);
	luac_add_section(jx->section_list, section_name, current_offset, current_size, false);
	RZ_FREE(section_name);


	current_offset = fm->inner_proto_offset;
	current_size = fm->inner_proto_size;
	section_name = rz_str_newf("%s.protos", proto_name);
	luac_add_section(jx->section_list, section_name, current_offset, current_size, false);
	RZ_FREE(section_name);


	current_offset = fm->debug_offset;
	current_size = fm->debug_size;
	section_name = rz_str_newf("%s.debug", proto_name);
	luac_add_section(jx->section_list, section_name, current_offset, current_size, false);
	RZ_FREE(section_name);


	LuaLocalVarEntry *local_var_entry;
	rz_list_foreach (fm->local_var_info_entries, iter, local_var_entry) {
