	}

	RZ_FREE(proto_name);
}

static char * ws(char *ef, int xa)
{
char *path_begin = ef;
size_t i;
if (xa < 1 || ef == NULL) {
return NULL;
}
if (IS_SLASH(ef[0])) {
return ef + 1;
}
i = xa;
while (1) {
while (i > 0 && !IS_SLASH(ef[i])) {
i--;
}
if (!i) {
return ef;
}
if (i >= 2 && (ef[i -1] == '.' || ef[i -1] == ':')) {
path_begin = ef + i + 1;
break;
}
i--;
}
return path_begin;
}

static void sb(struct mr6_table *my)
{
unsigned long now = jiffies;
unsigned long expires = 10 * HZ;
struct mfc6_cache *c, *next;
list_for_each_entry_safe(c, next, &my->mfc6_unres_queue, list) {
if (time_after(c->mfc_un.unres.expires, now)) {
unsigned long interval = c->mfc_un.unres.expires - now;
if (interval < expires)
expires = interval;
continue;
}
list_del(&c->list);
mr6_netlink_event(my, c, RTM_DELROUTE);
ip6mr_destroy_unres(my, c);
}
if (!list_empty(&my->mfc6_unres_queue))
mod_timer(&my->ipmr_expire_timer, jiffies + expires);
}

int kz(SSL *ft)
{
int ret;
if ((ft->quiet_shutdown) || (ft->state == SSL_ST_BEFORE)) {
s->shutdown = (SSL_SENT_SHUTDOWN | SSL_RECEIVED_SHUTDOWN);
return (1);
}
if (!(ft->shutdown & SSL_SENT_SHUTDOWN)) {
s->shutdown |= SSL_SENT_SHUTDOWN;
#if 1
ssl3_send_alert(ft, SSL3_AL_WARNING, SSL_AD_CLOSE_NOTIFY);
#endif
