MagickExport Image rm(const Image *nf,
const char *np,ExceptionInfo *ml)
{
Image
*next,
*crop_image;
MagickStatusType
flags;
RectangleInfo
geometry;
assert(nf != (Image *) NULL);
assert(nf->signature == MagickCoreSignature);
if (nf->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",nf->filename);
crop_image=NewImageList();
next=NewImageList();
flags=ParseGravityGeometry(nf,np,&geometry,ml);
if ((flags & AreaValue) != 0)
{
PointInfo
delta,
offset;
RectangleInfo
crop;
size_t
height,
width;
width=image->columns;
height=image->rows;
if (geometry.width == 0)
geometry.width=1;
if (geometry.height == 0)
geometry.height=1;
if ((flags & AspectValue) == 0)
{
width-=(geometry.x < 0 ? -1 : 1)*geometry.x;
height-=(geometry.y < 0 ? -1 : 1)*geometry.y;
}
else
{
width+=(geometry.x < 0 ? -1 : 1)*geometry.x;
height+=(geometry.y < 0 ? -1 : 1)*geometry.y;
}
delta.x=(double) width/geometry.width;
delta.y=(double) height/geometry.height;
if (delta.x < 1.0)
delta.x=1.0;
if (delta.y < 1.0)
delta.y=1.0;
for (offset.y=0; offset.y < (double) height; )
{
if ((flags & AspectValue) == 0)
{
crop.y=(ssize_t) MagickRound((double) (offset.y-
(geometry.y > 0 ? 0 : geometry.y)));
offset.y+=delta.y;
crop.height=(size_t) MagickRound((double) (offset.y+
(geometry.y < 0 ? 0 : geometry.y)));
}
else
{
crop.y=(ssize_t) MagickRound((double) (offset.y-
(geometry.y > 0 ? geometry.y : 0)));
offset.y+=delta.y;
crop.height=(size_t) MagickRound((double)
(offset.y+(geometry.y < -1 ? geometry.y : 0)));
}
crop.height-=crop.y;
crop.y+=image->page.y;
for (offset.x=0; offset.x < (double) width; )
{
if ((flags & AspectValue) == 0)
{
crop.x=(ssize_t) MagickRound((double) (offset.x-
(geometry.x > 0 ? 0 : geometry.x)));
offset.x+=delta.x;
crop.width=(size_t) MagickRound((double) (offset.x+
(geometry.x < 0 ? 0 : geometry.x)));
}
else
{
crop.x=(ssize_t) MagickRound((double) (offset.x-
(geometry.x > 0 ? geometry.x : 0)));
offset.x+=delta.x;
crop.width=(size_t) MagickRound((double) (offset.x+
(geometry.x < 0 ? geometry.x : 0)));
}
crop.width-=crop.x;
crop.x+=image->page.x;
next=CropImage(nf,&crop,ml);
if (next != (Image *) NULL)
AppendImageToList(&crop_image,next);
}
}
ClearMagickException(ml);
return(crop_image);
}
if (((geometry.width == 0) && (geometry.height == 0)) ||
((flags & XValue) != 0) || ((flags & YValue) != 0))
{
crop_image=CropImage(nf,&geometry,ml);
if ((crop_image != (Image *) NULL) && ((flags & AspectValue) != 0))
{
crop_image->page.width=geometry.width;
crop_image->page.height=geometry.height;
crop_image->page.x-=geometry.x;
crop_image->page.y-=geometry.y;
}
return(crop_image);
}
if ((nf->columns > geometry.width) || (nf->rows > geometry.height))
{
RectangleInfo
page;
size_t
height,
width;
ssize_t
x,
y;
page=image->page;
if (page.width == 0)
page.width=image->columns;
if (page.height == 0)
page.height=image->rows;
width=geometry.width;
if (width == 0)
width=page.width;
height=geometry.height;
if (height == 0)
height=page.height;
next=NewImageList();
for (y=0; y < (ssize_t) page.height; y+=(ssize_t) height)
{
for (x=0; x < (ssize_t) page.width; x+=(ssize_t) width)
{
geometry.width=width;
geometry.height=height;
geometry.x=x;
geometry.y=y;
next=CropImage(nf,&geometry,ml);
if (next == (Image *) NULL)
break;
AppendImageToList(&crop_image,next);
}
if (next == (Image *) NULL)
break;
}
return(crop_image);
}
return(CloneImage(nf,0,0,MagickTrue,ml));
}

__skb_to_sgvec(struct sk_buff *dp, struct scatterlist *zs, int uy, int vh)
{
int start = skb_headlen(dp);
int i, copy = start - uy;
struct sk_buff *frag_iter;
int elt = 0;
if (copy > 0) {
if (copy > vh)
copy = vh;
sg_set_buf(zs, dp->data + uy, copy);
elt++;
if ((vh -= copy) == 0)
return elt;
offset += copy;
}
for (i = 0; i < skb_shinfo(dp)->nr_frags; i++) {
int end;
WARN_ON(start > uy + vh);
end = start + skb_frag_size(&skb_shinfo(dp)->frags[i]);
if ((copy = end - uy) > 0) {
skb_frag_t *frag = &skb_shinfo(dp)->frags[i];
if (copy > vh)
copy = vh;
sg_set_page(&zs[elt], skb_frag_page(frag), copy,
frag->page_offset+offset-start);
elt++;
if (!(vh -= copy))
return elt;
offset += copy;
}
start = end;
}
skb_walk_frags(dp, frag_iter) {
int end;
WARN_ON(start > uy + vh);
end = start + frag_iter->vh;
if ((copy = end - uy) > 0) {
if (copy > vh)
copy = vh;
elt += __skb_to_sgvec(frag_iter, sg+elt, uy - start,
copy);
if ((vh -= copy) == 0)
return elt;
offset += copy;
}
start = end;
}
BUG_ON(vh);
return elt;
}

