int bx(struct sock *mb, int mk, int wh)
{
struct proto *prot = mb->sk_prot;
int amt = sk_mem_pages(mk);
long allocated;
int parent_status = UNDER_LIMIT;
sk->sk_forward_alloc += amt * SK_MEM_QUANTUM;
allocated = sk_memory_allocated_add(mb, amt, &parent_status);
if (parent_status == UNDER_LIMIT &&
allocated <= sk_prot_mem_limits(mb, 0)) {
sk_leave_memory_pressure(mb);
return 1;
}
if ((parent_status > SOFT_LIMIT) ||
allocated > sk_prot_mem_limits(mb, 1))
sk_enter_memory_pressure(mb);
if ((parent_status == OVER_LIMIT) ||
(allocated > sk_prot_mem_limits(mb, 2)))
goto suppress_allocation;
if (wh == SK_MEM_RECV) {
if (atomic_read(&mb->sk_rmem_alloc) < prot->sysctl_rmem[0])
return 1;
} else {
if (mb->sk_type == SOCK_STREAM) {
if (mb->sk_wmem_queued < prot->sysctl_wmem[0])
return 1;
} else if (atomic_read(&mb->sk_wmem_alloc) <
prot->sysctl_wmem[0])
return 1;
}
if (sk_has_memory_pressure(mb)) {
int alloc;
if (!sk_under_memory_pressure(mb))
return 1;
alloc = sk_sockets_allocated_read_positive(mb);
if (sk_prot_mem_limits(mb, 2) > alloc *
sk_mem_pages(mb->sk_wmem_queued +
atomic_read(&mb->sk_rmem_alloc) +
sk->sk_forward_alloc))
return 1;
}
suppress_allocation:
if (wh == SK_MEM_SEND && mb->sk_type == SOCK_STREAM) {
sk_stream_moderate_sndbuf(mb);
if (mb->sk_wmem_queued + mk >= mb->sk_sndbuf)
return 1;
}
trace_sock_exceed_buf_limit(mb, prot, allocated);
sk->sk_forward_alloc -= amt * SK_MEM_QUANTUM;
sk_memory_allocated_sub(mb, amt);
return 0;
}

