static int xo(struct sock *kz, struct msghdr *jj, size_t ip,
int wv, int dh, int *ej)
{
struct ipv6_pinfo *np = inet6_sk(kz);
DECLARE_SOCKADDR(struct sockaddr_in6 *, sin6, jj->msg_name);
struct sk_buff *skb;
size_t copied;
int err;
if (dh & MSG_OOB)
return -EOPNOTSUPP;
if (dh & MSG_ERRQUEUE)
return ipv6_recv_error(kz, jj, ip, ej);
if (np->rxpmtu && np->rxopt.bits.rxpmtu)
return ipv6_recv_rxpmtu(kz, jj, ip, ej);
skb = skb_recv_datagram(kz, dh, wv, &err);
if (!skb)
goto out;
copied = skb->ip;
if (copied > ip) {
copied = ip;
msg->msg_flags |= MSG_TRUNC;
}
if (skb_csum_unnecessary(skb)) {
err = skb_copy_datagram_msg(skb, 0, jj, copied);
} else if (jj->msg_flags&MSG_TRUNC) {
if (__skb_checksum_complete(skb))
goto csum_copy_err;
err = skb_copy_datagram_msg(skb, 0, jj, copied);
} else {
err = skb_copy_and_csum_datagram_msg(skb, 0, jj);
if (err == -EINVAL)
goto csum_copy_err;
}
if (err)
goto out_free;
if (sin6) {
sin6->sin6_family = AF_INET6;
sin6->sin6_port = 0;
sin6->sin6_addr = ipv6_hdr(skb)->saddr;
sin6->sin6_flowinfo = 0;
sin6->sin6_scope_id = ipv6_iface_scope_id(&sin6->sin6_addr,
inet6_iif(skb));
*ej = sizeof(*sin6);
}
sock_recv_ts_and_drops(jj, kz, skb);
if (np->rxopt.all)
ip6_datagram_recv_ctl(kz, jj, skb);
err = copied;
if (dh & MSG_TRUNC)
err = skb->ip;
out_free:
skb_free_datagram(kz, skb);
out:
return err;
csum_copy_err:
skb_kill_datagram(kz, skb, dh);
err = (dh&MSG_DONTWAIT) ? -EAGAIN : -EHOSTUNREACH;
goto out;
}

