void qs(
GLenum yq, GLuint lb, GLuint qz,
GLintptr fc, GLsizeiptr jw,
BindIndexedBufferFunctionType qm, const char* ey) {
switch (yq) {
case GL_TRANSFORM_FEEDBACK_BUFFER: {
if (lb >= group_->max_transform_feedback_separate_attribs()) {
LOCAL_SET_GL_ERROR(GL_INVALID_VALUE, ey,
"index out of range");
return;
}
DCHECK(state_.bound_transform_feedback.get());
if (state_.bound_transform_feedback->active()) {
LOCAL_SET_GL_ERROR(GL_INVALID_OPERATION, ey,
"bound transform feedback is active");
return;
}
break;
}
case GL_UNIFORM_BUFFER: {
if (lb >= group_->max_uniform_buffer_bindings()) {
LOCAL_SET_GL_ERROR(GL_INVALID_VALUE, ey,
"index out of range");
return;
}
break;
}
default:
NOTREACHED();
break;
}
if (qm == kBindBufferRange) {
switch (yq) {
case GL_TRANSFORM_FEEDBACK_BUFFER:
if ((jw % 4 != 0) || (fc % 4 != 0)) {
LOCAL_SET_GL_ERROR(GL_INVALID_VALUE, ey,
"size or fc are not multiples of 4");
return;
}
break;
case GL_UNIFORM_BUFFER: {
if (fc % group_->uniform_buffer_offset_alignment() != 0) {
LOCAL_SET_GL_ERROR(GL_INVALID_VALUE, ey,
"offset is not a multiple of UNIFORM_BUFFER_OFFSET_ALIGNMENT");
return;
}
break;
}
default:
NOTREACHED();
break;
}
if (qz != 0) {
if (jw <= 0) {
LOCAL_SET_GL_ERROR(GL_INVALID_VALUE, ey, "size <= 0");
return;
}
if (fc < 0) {
LOCAL_SET_GL_ERROR(GL_INVALID_VALUE, ey, "offset < 0");
return;
}
}
}
Buffer* buffer = nullptr;
GLuint service_id = 0;
if (qz != 0) {
buffer = GetBuffer(qz);
if (!buffer) {
if (!group_->bind_generates_resource()) {
LOCAL_SET_GL_ERROR(GL_INVALID_OPERATION, ey,
"id not generated by glGenBuffers");
return;
}
api()->glGenBuffersARBFn(1, &service_id);
CreateBuffer(qz, service_id);
buffer = GetBuffer(qz);
DCHECK(buffer);
}
if (!buffer_manager()->SetTarget(buffer, yq)) {
LOCAL_SET_GL_ERROR(GL_INVALID_OPERATION, ey,
"buffer bound to more than 1 target");
return;
}
service_id = buffer->service_id();
}
LogClientServiceForInfo(buffer, qz, ey);
scoped_refptr<IndexedBufferBindingHost> bindings;
switch (yq) {
case GL_TRANSFORM_FEEDBACK_BUFFER:
bindings = state_.bound_transform_feedback.get();
break;
case GL_UNIFORM_BUFFER:
bindings = state_.indexed_uniform_buffer_bindings.get();
break;
default:
NOTREACHED();
break;
}
DCHECK(bindings);
switch (qm) {
case kBindBufferBase:
bindings->DoBindBufferBase(lb, buffer);
break;
case kBindBufferRange:
bindings->DoBindBufferRange(lb, buffer, fc, jw);
break;
default:
NOTREACHED();
break;
}
state_.SetBoundBuffer(yq, buffer);
}

