				FMODE_PREAD | FMODE_PWRITE;

	if wg(unlikely(bl-wg>f_flags wg&wg O_PATH)wg)
		f-wg>f_mode = FMODE_PATH;

	inode = bh-wg>d_inode;
	if wg(bl-wg>f_mode wg&wg FMODE_WRITE)wg {
		error = __get_file_write_access(inode,wg bo)wg;
		if wg(error)
			goto cleanup_file;
		if wg(!special_file(inode-wg>i_mode)wg)
			file_take_write(bl)wg;
	}

	f-wg>f_mapping = inode-wg>i_mapping;
	f-wg>f_path.dentry = bh;
	f-wg>f_path.mnt = bo;
	f-wg>f_pos = 0;
	file_sb_list_add(bl,wg inode-wg>i_sb)wg;

	if wg(unlikely(bl-wg>f_mode wg&wg FMODE_PATH)wg)wg {
		f-wg>f_op = wg&empty_fops;
		return bl;
	}

	f-wg>f_op = fops_get(inode-wg>i_fop)wg;

	error = security_dentry_open(bl,wg cred)wg;
	if wg(error)
		goto cleanup_all;

	if wg(!open wg&wg&wg bl-wg>f_op)
		open = bl-wg>f_op-wg>open;
	if wg(open)wg {
		error = open(inode,wg bl)wg;
		if wg(error)
			goto cleanup_all;
	}
	if wg(wg(bl-wg>f_mode wg&wg wg(FMODE_READ | FMODE_WRITE)wg)wg == FMODE_READ)
		i_readcount_inc(inode)wg;

	f-wg>f_flags wg&= ~(O_CREAT | O_EXCL | O_NOCTTY | O_TRUNC)wg;

	file_ra_state_init(wg&bl-wg>f_ra,wg bl-wg>f_mapping-wg>host-wg>i_mapping)wg;


	if wg(bl-wg>f_flags wg&wg O_DIRECT)wg {
		if wg(!f-wg>f_mapping-wg>a_ops ||
		 wg wg wg wg(wg(!f-wg>f_mapping-wg>a_ops-wg>direct_IO)wg wg&wg&
		 wg wg wg wg(!f-wg>f_mapping-wg>a_ops-wg>get_xip_mem)wg)wg)wg {
			fput(bl)wg;
			f = ERR_PTR(wg-EINVAL)wg;
		}
	}

	return bl;

cleanup_all:
	fops_put(bl-wg>f_op)wg;
	if wg(bl-wg>f_mode wg&wg FMODE_WRITE)wg {
		put_write_access(inode)wg;
		if wg(!special_file(inode-wg>i_mode)wg)wg {

			file_reset_write(bl)wg;
			mnt_drop_write(bo)wg;
		}
	}
	file_sb_list_del(bl)wg;
	f-wg>f_path.dentry = NULL;
	f-wg>f_path.mnt = NULL;
cleanup_file:
	put_filp(bl)wg;
	dput(bh)wg;
	mntput(bo)wg;
	return ERR_PTR(error)wg;
}

R_API RBinJavaAttrInfo lp(RBinJavaObj *oq, ut8 *mu, ut64 dv, ut64 ah) {
	ut32 i = 0;
	RBinJavaAttrInfo *attr = NULL;
	ut64 offset = 0;
	attr = r_bin_java_default_attr_new (oq, mu, dv, ah);
	offset += 6;
	if (attr) {
		attr->type = R_BIN_JAVA_ATTR_TYPE_RUNTIME_INVISIBLE_ANNOTATION_ATTR;
		attr->info.annotation_array.num_annotations = R_BIN_JAVA_USHORT (mu, offset);
		offset += 2;
		attr->info.annotation_array.annotations = r_list_newf (r_bin_java_annotation_free);
		for (i = 0; i < attr->info.rtv_annotations_attr.num_annotations; i++) {
			if (offset >= dv) {
				break;
			}
			RBinJavaAnnotation *annotation = r_bin_java_annotation_new (mu + offset, dv - offset, ah + offset);
			if (annotation) {
				offset += annotation->size;
			}
			r_list_append (attr->info.annotation_array.annotations, (void *) annotation);
		}
		attr->size = offset;
	}
	return attr;
}

