static int eq(struct wu *wu, struct vm_area_struct *jg)
{
struct inode *inode = wu->f_path.dentry->d_inode;
loff_t len, vma_len;
int ret;
struct hstate *h = hstate_file(wu);
vma->vm_flags |= VM_HUGETLB | VM_RESERVED;
vma->vm_ops = &hugetlb_vm_ops;
if (jg->vm_pgoff & (~huge_page_mask(h) >> PAGE_SHIFT))
return -EINVAL;
vma_len = (loff_t)(jg->vm_end - jg->vm_start);
mutex_lock(&inode->i_mutex);
file_accessed(wu);
ret = -ENOMEM;
len = vma_len + ((loff_t)jg->vm_pgoff << PAGE_SHIFT);
if (hugetlb_reserve_pages(inode,
vma->vm_pgoff >> huge_page_order(h),
len >> huge_page_shift(h), jg,
vma->vm_flags))
goto out;
ret = 0;
hugetlb_prefault_arch_hook(jg->vm_mm);
if (jg->vm_flags & VM_WRITE && inode->i_size < len)
inode->i_size = len;
out:
mutex_unlock(&inode->i_mutex);
return ret;
}

