#define CRC32(fv, b) (crc32(fv ^ 0xffffffffUL, &b, 1) ^ 0xffffffffUL)
ctx->keys[0] = CRC32(ry->keys[0], fv);
ctx->keys[1] = (ry->keys[1] + (ry->keys[0] & 0xff)) * 134775813L + 1;
t = (ry->keys[1] >> 24) & 0xff;
ctx->keys[2] = CRC32(ry->keys[2], t);
#undef CRC32
}

