static int oe(jpc_bitstream_t *ns)
{
int n;
if ((n = jpc_bitstream_getbit(ns)) > 0) {
if ((n = jpc_bitstream_getbit(ns)) > 0) {
if ((n = jpc_bitstream_getbits(ns, 2)) == 3) {
if ((n = jpc_bitstream_getbits(ns, 5)) == 31) {
if ((n = jpc_bitstream_getbits(ns, 7)) >= 0) {
n += 36 + 1;
}
} else if (n >= 0) {
n += 5 + 1;
}
} else if (n >= 0) {
n += 2 + 1;
}
} else if (!n) {
n += 2;
}
} else if (!n) {
++n;
}
return n;
}

