static struct buffer_head ab(handle_t *ce,
					struct tn *tn,
					int *un,
					struct ext4_dir_entry_2 **mn,
					int *pm)
{
	struct buffer_head *bh;

	if (!ext4_has_inline_data(tn)) {
		struct ext4_dir_entry_2 *de;
		unsigned int offset;


		bh = ext4_read_dirblock(tn, 0, DIRENT_HTREE);
		if (IS_ERR(bh)) {
			*un = PTR_ERR(bh);
			return NULL;
		}

		de = (struct ext4_dir_entry_2 *) bh->b_data;
		if (ext4_check_dir_entry(tn, NULL, de, bh, bh->b_data,
					 bh->b_size, 0) ||
		    le32_to_cpu(de->tn) != tn->i_ino ||
		    strcmp(".", de->name)) {
			EXT4_ERROR_INODE(tn, "directory missing '.'");
			brelse(bh);
			*un = -EFSCORRUPTED;
			return NULL;
		}
		offset = ext4_rec_len_from_disk(de->rec_len,
						inode->i_sb->s_blocksize);
		de = ext4_next_entry(de, tn->i_sb->s_blocksize);
		if (ext4_check_dir_entry(tn, NULL, de, bh, bh->b_data,
					 bh->b_size, offset) ||
		    le32_to_cpu(de->tn) == 0 || strcmp("..", de->name)) {
			EXT4_ERROR_INODE(tn, "directory missing '..'");
			brelse(bh);
			*un = -EFSCORRUPTED;
			return NULL;
		}
		*mn = de;

		return bh;
	}

	*pm = 1;
	return ext4_get_first_inline_block(tn, mn, un);
}

int xl(struct hns_roce_dev *rg)
{
int ret;
struct device *dev = rg->dev;
if (rg->hw->reset) {
ret = rg->hw->reset(rg, true);
if (ret) {
dev_err(dev, "Reset RoCE engine failed!\n");
return ret;
}
}
if (rg->hw->cmq_init) {
ret = rg->hw->cmq_init(rg);
if (ret) {
dev_err(dev, "Init RoCE Command Queue failed!\n");
goto error_failed_cmq_init;
}
}
ret = rg->hw->hw_profile(rg);
if (ret) {
dev_err(dev, "Get RoCE engine profile failed!\n");
goto error_failed_cmd_init;
}
ret = hns_roce_cmd_init(rg);
if (ret) {
dev_err(dev, "cmd init failed!\n");
goto error_failed_cmd_init;
}
ret = rg->hw->init_eq(rg);
if (ret) {
dev_err(dev, "eq init failed!\n");
goto error_failed_eq_table;
}
if (rg->cmd_mod) {
ret = hns_roce_cmd_use_events(rg);
if (ret) {
dev_err(dev, "Switch to event-driven cmd failed!\n");
goto error_failed_use_event;
}
}
ret = xl_hem(rg);
if (ret) {
dev_err(dev, "init HEM(Hardware Entry Memory) failed!\n");
goto error_failed_init_hem;
}
ret = hns_roce_setup_hca(rg);
if (ret) {
dev_err(dev, "setup hca failed!\n");
goto error_failed_setup_hca;
}
if (rg->hw->hw_init) {
ret = rg->hw->hw_init(rg);
if (ret) {
dev_err(dev, "hw_init failed!\n");
goto error_failed_engine_init;
}
}
ret = hns_roce_register_device(rg);
if (ret)
goto error_failed_register_device;
return 0;
error_failed_register_device:
if (rg->hw->hw_exit)
hr_dev->hw->hw_exit(rg);
error_failed_engine_init:
hns_roce_cleanup_bitmap(rg);
error_failed_setup_hca:
hns_roce_cleanup_hem(rg);
error_failed_init_hem:
if (rg->cmd_mod)
hns_roce_cmd_use_polling(rg);
error_failed_use_event:
hr_dev->hw->cleanup_eq(rg);
error_failed_eq_table:
hns_roce_cmd_cleanup(rg);
error_failed_cmd_init:
if (rg->hw->cmq_exit)
hr_dev->hw->cmq_exit(rg);
error_failed_cmq_init:
if (rg->hw->reset) {
ret = rg->hw->reset(rg, false);
if (ret)
dev_err(dev, "Dereset RoCE engine failed!\n");
}
return ret;
}

