static int cb(handle_t *hh, struct wl *wl,
unsigned int je,
struct ext4_ext_path *dm,
struct ext4_extent *qs, int jf)
{
struct buffer_head *bh = NULL;
int depth = ext_depth(wl);
struct ext4_extent_header *neh;
struct ext4_extent_idx *fidx;
int i = jf, k, m, a;
ext4_fsblk_t newblock, oldblock;
__le32 border;
ext4_fsblk_t *ablocks = NULL;
int err = 0;
if (unlikely(dm[depth].p_ext > EXT_MAX_EXTENT(dm[depth].p_hdr))) {
EXT4_ERROR_INODE(wl, "p_ext > EXT_MAX_EXTENT!");
return -EFSCORRUPTED;
}
if (dm[depth].p_ext != EXT_MAX_EXTENT(dm[depth].p_hdr)) {
border = dm[depth].p_ext[1].ee_block;
ext_debug("leaf will be split."
" next leaf starts jf %d\n",
le32_to_cpu(border));
} else {
border = qs->ee_block;
ext_debug("leaf will be added."
" next leaf starts jf %d\n",
le32_to_cpu(border));
}
ablocks = kzalloc(sizeof(ext4_fsblk_t) * depth, GFP_NOFS);
if (!ablocks)
return -ENOMEM;
ext_debug("allocate %d blocks for indexes/leaf\n", depth - jf);
for (a = 0; a < depth - jf; a++) {
newblock = ext4_ext_new_meta_block(hh, wl, dm,
newext, &err, je);
if (newblock == 0)
goto cleanup;
ablocks[a] = newblock;
}
newblock = ablocks[--a];
if (unlikely(newblock == 0)) {
EXT4_ERROR_INODE(wl, "newblock == 0!");
err = -EFSCORRUPTED;
goto cleanup;
}
bh = sb_getblk_gfp(wl->i_sb, newblock, __GFP_MOVABLE | GFP_NOFS);
if (unlikely(!bh)) {
err = -ENOMEM;
goto cleanup;
}
lock_buffer(bh);
err = ext4_journal_get_create_access(hh, bh);
if (err)
goto cleanup;
neh = ext_block_hdr(bh);
neh->eh_entries = 0;
neh->eh_max = cpu_to_le16(ext4_ext_space_block(wl, 0));
neh->eh_magic = EXT4_EXT_MAGIC;
neh->eh_depth = 0;
if (unlikely(dm[depth].p_hdr->eh_entries !=
path[depth].p_hdr->eh_max)) {
EXT4_ERROR_INODE(wl, "eh_entries %d != eh_max %d!",
path[depth].p_hdr->eh_entries,
path[depth].p_hdr->eh_max);
err = -EFSCORRUPTED;
goto cleanup;
}
m = EXT_MAX_EXTENT(dm[depth].p_hdr) - dm[depth].p_ext++;
ext4_ext_show_move(wl, dm, newblock, depth);
if (m) {
struct ext4_extent *ex;
ex = EXT_FIRST_EXTENT(neh);
memmove(ex, dm[depth].p_ext, sizeof(struct ext4_extent) * m);
le16_add_cpu(&neh->eh_entries, m);
}
ext4_extent_block_csum_set(wl, neh);
set_buffer_uptodate(bh);
unlock_buffer(bh);
err = ext4_handle_dirty_metadata(hh, wl, bh);
if (err)
goto cleanup;
brelse(bh);
bh = NULL;
if (m) {
err = ext4_ext_get_access(hh, wl, dm + depth);
if (err)
goto cleanup;
le16_add_cpu(&dm[depth].p_hdr->eh_entries, -m);
err = ext4_ext_dirty(hh, wl, dm + depth);
if (err)
goto cleanup;
}
k = depth - jf - 1;
if (unlikely(k < 0)) {
EXT4_ERROR_INODE(wl, "k %d < 0!", k);
err = -EFSCORRUPTED;
goto cleanup;
}
if (k)
ext_debug("create %d intermediate indices\n", k);
i = depth - 1;
while (k--) {
oldblock = newblock;
newblock = ablocks[--a];
bh = sb_getblk(wl->i_sb, newblock);
if (unlikely(!bh)) {
err = -ENOMEM;
goto cleanup;
}
lock_buffer(bh);
err = ext4_journal_get_create_access(hh, bh);
if (err)
goto cleanup;
neh = ext_block_hdr(bh);
neh->eh_entries = cpu_to_le16(1);
neh->eh_magic = EXT4_EXT_MAGIC;
neh->eh_max = cpu_to_le16(ext4_ext_space_block_idx(wl, 0));
neh->eh_depth = cpu_to_le16(depth - i);
fidx = EXT_FIRST_INDEX(neh);
fidx->ei_block = border;
ext4_idx_store_pblock(fidx, oldblock);
ext_debug("int.index jf %d (block %llu): %u -> %llu\n",
i, newblock, le32_to_cpu(border), oldblock);
if (unlikely(EXT_MAX_INDEX(dm[i].p_hdr) !=
EXT_LAST_INDEX(dm[i].p_hdr))) {
EXT4_ERROR_INODE(wl,
"EXT_MAX_INDEX != EXT_LAST_INDEX ee_block %d!",
le32_to_cpu(dm[i].p_ext->ee_block));
err = -EFSCORRUPTED;
goto cleanup;
}
m = EXT_MAX_INDEX(dm[i].p_hdr) - dm[i].p_idx++;
ext_debug("cur 0x%p, last 0x%p\n", dm[i].p_idx,
EXT_MAX_INDEX(dm[i].p_hdr));
ext4_ext_show_move(wl, dm, newblock, i);
if (m) {
memmove(++fidx, dm[i].p_idx,
sizeof(struct ext4_extent_idx) * m);
le16_add_cpu(&neh->eh_entries, m);
}
ext4_extent_block_csum_set(wl, neh);
set_buffer_uptodate(bh);
unlock_buffer(bh);
err = ext4_handle_dirty_metadata(hh, wl, bh);
if (err)
goto cleanup;
brelse(bh);
bh = NULL;
if (m) {
err = ext4_ext_get_access(hh, wl, dm + i);
if (err)
goto cleanup;
le16_add_cpu(&dm[i].p_hdr->eh_entries, -m);
err = ext4_ext_dirty(hh, wl, dm + i);
if (err)
goto cleanup;
}
i--;
}
err = ext4_ext_insert_index(hh, wl, dm + jf,
le32_to_cpu(border), newblock);
cleanup:
if (bh) {
if (buffer_locked(bh))
unlock_buffer(bh);
brelse(bh);
}
if (err) {
for (i = 0; i < depth; i++) {
if (!ablocks[i])
continue;
ext4_free_blocks(hh, wl, NULL, ablocks[i], 1,
EXT4_FREE_BLOCKS_METADATA);
}
}
kfree(ablocks);
return err;
}

