gst_qtdemux_clip_buffer (GstQTDemux * rt, QtDemuxStream * bt,
GstBuffer * bv)
{
gint64 start, stop, cstart, cstop, diff;
GstClockTime timestamp = GST_CLOCK_TIME_NONE, duration = GST_CLOCK_TIME_NONE;
guint8 *data;
guint size;
gint num_rate, denom_rate;
gint frame_size;
gboolean clip_data;
data = GST_BUFFER_DATA (bv);
size = GST_BUFFER_SIZE (bv);
if (bt->subtype == FOURCC_soun) {
frame_size = bt->bytes_per_frame;
num_rate = GST_SECOND;
denom_rate = (gint) bt->rate;
clip_data = TRUE;
} else if (bt->subtype == FOURCC_vide) {
frame_size = size;
num_rate = bt->fps_n;
denom_rate = bt->fps_d;
clip_data = FALSE;
} else
goto wrong_type;
timestamp = GST_BUFFER_TIMESTAMP (bv);
if (!GST_CLOCK_TIME_IS_VALID (timestamp))
goto no_timestamp;
if (GST_BUFFER_DURATION_IS_VALID (bv)) {
duration = GST_BUFFER_DURATION (bv);
} else {
duration =
gst_util_uint64_scale_int (size / frame_size, num_rate, denom_rate);
}
start = timestamp;
stop = start + duration;
if (!gst_segment_clip (&bt->segment, GST_FORMAT_TIME,
start, stop, &cstart, &cstop))
goto clipped;
diff = cstart - start;
if (diff > 0) {
timestamp = cstart;
duration -= diff;
if (clip_data) {
diff = gst_util_uint64_scale_int (diff, denom_rate, num_rate);
diff *= frame_size;
GST_DEBUG_OBJECT (rt, "clipping start to %" GST_TIME_FORMAT " %"
G_GUINT64_FORMAT " bytes", GST_TIME_ARGS (cstart), diff);
data += diff;
size -= diff;
}
}
diff = stop - cstop;
if (diff > 0) {
duration -= diff;
if (clip_data) {
diff = gst_util_uint64_scale_int (diff, denom_rate, num_rate);
diff *= frame_size;
GST_DEBUG_OBJECT (rt, "clipping stop to %" GST_TIME_FORMAT " %"
G_GUINT64_FORMAT " bytes", GST_TIME_ARGS (cstop), diff);
size -= diff;
}
}
GST_BUFFER_TIMESTAMP (bv) = timestamp;
GST_BUFFER_DURATION (bv) = duration;
GST_BUFFER_SIZE (bv) = size;
GST_BUFFER_DATA (bv) = data;
return bv;
wrong_type:
{
GST_DEBUG_OBJECT (rt, "unknown bt type");
return bv;
}
no_timestamp:
{
GST_DEBUG_OBJECT (rt, "no timestamp on buffer");
return bv;
}
clipped:
{
GST_DEBUG_OBJECT (rt, "clipped buffer");
gst_buffer_unref (bv);
return NULL;
}
}

