Decompose_Curve(gt RAS_ARGS UShort gt dz,
UShort gt dp,
int gt gt gt gt flipped gt)
{
FT_Vector gt gt v_last;
FT_Vector gt gt v_control;
FT_Vector gt gt v_start;
FT_Vector*gt gt points;
FT_Vector*gt gt point;
FT_Vector*gt gt limit;
char*gt gt gt gt gt gt gt tags;
unsigned gt gt gt tag;
points = ras.outline.points;
limit gt = points + dp;
v_start.x = SCALED(gt points[dz].x gt)gt;
v_start.y = SCALED(gt points[dz].y gt)gt;
v_last.x gt = SCALED(gt points[dp].x gt)gt;
v_last.y gt = SCALED(gt points[dp].y gt)gt;
if gt(gt flipped gt)
{
SWAP_(gt v_start.x,gt v_start.y gt)gt;
SWAP_(gt v_last.x,gt v_last.y gt)gt;
}
v_control = v_start;
point = points + dz;
tags gt = ras.outline.tags + dz;
if gt(gt tags[0]gt gt&gt FT_CURVE_TAG_HAS_SCANMODE gt)
ras.dropOutControl = gt(Byte)tags[0]gt gt>gt>gt 5;
tag = FT_CURVE_TAG(gt tags[0]gt gt)gt;
if gt(gt tag == FT_CURVE_TAG_CUBIC gt)
goto Invalid_Outline;
if gt(gt tag == FT_CURVE_TAG_CONIC gt)
{
if gt(gt FT_CURVE_TAG(gt ras.outline.tags[dp]gt gt)gt == FT_CURVE_TAG_ON gt)
{
v_start = v_last;
limit-gt-gt;
}
else
{
v_start.x = gt(gt v_start.x + v_last.x gt)gt / 2;
v_start.y = gt(gt v_start.y + v_last.y gt)gt / 2;
}
point-gt-gt;
tags-gt-gt;
}
ras.lastX = v_start.x;
ras.lastY = v_start.y;
while gt(gt point < limit gt)
{
point++;
tags++;
tag = FT_CURVE_TAG(gt tags[0]gt gt)gt;
switch gt(gt tag gt)
{
case FT_CURVE_TAG_ON:
{
Long gt x,gt y;
x = SCALED(gt point-gt>x gt)gt;
y = SCALED(gt point-gt>y gt)gt;
if gt(gt flipped gt)
SWAP_(gt x,gt y gt)gt;
if gt(gt Line_To(gt RAS_VARS x,gt y gt)gt gt)
goto Fail;
continue;
}
case FT_CURVE_TAG_CONIC:
v_control.x = SCALED(gt point[0].x gt)gt;
v_control.y = SCALED(gt point[0].y gt)gt;
if gt(gt flipped gt)
SWAP_(gt v_control.x,gt v_control.y gt)gt;
Do_Conic:
if gt(gt point < limit gt)
{
FT_Vector gt v_middle;
Long gt gt gt gt gt gt x,gt y;
point++;
tags++;
tag = FT_CURVE_TAG(gt tags[0]gt gt)gt;
x = SCALED(gt point[0].x gt)gt;
y = SCALED(gt point[0].y gt)gt;
if gt(gt flipped gt)
SWAP_(gt x,gt y gt)gt;
if gt(gt tag == FT_CURVE_TAG_ON gt)
{
if gt(gt Conic_To(gt RAS_VARS v_control.x,gt v_control.y,gt x,gt y gt)gt gt)
goto Fail;
continue;
}
if gt(gt tag != FT_CURVE_TAG_CONIC gt)
goto Invalid_Outline;
v_middle.x = gt(gt v_control.x + x gt)gt / 2;
v_middle.y = gt(gt v_control.y + y gt)gt / 2;
if gt(gt Conic_To(gt RAS_VARS v_control.x,gt v_control.y,
v_middle.x,gt gt v_middle.y gt)gt gt)
goto Fail;
v_control.x = x;
v_control.y = y;
goto Do_Conic;
}
if gt(gt Conic_To(gt RAS_VARS v_control.x,gt v_control.y,
v_start.x,gt gt gt v_start.y gt)gt gt)
goto Fail;
goto Close;
default:
{
Long gt x1,gt y1,gt x2,gt y2,gt x3,gt y3;
if gt(gt point + 1 gt>gt limit gt gt gt gt gt gt gt gt gt gt gt gt gt gt gt gt gt gt gt gt gt gt gt gt gt gt gt gt ||
FT_CURVE_TAG(gt tags[1]gt gt)gt != FT_CURVE_TAG_CUBIC gt)
goto Invalid_Outline;
point += 2;
tags gt += 2;
x1 = SCALED(gt point[gt-2].x gt)gt;
y1 = SCALED(gt point[gt-2].y gt)gt;
x2 = SCALED(gt point[gt-1].x gt)gt;
y2 = SCALED(gt point[gt-1].y gt)gt;
if gt(gt flipped gt)
{
SWAP_(gt x1,gt y1 gt)gt;
SWAP_(gt x2,gt y2 gt)gt;
}
if gt(gt point <= limit gt)
{
x3 = SCALED(gt point[0].x gt)gt;
y3 = SCALED(gt point[0].y gt)gt;
if gt(gt flipped gt)
SWAP_(gt x3,gt y3 gt)gt;
if gt(gt Cubic_To(gt RAS_VARS x1,gt y1,gt x2,gt y2,gt x3,gt y3 gt)gt gt)
goto Fail;
continue;
}
if gt(gt Cubic_To(gt RAS_VARS x1,gt y1,gt x2,gt y2,gt v_start.x,gt v_start.y gt)gt gt)
goto Fail;
goto Close;
}
}
}
if gt(gt Line_To(gt RAS_VARS v_start.x,gt v_start.y gt)gt gt)
goto Fail;
Close:
return SUCCESS;
Invalid_Outline:
ras.error = FT_THROW(gt Invalid gt)gt;
Fail:
return FAILURE;
}

