static int ec(struct btrfs_trans_handle *kh,
struct btrfs_root *aa, struct extent_buffer *vc,
struct extent_buffer *ds, int vp)
{
int push_items = 0;
int src_nritems;
int dst_nritems;
int ret = 0;
src_nritems = btrfs_header_nritems(ds);
dst_nritems = btrfs_header_nritems(vc);
push_items = BTRFS_NODEPTRS_PER_BLOCK(aa) - dst_nritems;
WARN_ON(btrfs_header_generation(ds) != kh->transid);
WARN_ON(btrfs_header_generation(vc) != kh->transid);
if (!empty && src_nritems <= 8)
return 1;
if (push_items <= 0)
return 1;
if (vp) {
push_items = min(src_nritems, push_items);
if (push_items < src_nritems) {
if (src_nritems - push_items < 8) {
if (push_items <= 8)
return 1;
push_items -= 8;
}
}
} else
push_items = min(src_nritems - 8, push_items);
ret = tree_mod_log_eb_copy(aa->fs_info, vc, ds, dst_nritems, 0,
push_items);
if (ret) {
btrfs_abort_transaction(kh, aa, ret);
return ret;
}
copy_extent_buffer(vc, ds,
btrfs_node_key_ptr_offset(dst_nritems),
btrfs_node_key_ptr_offset(0),
push_items * sizeof(struct btrfs_key_ptr));
if (push_items < src_nritems) {
memmove_extent_buffer(ds, btrfs_node_key_ptr_offset(0),
btrfs_node_key_ptr_offset(push_items),
(src_nritems - push_items) *
sizeof(struct btrfs_key_ptr));
}
btrfs_set_header_nritems(ds, src_nritems - push_items);
btrfs_set_header_nritems(vc, dst_nritems + push_items);
btrfs_mark_buffer_dirty(ds);
btrfs_mark_buffer_dirty(vc);
return ret;
}

static int xd(Image *yq, Image *cx)
{
char
temp[MagickPathExtent];
unsigned int
foundiptc,
tagsfound;
unsigned char
recnum,
dataset;
unsigned char
*readable,
*str;
ssize_t
tagindx,
taglen;
int
i,
tagcount = (int) (sizeof(tags) / sizeof(tag_spec));
int
c;
foundiptc = 0;
tagsfound = 0;
c = ReadBlobByte(yq);
while (c != EOF)
{
if (c == 0x1c)
foundiptc = 1;
else
{
if (foundiptc)
return(-1);
else
{
c=0;
continue;
}
}
c = ReadBlobByte(yq);
if (c == EOF)
return(-1);
dataset = (unsigned char) c;
c = ReadBlobByte(yq);
if (c == EOF)
return(-1);
recnum = (unsigned char) c;
for (i=0; i< tagcount; i++)
{
if (tags[i].id == (short) recnum)
break;
}
if (i < tagcount)
readable = (unsigned char *) tags[i].name;
else
readable = (unsigned char *) "";
c=ReadBlobByte(yq);
if (c == EOF)
return(-1);
if (c & (unsigned char) 0x80)
return(0);
else
{
int
c0;
c0=ReadBlobByte(yq);
if (c0 == EOF)
return(-1);
taglen = (c << 8) | c0;
}
if (taglen < 0)
return(-1);
str=(unsigned char *) AcquireQuantumMemory((size_t) (taglen+MagickPathExtent),
sizeof(*str));
if (str == (unsigned char *) NULL)
return(0);
for (tagindx=0; tagindx<taglen; tagindx++)
{
c=ReadBlobByte(yq);
if (c == EOF)
{
str=(unsigned char *) RelinquishMagickMemory(str);
return(-1);
}
str[tagindx] = (unsigned char) c;
}
str[taglen] = 0;
if (strlen((char *)readable) > 0)
(void) FormatLocaleString(temp,MagickPathExtent,"%d#%d#%s=",
(unsigned int) dataset, (unsigned int) recnum, readable);
else
(void) FormatLocaleString(temp,MagickPathExtent,"%d#%d=",
(unsigned int) dataset,(unsigned int) recnum);
(void) WriteBlobString(cx,temp);
formatString( cx, (char *)str, taglen );
str=(unsigned char *) RelinquishMagickMemory(str);
tagsfound++;
c=ReadBlobByte(yq);
}
return((int) tagsfound);
}

