static int dn(struct kvm_vcpu_hv_synic *lt,
			 u32 av, u64 xe, bool pp)
{
	struct kvm_vcpu *vcpu = hv_synic_to_vcpu(lt);
	int ret;

	if (!synic->active && !host)
		return 1;

	trace_kvm_hv_dn(vcpu->vcpu_id, av, xe, pp);

	ret = 0;
	switch (av) {
	case HV_X64_MSR_SCONTROL:
		synic->control = xe;
		if (!host)
			synic_exit(lt, av);
		break;
	case HV_X64_MSR_SVERSION:
		if (!host) {
			ret = 1;
			break;
		}
		synic->version = xe;
		break;
	case HV_X64_MSR_SIEFP:
		if ((xe & HV_SYNIC_SIEFP_ENABLE) && !host &&
		    !synic->dont_zero_synic_pages)
			if (kvm_clear_guest(vcpu->kvm,
					    xe & PAGE_MASK, PAGE_SIZE)) {
				ret = 1;
				break;
			}
		synic->evt_page = xe;
		if (!host)
			synic_exit(lt, av);
		break;
	case HV_X64_MSR_SIMP:
		if ((xe & HV_SYNIC_SIMP_ENABLE) && !host &&
		    !synic->dont_zero_synic_pages)
			if (kvm_clear_guest(vcpu->kvm,
					    xe & PAGE_MASK, PAGE_SIZE)) {
				ret = 1;
				break;
			}
		synic->msg_page = xe;
		if (!host)
			synic_exit(lt, av);
		break;
	case HV_X64_MSR_EOM: {
		int i;

		for (i = 0; i < ARRAY_SIZE(lt->sint); i++)
			kvm_hv_notify_acked_sint(vcpu, i);
		break;
	}
	case HV_X64_MSR_SINT0 ... HV_X64_MSR_SINT15:
		ret = synic_set_sint(lt, av - HV_X64_MSR_SINT0, xe, pp);
		break;
	default:
		ret = 1;
		break;
	}
	return ret;
}

