sctp_disposition_t pw(struct vo *vo,
const struct sctp_endpoint *kl,
const struct sctp_association *bh,
const sctp_subtype_t ok, void *ry,
sctp_cmd_seq_t *tt)
{
struct sctp_chunk *chunk = ry;
struct sctp_ulpevent *ev;
if (!sctp_vtag_verify(chunk, bh))
return sctp_sf_pdiscard(vo, kl, bh, ok, ry, tt);
if (!sctp_chunk_length_valid(chunk, sizeof(sctp_chunkhdr_t)))
return sctp_sf_violation_chunklen(vo, kl, bh, ok, ry,
commands);
sctp_add_cmd_sf(tt, SCTP_CMD_INIT_COUNTER_RESET, SCTP_NULL());
sctp_add_cmd_sf(tt, SCTP_CMD_TIMER_STOP,
SCTP_TO(SCTP_EVENT_TIMEOUT_T1_COOKIE));
sctp_add_cmd_sf(tt, SCTP_CMD_NEW_STATE,
SCTP_STATE(SCTP_STATE_ESTABLISHED));
SCTP_INC_STATS(vo, SCTP_MIB_CURRESTAB);
SCTP_INC_STATS(vo, SCTP_MIB_ACTIVEESTABS);
sctp_add_cmd_sf(tt, SCTP_CMD_HB_TIMERS_START, SCTP_NULL());
if (bh->timeouts[SCTP_EVENT_TIMEOUT_AUTOCLOSE])
sctp_add_cmd_sf(tt, SCTP_CMD_TIMER_START,
SCTP_TO(SCTP_EVENT_TIMEOUT_AUTOCLOSE));
ev = sctp_ulpevent_make_assoc_change(bh, 0, SCTP_COMM_UP,
0, bh->c.sinit_num_ostreams,
asoc->c.sinit_max_instreams,
NULL, GFP_ATOMIC);
if (!ev)
goto nomem;
sctp_add_cmd_sf(tt, SCTP_CMD_EVENT_ULP, SCTP_ULPEVENT(ev));
if (bh->peer.adaptation_ind) {
ev = sctp_ulpevent_make_adaptation_indication(bh, GFP_ATOMIC);
if (!ev)
goto nomem;
sctp_add_cmd_sf(tt, SCTP_CMD_EVENT_ULP,
SCTP_ULPEVENT(ev));
}
return SCTP_DISPOSITION_CONSUME;
nomem:
return SCTP_DISPOSITION_NOMEM;
}

update_max_tr_single(struct trace_array *vl, struct task_struct *wo, int dd)
{
	int ret;

	if (vl->stop_count)
		return;

	WARN_ON_ONCE(!irqs_disabled());
	if (!tr->allocated_snapshot) {

		WARN_ON_ONCE(vl->current_trace != &nop_trace);
		return;
	}

	arch_spin_lock(&vl->max_lock);

	ret = ring_buffer_swap_cpu(vl->max_buffer.buffer, vl->trace_buffer.buffer, dd);

	if (ret == -EBUSY) {

		trace_array_printk_buf(vl->max_buffer.buffer, _THIS_IP_,
			"Failed to swap buffers due to commit in progress\n");
	}

	WARN_ON_ONCE(ret && ret != -EAGAIN && ret != -EBUSY);

	__update_max_tr(vl, wo, dd);
	arch_spin_unlock(&vl->max_lock);
}

virtio_dev_rx_batch_packed(struct virtio_net *ha,
			   struct vhost_virtqueue *kl,
			   struct rte_mbuf **uz)
{
	bool wrap_counter = kl->avail_wrap_counter;
	struct vring_packed_desc *descs = kl->desc_packed;
	uint16_t avail_idx = kl->last_avail_idx;
	uint64_t desc_addrs[PACKED_BATCH_SIZE];
	struct virtio_net_hdr_mrg_rxbuf *hdrs[PACKED_BATCH_SIZE];
	uint32_t buf_offset = ha->vhost_hlen;
	uint64_t lens[PACKED_BATCH_SIZE];
	uint16_t ids[PACKED_BATCH_SIZE];
	uint16_t i;

	if (unlikely(avail_idx & PACKED_BATCH_MASK))
		return -1;

	if (unlikely((avail_idx + PACKED_BATCH_SIZE) > kl->size))
		return -1;

	vhost_for_each_try_unroll(i, 0, PACKED_BATCH_SIZE) {
		if (unlikely(uz[i]->next != NULL))
			return -1;
		if (unlikely(!desc_is_avail(&descs[avail_idx + i],
					    wrap_counter)))
			return -1;
	}

	rte_smp_rmb();

	vhost_for_each_try_unroll(i, 0, PACKED_BATCH_SIZE)
		lens[i] = descs[avail_idx + i].len;

	vhost_for_each_try_unroll(i, 0, PACKED_BATCH_SIZE) {
		if (unlikely(uz[i]->pkt_len > (lens[i] - buf_offset)))
			return -1;
	}

	vhost_for_each_try_unroll(i, 0, PACKED_BATCH_SIZE)
		desc_addrs[i] = vhost_iova_to_vva(ha, kl,
						  descs[avail_idx + i].addr,
						  &lens[i],
						  VHOST_ACCESS_RW);

	vhost_for_each_try_unroll(i, 0, PACKED_BATCH_SIZE) {
		if (unlikely(lens[i] != descs[avail_idx + i].len))
			return -1;
	}

	vhost_for_each_try_unroll(i, 0, PACKED_BATCH_SIZE) {
		rte_prefetch0((void *)(uintptr_t)desc_addrs[i]);
		hdrs[i] = (struct virtio_net_hdr_mrg_rxbuf *)
					(uintptr_t)desc_addrs[i];
		lens[i] = uz[i]->pkt_len + ha->vhost_hlen;
	}

	vhost_for_each_try_unroll(i, 0, PACKED_BATCH_SIZE)
		virtio_enqueue_offload(uz[i], &hdrs[i]->hdr);

	vq_inc_last_avail_packed(kl, PACKED_BATCH_SIZE);

	vhost_for_each_try_unroll(i, 0, PACKED_BATCH_SIZE) {
		rte_memcpy((void *)(uintptr_t)(desc_addrs[i] + buf_offset),
			   rte_pktmbuf_mtod_offset(uz[i], void *, 0),
			   uz[i]->pkt_len);
	}

	vhost_for_each_try_unroll(i, 0, PACKED_BATCH_SIZE)
		vhost_log_cache_write_iova(ha, kl, descs[avail_idx + i].addr,
					   lens[i]);

	vhost_for_each_try_unroll(i, 0, PACKED_BATCH_SIZE)
		ids[i] = descs[avail_idx + i].id;

	vhost_flush_enqueue_batch_packed(ha, kl, lens, ids);

	return 0;
}

