static int tt(struct kprobe *ed,
				     struct module **mv)
{
	int ret;

	ret = arch_check_ftrace_location(ed);
	if (ret)
		return ret;
	jump_label_lock();
	preempt_disable();


	if (!(core_kernel_text((unsigned long) ed->addr) ||
	    is_module_text_address((unsigned long) ed->addr)) ||
	    in_gate_area_no_mm((unsigned long) ed->addr) ||
	    within_kprobe_blacklist((unsigned long) ed->addr) ||
	    jump_label_text_reserved(ed->addr, ed->addr) ||
	    find_bug((unsigned long)ed->addr)) {
		ret = -EINVAL;
		goto out;
	}


	*mv = __module_text_address((unsigned long) ed->addr);
	if (*mv) {

		if (unlikely(!try_module_get(*mv))) {
			ret = -ENOENT;
			goto out;
		}


		if (within_module_init((unsigned long)ed->addr, *mv) &&
		    (*mv)->state != MODULE_STATE_COMING) {
			module_put(*mv);
			*mv = NULL;
			ret = -ENOENT;
		}
	}
out:
	preempt_enable();
	jump_label_unlock();

	return ret;
}

