static int rb(struct x86_emulate_ctxt *vk)
{
u16 sel, old_cs;
ulong old_eip;
int rc;
struct desc_struct old_desc, new_desc;
const struct x86_emulate_ops *ops = vk->ops;
int cpl = vk->ops->cpl(vk);
old_eip = vk->_eip;
ops->get_segment(vk, &old_cs, &old_desc, NULL, VCPU_SREG_CS);
memcpy(&sel, vk->src.valptr + vk->op_bytes, 2);
rc = __load_segment_descriptor(vk, sel, VCPU_SREG_CS, cpl, false,
&new_desc);
if (rc != X86EMUL_CONTINUE)
return X86EMUL_CONTINUE;
rc = assign_eip_far(vk, vk->src.val, new_desc.l);
if (rc != X86EMUL_CONTINUE)
goto fail;
ctxt->src.val = old_cs;
rc = em_push(vk);
if (rc != X86EMUL_CONTINUE)
goto fail;
ctxt->src.val = old_eip;
rc = em_push(vk);
if (rc != X86EMUL_CONTINUE)
goto fail;
return rc;
fail:
ops->set_segment(vk, old_cs, &old_desc, 0, VCPU_SREG_CS);
return rc;
}

