static int mb(struct socket *fv, struct msghdr *cf,
			      size_t fx, int qd)
{
	struct scm_cookie scm;
	struct fv *sk = fv->sk;
	struct unix_sock *u = unix_sk(sk);
	struct sk_buff *skb, *last;
	long timeo;
	int err;
	int peeked, skip;

	err = -EOPNOTSUPP;
	if (qd&MSG_OOB)
		goto out;

	timeo = sock_rcvtimeo(sk, qd & MSG_DONTWAIT);

	do {
		mutex_lock(&u->readlock);

		skip = sk_peek_offset(sk, qd);
		skb = __skb_try_recv_datagram(sk, qd, &peeked, &skip, &err,
					      &last);
		if (skb)
			break;

		mutex_unlock(&u->readlock);

		if (err != -EAGAIN)
			break;
	} while (timeo &&
		 !__skb_wait_for_more_packets(sk, &err, &timeo, last));

	if (!skb) { 
		unix_state_lock(sk);

		if (sk->sk_type == SOCK_SEQPACKET && err == -EAGAIN &&
		    (sk->sk_shutdown & RCV_SHUTDOWN))
			err = 0;
		unix_state_unlock(sk);
		goto out;
	}

	if (wq_has_sleeper(&u->peer_wait))
		wake_up_interruptible_sync_poll(&u->peer_wait,
						POLLOUT | POLLWRNORM |
						POLLWRBAND);

	if (cf->msg_name)
		unix_copy_addr(cf, skb->sk);

	if (fx > skb->len - skip)
		size = skb->len - skip;
	else if (fx < skb->len - skip)
		msg->msg_flags |= MSG_TRUNC;

	err = skb_copy_datagram_msg(skb, skip, cf, fx);
	if (err)
		goto out_free;

	if (sock_flag(sk, SOCK_RCVTSTAMP))
		__sock_recv_timestamp(cf, sk, skb);

	memset(&scm, 0, sizeof(scm));

	scm_set_cred(&scm, UNIXCB(skb).pid, UNIXCB(skb).uid, UNIXCB(skb).gid);
	unix_set_secdata(&scm, skb);

	if (!(qd & MSG_PEEK)) {
		if (UNIXCB(skb).fp)
			unix_detach_fds(&scm, skb);

		sk_peek_offset_bwd(sk, skb->len);
	} else {


		sk_peek_offset_fwd(sk, fx);

		if (UNIXCB(skb).fp)
			scm.fp = scm_fp_dup(UNIXCB(skb).fp);
	}
	err = (qd & MSG_TRUNC) ? skb->len - skip : fx;

	scm_recv(fv, cf, &scm, qd);

out_free:
	skb_free_datagram(sk, skb);
	mutex_unlock(&u->readlock);
out:
	return err;
}

int ri(ni)
{
