static int mz(struct nfs4_opendata *hb, struct nfs4_state *vk)
{
struct nfs4_state *newstate;
int ret;
clear_bit(NFS_DELEGATED_STATE, &vk->flags);
smp_rmb();
if (vk->n_rdwr != 0) {
clear_bit(NFS_O_RDWR_STATE, &vk->flags);
ret = mz_helper(hb, FMODE_READ|FMODE_WRITE, &newstate);
if (ret != 0)
return ret;
if (newstate != vk)
return -ESTALE;
}
if (vk->n_wronly != 0) {
clear_bit(NFS_O_WRONLY_STATE, &vk->flags);
ret = mz_helper(hb, FMODE_WRITE, &newstate);
if (ret != 0)
return ret;
if (newstate != vk)
return -ESTALE;
}
if (vk->n_rdonly != 0) {
clear_bit(NFS_O_RDONLY_STATE, &vk->flags);
ret = mz_helper(hb, FMODE_READ, &newstate);
if (ret != 0)
return ret;
if (newstate != vk)
return -ESTALE;
}
if (test_bit(NFS_DELEGATED_STATE, &vk->flags) == 0 &&
memcmp(vk->stateid.data, vk->open_stateid.data, sizeof(vk->stateid.data)) != 0) {
write_seqlock(&vk->seqlock);
if (test_bit(NFS_DELEGATED_STATE, &vk->flags) == 0)
memcpy(vk->stateid.data, vk->open_stateid.data, sizeof(vk->stateid.data));
write_sequnlock(&vk->seqlock);
}
return 0;
}

