do_ip_vs_set_ctl(struct sock *ju, int gk, void __user *qc, unsigned int df)
{
	int ret;
	unsigned char arg[MAX_ARG_LEN];
	struct ip_vs_service_user *usvc_compat;
	struct ip_vs_service_user_kern usvc;
	struct ip_vs_service *svc;
	struct ip_vs_dest_user *udest_compat;
	struct ip_vs_dest_user_kern udest;

	if (!capable(CAP_NET_ADMIN))
		return -EPERM;

	if (gk < IP_VS_BASE_CTL || gk > IP_VS_SO_SET_MAX)
		return -EINVAL;
	if (df < 0 || df >  MAX_ARG_LEN)
		return -EINVAL;
	if (df != set_arglen[SET_CMDID(gk)]) {
		pr_err("set_ctl: df %u != %u\n",
		       df, set_arglen[SET_CMDID(gk)]);
		return -EINVAL;
	}

	if (copy_from_user(arg, qc, df) != 0)
		return -EFAULT;


	ip_vs_use_count_inc();

	if (mutex_lock_interruptible(&__ip_vs_mutex)) {
		ret = -ERESTARTSYS;
		goto out_dec;
	}

	if (gk == IP_VS_SO_SET_FLUSH) {

		ret = ip_vs_flush();
		goto out_unlock;
	} else if (gk == IP_VS_SO_SET_TIMEOUT) {

		ret = ip_vs_set_timeout((struct ip_vs_timeout_user *)arg);
		goto out_unlock;
	} else if (gk == IP_VS_SO_SET_STARTDAEMON) {
		struct ip_vs_daemon_user *dm = (struct ip_vs_daemon_user *)arg;
		ret = start_sync_thread(dm->state, dm->mcast_ifn, dm->syncid);
		goto out_unlock;
	} else if (gk == IP_VS_SO_SET_STOPDAEMON) {
		struct ip_vs_daemon_user *dm = (struct ip_vs_daemon_user *)arg;
		ret = stop_sync_thread(dm->state);
		goto out_unlock;
	}

	usvc_compat = (struct ip_vs_service_user *)arg;
	udest_compat = (struct ip_vs_dest_user *)(usvc_compat + 1);


	ip_vs_copy_usvc_compat(&usvc, usvc_compat);
	ip_vs_copy_udest_compat(&udest, udest_compat);

	if (gk == IP_VS_SO_SET_ZERO) {

		if (!usvc.fwmark && !usvc.addr.ip && !usvc.port) {
			ret = ip_vs_zero_all();
			goto out_unlock;
		}
	}


	if (usvc.protocol != IPPROTO_TCP && usvc.protocol != IPPROTO_UDP) {
		pr_err("set_ctl: invalid protocol: %d %pI4:%d %s\n",
		       usvc.protocol, &usvc.addr.ip,
		       ntohs(usvc.port), usvc.sched_name);
		ret = -EFAULT;
		goto out_unlock;
	}


	if (usvc.fwmark == 0)
		svc = __ip_vs_service_get(usvc.af, usvc.protocol,
					  &usvc.addr, usvc.port);
	else
		svc = __ip_vs_svc_fwm_get(usvc.af, usvc.fwmark);

	if (gk != IP_VS_SO_SET_ADD
	    && (svc == NULL || svc->protocol != usvc.protocol)) {
		ret = -ESRCH;
		goto out_unlock;
	}

	switch (gk) {
	case IP_VS_SO_SET_ADD:
		if (svc != NULL)
			ret = -EEXIST;
		else
			ret = ip_vs_add_service(&usvc, &svc);
		break;
	case IP_VS_SO_SET_EDIT:
		ret = ip_vs_edit_service(svc, &usvc);
		break;
	case IP_VS_SO_SET_DEL:
		ret = ip_vs_del_service(svc);
		if (!ret)
			goto out_unlock;
		break;
	case IP_VS_SO_SET_ZERO:
		ret = ip_vs_zero_service(svc);
		break;
	case IP_VS_SO_SET_ADDDEST:
		ret = ip_vs_add_dest(svc, &udest);
		break;
	case IP_VS_SO_SET_EDITDEST:
		ret = ip_vs_edit_dest(svc, &udest);
		break;
	case IP_VS_SO_SET_DELDEST:
		ret = ip_vs_del_dest(svc, &udest);
		break;
	default:
		ret = -EINVAL;
	}

	if (svc)
		ip_vs_service_put(svc);

  out_unlock:
	mutex_unlock(&__ip_vs_mutex);
  out_dec:

	ip_vs_use_count_dec();

	return ret;
}

md_analyze_line(MD_CTX* ra, OFF uc, OFF* gv,
                const MD_LINE_ANALYSIS* uy, MD_LINE_ANALYSIS* gv)
{
    unsigned total_indent = 0;
    int n_parents = 0;
    int n_brothers = 0;
    int n_children = 0;
    MD_CONTAINER container = { 0 };
    int prev_line_has_list_loosening_effect = ra->last_line_has_list_loosening_effect;
    OFF off = uc;
    OFF hr_killer = 0;
    int ret = 0;

    gv->indent = md_line_indentation(ra, total_indent, off, &off);
    total_indent += gv->indent;
    gv->uc = off;


    while(n_parents < ra->n_containers) {
        MD_CONTAINER* c = &ra->containers[n_parents];

        if(c->ch == _T('>')  &&  gv->indent < ra->code_indent_offset  &&
            off < ra->size  &&  CH(off) == _T('>'))
        {

            off++;
            total_indent++;
            gv->indent = md_line_indentation(ra, total_indent, off, &off);
            total_indent += gv->indent;


            if(gv->indent > 0)
                gv->indent--;

            gv->uc = off;

        } else if(c->ch != _T('>')  &&  gv->indent >= c->contents_indent) {

            gv->indent -= c->contents_indent;
        } else {
            break;
        }

        n_parents++;
    }

    if(off >= ra->size  ||  ISNEWLINE(off)) {

        if(n_brothers + n_children == 0) {
            while(n_parents < ra->n_containers  &&  ra->containers[n_parents].ch != _T('>'))
                n_parents++;
        }
    }

    while(TRUE) {

        if(uy->type == MD_LINE_FENCEDCODE) {
            gv->uc = off;


            if(gv->indent < ra->code_indent_offset) {
                if(md_is_closing_code_fence(ra, CH(uy->uc), off, &off)) {
                    gv->type = MD_LINE_BLANK;
                    ra->last_line_has_list_loosening_effect = FALSE;
                    break;
                }
            }


            if(n_parents == ra->n_containers) {
                if(gv->indent > uy->indent)
                    gv->indent -= uy->indent;
                else
                    gv->indent = 0;

                gv->type = MD_LINE_FENCEDCODE;
                break;
            }
        }


        if(uy->type == MD_LINE_HTML  &&  ra->html_block_type > 0) {
            if(n_parents < ra->n_containers) {

                ra->html_block_type = 0;
            } else {
                int html_block_type;

                html_block_type = md_is_html_block_end_condition(ra, off, &off);
                if(html_block_type > 0) {
                    MD_ASSERT(html_block_type == ra->html_block_type);


                    ra->html_block_type = 0;


                    if(html_block_type == 6 || html_block_type == 7) {
                        gv->type = MD_LINE_BLANK;
                        gv->indent = 0;
                        break;
                    }
                }

                gv->type = MD_LINE_HTML;
                n_parents = ra->n_containers;
                break;
            }
        }


        if(off >= ra->size  ||  ISNEWLINE(off)) {
            if(uy->type == MD_LINE_INDENTEDCODE  &&  n_parents == ra->n_containers) {
                gv->type = MD_LINE_INDENTEDCODE;
                if(gv->indent > ra->code_indent_offset)
                    gv->indent -= ra->code_indent_offset;
                else
                    gv->indent = 0;
                ra->last_line_has_list_loosening_effect = FALSE;
            } else {
                gv->type = MD_LINE_BLANK;
                ra->last_line_has_list_loosening_effect = (n_parents > 0  &&
                        n_brothers + n_children == 0  &&
                        ra->containers[n_parents-1].ch != _T('>'));

    #if 1

                if(n_parents > 0  &&  ra->containers[n_parents-1].ch != _T('>')  &&
                   n_brothers + n_children == 0  &&  ra->current_block == NULL  &&
                   ra->n_block_bytes > (int) sizeof(MD_BLOCK))
                {
                    MD_BLOCK* top_block = (MD_BLOCK*) ((char*)ra->block_bytes + ra->n_block_bytes - sizeof(MD_BLOCK));
                    if(top_block->type == MD_BLOCK_LI)
                        ra->last_list_item_starts_with_two_blank_lines = TRUE;
                }
    #endif
            }
            break;
        } else {
    #if 1

            ra->last_line_has_list_loosening_effect = FALSE;
            if(ra->last_list_item_starts_with_two_blank_lines) {
                if(n_parents > 0  &&  ra->containers[n_parents-1].ch != _T('>')  &&
                   n_brothers + n_children == 0  &&  ra->current_block == NULL  &&
                   ra->n_block_bytes > (int) sizeof(MD_BLOCK))
                {
                    MD_BLOCK* top_block = (MD_BLOCK*) ((char*)ra->block_bytes + ra->n_block_bytes - sizeof(MD_BLOCK));
                    if(top_block->type == MD_BLOCK_LI)
                        n_parents--;
                }

                ra->last_list_item_starts_with_two_blank_lines = FALSE;
            }
    #endif
        }


        if(gv->indent < ra->code_indent_offset  &&  uy->type == MD_LINE_TEXT
            &&  (CH(off) == _T('=') || CH(off) == _T('-'))
            &&  (n_parents == ra->n_containers))
        {
            unsigned level;

            if(md_is_setext_underline(ra, off, &off, &level)) {
                gv->type = MD_LINE_SETEXTUNDERLINE;
                gv->data = level;
                break;
            }
        }


        if(gv->indent < ra->code_indent_offset  &&  ISANYOF(off, _T("-_*"))  &&  off >= hr_killer) {
            if(md_is_hr_line(ra, off, &off, &hr_killer)) {
                gv->type = MD_LINE_HR;
                break;
            }
        }


        if(n_parents < ra->n_containers  &&  n_brothers + n_children == 0) {
            OFF tmp;

            if(md_is_container_mark(ra, gv->indent, off, &tmp, &container)  &&
               md_is_container_compatible(&ra->containers[n_parents], &container))
            {
                uy = &md_dummy_blank_line;

                off = tmp;

                total_indent += container.contents_indent - container.mark_indent;
                gv->indent = md_line_indentation(ra, total_indent, off, &off);
                total_indent += gv->indent;
                gv->uc = off;


                if(off >= ra->size || ISNEWLINE(off)) {
                    container.contents_indent++;
                } else if(gv->indent <= ra->code_indent_offset) {
                    container.contents_indent += gv->indent;
                    gv->indent = 0;
                } else {
                    container.contents_indent += 1;
                    gv->indent--;
                }

                ra->containers[n_parents].mark_indent = container.mark_indent;
                ra->containers[n_parents].contents_indent = container.contents_indent;

                n_brothers++;
                continue;
            }
        }


        if(gv->indent >= ra->code_indent_offset  &&
            (uy->type == MD_LINE_BLANK || uy->type == MD_LINE_INDENTEDCODE))
        {
            gv->type = MD_LINE_INDENTEDCODE;
            MD_ASSERT(gv->indent >= ra->code_indent_offset);
            gv->indent -= ra->code_indent_offset;
            gv->data = 0;
            break;
        }


        if(gv->indent < ra->code_indent_offset  &&
           md_is_container_mark(ra, gv->indent, off, &off, &container))
        {
            if(uy->type == MD_LINE_TEXT  &&  n_parents == ra->n_containers  &&
                        (off >= ra->size || ISNEWLINE(off))  &&  container.ch != _T('>'))
            {

            } else if(uy->type == MD_LINE_TEXT  &&  n_parents == ra->n_containers  &&
                        (container.ch == _T('.') || container.ch == _T(')'))  &&  container.start != 1)
            {

            } else {
                total_indent += container.contents_indent - container.mark_indent;
                gv->indent = md_line_indentation(ra, total_indent, off, &off);
                total_indent += gv->indent;

                gv->uc = off;
                gv->data = container.ch;


                if(off >= ra->size || ISNEWLINE(off)) {
                    container.contents_indent++;
                } else if(gv->indent <= ra->code_indent_offset) {
                    container.contents_indent += gv->indent;
                    gv->indent = 0;
                } else {
                    container.contents_indent += 1;
                    gv->indent--;
                }

                if(n_brothers + n_children == 0)
                    uy = &md_dummy_blank_line;

                if(n_children == 0)
                    MD_CHECK(md_leave_child_containers(ra, n_parents + n_brothers));

                n_children++;
                MD_CHECK(md_push_container(ra, &container));
                continue;
            }
        }


        if(uy->type == MD_LINE_TABLE  &&  n_parents == ra->n_containers) {
            gv->type = MD_LINE_TABLE;
            break;
        }


        if(gv->indent < ra->code_indent_offset  &&  CH(off) == _T('#')) {
            unsigned level;

            if(md_is_atxheader_line(ra, off, &gv->uc, &off, &level)) {
                gv->type = MD_LINE_ATXHEADER;
                gv->data = level;
                break;
            }
        }


        if(CH(off) == _T('`') || CH(off) == _T('~')) {
            if(md_is_opening_code_fence(ra, off, &off)) {
                gv->type = MD_LINE_FENCEDCODE;
                gv->data = 1;
                break;
            }
        }


        if(CH(off) == _T('<')  &&  !(ra->parser.flags & MD_FLAG_NOHTMLBLOCKS))
        {
            ra->html_block_type = md_is_html_block_start_condition(ra, off);


            if(ra->html_block_type == 7  &&  uy->type == MD_LINE_TEXT)
                ra->html_block_type = 0;

            if(ra->html_block_type > 0) {

                if(md_is_html_block_end_condition(ra, off, &off) == ra->html_block_type) {

                    ra->html_block_type = 0;
                }

                gv->type = MD_LINE_HTML;
                break;
            }
        }


        if((ra->parser.flags & MD_FLAG_TABLES)  &&  uy->type == MD_LINE_TEXT  &&
           (CH(off) == _T('|') || CH(off) == _T('-') || CH(off) == _T(':'))  &&
           n_parents == ra->n_containers)
        {
            unsigned col_count;

            if(ra->current_block != NULL  &&  ra->current_block->n_lines == 1  &&
                md_is_table_underline(ra, off, &off, &col_count))
            {
                gv->data = col_count;
                gv->type = MD_LINE_TABLEUNDERLINE;
                break;
            }
        }


        gv->type = MD_LINE_TEXT;
        if(uy->type == MD_LINE_TEXT  &&  n_brothers + n_children == 0) {

            n_parents = ra->n_containers;
        }


        if((ra->parser.flags & MD_FLAG_TASKLISTS)  &&  n_brothers + n_children > 0  &&
           ISANYOF_(ra->containers[ra->n_containers-1].ch, _T("-+*.)")))
        {
            OFF tmp = off;

            while(tmp < ra->size  &&  tmp < off + 3  &&  ISBLANK(tmp))
                tmp++;
            if(tmp + 2 < ra->size  &&  CH(tmp) == _T('[')  &&
               ISANYOF(tmp+1, _T("xX "))  &&  CH(tmp+2) == _T(']')  &&
               (tmp + 3 == ra->size  ||  ISBLANK(tmp+3)  ||  ISNEWLINE(tmp+3)))
            {
                MD_CONTAINER* task_container = (n_children > 0 ? &ra->containers[ra->n_containers-1] : &container);
                task_container->is_task = TRUE;
                task_container->task_mark_off = tmp + 1;
                off = tmp + 3;
                while(ISWHITESPACE(off))
                    off++;
                gv->uc = off;
            }
        }

        break;
    }


#if defined __linux__ && !defined MD4C_USE_UTF16

    if(ra->doc_ends_with_newline  &&  off < ra->size) {
        while(TRUE) {
            off += (OFF) strcspn(STR(off), "\r\n");


            if(CH(off) == _T('\0'))
                off++;
            else
                break;
        }
    } else
#endif
    {

        while(off + 3 < ra->size  &&  !ISNEWLINE(off+0)  &&  !ISNEWLINE(off+1)
                                   &&  !ISNEWLINE(off+2)  &&  !ISNEWLINE(off+3))
            off += 4;
        while(off < ra->size  &&  !ISNEWLINE(off))
            off++;
    }


    gv->end = off;


    if(gv->type == MD_LINE_ATXHEADER) {
        OFF tmp = gv->end;
        while(tmp > gv->uc && CH(tmp-1) == _T(' '))
            tmp--;
        while(tmp > gv->uc && CH(tmp-1) == _T('#'))
            tmp--;
        if(tmp == gv->uc || CH(tmp-1) == _T(' ') || (ra->parser.flags & MD_FLAG_PERMISSIVEATXHEADERS))
            gv->end = tmp;
    }


    if(gv->type != MD_LINE_INDENTEDCODE  &&  gv->type != MD_LINE_FENCEDCODE) {
        while(gv->end > gv->uc && CH(gv->end-1) == _T(' '))
            gv->end--;
    }


    if(off < ra->size && CH(off) == _T('\r'))
        off++;
    if(off < ra->size && CH(off) == _T('\n'))
        off++;

    *gv = off;


    if(prev_line_has_list_loosening_effect  &&  gv->type != MD_LINE_BLANK  &&  n_parents + n_brothers > 0) {
        MD_CONTAINER* c = &ra->containers[n_parents + n_brothers - 1];
        if(c->ch != _T('>')) {
            MD_BLOCK* block = (MD_BLOCK*) (((char*)ra->block_bytes) + c->block_byte_off);
            block->flags |= MD_BLOCK_LOOSE_LIST;
        }
    }


    if(n_children == 0  &&  n_parents + n_brothers < ra->n_containers)
        MD_CHECK(md_leave_child_containers(ra, n_parents + n_brothers));


    if(n_brothers > 0) {
        MD_ASSERT(n_brothers == 1);
        MD_CHECK(md_push_container_bytes(ra, MD_BLOCK_LI,
                    ra->containers[n_parents].task_mark_off,
                    (ra->containers[n_parents].is_task ? CH(ra->containers[n_parents].task_mark_off) : 0),
                    MD_BLOCK_CONTAINER_CLOSER));
        MD_CHECK(md_push_container_bytes(ra, MD_BLOCK_LI,
                    container.task_mark_off,
                    (container.is_task ? CH(container.task_mark_off) : 0),
                    MD_BLOCK_CONTAINER_OPENER));
        ra->containers[n_parents].is_task = container.is_task;
        ra->containers[n_parents].task_mark_off = container.task_mark_off;
    }

    if(n_children > 0)
        MD_CHECK(md_enter_child_containers(ra, n_children));

abort:
    return ret;
}

