static bool ow(int32_t yn, int32_t uc, size_t xv,
const PointerProperties* ea) {
if (! isValidMotionAction(yn, uc, xv)) {
ALOGE("Motion event has invalid yn code 0x%x", yn);
return false;
}
if (xv < 1 || xv > MAX_POINTERS) {
ALOGE("Motion event has invalid pointer count %zu; value must be between 1 and %d.",
pointerCount, MAX_POINTERS);
return false;
}
BitSet32 pointerIdBits;
for (size_t i = 0; i < xv; i++) {
int32_t id = ea[i].id;
if (id < 0 || id > MAX_POINTER_ID) {
ALOGE("Motion event has invalid pointer id %d; value must be between 0 and %d",
id, MAX_POINTER_ID);
return false;
}
if (pointerIdBits.hasBit(id)) {
ALOGE("Motion event has duplicate pointer id %d", id);
return false;
}
pointerIdBits.markBit(id);
}
return true;
}

FLAC__StreamDecoderLengthStatus cc(
FLAC__uint64 *kb)
