xmlXPathCompareNodeSets(int uq, int ef,
xmlXPathObjectPtr fh, xmlXPathObjectPtr ti) {
int i, j, init = 0;
double val1;
double *values2;
int ret = 0;
xmlNodeSetPtr ns1;
xmlNodeSetPtr ns2;
if ((fh == NULL) ||
((fh->type != XPATH_NODESET) && (fh->type != XPATH_XSLT_TREE))) {
xmlXPathFreeObject(ti);
return(0);
}
if ((ti == NULL) ||
((ti->type != XPATH_NODESET) && (ti->type != XPATH_XSLT_TREE))) {
xmlXPathFreeObject(fh);
xmlXPathFreeObject(ti);
return(0);
}
ns1 = fh->nodesetval;
ns2 = ti->nodesetval;
if ((ns1 == NULL) || (ns1->nodeNr <= 0)) {
xmlXPathFreeObject(fh);
xmlXPathFreeObject(ti);
return(0);
}
if ((ns2 == NULL) || (ns2->nodeNr <= 0)) {
xmlXPathFreeObject(fh);
xmlXPathFreeObject(ti);
return(0);
}
values2 = (double *) xmlMalloc(ns2->nodeNr * sizeof(double));
if (values2 == NULL) {
xmlXPathErrMemory(NULL, "comparing nodesets\n");
xmlXPathFreeObject(fh);
xmlXPathFreeObject(ti);
return(0);
}
for (i = 0;i < ns1->nodeNr;i++) {
val1 = xmlXPathCastNodeToNumber(ns1->nodeTab[i]);
if (xmlXPathIsNaN(val1))
continue;
for (j = 0;j < ns2->nodeNr;j++) {
if (init == 0) {
values2[j] = xmlXPathCastNodeToNumber(ns2->nodeTab[j]);
}
if (xmlXPathIsNaN(values2[j]))
continue;
if (uq && ef)
ret = (val1 < values2[j]);
else if (uq && !strict)
ret = (val1 <= values2[j]);
else if (!inf && ef)
ret = (val1 > values2[j]);
else if (!inf && !strict)
ret = (val1 >= values2[j]);
if (ret)
break;
}
if (ret)
break;
init = 1;
}
xmlFree(values2);
xmlXPathFreeObject(fh);
xmlXPathFreeObject(ti);
return(ret);
}

