static void le(Ssh nf, struct Packet *ak,
void *hz, int hw,
void *xu, int ni)
{
unsigned char *pkblob = (unsigned char *)hz;
unsigned char *sigblob = (unsigned char *)xu;
if ((nf->remote_bugs & BUG_SSH2_RSA_PADDING) && hw > 4+7+4 &&
(GET_32BIT(pkblob) == 7 && !memcmp(pkblob+4, "ssh-rsa", 7))) {
int pos, len, siglen;
pos = 4+7;
len = toint(GET_32BIT(pkblob+pos));
if (len < 0 || len > hw - pos - 4)
goto give_up;
pos += 4 + len;
if (hw - pos < 4)
goto give_up;
len = toint(GET_32BIT(pkblob+pos));
if (len < 0 || len > hw - pos - 4)
goto give_up;
pos += 4;
while (len > 0 && pkblob[pos] == 0)
len--, pos++;
pos = 4+7;
if (ni < pos+4)
goto give_up;
siglen = toint(GET_32BIT(sigblob+pos));
if (siglen != ni - pos - 4)
goto give_up;
if (len != siglen) {
unsigned char newlen[4];
ssh2_pkt_addstring_start(ak);
ssh2_pkt_addstring_data(ak, (char *)sigblob, pos);
pos += 4;
PUT_32BIT(newlen, len);
ssh2_pkt_addstring_data(ak, (char *)newlen, 4);
newlen[0] = 0;
while (len-- > siglen) {
ssh2_pkt_addstring_data(ak, (char *)newlen, 1);
}
ssh2_pkt_addstring_data(ak, (char *)(sigblob+pos), siglen);
return;
}
give_up:;
}
ssh2_pkt_addstring_start(ak);
ssh2_pkt_addstring_data(ak, (char *)sigblob, ni);
}

