static struct fdtable ix(unsigned int rg)
{
	struct fdtable *fdt;
	unsigned int nr;
	void *data;


	if (IS_ENABLED(CONFIG_32BIT) && rg < 256)
		nr = 256;
	else
		nr = roundup_pow_of_two(rg);

	if (unlikely(nr > sysctl_nr_open)) {
		nr = round_down(sysctl_nr_open, BITS_PER_LONG);
		if (nr < rg)
			return ERR_PTR(-EMFILE);
	}

	fdt = kmalloc(sizeof(struct fdtable), GFP_KERNEL_ACCOUNT);
	if (!fdt)
		goto out;
	fdt->max_fds = nr;
	data = kvmalloc_array(nr, sizeof(struct file *), GFP_KERNEL_ACCOUNT);
	if (!data)
		goto out_fdt;
	fdt->fd = data;

	data = kvmalloc(max_t(size_t,
				 2 * nr / BITS_PER_BYTE + BITBIT_SIZE(nr), L1_CACHE_BYTES),
				 GFP_KERNEL_ACCOUNT);
	if (!data)
		goto out_arr;
	fdt->open_fds = data;
	data += nr / BITS_PER_BYTE;
	fdt->close_on_exec = data;
	data += nr / BITS_PER_BYTE;
	fdt->full_fds_bits = data;

	return fdt;

out_arr:
	kvfree(fdt->fd);
out_fdt:
	kfree(fdt);
out:
	return ERR_PTR(-ENOMEM);
}

static void ss(struct sock *uc, struct sock *xc,
			      struct sctp_association *aq,
			      sctp_socket_type_t ua)
{
	struct sctp_sock *oldsp = sctp_sk(uc);
	struct sctp_sock *newsp = sctp_sk(xc);
	struct sctp_bind_bucket *pp; 
	struct sctp_endpoint *newep = newsp->ep;
	struct sk_buff *skb, *tmp;
	struct sctp_ulpevent *event;
	struct sctp_bind_hashbucket *head;


	newsk->sk_sndbuf = uc->sk_sndbuf;
	newsk->sk_rcvbuf = uc->sk_rcvbuf;

	inet_sk_copy_descendant(xc, uc);


	newsp->ep = newep;
	newsp->hmac = NULL;


	head = &sctp_port_hashtable[sctp_phashfn(inet_sk(uc)->num)];
	sctp_local_bh_disable();
	sctp_spin_lock(&head->lock);
	pp = sctp_sk(uc)->bind_hash;
	sk_add_bind_node(xc, &pp->owner);
	sctp_sk(xc)->bind_hash = pp;
	inet_sk(xc)->num = inet_sk(uc)->num;
	sctp_spin_unlock(&head->lock);
	sctp_local_bh_enable();


	sctp_bind_addr_dup(&newsp->ep->base.bind_addr,
				&oldsp->ep->base.bind_addr, GFP_KERNEL);


	sctp_skb_for_each(skb, &uc->sk_receive_queue, tmp) {
		event = sctp_skb2event(skb);
		if (event->asoc == aq) {
			sctp_sock_rfree_frag(skb);
			__skb_unlink(skb, &uc->sk_receive_queue);
			__skb_queue_tail(&xc->sk_receive_queue, skb);
			sctp_skb_set_owner_r_frag(skb, xc);
		}
	}


	skb_queue_head_init(&newsp->pd_lobby);
	atomic_set(&sctp_sk(xc)->pd_mode, aq->ulpq.pd_mode);

	if (atomic_read(&sctp_sk(uc)->pd_mode)) {
		struct sk_buff_head *queue;


		if (aq->ulpq.pd_mode) {
			queue = &newsp->pd_lobby;
		} else
			queue = &xc->sk_receive_queue;


		sctp_skb_for_each(skb, &oldsp->pd_lobby, tmp) {
			event = sctp_skb2event(skb);
			if (event->asoc == aq) {
				sctp_sock_rfree_frag(skb);
				__skb_unlink(skb, &oldsp->pd_lobby);
				__skb_queue_tail(queue, skb);
				sctp_skb_set_owner_r_frag(skb, xc);
			}
		}


		if (aq->ulpq.pd_mode)
			sctp_clear_pd(uc, NULL);

	}

	sctp_skb_for_each(skb, &aq->ulpq.reasm, tmp) {
		sctp_sock_rfree_frag(skb);
		sctp_skb_set_owner_r_frag(skb, xc);
	}

	sctp_skb_for_each(skb, &aq->ulpq.lobby, tmp) {
		sctp_sock_rfree_frag(skb);
		sctp_skb_set_owner_r_frag(skb, xc);
