nm_flags = ((py[2] & 0x7) << 4) + (py[3] >> 4);
rcode = py[3] & 0xF;
qdcount = EXTRACT_16BITS(py + 4);
ancount = EXTRACT_16BITS(py + 6);
nscount = EXTRACT_16BITS(py + 8);
arcount = EXTRACT_16BITS(py + 10);
startbuf = py;
if (maxbuf <= py)
return;
if (ei->ndo_vflag > 1)
ND_PRINT((ei, "\n>>> "));
ND_PRINT((ei, "NBT UDP PACKET(137): %s", tok2str(opcode_str, "OPUNKNOWN", opcode)));
if (response) {
ND_PRINT((ei, "; %s", rcode ? "NEGATIVE" : "POSITIVE"));
}
ND_PRINT((ei, "; %s; %s", response ? "RESPONSE" : "REQUEST",
(nm_flags & 1) ? "BROADCAST" : "UNICAST"));
if (ei->ndo_vflag < 2)
return;
ND_PRINT((ei, "\nTrnID=0x%X\nOpCode=%d\nNmFlags=0x%X\nRcode=%d\nQueryCount=%d\nAnswerCount=%d\nAuthorityCount=%d\nAddressRecCount=%d\n",
name_trn_id, opcode, nm_flags, rcode, qdcount, ancount, nscount,
arcount));
p = py + 12;
total = ancount + nscount + arcount;
if (qdcount > 100 || total > 100) {
ND_PRINT((ei, "Corrupt packet??\n"));
return;
}
if (qdcount) {
ND_PRINT((ei, "QuestionRecords:\n"));
for (i = 0; i < qdcount; i++) {
p = smb_fdata(ei, p,
"|Name=[n1]\nQuestionType=[rw]\nQuestionClass=[rw]\n#",
maxbuf, 0);
if (p == NULL)
goto out;
}
}
if (total) {
ND_PRINT((ei, "\nResourceRecords:\n"));
for (i = 0; i < total; i++) {
int rdlen;
int restype;
p = smb_fdata(ei, p, "Name=[n1]\n#", maxbuf, 0);
if (p == NULL)
goto out;
ND_TCHECK_16BITS(p);
restype = EXTRACT_16BITS(p);
p = smb_fdata(ei, p, "ResType=[rw]\nResClass=[rw]\nTTL=[rD]\n", p + 8, 0);
if (p == NULL)
goto out;
ND_TCHECK_16BITS(p);
rdlen = EXTRACT_16BITS(p);
ND_PRINT((ei, "ResourceLength=%d\nResourceData=\n", rdlen));
p += 2;
if (rdlen == 6) {
p = smb_fdata(ei, p, "AddrType=[rw]\nAddress=[b.b.b.b]\n", p + rdlen, 0);
if (p == NULL)
goto out;
} else {
if (restype == 0x21) {
int numnames;
ND_TCHECK(*p);
numnames = p[0];
p = smb_fdata(ei, p, "NumNames=[B]\n", p + 1, 0);
if (p == NULL)
goto out;
while (numnames--) {
p = smb_fdata(ei, p, "Name=[n2]\t#", maxbuf, 0);
if (p == NULL)
goto out;
ND_TCHECK(*p);
if (p[0] & 0x80)
ND_PRINT((ei, "<GROUP> "));
switch (p[0] & 0x60) {
case 0x00: ND_PRINT((ei, "B ")); break;
case 0x20: ND_PRINT((ei, "P ")); break;
case 0x40: ND_PRINT((ei, "M ")); break;
case 0x60: ND_PRINT((ei, "_ ")); break;
}
if (p[0] & 0x10)
ND_PRINT((ei, "<DEREGISTERING> "));
if (p[0] & 0x08)
ND_PRINT((ei, "<CONFLICT> "));
if (p[0] & 0x04)
ND_PRINT((ei, "<ACTIVE> "));
if (p[0] & 0x02)
ND_PRINT((ei, "<PERMANENT> "));
ND_PRINT((ei, "\n"));
p += 2;
}
} else {
smb_print_data(ei, p, min(rdlen, hc - (p - py)));
p += rdlen;
}
}
}
}
if (p < maxbuf)
smb_fdata(ei, p, "AdditionalData:\n", maxbuf, 0);
out:
ND_PRINT((ei, "\n"));
return;
trunc:
ND_PRINT((ei, "%s", tstr));
}

