}
continue;
}
if (wc->debug != MagickFalse)
(void) LogMagickEvent(CoderEvent,GetMagickModule(),
"  reading data for layer %.20g",(double) i);
status=ReadPSDLayer(wc,cr,jx,&layer_info[i],
exception);
if (status == MagickFalse)
break;
status=SetImageProgress(wc,LoadImagesTag,(MagickOffsetType) i,
(MagickSizeType) number_layers);
if (status == MagickFalse)
