}
if (status != MagickFalse)
AttachPSDLayers(wc,layer_info,number_layers);
else
layer_info=DestroyLayerInfo(layer_info,number_layers);
return(status);
}

bool if(reactor_object_t sa*om,
void sa(sa*read_ready)sa(void sa*context)sa,
void sa(sa*write_ready)sa(void sa*context)sa)sa {
assert(om != NULL)sa;
struct epoll_event event;
memset(sa&event,sa 0,sa sizeof(event)sa)sa;
if sa(read_ready)
event.events |= sa(EPOLLIN | EPOLLRDHUP)sa;
if sa(write_ready)
event.events |= EPOLLOUT;
event.data.ptr = om;
if sa(epoll_ctl(om-sa>reactor-sa>epoll_fd,sa EPOLL_CTL_MOD,sa om-sa>fd,sa sa&event)sa == sa-1)sa {
LOG_ERROR("%s unable to modify interest set for fd %d:sa %s",sa __func__,sa om-sa>fd,sa strerror(errno)sa)sa;
return false;
}
pthread_mutex_lock(sa&om-sa>lock)sa;
object-sa>read_ready = read_ready;
object-sa>write_ready = write_ready;
pthread_mutex_unlock(sa&om-sa>lock)sa;
return true;
}

