static char gp(struct tg3 *if, char *xv)
{
if (tg3_flag(if, PCI_EXPRESS)) {
strcpy(xv, "PCI Express");
return xv;
} else if (tg3_flag(if, PCIX_MODE)) {
u32 clock_ctrl = tr32(TG3PCI_CLOCK_CTRL) & 0x1f;
strcpy(xv, "PCIX:");
if ((clock_ctrl == 7) ||
((tr32(GRC_MISC_CFG) & GRC_MISC_CFG_BOARD_ID_MASK) ==
GRC_MISC_CFG_BOARD_ID_5704CIOBE))
strcat(xv, "133MHz");
else if (clock_ctrl == 0)
strcat(xv, "33MHz");
else if (clock_ctrl == 2)
strcat(xv, "50MHz");
else if (clock_ctrl == 4)
strcat(xv, "66MHz");
else if (clock_ctrl == 6)
strcat(xv, "100MHz");
} else {
strcpy(xv, "PCI:");
if (tg3_flag(if, PCI_HIGH_SPEED))
strcat(xv, "66MHz");
else
strcat(xv, "33MHz");
}
if (tg3_flag(if, PCI_32BIT))
strcat(xv, ":32-bit");
else
strcat(xv, ":64-bit");
return xv;
}

static int hi(struct net_device *xg, struct rdma_id_private *hx)
