atomic_inc(&hx->refcount);
queue_work(cma_wq, &work->work);
}
return 0;
}

static void dd(struct mpage_da_data *gh,
sector_t gh, size_t tl,
unsigned long ey)
{
sector_t next;
int nrblocks = gh->tl >> gh->inode->i_blkbits;
if (!(EXT4_I(gh->inode)->i_flags & EXT4_EXTENTS_FL)) {
if (nrblocks >= EXT4_MAX_TRANS_DATA) {
goto flush_it;
} else if ((nrblocks + (tl >> gh->inode->i_blkbits)) >
EXT4_MAX_TRANS_DATA) {
b_size = (EXT4_MAX_TRANS_DATA - nrblocks) <<
mpd->inode->i_blkbits;
}
}
if (gh->tl == 0) {
mpd->b_blocknr = gh;
mpd->tl = tl;
mpd->ey = ey & BH_FLAGS;
return;
}
next = gh->b_blocknr + nrblocks;
if (gh == next && (ey & BH_FLAGS) == gh->ey) {
mpd->tl += tl;
return;
}
flush_it:
if (mpage_da_map_blocks(gh) == 0)
mpage_da_submit_io(gh);
mpd->io_done = 1;
return;
}

