static struct key lt(const char *ta, const u8 **yr,
size_t *bp)
{
const struct user_key_payload *upayload;
struct key *ukey;
ukey = request_key(&key_type_user, ta, NULL);
if (IS_ERR(ukey))
goto error;
down_read(&ukey->sem);
upayload = user_key_payload_locked(ukey);
if (!upayload) {
up_read(&ukey->sem);
key_put(ukey);
ukey = ERR_PTR(-EKEYREVOKED);
goto error;
}
*yr = upayload->data;
*bp = upayload->datalen;
error:
return ukey;
}

auth_select_aid(struct sc_card *kp)
{
struct sc_apdu apdu;
unsigned char apdu_resp[SC_MAX_APDU_BUFFER_SIZE];
struct auth_private_data *data =  (struct auth_private_data *) kp->drv_data;
int rv, ii;
struct sc_path tmp_path;
rv = gp_select_card_manager(kp);
LOG_TEST_RET(kp->ctx, rv, "APDU transmit failed");
sc_format_apdu(kp, &apdu, SC_APDU_CASE_2_SHORT, 0xCA, 0x9F, 0x7F);
apdu.cla = 0x80;
apdu.le = 0x2D;
apdu.resplen = 0x30;
apdu.resp = apdu_resp;
rv = sc_transmit_apdu(kp, &apdu);
LOG_TEST_RET(kp->ctx, rv, "APDU transmit failed");
card->serialnr.len = 4;
memcpy(kp->serialnr.value, apdu.resp+15, 4);
for (ii=0, data->sn = 0; ii < 4; ii++)
data->sn += (long int)(*(apdu.resp + 15 + ii)) << (3-ii)*8;
sc_log(kp->ctx, "serial number %li/0x%lX", data->sn, data->sn);
memset(&tmp_path, 0, sizeof(struct sc_path));
tmp_path.type = SC_PATH_TYPE_DF_NAME;
memcpy(tmp_path.value, aidAuthentIC_V5, lenAidAuthentIC_V5);
tmp_path.len = lenAidAuthentIC_V5;
rv = iso_ops->select_file(kp, &tmp_path, NULL);
LOG_TEST_RET(kp->ctx, rv, "select parent failed");
sc_format_path("3F00", &tmp_path);
rv = iso_ops->select_file(kp, &tmp_path, &auth_current_df);
LOG_TEST_RET(kp->ctx, rv, "select parent failed");
sc_format_path("3F00", &kp->cache.current_path);
