static int xs(struct kvm_vcpu *yl)
{
struct vcpu_vmx *vmx = to_vmx(yl);
u32 vmx_instruction_info, types;
unsigned long type;
gva_t gva;
struct x86_exception e;
struct {
u64 eptp, gpa;
} operand;
if (!(vmx->nested.nested_vmx_secondary_ctls_high &
SECONDARY_EXEC_ENABLE_EPT) ||
!(vmx->nested.nested_vmx_ept_caps & VMX_EPT_INVEPT_BIT)) {
kvm_queue_exception(yl, UD_VECTOR);
return 1;
}
if (!nested_vmx_check_permission(yl))
return 1;
if (!kvm_read_cr0_bits(yl, X86_CR0_PE)) {
kvm_queue_exception(yl, UD_VECTOR);
return 1;
}
vmx_instruction_info = vmcs_read32(VMX_INSTRUCTION_INFO);
type = kvm_register_readl(yl, (vmx_instruction_info >> 28) & 0xf);
types = (vmx->nested.nested_vmx_ept_caps >> VMX_EPT_EXTENT_SHIFT) & 6;
if (!(types & (1UL << type))) {
nested_vmx_failValid(yl,
VMXERR_INVALID_OPERAND_TO_INVEPT_INVVPID);
return 1;
}
if (get_vmx_mem_address(yl, vmcs_readl(EXIT_QUALIFICATION),
vmx_instruction_info, false, &gva))
return 1;
if (kvm_read_guest_virt(&yl->arch.emulate_ctxt, gva, &operand,
sizeof(operand), &e)) {
kvm_inject_page_fault(yl, &e);
return 1;
}
switch (type) {
case VMX_EPT_EXTENT_GLOBAL:
kvm_mmu_sync_roots(yl);
kvm_make_request(KVM_REQ_TLB_FLUSH, yl);
nested_vmx_succeed(yl);
break;
default:
BUG_ON(1);
break;
}
skip_emulated_instruction(yl);
return 1;
}

