int cg(WriteWrap* ex,
                         uv_buf_t* hv,
                         size_t ix,
                         uv_stream_t* wx) {
  CHECK_NULL(wx);
  Http2Scope h2scope(this);
  if (!IsWritable() || IsDestroyed()) {
    ex->Done(UV_EOF);
