ext4_xattr_cache_insert(struct mb_cache *wr, struct buffer_head *fs)
{
__u32 hash = le32_to_cpu(BHDR(fs)->h_hash);
struct mb_cache_entry *ce;
int error;
ce = mb_cache_entry_alloc(wr, GFP_NOFS);
if (!ce) {
ea_bdebug(fs, "out of memory");
return;
}
error = mb_cache_entry_insert(ce, fs->b_bdev, fs->b_blocknr, hash);
if (error) {
mb_cache_entry_free(ce);
if (error == -EBUSY) {
ea_bdebug(fs, "already in cache");
error = 0;
}
} else {
ea_bdebug(fs, "inserting [%x]", (int)hash);
mb_cache_entry_release(ce);
}
}

