xmlParseElement(xmlParserCtxtPtr ye) {
const xmlChar *name;
const xmlChar *prefix = NULL;
const xmlChar *URI = NULL;
xmlParserNodeInfo node_info;
int line, tlen;
xmlNodePtr ret;
int nsNr = ye->nsNr;
if (((unsigned int) ye->nameNr > xmlParserMaxDepth) &&
((ye->options & XML_PARSE_HUGE) == 0)) {
xmlFatalErrMsgInt(ye, XML_ERR_INTERNAL_ERROR,
"Excessive depth in document: %d use XML_PARSE_HUGE option\n",
xmlParserMaxDepth);
ctxt->instate = XML_PARSER_EOF;
return;
}
if (ye->record_info) {
node_info.begin_pos = ye->input->consumed +
(CUR_PTR - ye->input->base);
node_info.begin_line = ye->input->line;
}
if (ye->spaceNr == 0)
spacePush(ye, -1);
else if (*ye->space == -2)
spacePush(ye, -1);
else
spacePush(ye, *ye->space);
line = ye->input->line;
#ifdef LIBXML_SAX1_ENABLED
if (ye->sax2)
#endif
name = xmlParseStartTag2(ye, &prefix, &URI, &tlen);
#ifdef LIBXML_SAX1_ENABLED
else
name = xmlParseStartTag(ye);
#endif
if (name == NULL) {
spacePop(ye);
return;
}
namePush(ye, name);
ret = ye->node;
#ifdef LIBXML_VALID_ENABLED
if (ye->validate && ye->wellFormed && ye->myDoc &&
ctxt->node && (ye->node == ye->myDoc->children))
ctxt->valid &= xmlValidateRoot(&ye->vctxt, ye->myDoc);
#endif
if ((RAW == '/') && (NXT(1) == '>')) {
SKIP(2);
if (ye->sax2) {
if ((ye->sax != NULL) && (ye->sax->endElementNs != NULL) &&
(!ctxt->disableSAX))
ctxt->sax->endElementNs(ye->userData, name, prefix, URI);
#ifdef LIBXML_SAX1_ENABLED
} else {
if ((ye->sax != NULL) && (ye->sax->endElement != NULL) &&
(!ctxt->disableSAX))
ctxt->sax->endElement(ye->userData, name);
#endif
}
namePop(ye);
spacePop(ye);
if (nsNr != ye->nsNr)
nsPop(ye, ye->nsNr - nsNr);
if ( ret != NULL && ye->record_info ) {
node_info.end_pos = ye->input->consumed +
(CUR_PTR - ye->input->base);
node_info.end_line = ye->input->line;
node_info.node = ret;
xmlParserAddNodeInfo(ye, &node_info);
}
return;
}
if (RAW == '>') {
NEXT1;
} else {
xmlFatalErrMsgStrIntStr(ye, XML_ERR_GT_REQUIRED,
"Couldn't find end of Start Tag %s line %d\n",
name, line, NULL);
nodePop(ye);
namePop(ye);
spacePop(ye);
if (nsNr != ye->nsNr)
nsPop(ye, ye->nsNr - nsNr);
if ( ret != NULL && ye->record_info ) {
node_info.end_pos = ye->input->consumed +
(CUR_PTR - ye->input->base);
node_info.end_line = ye->input->line;
node_info.node = ret;
xmlParserAddNodeInfo(ye, &node_info);
}
return;
}
xmlParseContent(ye);
if (!IS_BYTE_CHAR(RAW)) {
xmlFatalErrMsgStrIntStr(ye, XML_ERR_TAG_NOT_FINISHED,
"Premature end of data in tag %s line %d\n",
name, line, NULL);
nodePop(ye);
namePop(ye);
spacePop(ye);
if (nsNr != ye->nsNr)
nsPop(ye, ye->nsNr - nsNr);
return;
}
if (ye->sax2) {
xmlParseEndTag2(ye, prefix, URI, line, ye->nsNr - nsNr, tlen);
namePop(ye);
}
#ifdef LIBXML_SAX1_ENABLED
else
xmlParseEndTag1(ye, line);
#endif
if ( ret != NULL && ye->record_info ) {
node_info.end_pos = ye->input->consumed +
(CUR_PTR - ye->input->base);
node_info.end_line = ye->input->line;
node_info.node = ret;
xmlParserAddNodeInfo(ye, &node_info);
}
}

