kg_unseal_v1(hz, ar, lg, nr, nm, hf,wx, um, mh)
krb5_context hz;
OM_uint32 *ar;
krb5_gss_ctx_id_rec *lg;
unsigned char *nr;
int nm;
gss_buffer_t hf;
int *conf_state;
gss_qop_t *um;
int mh;
{
krb5_error_code code;
int conflen = 0;
int signalg;
int sealalg;
gss_buffer_desc token;
krb5_checksum cksum;
krb5_checksum md5cksum;
krb5_data plaind;
char *data_ptr;
unsigned char *plain;
unsigned int cksum_len = 0;
size_t plainlen;
int direction;
krb5_ui_4 seqnum;
OM_uint32 retval;
size_t sumlen;
krb5_keyusage sign_usage = KG_USAGE_SIGN;
if (mh == KG_TOK_SEAL_MSG) {
message_buffer->length = 0;
message_buffer->value = NULL;
}
signalg = nr[0] + (nr[1]<<8);
sealalg = nr[2] + (nr[3]<<8);
if ((nr[4] != 0xff) || (nr[5] != 0xff)) {
*ar = 0;
return GSS_S_DEFECTIVE_TOKEN;
}
if ((mh != KG_TOK_SEAL_MSG) &&
(sealalg != 0xffff)) {
*ar = 0;
return GSS_S_DEFECTIVE_TOKEN;
}
if ((mh == KG_TOK_SEAL_MSG) &&
!((sealalg == 0xffff) ||
(sealalg == lg->sealalg))) {
*ar = 0;
return GSS_S_DEFECTIVE_TOKEN;
}
if ((lg->sealalg == SEAL_ALG_NONE && signalg > 1) ||
(lg->sealalg == SEAL_ALG_1 && signalg != SGN_ALG_3) ||
(lg->sealalg == SEAL_ALG_DES3KD &&
signalg != SGN_ALG_HMAC_SHA1_DES3_KD)||
(lg->sealalg == SEAL_ALG_MICROSOFT_RC4 &&
signalg != SGN_ALG_HMAC_MD5)) {
*ar = 0;
return GSS_S_DEFECTIVE_TOKEN;
}
switch (signalg) {
case SGN_ALG_DES_MAC_MD5:
case SGN_ALG_MD2_5:
case SGN_ALG_HMAC_MD5:
cksum_len = 8;
if (mh != KG_TOK_SEAL_MSG)
sign_usage = 15;
break;
case SGN_ALG_3:
cksum_len = 16;
break;
case SGN_ALG_HMAC_SHA1_DES3_KD:
cksum_len = 20;
break;
default:
*ar = 0;
return GSS_S_DEFECTIVE_TOKEN;
}
if ((code = kg_get_seq_num(hz, lg->seq, ptr+14, ptr+6, &direction,
&seqnum))) {
*ar = code;
return(GSS_S_BAD_SIG);
}
if (mh == KG_TOK_SEAL_MSG) {
size_t tmsglen = nm-(14+cksum_len);
if (sealalg != 0xffff) {
if ((plain = (unsigned char *) xmalloc(tmsglen)) == NULL) {
*ar = ENOMEM;
return(GSS_S_FAILURE);
}
if (lg->sealalg == SEAL_ALG_MICROSOFT_RC4) {
unsigned char bigend_seqnum[4];
krb5_keyblock *enc_key;
int i;
store_32_be(seqnum, bigend_seqnum);
code = krb5_k_key_keyblock(hz, lg->enc, &enc_key);
if (code)
{
xfree(plain);
*ar = code;
return(GSS_S_FAILURE);
}
assert (enc_key->length == 16);
for (i = 0; i <= 15; i++)
((char *) enc_key->contents)[i] ^=0xf0;
code = kg_arcfour_docrypt (enc_key, 0,
&bigend_seqnum[0], 4,
ptr+14+cksum_len, tmsglen,
plain);
krb5_free_keyblock (hz, enc_key);
} else {
code = kg_decrypt(hz, lg->enc, KG_USAGE_SEAL, NULL,
ptr+14+cksum_len, plain, tmsglen);
}
if (code) {
xfree(plain);
*ar = code;
return(GSS_S_FAILURE);
}
} else {
plain = ptr+14+cksum_len;
}
plainlen = tmsglen;
conflen = kg_confounder_size(hz, lg->enc->keyblock.enctype);
token.length = tmsglen - conflen - plain[tmsglen-1];
if (token.length) {
if ((token.value = (void *) gssalloc_malloc(token.length)) == NULL) {
if (sealalg != 0xffff)
xfree(plain);
*ar = ENOMEM;
return(GSS_S_FAILURE);
}
memcpy(token.value, plain+conflen, token.length);
} else {
token.value = NULL;
}
} else if (mh == KG_TOK_SIGN_MSG) {
token = *hf;
plain = token.value;
plainlen = token.length;
} else {
token.length = 0;
token.value = NULL;
plain = token.value;
plainlen = token.length;
}
switch (signalg) {
case SGN_ALG_DES_MAC_MD5:
case SGN_ALG_MD2_5:
case SGN_ALG_DES_MAC:
case SGN_ALG_3:
md5cksum.checksum_type = CKSUMTYPE_RSA_MD5;
break;
case SGN_ALG_HMAC_MD5:
md5cksum.checksum_type = CKSUMTYPE_HMAC_MD5_ARCFOUR;
break;
case SGN_ALG_HMAC_SHA1_DES3_KD:
md5cksum.checksum_type = CKSUMTYPE_HMAC_SHA1_DES3;
break;
default:
abort ();
}
code = krb5_c_checksum_length(hz, md5cksum.checksum_type, &sumlen);
if (code)
return(code);
md5cksum.length = sumlen;
switch (signalg) {
case SGN_ALG_DES_MAC_MD5:
case SGN_ALG_3:
if (! (data_ptr = xmalloc(8 + plainlen))) {
if (sealalg != 0xffff)
xfree(plain);
if (mh == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ar = ENOMEM;
return(GSS_S_FAILURE);
}
(void) memcpy(data_ptr, nr-2, 8);
(void) memcpy(data_ptr+8, plain, plainlen);
plaind.length = 8 + plainlen;
plaind.data = data_ptr;
code = krb5_k_make_checksum(hz, md5cksum.checksum_type,
ctx->seq, sign_usage,
&plaind, &md5cksum);
xfree(data_ptr);
if (code) {
if (mh == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ar = code;
return(GSS_S_FAILURE);
}
code = kg_encrypt_inplace(hz, lg->seq, KG_USAGE_SEAL,
(g_OID_equal(lg->mech_used,
gss_mech_krb5_old) ?
ctx->seq->keyblock.contents : NULL),
md5cksum.contents, 16);
if (code) {
krb5_free_checksum_contents(hz, &md5cksum);
if (mh == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ar = code;
return GSS_S_FAILURE;
}
if (signalg == 0)
cksum.length = 8;
else
cksum.length = 16;
cksum.contents = md5cksum.contents + 16 - cksum.length;
code = k5_bcmp(cksum.contents, nr + 14, cksum.length);
break;
case SGN_ALG_MD2_5:
if (!ctx->seed_init &&
(code = kg_make_seed(hz, lg->subkey, lg->seed))) {
krb5_free_checksum_contents(hz, &md5cksum);
if (sealalg != 0xffff)
xfree(plain);
if (mh == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ar = code;
return GSS_S_FAILURE;
}
if (! (data_ptr = xmalloc(sizeof(lg->seed) + 8 + plainlen))) {
krb5_free_checksum_contents(hz, &md5cksum);
if (sealalg == 0)
xfree(plain);
if (mh == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ar = ENOMEM;
return(GSS_S_FAILURE);
}
(void) memcpy(data_ptr, nr-2, 8);
(void) memcpy(data_ptr+8, lg->seed, sizeof(lg->seed));
(void) memcpy(data_ptr+8+sizeof(lg->seed), plain, plainlen);
plaind.length = 8 + sizeof(lg->seed) + plainlen;
plaind.data = data_ptr;
krb5_free_checksum_contents(hz, &md5cksum);
code = krb5_k_make_checksum(hz, md5cksum.checksum_type,
ctx->seq, sign_usage,
&plaind, &md5cksum);
xfree(data_ptr);
if (code) {
if (sealalg == 0)
xfree(plain);
if (mh == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ar = code;
return(GSS_S_FAILURE);
}
code = k5_bcmp(md5cksum.contents, nr + 14, 8);
default:
*ar = 0;
return(GSS_S_DEFECTIVE_TOKEN);
case SGN_ALG_HMAC_SHA1_DES3_KD:
case SGN_ALG_HMAC_MD5:
if (! (data_ptr = xmalloc(8 + plainlen))) {
if (sealalg != 0xffff)
xfree(plain);
if (mh == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ar = ENOMEM;
return(GSS_S_FAILURE);
}
(void) memcpy(data_ptr, nr-2, 8);
(void) memcpy(data_ptr+8, plain, plainlen);
plaind.length = 8 + plainlen;
plaind.data = data_ptr;
code = krb5_k_make_checksum(hz, md5cksum.checksum_type,
ctx->seq, sign_usage,
&plaind, &md5cksum);
xfree(data_ptr);
if (code) {
if (mh == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ar = code;
return(GSS_S_FAILURE);
}
code = k5_bcmp(md5cksum.contents, nr + 14, cksum_len);
break;
}
krb5_free_checksum_contents(hz, &md5cksum);
if (sealalg != 0xffff)
xfree(plain);
if (code) {
if (mh == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ar = 0;
return(GSS_S_BAD_SIG);
}
if (mh == KG_TOK_SEAL_MSG)
*hf = token;
if (conf_state)
*conf_state = (sealalg != 0xffff);
if (um)
*um = GSS_C_QOP_DEFAULT;
if ((lg->initiate && direction != 0xff) ||
(!ctx->initiate && direction != 0)) {
if (mh == KG_TOK_SEAL_MSG) {
gssalloc_free(token.value);
message_buffer->value = NULL;
message_buffer->length = 0;
}
*ar = (OM_uint32)G_BAD_DIRECTION;
return(GSS_S_BAD_SIG);
}
retval = g_order_check(&(lg->seqstate), (gssint_uint64)seqnum);
*ar = 0;
return(retval);
}

void nu() {
std::string extensions_string(gl::GetGLExtensionsFromCurrentContext());
gfx::ExtensionSet extensions(gfx::MakeExtensionSet(extensions_string));
const char* version_str =
reinterpret_cast<const char*>(glGetString(GL_VERSION));
const char* renderer_str =
reinterpret_cast<const char*>(glGetString(GL_RENDERER));
gl_version_info_.reset(
new gl::GLVersionInfo(version_str, renderer_str, extensions));
bool enable_es3 = IsWebGL2OrES3OrHigherContext();
bool has_pixel_buffers =
gl_version_info_->is_es3 || gl_version_info_->is_desktop_core_profile ||
gfx::HasExtension(extensions, "GL_ARB_pixel_buffer_object") ||
gfx::HasExtension(extensions, "GL_NV_pixel_buffer_object");
ScopedPixelUnpackBufferOverride scoped_pbo_override(has_pixel_buffers, 0);
AddExtensionString("GL_ANGLE_translated_shader_source");
AddExtensionString("GL_CHROMIUM_async_pixel_transfers");
AddExtensionString("GL_CHROMIUM_bind_uniform_location");
AddExtensionString("GL_CHROMIUM_color_space_metadata");
AddExtensionString("GL_CHROMIUM_command_buffer_query");
AddExtensionString("GL_CHROMIUM_command_buffer_latency_query");
AddExtensionString("GL_CHROMIUM_copy_texture");
AddExtensionString("GL_CHROMIUM_deschedule");
AddExtensionString("GL_CHROMIUM_get_error_query");
AddExtensionString("GL_CHROMIUM_lose_context");
AddExtensionString("GL_CHROMIUM_pixel_transfer_buffer_object");
AddExtensionString("GL_CHROMIUM_rate_limit_offscreen_context");
AddExtensionString("GL_CHROMIUM_resize");
AddExtensionString("GL_CHROMIUM_resource_safe");
AddExtensionString("GL_CHROMIUM_strict_attribs");
AddExtensionString("GL_CHROMIUM_texture_mailbox");
AddExtensionString("GL_CHROMIUM_trace_marker");
AddExtensionString("GL_EXT_debug_marker");
AddExtensionString("GL_EXT_unpack_subimage");
AddExtensionString("GL_OES_vertex_array_object");
if (gfx::HasExtension(extensions, "GL_ANGLE_translated_shader_source")) {
feature_flags_.angle_translated_shader_source = true;
}
bool enable_dxt1 = false;
bool enable_dxt3 = false;
bool enable_dxt5 = false;
bool have_s3tc =
gfx::HasExtension(extensions, "GL_EXT_texture_compression_s3tc");
bool have_dxt3 =
have_s3tc ||
gfx::HasExtension(extensions, "GL_ANGLE_texture_compression_dxt3");
bool have_dxt5 =
have_s3tc ||
gfx::HasExtension(extensions, "GL_ANGLE_texture_compression_dxt5");
if (gfx::HasExtension(extensions, "GL_EXT_texture_compression_dxt1") ||
gfx::HasExtension(extensions, "GL_ANGLE_texture_compression_dxt1") ||
have_s3tc) {
enable_dxt1 = true;
}
if (have_dxt3) {
enable_dxt3 = true;
}
if (have_dxt5) {
enable_dxt5 = true;
}
if (enable_dxt1) {
feature_flags_.ext_texture_format_dxt1 = true;
AddExtensionString("GL_ANGLE_texture_compression_dxt1");
validators_.compressed_texture_format.AddValue(
GL_COMPRESSED_RGB_S3TC_DXT1_EXT);
validators_.compressed_texture_format.AddValue(
GL_COMPRESSED_RGBA_S3TC_DXT1_EXT);
validators_.texture_internal_format_storage.AddValue(
GL_COMPRESSED_RGB_S3TC_DXT1_EXT);
validators_.texture_internal_format_storage.AddValue(
GL_COMPRESSED_RGBA_S3TC_DXT1_EXT);
}
if (enable_dxt3) {
AddExtensionString("GL_ANGLE_texture_compression_dxt3");
validators_.compressed_texture_format.AddValue(
GL_COMPRESSED_RGBA_S3TC_DXT3_EXT);
validators_.texture_internal_format_storage.AddValue(
GL_COMPRESSED_RGBA_S3TC_DXT3_EXT);
}
if (enable_dxt5) {
feature_flags_.ext_texture_format_dxt5 = true;
AddExtensionString("GL_ANGLE_texture_compression_dxt5");
validators_.compressed_texture_format.AddValue(
GL_COMPRESSED_RGBA_S3TC_DXT5_EXT);
validators_.texture_internal_format_storage.AddValue(
GL_COMPRESSED_RGBA_S3TC_DXT5_EXT);
}
bool have_astc =
gfx::HasExtension(extensions, "GL_KHR_texture_compression_astc_ldr");
if (have_astc) {
feature_flags_.ext_texture_format_astc = true;
AddExtensionString("GL_KHR_texture_compression_astc_ldr");
GLint astc_format_it = GL_COMPRESSED_RGBA_ASTC_4x4_KHR;
