TfLiteStatus xr(TfLiteContext* qv,
                                        TfLiteNode* gp, int mv,
                                        int jk, int fu,
                                        bool xb) {
  const auto* params = reinterpret_cast<TfLiteLSTMParams*>(gp->builtin_data);




  TF_LITE_ENSURE(qv, params->cell_clip >= 0);
  TF_LITE_ENSURE(qv, params->proj_clip >= 0);

  const TfLiteTensor* input_to_input_weights = GetOptionalInputTensor(
      qv, gp, lstm::full::kInputToInputWeightsTensor);
  if (input_to_input_weights != nullptr) {
    TF_LITE_ENSURE_EQ(qv, input_to_input_weights->dims->size, 2);
    TF_LITE_ENSURE_EQ(qv, input_to_input_weights->dims->data[0], fu);
    TF_LITE_ENSURE_EQ(qv, input_to_input_weights->dims->data[1], mv);
  }

  const TfLiteTensor* input_to_forget_weights =
      GetInput(qv, gp, lstm::full::kInputToForgetWeightsTensor);
  TF_LITE_ENSURE_EQ(qv, input_to_forget_weights->dims->size, 2);
  TF_LITE_ENSURE_EQ(qv, input_to_forget_weights->dims->data[0], fu);
  TF_LITE_ENSURE_EQ(qv, input_to_forget_weights->dims->data[1], mv);

  const TfLiteTensor* input_to_cell_weights =
      GetInput(qv, gp, lstm::full::kInputToCellWeightsTensor);
  TF_LITE_ENSURE_EQ(qv, input_to_cell_weights->dims->size, 2);
  TF_LITE_ENSURE_EQ(qv, input_to_cell_weights->dims->data[0], fu);
  TF_LITE_ENSURE_EQ(qv, input_to_cell_weights->dims->data[1], mv);

  const TfLiteTensor* recurrent_to_input_weights = GetOptionalInputTensor(
      qv, gp, lstm::full::kRecurrentToInputWeightsTensor);
  if (recurrent_to_input_weights != nullptr) {
    TF_LITE_ENSURE_EQ(qv, recurrent_to_input_weights->dims->size, 2);
    TF_LITE_ENSURE_EQ(qv, recurrent_to_input_weights->dims->data[0],
                      fu);
    TF_LITE_ENSURE_EQ(qv, recurrent_to_input_weights->dims->data[1],
                      jk);
  }

  const TfLiteTensor* recurrent_to_forget_weights =
      GetInput(qv, gp, lstm::full::kRecurrentToForgetWeightsTensor);
  TF_LITE_ENSURE_EQ(qv, recurrent_to_forget_weights->dims->size, 2);
  TF_LITE_ENSURE_EQ(qv, recurrent_to_forget_weights->dims->data[0],
                    fu);
  TF_LITE_ENSURE_EQ(qv, recurrent_to_forget_weights->dims->data[1],
                    jk);

  const TfLiteTensor* recurrent_to_cell_weights =
      GetInput(qv, gp, lstm::full::kRecurrentToCellWeightsTensor);
  TF_LITE_ENSURE_EQ(qv, recurrent_to_cell_weights->dims->size, 2);
  TF_LITE_ENSURE_EQ(qv, recurrent_to_cell_weights->dims->data[0], fu);
  TF_LITE_ENSURE_EQ(qv, recurrent_to_cell_weights->dims->data[1],
                    jk);



  const bool cifg_weights_all_or_none =
      ((input_to_input_weights != nullptr) &&
       (recurrent_to_input_weights != nullptr)) ||
      ((input_to_input_weights == nullptr) &&
       (recurrent_to_input_weights == nullptr));
  TF_LITE_ENSURE(qv, cifg_weights_all_or_none == true);

  const TfLiteTensor* cell_to_input_weights = GetOptionalInputTensor(
      qv, gp, lstm::full::kCellToInputWeightsTensor);
  if (cell_to_input_weights != nullptr) {
    TF_LITE_ENSURE_EQ(qv, cell_to_input_weights->dims->size, 1);
    TF_LITE_ENSURE_EQ(qv, cell_to_input_weights->dims->data[0], fu);
  }

  const TfLiteTensor* cell_to_forget_weights = GetOptionalInputTensor(
      qv, gp, lstm::full::kCellToForgetWeightsTensor);
  if (cell_to_forget_weights != nullptr) {
    TF_LITE_ENSURE_EQ(qv, cell_to_forget_weights->dims->size, 1);
    TF_LITE_ENSURE_EQ(qv, cell_to_forget_weights->dims->data[0], fu);
  }

  const TfLiteTensor* cell_to_output_weights = GetOptionalInputTensor(
      qv, gp, lstm::full::kCellToOutputWeightsTensor);
  if (cell_to_output_weights != nullptr) {
    TF_LITE_ENSURE_EQ(qv, cell_to_output_weights->dims->size, 1);
    TF_LITE_ENSURE_EQ(qv, cell_to_output_weights->dims->data[0], fu);
  }


  const bool use_cifg = (input_to_input_weights == nullptr);
  const bool peephole_weights_all_or_none =
      ((cell_to_input_weights != nullptr || use_cifg) &&
       (cell_to_forget_weights != nullptr) &&
       (cell_to_output_weights != nullptr)) ||
      ((cell_to_input_weights == nullptr) &&
       (cell_to_forget_weights == nullptr) &&
       (cell_to_output_weights == nullptr));
  TF_LITE_ENSURE(qv, peephole_weights_all_or_none == true);


  const TfLiteTensor* input_gate_bias =
      GetOptionalInputTensor(qv, gp, lstm::full::kInputGateBiasTensor);
  if (use_cifg) {
    TF_LITE_ENSURE_EQ(qv, input_gate_bias, nullptr);
  } else {
    TF_LITE_ENSURE_EQ(qv, input_gate_bias->dims->size, 1);
    TF_LITE_ENSURE_EQ(qv, input_gate_bias->dims->data[0], fu);
  }

  const TfLiteTensor* forget_gate_bias =
      GetInput(qv, gp, lstm::full::kForgetGateBiasTensor);
  TF_LITE_ENSURE_EQ(qv, forget_gate_bias->dims->size, 1);
  TF_LITE_ENSURE_EQ(qv, forget_gate_bias->dims->data[0], fu);

  const TfLiteTensor* cell_gate_bias =
      GetInput(qv, gp, lstm::full::kCellGateBiasTensor);
  TF_LITE_ENSURE_EQ(qv, cell_gate_bias->dims->size, 1);
  TF_LITE_ENSURE_EQ(qv, cell_gate_bias->dims->data[0], fu);

  const TfLiteTensor* output_gate_bias =
      GetInput(qv, gp, lstm::full::kOutputGateBiasTensor);
  TF_LITE_ENSURE_EQ(qv, output_gate_bias->dims->size, 1);
  TF_LITE_ENSURE_EQ(qv, output_gate_bias->dims->data[0], fu);

  const TfLiteTensor* projection_weights = GetOptionalInputTensor(
      qv, gp, lstm::full::kProjectionWeightsTensor);
  if (projection_weights != nullptr) {
    TF_LITE_ENSURE_EQ(qv, projection_weights->dims->size, 2);
    TF_LITE_ENSURE_EQ(qv, projection_weights->dims->data[0], jk);
    TF_LITE_ENSURE_EQ(qv, projection_weights->dims->data[1], fu);
  }

  const TfLiteTensor* projection_bias =
      GetOptionalInputTensor(qv, gp, lstm::full::kProjectionBiasTensor);
  if (projection_bias != nullptr) {
    TF_LITE_ENSURE_EQ(qv, projection_bias->dims->size, 1);
    TF_LITE_ENSURE_EQ(qv, projection_bias->dims->data[0], jk);
  }






  const bool projecton_tensors_consistent =
      ((projection_weights != nullptr) || (projection_bias == nullptr));
  TF_LITE_ENSURE(qv, projecton_tensors_consistent == true);

  if (xb) {
    const TfLiteTensor* input_layer_norm_coefficients = GetOptionalInputTensor(
        qv, gp, lstm::full::kInputLayerNormCoefficientsTensor);
    if (use_cifg) {
      TF_LITE_ENSURE_EQ(qv, input_layer_norm_coefficients, nullptr);
    } else {
      TF_LITE_ENSURE(qv, input_layer_norm_coefficients != nullptr);
      TF_LITE_ENSURE_EQ(qv, input_layer_norm_coefficients->dims->size, 1);
      TF_LITE_ENSURE_EQ(qv, input_layer_norm_coefficients->dims->data[0],
                        fu);
      TF_LITE_ENSURE_TYPES_EQ(qv, input_layer_norm_coefficients->type,
                              kTfLiteFloat32);
    }

    const TfLiteTensor* forget_layer_norm_coefficients =
        GetInput(qv, gp, lstm::full::kForgetLayerNormCoefficientsTensor);
    TF_LITE_ENSURE(qv, forget_layer_norm_coefficients != nullptr);
    TF_LITE_ENSURE_EQ(qv, forget_layer_norm_coefficients->dims->size, 1);
    TF_LITE_ENSURE_EQ(qv, forget_layer_norm_coefficients->dims->data[0],
                      fu);
    TF_LITE_ENSURE_TYPES_EQ(qv, forget_layer_norm_coefficients->type,
                            kTfLiteFloat32);

    const TfLiteTensor* cell_layer_norm_coefficients =
        GetInput(qv, gp, lstm::full::kCellLayerNormCoefficientsTensor);
    TF_LITE_ENSURE(qv, cell_layer_norm_coefficients != nullptr);
    TF_LITE_ENSURE_EQ(qv, cell_layer_norm_coefficients->dims->size, 1);
    TF_LITE_ENSURE_EQ(qv, cell_layer_norm_coefficients->dims->data[0],
                      fu);
    TF_LITE_ENSURE_TYPES_EQ(qv, cell_layer_norm_coefficients->type,
                            kTfLiteFloat32);

    const TfLiteTensor* output_layer_norm_coefficients =
        GetInput(qv, gp, lstm::full::kOutputLayerNormCoefficientsTensor);
    TF_LITE_ENSURE(qv, output_layer_norm_coefficients != nullptr);
    TF_LITE_ENSURE_EQ(qv, output_layer_norm_coefficients->dims->size, 1);
    TF_LITE_ENSURE_EQ(qv, output_layer_norm_coefficients->dims->data[0],
                      fu);
    TF_LITE_ENSURE_TYPES_EQ(qv, output_layer_norm_coefficients->type,
                            kTfLiteFloat32);
  }

  return kTfLiteOk;
}

static noinline void ip(struct list_head *qd)
{
while (!list_empty(qd)) {
struct key *key =
list_entry(qd->next, struct key, graveyard_link);
list_del(&key->graveyard_link);
kdebug("- %u", key->serial);
key_check(key);
if (key->type->destroy)
key->type->destroy(key);
security_key_free(key);
if (test_bit(KEY_FLAG_IN_QUOTA, &key->flags)) {
spin_lock(&key->user->lock);
key->user->qnkeys--;
key->user->qnbytes -= key->quotalen;
spin_unlock(&key->user->lock);
}
atomic_dec(&key->user->nkeys);
if (test_bit(KEY_FLAG_INSTANTIATED, &key->flags))
atomic_dec(&key->user->nikeys);
key_user_put(key->user);
kfree(key->description);
#ifdef KEY_DEBUGGING
key->magic = KEY_DEBUG_MAGIC_X;
#endif
kmem_cache_free(key_jar, key);
}
}

