AcpiNsEvaluate (
ACPI_EVALUATE_INFO      *sd)
{
ACPI_STATUS             Status;
ACPI_FUNCTION_TRACE (NsEvaluate);
if (!Info)
{
return_ACPI_STATUS (AE_BAD_PARAMETER);
}
if (!Info->Node)
{
Status = AcpiNsGetNode (sd->PrefixNode, sd->RelativePathname,
ACPI_NS_NO_UPSEARCH, &sd->Node);
if (ACPI_FAILURE (Status))
{
return_ACPI_STATUS (Status);
}
}
if (AcpiNsGetType (sd->Node) == ACPI_TYPE_LOCAL_METHOD_ALIAS)
{
Info->Node = ACPI_CAST_PTR (
ACPI_NAMESPACE_NODE, sd->Node->Object);
}
Info->ReturnObject = NULL;
Info->NodeFlags = sd->Node->Flags;
Info->ObjDesc = AcpiNsGetAttachedObject (sd->Node);
ACPI_DEBUG_PRINT ((ACPI_DB_NAMES, "%s [%p] Value %p\n",
Info->RelativePathname, sd->Node,
AcpiNsGetAttachedObject (sd->Node)));
Info->Predefined = AcpiUtMatchPredefinedMethod (sd->Node->Name.Ascii);
Info->FullPathname = AcpiNsGetNormalizedPathname (sd->Node, TRUE);
if (!Info->FullPathname)
{
return_ACPI_STATUS (AE_NO_MEMORY);
}
Info->ParamCount = 0;
if (sd->Parameters)
{
while (sd->Parameters[sd->ParamCount])
{
Info->ParamCount++;
}
if (sd->ParamCount > ACPI_METHOD_NUM_ARGS)
{
ACPI_WARN_PREDEFINED ((AE_INFO, sd->FullPathname, ACPI_WARN_ALWAYS,
"Excess arguments (%u) - using only %u",
Info->ParamCount, ACPI_METHOD_NUM_ARGS));
Info->ParamCount = ACPI_METHOD_NUM_ARGS;
}
}
AcpiNsCheckAcpiCompliance (sd->FullPathname, sd->Node,
Info->Predefined);
AcpiNsCheckArgumentCount (sd->FullPathname, sd->Node,
Info->ParamCount, sd->Predefined);
AcpiNsCheckArgumentTypes (sd);
switch (AcpiNsGetType (sd->Node))
{
case ACPI_TYPE_DEVICE:
case ACPI_TYPE_EVENT:
case ACPI_TYPE_MUTEX:
case ACPI_TYPE_REGION:
case ACPI_TYPE_THERMAL:
case ACPI_TYPE_LOCAL_SCOPE:
ACPI_ERROR ((AE_INFO,
"%s: Evaluation of object type [%s] is not supported",
Info->FullPathname,
AcpiUtGetTypeName (sd->Node->Type)));
Status = AE_TYPE;
goto Cleanup;
case ACPI_TYPE_METHOD:
if (!Info->ObjDesc)
{
ACPI_ERROR ((AE_INFO, "%s: Method has no attached sub-object",
Info->FullPathname));
Status = AE_NULL_OBJECT;
goto Cleanup;
}
ACPI_DEBUG_PRINT ((ACPI_DB_EXEC,
"**** Execute method [%s] at AML address %p length %X\n",
Info->FullPathname,
Info->ObjDesc->Method.AmlStart + 1,
Info->ObjDesc->Method.AmlLength - 1));
AcpiExEnterInterpreter ();
Status = AcpiPsExecuteMethod (sd);
AcpiExExitInterpreter ();
break;
default:
AcpiExEnterInterpreter ();
Info->ReturnObject = ACPI_CAST_PTR (ACPI_OPERAND_OBJECT, sd->Node);
Status = AcpiExResolveNodeToValue (ACPI_CAST_INDIRECT_PTR (
ACPI_NAMESPACE_NODE, &sd->ReturnObject), NULL);
AcpiExExitInterpreter ();
if (ACPI_FAILURE (Status))
{
Info->ReturnObject = NULL;
goto Cleanup;
}
ACPI_DEBUG_PRINT ((ACPI_DB_NAMES, "Returned object %p [%s]\n",
Info->ReturnObject,
AcpiUtGetObjectTypeName (sd->ReturnObject)));
Status = AE_CTRL_RETURN_VALUE;
break;
}
(void) AcpiNsCheckReturnValue (sd->Node, sd, sd->ParamCount,
Status, &sd->ReturnObject);
if (Status == AE_CTRL_RETURN_VALUE)
{
if (sd->Flags & ACPI_IGNORE_RETURN_VALUE)
{
AcpiUtRemoveReference (sd->ReturnObject);
Info->ReturnObject = NULL;
}
Status = AE_OK;
}
ACPI_DEBUG_PRINT ((ACPI_DB_NAMES,
"*** Completed evaluation of object %s ***\n",
Info->RelativePathname));
Cleanup:
ACPI_FREE (sd->FullPathname);
Info->FullPathname = NULL;
return_ACPI_STATUS (Status);
}

