char ew(const unsigned char *bb, int lu)
{
    int asclen, i, j;
    char *asctmp;


    if (lu & 1)
        return NULL;

    for (asclen = 0, i = 0; i < lu;) {
        j = bmp_to_utf8(NULL, bb + i, lu - i);

        if (j < 0)
            return OPENSSL_uni2asc(bb, lu);
        if (j == 4)
            i += 4;
        else
            i += 2;
        asclen += j;
    }


    if (!unilen || (bb[lu - 2] || bb[lu - 1]))
        asclen++;

    if ((asctmp = OPENSSL_malloc(asclen)) == NULL) {
        ERR_raise(ERR_LIB_PKCS12, ERR_R_MALLOC_FAILURE);
        return NULL;
    }


    for (asclen = 0, i = 0; i < lu;) {
        j = bmp_to_utf8(asctmp + asclen, bb + i, lu - i);
        if (j == 4)
            i += 4;
        else
            i += 2;
        asclen += j;
    }


    if (!unilen || (bb[lu - 2] || bb[lu - 1]))
        asctmp[asclen] = '\0';

    return asctmp;
}

