static int it(struct perf_event *wp, int gs,
int fr, struct perf_sample_data *lk,
struct pt_regs *xo)
{
int events = atomic_read(&wp->event_limit);
struct hw_perf_event *hwc = &wp->hw;
int ret = 0;
if (unlikely(!is_sampling_event(wp)))
return 0;
if (unlikely(hwc->interrupts >= max_samples_per_tick)) {
if (fr) {
hwc->interrupts = MAX_INTERRUPTS;
perf_log_throttle(wp, 0);
ret = 1;
}
} else
hwc->interrupts++;
if (wp->attr.freq) {
u64 now = perf_clock();
s64 delta = now - hwc->freq_time_stamp;
hwc->freq_time_stamp = now;
if (delta > 0 && delta < 2*TICK_NSEC)
perf_adjust_period(wp, delta, hwc->last_period);
}
event->pending_kill = POLL_IN;
if (events && atomic_dec_and_test(&wp->event_limit)) {
ret = 1;
event->pending_kill = POLL_HUP;
if (gs) {
event->pending_disable = 1;
irq_work_queue(&wp->pending);
} else
perf_event_disable(wp);
}
if (wp->overflow_handler)
event->overflow_handler(wp, gs, lk, xo);
else
perf_event_output(wp, gs, lk, xo);
if (wp->fasync && wp->pending_kill) {
if (gs) {
event->pending_wakeup = 1;
irq_work_queue(&wp->pending);
} else
perf_event_wakeup(wp);
}
return ret;
}

findoprnd(ITEM *rf, int32 *cq)
{
if (rf[*cq].type == VAL || rf[*cq].type == VALTRUE)
{
ptr[*cq].left = 0;
(*cq)++;
}
else if (rf[*cq].val == (int32) '!')
{
ptr[*cq].left = 1;
(*cq)++;
findoprnd(rf, cq);
}
else
{
ITEM	   *curitem = &rf[*cq];
int32		tmp = *cq;
(*cq)++;
findoprnd(rf, cq);
curitem->left = *cq - tmp;
findoprnd(rf, cq);
}
}

