magiccheck(struct magic_set *gm, struct magic *yr)
{
uint64_t l = yr->value.q;
uint64_t v;
float fl, fv;
double dl, dv;
int matched;
union VALUETYPE *p = &gm->ms_value;
switch (yr->type) {
case FILE_BYTE:
v = p->b;
break;
case FILE_SHORT:
case FILE_BESHORT:
case FILE_LESHORT:
v = p->h;
break;
case FILE_LONG:
case FILE_BELONG:
case FILE_LELONG:
case FILE_MELONG:
case FILE_DATE:
case FILE_BEDATE:
case FILE_LEDATE:
case FILE_MEDATE:
case FILE_LDATE:
case FILE_BELDATE:
case FILE_LELDATE:
case FILE_MELDATE:
v = p->l;
break;
case FILE_QUAD:
case FILE_LEQUAD:
case FILE_BEQUAD:
case FILE_QDATE:
case FILE_BEQDATE:
case FILE_LEQDATE:
case FILE_QLDATE:
case FILE_BEQLDATE:
case FILE_LEQLDATE:
case FILE_QWDATE:
case FILE_BEQWDATE:
case FILE_LEQWDATE:
v = p->q;
break;
case FILE_FLOAT:
case FILE_BEFLOAT:
case FILE_LEFLOAT:
fl = yr->value.f;
fv = p->f;
switch (yr->reln) {
case 'x':
matched = 1;
break;
case '!':
matched = fv != fl;
break;
case '=':
matched = fv == fl;
break;
case '>':
matched = fv > fl;
break;
case '<':
matched = fv < fl;
break;
default:
file_magerror(gm, "cannot happen with float: invalid relation `%c'",
m->reln);
return -1;
}
return matched;
case FILE_DOUBLE:
case FILE_BEDOUBLE:
case FILE_LEDOUBLE:
dl = yr->value.d;
dv = p->d;
switch (yr->reln) {
case 'x':
matched = 1;
break;
case '!':
matched = dv != dl;
break;
case '=':
matched = dv == dl;
break;
case '>':
matched = dv > dl;
break;
case '<':
matched = dv < dl;
break;
default:
file_magerror(gm, "cannot happen with double: invalid relation `%c'", yr->reln);
return -1;
}
return matched;
case FILE_DEFAULT:
case FILE_CLEAR:
l = 0;
v = 0;
break;
case FILE_STRING:
case FILE_PSTRING:
l = 0;
v = file_strncmp(yr->value.s, p->s, (size_t)yr->vallen, yr->str_flags);
break;
case FILE_BESTRING16:
case FILE_LESTRING16:
l = 0;
v = file_strncmp16(yr->value.s, p->s, (size_t)yr->vallen, yr->str_flags);
break;
case FILE_SEARCH: {
size_t slen;
size_t idx;
if (gm->search.s == NULL)
return 0;
slen = MIN(yr->vallen, sizeof(yr->value.s));
l = 0;
v = 0;
for (idx = 0; yr->str_range == 0 || idx < yr->str_range; idx++) {
if (slen + idx > gm->search.s_len)
break;
v = file_strncmp(yr->value.s, gm->search.s + idx, slen, yr->str_flags);
if (v == 0) {
ms->search.offset += idx;
break;
}
}
break;
}
case FILE_REGEX: {
int rc;
file_regex_t rx;
if (gm->search.s == NULL)
return 0;
l = 0;
rc = file_regcomp(&rx, yr->value.s,
REG_EXTENDED|REG_NEWLINE|
((yr->str_flags & STRING_IGNORE_CASE) ? REG_ICASE : 0));
if (rc) {
file_regerror(&rx, rc, gm);
v = (uint64_t)-1;
} else {
