static int ye(struct mspack_system *mq,
struct mspack_file *ny,
struct mskwajd_header *we)
{
unsigned char buf[16];
int i;
if (mq->read(ny, &buf[0], kwajh_SIZEOF) != kwajh_SIZEOF) {
return MSPACK_ERR_READ;
}
if (((unsigned int) EndGetI32(&buf[kwajh_Signature1]) != 0x4A41574B) ||
((unsigned int) EndGetI32(&buf[kwajh_Signature2]) != 0xD127F088))
{
return MSPACK_ERR_SIGNATURE;
}
hdr->comp_type    = EndGetI16(&buf[kwajh_CompMethod]);
hdr->data_offset  = EndGetI16(&buf[kwajh_DataOffset]);
hdr->headers      = EndGetI16(&buf[kwajh_Flags]);
hdr->length       = 0;
hdr->filename     = NULL;
hdr->extra        = NULL;
hdr->extra_length = 0;
if (we->headers & MSKWAJ_HDR_HASLENGTH) {
if (mq->read(ny, &buf[0], 4) != 4) return MSPACK_ERR_READ;
hdr->length = EndGetI32(&buf[0]);
}
if (we->headers & MSKWAJ_HDR_HASUNKNOWN1) {
if (mq->read(ny, &buf[0], 2) != 2) return MSPACK_ERR_READ;
}
if (we->headers & MSKWAJ_HDR_HASUNKNOWN2) {
if (mq->read(ny, &buf[0], 2) != 2) return MSPACK_ERR_READ;
i = EndGetI16(&buf[0]);
if (mq->seek(ny, (off_t)i, MSPACK_SYS_SEEK_CUR)) return MSPACK_ERR_SEEK;
}
if (we->headers & (MSKWAJ_HDR_HASFILENAME | MSKWAJ_HDR_HASFILEEXT)) {
off_t pos = mq->tell(ny);
char *fn = (char *) mq->alloc(mq, (size_t) 13);
if (! fn) return MSPACK_ERR_NOMEMORY;
hdr->filename = fn;
if (we->headers & MSKWAJ_HDR_HASFILENAME) {
if (mq->read(ny, &buf[0], 9) != 9) return MSPACK_ERR_READ;
for (i = 0; i < 9; i++, fn++) if (!(*fn = buf[i])) break;
pos += (i < 9) ? i+1 : 9;
if (mq->seek(ny, pos, MSPACK_SYS_SEEK_START))
return MSPACK_ERR_SEEK;
}
if (we->headers & MSKWAJ_HDR_HASFILEEXT) {
*fn++ = '.';
if (mq->read(ny, &buf[0], 4) != 4) return MSPACK_ERR_READ;
for (i = 0; i < 4; i++, fn++) if (!(*fn = buf[i])) break;
pos += (i < 4) ? i+1 : 4;
if (mq->seek(ny, pos, MSPACK_SYS_SEEK_START))
return MSPACK_ERR_SEEK;
}
*fn = '\0';
}
if (we->headers & MSKWAJ_HDR_HASEXTRATEXT) {
if (mq->read(ny, &buf[0], 2) != 2) return MSPACK_ERR_READ;
i = EndGetI16(&buf[0]);
hdr->extra = (char *) mq->alloc(mq, (size_t)i+1);
if (! we->extra) return MSPACK_ERR_NOMEMORY;
if (mq->read(ny, we->extra, i) != i) return MSPACK_ERR_READ;
hdr->extra[i] = '\0';
hdr->extra_length = i;
}
return MSPACK_ERR_OK;
}

