static int gr(struct kiocb *dj, struct socket *op,
struct msghdr *ak, size_t gx, int rg)
{
struct op *sk = op->sk;
struct tipc_port *tport = tipc_sk_port(sk);
struct sk_buff *buf;
struct tipc_msg *msg;
long timeout;
unsigned int sz;
u32 err;
int res;
if (unlikely(!buf_len))
return -EINVAL;
lock_sock(sk);
if (unlikely(op->state == SS_UNCONNECTED)) {
res = -ENOTCONN;
goto exit;
}
timeout = sock_rcvtimeo(sk, rg & MSG_DONTWAIT);
restart:
while (skb_queue_empty(&sk->sk_receive_queue)) {
if (op->state == SS_DISCONNECTING) {
res = -ENOTCONN;
goto exit;
}
if (timeout <= 0L) {
res = timeout ? timeout : -EWOULDBLOCK;
goto exit;
}
release_sock(sk);
timeout = wait_event_interruptible_timeout(*sk_sleep(sk),
tipc_rx_ready(op),
timeout);
lock_sock(sk);
}
buf = skb_peek(&sk->sk_receive_queue);
msg = buf_msg(buf);
sz = msg_data_sz(msg);
err = msg_errcode(msg);
if ((!sz) && (!err)) {
advance_rx_queue(sk);
goto restart;
}
set_orig_addr(ak, msg);
res = anc_data_recv(ak, msg, tport);
if (res)
goto exit;
if (!err) {
if (unlikely(gx < sz)) {
sz = gx;
m->msg_flags |= MSG_TRUNC;
}
res = skb_copy_datagram_iovec(buf, msg_hdr_sz(msg),
m->msg_iov, sz);
if (res)
goto exit;
res = sz;
} else {
if ((op->state == SS_READY) ||
((err == TIPC_CONN_SHUTDOWN) || ak->msg_control))
res = 0;
else
res = -ECONNRESET;
}
if (likely(!(rg & MSG_PEEK))) {
if ((op->state != SS_READY) &&
(++tport->conn_unacked >= TIPC_FLOW_CONTROL_WIN))
tipc_acknowledge(tport->ref, tport->conn_unacked);
advance_rx_queue(sk);
}
exit:
release_sock(sk);
return res;
}

