void WT_VoiceGain (S_WT_VOICE *jg, S_WT_INT_FRAME *zw)
{
EAS_I32 *pMixBuffer;
EAS_PCM *pInputBuffer;
EAS_I32 gain;
EAS_I32 gainIncrement;
EAS_I32 tmp0;
EAS_I32 tmp1;
EAS_I32 tmp2;
EAS_I32 numSamples;
#if (NUM_OUTPUT_CHANNELS == 2)
EAS_I32 gainLeft, gainRight;
#endif
numSamples = zw->numSamples;
pMixBuffer = zw->pMixBuffer;
pInputBuffer = zw->pAudioBuffer;
gainIncrement = (zw->frame.gainTarget - zw->prevGain) << (16 - SYNTH_UPDATE_PERIOD_IN_BITS);
if (gainIncrement < 0)
gainIncrement++;
gain = zw->prevGain << 16;
#if (NUM_OUTPUT_CHANNELS == 2)
gainLeft = jg->gainLeft;
gainRight = jg->gainRight;
#endif
while (numSamples--) {
tmp0 = *pInputBuffer++;
gain += gainIncrement;
tmp2 = gain >> 16;
tmp2 *= tmp0;
#if (NUM_OUTPUT_CHANNELS == 2)
tmp2 = tmp2 >> 14;
tmp1 = *pMixBuffer;
tmp0 = tmp2 * gainLeft;
tmp0 = tmp0 >> NUM_MIXER_GUARD_BITS;
tmp1 += tmp0;
*pMixBuffer++ = tmp1;
tmp1 = *pMixBuffer;
tmp0 = tmp2 * gainRight;
tmp0 = tmp0 >> NUM_MIXER_GUARD_BITS;
tmp1 += tmp0;
*pMixBuffer++ = tmp1;
#else
tmp1 = *pMixBuffer;
tmp2 = tmp2 >> (NUM_MIXER_GUARD_BITS - 1);
tmp1 += tmp2;
*pMixBuffer++ = tmp1;
#endif
}
}

