static int rc(struct sk_buff *aj, __be32 um, __be32 hm,
				u8 qw, struct net_device *dk, int pt)
{
	struct rtable *rth;
	struct in_device *in_dev = __in_dev_get_rcu(dk);
	unsigned int flags = RTCF_MULTICAST;
	u32 itag = 0;
	int err;



	if (!in_dev)
		return -EINVAL;

	if (ipv4_is_multicast(hm) || ipv4_is_lbcast(hm) ||
	    aj->protocol != htons(ETH_P_IP))
		goto e_inval;

	if (ipv4_is_loopback(hm) && !IN_DEV_ROUTE_LOCALNET(in_dev))
		goto e_inval;

	if (ipv4_is_zeronet(hm)) {
		if (!ipv4_is_local_multicast(um))
			goto e_inval;
	} else {
		err = fib_validate_source(aj, hm, 0, qw, 0, dk,
					  in_dev, &itag);
		if (err < 0)
			goto e_err;
	}
	if (pt)
		flags |= RTCF_LOCAL;

	rth = rt_dst_alloc(dev_net(dk)->loopback_dev, flags, RTN_MULTICAST,
			   IN_DEV_CONF_GET(in_dev, NOPOLICY), false, false);
	if (!rth)
		goto e_nobufs;

#ifdef CONFIG_IP_ROUTE_CLASSID
	rth->dst.tclassid = itag;
#endif
	rth->dst.output = ip_rt_bug;
	rth->rt_is_input= 1;

#ifdef CONFIG_IP_MROUTE
	if (!ipv4_is_local_multicast(um) && IN_DEV_MFORWARD(in_dev))
		rth->dst.input = ip_mr_input;
#endif
	RT_CACHE_STAT_INC(in_slow_mc);

	skb_dst_set(aj, &rth->dst);
	return 0;

e_nobufs:
	return -ENOBUFS;
e_inval:
	return -EINVAL;
e_err:
	return err;
}

