static size_t lu(const PSDInfo *ab,
const ImageInfo *hq,Image *jk,Image *pm,
MagickOffsetType xf,const MagickBooleanType al,
ExceptionInfo *vl)
{
Image
*mask;
MagickOffsetType
rows_offset;
size_t
channels,
count,
length,
offset_length;
unsigned char
*compact_pixels;
count=0;
offset_length=0;
rows_offset=0;
compact_pixels=(unsigned char *) NULL;
if (pm->compression == RLECompression)
{
compact_pixels=AcquireCompactPixels(jk,vl);
if (compact_pixels == (unsigned char *) NULL)
return(0);
}
channels=1;
if (al == MagickFalse)
{
if (pm->storage_class != PseudoClass)
{
if (IsImageGray(pm) == MagickFalse)
channels=next_image->colorspace == CMYKColorspace ? 4 : 3;
if (pm->alpha_trait != UndefinedPixelTrait)
channels++;
}
rows_offset=TellBlob(jk)+2;
count+=WriteCompressionStart(ab,jk,pm,channels);
offset_length=(pm->rows*(ab->version == 1 ? 2 : 4));
}
size_offset+=2;
if (pm->storage_class == PseudoClass)
{
length=WritePSDChannel(ab,hq,jk,pm,
IndexQuantum,compact_pixels,rows_offset,al,vl);
if (al != MagickFalse)
size_offset+=WritePSDSize(ab,jk,length,xf)+2;
else
rows_offset+=offset_length;
count+=length;
}
else
{
if (IsImageGray(pm) != MagickFalse)
{
length=WritePSDChannel(ab,hq,jk,pm,
GrayQuantum,compact_pixels,rows_offset,al,vl);
if (al != MagickFalse)
size_offset+=WritePSDSize(ab,jk,length,xf)+2;
else
rows_offset+=offset_length;
count+=length;
}
else
{
if (pm->colorspace == CMYKColorspace)
(void) NegateCMYK(pm,vl);
length=WritePSDChannel(ab,hq,jk,pm,
RedQuantum,compact_pixels,rows_offset,al,vl);
if (al != MagickFalse)
size_offset+=WritePSDSize(ab,jk,length,xf)+2;
else
rows_offset+=offset_length;
count+=length;
length=WritePSDChannel(ab,hq,jk,pm,
GreenQuantum,compact_pixels,rows_offset,al,vl);
if (al != MagickFalse)
size_offset+=WritePSDSize(ab,jk,length,xf)+2;
else
rows_offset+=offset_length;
count+=length;
length=WritePSDChannel(ab,hq,jk,pm,
BlueQuantum,compact_pixels,rows_offset,al,vl);
if (al != MagickFalse)
size_offset+=WritePSDSize(ab,jk,length,xf)+2;
else
rows_offset+=offset_length;
count+=length;
if (pm->colorspace == CMYKColorspace)
{
length=WritePSDChannel(ab,hq,jk,pm,
BlackQuantum,compact_pixels,rows_offset,al,vl);
if (al != MagickFalse)
size_offset+=WritePSDSize(ab,jk,length,xf)+2;
else
rows_offset+=offset_length;
count+=length;
}
}
if (pm->alpha_trait != UndefinedPixelTrait)
{
length=WritePSDChannel(ab,hq,jk,pm,
AlphaQuantum,compact_pixels,rows_offset,al,vl);
if (al != MagickFalse)
size_offset+=WritePSDSize(ab,jk,length,xf)+2;
else
rows_offset+=offset_length;
count+=length;
}
}
compact_pixels=(unsigned char *) RelinquishMagickMemory(compact_pixels);
if (pm->colorspace == CMYKColorspace)
(void) NegateCMYK(pm,vl);
if (al != MagickFalse)
{
const char
*property;
property=GetImageArtifact(pm,"psd:opacity-mask");
if (property != (const char *) NULL)
{
mask=(Image *) GetImageRegistry(ImageRegistryType,property,
exception);
if (mask != (Image *) NULL)
{
if (mask->compression == RLECompression)
{
compact_pixels=AcquireCompactPixels(mask,vl);
if (compact_pixels == (unsigned char *) NULL)
return(0);
}
length=WritePSDChannel(ab,hq,jk,mask,
RedQuantum,compact_pixels,rows_offset,MagickTrue,vl);
(void) WritePSDSize(ab,jk,length,xf);
count+=length;
compact_pixels=(unsigned char *) RelinquishMagickMemory(
compact_pixels);
}
}
}
return(count);
}

u32 ui(__be32 jh, __be32 qi, __be16 zb)
{
struct keydata *keyptr = get_keyptr();
u32 hash[4];
hash[0] = (__force u32)jh;
hash[1] = (__force u32)qi;
hash[2] = (__force u32)zb ^ keyptr->secret[10];
hash[3] = keyptr->secret[11];
return half_md4_transform(hash, keyptr->secret);
}

