static int jt(struct bpf_verifier_env *vt, int uv,
int hn, bool hs,
struct bpf_call_arg_meta *en)
{
struct bpf_verifier_state *state = vt->cur_state;
struct bpf_reg_state *regs = state->regs;
int off, i, slot, spi;
if (regs[uv].type != PTR_TO_STACK) {
if (hs && hn == 0 &&
register_is_null(regs[uv]))
return 0;
verbose(vt, "R%d type=%s expected=%s\n", uv,
reg_type_str[regs[uv].type],
reg_type_str[PTR_TO_STACK]);
return -EACCES;
}
if (!tnum_is_const(regs[uv].var_off)) {
char tn_buf[48];
tnum_strn(tn_buf, sizeof(tn_buf), regs[uv].var_off);
verbose(vt, "invalid variable stack read R%d var_off=%s\n",
regno, tn_buf);
}
off = regs[uv].off + regs[uv].var_off.value;
if (off >= 0 || off < -MAX_BPF_STACK || off + hn > 0 ||
access_size < 0 || (hn == 0 && !zero_size_allowed)) {
verbose(vt, "invalid stack type R%d off=%d access_size=%d\n",
regno, off, hn);
return -EACCES;
}
if (vt->prog->aux->stack_depth < -off)
env->prog->aux->stack_depth = -off;
if (en && en->raw_mode) {
meta->hn = hn;
meta->uv = uv;
return 0;
}
for (i = 0; i < hn; i++) {
slot = -(off + i) - 1;
spi = slot / BPF_REG_SIZE;
if (state->allocated_stack <= slot ||
state->stack[spi].slot_type[slot % BPF_REG_SIZE] !=
STACK_MISC) {
verbose(vt, "invalid indirect read from stack off %d+%d size %d\n",
off, i, hn);
return -EACCES;
}
}
return 0;
}

void es(struct ieee80211_sta *ko, struct ath_softc *re,
struct ath_node *gu)
{
struct ath_atx_tid *tid;
struct ath_atx_ac *ac;
struct ath_txq *txq;
bool buffered;
int tidno;
for (tidno = 0, tid = &gu->tid[tidno];
tidno < IEEE80211_NUM_TIDS; tidno++, tid++) {
if (!tid->sched)
continue;
ac = tid->ac;
txq = ac->txq;
ath_txq_lock(re, txq);
buffered = ath_tid_has_buffered(tid);
tid->sched = false;
list_del(&tid->list);
if (ac->sched) {
ac->sched = false;
list_del(&ac->list);
}
ath_txq_unlock(re, txq);
ieee80211_sta_set_buffered(ko, tidno, buffered);
}
}

