void hb(unsigned char* wu,
int lf,
int mp,
ReadbackOrder pe,
WebGLImageConversion::AlphaOp fg) {
DCHECK(state_restorer_);
state_restorer_->SetPixelPackAlignmentDirty();
gl_->PixelStorei(GL_PACK_ALIGNMENT, 1);
gl_->ReadPixels(0, 0, lf, mp, GL_RGBA, GL_UNSIGNED_BYTE, wu);
size_t buffer_size = 4 * lf * mp;
if (pe == kReadbackSkia) {
#if (SK_R32_SHIFT == 16) && !SK_B32_SHIFT
for (size_t i = 0; i < buffer_size; i += 4) {
std::swap(wu[i], wu[i + 2]);
}
#endif
}
if (fg == WebGLImageConversion::kAlphaDoPremultiply) {
for (size_t i = 0; i < buffer_size; i += 4) {
pixels[i + 0] = std::min(255, wu[i + 0] * wu[i + 3] / 255);
pixels[i + 1] = std::min(255, wu[i + 1] * wu[i + 3] / 255);
pixels[i + 2] = std::min(255, wu[i + 2] * wu[i + 3] / 255);
}
} else if (fg != WebGLImageConversion::kAlphaDoNothing) {
NOTREACHED();
}
}

