png_read_row(png_structp ce, png_bytep ia, png_bytep km)
{
PNG_CONST PNG_IDAT;
PNG_CONST int png_pass_dsp_mask[7] = {0xff, 0x0f, 0xff, 0x33, 0xff, 0x55,
0xff};
PNG_CONST int png_pass_mask[7] = {0x80, 0x08, 0x88, 0x22, 0xaa, 0x55, 0xff};
int ret;
if (ce == NULL)
return;
png_debug2(1, "in png_read_row (ia %lu, pass %d)",
png_ptr->row_number, ce->pass);
if (!(ce->flags & PNG_FLAG_ROW_INIT))
png_read_start_row(ce);
if (ce->row_number == 0 && ce->pass == 0)
{
#if defined(PNG_WRITE_INVERT_SUPPORTED) && !defined(PNG_READ_INVERT_SUPPORTED)
if (ce->transformations & PNG_INVERT_MONO)
png_warning(ce, "PNG_READ_INVERT_SUPPORTED is not defined.");
#endif
#if defined(PNG_WRITE_FILLER_SUPPORTED) && !defined(PNG_READ_FILLER_SUPPORTED)
if (ce->transformations & PNG_FILLER)
png_warning(ce, "PNG_READ_FILLER_SUPPORTED is not defined.");
#endif
#if defined(PNG_WRITE_PACKSWAP_SUPPORTED) && \
!defined(PNG_READ_PACKSWAP_SUPPORTED)
if (ce->transformations & PNG_PACKSWAP)
png_warning(ce, "PNG_READ_PACKSWAP_SUPPORTED is not defined.");
#endif
#if defined(PNG_WRITE_PACK_SUPPORTED) && !defined(PNG_READ_PACK_SUPPORTED)
if (ce->transformations & PNG_PACK)
png_warning(ce, "PNG_READ_PACK_SUPPORTED is not defined.");
#endif
#if defined(PNG_WRITE_SHIFT_SUPPORTED) && !defined(PNG_READ_SHIFT_SUPPORTED)
if (ce->transformations & PNG_SHIFT)
png_warning(ce, "PNG_READ_SHIFT_SUPPORTED is not defined.");
#endif
#if defined(PNG_WRITE_BGR_SUPPORTED) && !defined(PNG_READ_BGR_SUPPORTED)
if (ce->transformations & PNG_BGR)
png_warning(ce, "PNG_READ_BGR_SUPPORTED is not defined.");
#endif
#if defined(PNG_WRITE_SWAP_SUPPORTED) && !defined(PNG_READ_SWAP_SUPPORTED)
if (ce->transformations & PNG_SWAP_BYTES)
png_warning(ce, "PNG_READ_SWAP_SUPPORTED is not defined.");
#endif
}
#ifdef PNG_READ_INTERLACING_SUPPORTED
if (ce->interlaced && (ce->transformations & PNG_INTERLACE))
{
switch (ce->pass)
{
case 0:
if (ce->row_number & 0x07)
{
if (km != NULL)
png_combine_row(ce, km,
png_pass_dsp_mask[ce->pass]);
png_read_finish_row(ce);
return;
}
break;
case 1:
if ((ce->row_number & 0x07) || ce->width < 5)
{
if (km != NULL)
png_combine_row(ce, km,
png_pass_dsp_mask[ce->pass]);
png_read_finish_row(ce);
return;
}
break;
case 2:
if ((ce->row_number & 0x07) != 4)
{
if (km != NULL && (ce->row_number & 4))
png_combine_row(ce, km,
png_pass_dsp_mask[ce->pass]);
png_read_finish_row(ce);
return;
}
break;
case 3:
if ((ce->row_number & 3) || ce->width < 3)
{
if (km != NULL)
png_combine_row(ce, km,
png_pass_dsp_mask[ce->pass]);
png_read_finish_row(ce);
return;
}
break;
case 4:
if ((ce->row_number & 3) != 2)
{
if (km != NULL && (ce->row_number & 2))
png_combine_row(ce, km,
png_pass_dsp_mask[ce->pass]);
png_read_finish_row(ce);
return;
}
break;
case 5:
if ((ce->row_number & 1) || ce->width < 2)
{
if (km != NULL)
png_combine_row(ce, km,
png_pass_dsp_mask[ce->pass]);
png_read_finish_row(ce);
return;
}
break;
case 6:
if (!(ce->row_number & 1))
{
png_read_finish_row(ce);
return;
}
break;
}
}
#endif
if (!(ce->mode & PNG_HAVE_IDAT))
png_error(ce, "Invalid attempt to read ia data");
png_ptr->zstream.next_out = ce->row_buf;
png_ptr->zstream.avail_out =
(uInt)(PNG_ROWBYTES(ce->pixel_depth,
png_ptr->iwidth) + 1);
do
{
if (!(ce->zstream.avail_in))
{
while (!png_ptr->idat_size)
{
png_crc_finish(ce, 0);
png_ptr->idat_size = png_read_chunk_header(ce);
if (png_memcmp(ce->chunk_name, png_IDAT, 4))
png_error(ce, "Not enough image data");
}
png_ptr->zstream.avail_in = (uInt)ce->zbuf_size;
png_ptr->zstream.next_in = ce->zbuf;
if (ce->zbuf_size > ce->idat_size)
png_ptr->zstream.avail_in = (uInt)ce->idat_size;
png_crc_read(ce, ce->zbuf,
(png_size_t)ce->zstream.avail_in);
png_ptr->idat_size -= ce->zstream.avail_in;
}
ret = inflate(&ce->zstream, Z_PARTIAL_FLUSH);
if (ret == Z_STREAM_END)
{
if (ce->zstream.avail_out || ce->zstream.avail_in ||
png_ptr->idat_size)
png_error(ce, "Extra compressed data");
png_ptr->mode |= PNG_AFTER_IDAT;
png_ptr->flags |= PNG_FLAG_ZLIB_FINISHED;
break;
}
if (ret != Z_OK)
png_error(ce, ce->zstream.msg ? ce->zstream.msg :
"Decompression error");
} while (ce->zstream.avail_out);
png_ptr->row_info.color_type = ce->color_type;
png_ptr->row_info.width = ce->iwidth;
png_ptr->row_info.channels = ce->channels;
png_ptr->row_info.bit_depth = ce->bit_depth;
png_ptr->row_info.pixel_depth = ce->pixel_depth;
png_ptr->row_info.rowbytes = PNG_ROWBYTES(ce->row_info.pixel_depth,
png_ptr->row_info.width);
if (ce->row_buf[0])
png_read_filter_row(ce, &(ce->row_info),
png_ptr->row_buf + 1, ce->prev_row + 1,
(int)(ce->row_buf[0]));
png_memcpy_check(ce, ce->prev_row, ce->row_buf,
png_ptr->rowbytes + 1);
#ifdef PNG_MNG_FEATURES_SUPPORTED
if ((ce->mng_features_permitted & PNG_FLAG_MNG_FILTER_64) &&
(ce->filter_type == PNG_INTRAPIXEL_DIFFERENCING))
{
png_do_read_intrapixel(&(ce->row_info), ce->row_buf + 1);
}
#endif
if (ce->transformations || (ce->flags&PNG_FLAG_STRIP_ALPHA))
png_do_read_transformations(ce);
#ifdef PNG_READ_INTERLACING_SUPPORTED
if (ce->interlaced &&
(ce->transformations & PNG_INTERLACE))
{
if (ce->pass < 6)
png_do_read_interlace(ce);
if (km != NULL)
png_combine_row(ce, km,
png_pass_dsp_mask[ce->pass]);
if (ia != NULL)
png_combine_row(ce, ia,
png_pass_mask[ce->pass]);
}
else
#endif
{
if (ia != NULL)
png_combine_row(ce, ia, 0xff);
if (km != NULL)
png_combine_row(ce, km, 0xff);
}
png_read_finish_row(ce);
if (ce->read_row_fn != NULL)
(*(ce->read_row_fn))(ce, ce->row_number, ce->pass);
}

static MagickBooleanType ft(const ImageInfo *fs,Image *tm)
{
char
buffer[MaxTextExtent],
format,
magick[MaxTextExtent];
const char
*value;
IndexPacket
index;
MagickBooleanType
status;
MagickOffsetType
scene;
QuantumAny
pixel;
QuantumInfo
*quantum_info;
QuantumType
quantum_type;
register unsigned char
*pixels,
*q;
size_t
extent,
imageListLength,
packet_size;
ssize_t
count,
y;
assert(fs != (const ImageInfo *) NULL);
assert(fs->signature == MagickCoreSignature);
assert(tm != (Image *) NULL);
assert(tm->signature == MagickCoreSignature);
if (tm->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",tm->filename);
status=OpenBlob(fs,tm,WriteBinaryBlobMode,&tm->exception);
if (status == MagickFalse)
return(status);
scene=0;
imageListLength=GetImageListLength(tm);
do
{
QuantumAny
max_value;
max_value=GetQuantumRange(tm->depth);
packet_size=3;
quantum_type=RGBQuantum;
(void) CopyMagickString(magick,fs->magick,MaxTextExtent);
switch (magick[1])
{
case 'A':
case 'a':
{
format='7';
break;
}
case 'B':
case 'b':
{
format='4';
if (fs->compression == NoCompression)
format='1';
break;
}
case 'F':
case 'f':
{
format='F';
if (SetImageGray(tm,&tm->exception) != MagickFalse)
format='f';
break;
}
case 'G':
case 'g':
{
format='5';
if (fs->compression == NoCompression)
format='2';
break;
}
case 'N':
case 'n':
{
if ((fs->type != TrueColorType) &&
(SetImageGray(tm,&tm->exception) != MagickFalse))
{
format='5';
if (fs->compression == NoCompression)
format='2';
if (SetImageMonochrome(tm,&tm->exception) != MagickFalse)
{
format='4';
if (fs->compression == NoCompression)
format='1';
}
break;
}
}
default:
{
format='6';
if (fs->compression == NoCompression)
format='3';
break;
}
}
(void) FormatLocaleString(buffer,MaxTextExtent,"P%c\n",format);
(void) WriteBlobString(tm,buffer);
value=GetImageProperty(tm,"comment");
if (value != (const char *) NULL)
{
register const char
*p;
(void) WriteBlobByte(tm,'#');
for (p=value; *p != '\0'; p++)
{
(void) WriteBlobByte(tm,(unsigned char) *p);
if ((*p == '\n') || (*p == '\r'))
(void) WriteBlobByte(tm,'#');
}
(void) WriteBlobByte(tm,'\n');
}
if (format != '7')
{
(void) FormatLocaleString(buffer,MaxTextExtent,"%.20g %.20g\n",
(double) tm->columns,(double) tm->rows);
(void) WriteBlobString(tm,buffer);
}
else
{
char
type[MaxTextExtent];
(void) FormatLocaleString(buffer,MaxTextExtent,
"WIDTH %.20g\nHEIGHT %.20g\n",(double) tm->columns,(double)
image->rows);
(void) WriteBlobString(tm,buffer);
quantum_type=GetQuantumType(tm,&tm->exception);
switch (quantum_type)
{
case CMYKQuantum:
case CMYKAQuantum:
{
packet_size=4;
(void) CopyMagickString(type,"CMYK",MaxTextExtent);
break;
}
case GrayQuantum:
case GrayAlphaQuantum:
{
packet_size=1;
(void) CopyMagickString(type,"GRAYSCALE",MaxTextExtent);
if (IdentifyImageMonochrome(tm,&tm->exception) != MagickFalse)
(void) CopyMagickString(type,"BLACKANDWHITE",MaxTextExtent);
break;
}
default:
{
quantum_type=RGBQuantum;
if (tm->matte != MagickFalse)
quantum_type=RGBAQuantum;
packet_size=3;
(void) CopyMagickString(type,"RGB",MaxTextExtent);
break;
}
}
if (tm->matte != MagickFalse)
{
packet_size++;
(void) ConcatenateMagickString(type,"_ALPHA",MaxTextExtent);
}
if (tm->depth > 32)
image->depth=32;
(void) FormatLocaleString(buffer,MaxTextExtent,
"DEPTH %.20g\nMAXVAL %.20g\n",(double) packet_size,(double)
((MagickOffsetType) GetQuantumRange(tm->depth)));
(void) WriteBlobString(tm,buffer);
(void) FormatLocaleString(buffer,MaxTextExtent,"TUPLTYPE %s\nENDHDR\n",
type);
(void) WriteBlobString(tm,buffer);
}
switch (format)
{
case '1':
{
unsigned char
pixels[2048];
(void) SetImageType(tm,BilevelType);
q=pixels;
for (y=0; y < (ssize_t) tm->rows; y++)
{
register const PixelPacket
*magick_restrict p;
register ssize_t
x;
p=GetVirtualPixels(tm,0,y,tm->columns,1,&tm->exception);
if (p == (const PixelPacket *) NULL)
break;
for (x=0; x < (ssize_t) tm->columns; x++)
{
*q++=(unsigned char) (GetPixelLuma(tm,p) >= (QuantumRange/2.0) ?
'0' : '1');
*q++=' ';
if ((q-pixels+1) >= (ssize_t) sizeof(pixels))
{
*q++='\n';
(void) WriteBlob(tm,q-pixels,pixels);
q=pixels;
}
p++;
}
*q++='\n';
(void) WriteBlob(tm,q-pixels,pixels);
q=pixels;
if (tm->previous == (Image *) NULL)
{
status=SetImageProgress(tm,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
if (q != pixels)
{
*q++='\n';
(void) WriteBlob(tm,q-pixels,pixels);
}
break;
}
case '2':
{
unsigned char
pixels[2048];
if (tm->depth <= 8)
(void) WriteBlobString(tm,"255\n");
else
if (tm->depth <= 16)
(void) WriteBlobString(tm,"65535\n");
else
(void) WriteBlobString(tm,"4294967295\n");
q=pixels;
for (y=0; y < (ssize_t) tm->rows; y++)
{
register const PixelPacket
*magick_restrict p;
register ssize_t
x;
p=GetVirtualPixels(tm,0,y,tm->columns,1,&tm->exception);
if (p == (const PixelPacket *) NULL)
break;
for (x=0; x < (ssize_t) tm->columns; x++)
{
index=ClampToQuantum(GetPixelLuma(tm,p));
if (tm->depth <= 8)
count=(ssize_t) FormatLocaleString(buffer,MaxTextExtent,"%u ",
ScaleQuantumToChar(index));
else
if (tm->depth <= 16)
count=(ssize_t) FormatLocaleString(buffer,MaxTextExtent,"%u ",
ScaleQuantumToShort(index));
else
count=(ssize_t) FormatLocaleString(buffer,MaxTextExtent,"%u ",
ScaleQuantumToLong(index));
extent=(size_t) count;
if ((q-pixels+extent+1) >= sizeof(pixels))
{
*q++='\n';
(void) WriteBlob(tm,q-pixels,pixels);
q=pixels;
}
(void) strncpy((char *) q,buffer,extent);
q+=extent;
p++;
}
*q++='\n';
(void) WriteBlob(tm,q-pixels,pixels);
q=pixels;
if (tm->previous == (Image *) NULL)
{
status=SetImageProgress(tm,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
if (q != pixels)
{
*q++='\n';
(void) WriteBlob(tm,q-pixels,pixels);
}
break;
}
case '3':
{
unsigned char
pixels[2048];
(void) TransformImageColorspace(tm,sRGBColorspace);
if (tm->depth <= 8)
(void) WriteBlobString(tm,"255\n");
else
if (tm->depth <= 16)
(void) WriteBlobString(tm,"65535\n");
else
(void) WriteBlobString(tm,"4294967295\n");
q=pixels;
for (y=0; y < (ssize_t) tm->rows; y++)
{
register const PixelPacket
*magick_restrict p;
register ssize_t
x;
p=GetVirtualPixels(tm,0,y,tm->columns,1,&tm->exception);
if (p == (const PixelPacket *) NULL)
break;
for (x=0; x < (ssize_t) tm->columns; x++)
{
if (tm->depth <= 8)
count=(ssize_t) FormatLocaleString(buffer,MaxTextExtent,
"%u %u %u ",ScaleQuantumToChar(GetPixelRed(p)),
ScaleQuantumToChar(GetPixelGreen(p)),
ScaleQuantumToChar(GetPixelBlue(p)));
else
if (tm->depth <= 16)
count=(ssize_t) FormatLocaleString(buffer,MaxTextExtent,
"%u %u %u ",ScaleQuantumToShort(GetPixelRed(p)),
ScaleQuantumToShort(GetPixelGreen(p)),
ScaleQuantumToShort(GetPixelBlue(p)));
else
count=(ssize_t) FormatLocaleString(buffer,MaxTextExtent,
"%u %u %u ",ScaleQuantumToLong(GetPixelRed(p)),
ScaleQuantumToLong(GetPixelGreen(p)),
ScaleQuantumToLong(GetPixelBlue(p)));
extent=(size_t) count;
if ((q-pixels+extent+1) >= sizeof(pixels))
{
*q++='\n';
(void) WriteBlob(tm,q-pixels,pixels);
q=pixels;
}
(void) strncpy((char *) q,buffer,extent);
q+=extent;
p++;
}
*q++='\n';
(void) WriteBlob(tm,q-pixels,pixels);
q=pixels;
if (tm->previous == (Image *) NULL)
{
status=SetImageProgress(tm,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
if (q != pixels)
{
*q++='\n';
(void) WriteBlob(tm,q-pixels,pixels);
}
break;
}
case '4':
{
(void) SetImageType(tm,BilevelType);
image->depth=1;
quantum_info=AcquireQuantumInfo(fs,tm);
if (quantum_info == (QuantumInfo *) NULL)
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
(void) SetQuantumEndian(tm,quantum_info,MSBEndian);
quantum_info->min_is_white=MagickTrue;
pixels=GetQuantumPixels(quantum_info);
for (y=0; y < (ssize_t) tm->rows; y++)
{
register const PixelPacket
*magick_restrict p;
p=GetVirtualPixels(tm,0,y,tm->columns,1,&tm->exception);
if (p == (const PixelPacket *) NULL)
break;
extent=ExportQuantumPixels(tm,(const CacheView *) NULL,
quantum_info,GrayQuantum,pixels,&tm->exception);
count=WriteBlob(tm,extent,pixels);
if (count != (ssize_t) extent)
break;
if (tm->previous == (Image *) NULL)
{
status=SetImageProgress(tm,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
quantum_info=DestroyQuantumInfo(quantum_info);
break;
}
case '5':
{
if (tm->depth > 32)
image->depth=32;
(void) FormatLocaleString(buffer,MaxTextExtent,"%.20g\n",(double)
((MagickOffsetType) GetQuantumRange(tm->depth)));
(void) WriteBlobString(tm,buffer);
quantum_info=AcquireQuantumInfo(fs,tm);
if (quantum_info == (QuantumInfo *) NULL)
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
(void) SetQuantumEndian(tm,quantum_info,MSBEndian);
quantum_info->min_is_white=MagickTrue;
pixels=GetQuantumPixels(quantum_info);
extent=GetQuantumExtent(tm,quantum_info,GrayQuantum);
for (y=0; y < (ssize_t) tm->rows; y++)
{
register const PixelPacket
*magick_restrict p;
register ssize_t
x;
p=GetVirtualPixels(tm,0,y,tm->columns,1,&tm->exception);
if (p == (const PixelPacket *) NULL)
break;
q=pixels;
switch (tm->depth)
{
case 8:
case 16:
case 32:
{
extent=ExportQuantumPixels(tm,(const CacheView *) NULL,
quantum_info,GrayQuantum,pixels,&tm->exception);
break;
}
default:
{
if (tm->depth <= 8)
{
for (x=0; x < (ssize_t) tm->columns; x++)
{
if (IsGrayPixel(p) == MagickFalse)
pixel=ScaleQuantumToAny(ClampToQuantum(
GetPixelLuma(tm,p)),max_value);
else
{
if (tm->depth == 8)
pixel=ScaleQuantumToChar(GetPixelRed(p));
else
pixel=ScaleQuantumToAny(GetPixelRed(p),max_value);
}
q=PopCharPixel((unsigned char) pixel,q);
p++;
}
extent=(size_t) (q-pixels);
break;
}
if (tm->depth <= 16)
{
for (x=0; x < (ssize_t) tm->columns; x++)
{
if (IsGrayPixel(p) == MagickFalse)
pixel=ScaleQuantumToAny(ClampToQuantum(
GetPixelLuma(tm,p)),max_value);
else
{
if (tm->depth == 16)
pixel=ScaleQuantumToShort(GetPixelRed(p));
else
pixel=ScaleQuantumToAny(GetPixelRed(p),max_value);
}
q=PopShortPixel(MSBEndian,(unsigned short) pixel,q);
p++;
}
extent=(size_t) (q-pixels);
break;
}
for (x=0; x < (ssize_t) tm->columns; x++)
{
