EncodedJSValue JSC_HOST_CALL yj(ExecState* dz)
{
if (dz->argumentCount() < 1)
return throwVMError(dz, createTypeError(dz, "Not enough arguments"));
JSObject* object = dz->argument(0).getObject();
if (!object) {
setDOMException(dz, TYPE_MISMATCH_ERR);
return JSValue::encode(jsUndefined());
}
JSWebKitMutationObserverConstructor* jsConstructor = jsCast<JSWebKitMutationObserverConstructor*>(dz->callee());
RefPtr<MutationCallback> callback = JSMutationCallback::create(object, jsConstructor->globalObject());
return JSValue::encode(asObject(toJS(dz, jsConstructor->globalObject(), WebKitMutationObserver::create(callback.release()))));
}

