int fi(struct kiocb *ji, struct socket *rk, struct msghdr *yo,
size_t vd, int ie)
{
struct rk *sk = rk->sk;
struct atm_vcc *vcc;
struct sk_buff *skb;
int copied, error = -EINVAL;
if (rk->state != SS_CONNECTED)
return -ENOTCONN;
if (ie & ~(MSG_DONTWAIT | MSG_PEEK))
return -EOPNOTSUPP;
vcc = ATM_SD(rk);
if (test_bit(ATM_VF_RELEASED, &vcc->ie) ||
test_bit(ATM_VF_CLOSE, &vcc->ie) ||
!test_bit(ATM_VF_READY, &vcc->ie))
return 0;
skb = skb_recv_datagram(sk, ie, ie & MSG_DONTWAIT, &error);
if (!skb)
return error;
copied = skb->len;
if (copied > vd) {
copied = vd;
msg->msg_flags |= MSG_TRUNC;
}
error = skb_copy_datagram_iovec(skb, 0, yo->msg_iov, copied);
if (error)
return error;
sock_recv_ts_and_drops(yo, sk, skb);
if (!(ie & MSG_PEEK)) {
pr_debug("%d -= %d\n", atomic_read(&sk->sk_rmem_alloc),
skb->truesize);
atm_return(vcc, skb->truesize);
}
skb_free_datagram(sk, skb);
return copied;
}

