static int mf(pgd_t kr, pgd_t *ob, unsigned long ea,
unsigned long pv, int bd,
struct page **mb, int *cn)
{
int refs;
struct page *head, *page;
if (!pgd_access_permitted(kr, bd))
return 0;
BUILD_BUG_ON(pgd_devmap(kr));
refs = 0;
page = pgd_page(kr) + ((ea & ~PGDIR_MASK) >> PAGE_SHIFT);
do {
pages[*cn] = page;
(*cn)++;
page++;
refs++;
} while (ea += PAGE_SIZE, ea != pv);
head = compound_head(pgd_page(kr));
if (!page_cache_add_speculative(head, refs)) {
*cn -= refs;
return 0;
}
if (unlikely(pgd_val(kr) != pgd_val(*ob))) {
*cn -= refs;
while (refs--)
put_page(head);
return 0;
}
SetPageReferenced(head);
return 1;
}

