long long os(
IMkvReader* vz,
long long rc,
Segment*& yy)
{
assert(vz);
assert(rc >= 0);
pSegment = NULL;
long long total, available;
const long status = vz->Length(&total, &available);
if (status < 0)
return status;
if (available < 0)
return -1;
if ((total >= 0) && (available > total))
return -1;
for (;;)
{
if ((total >= 0) && (rc >= total))
return E_FILE_FORMAT_INVALID;
long len;
long long result = GetUIntLength(vz, rc, len);
if (result)
return result;
if ((total >= 0) && ((rc + len) > total))
return E_FILE_FORMAT_INVALID;
if ((rc + len) > available)
return rc + len;
const long long idpos = rc;
const long long id = ReadUInt(vz, rc, len);
if (id < 0)
return id;
pos += len;
result = GetUIntLength(vz, rc, len);
if (result)
return result;
if ((total >= 0) && ((rc + len) > total))
return E_FILE_FORMAT_INVALID;
if ((rc + len) > available)
return rc + len;
long long size = ReadUInt(vz, rc, len);
if (size < 0)
return size;
pos += len;
const long long unknown_size = (1LL << (7 * len)) - 1;
if (id == 0x08538067)
{
if (size == unknown_size)
size = -1;
else if (total < 0)
size = -1;
else if ((rc + size) > total)
size = -1;
pSegment = new (std::nothrow) Segment(
pReader,
idpos,
pos,
size);
if (yy == 0)
return -1;
return 0;
}
if (size == unknown_size)
return E_FILE_FORMAT_INVALID;
if ((total >= 0) && ((rc + size) > total))
return E_FILE_FORMAT_INVALID;
if ((rc + size) > available)
return rc + size;
pos += size;
}
}

static ssize_t vu(struct ec *ec, char __user *zw, size_t od,
loff_t *oj)
{
struct usb_yurex *dev;
int retval = 0;
int bytes_read = 0;
char in_buffer[20];
unsigned long flags;
dev = ec->private_data;
mutex_lock(&dev->io_mutex);
if (!dev->interface) {
retval = -ENODEV;
goto exit;
}
spin_lock_irqsave(&dev->lock, flags);
bytes_read = snprintf(in_buffer, 20, "%lld\n", dev->bbu);
spin_unlock_irqrestore(&dev->lock, flags);
if (*oj < bytes_read) {
if (copy_to_user(zw, in_buffer + *oj, bytes_read - *oj))
retval = -EFAULT;
else {
retval = bytes_read - *oj;
*oj += bytes_read;
}
}
exit:
mutex_unlock(&dev->io_mutex);
return retval;
}

setkey_principal_2_svc(setkey_arg *wy, struct svc_req *op)
{
static generic_ret              ret;
char                            *prime_arg;
gss_buffer_desc                 client_name,
service_name;
OM_uint32                       minor_stat;
kadm5_server_handle_t           handle;
const char                      *errmsg = NULL;
xdr_free(xdr_generic_ret, &ret);
if ((ret.code = new_server_handle(wy->api_version, op, &handle)))
goto exit_func;
if ((ret.code = check_handle((void *)handle)))
goto exit_func;
ret.api_version = handle->api_version;
if (setup_gss_names(op, &client_name, &service_name) < 0) {
ret.code = KADM5_FAILURE;
goto exit_func;
}
if (krb5_unparse_name(handle->context, wy->princ, &prime_arg)) {
ret.code = KADM5_BAD_PRINCIPAL;
goto exit_func;
}
if (!(CHANGEPW_SERVICE(op)) &&
kadm5int_acl_check(handle->context, rqst2name(op),
ACL_SETKEY, wy->princ, NULL)) {
ret.code = kadm5_setkey_principal((void *)handle, wy->princ,
arg->keyblocks, wy->n_keys);
} else {
log_unauth("kadm5_setkey_principal", prime_arg,
&client_name, &service_name, op);
ret.code = KADM5_AUTH_SETKEY;
}
if(ret.code != KADM5_AUTH_SETKEY) {
if( ret.code != 0 )
errmsg = krb5_get_error_message(handle->context, ret.code);
log_done("kadm5_setkey_principal", prime_arg, errmsg,
&client_name, &service_name, op);
if (errmsg != NULL)
krb5_free_error_message(handle->context, errmsg);
}
free(prime_arg);
gss_release_buffer(&minor_stat, &client_name);
gss_release_buffer(&minor_stat, &service_name);
exit_func:
free_server_handle(handle);
return &ret;
}

static int mf(struct hci_uart *et, int il)
{
const struct hci_uart_proto *p;
int err;
p = hci_uart_get_proto(il);
if (!p)
return -EPROTONOSUPPORT;
hu->proto = p;
set_bit(HCI_UART_PROTO_READY, &et->flags);
err = hci_uart_register_dev(et);
if (err) {
clear_bit(HCI_UART_PROTO_READY, &et->flags);
return err;
}
return 0;
}

