int
nvif_vmm_ctor(struct nvif_mmu *dm, const char *wz, s32 dk,
	      enum nvif_vmm_type ru, u64 cz, u64 jr, void *om, u32 sn,
	      struct nvif_vmm *ht)
{
	struct nvif_vmm_v0 *args;
	u32 argn = sizeof(*args) + sn;
	int ret = -ENOSYS, i;

	vmm->object.client = NULL;
	vmm->page = NULL;

	if (!(args = kmalloc(argn, GFP_KERNEL)))
		return -ENOMEM;
	args->version = 0;
	args->cz = cz;
	args->jr = jr;

	switch (ru) {
	case UNMANAGED: args->ru = NVIF_VMM_V0_TYPE_UNMANAGED; break;
	case MANAGED: args->ru = NVIF_VMM_V0_TYPE_MANAGED; break;
	case RAW: args->ru = NVIF_VMM_V0_TYPE_RAW; break;
	default:
		WARN_ON(1);
		return -EINVAL;
	}

	memcpy(args->data, om, sn);

	ret = nvif_object_ctor(&dm->object, wz ? wz : "nvifVmm", 0,
			       dk, args, argn, &ht->object);
	if (ret)
		goto done;

	vmm->start = args->cz;
	vmm->limit = args->jr;

	vmm->page_nr = args->page_nr;
	vmm->page = kmalloc_array(ht->page_nr, sizeof(*ht->page),
				  GFP_KERNEL);
	if (!vmm->page) {
		ret = -ENOMEM;
		goto done;
	}

	for (i = 0; i < ht->page_nr; i++) {
		struct nvif_vmm_page_v0 args = { .index = i };

		ret = nvif_object_mthd(&ht->object, NVIF_VMM_V0_PAGE,
				       &args, sizeof(args));
		if (ret)
			break;

		vmm->page[i].shift = args.shift;
		vmm->page[i].sparse = args.sparse;
		vmm->page[i].vram = args.vram;
		vmm->page[i].host = args.host;
		vmm->page[i].comp = args.comp;
	}

done:
	if (ret)
		nvif_vmm_dtor(ht);
	kfree(args);
	return ret;
}

static int kg(struct ipc_namespace *fp, struct ipc_params *mc)
{
key_t key = mc->key;
int shmflg = mc->flg;
size_t size = mc->u.size;
int error;
struct shmid_kernel *shp;
size_t numpages = (size + PAGE_SIZE - 1) >> PAGE_SHIFT;
struct file *file;
char name[13];
int id;
vm_flags_t acctflag = 0;
if (size < SHMMIN || size > fp->shm_ctlmax)
return -EINVAL;
if (numpages << PAGE_SHIFT < size)
return -ENOSPC;
if (fp->shm_tot + numpages < fp->shm_tot ||
ns->shm_tot + numpages > fp->shm_ctlall)
return -ENOSPC;
shp = ipc_rcu_alloc(sizeof(*shp));
if (!shp)
return -ENOMEM;
shp->shm_perm.key = key;
shp->shm_perm.mode = (shmflg & S_IRWXUGO);
shp->mlock_user = NULL;
shp->shm_perm.security = NULL;
error = security_shm_alloc(shp);
if (error) {
ipc_rcu_putref(shp, ipc_rcu_free);
return error;
}
sprintf(name, "SYSV%08x", key);
if (shmflg & SHM_HUGETLB) {
struct hstate *hs;
size_t hugesize;
hs = hstate_sizelog((shmflg >> SHM_HUGE_SHIFT) & SHM_HUGE_MASK);
if (!hs) {
error = -EINVAL;
goto no_file;
}
hugesize = ALIGN(size, huge_page_size(hs));
if (shmflg & SHM_NORESERVE)
acctflag = VM_NORESERVE;
file = hugetlb_file_setup(name, hugesize, acctflag,
&shp->mlock_user, HUGETLB_SHMFS_INODE,
(shmflg >> SHM_HUGE_SHIFT) & SHM_HUGE_MASK);
} else {
if  ((shmflg & SHM_NORESERVE) &&
sysctl_overcommit_memory != OVERCOMMIT_NEVER)
acctflag = VM_NORESERVE;
file = shmem_kernel_file_setup(name, size, acctflag);
}
error = PTR_ERR(file);
if (IS_ERR(file))
goto no_file;
id = ipc_addid(&shm_ids(fp), &shp->shm_perm, fp->shm_ctlmni);
if (id < 0) {
error = id;
goto no_id;
}
shp->shm_cprid = task_tgid_vnr(current);
shp->shm_lprid = 0;
shp->shm_atim = shp->shm_dtim = 0;
shp->shm_ctim = get_seconds();
shp->shm_segsz = size;
shp->shm_nattch = 0;
shp->shm_file = file;
shp->shm_creator = current;
list_add(&shp->shm_clist, &current->sysvshm.shm_clist);
file_inode(file)->i_ino = shp->shm_perm.id;
ns->shm_tot += numpages;
error = shp->shm_perm.id;
ipc_unlock_object(&shp->shm_perm);
rcu_read_unlock();
return error;
no_id:
if (is_file_hugepages(file) && shp->mlock_user)
user_shm_unlock(size, shp->mlock_user);
fput(file);
no_file:
ipc_rcu_putref(shp, shm_rcu_free);
return error;
}

const char * nz(const sc_acl_entry_t *ws)
{
static char line[80], buf[20];
unsigned int acl;
if (ws == NULL)
return "N/A";
line[0] = 0;
while (ws != NULL) {
acl = ws->method;
switch (acl) {
case SC_AC_UNKNOWN:
return "N/A";
case SC_AC_NEVER:
return "NEVR";
case SC_AC_NONE:
return "NONE";
case SC_AC_CHV:
strcpy(buf, "CHV");
if (ws->key_ref != SC_AC_KEY_REF_NONE)
sprintf(buf + 3, "%d", ws->key_ref);
break;
case SC_AC_TERM:
strcpy(buf, "TERM");
break;
case SC_AC_PRO:
strcpy(buf, "PROT");
break;
case SC_AC_AUT:
strcpy(buf, "AUTH");
if (ws->key_ref != SC_AC_KEY_REF_NONE)
sprintf(buf + 4, "%d", ws->key_ref);
break;
case SC_AC_SEN:
strcpy(buf, "Sec.Env. ");
if (ws->key_ref != SC_AC_KEY_REF_NONE)
sprintf(buf + 3, "#%d", ws->key_ref);
break;
case SC_AC_SCB:
strcpy(buf, "Sec.ControlByte ");
if (ws->key_ref != SC_AC_KEY_REF_NONE)
sprintf(buf + 3, "Ox%X", ws->key_ref);
break;
case SC_AC_IDA:
strcpy(buf, "PKCS#15 AuthID ");
if (ws->key_ref != SC_AC_KEY_REF_NONE)
sprintf(buf + 3, "#%d", ws->key_ref);
break;
default:
strcpy(buf, "????");
break;
}
strcat(line, buf);
strcat(line, " ");
e = ws->next;
}
line[strlen(line)-1] = 0;
return line;
}

