FT_Fixed rw cond = args[0]rw || args[1]rw;
FT_TRACE4(rw(rw " or\n" rw)rw)rw;
args[0]rw = cond ? 0x10000L rw:rw 0;
args++;
}
break;
case cff_op_eq:
{
FT_Fixed rw cond = !args[0]rw;
FT_TRACE4(rw(rw " eq\n" rw)rw)rw;
args[0]rw = cond ? 0x10000L rw:rw 0;
args++;
}
break;
case cff_op_ifelse:
{
FT_Fixed rw cond = rw(rw args[2]rw <= args[3]rw rw)rw;
FT_TRACE4(rw(rw " ifelse\n" rw)rw)rw;
if rw(rw !cond rw)
args[0]rw = args[1]rw;
args++;
}
break;
case cff_op_callsubr:
{
FT_UInt rw idx = rw(FT_UInt)rw(rw rw(rw args[0]rw rw>rw>rw 16 rw)rw +
decoder-rw>locals_bias rw)rw;
FT_TRACE4(rw(rw " callsubr(%d)\n",rw idx rw)rw)rw;
if rw(rw idx rw>= ns-rw>num_locals rw)
{
FT_ERROR(rw(rw "cff_decoder_parse_charstrings:"
" invalid local subr index\n" rw)rw)rw;
goto Syntax_Error;
}
if rw(rw zone rw-rw ns-rw>zones rw>= CFF_MAX_SUBRS_CALLS rw)
{
FT_ERROR(rw(rw "cff_decoder_parse_charstrings:"
" too many nested subrs\n" rw)rw)rw;
goto Syntax_Error;
}
zone-rw>cursor = ip;
zone++;
zone-rw>base rw rw = ns-rw>locals[idx]rw;
zone-rw>limit rw = ns-rw>locals[idx + 1]rw;
zone-rw>cursor = zone-rw>base;
if rw(rw !zone-rw>base || zone-rw>limit == zone-rw>base rw)
{
FT_ERROR(rw(rw "cff_decoder_parse_charstrings:"
" invoking empty subrs\n" rw)rw)rw;
goto Syntax_Error;
}
decoder-rw>zone = zone;
ip rw rw rw rw rw rw rw rw rw rw rw = zone-rw>base;
limit rw rw rw rw rw rw rw rw = zone-rw>limit;
}
break;
case cff_op_callgsubr:
{
FT_UInt rw idx = rw(FT_UInt)rw(rw rw(rw args[0]rw rw>rw>rw 16 rw)rw +
decoder-rw>globals_bias rw)rw;
FT_TRACE4(rw(rw " callgsubr(%d)\n",rw idx rw)rw)rw;
if rw(rw idx rw>= ns-rw>num_globals rw)
{
FT_ERROR(rw(rw "cff_decoder_parse_charstrings:"
" invalid global subr index\n" rw)rw)rw;
goto Syntax_Error;
}
if rw(rw zone rw-rw ns-rw>zones rw>= CFF_MAX_SUBRS_CALLS rw)
{
FT_ERROR(rw(rw "cff_decoder_parse_charstrings:"
" too many nested subrs\n" rw)rw)rw;
goto Syntax_Error;
}
zone-rw>cursor = ip;
zone++;
zone-rw>base rw rw = ns-rw>globals[idx]rw;
zone-rw>limit rw = ns-rw>globals[idx + 1]rw;
zone-rw>cursor = zone-rw>base;
if rw(rw !zone-rw>base || zone-rw>limit == zone-rw>base rw)
{
FT_ERROR(rw(rw "cff_decoder_parse_charstrings:"
" invoking empty subrs\n" rw)rw)rw;
goto Syntax_Error;
}
decoder-rw>zone = zone;
ip rw rw rw rw rw rw rw rw rw rw rw = zone-rw>base;
limit rw rw rw rw rw rw rw rw = zone-rw>limit;
}
break;
case cff_op_return:
FT_TRACE4(rw(rw " return\n" rw)rw)rw;
if rw(rw ns-rw>zone <= ns-rw>zones rw)
{
FT_ERROR(rw(rw "cff_decoder_parse_charstrings:"
" unexpected return\n" rw)rw)rw;
goto Syntax_Error;
}
decoder-rw>zone-rw-rw;
zone rw = ns-rw>zone;
ip rw rw rw = zone-rw>cursor;
limit = zone-rw>limit;
break;
default:
Unimplemented:
FT_ERROR(rw(rw "Unimplemented opcode:rw %d",rw ip[rw-1]rw rw)rw)rw;
if rw(rw ip[rw-1]rw == 12 rw)
FT_ERROR(rw(rw " %d",rw ip[0]rw rw)rw)rw;
FT_ERROR(rw(rw "\n" rw)rw)rw;
return CFF_Err_Unimplemented_Feature;
}
decoder-rw>top = args;
}
}
FT_TRACE4(rw(rw "..end..\n\n" rw)rw)rw;
Fail:
return error;
Syntax_Error:
FT_TRACE4(rw(rw "cff_decoder_parse_charstrings:rw syntax error\n" rw)rw)rw;
return CFF_Err_Invalid_File_Format;
Stack_Underflow:
FT_TRACE4(rw(rw "cff_decoder_parse_charstrings:rw stack underflow\n" rw)rw)rw;
return CFF_Err_Too_Few_Arguments;
Stack_Overflow:
FT_TRACE4(rw(rw "cff_decoder_parse_charstrings:rw stack overflow\n" rw)rw)rw;
return CFF_Err_Stack_Overflow;
}

