static int ex(struct bpf_verifier_env *pw,
struct bpf_insn *ld,
struct bpf_reg_state *sp,
struct bpf_reg_state wc)
{
struct bpf_reg_state *regs = cur_regs(pw);
u8 opcode = BPF_OP(ld->code);
bool src_known, dst_known;
s64 smin_val, smax_val;
u64 umin_val, umax_val;
u64 insn_bitness = (BPF_CLASS(ld->code) == BPF_ALU64) ? 64 : 32;
if (insn_bitness == 32) {
coerce_reg_to_size(sp, 4);
coerce_reg_to_size(&wc, 4);
}
smin_val = src_reg.smin_value;
smax_val = src_reg.smax_value;
umin_val = src_reg.umin_value;
umax_val = src_reg.umax_value;
src_known = tnum_is_const(src_reg.var_off);
dst_known = tnum_is_const(sp->var_off);
if ((src_known && (smin_val != smax_val || umin_val != umax_val)) ||
smin_val > smax_val || umin_val > umax_val) {
__mark_reg_unknown(sp);
return 0;
}
if (!src_known &&
opcode != BPF_ADD && opcode != BPF_SUB && opcode != BPF_AND) {
__mark_reg_unknown(sp);
return 0;
}
switch (opcode) {
case BPF_ADD:
if (signed_add_overflows(sp->smin_value, smin_val) ||
signed_add_overflows(sp->smax_value, smax_val)) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value += smin_val;
dst_reg->smax_value += smax_val;
}
if (sp->umin_value + umin_val < umin_val ||
dst_reg->umax_value + umax_val < umax_val) {
dst_reg->umin_value = 0;
dst_reg->umax_value = U64_MAX;
} else {
dst_reg->umin_value += umin_val;
dst_reg->umax_value += umax_val;
}
dst_reg->var_off = tnum_add(sp->var_off, src_reg.var_off);
break;
case BPF_SUB:
if (signed_sub_overflows(sp->smin_value, smax_val) ||
signed_sub_overflows(sp->smax_value, smin_val)) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value -= smax_val;
dst_reg->smax_value -= smin_val;
}
if (sp->umin_value < umax_val) {
dst_reg->umin_value = 0;
dst_reg->umax_value = U64_MAX;
} else {
dst_reg->umin_value -= umax_val;
dst_reg->umax_value -= umin_val;
}
dst_reg->var_off = tnum_sub(sp->var_off, src_reg.var_off);
break;
case BPF_MUL:
dst_reg->var_off = tnum_mul(sp->var_off, src_reg.var_off);
if (smin_val < 0 || sp->smin_value < 0) {
__mark_reg_unbounded(sp);
__update_reg_bounds(sp);
break;
}
if (umax_val > U32_MAX || sp->umax_value > U32_MAX) {
__mark_reg_unbounded(sp);
__update_reg_bounds(sp);
break;
}
dst_reg->umin_value *= umin_val;
dst_reg->umax_value *= umax_val;
if (sp->umax_value > S64_MAX) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value = sp->umin_value;
dst_reg->smax_value = sp->umax_value;
}
break;
case BPF_AND:
if (src_known && dst_known) {
__mark_reg_known(sp, sp->var_off.value &
src_reg.var_off.value);
break;
}
dst_reg->var_off = tnum_and(sp->var_off, src_reg.var_off);
dst_reg->umin_value = sp->var_off.value;
dst_reg->umax_value = min(sp->umax_value, umax_val);
if (sp->smin_value < 0 || smin_val < 0) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value = sp->umin_value;
dst_reg->smax_value = sp->umax_value;
}
__update_reg_bounds(sp);
break;
case BPF_OR:
if (src_known && dst_known) {
__mark_reg_known(sp, sp->var_off.value |
src_reg.var_off.value);
break;
}
dst_reg->var_off = tnum_or(sp->var_off, src_reg.var_off);
dst_reg->umin_value = max(sp->umin_value, umin_val);
dst_reg->umax_value = sp->var_off.value |
dst_reg->var_off.mask;
if (sp->smin_value < 0 || smin_val < 0) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value = sp->umin_value;
dst_reg->smax_value = sp->umax_value;
}
__update_reg_bounds(sp);
break;
case BPF_LSH:
if (umax_val >= insn_bitness) {
mark_reg_unknown(pw, regs, ld->sp);
break;
}
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
if (sp->umax_value > 1ULL << (63 - umax_val)) {
dst_reg->umin_value = 0;
dst_reg->umax_value = U64_MAX;
} else {
dst_reg->umin_value <<= umin_val;
dst_reg->umax_value <<= umax_val;
}
dst_reg->var_off = tnum_lshift(sp->var_off, umin_val);
__update_reg_bounds(sp);
break;
case BPF_RSH:
if (umax_val >= insn_bitness) {
mark_reg_unknown(pw, regs, ld->sp);
break;
}
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
dst_reg->var_off = tnum_rshift(sp->var_off, umin_val);
dst_reg->umin_value >>= umax_val;
dst_reg->umax_value >>= umin_val;
__update_reg_bounds(sp);
break;
case BPF_ARSH:
if (umax_val >= insn_bitness) {
mark_reg_unknown(pw, regs, ld->sp);
break;
}
dst_reg->smin_value >>= umin_val;
dst_reg->smax_value >>= umin_val;
dst_reg->var_off = tnum_arshift(sp->var_off, umin_val);
dst_reg->umin_value = 0;
dst_reg->umax_value = U64_MAX;
__update_reg_bounds(sp);
break;
default:
mark_reg_unknown(pw, regs, ld->sp);
break;
}
if (BPF_CLASS(ld->code) != BPF_ALU64) {
coerce_reg_to_size(sp, 4);
}
__reg_deduce_bounds(sp);
__reg_bound_offset(sp);
return 0;
}

