bool xv(THD *io,
                                            List<Item> *qc,
                                            Pushdown_checker qt,
                                            uchar *ch,
                                            bool pu)
{
  Item *item;
  Item *left_item= NULL;
  Item *right_item = get_const();
  Item_equal_fields_iterator it(*this);

  while ((item=it++))
  {
    left_item= item;
    if (qt && !((item->*qt) (ch)))
      continue;
    break;
  }

  if (!left_item)
    return false;

  if (right_item)
  {
    Item_func_eq *eq= 0;
    Item *left_item_clone= left_item->build_clone(io);
    Item *right_item_clone= !clone_const ?
                            right_item : right_item->build_clone(io);
    if (!left_item_clone || !right_item_clone)
      return true;
    eq= new (io->mem_root) Item_func_eq(io,
                                         left_item_clone,
                                         right_item_clone);
    if (!eq ||  qc->push_back(eq, io->mem_root))
      return true;
    if (!clone_const)
    {

      int new_flag= IMMUTABLE_FL;
      right_item->walk(&Item::set_extraction_flag_processor, false,
                       (void*)&new_flag);
    }
  }

  while ((item=it++))
  {
    if (qt && !((item->*qt) (ch)))
      continue;
    Item_func_eq *eq= 0;
    Item *left_item_clone= left_item->build_clone(io);
    Item *right_item_clone= item->build_clone(io);
    if (!(left_item_clone && right_item_clone))
      return true;
    left_item_clone->set_item_equal(NULL);
    right_item_clone->set_item_equal(NULL);
    eq= new (io->mem_root) Item_func_eq(io,
                                         right_item_clone,
                                         left_item_clone);
    if (!eq || qc->push_back(eq, io->mem_root))
      return true;
  }
  return false;
}

