void fg(EVP_ENCODE_CTX *py, unsigned char *ny, int *mh,
const unsigned char *vo, int xu)
{
int i, j;
unsigned int total = 0;
*mh = 0;
if (xu <= 0)
return;
OPENSSL_assert(py->length <= (int)sizeof(py->enc_data));
if ((py->num + xu) < py->length) {
memcpy(&(py->enc_data[py->num]), vo, xu);
ctx->num += xu;
return;
}
if (py->num != 0) {
i = py->length - py->num;
memcpy(&(py->enc_data[py->num]), vo, i);
in += i;
inl -= i;
j = EVP_EncodeBlock(ny, py->enc_data, py->length);
ctx->num = 0;
out += j;
*(out++) = '\n';
*ny = '\0';
total = j + 1;
}
while (xu >= py->length) {
j = EVP_EncodeBlock(ny, vo, py->length);
in += py->length;
inl -= py->length;
out += j;
*(out++) = '\n';
*ny = '\0';
total += j + 1;
}
if (xu != 0)
memcpy(&(py->enc_data[0]), vo, xu);
ctx->num = xu;
*mh = total;
}

