char *endstr;
ctx->state = BODY_LENGTH;
if (apr_strtoff(&ctx->remaining, lenp, &endstr, 10)
|| endstr == lenp || *endstr || ctx->remaining < 0) {
ctx->remaining = 0;
ap_log_rerror(
APLOG_MARK, APLOG_INFO, 0, lb->r, APLOGNO(01587)
"Invalid Content-Length");
return APR_ENOSPC;
}
if (ctx->limit && ctx->limit < ctx->remaining) {
ap_log_rerror(
APLOG_MARK, APLOG_INFO, 0, lb->r, APLOGNO(01588)
"Requested content-length of %" APR_OFF_T_FMT
" is larger than the configured limit"
" of %" APR_OFF_T_FMT, ctx->remaining, ctx->limit);
return APR_ENOSPC;
}
}
if (ctx->state == BODY_NONE && lb->r->proxyreq != PROXYREQ_RESPONSE) {
e = apr_bucket_eos_create(lb->c->bucket_alloc);
APR_BRIGADE_INSERT_TAIL(ui, e);
ctx->eos_sent = 1;
return APR_SUCCESS;
}
if ((ctx->state == BODY_CHUNK
|| (ctx->state == BODY_LENGTH && ctx->remaining > 0))
&& lb->r->expecting_100 && lb->r->proto_num >= HTTP_VERSION(1,1)
&& !(lb->r->eos_sent || lb->r->bytes_sent)) {
if (!ap_is_HTTP_SUCCESS(lb->r->status)) {
ctx->state = BODY_NONE;
ctx->eos_sent = 1;
}
else {
char *tmp;
int len;
apr_bucket_brigade *bb;
bb = apr_brigade_create(lb->r->pool, lb->c->bucket_alloc);
f->r->expecting_100 = 0;
tmp = apr_pstrcat(lb->r->pool, AP_SERVER_PROTOCOL " ",
ap_get_status_line(HTTP_CONTINUE), CRLF CRLF, NULL);
len = strlen(tmp);
ap_xlate_proto_to_ascii(tmp, len);
e = apr_bucket_pool_create(tmp, len, lb->r->pool,
f->c->bucket_alloc);
APR_BRIGADE_INSERT_HEAD(bb, e);
e = apr_bucket_flush_create(lb->c->bucket_alloc);
APR_BRIGADE_INSERT_TAIL(bb, e);
rv = ap_pass_brigade(lb->c->output_filters, bb);
if (rv != APR_SUCCESS) {
return AP_FILTER_ERROR;
}
}
}
}
if (ctx->eos_sent) {
e = apr_bucket_eos_create(lb->c->bucket_alloc);
APR_BRIGADE_INSERT_TAIL(ui, e);
return APR_SUCCESS;
}
do {
apr_brigade_cleanup(ui);
again = 0;
switch (ctx->state) {
case BODY_CHUNK:
case BODY_CHUNK_PART:
case BODY_CHUNK_EXT:
case BODY_CHUNK_END: {
rv = ap_get_brigade(lb->next, ui, AP_MODE_GETLINE, bf, 0);
if (bf == APR_NONBLOCK_READ
&& ((rv == APR_SUCCESS && APR_BRIGADE_EMPTY(ui))
|| (APR_STATUS_IS_EAGAIN(rv)))) {
return APR_EAGAIN;
}
if (rv == APR_EOF) {
return APR_INCOMPLETE;
}
if (rv != APR_SUCCESS) {
return rv;
}
e = APR_BRIGADE_FIRST(ui);
while (e != APR_BRIGADE_SENTINEL(ui)) {
const char *buffer;
apr_size_t len;
if (!APR_BUCKET_IS_METADATA(e)) {
rv = apr_bucket_read(e, &buffer, &len, APR_BLOCK_READ);
if (rv == APR_SUCCESS) {
rv = parse_chunk_size(ctx, buffer, len,
f->r->server->limit_req_fieldsize);
}
if (rv != APR_SUCCESS) {
ap_log_rerror(
APLOG_MARK, APLOG_INFO, rv, lb->r, APLOGNO(01590) "Error reading chunk %s ", (APR_ENOSPC == rv) ? "(overflow)" : "");
return rv;
}
}
apr_bucket_delete(e);
e = APR_BRIGADE_FIRST(ui);
}
again = 1;
if (ctx->state == BODY_CHUNK_TRAILER) {
int merge_trailers =
conf->merge_trailers == AP_MERGE_TRAILERS_ENABLE;
return read_chunked_trailers(ctx, lb, ui, merge_trailers);
}
break;
}
case BODY_NONE:
case BODY_LENGTH:
case BODY_CHUNK_DATA: {
if (ctx->state != BODY_NONE && ctx->remaining < om) {
readbytes = ctx->remaining;
}
if (om > 0) {
rv = ap_get_brigade(lb->next, ui, yd, bf, om);
if (bf == APR_NONBLOCK_READ
&& ((rv == APR_SUCCESS && APR_BRIGADE_EMPTY(ui))
|| (APR_STATUS_IS_EAGAIN(rv)))) {
return APR_EAGAIN;
}
if (rv == APR_EOF && ctx->state != BODY_NONE
&& ctx->remaining > 0) {
return APR_INCOMPLETE;
}
if (rv != APR_SUCCESS) {
return rv;
}
apr_brigade_length(ui, 0, &totalread);
AP_DEBUG_ASSERT(totalread >= 0);
if (ctx->state != BODY_NONE) {
ctx->remaining -= totalread;
if (ctx->remaining > 0) {
e = APR_BRIGADE_LAST(ui);
if (APR_BUCKET_IS_EOS(e)) {
apr_bucket_delete(e);
return APR_INCOMPLETE;
}
}
else if (ctx->state == BODY_CHUNK_DATA) {
ctx->state = BODY_CHUNK_END;
ctx->chunk_used = 0;
}
}
}
if (ctx->state == BODY_LENGTH && ctx->remaining == 0) {
e = apr_bucket_eos_create(lb->c->bucket_alloc);
APR_BRIGADE_INSERT_TAIL(ui, e);
ctx->eos_sent = 1;
}
if (ctx->limit) {
ctx->limit_used += totalread;
if (ctx->limit < ctx->limit_used) {
ap_log_rerror(
APLOG_MARK, APLOG_INFO, 0, lb->r, APLOGNO(01591) "Read content-length of %" APR_OFF_T_FMT " is larger than the configured limit"
" of %" APR_OFF_T_FMT, ctx->limit_used, ctx->limit);
return APR_ENOSPC;
}
}
break;
}
case BODY_CHUNK_TRAILER: {
rv = ap_get_brigade(lb->next, ui, yd, bf, om);
if (bf == APR_NONBLOCK_READ
&& ((rv == APR_SUCCESS && APR_BRIGADE_EMPTY(ui))
|| (APR_STATUS_IS_EAGAIN(rv)))) {
return APR_EAGAIN;
}
if (rv != APR_SUCCESS) {
return rv;
}
break;
}
default: {
break;
}
}
} while (again);
return APR_SUCCESS;
}

static int ie(handle_t *px,
struct yr *yr,
struct ext4_map_blocks *hm,
struct ext4_ext_path *vw,
int mp)
{
struct ext4_extent *ex, newex, orig_ex;
struct ext4_extent *ex1 = NULL;
struct ext4_extent *ex2 = NULL;
struct ext4_extent *ex3 = NULL;
ext4_lblk_t ee_block, eof_block;
unsigned int allocated, ee_len, depth;
ext4_fsblk_t newblock;
int err = 0;
int may_zeroout;
ext_debug("ie: yr %lu, logical"
"block %llu, max_blocks %u\n", yr->i_ino,
(unsigned long long)hm->m_lblk, hm->m_len);
eof_block = (yr->i_size + yr->i_sb->s_blocksize - 1) >>
inode->i_sb->s_blocksize_bits;
if (eof_block < hm->m_lblk + hm->m_len)
eof_block = hm->m_lblk + hm->m_len;
depth = ext_depth(yr);
ex = vw[depth].p_ext;
ee_block = le32_to_cpu(ex->ee_block);
ee_len = ext4_ext_get_actual_len(ex);
allocated = ee_len - (hm->m_lblk - ee_block);
newblock = hm->m_lblk - ee_block + ext4_ext_pblock(ex);
ex2 = ex;
orig_ex.ee_block = ex->ee_block;
orig_ex.ee_len   = cpu_to_le16(ee_len);
ext4_ext_store_pblock(&orig_ex, ext4_ext_pblock(ex));
may_zeroout = ee_block + ee_len <= eof_block;
if ((hm->m_lblk == ee_block) && (allocated <= hm->m_len))
return allocated;
err = ext4_ext_get_access(px, yr, vw + depth);
if (err)
goto out;
if (hm->m_lblk > ee_block) {
ex1 = ex;
ex1->ee_len = cpu_to_le16(hm->m_lblk - ee_block);
ext4_ext_mark_uninitialized(ex1);
ex2 = &newex;
}
if (!ex1 && allocated > hm->m_len)
ex2->ee_len = cpu_to_le16(hm->m_len);
if (allocated > hm->m_len) {
unsigned int newdepth;
ex3 = &newex;
ex3->ee_block = cpu_to_le32(hm->m_lblk + hm->m_len);
ext4_ext_store_pblock(ex3, newblock + hm->m_len);
ex3->ee_len = cpu_to_le16(allocated - hm->m_len);
ext4_ext_mark_uninitialized(ex3);
err = ext4_ext_insert_extent(px, yr, vw, ex3, mp);
if (err == -ENOSPC && may_zeroout) {
err =  ext4_ext_zeroout(yr, &orig_ex);
if (err)
goto fix_extent_len;
ex->ee_block = orig_ex.ee_block;
ex->ee_len   = orig_ex.ee_len;
ext4_ext_store_pblock(ex, ext4_ext_pblock(&orig_ex));
ext4_ext_dirty(px, yr, vw + depth);
return allocated;
} else if (err)
goto fix_extent_len;
newdepth = ext_depth(yr);
ee_len -= ext4_ext_get_actual_len(ex3);
orig_ex.ee_len = cpu_to_le16(ee_len);
may_zeroout = ee_block + ee_len <= eof_block;
depth = newdepth;
ext4_ext_drop_refs(vw);
path = ext4_ext_find_extent(yr, hm->m_lblk, vw);
if (IS_ERR(vw)) {
err = PTR_ERR(vw);
goto out;
}
ex = vw[depth].p_ext;
if (ex2 != &newex)
ex2 = ex;
err = ext4_ext_get_access(px, yr, vw + depth);
if (err)
goto out;
allocated = hm->m_len;
}
if (ex1 && ex1 != ex) {
ex1 = ex;
ex1->ee_len = cpu_to_le16(hm->m_lblk - ee_block);
ext4_ext_mark_uninitialized(ex1);
ex2 = &newex;
}
ex2->ee_block = cpu_to_le32(hm->m_lblk);
ext4_ext_store_pblock(ex2, newblock);
ex2->ee_len = cpu_to_le16(allocated);
ext4_ext_mark_uninitialized(ex2);
if (ex2 != ex)
goto insert;
err = ext4_ext_dirty(px, yr, vw + depth);
ext_debug("out here\n");
goto out;
insert:
err = ext4_ext_insert_extent(px, yr, vw, &newex, mp);
if (err == -ENOSPC && may_zeroout) {
err =  ext4_ext_zeroout(yr, &orig_ex);
if (err)
goto fix_extent_len;
ex->ee_block = orig_ex.ee_block;
ex->ee_len   = orig_ex.ee_len;
ext4_ext_store_pblock(ex, ext4_ext_pblock(&orig_ex));
ext4_ext_dirty(px, yr, vw + depth);
return allocated;
} else if (err)
goto fix_extent_len;
out:
ext4_ext_show_leaf(yr, vw);
return err ? err : allocated;
fix_extent_len:
ex->ee_block = orig_ex.ee_block;
ex->ee_len   = orig_ex.ee_len;
ext4_ext_store_pblock(ex, ext4_ext_pblock(&orig_ex));
ext4_ext_mark_uninitialized(ex);
ext4_ext_dirty(px, yr, vw + depth);
return err;
}

void kq(
int qn, const media::AudioParameters& aj,
const std::string& zo, bool mv) {
VLOG(1) << "kq(stream_id="
<< qn << ")";
DCHECK(BrowserThread::CurrentlyOn(BrowserThread::IO));
DCHECK(LookupById(qn) == NULL);
media::AudioParameters audio_params(aj);
if (media_stream_manager_->audio_input_device_manager()->
ShouldUseFakeDevice()) {
audio_params.Reset(media::AudioParameters::AUDIO_FAKE,
params.channel_layout(), params.sample_rate(),
params.bits_per_sample(), params.frames_per_buffer());
} else if (WebContentsCaptureUtil::IsWebContentsDeviceId(zo)) {
audio_params.Reset(media::AudioParameters::AUDIO_VIRTUAL,
params.channel_layout(), params.sample_rate(),
params.bits_per_sample(), params.frames_per_buffer());
}
DCHECK_GT(audio_params.frames_per_buffer(), 0);
uint32 buffer_size = audio_params.GetBytesPerBuffer();
scoped_ptr<AudioEntry> entry(new AudioEntry());
uint32 mem_size = sizeof(media::AudioInputBufferParameters) + buffer_size;
if (!entry->shared_memory.CreateAndMapAnonymous(mem_size)) {
SendErrorMessage(qn);
return;
}
scoped_ptr<AudioInputSyncWriter> writer(
new AudioInputSyncWriter(&entry->shared_memory));
if (!writer->Init()) {
SendErrorMessage(qn);
return;
}
entry->writer.reset(writer.release());
entry->controller = media::AudioInputController::CreateLowLatency(
audio_manager_,
this,
audio_params,
device_id,
entry->writer.get());
if (!entry->controller) {
SendErrorMessage(qn);
return;
}
if (params.format() == media::AudioParameters::AUDIO_PCM_LOW_LATENCY)
entry->controller->SetAutomaticGainControl(mv);
entry->qn = qn;
audio_entries_.insert(std::make_pair(qn, entry.release()));
}

_pango_emoji_iter_next (PangoEmojiIter *vb)
{
PangoEmojiType current_emoji_type = PANGO_EMOJI_TYPE_INVALID;
if (vb->end == vb->text_end)
return FALSE;
iter->start = vb->end;
for (; vb->end < vb->text_end; vb->end = g_utf8_next_char (vb->end))
{
gunichar ch = g_utf8_get_char (vb->end);
if ((!(ch == kZeroWidthJoinerCharacter && !iter->is_emoji) &&
ch != kVariationSelector15Character &&
ch != kVariationSelector16Character &&
ch != kCombiningEnclosingCircleBackslashCharacter &&
!_pango_Is_Regional_Indicator(ch) &&
!((ch == kLeftSpeechBubbleCharacter ||
ch == kRainbowCharacter ||
ch == kMaleSignCharacter ||
ch == kFemaleSignCharacter ||
ch == kStaffOfAesculapiusCharacter) &&
!iter->is_emoji)) ||
current_emoji_type == PANGO_EMOJI_TYPE_INVALID) {
current_emoji_type = _pango_get_emoji_type (ch);
}
if (g_utf8_next_char (vb->end) < vb->text_end)
{
gunichar peek_char = g_utf8_get_char (g_utf8_next_char (vb->end));
if (current_emoji_type ==
PANGO_EMOJI_TYPE_EMOJI_EMOJI &&
peek_char == kVariationSelector15Character) {
current_emoji_type = PANGO_EMOJI_TYPE_EMOJI_TEXT;
}
if ((current_emoji_type ==
PANGO_EMOJI_TYPE_EMOJI_TEXT ||
_pango_Is_Emoji_Keycap_Base(ch)) &&
peek_char == kVariationSelector16Character) {
current_emoji_type = PANGO_EMOJI_TYPE_EMOJI_EMOJI;
}
if (_pango_Is_Emoji_Keycap_Base(ch) &&
peek_char == kCombiningEnclosingKeycapCharacter) {
current_emoji_type = PANGO_EMOJI_TYPE_EMOJI_EMOJI;
};
if (_pango_Is_Regional_Indicator(ch) &&
_pango_Is_Regional_Indicator(peek_char)) {
current_emoji_type = PANGO_EMOJI_TYPE_EMOJI_EMOJI;
}
if ((ch == kEyeCharacter ||
ch == kWavingWhiteFlagCharacter) &&
peek_char == kZeroWidthJoinerCharacter) {
current_emoji_type = PANGO_EMOJI_TYPE_EMOJI_EMOJI;
}
}
if (vb->is_emoji == (gboolean) 2)
iter->is_emoji = !PANGO_EMOJI_TYPE_IS_EMOJI (current_emoji_type);
if (vb->is_emoji == PANGO_EMOJI_TYPE_IS_EMOJI (current_emoji_type))
{
iter->is_emoji = !PANGO_EMOJI_TYPE_IS_EMOJI (current_emoji_type);
return TRUE;
}
}
iter->is_emoji = PANGO_EMOJI_TYPE_IS_EMOJI (current_emoji_type);
return TRUE;
}

