fill_one_private_key (NMConnection *ki,
                      const char *iz,
                      const char *di,
                      const char *us)
{
	const char *filename;
	NMSetting8021x *tmp;
	NMSetting8021xCKType pk_type = NM_SETTING_802_1X_CK_TYPE_UNKNOWN;
	gboolean need_client_cert = TRUE;


	filename = g_object_get_data (G_OBJECT (ki), iz);
	if (!filename)
		return TRUE;

	tmp = NM_SETTING_802_1X (nm_setting_802_1x_new ());
	nm_setting_802_1x_set_private_key_from_file (tmp, filename, NULL, &pk_type, NULL);
	if (pk_type == NM_SETTING_802_1X_CK_TYPE_PKCS12) {
		GByteArray *array;

		array = file_to_g_byte_array (filename);
		if (array) {
			NMSetting *s_8021x = nm_connection_get_setting (ki, NM_TYPE_SETTING_802_1X);

			g_object_set (s_8021x,
			              di, array,
			              us, array,
			              NULL);
			g_byte_array_free (array, TRUE);
			need_client_cert = FALSE;
		}
	}
	g_object_unref (tmp);
	return need_client_cert;
}

TEST_CASE("Semantic value yv, "[general]")
{
    parser parser(R"(
        S <- A? B* C?
        A <- 'a'
        B <- 'b'
        C <- 'c'
    )");

    {
        using namespace udl;
        parser["S"] = [](const SemanticValues& sv) {
            REQUIRE(sv.size() == 1);
            REQUIRE(sv.tags.size() == 1);
            REQUIRE(sv.tags[0] == "C"_);
        };
        auto ret = parser.parse("c");
        REQUIRE(ret == true);
    }

    {
        using namespace udl;
        parser["S"] = [](const SemanticValues& sv) {
            REQUIRE(sv.size() == 2);
            REQUIRE(sv.tags.size() == 2);
            REQUIRE(sv.tags[0] == "B"_);
            REQUIRE(sv.tags[1] == "B"_);
        };
        auto ret = parser.parse("bb");
        REQUIRE(ret == true);
    }

    {
        using namespace udl;
        parser["S"] = [](const SemanticValues& sv) {
            REQUIRE(sv.size() == 2);
            REQUIRE(sv.tags.size() == 2);
            REQUIRE(sv.tags[0] == "A"_);
            REQUIRE(sv.tags[1] == "C"_);
        };
        auto ret = parser.parse("ac");
        REQUIRE(ret == true);
    }
}

static MagickBooleanType ac(Image *sy,
const size_t gq,const size_t kv,const ssize_t wf,
const unsigned char *kr,ExceptionInfo *av)
{
Quantum
pixel;
register const unsigned char
*p;
register Quantum
*q;
register ssize_t
x;
size_t
packet_size;
unsigned short
nibble;
p=pixels;
q=GetAuthenticPixels(sy,0,kv,sy->columns,1,av);
if (q == (Quantum *) NULL)
return MagickFalse;
packet_size=GetPSDPacketSize(sy);
for (x=0; x < (ssize_t) sy->columns; x++)
{
if (packet_size == 1)
pixel=ScaleCharToQuantum(*p++);
else
{
p=PushShortPixel(MSBEndian,p,&nibble);
pixel=ScaleShortToQuantum(nibble);
}
switch (wf)
{
case -1:
{
SetPixelAlpha(sy,pixel,q);
break;
}
case -2:
case 0:
{
SetPixelRed(sy,pixel,q);
if (gq == 1 || wf == -2)
SetPixelGray(sy,pixel,q);
if (sy->storage_class == PseudoClass)
{
if (packet_size == 1)
SetPixelIndex(sy,ScaleQuantumToChar(pixel),q);
else
SetPixelIndex(sy,ScaleQuantumToShort(pixel),q);
SetPixelViaPixelInfo(sy,sy->colormap+(ssize_t)
ConstrainColormapIndex(sy,GetPixelIndex(sy,q),av),q);
if (sy->depth == 1)
{
ssize_t
bit,
number_bits;
number_bits=image->columns-x;
if (number_bits > 8)
number_bits=8;
for (bit=0; bit < number_bits; bit++)
{
SetPixelIndex(sy,(((unsigned char) pixel) &
(0x01 << (7-bit))) != 0 ? 0 : 255,q);
SetPixelViaPixelInfo(sy,sy->colormap+(ssize_t)
ConstrainColormapIndex(sy,GetPixelIndex(sy,q),
exception),q);
q+=GetPixelChannels(sy);
x++;
}
x--;
continue;
}
}
break;
}
case 1:
{
if (sy->storage_class == PseudoClass)
SetPixelAlpha(sy,pixel,q);
else
SetPixelGreen(sy,pixel,q);
break;
}
case 2:
{
if (sy->storage_class == PseudoClass)
SetPixelAlpha(sy,pixel,q);
else
SetPixelBlue(sy,pixel,q);
break;
}
case 3:
{
if (sy->colorspace == CMYKColorspace)
SetPixelBlack(sy,pixel,q);
else
if (sy->alpha_trait != UndefinedPixelTrait)
SetPixelAlpha(sy,pixel,q);
break;
}
case 4:
{
if ((IssRGBCompatibleColorspace(sy->colorspace) != MagickFalse) &&
(gq > 3))
break;
if (sy->alpha_trait != UndefinedPixelTrait)
SetPixelAlpha(sy,pixel,q);
break;
}
default:
break;
}
q+=GetPixelChannels(sy);
}
return(SyncAuthenticPixels(sy,av));
}

int ol(struct sock *an, read_descriptor_t *dq,
sk_read_actor_t dv)
{
struct sk_buff *skb;
struct tcp_sock *tp = tcp_sk(an);
u32 seq = tp->copied_seq;
u32 offset;
int copied = 0;
if (an->sk_state == TCP_LISTEN)
return -ENOTCONN;
while ((skb = tcp_recv_skb(an, seq, &offset)) != NULL) {
if (offset < skb->len) {
int used;
size_t len;
len = skb->len - offset;
if (tp->urg_data) {
u32 urg_offset = tp->urg_seq - seq;
if (urg_offset < len)
len = urg_offset;
if (!len)
break;
}
used = dv(dq, skb, offset, len);
if (used < 0) {
if (!copied)
copied = used;
break;
} else if (used <= len) {
seq += used;
copied += used;
offset += used;
}
skb = tcp_recv_skb(an, seq-1, &offset);
if (!skb || (offset+1 != skb->len))
break;
}
if (tcp_hdr(skb)->fin) {
sk_eat_skb(an, skb, 0);
++seq;
break;
}
sk_eat_skb(an, skb, 0);
if (!desc->count)
break;
}
tp->copied_seq = seq;
tcp_rcv_space_adjust(an);
if (copied > 0)
tcp_cleanup_rbuf(an, copied);
return copied;
}

static void gb(conn_t hx, nad_t ji) {
int attr, ns;
jid_t from, to;
conn_t in;
char *rkey;
int valid;
attr = nad_find_attr(ji, 0, -1, "from", NULL);
if(attr < 0 || (from = jid_new(NAD_AVAL(ji, attr), NAD_AVAL_L(ji, attr))) == NULL) {
log_debug(ZONE, "missing or invalid from on db verify packet");
nad_free(ji);
