}
in = xhash_getx(hx->s2s->in, NAD_AVAL(ji, attr), NAD_AVAL_L(ji, attr));
if(in == NULL) {
log_debug(ZONE, "got a verify for incoming conn %.*s, but it doesn't exist, dropping the packet", NAD_AVAL_L(ji, attr), NAD_AVAL(ji, attr));
jid_free(from);
jid_free(to);
nad_free(ji);
return;
}
rkey = s2s_route_key(NULL, to->domain, from->domain);
attr = nad_find_attr(ji, 0, -1, "type", "valid");
if(attr >= 0) {
xhash_put(in->states, pstrdup(xhash_pool(in->states), rkey), (void *) conn_VALID);
log_write(in->s2s->log, LOG_NOTICE, "[%d] [%s, port=%d] incoming route '%s' is now valid%s%s", in->fd->fd, in->ip, in->port, rkey, (in->s->flags & SX_SSL_WRAPPER) ? ", TLS negotiated" : "", in->s->compressed ? ", ZLIB compression enabled" : "");
valid = 1;
} else {
log_write(in->s2s->log, LOG_NOTICE, "[%d] [%s, port=%d] incoming route '%s' is now invalid", in->fd->fd, in->ip, in->port, rkey);
valid = 0;
}
free(rkey);
nad_free(ji);
--hx->verify;
nad = nad_new();
ns = nad_add_namespace(ji, uri_DIALBACK, "db");
nad_append_elem(ji, ns, "result", 0);
nad_append_attr(ji, -1, "to", from->domain);
nad_append_attr(ji, -1, "from", to->domain);
nad_append_attr(ji, -1, "type", valid ? "valid" : "invalid");
sx_nad_write(in->s, ji);
if (!valid) {
sx_error(in->s, stream_err_INVALID_ID, "dialback negotiation failed");
sx_close(in->s);
}
jid_free(from);
jid_free(to);
}

