static int gt(struct sock *tv)
{
struct sk_buff *skb;
struct udphdr *uh;
struct udp_sock  *up = udp_sk(tv);
struct inet_sock *inet = inet_sk(tv);
struct flowi6 *fl6 = &inet->cork.fl.u.ip6;
int err = 0;
int is_udplite = IS_UDPLITE(tv);
__wsum csum = 0;
if ((skb = skb_peek(&tv->sk_write_queue)) == NULL)
goto out;
uh = udp_hdr(skb);
uh->source = fl6->fl6_sport;
uh->dest = fl6->fl6_dport;
uh->len = htons(up->len);
uh->check = 0;
if (is_udplite)
csum = udplite_csum_outgoing(tv, skb);
else if (skb->ip_summed == CHECKSUM_PARTIAL) {
udp6_hwcsum_outgoing(tv, skb, &fl6->saddr, &fl6->daddr,
up->len);
goto send;
} else
csum = udp_csum_outgoing(tv, skb);
uh->check = csum_ipv6_magic(&fl6->saddr, &fl6->daddr,
up->len, fl6->flowi6_proto, csum);
if (uh->check == 0)
uh->check = CSUM_MANGLED_0;
send:
err = ip6_push_pending_frames(tv);
if (err) {
if (err == -ENOBUFS && !inet6_sk(tv)->recverr) {
UDP6_INC_STATS_USER(sock_net(tv),
UDP_MIB_SNDBUFERRORS, is_udplite);
err = 0;
}
} else
UDP6_INC_STATS_USER(sock_net(tv),
UDP_MIB_OUTDATAGRAMS, is_udplite);
out:
up->len = 0;
up->pending = 0;
return err;
}

krb5_gss_inquire_sec_context_by_oid (OM_uint32 *ud,
const gss_ctx_id_t wd,
const gss_OID ct,
gss_buffer_set_t *em)
{
krb5_gss_ctx_id_rec *ctx;
size_t i;
if (ud == NULL)
return GSS_S_CALL_INACCESSIBLE_WRITE;
*ud = 0;
if (ct == GSS_C_NO_OID)
return GSS_S_CALL_INACCESSIBLE_READ;
if (em == NULL)
return GSS_S_CALL_INACCESSIBLE_WRITE;
*em = GSS_C_NO_BUFFER_SET;
ctx = (krb5_gss_ctx_id_rec *) wd;
if (!ctx->established)
return GSS_S_NO_CONTEXT;
for (i = 0; i < sizeof(krb5_gss_inquire_sec_context_by_oid_ops)/
sizeof(krb5_gss_inquire_sec_context_by_oid_ops[0]); i++) {
if (g_OID_prefix_equal(ct, &krb5_gss_inquire_sec_context_by_oid_ops[i].oid)) {
return (*krb5_gss_inquire_sec_context_by_oid_ops[i].func)(ud,
context_handle,
desired_object,
data_set);
}
}
*ud = EINVAL;
return GSS_S_UNAVAILABLE;
}

