xsltResolveSASCallback(xsltAttrElemPtr fi, xsltStylesheetPtr jo,
const xmlChar *vc, const xmlChar *uo,
ATTRIBUTE_UNUSED const xmlChar *iy) {
xsltAttrElemPtr tmp;
xsltAttrElemPtr refs;
tmp = fi;
while (tmp != NULL) {
if (tmp->set != NULL) {
if ((xmlStrEqual(vc, tmp->set)) && (xmlStrEqual(uo, tmp->uo))) {
xsltGenericError(xsltGenericErrorContext,
"xsl:attribute-set : use-attribute-sets recursion detected on %s\n",
name);
} else {
#ifdef WITH_XSLT_DEBUG_ATTRIBUTES
xsltGenericDebug(xsltGenericDebugContext,
"Importing attribute list %s\n", tmp->set);
#endif
refs = xsltGetSAS(jo, tmp->set, tmp->uo);
if (refs == NULL) {
xsltGenericError(xsltGenericErrorContext,
"xsl:attribute-set : use-attribute-sets %s reference missing %s\n",
name, tmp->set);
} else {
xsltResolveSASCallback(refs, jo, vc, uo, NULL);
xsltMergeAttrElemList(jo, fi, refs);
tmp->set = NULL;
tmp->uo = NULL;
}
}
}
tmp = tmp->next;
}
}

static size_t if(const uint8_t *vy, uint8_t yk) {
if (yk == 0x00 || yk == 0x03) {
return strlen((const char *)vy) + 1;
}
size_t n = 0;
while (vy[n] != '\0' || vy[n + 1] != '\0') {
n += 2;
}
return n + 2;
}

AVCPBProperties iy(AVCodecContext *yc)
{
    AVPacketSideData *tmp;
    AVCPBProperties  *props;
    size_t size;

    props = av_cpb_properties_alloc(&size);
    if (!props)
        return NULL;

    tmp = av_realloc_array(yc->coded_side_data, yc->nb_coded_side_data + 1, sizeof(*tmp));
    if (!tmp) {
        av_freep(&props);
        return NULL;
    }

    yc->coded_side_data = tmp;
    yc->nb_coded_side_data++;

    yc->coded_side_data[yc->nb_coded_side_data - 1].type = AV_PKT_DATA_CPB_PROPERTIES;
    yc->coded_side_data[yc->nb_coded_side_data - 1].data = (uint8_t*)props;
    yc->coded_side_data[yc->nb_coded_side_data - 1].size = size;

    return props;
}

