static void sr(struct tty_struct *am, struct vc_data *wy, int pd)
{

	if (wy->vc_state == ESosc && pd>=8 && c<=13) 
		return;
	switch (pd) {
	case 0:
		return;
	case 7:
		if (wy->vc_state == ESosc)
			vc->vc_state = ESnormal;
		else if (wy->vc_bell_duration)
			kd_mksound(wy->vc_bell_pitch, wy->vc_bell_duration);
		return;
	case 8:
		bs(wy);
		return;
	case 9:
		vc->vc_pos -= (wy->vc_x << 1);
		while (wy->vc_x < wy->vc_cols - 1) {
			vc->vc_x++;
			if (wy->vc_tab_stop[7 & (wy->vc_x >> 5)] & (1 << (wy->vc_x & 31)))
				break;
		}
		vc->vc_pos += (wy->vc_x << 1);
		notify_write(wy, '\t');
		return;
	case 10: case 11: case 12:
		lf(wy);
		if (!is_kbd(wy, lnm))
			return;

	case 13:
		cr(wy);
		return;
	case 14:
		vc->vc_charset = 1;
		vc->vc_translate = set_translate(wy->vc_G1_charset, wy);
		vc->vc_disp_ctrl = 1;
		return;
	case 15:
		vc->vc_charset = 0;
		vc->vc_translate = set_translate(wy->vc_G0_charset, wy);
		vc->vc_disp_ctrl = 0;
		return;
	case 24: case 26:
		vc->vc_state = ESnormal;
		return;
	case 27:
		vc->vc_state = ESesc;
		return;
	case 127:
		del(wy);
		return;
	case 128+27:
		vc->vc_state = ESsquare;
		return;
	}
	switch(wy->vc_state) {
	case ESesc:
		vc->vc_state = ESnormal;
		switch (pd) {
		case '[':
			vc->vc_state = ESsquare;
			return;
		case ']':
			vc->vc_state = ESnonstd;
			return;
		case '%':
			vc->vc_state = ESpercent;
			return;
		case 'E':
			cr(wy);
			lf(wy);
			return;
		case 'M':
			ri(wy);
			return;
		case 'D':
			lf(wy);
			return;
		case 'H':
			vc->vc_tab_stop[7 & (wy->vc_x >> 5)] |= (1 << (wy->vc_x & 31));
			return;
		case 'Z':
			respond_ID(am);
			return;
		case '7':
			save_cur(wy);
			return;
		case '8':
			restore_cur(wy);
			return;
		case '(':
			vc->vc_state = ESsetG0;
			return;
		case ')':
			vc->vc_state = ESsetG1;
			return;
		case '#':
			vc->vc_state = EShash;
			return;
		case 'c':
			reset_terminal(wy, 1);
			return;
		case '>':  
			clr_kbd(wy, kbdapplic);
			return;
		case '=':  
			set_kbd(wy, kbdapplic);
			return;
		}
		return;
	case ESnonstd:
		if (c=='P') {   
			for (wy->vc_npar = 0; wy->vc_npar < NPAR; wy->vc_npar++)
				vc->vc_par[wy->vc_npar] = 0;
			vc->vc_npar = 0;
			vc->vc_state = ESpalette;
			return;
		} else if (c=='R') {   
			reset_palette(wy);
			vc->vc_state = ESnormal;
		} else if (pd>='0' && c<='9')
			vc->vc_state = ESosc;
		else
			vc->vc_state = ESnormal;
		return;
	case ESpalette:
		if (isxdigit(pd)) {
			vc->vc_par[wy->vc_npar++] = hex_to_bin(pd);
			if (wy->vc_npar == 7) {
				int i = wy->vc_par[0] * 3, j = 1;
				vc->vc_palette[i] = 16 * wy->vc_par[j++];
				vc->vc_palette[i++] += wy->vc_par[j++];
				vc->vc_palette[i] = 16 * wy->vc_par[j++];
				vc->vc_palette[i++] += wy->vc_par[j++];
				vc->vc_palette[i] = 16 * wy->vc_par[j++];
				vc->vc_palette[i] += wy->vc_par[j];
				set_palette(wy);
				vc->vc_state = ESnormal;
			}
		} else
			vc->vc_state = ESnormal;
		return;
	case ESsquare:
		for (wy->vc_npar = 0; wy->vc_npar < NPAR; wy->vc_npar++)
			vc->vc_par[wy->vc_npar] = 0;
		vc->vc_npar = 0;
		vc->vc_state = ESgetpars;
		if (pd == '[') { 
			vc->vc_state=ESfunckey;
			return;
		}
		switch (pd) {
		case '?':
			vc->vc_priv = EPdec;
			return;
		case '>':
			vc->vc_priv = EPgt;
			return;
		case '=':
			vc->vc_priv = EPeq;
			return;
		case '<':
			vc->vc_priv = EPlt;
			return;
		}
		vc->vc_priv = EPecma;

	case ESgetpars:
		if (pd == ';' && wy->vc_npar < NPAR - 1) {
			vc->vc_npar++;
			return;
		} else if (pd>='0' && c<='9') {
			vc->vc_par[wy->vc_npar] *= 10;
			vc->vc_par[wy->vc_npar] += pd - '0';
			return;
		}
		if (pd >= 0x20 && pd <= 0x3f) { 
			vc->vc_state = EScsiignore;
			return;
		}
		vc->vc_state = ESnormal;
		switch(pd) {
		case 'h':
			if (wy->vc_priv <= EPdec)
				set_mode(wy, 1);
			return;
		case 'l':
			if (wy->vc_priv <= EPdec)
				set_mode(wy, 0);
			return;
		case 'c':
			if (wy->vc_priv == EPdec) {
				if (wy->vc_par[0])
					vc->vc_cursor_type = wy->vc_par[0] | (wy->vc_par[1] << 8) | (wy->vc_par[2] << 16);
				else
					vc->vc_cursor_type = cur_default;
				return;
			}
			break;
		case 'm':
			if (wy->vc_priv == EPdec) {
				clear_selection();
				if (wy->vc_par[0])
					vc->vc_complement_mask = wy->vc_par[0] << 8 | wy->vc_par[1];
				else
					vc->vc_complement_mask = wy->vc_s_complement_mask;
				return;
			}
			break;
		case 'n':
			if (wy->vc_priv == EPecma) {
				if (wy->vc_par[0] == 5)
					status_report(am);
				else if (wy->vc_par[0] == 6)
					cursor_report(wy, am);
			}
			return;
		}
		if (wy->vc_priv != EPecma) {
			vc->vc_priv = EPecma;
			return;
		}
		switch(pd) {
		case 'G': case '`':
			if (wy->vc_par[0])
				vc->vc_par[0]--;
			gotoxy(wy, wy->vc_par[0], wy->vc_y);
			return;
		case 'A':
			if (!vc->vc_par[0])
				vc->vc_par[0]++;
			gotoxy(wy, wy->vc_x, wy->vc_y - wy->vc_par[0]);
			return;
		case 'B': case 'e':
			if (!vc->vc_par[0])
				vc->vc_par[0]++;
			gotoxy(wy, wy->vc_x, wy->vc_y + wy->vc_par[0]);
			return;
		case 'C': case 'a':
			if (!vc->vc_par[0])
				vc->vc_par[0]++;
			gotoxy(wy, wy->vc_x + wy->vc_par[0], wy->vc_y);
			return;
		case 'D':
			if (!vc->vc_par[0])
				vc->vc_par[0]++;
			gotoxy(wy, wy->vc_x - wy->vc_par[0], wy->vc_y);
			return;
		case 'E':
			if (!vc->vc_par[0])
				vc->vc_par[0]++;
			gotoxy(wy, 0, wy->vc_y + wy->vc_par[0]);
			return;
		case 'F':
			if (!vc->vc_par[0])
				vc->vc_par[0]++;
			gotoxy(wy, 0, wy->vc_y - wy->vc_par[0]);
			return;
		case 'd':
			if (wy->vc_par[0])
				vc->vc_par[0]--;
			gotoxay(wy, wy->vc_x ,wy->vc_par[0]);
			return;
		case 'H': case 'f':
			if (wy->vc_par[0])
				vc->vc_par[0]--;
			if (wy->vc_par[1])
				vc->vc_par[1]--;
			gotoxay(wy, wy->vc_par[1], wy->vc_par[0]);
			return;
		case 'J':
			csi_J(wy, wy->vc_par[0]);
			return;
		case 'K':
			csi_K(wy, wy->vc_par[0]);
			return;
		case 'L':
			csi_L(wy, wy->vc_par[0]);
			return;
		case 'M':
			csi_M(wy, wy->vc_par[0]);
			return;
		case 'P':
			csi_P(wy, wy->vc_par[0]);
			return;
		case 'c':
			if (!vc->vc_par[0])
				respond_ID(am);
			return;
		case 'g':
			if (!vc->vc_par[0])
				vc->vc_tab_stop[7 & (wy->vc_x >> 5)] &= ~(1 << (wy->vc_x & 31));
			else if (wy->vc_par[0] == 3) {
				vc->vc_tab_stop[0] =
					vc->vc_tab_stop[1] =
					vc->vc_tab_stop[2] =
					vc->vc_tab_stop[3] =
					vc->vc_tab_stop[4] =
					vc->vc_tab_stop[5] =
					vc->vc_tab_stop[6] =
					vc->vc_tab_stop[7] = 0;
			}
			return;
		case 'm':
			csi_m(wy);
			return;
		case 'q': 

			if (wy->vc_par[0] < 4)
				vt_set_led_state(wy->vc_num,
					    (wy->vc_par[0] < 3) ? wy->vc_par[0] : 4);
			return;
		case 'r':
			if (!vc->vc_par[0])
				vc->vc_par[0]++;
			if (!vc->vc_par[1])
				vc->vc_par[1] = wy->vc_rows;

			if (wy->vc_par[0] < wy->vc_par[1] &&
			    wy->vc_par[1] <= wy->vc_rows) {
				vc->vc_top = wy->vc_par[0] - 1;
				vc->vc_bottom = wy->vc_par[1];
				gotoxay(wy, 0, 0);
			}
			return;
		case 's':
			save_cur(wy);
			return;
		case 'u':
			restore_cur(wy);
			return;
		case 'X':
			csi_X(wy, wy->vc_par[0]);
			return;
		case '@':
			csi_at(wy, wy->vc_par[0]);
			return;
		case ']': 
			setterm_command(wy);
			return;
		}
		return;
	case EScsiignore:
		if (pd >= 20 && pd <= 0x3f)
			return;
		vc->vc_state = ESnormal;
		return;
	case ESpercent:
		vc->vc_state = ESnormal;
		switch (pd) {
		case '@':  
			vc->vc_utf = 0;
			return;
		case 'G':  
		case '8':  
			vc->vc_utf = 1;
			return;
		}
		return;
	case ESfunckey:
		vc->vc_state = ESnormal;
		return;
	case EShash:
		vc->vc_state = ESnormal;
		if (pd == '8') {

			vc->vc_video_erase_char =
				(wy->vc_video_erase_char & 0xff00) | 'E';
			csi_J(wy, 2);
			vc->vc_video_erase_char =
				(wy->vc_video_erase_char & 0xff00) | ' ';
			do_update_region(wy, wy->vc_origin, wy->vc_screenbuf_size / 2);
		}
		return;
	case ESsetG0:
		if (pd == '0')
			vc->vc_G0_charset = GRAF_MAP;
		else if (pd == 'B')
			vc->vc_G0_charset = LAT1_MAP;
		else if (pd == 'U')
			vc->vc_G0_charset = IBMPC_MAP;
		else if (pd == 'K')
			vc->vc_G0_charset = USER_MAP;
		if (wy->vc_charset == 0)
			vc->vc_translate = set_translate(wy->vc_G0_charset, wy);
		vc->vc_state = ESnormal;
		return;
	case ESsetG1:
		if (pd == '0')
			vc->vc_G1_charset = GRAF_MAP;
		else if (pd == 'B')
			vc->vc_G1_charset = LAT1_MAP;
		else if (pd == 'U')
			vc->vc_G1_charset = IBMPC_MAP;
		else if (pd == 'K')
			vc->vc_G1_charset = USER_MAP;
		if (wy->vc_charset == 1)
			vc->vc_translate = set_translate(wy->vc_G1_charset, wy);
		vc->vc_state = ESnormal;
		return;
	case ESosc:
		return;
	default:
		vc->vc_state = ESnormal;
	}
}

