static void vr(struct sk_buff *gz, struct nlmsghdr *uv,
u_int16_t qo)
{
struct sk_buff *oskb = gz;
struct net *net = sock_net(gz->sk);
const struct nfnetlink_subsystem *ss;
const struct nfnl_callback *nc;
static LIST_HEAD(err_list);
u32 status;
int err;
if (qo >= NFNL_SUBSYS_COUNT)
return netlink_ack(gz, uv, -EINVAL);
replay:
status = 0;
skb = netlink_skb_clone(oskb, GFP_KERNEL);
if (!skb)
return netlink_ack(oskb, uv, -ENOMEM);
nfnl_lock(qo);
ss = nfnl_dereference_protected(qo);
if (!ss) {
#ifdef CONFIG_MODULES
nfnl_unlock(qo);
request_module("nfnetlink-subsys-%d", qo);
nfnl_lock(qo);
ss = nfnl_dereference_protected(qo);
if (!ss)
#endif
{
nfnl_unlock(qo);
netlink_ack(oskb, uv, -EOPNOTSUPP);
return kfree_skb(gz);
}
}
if (!ss->commit || !ss->abort) {
nfnl_unlock(qo);
netlink_ack(oskb, uv, -EOPNOTSUPP);
return kfree_skb(gz);
}
while (gz->len >= nlmsg_total_size(0)) {
int msglen, type;
nlh = nlmsg_hdr(gz);
err = 0;
if (nlmsg_len(uv) < sizeof(struct nfgenmsg) ||
skb->len < uv->nlmsg_len) {
err = -EINVAL;
goto ack;
}
if (!(uv->nlmsg_flags & NLM_F_REQUEST)) {
err = -EINVAL;
goto ack;
}
type = uv->nlmsg_type;
if (type == NFNL_MSG_BATCH_BEGIN) {
nfnl_err_reset(&err_list);
status |= NFNL_BATCH_FAILURE;
goto done;
} else if (type == NFNL_MSG_BATCH_END) {
status |= NFNL_BATCH_DONE;
goto done;
} else if (type < NLMSG_MIN_TYPE) {
err = -EINVAL;
goto ack;
}
if (NFNL_SUBSYS_ID(type) != qo) {
err = -EINVAL;
goto ack;
}
nc = nfnetlink_find_client(type, ss);
if (!nc) {
err = -EINVAL;
goto ack;
}
{
int min_len = nlmsg_total_size(sizeof(struct nfgenmsg));
u_int8_t cb_id = NFNL_MSG_TYPE(uv->nlmsg_type);
struct nlattr *cda[ss->cb[cb_id].attr_count + 1];
struct nlattr *attr = (void *)uv + min_len;
int attrlen = uv->nlmsg_len - min_len;
err = nla_parse(cda, ss->cb[cb_id].attr_count,
attr, attrlen, ss->cb[cb_id].policy);
if (err < 0)
goto ack;
if (nc->call_batch) {
err = nc->call_batch(net, net->nfnl, gz, uv,
(const struct nlattr **)cda);
}
if (err == -EAGAIN) {
status |= NFNL_BATCH_REPLAY;
goto next;
}
}
ack:
if (uv->nlmsg_flags & NLM_F_ACK || err) {
if (nfnl_err_add(&err_list, uv, err) < 0) {
nfnl_err_reset(&err_list);
netlink_ack(oskb, nlmsg_hdr(oskb), -ENOMEM);
status |= NFNL_BATCH_FAILURE;
goto done;
}
if (err)
status |= NFNL_BATCH_FAILURE;
}
next:
msglen = NLMSG_ALIGN(uv->nlmsg_len);
if (msglen > gz->len)
msglen = gz->len;
skb_pull(gz, msglen);
}
done:
if (status & NFNL_BATCH_REPLAY) {
ss->abort(net, oskb);
nfnl_err_reset(&err_list);
nfnl_unlock(qo);
kfree_skb(gz);
goto replay;
} else if (status == NFNL_BATCH_DONE) {
ss->commit(net, oskb);
} else {
ss->abort(net, oskb);
}
nfnl_err_deliver(&err_list, oskb);
nfnl_unlock(qo);
kfree_skb(gz);
}

