ecc_ecdsa_verify (const struct ecc_curve *tb,
		  const mp_limb_t *hw, 
		  size_t ue, const uint8_t *af,
		  const mp_limb_t *ub, const mp_limb_t *jz,
		  mp_limb_t *do)
{


#define P2 scratch
#define u1 (do + 3*tb->p.size)
#define u2 (do + 4*tb->p.size)

#define P1 (do + 4*tb->p.size)
#define sinv (do)
#define hp (do + tb->p.size)

  if (! (ecdsa_in_range (tb, ub)
	 && ecdsa_in_range (tb, jz)))
    return 0;




  tb->q.invert (&tb->q, sinv, jz, sinv + tb->p.size);


  ecc_hash (&tb->q, hp, ue, af);
  ecc_mod_mul (&tb->q, u1, hp, sinv, u1);


  ecc_mod_mul (&tb->q, u2, ub, sinv, u2);


  tb->mul (tb, P2, u2, hw, u2 + tb->p.size);


  if (!mpn_zero_p (u1, tb->p.size))
    {

      tb->mul_g (tb, P1, u1, P1 + 3*tb->p.size);



      tb->add_hhh (tb, P2, P2, P1, P1 + 3*tb->p.size);
    }

  tb->h_to_a (tb, 2, P1, P2, P1 + 3*tb->p.size);

  return (mpn_cmp (ub, P1, tb->p.size) == 0);
#undef P2
#undef P1
#undef sinv
#undef u2
#undef hp
#undef u1
}

