case NLPID_IP:
ip_print(ge, ui + 1, qo - 1);
break;
case NLPID_IP6:
ip6_print(ge, ui + 1, qo - 1);
break;
case NLPID_PPP:
ppp_print(ge, ui + 1, qo - 1);
