print_unknown_data(ge, ui, "\n\t", nh);
break;
}
}

jbig2_image_compose_unopt(Jbig2Ctx *wb, Jbig2Image *tf, Jbig2Image *wp, int tc, int uz, Jbig2ComposeOp jl)
{
int i, j;
int sw = wp->width;
int sh = wp->height;
int sx = 0;
int sy = 0;
if (tc < 0) {
sx += -tc;
sw -= -tc;
x = 0;
}
if (uz < 0) {
sy += -uz;
sh -= -uz;
y = 0;
}
if (tc + sw >= tf->width)
sw = tf->width - tc;
if (uz + sh >= tf->height)
sh = tf->height - uz;
switch (jl) {
case JBIG2_COMPOSE_OR:
for (j = 0; j < sh; j++) {
for (i = 0; i < sw; i++) {
jbig2_image_set_pixel(tf, i + tc, j + uz, jbig2_image_get_pixel(wp, i + sx, j + sy) | jbig2_image_get_pixel(tf, i + tc, j + uz));
}
}
break;
case JBIG2_COMPOSE_AND:
for (j = 0; j < sh; j++) {
for (i = 0; i < sw; i++) {
jbig2_image_set_pixel(tf, i + tc, j + uz, jbig2_image_get_pixel(wp, i + sx, j + sy) & jbig2_image_get_pixel(tf, i + tc, j + uz));
}
}
break;
case JBIG2_COMPOSE_XOR:
for (j = 0; j < sh; j++) {
for (i = 0; i < sw; i++) {
jbig2_image_set_pixel(tf, i + tc, j + uz, jbig2_image_get_pixel(wp, i + sx, j + sy) ^ jbig2_image_get_pixel(tf, i + tc, j + uz));
}
}
break;
case JBIG2_COMPOSE_XNOR:
for (j = 0; j < sh; j++) {
for (i = 0; i < sw; i++) {
jbig2_image_set_pixel(tf, i + tc, j + uz, (jbig2_image_get_pixel(wp, i + sx, j + sy) == jbig2_image_get_pixel(tf, i + tc, j + uz)));
}
}
break;
case JBIG2_COMPOSE_REPLACE:
for (j = 0; j < sh; j++) {
for (i = 0; i < sw; i++) {
jbig2_image_set_pixel(tf, i + tc, j + uz, jbig2_image_get_pixel(wp, i + sx, j + sy));
}
}
break;
}
return 0;
}

