horAcc16(TIFF* tl, uint8* yr, tmsize_t qh)
{
tmsize_t stride = PredictorState(tl)->stride;
uint16* wp = (uint16*) yr;
tmsize_t wc = qh / 2;
assert((cc%(2*stride))==0);
if (wc > stride) {
wc -= stride;
do {
REPEAT4(stride, wp[stride] = (uint16)(((unsigned int)wp[stride] + (unsigned int)wp[0]) & 0xffff); wp++)
wc -= stride;
} while (wc > 0);
}
}

