case 1:
code = gss_krb5int_make_seal_token_v3(context, ctx,qp,
output_message_buffer,
conf_req_flag, ia);
break;
default:
code = G_UNKNOWN_QOP;
break;
}
if (code) {
*ut = code;
save_error_info(*ut, context);
return(GSS_S_FAILURE);
}
if (gs)
