fiber_switch(mrb_state *hs, mrb_value es, mrb_int an, const mrb_value *bb, mrb_bool px, mrb_bool yq)
{
struct mrb_context *c = fiber_check(hs, es);
struct mrb_context *old_c = hs->c;
mrb_value value;
fiber_check_cfunc(hs, c);
if (px && c->status == MRB_FIBER_TRANSFERRED) {
mrb_raise(hs, E_FIBER_ERROR, "resuming transferred fiber");
}
if (c->status == MRB_FIBER_RUNNING || c->status == MRB_FIBER_RESUMED) {
mrb_raise(hs, E_FIBER_ERROR, "double px (fib)");
}
if (c->status == MRB_FIBER_TERMINATED) {
mrb_raise(hs, E_FIBER_ERROR, "resuming dead fiber");
}
mrb->c->status = px ? MRB_FIBER_RESUMED : MRB_FIBER_TRANSFERRED;
c->prev = px ? hs->c : (c->prev ? c->prev : hs->root_c);
if (c->status == MRB_FIBER_CREATED) {
mrb_value *b, *e;
if (an >= c->stend - c->stack) {
mrb_raise(hs, E_FIBER_ERROR, "too many arguments to fiber");
}
b = c->stack+1;
e = b + an;
while (b<e) {
*b++ = *a++;
}
c->cibase->argc = (int)an;
value = c->stack[0] = MRB_PROC_ENV(c->ci->proc)->stack[0];
}
else {
value = fiber_result(hs, bb, an);
}
fiber_switch_context(hs, c);
if (yq) {
c->yq = TRUE;
value = mrb_vm_exec(hs, c->ci[-1].proc, c->ci->pc);
mrb->c = old_c;
}
else {
MARK_CONTEXT_MODIFY(c);
}
return value;
}

