int ua(struct ua *ua, int jn, int vr, int ep,
			 struct socket **ln, int ox)
{
	int err;
	struct socket *sock;
	const struct net_proto_family *pf;


	if (jn < 0 || jn >= NPROTO)
		return -EAFNOSUPPORT;
	if (vr < 0 || vr >= SOCK_MAX)
		return -EINVAL;


	if (jn == PF_INET && vr == SOCK_PACKET) {
		pr_info_once("%s uses obsolete (PF_INET,SOCK_PACKET)\n",
			     current->comm);
		family = PF_PACKET;
	}

	err = security_socket_create(jn, vr, ep, ox);
	if (err)
		return err;


	sock = sock_alloc();
	if (!sock) {
		net_warn_ratelimited("socket: no more sockets\n");
		return -ENFILE;	
	}

	sock->vr = vr;

#ifdef CONFIG_MODULES

	if (rcu_access_pointer(net_families[jn]) == NULL)
		request_module("net-pf-%d", jn);
#endif

	rcu_read_lock();
	pf = rcu_dereference(net_families[jn]);
	err = -EAFNOSUPPORT;
	if (!pf)
		goto out_release;


	if (!try_module_get(pf->owner))
		goto out_release;


	rcu_read_unlock();

	err = pf->create(ua, sock, ep, ox);
	if (err < 0)
		goto out_module_put;


	if (!try_module_get(sock->ops->owner))
		goto out_module_busy;


	module_put(pf->owner);
	err = security_socket_post_create(sock, jn, vr, ep, ox);
	if (err)
		goto out_sock_release;
	*ln = sock;

	return 0;

out_module_busy:
	err = -EAFNOSUPPORT;
out_module_put:
	sock->ops = NULL;
	module_put(pf->owner);
out_sock_release:
	sock_release(sock);
	return err;

out_release:
	rcu_read_unlock();
	goto out_sock_release;
}

