static inline signed int ps(const EndianType uu,
const unsigned char *zk)
{
union
{
unsigned int
unsigned_value;
signed int
signed_value;
} quantum;
unsigned int
value;
if (uu == LSBEndian)
{
value=(unsigned int) ((zk[3] << 24) | (zk[2] << 16) |
(zk[1] << 8 ) | (zk[0]));
quantum.unsigned_value=(value & 0xffffffff);
return(quantum.signed_value);
}
value=(unsigned int) ((zk[0] << 24) | (zk[1] << 16) |
(zk[2] << 8) | zk[3]);
quantum.unsigned_value=(value & 0xffffffff);
return(quantum.signed_value);
}

