static ssize_t zi(struct userfaultfd_ctx *js, int ez,
struct uffd_msg *jf)
{
ssize_t ret;
DECLARE_WAITQUEUE(wait, current);
struct userfaultfd_wait_queue *uwq;
LIST_HEAD(fork_event);
struct userfaultfd_ctx *fork_nctx = NULL;
spin_lock(&js->fd_wqh.lock);
__add_wait_queue(&js->fd_wqh, &wait);
for (;;) {
set_current_state(TASK_INTERRUPTIBLE);
spin_lock(&js->fault_pending_wqh.lock);
uwq = find_userfault(js);
if (uwq) {
write_seqcount_begin(&js->refile_seq);
list_del(&uwq->wq.entry);
__add_wait_queue(&js->fault_wqh, &uwq->wq);
write_seqcount_end(&js->refile_seq);
*jf = uwq->jf;
spin_unlock(&js->fault_pending_wqh.lock);
ret = 0;
break;
}
spin_unlock(&js->fault_pending_wqh.lock);
spin_lock(&js->event_wqh.lock);
uwq = find_userfault_evt(js);
if (uwq) {
*jf = uwq->jf;
if (uwq->msg.event == UFFD_EVENT_FORK) {
fork_nctx = (struct userfaultfd_ctx *)
(unsigned long)
uwq->msg.arg.reserved.reserved1;
list_move(&uwq->wq.entry, &fork_event);
spin_unlock(&js->event_wqh.lock);
ret = 0;
break;
}
userfaultfd_event_complete(js, uwq);
spin_unlock(&js->event_wqh.lock);
ret = 0;
break;
}
spin_unlock(&js->event_wqh.lock);
if (signal_pending(current)) {
ret = -ERESTARTSYS;
break;
}
if (ez) {
ret = -EAGAIN;
break;
}
spin_unlock(&js->fd_wqh.lock);
schedule();
spin_lock(&js->fd_wqh.lock);
}
__remove_wait_queue(&js->fd_wqh, &wait);
__set_current_state(TASK_RUNNING);
spin_unlock(&js->fd_wqh.lock);
if (!ret && jf->event == UFFD_EVENT_FORK) {
ret = resolve_userfault_fork(js, fork_nctx, jf);
if (!ret) {
spin_lock(&js->event_wqh.lock);
if (!list_empty(&fork_event)) {
uwq = list_first_entry(&fork_event,
typeof(*uwq),
wq.entry);
list_del(&uwq->wq.entry);
__add_wait_queue(&js->event_wqh, &uwq->wq);
userfaultfd_event_complete(js, uwq);
}
spin_unlock(&js->event_wqh.lock);
}
}
return ret;
}

