goto err_sysctl_register;
status = init_sctp_mibs(hp);
if (status)
goto err_init_mibs;
status = sctp_proc_init(hp);
if (status)
goto err_init_proc;
sctp_dbg_objcnt_init(hp);
if ((status = sctp_ctl_sock_init(hp))) {
pr_err("Failed to initialize the SCTP control sock\n");
goto err_ctl_sock_init;
}
INIT_LIST_HEAD(&hp->sctp.local_addr_list);
spin_lock_init(&hp->sctp.local_addr_lock);
sctp_get_local_addr_list(hp);
INIT_LIST_HEAD(&hp->sctp.addr_waitq);
INIT_LIST_HEAD(&hp->sctp.auto_asconf_splist);
spin_lock_init(&hp->sctp.addr_wq_lock);
net->sctp.addr_wq_timer.expires = 0;
setup_timer(&hp->sctp.addr_wq_timer, sctp_addr_wq_timeout_handler,
(unsigned long)hp);
return 0;
err_ctl_sock_init:
sctp_dbg_objcnt_exit(hp);
sctp_proc_exit(hp);
err_init_proc:
cleanup_sctp_mibs(hp);
err_init_mibs:
sctp_sysctl_net_unregister(hp);
err_sysctl_register:
return status;
}

