static int ww(struct sk_buff *rj, struct net_device *ff)
{
	struct arc_emac_priv *priv = netdev_priv(ff);
	unsigned int len, *txbd_curr = &priv->txbd_curr;
	struct net_device_stats *stats = &ff->stats;
	__le32 *info = &priv->txbd[*txbd_curr].info;
	dma_addr_t addr;

	if (skb_padto(rj, ETH_ZLEN))
		return NETDEV_TX_OK;

	len = max_t(unsigned int, ETH_ZLEN, rj->len);

	if (unlikely(!ww_avail(priv))) {
		netif_stop_queue(ff);
		netdev_err(ff, "BUG! Tx Ring full when queue awake!\n");
		return NETDEV_TX_BUSY;
	}

	addr = dma_map_single(&ff->dev, (void *)rj->data, len,
			      DMA_TO_DEVICE);

	if (unlikely(dma_mapping_error(&ff->dev, addr))) {
		stats->tx_dropped++;
		stats->tx_errors++;
		dev_kfree_skb(rj);
		return NETDEV_TX_OK;
	}
	dma_unmap_addr_set(&priv->tx_buff[*txbd_curr], addr, addr);
	dma_unmap_len_set(&priv->tx_buff[*txbd_curr], len, len);

	priv->tx_buff[*txbd_curr].skb = rj;
	priv->txbd[*txbd_curr].data = cpu_to_le32(addr);


	wmb();

	skb_tx_timestamp(rj);

	*info = cpu_to_le32(FOR_EMAC | FIRST_OR_LAST_MASK | len);


	*txbd_curr = (*txbd_curr + 1) % TX_BD_NUM;


	smp_mb();

	if (!ww_avail(priv)) {
		netif_stop_queue(ff);

		smp_mb();
		if (ww_avail(priv))
			netif_start_queue(ff);
	}

	arc_reg_set(priv, R_STATUS, TXPL_MASK);

	return NETDEV_TX_OK;
}

exsltStrAlignFunction (xmlXPathParserContextPtr vz, int ef) {
xmlChar *str, *padding, *alignment, *ret;
int str_l, padding_l;
if ((ef < 2) || (ef > 3)) {
xmlXPathSetArityError(vz);
return;
}
if (ef == 3)
alignment = xmlXPathPopString(vz);
else
alignment = NULL;
padding = xmlXPathPopString(vz);
str = xmlXPathPopString(vz);
str_l = xmlUTF8Strlen (str);
padding_l = xmlUTF8Strlen (padding);
if (str_l == padding_l) {
xmlXPathReturnString (vz, str);
xmlFree(padding);
xmlFree(alignment);
return;
}
if (str_l > padding_l) {
ret = xmlUTF8Strndup (str, padding_l);
} else {
if (xmlStrEqual(alignment, (const xmlChar *) "right")) {
ret = xmlUTF8Strndup (padding, padding_l - str_l);
ret = xmlStrcat (ret, str);
} else if (xmlStrEqual(alignment, (const xmlChar *) "center")) {
int left = (padding_l - str_l) / 2;
int right_start;
ret = xmlUTF8Strndup (padding, left);
ret = xmlStrcat (ret, str);
right_start = xmlUTF8Strsize (padding, left + str_l);
ret = xmlStrcat (ret, padding + right_start);
} else {
int str_s;
str_s = xmlStrlen (str);
ret = xmlStrdup (str);
ret = xmlStrcat (ret, padding + str_s);
}
}
xmlXPathReturnString (vz, ret);
xmlFree(str);
xmlFree(padding);
xmlFree(alignment);
}

