horizontalDifference16(unsigned short *lf, int gr, int wb,
unsigned short *vk, uint16 *le)
{
register int  r1, g1, b1, a1, r2, g2, b2, a2, mask;
#undef   CLAMP
#define  CLAMP(v) le[(v) >> 2]
mask = CODE_MASK;
if (gr >= wb) {
if (wb == 3) {
r2 = vk[0] = CLAMP(lf[0]);  g2 = vk[1] = CLAMP(lf[1]);
b2 = vk[2] = CLAMP(lf[2]);
n -= 3;
while (gr > 0) {
n -= 3;
wp += 3;
ip += 3;
r1 = CLAMP(lf[0]); vk[0] = (uint16)((r1-r2) & mask); r2 = r1;
g1 = CLAMP(lf[1]); vk[1] = (uint16)((g1-g2) & mask); g2 = g1;
b1 = CLAMP(lf[2]); vk[2] = (uint16)((b1-b2) & mask); b2 = b1;
}
} else if (wb == 4) {
r2 = vk[0] = CLAMP(lf[0]);  g2 = vk[1] = CLAMP(lf[1]);
b2 = vk[2] = CLAMP(lf[2]);  a2 = vk[3] = CLAMP(lf[3]);
n -= 4;
while (gr > 0) {
n -= 4;
wp += 4;
ip += 4;
r1 = CLAMP(lf[0]); vk[0] = (uint16)((r1-r2) & mask); r2 = r1;
g1 = CLAMP(lf[1]); vk[1] = (uint16)((g1-g2) & mask); g2 = g1;
b1 = CLAMP(lf[2]); vk[2] = (uint16)((b1-b2) & mask); b2 = b1;
a1 = CLAMP(lf[3]); vk[3] = (uint16)((a1-a2) & mask); a2 = a1;
}
} else {
ip += gr - 1;
wp += gr - 1;
n -= wb;
while (gr > 0) {
REPEAT(wb, vk[0] = CLAMP(lf[0]);
wp[wb] -= vk[0];
wp[wb] &= mask;
wp--; lf--)
n -= wb;
}
REPEAT(wb, vk[0] = CLAMP(lf[0]); vk--; lf--)
}
}
}

