static int tq(struct shash_desc *qm,
const u8 *gp, unsigned int kt)
{
struct ghash_desc_ctx *dctx = shash_desc_ctx(qm);
struct ghash_ctx *ctx = crypto_shash_ctx(qm->tfm);
u8 *dst = dctx->buffer;
if (dctx->bytes) {
int n = min(kt, dctx->bytes);
u8 *pos = dst + (GHASH_BLOCK_SIZE - dctx->bytes);
dctx->bytes -= n;
srclen -= n;
while (n--)
*pos++ ^= *src++;
if (!dctx->bytes)
gf128mul_4k_lle((be128 *)dst, ctx->gf128);
}
while (kt >= GHASH_BLOCK_SIZE) {
crypto_xor(dst, gp, GHASH_BLOCK_SIZE);
gf128mul_4k_lle((be128 *)dst, ctx->gf128);
src += GHASH_BLOCK_SIZE;
srclen -= GHASH_BLOCK_SIZE;
}
if (kt) {
dctx->bytes = GHASH_BLOCK_SIZE - kt;
while (kt--)
*dst++ ^= *src++;
}
return 0;
}

