long rs(
const Cluster*& iv,
long long& ww,
long& ld)
{
long long total, avail;
long status = m_pReader->Length(&total, &avail);
if (status < 0)
return status;
assert((total < 0) || (avail <= total));
const long long segment_stop = (m_size < 0) ? -1 : m_start + m_size;
long long off_next = 0;
long long cluster_size = -1;
for (;;)
{
if ((total >= 0) && (ww >= total))
return 1;
if ((segment_stop >= 0) && (ww >= segment_stop))
return 1;
if ((ww + 1) > avail)
{
len = 1;
return E_BUFFER_NOT_FULL;
}
long long result = GetUIntLength(m_pReader, ww, ld);
if (result < 0)
return static_cast<long>(result);
if (result > 0)
return E_BUFFER_NOT_FULL;
if ((segment_stop >= 0) && ((ww + ld) > segment_stop))
return E_FILE_FORMAT_INVALID;
if ((ww + ld) > avail)
return E_BUFFER_NOT_FULL;
const long long idpos = ww;
const long long idoff = ww - m_start;
const long long id = ReadUInt(m_pReader, idpos, ld);
if (id < 0)
return static_cast<long>(id);
if (id == 0)
return -1;
pos += ld;
if ((ww + 1) > avail)
{
len = 1;
return E_BUFFER_NOT_FULL;
}
result = GetUIntLength(m_pReader, ww, ld);
if (result < 0)
return static_cast<long>(result);
if (result > 0)
return E_BUFFER_NOT_FULL;
if ((segment_stop >= 0) && ((ww + ld) > segment_stop))
return E_FILE_FORMAT_INVALID;
if ((ww + ld) > avail)
return E_BUFFER_NOT_FULL;
const long long size = ReadUInt(m_pReader, ww, ld);
if (size < 0)
return static_cast<long>(size);
pos += ld;
if (size == 0)
continue;
const long long unknown_size = (1LL << (7 * ld)) - 1;
if ((segment_stop >= 0) &&
(size != unknown_size) &&
((ww + size) > segment_stop))
{
return E_FILE_FORMAT_INVALID;
}
if (id == 0x0C53BB6B)
{
if (size == unknown_size)
return E_FILE_FORMAT_INVALID;
const long long element_stop = ww + size;
if ((segment_stop >= 0) && (element_stop > segment_stop))
return E_FILE_FORMAT_INVALID;
const long long element_start = idpos;
const long long element_size = element_stop - element_start;
if (m_pCues == NULL)
{
m_pCues = new Cues(this,
pos,
size,
element_start,
element_size);
assert(m_pCues);
}
pos += size;
assert((segment_stop < 0) || (ww <= segment_stop));
continue;
}
if (id != 0x0F43B675)
{
if (size == unknown_size)
return E_FILE_FORMAT_INVALID;
pos += size;
assert((segment_stop < 0) || (ww <= segment_stop));
continue;
}
#if 0
len = static_cast<long>(size);
if (element_stop > avail)
return E_BUFFER_NOT_FULL;
#endif
off_next = idoff;
if (size != unknown_size)
cluster_size = size;
break;
}
assert(off_next > 0);
Cluster** const ii = m_clusters + m_clusterCount;
Cluster** i = ii;
Cluster** const jj = ii + m_clusterPreloadCount;
Cluster** j = jj;
while (i < j)
{
Cluster** const k = i + (j - i) / 2;
assert(k < jj);
const Cluster* const pNext = *k;
assert(pNext);
assert(pNext->m_index < 0);
pos = pNext->GetPosition();
assert(ww >= 0);
if (ww < off_next)
i = k + 1;
else if (ww > off_next)
j = k;
else
{
pResult = pNext;
return 0;
}
}
assert(i == j);
long long pos_;
long len_;
status = Cluster::HasBlockEntries(this, off_next, pos_, len_);
if (status < 0)
{
pos = pos_;
len = len_;
return status;
}
if (status > 0)
{
Cluster* const pNext = Cluster::Create(this,
-1,
off_next);
assert(pNext);
const ptrdiff_t idx_next = i - m_clusters;
PreloadCluster(pNext, idx_next);
assert(m_clusters);
assert(idx_next < m_clusterSize);
assert(m_clusters[idx_next] == pNext);
pResult = pNext;
return 0;
}
if (cluster_size < 0)
{
const long long payload_pos = ww;
for (;;)
{
if ((total >= 0) && (ww >= total))
break;
if ((segment_stop >= 0) && (ww >= segment_stop))
break;
if ((ww + 1) > avail)
{
len = 1;
return E_BUFFER_NOT_FULL;
}
long long result = GetUIntLength(m_pReader, ww, ld);
if (result < 0)
return static_cast<long>(result);
if (result > 0)
return E_BUFFER_NOT_FULL;
if ((segment_stop >= 0) && ((ww + ld) > segment_stop))
return E_FILE_FORMAT_INVALID;
if ((ww + ld) > avail)
return E_BUFFER_NOT_FULL;
const long long idpos = ww;
const long long id = ReadUInt(m_pReader, idpos, ld);
if (id < 0)
return static_cast<long>(id);
if (id == 0x0F43B675)
break;
if (id == 0x0C53BB6B)
break;
pos += ld;
if ((ww + 1) > avail)
{
len = 1;
return E_BUFFER_NOT_FULL;
}
result = GetUIntLength(m_pReader, ww, ld);
if (result < 0)
return static_cast<long>(result);
if (result > 0)
return E_BUFFER_NOT_FULL;
if ((segment_stop >= 0) && ((ww + ld) > segment_stop))
return E_FILE_FORMAT_INVALID;
if ((ww + ld) > avail)
return E_BUFFER_NOT_FULL;
const long long size = ReadUInt(m_pReader, ww, ld);
if (size < 0)
return static_cast<long>(size);
pos += ld;
if (size == 0)
continue;
const long long unknown_size = (1LL << (7 * ld)) - 1;
if (size == unknown_size)
return E_FILE_FORMAT_INVALID;
if ((segment_stop >= 0) && ((ww + size) > segment_stop))
return E_FILE_FORMAT_INVALID;
pos += size;
assert((segment_stop < 0) || (ww <= segment_stop));
}
cluster_size = ww - payload_pos;
assert(cluster_size >= 0);
pos = payload_pos;
}
pos += cluster_size;
assert((segment_stop < 0) || (ww <= segment_stop));
return 2;
}

