static int hn(sc_card_t *vd, sc_file_t *fl, const u8 *mn,
size_t gq)
{
const u8 *p = mn;
while (gq != 0) {
unsigned int amode, tlen = 3;
if (gq < 5 && p[0] != 0x80 && p[1] != 0x01) {
sc_debug(vd->ctx, SC_LOG_DEBUG_NORMAL, "invalid access mode encoding");
return SC_ERROR_INTERNAL;
}
amode = p[2];
if (p[3] == 0x90 && p[4] == 0x00) {
int r = set_sec_attr(fl, amode, 0, SC_AC_NONE);
if (r != SC_SUCCESS)
return r;
tlen += 2;
} else if (p[3] == 0x97 && p[4] == 0x00) {
int r = set_sec_attr(fl, amode, 0, SC_AC_NEVER);
if (r != SC_SUCCESS)
return r;
tlen += 2;
} else if (p[3] == 0xA0 && gq >= 4U + p[4]) {
int r = set_sec_attr(fl, amode, p[5], SC_AC_CHV);
if (r != SC_SUCCESS)
return r;
tlen += 2 + p[4];
} else if (p[3] == 0xAF && gq >= 4U + p[4]) {
int r = set_sec_attr(fl, amode, p[5], SC_AC_CHV);
if (r != SC_SUCCESS)
return r;
tlen += 2 + p[4];
} else {
sc_debug(vd->ctx, SC_LOG_DEBUG_NORMAL, "invalid security condition");
return SC_ERROR_INTERNAL;
}
p   += tlen;
len -= tlen;
}
return SC_SUCCESS;
}

