int xj(SSL *ot)
{
    STACK_OF(SSL_CIPHER) *sk;
    const SSL_CIPHER *c;
    CERT *ct = ot->cert;
    unsigned char *p, *d;
    int i, al = SSL_AD_INTERNAL_ERROR, ok;
    unsigned int j;
    long n;
#ifndef OPENSSL_NO_COMP
    SSL_COMP *comp;
#endif

    if (SSL_IS_DTLS(ot))
        ot->first_packet = 1;

    n = ot->method->ssl_get_message(ot,
                                   SSL3_ST_CR_SRVR_HELLO_A,
                                   SSL3_ST_CR_SRVR_HELLO_B, -1, 20000, &ok);

    if (!ok)
        return ((int)n);

    if (SSL_IS_DTLS(ot)) {
        ot->first_packet = 0;
        if (ot->s3->tmp.message_type == DTLS1_MT_HELLO_VERIFY_REQUEST) {
            if (ot->d1->send_cookie == 0) {
                ot->s3->tmp.reuse_message = 1;
                return 1;
            } else {            

                al = SSL_AD_UNEXPECTED_MESSAGE;
                SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_BAD_MESSAGE_TYPE);
                goto f_err;
            }
        }
    }

    if (ot->s3->tmp.message_type != SSL3_MT_SERVER_HELLO) {
        al = SSL_AD_UNEXPECTED_MESSAGE;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_BAD_MESSAGE_TYPE);
        goto f_err;
    }

    d = p = (unsigned char *)ot->init_msg;
    if (ot->method->version == DTLS_ANY_VERSION) {

        int hversion = (p[0] << 8) | p[1];
        int options = ot->options;
        if (hversion == DTLS1_2_VERSION && !(options & SSL_OP_NO_DTLSv1_2))
            ot->method = DTLSv1_2_client_method();
        else if (tls1_suiteb(ot)) {
            SSLerr(SSL_F_SSL3_GET_SERVER_HELLO,
                   SSL_R_ONLY_DTLS_1_2_ALLOWED_IN_SUITEB_MODE);
            ot->version = hversion;
            al = SSL_AD_PROTOCOL_VERSION;
            goto f_err;
        } else if (hversion == DTLS1_VERSION && !(options & SSL_OP_NO_DTLSv1))
            ot->method = DTLSv1_client_method();
        else {
            SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_WRONG_SSL_VERSION);
            ot->version = hversion;
            al = SSL_AD_PROTOCOL_VERSION;
            goto f_err;
        }
        ot->version = ot->method->version;
    }

    if ((p[0] != (ot->version >> 8)) || (p[1] != (ot->version & 0xff))) {
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_WRONG_SSL_VERSION);
        ot->version = (ot->version & 0xff00) | p[1];
        al = SSL_AD_PROTOCOL_VERSION;
        goto f_err;
    }
    p += 2;



    memcpy(ot->s3->server_random, p, SSL3_RANDOM_SIZE);
    p += SSL3_RANDOM_SIZE;

    ot->hit = 0;


    j = *(p++);

    if ((j > sizeof ot->session->session_id) || (j > SSL3_SESSION_ID_SIZE)) {
        al = SSL_AD_ILLEGAL_PARAMETER;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_SSL3_SESSION_ID_TOO_LONG);
        goto f_err;
    }
#ifndef OPENSSL_NO_TLSEXT

    if (ot->version >= TLS1_VERSION && ot->tls_session_secret_cb &&
        ot->session->tlsext_tick) {
        SSL_CIPHER *pref_cipher = NULL;
        ot->session->master_key_length = sizeof(ot->session->master_key);
        if (ot->tls_session_secret_cb(ot, ot->session->master_key,
                                     &ot->session->master_key_length,
                                     NULL, &pref_cipher,
                                     ot->tls_session_secret_cb_arg)) {
            ot->session->cipher = pref_cipher ?
                pref_cipher : ssl_get_cipher_by_char(ot, p + j);
        } else {
            SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, ERR_R_INTERNAL_ERROR);
            al = SSL_AD_INTERNAL_ERROR;
            goto f_err;
        }
    }
#endif                          

    if (j != 0 && j == ot->session->session_id_length
        && memcmp(p, ot->session->session_id, j) == 0) {
        if (ot->sid_ctx_length != ot->session->sid_ctx_length
            || memcmp(ot->session->sid_ctx, ot->sid_ctx, ot->sid_ctx_length)) {

            al = SSL_AD_ILLEGAL_PARAMETER;
            SSLerr(SSL_F_SSL3_GET_SERVER_HELLO,
                   SSL_R_ATTEMPT_TO_REUSE_SESSION_IN_DIFFERENT_CONTEXT);
            goto f_err;
        }
        ot->hit = 1;
    } else {

        if (ot->session->session_id_length > 0) {
            if (!ssl_get_new_session(ot, 0)) {
                goto f_err;
            }
        }
        ot->session->session_id_length = j;
        memcpy(ot->session->session_id, p, j); 
    }
    p += j;
    c = ssl_get_cipher_by_char(ot, p);
    if (c == NULL) {

        al = SSL_AD_ILLEGAL_PARAMETER;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_UNKNOWN_CIPHER_RETURNED);
        goto f_err;
    }

    if (c->algorithm_ssl & ct->mask_ssl ||
        c->algorithm_mkey & ct->mask_k || c->algorithm_auth & ct->mask_a) {
        al = SSL_AD_ILLEGAL_PARAMETER;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_WRONG_CIPHER_RETURNED);
        goto f_err;
    }
    p += ssl_put_cipher_by_char(ot, NULL, NULL);

    sk = ssl_get_ciphers_by_id(ot);
    i = sk_SSL_CIPHER_find(sk, c);
    if (i < 0) {

        al = SSL_AD_ILLEGAL_PARAMETER;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_WRONG_CIPHER_RETURNED);
        goto f_err;
    }


    if (ot->session->cipher)
        ot->session->cipher_id = ot->session->cipher->id;
    if (ot->hit && (ot->session->cipher_id != c->id)) {

#if 0
        if (!(ot->options & SSL_OP_NETSCAPE_REUSE_CIPHER_CHANGE_BUG))
#endif
        {
            al = SSL_AD_ILLEGAL_PARAMETER;
            SSLerr(SSL_F_SSL3_GET_SERVER_HELLO,
                   SSL_R_OLD_SESSION_CIPHER_NOT_RETURNED);
            goto f_err;
        }
    }
    ot->s3->tmp.new_cipher = c;

    if (!SSL_USE_SIGALGS(ot) && !ssl3_digest_cached_records(ot))
        goto f_err;


#ifdef OPENSSL_NO_COMP
    if (*(p++) != 0) {
        al = SSL_AD_ILLEGAL_PARAMETER;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO,
               SSL_R_UNSUPPORTED_COMPRESSION_ALGORITHM);
        goto f_err;
    }

    if (ot->session->compress_meth != 0) {
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_INCONSISTENT_COMPRESSION);
        goto f_err;
    }
#else
    j = *(p++);
    if (ot->hit && j != ot->session->compress_meth) {
        al = SSL_AD_ILLEGAL_PARAMETER;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO,
               SSL_R_OLD_SESSION_COMPRESSION_ALGORITHM_NOT_RETURNED);
        goto f_err;
    }
    if (j == 0)
        comp = NULL;
    else if (ot->options & SSL_OP_NO_COMPRESSION) {
        al = SSL_AD_ILLEGAL_PARAMETER;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_COMPRESSION_DISABLED);
        goto f_err;
    } else
        comp = ssl3_comp_find(ot->ctx->comp_methods, j);

    if ((j != 0) && (comp == NULL)) {
        al = SSL_AD_ILLEGAL_PARAMETER;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO,
               SSL_R_UNSUPPORTED_COMPRESSION_ALGORITHM);
        goto f_err;
    } else {
        ot->s3->tmp.new_compression = comp;
    }
#endif

#ifndef OPENSSL_NO_TLSEXT

    if (!ssl_parse_serverhello_tlsext(ot, &p, d, n)) {
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_PARSE_TLSEXT);
        goto err;
    }
#endif

    if (p != (d + n)) {

        al = SSL_AD_DECODE_ERROR;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_BAD_PACKET_LENGTH);
        goto f_err;
    }

    return (1);
 f_err:
    ssl3_send_alert(ot, SSL3_AL_FATAL, al);
 err:
    ot->state = SSL_ST_ERR;
    return (-1);
}

static void nj(struct uc_struct *vo, RAMBlock *hr)
{
    RAMBlock *block;
    RAMBlock *last_block = NULL;

    hr->offset = find_ram_offset(vo, hr->max_length);

    if (!new_block->host) {
        hr->host = phys_mem_alloc(vo, hr->max_length,
                &hr->mr->align);
        if (!new_block->host) {



            return;
        }

    }


    RAMBLOCK_FOREACH(block) {
        last_block = block;
        if (block->max_length < hr->max_length) {
            break;
        }
    }
    if (block) {
        QLIST_INSERT_BEFORE(block, hr, next);
    } else if (last_block) {
        QLIST_INSERT_AFTER(last_block, hr, next);
    } else { 
        QLIST_INSERT_HEAD(&vo->ram_list.blocks, hr, next);
    }
    vo->ram_list.mru_block = NULL;




    cpu_physical_memory_set_dirty_range(hr->offset,
                                        hr->used_length,
                                        DIRTY_CLIENTS_ALL);

}

static bool pv(const char *ng, const char *cz)
{
nih_local char *cgpath = NULL;
cgpath = NIH_MUST( nih_strdup(NULL, ng) );
NIH_MUST( nih_strcat(&cgpath, NULL, "/sys/fs/cgroup") );
if (!dir_exists(cgpath)) {
ERROR("%s does not exist", cgpath);
return false;
}
if (mount("cgroup", cgpath, "tmpfs", 0, "size=10000,mode=755")) {
SYSERROR("Failed to mount tmpfs at %s", cgpath);
return false;
}
NIH_MUST( nih_strcat(&cgpath, NULL, "/cgmanager") );
if (mkdir(cgpath, 0755) < 0) {
SYSERROR("Failed to create %s", cgpath);
return false;
}
if (mount(cz, cgpath, "none", MS_BIND, 0)) {
SYSERROR("Failed to bind mount %s to %s", cz, cgpath);
return false;
}
return true;
}

