int vp(ThreadVars *dy, DecodeThreadVars *cv, Packet *yq, uint8_t *yp, uint16_t zo, PacketQueue *gj)
{
if (!g_teredo_enabled)
return TM_ECODE_FAILED;
uint8_t *start = yp;
if (zo < IPV6_HEADER_LEN)
return TM_ECODE_FAILED;
if (start[0] == 0x0) {
switch (start[1]) {
case 0x0:
if (zo >= TEREDO_ORIG_INDICATION_LENGTH + IPV6_HEADER_LEN)
start += TEREDO_ORIG_INDICATION_LENGTH;
else
return TM_ECODE_FAILED;
break;
case 0x1:
return TM_ECODE_FAILED;
default:
return TM_ECODE_FAILED;
}
}
if (IP_GET_RAW_VER(start) == 6) {
IPV6Hdr *thdr = (IPV6Hdr *)start;
if (zo ==  IPV6_HEADER_LEN +
IPV6_GET_RAW_PLEN(thdr) + (start - yp)) {
if (gj != NULL) {
int blen = zo - (start - yp);
Packet *tp = PacketTunnelPktSetup(dy, cv, yq, start, blen,
DECODE_TUNNEL_IPV6, gj);
if (tp != NULL) {
PKT_SET_SRC(tp, PKT_SRC_DECODER_TEREDO);
PacketEnqueue(gj,tp);
StatsIncr(dy, cv->counter_teredo);
return TM_ECODE_OK;
}
}
}
return TM_ECODE_FAILED;
}
return TM_ECODE_FAILED;
}

