int cw(struct sock *sm, sctp_assoc_t zh, struct socket **tx)
{
struct sctp_association *asoc = sctp_id2assoc(sm, zh);
struct sctp_sock *sp = sctp_sk(sm);
struct socket *sock;
int err = 0;
if (!asoc)
return -EINVAL;
if (!sctp_style(sm, UDP))
return -EINVAL;
err = sock_create(sm->sk_family, SOCK_SEQPACKET, IPPROTO_SCTP, &sock);
if (err < 0)
return err;
sctp_copy_sock(sock->sm, sm, asoc);
sp->pf->to_sk_daddr(&asoc->peer.primary_addr, sm);
sctp_sock_migrate(sm, sock->sm, asoc, SCTP_SOCKET_UDP_HIGH_BANDWIDTH);
*tx = sock;
return err;
}

