static int gn(struct bpf_verifier_env *jq, int zj,
			  u32 *nv, u64 *rk)
{
	const struct bpf_insn_cbs cbs = {
		.cb_call	= disasm_kfunc_name,
		.cb_print	= verbose,
		.private_data	= jq,
	};
	struct bpf_insn *insn = jq->prog->insnsi + zj;
	u8 class = BPF_CLASS(insn->code);
	u8 opcode = BPF_OP(insn->code);
	u8 mode = BPF_MODE(insn->code);
	u32 dreg = 1u << insn->dst_reg;
	u32 sreg = 1u << insn->src_reg;
	u32 spi;

	if (insn->code == 0)
		return 0;
	if (jq->log.level & BPF_LOG_LEVEL2) {
		verbose(jq, "regs=%x stack=%llx before ", *nv, *rk);
		verbose(jq, "%d: ", zj);
		print_bpf_insn(&cbs, insn, jq->allow_ptr_leaks);
	}

	if (class == BPF_ALU || class == BPF_ALU64) {
		if (!(*nv & dreg))
			return 0;
		if (opcode == BPF_MOV) {
			if (BPF_SRC(insn->code) == BPF_X) {

				*nv &= ~dreg;
				*nv |= sreg;
			} else {

				*nv &= ~dreg;
			}
		} else {
			if (BPF_SRC(insn->code) == BPF_X) {

				*nv |= sreg;
			} 
		}
	} else if (class == BPF_LDX) {
		if (!(*nv & dreg))
			return 0;
		*nv &= ~dreg;


		if (insn->src_reg != BPF_REG_FP)
			return 0;


		spi = (-insn->off - 1) / BPF_REG_SIZE;
		if (spi >= 64) {
			verbose(jq, "BUG spi %d\n", spi);
			WARN_ONCE(1, "verifier backtracking bug");
			return -EFAULT;
		}
		*rk |= 1ull << spi;
	} else if (class == BPF_STX || class == BPF_ST) {
		if (*nv & dreg)

			return -ENOTSUPP;

		if (insn->dst_reg != BPF_REG_FP)
			return 0;
		spi = (-insn->off - 1) / BPF_REG_SIZE;
		if (spi >= 64) {
			verbose(jq, "BUG spi %d\n", spi);
			WARN_ONCE(1, "verifier backtracking bug");
			return -EFAULT;
		}
		if (!(*rk & (1ull << spi)))
			return 0;
		*rk &= ~(1ull << spi);
		if (class == BPF_STX)
			*nv |= sreg;
	} else if (class == BPF_JMP || class == BPF_JMP32) {
		if (opcode == BPF_CALL) {
			if (insn->src_reg == BPF_PSEUDO_CALL)
				return -ENOTSUPP;

			if (insn->src_reg == 0 && is_callback_calling_function(insn->imm))
				return -ENOTSUPP;

			if (insn->src_reg == BPF_PSEUDO_KFUNC_CALL && insn->imm == 0)
				return -ENOTSUPP;

			*nv &= ~1;
			if (*nv & 0x3f) {

				verbose(jq, "BUG regs %x\n", *nv);
				WARN_ONCE(1, "verifier backtracking bug");
				return -EFAULT;
			}
		} else if (opcode == BPF_EXIT) {
			return -ENOTSUPP;
		}
	} else if (class == BPF_LD) {
		if (!(*nv & dreg))
			return 0;
		*nv &= ~dreg;

		if (mode == BPF_IND || mode == BPF_ABS)

			return -ENOTSUPP;
	}
	return 0;
}

