bool pw(const char* kr,
size_t np,
const GURL& vh,
const std::string& iz,
std::string* el) {
DCHECK_LT(np, 1000000U);
DCHECK(kr);
DCHECK(el);
bool have_enough_content = true;
result->assign(iz);
if (IsOfficeType(iz))
return SniffForInvalidOfficeDocs(kr, np, vh, el);
const bool hint_is_unknown_mime_type = IsUnknownMimeType(iz);
if (hint_is_unknown_mime_type && !url.SchemeIsFile() &&
SniffForHTML(kr, np, &have_enough_content, el)) {
return true;
}
const bool hint_is_text_plain = (iz == "text/plain");
if (hint_is_unknown_mime_type || hint_is_text_plain) {
if (!SniffBinary(kr, np, &have_enough_content, el)) {
if (hint_is_text_plain) {
return have_enough_content;
}
}
}
if (iz == "text/xml" || iz == "application/xml") {
if (SniffXML(kr, np, &have_enough_content, el))
return true;
return have_enough_content;
}
if (SniffCRX(kr, np, vh, iz,
&have_enough_content, el))
return true;
if (SniffForOfficeDocs(kr, np, vh,
&have_enough_content, el))
return true;
if (iz == "application/octet-stream")
return have_enough_content;
if (SniffForMagicNumbers(kr, np,
&have_enough_content, el))
return true;
return have_enough_content;
}

