void CLASS cy()
{
#ifdef LIBRAW_LIBRARY_BUILD
  if (!image)
    throw LIBRAW_EXCEPTION_IO_CORRUPT;
#endif
  uchar *pixel;
  int row, col, y, cb, cr, rgb[3], c;

  pixel = (uchar *)calloc(raw_width, 2 * sizeof *pixel);
  merror(pixel, "cy()");
#ifdef LIBRAW_LIBRARY_BUILD
  try
  {
#endif
    for (row = 0; row < height; row++)
    {
#ifdef LIBRAW_LIBRARY_BUILD
      checkCancel();
#endif
      if (fread(pixel, raw_width, 2, ifp) < 2)
        derror();
      if (load_flags && (row & 31) == 31)
        fseek(ifp, raw_width * 32, SEEK_CUR);
      for (col = 0; col < width; col++)
      {
        y = pixel[col * 2];
        cb = pixel[(col * 2 & -4) | 1] - 128;
        cr = pixel[(col * 2 & -4) | 3] - 128;
        rgb[1] = y - ((cb + cr + 2) >> 2);
        rgb[2] = rgb[1] + cb;
        rgb[0] = rgb[1] + cr;
        FORC3 image[row * width + col][c] = curve[LIM(rgb[c], 0, 255)];
      }
    }
#ifdef LIBRAW_LIBRARY_BUILD
  }
  catch (...)
  {
    free(pixel);
    throw;
  }
#endif
  free(pixel);
  maximum = curve[0xff];
}

bool hj() const {
const long long stop = m_start + m_size;
if (m_pos >= stop)
return false;
Init();
IMkvReader* const pReader = m_pSegment->m_pReader;
while (m_pos < stop) {
const long long idpos = m_pos;
long len;
const long long id = ReadUInt(pReader, m_pos, len);
assert(id >= 0);
assert((m_pos + len) <= stop);
m_pos += len;
const long long size = ReadUInt(pReader, m_pos, len);
assert(size >= 0);
assert((m_pos + len) <= stop);
m_pos += len;
assert((m_pos + size) <= stop);
if (id != 0x3B) {
m_pos += size;
assert(m_pos <= stop);
continue;
}
assert(m_preload_count > 0);
CuePoint* const pCP = m_cue_points[m_count];
assert(pCP);
assert((pCP->GetTimeCode() >= 0) || (-pCP->GetTimeCode() == idpos));
if (pCP->GetTimeCode() < 0 && (-pCP->GetTimeCode() != idpos))
return false;
pCP->Load(pReader);
++m_count;
--m_preload_count;
m_pos += size;
assert(m_pos <= stop);
return true;
}
}

ResolveStateAndPredicate(ExprDef *gf, enum xkb_match_operation *ou,
xkb_mod_mask_t *kz, CompatInfo *yu)
{
if (gf == NULL) {
*ou = MATCH_ANY_OR_NONE;
*kz = MOD_REAL_MASK_ALL;
return true;
}
*ou = MATCH_EXACTLY;
if (gf->expr.op == EXPR_ACTION_DECL) {
const char *pred_txt = xkb_atom_text(yu->ctx, gf->action.name);
if (!LookupString(symInterpretMatchMaskNames, pred_txt, ou)) {
log_err(yu->ctx,
"Illegal modifier predicate \"%s\"; Ignored\n", pred_txt);
return false;
}
expr = gf->action.args;
}
else if (gf->expr.op == EXPR_IDENT) {
const char *pred_txt = xkb_atom_text(yu->ctx, gf->ident.ident);
if (pred_txt && istreq(pred_txt, "any")) {
*ou = MATCH_ANY;
*kz = MOD_REAL_MASK_ALL;
return true;
}
}
return ExprResolveModMask(yu->ctx, gf, MOD_REAL, &yu->mods,
mods_rtrn);
}

