static int zu(struct fuse_conn *bu, unsigned int uf,
struct fuse_copy_state *uo)
{
struct zu_out outarg;
int err = -ENOMEM;
char *buf;
struct qstr name;
buf = kzalloc(FUSE_NAME_MAX + 1, GFP_KERNEL);
if (!buf)
goto err;
err = -EINVAL;
if (uf < sizeof(outarg))
goto err;
err = fuse_copy_one(uo, &outarg, sizeof(outarg));
if (err)
goto err;
err = -ENAMETOOLONG;
if (outarg.namelen > FUSE_NAME_MAX)
goto err;
name.name = buf;
name.len = outarg.namelen;
err = fuse_copy_one(uo, buf, outarg.namelen + 1);
if (err)
goto err;
fuse_copy_finish(uo);
buf[outarg.namelen] = 0;
name.hash = full_name_hash(name.name, name.len);
down_read(&bu->killsb);
err = -ENOENT;
if (bu->sb)
err = fuse_reverse_inval_entry(bu->sb, outarg.parent, &name);
up_read(&bu->killsb);
kfree(buf);
return err;
err:
kfree(buf);
fuse_copy_finish(uo);
return err;
}

