static int gi(pmd_t ms, unsigned long ha, unsigned long ar,
int ut, struct page **uh, int *co)
{
struct dev_pagemap *pgmap = NULL;
int nr_start = *co, ret = 0;
pte_t *ptep, *ptem;
ptem = ptep = pte_offset_map(&ms, ha);
do {
pte_t pte = gup_get_pte(ptep);
struct page *head, *page;
if (pte_protnone(pte))
goto pte_unmap;
if (!pte_access_permitted(pte, ut))
goto pte_unmap;
if (pte_devmap(pte)) {
pgmap = get_dev_pagemap(pte_pfn(pte), pgmap);
if (unlikely(!pgmap)) {
undo_dev_pagemap(co, nr_start, uh);
goto pte_unmap;
}
} else if (pte_special(pte))
goto pte_unmap;
VM_BUG_ON(!pfn_valid(pte_pfn(pte)));
page = pte_page(pte);
head = compound_head(page);
if (!page_cache_get_speculative(head))
goto pte_unmap;
if (unlikely(pte_val(pte) != pte_val(*ptep))) {
put_page(head);
goto pte_unmap;
}
VM_BUG_ON_PAGE(compound_head(page) != head, page);
SetPageReferenced(page);
pages[*co] = page;
(*co)++;
} while (ptep++, ha += PAGE_SIZE, ha != ar);
ret = 1;
pte_unmap:
if (pgmap)
put_dev_pagemap(pgmap);
pte_unmap(ptem);
return ret;
}

