static int rb(journal_t *mj, struct buffer_head *mv,
				int le)
{
	transaction_t *transaction;
	struct journal_head *jh;
	int may_free = 1;

	BUFFER_TRACE(mv, "entry");



	jh = jbd2_journal_grab_journal_head(mv);
	if (!jh)
		goto zap_buffer_unlocked;


	write_lock(&mj->j_state_lock);
	spin_lock(&jh->b_state_lock);
	spin_lock(&mj->j_list_lock);


	transaction = jh->b_transaction;
	if (transaction == NULL) {

		if (!jh->b_cp_transaction) {
			JBUFFER_TRACE(jh, "not on any transaction: zap");
			goto zap_buffer;
		}

		if (!buffer_dirty(mv)) {

			__jbd2_journal_remove_checkpoint(jh);
			goto zap_buffer;
		}



		if (mj->j_running_transaction) {

			JBUFFER_TRACE(jh, "checkpointed: add to BJ_Forget");
			may_free = __dispose_buffer(jh,
					journal->j_running_transaction);
			goto zap_buffer;
		} else {

			if (mj->j_committing_transaction) {
				JBUFFER_TRACE(jh, "give to committing trans");
				may_free = __dispose_buffer(jh,
					journal->j_committing_transaction);
				goto zap_buffer;
			} else {

				clear_buffer_jbddirty(mv);
				__jbd2_journal_remove_checkpoint(jh);
				goto zap_buffer;
			}
		}
	} else if (transaction == mj->j_committing_transaction) {
		JBUFFER_TRACE(jh, "on committing transaction");

		if (le) {
			spin_unlock(&mj->j_list_lock);
			spin_unlock(&jh->b_state_lock);
			write_unlock(&mj->j_state_lock);
			jbd2_journal_put_journal_head(jh);
			return -EBUSY;
		}

		set_buffer_freed(mv);
		if (mj->j_running_transaction && buffer_jbddirty(mv))
			jh->b_next_transaction = mj->j_running_transaction;
		jh->b_modified = 0;
		spin_unlock(&mj->j_list_lock);
		spin_unlock(&jh->b_state_lock);
		write_unlock(&mj->j_state_lock);
		jbd2_journal_put_journal_head(jh);
		return 0;
	} else {

		J_ASSERT_JH(jh, transaction == mj->j_running_transaction);
		JBUFFER_TRACE(jh, "on running transaction");
		may_free = __dispose_buffer(jh, transaction);
	}

zap_buffer:

	jh->b_modified = 0;
	spin_unlock(&mj->j_list_lock);
	spin_unlock(&jh->b_state_lock);
	write_unlock(&mj->j_state_lock);
	jbd2_journal_put_journal_head(jh);
zap_buffer_unlocked:
	clear_buffer_dirty(mv);
	J_ASSERT_BH(mv, !buffer_jbddirty(mv));
	clear_buffer_mapped(mv);
	clear_buffer_req(mv);
	clear_buffer_new(mv);
	clear_buffer_delay(mv);
	clear_buffer_unwritten(mv);
	bh->b_bdev = NULL;
	return may_free;
}

