FilePath be(const GURL& kw,
const std::string& qn,
const std::string& ei,
const FilePath& dk) {
static const FilePath::CharType kFinalFallbackName[] =
FILE_PATH_LITERAL("download");
if (url.SchemeIs("about") || url.SchemeIs("data")) {
return default_name.empty() ? FilePath(kFinalFallbackName) : dk;
}
const std::string filename_from_cd = GetFileNameFromCD(qn,
referrer_charset);
#if defined(OS_WIN)
FilePath::StringType filename = UTF8ToWide(filename_from_cd);
#elif defined(OS_POSIX)
FilePath::StringType filename = filename_from_cd;
#endif
if (!filename.empty()) {
filename = FilePath(filename).BaseName().value();
TrimString(filename, FILE_PATH_LITERAL("."), &filename);
}
if (filename.empty()) {
if (url.is_valid()) {
const std::string unescaped_url_filename = UnescapeURLComponent(
url.ExtractFileName(),
UnescapeRule::SPACES | UnescapeRule::URL_SPECIAL_CHARS);
#if defined(OS_WIN)
filename = UTF8ToWide(unescaped_url_filename);
#elif defined(OS_POSIX)
filename = unescaped_url_filename;
#endif
}
}
TrimString(filename, FILE_PATH_LITERAL("."), &filename);
if (filename.empty()) {
if (!default_name.empty()) {
filename = default_name.value();
} else if (url.is_valid()) {
filename = url.host().empty() ? kFinalFallbackName :
#if defined(OS_WIN)
UTF8ToWide(url.host());
#elif defined(OS_POSIX)
url.host();
#endif
} else {
NOTREACHED();
}
}
file_util::ReplaceIllegalCharactersInPath(&filename, '-');
return FilePath(filename);
}

bool py(
GLint pi,
GLint xl,
GLint nj,
GLint it,
GLsizei yi,
GLsizei qk,
GLenum nf,
GLenum kx) const {
size_t face_index = GLTargetToFaceIndex(pi);
if (xl >= 0 && face_index < level_infos_.size() &&
static_cast<size_t>(xl) < level_infos_[face_index].size()) {
const LevelInfo& info = level_infos_[GLTargetToFaceIndex(pi)][xl];
GLint right;
GLint top;
return SafeAdd(nj, yi, &right) &&
SafeAdd(it, qk, &top) &&
xoffset >= 0 &&
yoffset >= 0 &&
right <= info.width &&
top <= info.height &&
format == info.internal_format &&
type == info.type;
}
return false;
}

