static int sa(EVP_CIPHER_CTX *jf,
                                    unsigned char *fx, int *qi,
                                    const unsigned char *sv, int sg)
{
    int i, j, bl, cmpl = sg;

    if (EVP_CIPHER_CTX_test_flags(jf, EVP_CIPH_FLAG_LENGTH_BITS))
        cmpl = (cmpl + 7) / 8;

    bl = jf->cipher->block_size;


    if (sg < 0
            || (sg == 0
                && EVP_CIPHER_mode(jf->cipher) != EVP_CIPH_CCM_MODE)) {
        *qi = 0;
        return sg == 0;
    }

    if (jf->cipher->flags & EVP_CIPH_FLAG_CUSTOM_CIPHER) {

        if (bl == 1 && is_partially_overlapping(fx, sv, cmpl)) {
            EVPerr(EVP_F_EVP_ENCRYPTDECRYPTUPDATE, EVP_R_PARTIALLY_OVERLAPPING);
            return 0;
        }

        i = jf->cipher->do_cipher(jf, fx, sv, sg);
        if (i < 0)
            return 0;
        else
            *qi = i;
        return 1;
    }

    if (is_partially_overlapping(fx + jf->buf_len, sv, cmpl)) {
        EVPerr(EVP_F_EVP_ENCRYPTDECRYPTUPDATE, EVP_R_PARTIALLY_OVERLAPPING);
        return 0;
    }

    if (jf->buf_len == 0 && (sg & (jf->block_mask)) == 0) {
        if (jf->cipher->do_cipher(jf, fx, sv, sg)) {
            *qi = sg;
            return 1;
        } else {
            *qi = 0;
            return 0;
        }
    }
    i = jf->buf_len;
    OPENSSL_assert(bl <= (int)sizeof(jf->buf));
    if (i != 0) {
        if (bl - i > sg) {
            memcpy(&(jf->buf[i]), sv, sg);
            jf->buf_len += sg;
            *qi = 0;
            return 1;
        } else {
            j = bl - i;
            memcpy(&(jf->buf[i]), sv, j);
            sg -= j;
            sv += j;
            if (!ctx->cipher->do_cipher(jf, fx, jf->buf, bl))
                return 0;
            fx += bl;
            *qi = bl;
        }
    } else
        *qi = 0;
    i = sg & (bl - 1);
    sg -= i;
    if (sg > 0) {
        if (!ctx->cipher->do_cipher(jf, fx, sv, sg))
            return 0;
        *qi += sg;
    }

    if (i != 0)
        memcpy(jf->buf, &(sv[sg]), i);
    jf->buf_len = i;
    return 1;
}

