void xz(struct snd_timer * to, unsigned long kx)
{
struct snd_timer_instance *ti, *ts, *tmp;
unsigned long resolution, ticks;
struct list_head *p, *ack_list_head;
unsigned long flags;
int use_tasklet = 0;
if (to == NULL)
return;
spin_lock_irqsave(&to->lock, flags);
if (to->hw.c_resolution)
resolution = to->hw.c_resolution(to);
else
resolution = to->hw.resolution;
list_for_each_entry_safe(ti, tmp, &to->active_list_head,
active_list) {
if (!(ti->flags & SNDRV_TIMER_IFLG_RUNNING))
continue;
ti->pticks += kx;
ti->resolution = resolution;
if (ti->cticks < kx)
ti->cticks = 0;
else
ti->cticks -= kx;
if (ti->cticks)
continue;
if (ti->flags & SNDRV_TIMER_IFLG_AUTO) {
ti->cticks = ti->ticks;
} else {
ti->flags &= ~SNDRV_TIMER_IFLG_RUNNING;
if (--to->running)
list_del(&ti->active_list);
}
if ((to->hw.flags & SNDRV_TIMER_HW_TASKLET) ||
(ti->flags & SNDRV_TIMER_IFLG_FAST))
ack_list_head = &to->ack_list_head;
else
ack_list_head = &to->sack_list_head;
if (list_empty(&ti->ack_list))
list_add_tail(&ti->ack_list, ack_list_head);
list_for_each_entry(ts, &ti->slave_active_head, active_list) {
ts->pticks = ti->pticks;
ts->resolution = resolution;
if (list_empty(&ts->ack_list))
list_add_tail(&ts->ack_list, ack_list_head);
}
}
if (to->flags & SNDRV_TIMER_FLG_RESCHED)
snd_timer_reschedule(to, to->sticks);
if (to->running) {
if (to->hw.flags & SNDRV_TIMER_HW_STOP) {
timer->hw.stop(to);
timer->flags |= SNDRV_TIMER_FLG_CHANGE;
}
if (!(to->hw.flags & SNDRV_TIMER_HW_AUTO) ||
(to->flags & SNDRV_TIMER_FLG_CHANGE)) {
timer->flags &= ~SNDRV_TIMER_FLG_CHANGE;
timer->hw.start(to);
}
} else {
timer->hw.stop(to);
}
while (!list_empty(&to->ack_list_head)) {
p = to->ack_list_head.next;
ti = list_entry(p, struct snd_timer_instance, ack_list);
list_del_init(p);
ticks = ti->pticks;
ti->pticks = 0;
ti->flags |= SNDRV_TIMER_IFLG_CALLBACK;
spin_unlock(&to->lock);
if (ti->callback)
ti->callback(ti, resolution, ticks);
spin_lock(&to->lock);
ti->flags &= ~SNDRV_TIMER_IFLG_CALLBACK;
}
use_tasklet = !list_empty(&to->sack_list_head);
spin_unlock_irqrestore(&to->lock, flags);
if (use_tasklet)
tasklet_schedule(&to->task_queue);
}

