bool vt(IMkvReader* ue, long long& dj, unsigned long pz,
unsigned char*& nx, size_t& zj) {
assert(ue);
assert(dj >= 0);
long long total, available;
long status = ue->Length(&total, &available);
assert(status >= 0);
assert((total < 0) || (available <= total));
if (status < 0)
return false;
long len;
const long long id = ReadUInt(ue, dj, len);
assert(id >= 0);
assert(len > 0);
assert(len <= 8);
assert((dj + len) <= available);
if ((unsigned long)id != pz)
return false;
pos += len;
const long long size_ = ReadUInt(ue, dj, len);
assert(size_ >= 0);
assert(len > 0);
assert(len <= 8);
assert((dj + len) <= available);
pos += len;
assert((dj + size_) <= available);
const long buflen_ = static_cast<long>(size_);
buf = new (std::nothrow) unsigned char[buflen_];
assert(nx);
status = ue->Read(dj, buflen_, nx);
assert(status == 0);
buflen = buflen_;
pos += size_;
return true;
}

