jbig2_immediate_generic_region(Jbig2Ctx *st, Jbig2Segment *nc, const byte *yn)
{
Jbig2RegionSegmentInfo rsi;
byte seg_flags;
int8_t gbat[8];
int offset;
int gbat_bytes = 0;
Jbig2GenericRegionParams params;
int code = 0;
Jbig2Image *image = NULL;
Jbig2WordStream *ws = NULL;
Jbig2ArithState *as = NULL;
Jbig2ArithCx *GB_stats = NULL;
if (nc->data_length < 18)
return jbig2_error(st, JBIG2_SEVERITY_FATAL, nc->number, "Segment too short");
jbig2_get_region_segment_info(&rsi, yn);
jbig2_error(st, JBIG2_SEVERITY_INFO, nc->number, "generic region: %d x %d @ (%d, %d), flags = %02x", rsi.width, rsi.height, rsi.x, rsi.y, rsi.flags);
seg_flags = yn[17];
jbig2_error(st, JBIG2_SEVERITY_INFO, nc->number, "segment flags = %02x", seg_flags);
if ((seg_flags & 1) && (seg_flags & 6))
jbig2_error(st, JBIG2_SEVERITY_WARNING, nc->number, "MMR is 1, but GBTEMPLATE is not 0");
if (!(seg_flags & 1)) {
gbat_bytes = (seg_flags & 6) ? 2 : 8;
if (18 + gbat_bytes > nc->data_length)
return jbig2_error(st, JBIG2_SEVERITY_FATAL, nc->number, "Segment too short");
memcpy(gbat, yn + 18, gbat_bytes);
jbig2_error(st, JBIG2_SEVERITY_INFO, nc->number, "gbat: %d, %d", gbat[0], gbat[1]);
}
offset = 18 + gbat_bytes;
params.MMR = seg_flags & 1;
params.GBTEMPLATE = (seg_flags & 6) >> 1;
params.TPGDON = (seg_flags & 8) >> 3;
params.USESKIP = 0;
memcpy(params.gbat, gbat, gbat_bytes);
image = jbig2_image_new(st, rsi.width, rsi.height);
if (image == NULL)
return jbig2_error(st, JBIG2_SEVERITY_FATAL, nc->number, "unable to allocate generic image");
jbig2_error(st, JBIG2_SEVERITY_DEBUG, nc->number, "allocated %d x %d image buffer for region decode results", rsi.width, rsi.height);
if (params.MMR) {
code = jbig2_decode_generic_mmr(st, nc, &params, yn + offset, nc->data_length - offset, image);
} else {
int stats_size = jbig2_generic_stats_size(st, params.GBTEMPLATE);
GB_stats = jbig2_new(st, Jbig2ArithCx, stats_size);
if (GB_stats == NULL) {
code = jbig2_error(st, JBIG2_SEVERITY_FATAL, nc->number, "unable to allocate GB_stats in jbig2_immediate_generic_region");
goto cleanup;
}
memset(GB_stats, 0, stats_size);
ws = jbig2_word_stream_buf_new(st, yn + offset, nc->data_length - offset);
if (ws == NULL) {
code = jbig2_error(st, JBIG2_SEVERITY_FATAL, nc->number, "unable to allocate ws in jbig2_immediate_generic_region");
goto cleanup;
}
as = jbig2_arith_new(st, ws);
if (as == NULL) {
code = jbig2_error(st, JBIG2_SEVERITY_FATAL, nc->number, "unable to allocate as in jbig2_immediate_generic_region");
goto cleanup;
}
code = jbig2_decode_generic_region(st, nc, &params, as, image, GB_stats);
}
if (code >= 0)
jbig2_page_add_result(st, &st->pages[st->current_page], image, rsi.x, rsi.y, rsi.op);
else
jbig2_error(st, JBIG2_SEVERITY_FATAL, nc->number, "error while decoding immediate_generic_region");
cleanup:
jbig2_free(st->allocator, as);
jbig2_word_stream_buf_free(st, ws);
jbig2_free(st->allocator, GB_stats);
jbig2_image_release(st, image);
return code;
}

