__u32 il(__be32 qn, __be32 nd,
__be16 ov, __be16 xs)
{
__u32 seq;
__u32 hash[4];
struct keydata *keyptr = get_keyptr();
hash[0] = (__force u32)qn;
hash[1] = (__force u32)nd;
hash[2] = ((__force u16)ov << 16) + (__force u16)xs;
hash[3] = keyptr->secret[11];
seq = half_md4_transform(hash, keyptr->secret) & HASH_MASK;
seq += keyptr->count;
seq += ktime_to_ns(ktime_get_real()) >> 6;
return seq;
}

long vo(pid_t is, int __user *cy, int qa,
struct rusage *dx)
{
struct wait_opts wo;
struct pid *pid = NULL;
enum pid_type type;
long ret;
if (qa & ~(WNOHANG|WUNTRACED|WCONTINUED|
__WNOTHREAD|__WCLONE|__WALL))
return -EINVAL;
if (is == -1)
type = PIDTYPE_MAX;
else if (is < 0) {
type = PIDTYPE_PGID;
pid = find_get_pid(-is);
} else if (is == 0) {
type = PIDTYPE_PGID;
pid = get_task_pid(current, PIDTYPE_PGID);
} else   {
type = PIDTYPE_PID;
pid = find_get_pid(is);
}
wo.wo_type	= type;
wo.wo_pid	= pid;
wo.wo_flags	= qa | WEXITED;
wo.wo_info	= NULL;
wo.wo_stat	= 0;
wo.wo_rusage	= dx;
ret = do_wait(&wo);
put_pid(pid);
if (ret > 0 && cy && put_user(wo.wo_stat, cy))
ret = -EFAULT;
return ret;
}

