int ul(MemoryPoolHandle *de) {
  struct mempool *pool = NULL;
  struct memory_pool_element *pool_item;
  char *log_msg_fmt = "mempool(%p): free(%p) called for buffer size(%zu)";
  char log_msg[200];

  if (de == NULL) {
    return S3_MEMPOOL_INVALID_ARG;
  }

  pool = (struct mempool *)*de;
  if (pool == NULL) {
    return S3_MEMPOOL_INVALID_ARG;
  }

  if ((pool->flags & ENABLE_LOCKING) != 0) {
    pthread_mutex_lock(&pool->lock);
  }

  if (*de == NULL) {
    if ((pool->flags & ENABLE_LOCKING) != 0) {
      pthread_mutex_unlock(&pool->lock);
    }
    return S3_MEMPOOL_INVALID_ARG;
  }


  *de = NULL;

  pool_item = pool->free_list;
  while (pool_item != NULL) {
    pool->free_list = pool_item->next;

    if (pool->log_callback_func) {
      snprintf(log_msg, sizeof(log_msg), log_msg_fmt, (void *)pool,
               (void *)pool_item, pool->mempool_item_size);
      pool->log_callback_func(MEMPOOL_LOG_DEBUG, log_msg);
    }
    free(pool_item);
#if 0

    pool->total_bufs_allocated_by_pool--;
    pool->free_bufs_in_pool--;
#endif
    pool_item = pool->free_list;
  }
  pool->free_list = NULL;





  if ((pool->flags & ENABLE_LOCKING) != 0) {
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
  }

  free(pool);
  pool = NULL;
  return 0;
}

flushline(struct html_feed_environ *ke, struct readbuffer *dg, int on,
	  int yy, int ah)
{
    TextLineList *buf = ke->buf;
    FILE *f = ke->f;
    Str line = dg->line, pass = NULL;
    char *hidden_anchor = NULL, *hidden_img = NULL, *hidden_bold = NULL,
	*hidden_under = NULL, *hidden_italic = NULL, *hidden_strike = NULL,
	*hidden_ins = NULL, *hidden_input = NULL, *hidden = NULL;

#ifdef DEBUG
    if (w3m_debug) {
	FILE *df = fopen("zzzproc1", "a");
	fprintf(df, "flushline(%s,%d,%d,%d)\n", dg->line->ptr, on, yy,
		width);
	if (buf) {
	    TextLineListItem *p;
	    for (p = buf->first; p; p = p->next) {
		fprintf(df, "buf=\"%s\"\n", p->ptr->line->ptr);
	    }
	}
	fclose(df);
    }
#endif

    if (!(dg->flag & (RB_SPECIAL & ~RB_NOBR)) && Strlastchar(line) == ' ') {
	Strshrink(line, 1);
	obuf->pos--;
    }

    append_tags(dg);

    if (dg->anchor.url)
	hidden = hidden_anchor = has_hidden_link(dg, HTML_A);
    if (dg->img_alt) {
	if ((hidden_img = has_hidden_link(dg, HTML_IMG_ALT)) != NULL) {
	    if (!hidden || hidden_img < hidden)
		hidden = hidden_img;
	}
    }
    if (dg->input_alt.in) {
	if ((hidden_input = has_hidden_link(dg, HTML_INPUT_ALT)) != NULL) {
	    if (!hidden || hidden_input < hidden)
		hidden = hidden_input;
	}
    }
    if (dg->in_bold) {
	if ((hidden_bold = has_hidden_link(dg, HTML_B)) != NULL) {
	    if (!hidden || hidden_bold < hidden)
		hidden = hidden_bold;
	}
    }
    if (dg->in_italic) {
	if ((hidden_italic = has_hidden_link(dg, HTML_I)) != NULL) {
	    if (!hidden || hidden_italic < hidden)
		hidden = hidden_italic;
	}
    }
    if (dg->in_under) {
	if ((hidden_under = has_hidden_link(dg, HTML_U)) != NULL) {
	    if (!hidden || hidden_under < hidden)
		hidden = hidden_under;
	}
    }
    if (dg->in_strike) {
	if ((hidden_strike = has_hidden_link(dg, HTML_S)) != NULL) {
	    if (!hidden || hidden_strike < hidden)
		hidden = hidden_strike;
	}
    }
    if (dg->in_ins) {
	if ((hidden_ins = has_hidden_link(dg, HTML_INS)) != NULL) {
	    if (!hidden || hidden_ins < hidden)
		hidden = hidden_ins;
	}
    }
    if (hidden) {
	pass = Strnew_charp(hidden);
	Strshrink(line, line->ptr + line->length - hidden);
    }

    if (!(dg->flag & (RB_SPECIAL & ~RB_NOBR)) && dg->pos > ah) {
	char *tp = &line->ptr[dg->bp.len - dg->bp.tlen];
	char *ep = &line->ptr[line->length];

	if (dg->bp.pos == dg->pos && tp <= ep &&
	    tp > line->ptr && tp[-1] == ' ') {
	    bcopy(tp, tp - 1, ep - tp + 1);
	    line->length--;
	    dg->pos--;
	}
    }

    if (dg->anchor.url && !hidden_anchor)
	Strcat_charp(line, "</a>");
    if (dg->img_alt && !hidden_img)
	Strcat_charp(line, "</img_alt>");
    if (dg->input_alt.in && !hidden_input)
	Strcat_charp(line, "</input_alt>");
    if (dg->in_bold && !hidden_bold)
	Strcat_charp(line, "</b>");
    if (dg->in_italic && !hidden_italic)
	Strcat_charp(line, "</i>");
    if (dg->in_under && !hidden_under)
	Strcat_charp(line, "</u>");
    if (dg->in_strike && !hidden_strike)
	Strcat_charp(line, "</s>");
    if (dg->in_ins && !hidden_ins)
	Strcat_charp(line, "</ins>");

    if (dg->top_margin > 0) {
	int i;
	struct html_feed_environ h;
	struct readbuffer o;
	struct environment e[1];

	init_henv(&h, &o, e, 1, NULL, ah, on);
	o.line = Strnew_size(ah + 20);
	o.pos = dg->pos;
	o.flag = dg->flag;
	o.top_margin = -1;
	o.bottom_margin = -1;
	Strcat_charp(o.line, "<pre_int>");
	for (i = 0; i < o.pos; i++)
	    Strcat_char(o.line, ' ');
	Strcat_charp(o.line, "</pre_int>");
	for (i = 0; i < dg->top_margin; i++)
	    flushline(ke, &o, on, yy, ah);
    }

    if (yy == 1 || dg->flag & RB_NFLUSHED) {
	TextLine *lbuf = newTextLine(line, dg->pos);
	if (RB_GET_ALIGN(dg) == RB_CENTER) {
	    align(lbuf, ah, ALIGN_CENTER);
	}
	else if (RB_GET_ALIGN(dg) == RB_RIGHT) {
	    align(lbuf, ah, ALIGN_RIGHT);
	}
	else if (RB_GET_ALIGN(dg) == RB_LEFT && dg->flag & RB_INTABLE) {
	    align(lbuf, ah, ALIGN_LEFT);
	}
#ifdef FORMAT_NICE
	else if (dg->flag & RB_FILL) {
	    char *p;
	    int rest, rrest;
	    int nspace, d, i;

	    rest = ah - get_Str_strwidth(line);
	    if (rest > 1) {
		nspace = 0;
		for (p = line->ptr + on; *p; p++) {
		    if (*p == ' ')
			nspace++;
		}
		if (nspace > 0) {
		    int indent_here = 0;
		    d = rest / nspace;
		    p = line->ptr;
		    while (IS_SPACE(*p)) {
			p++;
			indent_here++;
		    }
		    rrest = rest - d * nspace;
		    line = Strnew_size(ah + 1);
		    for (i = 0; i < indent_here; i++)
			Strcat_char(line, ' ');
		    for (; *p; p++) {
			Strcat_char(line, *p);
			if (*p == ' ') {
			    for (i = 0; i < d; i++)
				Strcat_char(line, ' ');
			    if (rrest > 0) {
				Strcat_char(line, ' ');
				rrest--;
			    }
			}
		    }
		    lbuf = newTextLine(line, ah);
		}
	    }
	}
#endif				
#ifdef TABLE_DEBUG
	if (w3m_debug) {
	    FILE *f = fopen("zzzproc1", "a");
	    fprintf(f, "pos=%d,%d, maxlimit=%d\n",
		    visible_length(lbuf->line->ptr), lbuf->pos,
		    ke->maxlimit);
	    fclose(f);
	}
#endif
	if (lbuf->pos > ke->maxlimit)
	    ke->maxlimit = lbuf->pos;
	if (buf)
	    pushTextLine(buf, lbuf);
	else if (f) {
	    Strfputs(Str_conv_to_halfdump(lbuf->line), f);
	    fputc('\n', f);
	}
	if (dg->flag & RB_SPECIAL || dg->flag & RB_NFLUSHED)
	    ke->blank_lines = 0;
	else
	    ke->blank_lines++;
    }
    else {
	char *p = line->ptr, *q;
	Str tmp = Strnew(), tmp2 = Strnew();

#define APPEND(str) \
	if (buf) \
	    appendTextLine(buf,(str),0); \
	else if (f) \
	    Strfputs((str),f)

	while (*p) {
	    q = p;
	    if (sloppy_parse_line(&p)) {
		Strcat_charp_n(tmp, q, p - q);
		if (yy == 2) {
		    APPEND(tmp);
		}
		else
		    Strcat(tmp2, tmp);
		Strclear(tmp);
	    }
	}
	if (yy == 2) {
	    if (pass) {
		APPEND(pass);
	    }
	    pass = NULL;
	}
	else {
	    if (pass)
		Strcat(tmp2, pass);
	    pass = tmp2;
	}
    }

    if (dg->bottom_margin > 0) {
	int i;
	struct html_feed_environ h;
	struct readbuffer o;
	struct environment e[1];

	init_henv(&h, &o, e, 1, NULL, ah, on);
	o.line = Strnew_size(ah + 20);
	o.pos = dg->pos;
	o.flag = dg->flag;
	o.top_margin = -1;
	o.bottom_margin = -1;
	Strcat_charp(o.line, "<pre_int>");
	for (i = 0; i < o.pos; i++)
	    Strcat_char(o.line, ' ');
	Strcat_charp(o.line, "</pre_int>");
	for (i = 0; i < dg->bottom_margin; i++)
	    flushline(ke, &o, on, yy, ah);
    }
    if (dg->top_margin < 0 || dg->bottom_margin < 0)
	return;

    dg->line = Strnew_size(256);
    dg->pos = 0;
    dg->top_margin = 0;
    dg->bottom_margin = 0;
    set_space_to_prevchar(dg->prevchar);
    dg->bp.init_flag = 1;
    dg->flag &= ~RB_NFLUSHED;
    set_breakpoint(dg, 0);
    dg->prev_ctype = PC_ASCII;
    link_stack = NULL;
    fillline(dg, on);
    if (pass)
	passthrough(dg, pass->ptr, 0);
    if (!hidden_anchor && dg->anchor.url) {
	Str tmp;
	if (dg->anchor.hseq > 0)
	    dg->anchor.hseq = -dg->anchor.hseq;
	tmp = Sprintf("<A HSEQ=\"%d\" HREF=\"", dg->anchor.hseq);
	Strcat_charp(tmp, html_quote(dg->anchor.url));
	if (dg->anchor.target) {
	    Strcat_charp(tmp, "\" TARGET=\"");
	    Strcat_charp(tmp, html_quote(dg->anchor.target));
	}
	if (dg->anchor.referer) {
	    Strcat_charp(tmp, "\" REFERER=\"");
	    Strcat_charp(tmp, html_quote(dg->anchor.referer));
	}
	if (dg->anchor.title) {
	    Strcat_charp(tmp, "\" TITLE=\"");
	    Strcat_charp(tmp, html_quote(dg->anchor.title));
	}
	if (dg->anchor.accesskey) {
	    char *c = html_quote_char(dg->anchor.accesskey);
	    Strcat_charp(tmp, "\" ACCESSKEY=\"");
	    if (c)
		Strcat_charp(tmp, c);
	    else
		Strcat_char(tmp, dg->anchor.accesskey);
	}
	Strcat_charp(tmp, "\">");
	push_tag(dg, tmp->ptr, HTML_A);
    }
    if (!hidden_img && dg->img_alt) {
	Str tmp = Strnew_charp("<IMG_ALT SRC=\"");
	Strcat_charp(tmp, html_quote(dg->img_alt->ptr));
	Strcat_charp(tmp, "\">");
	push_tag(dg, tmp->ptr, HTML_IMG_ALT);
    }
    if (!hidden_input && dg->input_alt.in) {
	Str tmp;
	if (dg->input_alt.hseq > 0)
	    dg->input_alt.hseq = - dg->input_alt.hseq;
	tmp = Sprintf("<INPUT_ALT hseq=\"%d\" fid=\"%d\" name=\"%s\" type=\"%s\" value=\"%s\">",
		     dg->input_alt.hseq,
		     dg->input_alt.fid,
		     dg->input_alt.name->ptr,
		     dg->input_alt.type->ptr,
		     dg->input_alt.value->ptr);
	push_tag(dg, tmp->ptr, HTML_INPUT_ALT);
    }
    if (!hidden_bold && dg->in_bold)
	push_tag(dg, "<B>", HTML_B);
    if (!hidden_italic && dg->in_italic)
	push_tag(dg, "<I>", HTML_I);
    if (!hidden_under && dg->in_under)
	push_tag(dg, "<U>", HTML_U);
    if (!hidden_strike && dg->in_strike)
	push_tag(dg, "<S>", HTML_S);
    if (!hidden_ins && dg->in_ins)
	push_tag(dg, "<INS>", HTML_INS);
}

