NOEXPORT char kl(CLI *vw, SERVICE_OPTIONS *rj, const PHASE xx) {
    uint8_t buffer[128];
    uint8_t response_access_denied[5] = {0x83, 0, 0, 1, 0x81};
    uint8_t response_use_ssl[5] = {0x83, 0, 0, 1, 0x8e};
    uint16_t len;

    (void)rj; 
    if(phase!=PROTOCOL_EARLY)
        return NULL;
    s_read(vw, vw->local_rfd.fd, buffer, 4) ;
    len=(uint16_t)(((uint16_t)(buffer[2])<<8)|buffer[3]);
    if(len>sizeof buffer-4) {
        s_log(LOG_ERR, "Received block too long");
        throw_exception(vw, 1);
    }
    s_read(vw, vw->local_rfd.fd, buffer+4, len);
    if(buffer[0]!=0x81) { 
        s_log(LOG_ERR, "Client did not send session setup");
        s_write(vw, vw->local_wfd.fd, response_access_denied, 5);
        throw_exception(vw, 1);
    }
    s_write(vw, vw->local_wfd.fd, response_use_ssl, 5);
    return NULL;
}

