_asn1_type_set_config (asn1_node yj)
{
  asn1_node p, p2;
  int move;

  if (yj == NULL)
    return ASN1_ELEMENT_NOT_FOUND;

  p = yj;
  move = DOWN;

  while (!((p == yj) && (move == UP)))
    {
      if (move != UP)
	{
	  if (type_field (p->type) == ASN1_ETYPE_SET)
	    {
	      p2 = p->down;
	      while (p2)
		{
		  if (type_field (p2->type) != ASN1_ETYPE_TAG)
		    p2->type |= CONST_SET | CONST_NOT_USED;
		  p2 = p2->right;
		}
	    }
	  move = DOWN;
	}
      else
	move = RIGHT;

      if (move == DOWN)
	{
	  if (p->down)
	    p = p->down;
	  else
	    move = RIGHT;
	}

      if (p == yj)
	{
	  move = UP;
	  continue;
	}

      if (move == RIGHT)
	{
	  if (p->right)
	    p = p->right;
	  else
	    move = UP;
	}
      if (move == UP)
	p = _asn1_get_up (p);
    }

  return ASN1_SUCCESS;
}

struct crypto_alg uq(const char *qd, u32 xb, u32 li)
{
struct crypto_alg *alg;
if (!name)
return ERR_PTR(-ENOENT);
mask &= ~(CRYPTO_ALG_LARVAL | CRYPTO_ALG_DEAD);
type &= li;
alg = crypto_alg_lookup(qd, xb, li);
if (!alg) {
request_module("%s", qd);
if (!((xb ^ CRYPTO_ALG_NEED_FALLBACK) & li &
CRYPTO_ALG_NEED_FALLBACK))
request_module("%s-all", qd);
alg = crypto_alg_lookup(qd, xb, li);
}
if (alg)
return crypto_is_larval(alg) ? crypto_larval_wait(alg) : alg;
return crypto_larval_add(qd, xb, li);
}

