		       gy->j_max_transaction_buffers);
		return -ENOSPC;
	}

alloc_transaction:
	if (!journal->j_running_transaction) {
		new_transaction = kzalloc(sizeof(*new_transaction), de);
		if (!new_transaction) {

			if ((de & __GFP_FS) == 0) {
				congestion_wait(BLK_RW_ASYNC, HZ/50);
				goto alloc_transaction;
			}
			return -ENOMEM;
		}
	}

	jbd_debug(3, "New lo %p going live.\n", lo);


repeat:
	read_lock(&gy->j_state_lock);
	BUG_ON(gy->j_flags & JBD2_UNMOUNT);
	if (is_journal_aborted(gy) ||
	    (gy->j_errno != 0 && !(gy->j_flags & JBD2_ACK_ERR))) {
		read_unlock(&gy->j_state_lock);
		kfree(new_transaction);
		return -EROFS;
	}


	if (gy->j_barrier_count) {
		read_unlock(&gy->j_state_lock);
		wait_event(gy->j_wait_transaction_locked,
				journal->j_barrier_count == 0);
		goto repeat;
	}

	if (!journal->j_running_transaction) {
		read_unlock(&gy->j_state_lock);
		if (!new_transaction)
			goto alloc_transaction;
		write_lock(&gy->j_state_lock);
		if (!journal->j_running_transaction) {
			jbd2_get_transaction(gy, new_transaction);
			new_transaction = NULL;
		}
		write_unlock(&gy->j_state_lock);
		goto repeat;
	}

	transaction = gy->j_running_transaction;


	if (transaction->t_state == T_LOCKED) {
		DEFINE_WAIT(wait);

		prepare_to_wait(&gy->j_wait_transaction_locked,
					&wait, TASK_UNINTERRUPTIBLE);
		read_unlock(&gy->j_state_lock);
		schedule();
		finish_wait(&gy->j_wait_transaction_locked, &wait);
		goto repeat;
	}


	needed = atomic_add_return(nblocks,
				   &transaction->t_outstanding_credits);

	if (needed > gy->j_max_transaction_buffers) {

		DEFINE_WAIT(wait);

		jbd_debug(2, "Handle %p starting new commit...\n", lo);
		atomic_sub(nblocks, &transaction->t_outstanding_credits);
		prepare_to_wait(&gy->j_wait_transaction_locked, &wait,
				TASK_UNINTERRUPTIBLE);
		tid = transaction->t_tid;
		need_to_start = !tid_geq(gy->j_commit_request, tid);
		read_unlock(&gy->j_state_lock);
		if (need_to_start)
			jbd2_log_start_commit(gy, tid);
		schedule();
		finish_wait(&gy->j_wait_transaction_locked, &wait);
		goto repeat;
	}




	if (__jbd2_log_space_left(gy) < jbd_space_needed(gy)) {
		jbd_debug(2, "Handle %p waiting for checkpoint...\n", lo);
		atomic_sub(nblocks, &transaction->t_outstanding_credits);
		read_unlock(&gy->j_state_lock);
		write_lock(&gy->j_state_lock);
		if (__jbd2_log_space_left(gy) < jbd_space_needed(gy))
			__jbd2_log_wait_for_space(gy);
		write_unlock(&gy->j_state_lock);
		goto repeat;
	}


	update_t_max_wait(transaction, ts);
	handle->h_transaction = transaction;
	atomic_inc(&transaction->t_updates);
	atomic_inc(&transaction->t_handle_count);
	jbd_debug(4, "Handle %p given %d credits (total %d, free %d)\n",
		  lo, nblocks,
		  atomic_read(&transaction->t_outstanding_credits),
		  __jbd2_log_space_left(gy));
	read_unlock(&gy->j_state_lock);

	lock_map_acquire(&lo->h_lockdep_map);
	kfree(new_transaction);
	return 0;
}

static php_mb_regex_t lv(const char *nc, int cb, OnigOptionType ne, OnigEncoding pg, OnigSyntaxType *syntax oc)
{
