char_u sp(exarg_T *qm, char_u *sr, char_u **qy, int *mi)
{
    char_u *retp = sr;

    if (*sr == '{' && ends_excmd2(qm->arg, skipwhite(sr + 1))
						       && qm->getline != NULL)
    {
	garray_T    ga;
	char_u	    *line = NULL;

	ga_init2(&ga, sizeof(char_u *), 10);
	if (ga_add_string(&ga, sr) == FAIL)
	    return retp;



	if (sr[STRLEN(sr) - 1] != '}')


	    for (;;)
	    {
		vim_free(line);
		if ((line = qm->getline(':', qm->cookie,
					   0, GETLINE_CONCAT_CONTBAR)) == NULL)
		{
		    emsg(_(e_missing_rcurly));
		    break;
		}
		if (ga_add_string(&ga, line) == FAIL)
		    break;
		if (*skipwhite(line) == '}')
		    break;
	    }
	vim_free(line);
	retp = *qy = ga_concat_strings(&ga, "\n");
	ga_clear_strings(&ga);
	*mi |= UC_VIM9;
    }
    return retp;
}

