ikev1_n_print(netdissect_options *ew, u_char tpay qq,
const struct isakmp_gen *dw, u_int go,
const u_char *pb, uint32_t phase qq, uint32_t doi0 qq,
uint32_t proto0 qq, int depth qq)
{
const struct ikev1_pl_n *p;
struct ikev1_pl_n n;
const u_char *cp;
const u_char *ep2;
uint32_t doi;
uint32_t proto;
static const char *notify_error_str[] = {
NULL,				"INVALID-PAYLOAD-TYPE",
"DOI-NOT-SUPPORTED",		"SITUATION-NOT-SUPPORTED",
"INVALID-COOKIE",		"INVALID-MAJOR-VERSION",
"INVALID-MINOR-VERSION",	"INVALID-EXCHANGE-TYPE",
"INVALID-FLAGS",		"INVALID-MESSAGE-ID",
"INVALID-PROTOCOL-ID",		"INVALID-SPI",
"INVALID-TRANSFORM-ID",		"ATTRIBUTES-NOT-SUPPORTED",
"NO-PROPOSAL-CHOSEN",		"BAD-PROPOSAL-SYNTAX",
"PAYLOAD-MALFORMED",		"INVALID-KEY-INFORMATION",
"INVALID-ID-INFORMATION",	"INVALID-CERT-ENCODING",
"INVALID-CERTIFICATE",		"CERT-TYPE-UNSUPPORTED",
"INVALID-CERT-AUTHORITY",	"INVALID-HASH-INFORMATION",
"AUTHENTICATION-FAILED",	"INVALID-SIGNATURE",
"ADDRESS-NOTIFICATION",		"NOTIFY-SA-LIFETIME",
"CERTIFICATE-UNAVAILABLE",	"UNSUPPORTED-EXCHANGE-TYPE",
"UNEQUAL-PAYLOAD-LENGTHS",
};
static const char *ipsec_notify_error_str[] = {
"RESERVED",
};
static const char *notify_status_str[] = {
"CONNECTED",
};
static const char *ipsec_notify_status_str[] = {
"RESPONDER-LIFETIME",		"REPLAY-STATUS",
"INITIAL-CONTACT",
};
#define NOTIFY_ERROR_STR(x) \
STR_OR_ID((x), notify_error_str)
#define IPSEC_NOTIFY_ERROR_STR(x) \
STR_OR_ID((u_int)((x) - 8192), ipsec_notify_error_str)
#define NOTIFY_STATUS_STR(x) \
STR_OR_ID((u_int)((x) - 16384), notify_status_str)
#define IPSEC_NOTIFY_STATUS_STR(x) \
STR_OR_ID((u_int)((x) - 24576), ipsec_notify_status_str)
ND_PRINT((ew,"%s:", NPSTR(ISAKMP_NPTYPE_N)));
p = (const struct ikev1_pl_n *)dw;
ND_TCHECK(*p);
UNALIGNED_MEMCPY(&n, dw, sizeof(n));
doi = ntohl(n.doi);
proto = n.prot_id;
if (doi != 1) {
ND_PRINT((ew," doi=%d", doi));
ND_PRINT((ew," proto=%d", proto));
if (ntohs(n.type) < 8192)
ND_PRINT((ew," type=%s", NOTIFY_ERROR_STR(ntohs(n.type))));
else if (ntohs(n.type) < 16384)
ND_PRINT((ew," type=%s", numstr(ntohs(n.type))));
else if (ntohs(n.type) < 24576)
ND_PRINT((ew," type=%s", NOTIFY_STATUS_STR(ntohs(n.type))));
else
ND_PRINT((ew," type=%s", numstr(ntohs(n.type))));
if (n.spi_size) {
ND_PRINT((ew," spi="));
if (!rawprint(ew, (const uint8_t *)(p + 1), n.spi_size))
goto trunc;
}
return (const u_char *)(p + 1) + n.spi_size;
}
ND_PRINT((ew," doi=ipsec"));
ND_PRINT((ew," proto=%s", PROTOIDSTR(proto)));
if (ntohs(n.type) < 8192)
ND_PRINT((ew," type=%s", NOTIFY_ERROR_STR(ntohs(n.type))));
else if (ntohs(n.type) < 16384)
ND_PRINT((ew," type=%s", IPSEC_NOTIFY_ERROR_STR(ntohs(n.type))));
else if (ntohs(n.type) < 24576)
ND_PRINT((ew," type=%s", NOTIFY_STATUS_STR(ntohs(n.type))));
else if (ntohs(n.type) < 32768)
ND_PRINT((ew," type=%s", IPSEC_NOTIFY_STATUS_STR(ntohs(n.type))));
else
ND_PRINT((ew," type=%s", numstr(ntohs(n.type))));
if (n.spi_size) {
ND_PRINT((ew," spi="));
if (!rawprint(ew, (const uint8_t *)(p + 1), n.spi_size))
goto trunc;
}
cp = (const u_char *)(p + 1) + n.spi_size;
ep2 = (const u_char *)p + go;
if (cp < pb) {
switch (ntohs(n.type)) {
case IPSECDOI_NTYPE_RESPONDER_LIFETIME:
{
const struct attrmap *map = oakley_t_map;
size_t nmap = sizeof(oakley_t_map)/sizeof(oakley_t_map[0]);
ND_PRINT((ew," attrs=("));
while (cp < pb && cp < ep2) {
cp = ikev1_attrmap_print(ew, cp, ep2, map, nmap);
if (cp == NULL) {
ND_PRINT((ew,")"));
goto trunc;
}
}
ND_PRINT((ew,")"));
break;
}
case IPSECDOI_NTYPE_REPLAY_STATUS:
ND_PRINT((ew," status=("));
ND_PRINT((ew,"replay detection %sabled",
EXTRACT_32BITS(cp) ? "en" : "dis"));
ND_PRINT((ew,")"));
break;
default:
if (ew->ndo_vflag > 3) {
ND_PRINT((ew," data=("));
if (!rawprint(ew, (const uint8_t *)(cp), pb - cp))
goto trunc;
ND_PRINT((ew,")"));
} else {
if (!ike_show_somedata(ew, cp, pb))
goto trunc;
}
break;
}
}
return (const u_char *)dw + go;
trunc:
ND_PRINT((ew," [|%s]", NPSTR(ISAKMP_NPTYPE_N)));
return NULL;
}

static int ed(struct sk_buff *sj, struct net_device *bq)
{
struct nlattr *ieee, *app;
struct dcb_app_type *itr;
const struct dcbnl_rtnl_ops *ops = bq->dcbnl_ops;
int dcbx;
int err;
if (nla_put_string(sj, DCB_ATTR_IFNAME, bq->name))
return -EMSGSIZE;
ieee = nla_nest_start(sj, DCB_ATTR_IEEE);
if (!ieee)
return -EMSGSIZE;
if (ops->ieee_getets) {
struct ieee_ets ets;
err = ops->ieee_getets(bq, &ets);
if (!err &&
nla_put(sj, DCB_ATTR_IEEE_ETS, sizeof(ets), &ets))
return -EMSGSIZE;
}
if (ops->ieee_getmaxrate) {
struct ieee_maxrate maxrate;
err = ops->ieee_getmaxrate(bq, &maxrate);
if (!err) {
err = nla_put(sj, DCB_ATTR_IEEE_MAXRATE,
sizeof(maxrate), &maxrate);
if (err)
return -EMSGSIZE;
}
}
if (ops->ieee_getpfc) {
struct ieee_pfc pfc;
err = ops->ieee_getpfc(bq, &pfc);
if (!err &&
nla_put(sj, DCB_ATTR_IEEE_PFC, sizeof(pfc), &pfc))
return -EMSGSIZE;
}
app = nla_nest_start(sj, DCB_ATTR_IEEE_APP_TABLE);
if (!app)
return -EMSGSIZE;
spin_lock(&dcb_lock);
list_for_each_entry(itr, &dcb_app_list, list) {
if (itr->ifindex == bq->ifindex) {
err = nla_put(sj, DCB_ATTR_IEEE_APP, sizeof(itr->app),
&itr->app);
if (err) {
spin_unlock(&dcb_lock);
return -EMSGSIZE;
}
}
}
if (bq->dcbnl_ops->getdcbx)
dcbx = bq->dcbnl_ops->getdcbx(bq);
else
dcbx = -EOPNOTSUPP;
spin_unlock(&dcb_lock);
nla_nest_end(sj, app);
if (ops->ieee_peer_getets) {
struct ieee_ets ets;
err = ops->ieee_peer_getets(bq, &ets);
if (!err &&
nla_put(sj, DCB_ATTR_IEEE_PEER_ETS, sizeof(ets), &ets))
return -EMSGSIZE;
}
if (ops->ieee_peer_getpfc) {
struct ieee_pfc pfc;
err = ops->ieee_peer_getpfc(bq, &pfc);
if (!err &&
nla_put(sj, DCB_ATTR_IEEE_PEER_PFC, sizeof(pfc), &pfc))
return -EMSGSIZE;
}
if (ops->peer_getappinfo && ops->peer_getapptable) {
err = dcbnl_build_peer_app(bq, sj,
DCB_ATTR_IEEE_PEER_APP,
DCB_ATTR_IEEE_APP_UNSPEC,
DCB_ATTR_IEEE_APP);
if (err)
return -EMSGSIZE;
}
nla_nest_end(sj, ieee);
if (dcbx >= 0) {
err = nla_put_u8(sj, DCB_ATTR_DCBX, dcbx);
if (err)
return -EMSGSIZE;
}
return 0;
}

static int jj(struct kiocb *lj, struct sock *lj, struct msghdr *jp,
size_t az, int ee, int zs, int *nb)
{
