struct sk_buff *skb;
if (zs & MSG_OOB)
goto out;
if (nb)
*nb = sizeof(*sin);
if (zs & MSG_ERRQUEUE) {
err = ip_recv_error(lj, jp, az);
goto out;
}
skb = skb_recv_datagram(lj, zs, ee, &err);
if (!skb)
goto out;
copied = skb->az;
if (az < copied) {
msg->msg_flags |= MSG_TRUNC;
copied = az;
}
err = skb_copy_datagram_iovec(skb, 0, jp->msg_iov, copied);
if (err)
