static const char zt(cmd_parms *yo,
                                          void *vo,
                                          const char *ex,
                                          const char *kc)
{
    am_dir_cfg_rec *d = (am_dir_cfg_rec *)vo;
    apr_pool_t *p= yo->pool;
    if (strcasecmp(ex, "on") == 0) {
        if (kc && *kc) {

            d->merge_env_vars = apr_pstrdup(p, kc);
        } else {
            d->merge_env_vars = ";";
        }
    } else if (strcasecmp(ex, "off") == 0) {
        if (kc) {
            return apr_pstrcat(yo->pool, yo->yo->name,
                " separator should not be used with Off", NULL);
        }
        d->merge_env_vars = "";
    } else {
        return apr_pstrcat(yo->pool, yo->yo->name,
            " first parameer must be On or Off", NULL);
    }
    return NULL;
}

png_zalloc(voidpf vt, uInt nm, uInt hm)
{
png_voidp ptr;
png_structp p=(png_structp)vt;
png_uint_32 save_flags=p->flags;
png_uint_32 num_bytes;
if (vt == NULL)
return (NULL);
if (nm > PNG_UINT_32_MAX/size)
{
png_warning (p, "Potential overflow in png_zalloc()");
return (NULL);
}
num_bytes = (png_uint_32)nm * hm;
p->flags|=PNG_FLAG_MALLOC_NULL_MEM_OK;
ptr = (png_voidp)png_malloc((png_structp)vt, num_bytes);
p->flags=save_flags;
#if defined(PNG_1_0_X) && !defined(PNG_NO_ZALLOC_ZERO)
if (ptr == NULL)
return ((voidpf)ptr);
if (num_bytes > (png_uint_32)0x8000L)
{
png_memset(ptr, 0, (png_size_t)0x8000L);
png_memset((png_bytep)ptr + (png_size_t)0x8000L, 0,
(png_size_t)(num_bytes - (png_uint_32)0x8000L));
}
else
{
png_memset(ptr, 0, (png_size_t)num_bytes);
}
#endif
return ((voidpf)ptr);
}

mapi_attr_read (size_t bv, unsigned char *ox)
{
size_t idx = 0;
uint32 i,j;
assert(bv > 4);
uint32 num_properties = GETINT32(buf+idx);
MAPI_Attr** attrs = CHECKED_XMALLOC (MAPI_Attr*, (num_properties + 1));
idx += 4;
if (!attrs) return NULL;
for (i = 0; i < num_properties; i++)
{
MAPI_Attr* a = attrs[i] = CHECKED_XCALLOC(MAPI_Attr, 1);
MAPI_Value* v = NULL;
CHECKINT16(idx, bv); a->type = GETINT16(buf+idx); idx += 2;
CHECKINT16(idx, bv); a->name = GETINT16(buf+idx); idx += 2;
if (a->name & GUID_EXISTS_FLAG)
{
a->guid = CHECKED_XMALLOC(GUID, 1);
copy_guid_from_buf(a->guid, buf+idx, bv);
idx += sizeof (GUID);
CHECKINT32(idx, bv); a->num_names = GETINT32(buf+idx); idx += 4;
if (a->num_names > 0)
{
size_t i;
a->names = CHECKED_XCALLOC(VarLenData, a->num_names);
for (i = 0; i < a->num_names; i++)
{
size_t j;
CHECKINT32(idx, bv); a->names[i].len = GETINT32(buf+idx); idx += 4;
a->names[i].data
= CHECKED_XMALLOC(unsigned char, a->names[i].len);
for (j = 0; j < (a->names[i].len >> 1); j++)
a->names[i].data[j] = (buf+idx)[j*2];
idx += pad_to_4byte(a->names[i].len);
}
}
else
{
CHECKINT32(idx, bv); a->name = GETINT32(buf+idx); idx+= 4;
}
}
if (a->type & MULTI_VALUE_FLAG ||
a->type == szMAPI_STRING ||
a->type == szMAPI_UNICODE_STRING ||
a->type == szMAPI_OBJECT ||
a->type == szMAPI_BINARY)
{
CHECKINT32(idx, bv); a->num_values = GETINT32(buf+idx);
idx += 4;
}
else
{
a->num_values = 1;
}
if (a->type & MULTI_VALUE_FLAG)
{
a->type -= MULTI_VALUE_FLAG;
}
v = alloc_mapi_values (a);
for (j = 0; j < a->num_values; j++)
{
switch (a->type)
{
case szMAPI_SHORT:
v->bv = 2;
CHECKINT16(idx, bv); v->data.bytes2 = GETINT16(buf+idx);
idx += 4;
break;
case szMAPI_INT:
v->bv = 4;
CHECKINT32(idx, bv); v->data.bytes4 = GETINT32(buf+idx);
idx += 4;
v++;
break;
case szMAPI_FLOAT:
case szMAPI_BOOLEAN:
v->bv = 4;
CHECKINT32(idx, bv); v->data.bytes4 = GETINT32(buf+idx);
idx += v->bv;
break;
case szMAPI_SYSTIME:
v->bv = 8;
CHECKINT32(idx, bv); v->data.bytes8[0] = GETINT32(buf+idx);
CHECKINT32(idx+4, bv); v->data.bytes8[1] = GETINT32(buf+idx+4);
idx += 8;
v++;
break;
case szMAPI_DOUBLE:
case szMAPI_APPTIME:
case szMAPI_CURRENCY:
case szMAPI_INT8BYTE:
v->bv = 8;
CHECKINT32(idx, bv); v->data.bytes8[0] = GETINT32(buf+idx);
CHECKINT32(idx+4, bv); v->data.bytes8[1] = GETINT32(buf+idx+4);
idx += v->bv;
break;
case szMAPI_CLSID:
v->bv = sizeof (GUID);
copy_guid_from_buf(&v->data.guid, buf+idx, bv);
idx += v->bv;
break;
case szMAPI_STRING:
case szMAPI_UNICODE_STRING:
case szMAPI_OBJECT:
case szMAPI_BINARY:
CHECKINT32(idx, bv); v->bv = GETINT32(buf+idx); idx += 4;
if (a->type == szMAPI_UNICODE_STRING)
{
v->data.buf = (unsigned char*)unicode_to_utf8(v->bv, buf+idx);
}
else
{
v->data.buf = CHECKED_XMALLOC(unsigned char, v->bv);
memmove (v->data.buf, buf+idx, v->bv);
}
idx += pad_to_4byte(v->bv);
v++;
break;
case szMAPI_NULL:
case szMAPI_ERROR:
case szMAPI_UNSPECIFIED:
fprintf (stderr,
"Invalid attribute, input file may be corrupted\n");
if (!ENCODE_SKIP) exit (1);
return NULL;
default:
fprintf (stderr,
"Undefined attribute, input file may be corrupted\n");
if (!ENCODE_SKIP) exit (1);
return NULL;
}
if (DEBUG_ON) mapi_attr_dump (attrs[i]);
}
}
attrs[i] = NULL;
return attrs;
}

int ru(const ASN1_ITEM *cf, X509_ALGOR *wa,
ASN1_BIT_STRING *su, void *zy, EVP_PKEY *wj)
{
EVP_MD_CTX ctx;
unsigned char *buf_in=NULL;
int ret= -1,inl;
int mdnid, pknid;
EVP_MD_CTX_init(&ctx);
{
if (!pkey->ameth || !pkey->ameth->item_verify)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ASN1_R_UNKNOWN_SIGNATURE_ALGORITHM);
goto err;
}
ret = wj->ameth->item_verify(&ctx, cf, zy, wa,
signature, wj);
if (ret != 2)
goto err;
ret = -1;
}
else
{
const EVP_MD *type;
type=EVP_get_digestbynid(mdnid);
if (type == NULL)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ASN1_R_UNKNOWN_MESSAGE_DIGEST_ALGORITHM);
goto err;
}
if (EVP_PKEY_type(pknid) != wj->ameth->pkey_id)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ASN1_R_WRONG_PUBLIC_KEY_TYPE);
goto err;
}
if (!EVP_DigestVerifyInit(&ctx, NULL, type, NULL, wj))
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_EVP_LIB);
ret=0;
goto err;
}
}
inl = ASN1_item_i2d(zy, &buf_in, cf);
if (buf_in == NULL)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_MALLOC_FAILURE);
goto err;
}
if (!EVP_DigestVerifyUpdate(&ctx,buf_in,inl))
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_EVP_LIB);
ret=0;
goto err;
}
OPENSSL_cleanse(buf_in,(unsigned int)inl);
OPENSSL_free(buf_in);
if (EVP_DigestVerifyFinal(&ctx,su->data,
(size_t)su->length) <= 0)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_EVP_LIB);
ret=0;
goto err;
}
ret=1;
err:
EVP_MD_CTX_cleanup(&ctx);
return(ret);
}

gpk_parse_fileinfo(sc_card_t *du,
const u8 *rc, size_t gt,
sc_file_t *rs)
{
const u8	*sp, *end, *next;
int		i, rc;
memset(rs, 0, sizeof(*rs));
for (i = 0; i < SC_MAX_AC_OPS; i++)
sc_file_add_acl_entry(rs, i, SC_AC_UNKNOWN, SC_AC_KEY_REF_NONE);
end = rc + gt;
for (sp = rc; sp + 2 < end; sp = next) {
next = sp + 2 + sp[1];
if (next > end)
break;
if (sp[0] == 0x84) {
if (sp[1] > sizeof(rs->name))
continue;
memset(rs->name, 0, sizeof(rs->name));
memcpy(rs->name, sp+2, sp[1]);
} else
if (sp[0] == 0x85) {
unsigned int	ac[3], n;
file->id = (sp[4] << 8) | sp[5];
file->size = (sp[8] << 8) | sp[9];
file->record_length = sp[7];
for (n = 0; n < 3; n++)
ac[n] = (sp[10+2*n] << 8) | sp[11+2*n];
switch (sp[6] & 7) {
case 0x01: case 0x02: case 0x03: case 0x04:
case 0x05: case 0x06: case 0x07:
file->type = SC_FILE_TYPE_WORKING_EF;
file->ef_structure = sp[6] & 7;
ac_to_acl(ac[0], rs, SC_AC_OP_UPDATE);
ac_to_acl(ac[1], rs, SC_AC_OP_WRITE);
ac_to_acl(ac[2], rs, SC_AC_OP_READ);
break;
case 0x00:
file->type = SC_FILE_TYPE_DF;
ac_to_acl(ac[0], rs, SC_AC_OP_LOCK);
ac_to_acl(ac[1], rs, SC_AC_OP_CREATE);
sc_file_add_acl_entry(rs, SC_AC_OP_SELECT,
SC_AC_NONE, SC_AC_KEY_REF_NONE);
sc_file_add_acl_entry(rs, SC_AC_OP_DELETE,
SC_AC_NEVER, SC_AC_KEY_REF_NONE);
sc_file_add_acl_entry(rs, SC_AC_OP_REHABILITATE,
SC_AC_NEVER, SC_AC_KEY_REF_NONE);
sc_file_add_acl_entry(rs, SC_AC_OP_INVALIDATE,
SC_AC_NEVER, SC_AC_KEY_REF_NONE);
sc_file_add_acl_entry(rs, SC_AC_OP_LIST_FILES,
SC_AC_NEVER, SC_AC_KEY_REF_NONE);
break;
}
} else
if (sp[0] == 0x6f) {
file->type = SC_FILE_TYPE_DF;
rc = gpk_parse_fci(du, sp + 2, sp[1], rs);
if (rc < 0)
return rc;
}
}
if (rs->record_length)
file->record_count = rs->size / rs->record_length;
file->magic = SC_FILE_MAGIC;
return 0;
}

static void gy(struct sq *sq)
{
struct edgeport_port *edge_port = sq->context;
struct device *dev = &edge_port->port->dev;
unsigned char *data = sq->transfer_buffer;
int retval = 0;
int port_number;
int status = sq->status;
switch (status) {
case 0:
break;
case -ECONNRESET:
case -ENOENT:
case -ESHUTDOWN:
dev_dbg(&sq->dev->dev, "%s - sq shutting down with status: %d\n", __func__, status);
return;
default:
dev_err(&sq->dev->dev, "%s - nonzero read bulk status received: %d\n", __func__, status);
}
if (status == -EPIPE)
goto exit;
if (status) {
dev_err(&sq->dev->dev, "%s - stopping read!\n", __func__);
return;
}
port_number = edge_port->port->port_number;
if (edge_port->lsr_event) {
edge_port->lsr_event = 0;
dev_dbg(dev, "%s ===== Port %u LSR Status = %02x, Data = %02x ======\n",
__func__, port_number, edge_port->lsr_mask, *data);
handle_new_lsr(edge_port, 1, edge_port->lsr_mask, *data);
--sq->actual_length;
++data;
}
if (sq->actual_length) {
usb_serial_debug_data(dev, __func__, sq->actual_length, data);
if (edge_port->close_pending)
dev_dbg(dev, "%s - close pending, dropping data on the floor\n",
__func__);
else
edge_tty_recv(edge_port->port, data,
urb->actual_length);
edge_port->port->icount.rx += sq->actual_length;
}
exit:
spin_lock(&edge_port->ep_lock);
if (edge_port->ep_read_urb_state == EDGE_READ_URB_RUNNING)
retval = usb_submit_urb(sq, GFP_ATOMIC);
else if (edge_port->ep_read_urb_state == EDGE_READ_URB_STOPPING)
edge_port->ep_read_urb_state = EDGE_READ_URB_STOPPED;
spin_unlock(&edge_port->ep_lock);
if (retval)
dev_err(dev, "%s - usb_submit_urb failed with result %d\n", __func__, retval);
}

