long sh(const BlockEntry* gh,
const BlockEntry*& yt) const {
assert(gh);
assert(!pCurrEntry->EOS());
const Block* const pCurrBlock = gh->GetBlock();
assert(pCurrBlock && pCurrBlock->GetTrackNumber() == m_info.number);
if (!pCurrBlock || pCurrBlock->GetTrackNumber() != m_info.number)
return -1;
const Cluster* pCluster = gh->GetCluster();
assert(pCluster);
assert(!pCluster->EOS());
long status = pCluster->GetNext(gh, yt);
if (status < 0)
return status;
for (int i = 0;;) {
while (yt) {
const Block* const pNextBlock = yt->GetBlock();
assert(pNextBlock);
if (pNextBlock->GetTrackNumber() == m_info.number)
return 0;
pCurrEntry = yt;
status = pCluster->GetNext(gh, yt);
if (status < 0)
return status;
}
pCluster = m_pSegment->GetNext(pCluster);
if (pCluster == NULL) {
pNextEntry = GetEOS();
return 1;
}
if (pCluster->EOS()) {
#if 0
if (m_pSegment->Unparsed() <= 0)
{
pNextEntry = GetEOS();
return 1;
}
#else
if (m_pSegment->DoneParsing()) {
pNextEntry = GetEOS();
return 1;
}
#endif
pNextEntry = NULL;
return E_BUFFER_NOT_FULL;
}
status = pCluster->GetFirst(yt);
if (status < 0)
return status;
if (yt == NULL)
continue;
++i;
if (i >= 100)
break;
}
pNextEntry = GetEOS();
return 1;
}

