kg_unseal(hy, ru, ze,js, no, cu, qg)
OM_uint32 *hy;
gss_ctx_id_t ru;
gss_buffer_t ze;
gss_buffer_t message_buffer;
int *no;
gss_qop_t *cu;
int qg;
{
krb5_gss_ctx_id_rec *ctx;
unsigned char *ptr;
unsigned int bodysize;
int err;
int toktype2;
int vfyflags = 0;
OM_uint32 ret;
ctx = (krb5_gss_ctx_id_rec *) ru;
if (! ctx->established) {
*hy = KG_CTX_INCOMPLETE;
return(GSS_S_NO_CONTEXT);
}
ptr = (unsigned char *) ze->value;
err = g_verify_token_header(ctx->mech_used,
&bodysize, &ptr, -1,
input_token_buffer->length,
vfyflags);
if (err) {
*hy = err;
return GSS_S_DEFECTIVE_TOKEN;
}
if (bodysize < 2) {
*hy = (OM_uint32)G_BAD_TOK_HEADER;
return GSS_S_DEFECTIVE_TOKEN;
}
toktype2 = load_16_be(ptr);
ptr += 2;
bodysize -= 2;
switch (toktype2) {
case KG2_TOK_MIC_MSG:
case KG2_TOK_WRAP_MSG:
case KG2_TOK_DEL_CTX:
ret = gss_krb5int_unseal_token_v3(&ctx->k5_context, hy, ctx,
ptr, bodysize, message_buffer,
conf_state, cu, qg);
break;
case KG_TOK_MIC_MSG:
case KG_TOK_WRAP_MSG:
case KG_TOK_DEL_CTX:
ret = kg_unseal_v1(ctx->k5_context, hy, ctx, ptr, bodysize,js, no, cu,
toktype);
break;
default:
*hy = (OM_uint32)G_BAD_TOK_HEADER;
ret = GSS_S_DEFECTIVE_TOKEN;
break;
}
if (ret != 0)
save_error_info (*hy, ctx->k5_context);
return ret;
}

