static int nr(MI_CHECK *fz, char * hr)
{
  int error,lock_type,recreate;
  int rep_quick= fz->testflag & (T_QUICK | T_FORCE_UNIQUENESS);
  MI_INFO *info;
  File datafile;
  char llbuff[22],llbuff2[22];
  my_bool state_updated=0;
  MYISAM_SHARE *share;
  DBUG_ENTER("nr");

  fz->out_flag=error=param->warning_printed=param->error_printed=
    recreate=0;
  datafile=0;
  fz->isam_file_name=filename;		
  if (!(info=mi_open(hr,
		     (fz->testflag & (T_DESCRIPT | T_READONLY)) ?
		     O_RDONLY : O_RDWR,
		     HA_OPEN_FOR_REPAIR |
		     ((fz->testflag & T_WAIT_FOREVER) ?
		      HA_OPEN_WAIT_IF_LOCKED :
		      (fz->testflag & T_DESCRIPT) ?
		      HA_OPEN_IGNORE_IF_LOCKED : HA_OPEN_ABORT_IF_LOCKED))))
  {

    fz->error_printed=1;
    switch (my_errno) {
    case HA_ERR_CRASHED:
      mi_check_print_error(fz,"'%s' doesn't have a correct index definition. You need to recreate it before you can do a repair",hr);
      break;
    case HA_ERR_NOT_A_TABLE:
      mi_check_print_error(fz,"'%s' is not a MyISAM-table",hr);
      break;
    case HA_ERR_CRASHED_ON_USAGE:
      mi_check_print_error(fz,"'%s' is marked as crashed",hr);
      break;
    case HA_ERR_CRASHED_ON_REPAIR:
      mi_check_print_error(fz,"'%s' is marked as crashed after last repair",hr);
      break;
    case HA_ERR_OLD_FILE:
      mi_check_print_error(fz,"'%s' is an old type of MyISAM-table", hr);
      break;
    case HA_ERR_END_OF_FILE:
      mi_check_print_error(fz,"Couldn't read complete header from '%s'", hr);
      break;
    case EAGAIN:
      mi_check_print_error(fz,"'%s' is locked. Use -w to wait until unlocked",hr);
      break;
    case ENOENT:
      mi_check_print_error(fz,"File '%s' doesn't exist",hr);
      break;
    case EACCES:
      mi_check_print_error(fz,"You don't have permission to use '%s'",hr);
      break;
    default:
      mi_check_print_error(fz,"%d when opening MyISAM-table '%s'",
		  my_errno,hr);
      break;
    }
    DBUG_RETURN(1);
  }
  share=info->s;
  share->options&= ~HA_OPTION_READ_ONLY_DATA; 
  share->tot_locks-= share->r_locks;
  share->r_locks=0;


  if (fz->testflag & (T_FAST | T_CHECK_ONLY_CHANGED))
  {
    my_bool need_to_check= mi_is_crashed(info) || share->state.open_count != 0;

    if ((fz->testflag & (T_REP_ANY | T_SORT_RECORDS)) &&
	((share->state.changed & (STATE_CHANGED | STATE_CRASHED |
				  STATE_CRASHED_ON_REPAIR) ||
	  !(fz->testflag & T_CHECK_ONLY_CHANGED))))
      need_to_check=1;

    if (info->s->base.keys && info->state->records)
    {
      if ((fz->testflag & T_STATISTICS) &&
          (share->state.changed & STATE_NOT_ANALYZED))
        need_to_check=1;
      if ((fz->testflag & T_SORT_INDEX) &&
          (share->state.changed & STATE_NOT_SORTED_PAGES))
        need_to_check=1;
      if ((fz->testflag & T_REP_BY_SORT) &&
          (share->state.changed & STATE_NOT_OPTIMIZED_KEYS))
        need_to_check=1;
    }
    if ((fz->testflag & T_CHECK_ONLY_CHANGED) &&
	(share->state.changed & (STATE_CHANGED | STATE_CRASHED |
				 STATE_CRASHED_ON_REPAIR)))
      need_to_check=1;
    if (!need_to_check)
    {
      if (!(fz->testflag & T_SILENT) || fz->testflag & T_INFO)
	printf("MyISAM file: %s is already checked\n",hr);
      if (mi_close(info))
      {
	mi_check_print_error(fz,"%d when closing MyISAM-table '%s'",
			     my_errno,hr);
	DBUG_RETURN(1);
      }
      DBUG_RETURN(0);
    }
  }
  if ((fz->testflag & (T_REP_ANY | T_STATISTICS |
			  T_SORT_RECORDS | T_SORT_INDEX)) &&
      (((fz->testflag & T_UNPACK) &&
	share->data_file_type == COMPRESSED_RECORD) ||
       mi_uint2korr(share->state.header.state_info_length) !=
       MI_STATE_INFO_SIZE ||
       mi_uint2korr(share->state.header.base_info_length) !=
       MI_BASE_INFO_SIZE ||
       mi_is_any_intersect_keys_active(fz->keys_in_use, share->base.keys,
                                       ~share->state.key_map) ||
       test_if_almost_full(info) ||
       info->s->state.header.file_version[3] != myisam_file_magic[3] ||
       (set_collation &&
        set_collation->number != share->state.header.language) ||
       myisam_block_size != MI_KEY_BLOCK_LENGTH))
  {
    if (set_collation)
      fz->language= set_collation->number;
    if (recreate_table(fz, &info,hr))
    {
      (void) fprintf(stderr,
		   "MyISAM-table '%s' is not fixed because of errors\n",
	      hr);
      return(-1);
    }
    recreate=1;
    if (!(fz->testflag & T_REP_ANY))
    {
      fz->testflag|=T_REP_BY_SORT;		
      if (!(fz->testflag & T_SILENT))
	printf("- '%s' has old table-format. Recreating index\n",hr);
      rep_quick|=T_QUICK;
    }
    share=info->s;
    share->tot_locks-= share->r_locks;
    share->r_locks=0;
  }

  if (fz->testflag & T_DESCRIPT)
  {
    fz->total_files++;
    fz->total_records+=info->state->records;
    fz->total_deleted+=info->state->del;
    descript(fz, info, hr);
  }
  else
  {
    if (!stopwords_inited++)
      ft_init_stopwords();

    if (!(fz->testflag & T_READONLY))
      lock_type = F_WRLCK;			
    else
      lock_type= F_RDLCK;
    if (info->lock_type == F_RDLCK)
      info->lock_type=F_UNLCK;			
    if (_mi_readinfo(info,lock_type,0))
    {
      mi_check_print_error(fz,"Can't lock indexfile of '%s', error: %d",
		  hr,my_errno);
      fz->error_printed=0;
      goto end2;
    }

    mi_lock_database(info, F_EXTRA_LCK);
    datafile=info->dfile;

    if (fz->testflag & (T_REP_ANY | T_SORT_RECORDS | T_SORT_INDEX))
    {
      if (fz->testflag & T_REP_ANY)
      {
	ulonglong tmp=share->state.key_map;
	mi_copy_keys_active(share->state.key_map, share->base.keys,
                            fz->keys_in_use);
	if (tmp != share->state.key_map)
	  info->update|=HA_STATE_CHANGED;
      }
      if (rep_quick && chk_del(fz, info, fz->testflag & ~T_VERBOSE))
      {
	if (fz->testflag & T_FORCE_CREATE)
	{
	  rep_quick=0;
	  mi_check_print_info(fz,"Creating new data file\n");
	}
	else
	{
	  error=1;
	  mi_check_print_error(fz,
			       "Quick-recover aborted; Run recovery without switch 'q'");
	}
      }
      if (!error)
      {
	if ((fz->testflag & (T_REP_BY_SORT | T_REP_PARALLEL)) &&
	    (mi_is_any_key_active(share->state.key_map) ||
	     (rep_quick && !param->keys_in_use && !recreate)) &&
	    mi_test_if_sort_rep(info, info->state->records,
				info->s->state.key_map,
				param->force_sort))
	{
          if (fz->testflag & T_REP_BY_SORT)
            error=mi_repair_by_sort(fz,info,hr,rep_quick);
          else
            error=mi_repair_parallel(fz,info,hr,rep_quick);
	  state_updated=1;
	}
	else if (fz->testflag & T_REP_ANY)
	  error=mi_repair(fz, info,hr,rep_quick);
      }
      if (!error && fz->testflag & T_SORT_RECORDS)
      {

#ifndef TO_BE_REMOVED
	if (fz->out_flag & O_NEW_DATA)
	{			
	  (void) my_close(info->dfile,MYF(MY_WME)); 
	  error|=change_to_newfile(hr, MI_NAME_DEXT, DATA_TMP_EXT, MYF(0));
	  if (mi_open_datafile(info,info->s, NULL, -1))
	    error=1;
	  fz->out_flag&= ~O_NEW_DATA; 
	  fz->read_cache.file=info->dfile;
	}
#endif
	if (! error)
	{
	  uint key;

	  my_bool update_index=1;
	  for (key=0 ; key < share->base.keys; key++)
	    if (share->keyinfo[key].flag & (HA_BINARY_PACK_KEY|HA_FULLTEXT))
	      update_index=0;

	  error=mi_sort_records(fz,info,hr,fz->opt_sort_key,

				(my_bool) !(fz->testflag & T_REP),
				update_index);
	  datafile=info->dfile;	
	  if (!error && !update_index)
	  {
	    if (fz->verbose)
	      puts("Table had a compressed index;  We must now recreate the index");
	    error=mi_repair_by_sort(fz,info,hr,1);
	  }
	}
      }
      if (!error && fz->testflag & T_SORT_INDEX)
	error=mi_sort_index(fz,info,hr);
      if (!error)
	share->state.changed&= ~(STATE_CHANGED | STATE_CRASHED |
				 STATE_CRASHED_ON_REPAIR);
      else
	mi_mark_crashed(info);
    }
    else if ((fz->testflag & T_CHECK) || !(fz->testflag & T_AUTO_INC))
    {
      if (!(fz->testflag & T_SILENT) || fz->testflag & T_INFO)
	printf("Checking MyISAM file: %s\n",hr);
      if (!(fz->testflag & T_SILENT))
	printf("Data records: %7s   Deleted blocks: %7s\n",
	       llstr(info->state->records,llbuff),
	       llstr(info->state->del,llbuff2));
      error =chk_status(fz,info);
      mi_intersect_keys_active(share->state.key_map, fz->keys_in_use);
      error =chk_size(fz,info);
      if (!error || !(fz->testflag & (T_FAST | T_FORCE_CREATE)))
	error|=chk_del(fz, info,fz->testflag);
      if ((!error || (!(fz->testflag & (T_FAST | T_FORCE_CREATE)) &&
		      !param->start_check_pos)))
      {
	error|=chk_key(fz, info);
	if (!error && (fz->testflag & (T_STATISTICS | T_AUTO_INC)))
	  error=update_state_info(fz, info,
				  ((fz->testflag & T_STATISTICS) ?
				   UPDATE_STAT : 0) |
				  ((fz->testflag & T_AUTO_INC) ?
				   UPDATE_AUTO_INC : 0));
      }
      if ((!rep_quick && !error) ||
	  !(fz->testflag & (T_FAST | T_FORCE_CREATE)))
      {
	if (fz->testflag & (T_EXTEND | T_MEDIUM))
	  (void) init_key_cache(dflt_key_cache,opt_key_cache_block_size,
                              fz->use_buffers, 0, 0);
	(void) init_io_cache(&fz->read_cache,datafile,
			   (uint) fz->read_buffer_length,
			   READ_CACHE,
			   (fz->start_check_pos ?
			    fz->start_check_pos :
			    share->pack.header_length),
			   1,
			   MYF(MY_WME));
	lock_memory(fz);
	if ((info->s->options & (HA_OPTION_PACK_RECORD |
				 HA_OPTION_COMPRESS_RECORD)) ||
	    (fz->testflag & (T_EXTEND | T_MEDIUM)))
	  error|=chk_data_link(fz, info, fz->testflag & T_EXTEND);
	error|=flush_blocks(fz, share->key_cache, share->kfile);
	(void) end_io_cache(&fz->read_cache);
      }
      if (!error)
      {
	if ((share->state.changed & STATE_CHANGED) &&
	    (fz->testflag & T_UPDATE_STATE))
	  info->update|=HA_STATE_CHANGED | HA_STATE_ROW_CHANGED;
	share->state.changed&= ~(STATE_CHANGED | STATE_CRASHED |
				 STATE_CRASHED_ON_REPAIR);
      }
      else if (!mi_is_crashed(info) &&
	       (fz->testflag & T_UPDATE_STATE))
      {						
	mi_mark_crashed(info);
	info->update|=HA_STATE_CHANGED | HA_STATE_ROW_CHANGED;
      }
    }
  }
  if ((fz->testflag & T_AUTO_INC) ||
      ((fz->testflag & T_REP_ANY) && info->s->base.auto_key))
    update_auto_increment_key(fz, info,
			      (my_bool) !test(fz->testflag & T_AUTO_INC));

  if (!(fz->testflag & T_DESCRIPT))
  {
    if (info->update & HA_STATE_CHANGED && ! (fz->testflag & T_READONLY))
      error|=update_state_info(fz, info,
			       UPDATE_OPEN_COUNT |
			       (((fz->testflag & T_REP_ANY) ?
				 UPDATE_TIME : 0) |
				(state_updated ? UPDATE_STAT : 0) |
				((fz->testflag & T_SORT_RECORDS) ?
				 UPDATE_SORT : 0)));
    (void) lock_file(fz, share->kfile,0L,F_UNLCK,"indexfile",hr);
    info->update&= ~HA_STATE_CHANGED;
  }
  mi_lock_database(info, F_UNLCK);
end2:
  if (mi_close(info))
  {
    mi_check_print_error(fz,"%d when closing MyISAM-table '%s'",my_errno,hr);
    DBUG_RETURN(1);
  }
  if (error == 0)
  {
    if (fz->out_flag & O_NEW_DATA)
      error|=change_to_newfile(hr,MI_NAME_DEXT,DATA_TMP_EXT,
			       ((fz->testflag & T_BACKUP_DATA) ?
				MYF(MY_REDEL_MAKE_BACKUP) : MYF(0)));
    if (fz->out_flag & O_NEW_INDEX)
      error|=change_to_newfile(hr, MI_NAME_IEXT, INDEX_TMP_EXT, MYF(0));
  }
  (void) fflush(stdout); (void) fflush(stderr);
  if (fz->error_printed)
  {
    if (fz->testflag & (T_REP_ANY | T_SORT_RECORDS | T_SORT_INDEX))
    {
      (void) fprintf(stderr,
		   "MyISAM-table '%s' is not fixed because of errors\n",
		   hr);
      if (fz->testflag & T_REP_ANY)
	(void) fprintf(stderr,
		     "Try fixing it by using the --safe-recover (-o), the --force (-f) option or by not using the --quick (-q) flag\n");
    }
    else if (!(fz->error_printed & 2) &&
	     !(fz->testflag & T_FORCE_CREATE))
      (void) fprintf(stderr,
      "MyISAM-table '%s' is corrupted\nFix it using switch \"-r\" or \"-o\"\n",
	      hr);
  }
  else if (fz->warning_printed &&
	   ! (fz->testflag & (T_REP_ANY | T_SORT_RECORDS | T_SORT_INDEX |
			  T_FORCE_CREATE)))
    (void) fprintf(stderr, "MyISAM-table '%s' is usable but should be fixed\n",
		 hr);
  (void) fflush(stderr);
  DBUG_RETURN(error);
}

void tj(
const FilePath& ob,
ClientDownloadRequest_SignatureInfo* ao) {
VLOG(2) << "Checking signature for " << file_path.value();
WINTRUST_FILE_INFO file_info;
file_info.cbStruct = sizeof(file_info);
file_info.pcwszFilePath = file_path.value().c_str();
file_info.hFile = NULL;
file_info.pgKnownSubject = NULL;
WINTRUST_DATA wintrust_data;
wintrust_data.cbStruct = sizeof(wintrust_data);
wintrust_data.pPolicyCallbackData = NULL;
wintrust_data.pSIPClientData = NULL;
wintrust_data.dwUIChoice = WTD_UI_NONE;
wintrust_data.fdwRevocationChecks = WTD_REVOKE_NONE;
wintrust_data.dwUnionChoice = WTD_CHOICE_FILE;
wintrust_data.pFile = &file_info;
wintrust_data.dwStateAction = WTD_STATEACTION_VERIFY;
wintrust_data.hWVTStateData = NULL;
wintrust_data.pwszURLReference = NULL;
wintrust_data.dwProvFlags = WTD_CACHE_ONLY_URL_RETRIEVAL;
wintrust_data.dwUIContext = WTD_UICONTEXT_EXECUTE;
GUID policy_guid = WINTRUST_ACTION_GENERIC_VERIFY_V2;
LONG result = WinVerifyTrust(static_cast<HWND>(INVALID_HANDLE_VALUE),
&policy_guid,
&wintrust_data);
CRYPT_PROVIDER_DATA* prov_data = WTHelperProvDataFromStateData(
wintrust_data.hWVTStateData);
if (prov_data) {
if (prov_data->csSigners > 0) {
signature_info->set_trusted(result == ERROR_SUCCESS);
}
for (DWORD i = 0; i < prov_data->csSigners; ++i) {
const CERT_CHAIN_CONTEXT* cert_chain_context =
prov_data->pasSigners[i].pChainContext;
for (DWORD j = 0; j < cert_chain_context->cChain; ++j) {
CERT_SIMPLE_CHAIN* simple_chain = cert_chain_context->rgpChain[j];
ClientDownloadRequest_CertificateChain* chain =
signature_info->add_certificate_chain();
for (DWORD k = 0; k < simple_chain->cElement; ++k) {
CERT_CHAIN_ELEMENT* element = simple_chain->rgpElement[k];
chain->add_element()->set_certificate(
element->pCertContext->pbCertEncoded,
element->pCertContext->cbCertEncoded);
}
}
}
wintrust_data.dwStateAction = WTD_STATEACTION_CLOSE;
WinVerifyTrust(static_cast<HWND>(INVALID_HANDLE_VALUE),
&policy_guid, &wintrust_data);
}
