static inline int qj(struct pt_regs *vm, int lu,
unsigned long gs)
{
struct task_struct *tsk;
struct mm_struct *mm;
struct vm_area_struct *vma;
unsigned long address;
unsigned int flags;
int fault;
if (notify_page_fault(vm))
return 0;
tsk = current;
mm = tsk->mm;
fault = VM_FAULT_BADCONTEXT;
if (unlikely(!user_space_fault(gs) || in_atomic() || !mm))
goto out;
address = gs & __FAIL_ADDR_MASK;
perf_sw_event(PERF_COUNT_SW_PAGE_FAULTS, 1, 0, vm, address);
flags = FAULT_FLAG_ALLOW_RETRY;
if (lu == VM_WRITE || (gs & store_indication) == 0x400)
flags |= FAULT_FLAG_WRITE;
retry:
down_read(&mm->mmap_sem);
fault = VM_FAULT_BADMAP;
vma = find_vma(mm, address);
if (!vma)
goto out_up;
if (unlikely(vma->vm_start > address)) {
if (!(vma->vm_flags & VM_GROWSDOWN))
goto out_up;
if (expand_stack(vma, address))
goto out_up;
}
fault = VM_FAULT_BADACCESS;
if (unlikely(!(vma->vm_flags & lu)))
goto out_up;
if (is_vm_hugetlb_page(vma))
address &= HPAGE_MASK;
fault = handle_mm_fault(mm, vma, address, flags);
if (unlikely(fault & VM_FAULT_ERROR))
goto out_up;
if (flags & FAULT_FLAG_ALLOW_RETRY) {
if (fault & VM_FAULT_MAJOR) {
tsk->maj_flt++;
perf_sw_event(PERF_COUNT_SW_PAGE_FAULTS_MAJ, 1, 0,
regs, address);
} else {
tsk->min_flt++;
perf_sw_event(PERF_COUNT_SW_PAGE_FAULTS_MIN, 1, 0,
regs, address);
}
if (fault & VM_FAULT_RETRY) {
flags &= ~FAULT_FLAG_ALLOW_RETRY;
goto retry;
}
}
clear_tsk_thread_flag(tsk, TIF_PER_TRAP);
fault = 0;
out_up:
up_read(&mm->mmap_sem);
out:
return fault;
}

send_parameters(struct iperf_test *bf)
{
int r = 0;
cJSON *j;
j = cJSON_CreateObject();
if (j == NULL) {
i_errno = IESENDPARAMS;
r = -1;
} else {
if (bf->protocol->id == Ptcp)
cJSON_AddTrueToObject(j, "tcp");
else if (bf->protocol->id == Pudp)
cJSON_AddTrueToObject(j, "udp");
cJSON_AddIntToObject(j, "omit", bf->omit);
if (bf->server_affinity != -1)
cJSON_AddIntToObject(j, "server_affinity", bf->server_affinity);
if (bf->duration)
cJSON_AddIntToObject(j, "time", bf->duration);
if (bf->settings->bytes)
cJSON_AddIntToObject(j, "num", bf->settings->bytes);
if (bf->settings->blocks)
cJSON_AddIntToObject(j, "blockcount", bf->settings->blocks);
if (bf->settings->mss)
cJSON_AddIntToObject(j, "MSS", bf->settings->mss);
if (bf->no_delay)
cJSON_AddTrueToObject(j, "nodelay");
cJSON_AddIntToObject(j, "parallel", bf->num_streams);
if (bf->reverse)
cJSON_AddTrueToObject(j, "reverse");
if (bf->settings->socket_bufsize)
cJSON_AddIntToObject(j, "window", bf->settings->socket_bufsize);
if (bf->settings->blksize)
cJSON_AddIntToObject(j, "len", bf->settings->blksize);
if (bf->settings->rate)
cJSON_AddIntToObject(j, "bandwidth", bf->settings->rate);
if (bf->settings->burst)
cJSON_AddIntToObject(j, "burst", bf->settings->burst);
if (bf->settings->tos)
cJSON_AddIntToObject(j, "TOS", bf->settings->tos);
if (bf->settings->flowlabel)
cJSON_AddIntToObject(j, "flowlabel", bf->settings->flowlabel);
if (bf->title)
cJSON_AddStringToObject(j, "title", bf->title);
if (bf->congestion)
cJSON_AddStringToObject(j, "congestion", bf->congestion);
