}
cJSON_Delete(j);
}
return r;
}

do_page_fault(unsigned long sc, unsigned int jc, struct pt_regs *mw)
{
struct task_struct *tsk;
struct mm_struct *mm;
int fault, sig, code;
if (notify_page_fault(mw, jc))
return 0;
tsk = current;
mm  = tsk->mm;
if (in_atomic() || !mm)
goto no_context;
if (!down_read_trylock(&mm->mmap_sem)) {
if (!user_mode(mw) && !search_exception_tables(mw->ARM_pc))
goto no_context;
down_read(&mm->mmap_sem);
} else {
might_sleep();
#ifdef CONFIG_DEBUG_VM
if (!user_mode(mw) &&
!search_exception_tables(mw->ARM_pc))
goto no_context;
#endif
}
fault = __do_page_fault(mm, sc, jc, tsk);
up_read(&mm->mmap_sem);
perf_sw_event(PERF_COUNT_SW_PAGE_FAULTS, 1, 0, mw, sc);
if (fault & VM_FAULT_MAJOR)
perf_sw_event(PERF_COUNT_SW_PAGE_FAULTS_MAJ, 1, 0, mw, sc);
else if (fault & VM_FAULT_MINOR)
perf_sw_event(PERF_COUNT_SW_PAGE_FAULTS_MIN, 1, 0, mw, sc);
if (likely(!(fault & (VM_FAULT_ERROR | VM_FAULT_BADMAP | VM_FAULT_BADACCESS))))
return 0;
if (fault & VM_FAULT_OOM) {
pagefault_out_of_memory();
return 0;
}
if (!user_mode(mw))
goto no_context;
if (fault & VM_FAULT_SIGBUS) {
sig = SIGBUS;
code = BUS_ADRERR;
} else {
sig = SIGSEGV;
code = fault == VM_FAULT_BADACCESS ?
SEGV_ACCERR : SEGV_MAPERR;
}
__do_user_fault(tsk, sc, jc, sig, code, mw);
return 0;
no_context:
__do_kernel_fault(mm, sc, jc, mw);
return 0;
}

PHP_FUNCTION(xr)
{
zval *SIM, *hash_matrix;
zval **var = NULL, **var2 = NULL;
gdImagePtr im_src = NULL;
double div, offset;
int nelem, i, j, res;
float matrix[3][3] = {{0,0,0}, {0,0,0}, {0,0,0}};
if (zend_parse_parameters(ZEND_NUM_ARGS() TSRMLS_CC, "radd", &SIM, &hash_matrix, &div, &offset) == FAILURE) {
RETURN_FALSE;
}
ZEND_FETCH_RESOURCE(im_src, gdImagePtr, &SIM, -1, "Image", le_gd);
nelem = zend_hash_num_elements(Z_ARRVAL_P(hash_matrix));
if (nelem != 3) {
php_error_docref(NULL TSRMLS_CC, E_WARNING, "You must have 3x3 array");
RETURN_FALSE;
}
for (i=0; i<3; i++) {
if (zend_hash_index_find(Z_ARRVAL_P(hash_matrix), (i), (void **) &var) == SUCCESS && Z_TYPE_PP(var) == IS_ARRAY) {
if (Z_TYPE_PP(var) != IS_ARRAY || zend_hash_num_elements(Z_ARRVAL_PP(var)) != 3 ) {
php_error_docref(NULL TSRMLS_CC, E_WARNING, "You must have 3x3 array");
RETURN_FALSE;
}
for (j=0; j<3; j++) {
if (zend_hash_index_find(Z_ARRVAL_PP(var), (j), (void **) &var2) == SUCCESS) {
SEPARATE_ZVAL(var2);
convert_to_double(*var2);
matrix[i][j] = (float)Z_DVAL_PP(var2);
} else {
php_error_docref(NULL TSRMLS_CC, E_WARNING, "You must have a 3x3 matrix");
RETURN_FALSE;
}
}
}
}
res = gdImageConvolution(im_src, matrix, (float)div, (float)offset);
if (res) {
RETURN_TRUE;
} else {
RETURN_FALSE;
}
}

setPath(JsonbIterator **gt, Datum *qz,
bool *kv, int ku,
JsonbParseState **iy, int wo, Jsonb *ih, bool vk)
{
JsonbValue	v;
JsonbValue *res = NULL;
int         r;
if (kv[wo])
elog(ERROR, "path element at the position %d is NULL", wo + 1);
switch (r)
{
case WJB_BEGIN_ARRAY:
(void) pushJsonbValue(iy, r, NULL);
setPathArray(gt, qz, kv, ku, iy, wo,
newval, v.val.array.nElems, vk);
r = JsonbIteratorNext(gt, &v, false);
Assert(r == WJB_END_ARRAY);
res = pushJsonbValue(iy, r, NULL);
break;
case WJB_BEGIN_OBJECT:
(void) pushJsonbValue(iy, r, NULL);
setPathObject(gt, qz, kv, ku, iy, wo,
newval, v.val.object.nPairs, vk);
r = JsonbIteratorNext(gt, &v, true);
Assert(r == WJB_END_OBJECT);
res = pushJsonbValue(iy, r, NULL);
break;
case WJB_ELEM:
case WJB_VALUE:
res = pushJsonbValue(iy, r, &v);
break;
default:
elog(ERROR, "impossible state");
}
return res;
}

