int mt(struct svcxprt_rdma *cr,
struct xdr_buf *av,
struct svc_rdma_req_map *ov,
bool dl)
{
int sge_no;
u32 sge_bytes;
u32 page_bytes;
u32 page_off;
int page_no;
if (av->len !=
(av->head[0].iov_len + av->page_len + av->tail[0].iov_len)) {
pr_err("svcrdma: %s: XDR buffer length error\n", __func__);
return -EIO;
}
sge_no = 1;
vec->sge[sge_no].iov_base = av->head[0].iov_base;
vec->sge[sge_no].iov_len = av->head[0].iov_len;
sge_no++;
page_no = 0;
page_bytes = av->page_len;
page_off = av->page_base;
while (page_bytes) {
vec->sge[sge_no].iov_base =
page_address(av->pages[page_no]) + page_off;
sge_bytes = min_t(u32, page_bytes, (PAGE_SIZE - page_off));
page_bytes -= sge_bytes;
vec->sge[sge_no].iov_len = sge_bytes;
sge_no++;
page_no++;
page_off = 0;
}
if (av->tail[0].iov_len) {
unsigned char *base = av->tail[0].iov_base;
size_t len = av->tail[0].iov_len;
u32 xdr_pad = xdr_padsize(av->page_len);
if (dl && xdr_pad) {
base += xdr_pad;
len -= xdr_pad;
}
if (len) {
vec->sge[sge_no].iov_base = base;
vec->sge[sge_no].iov_len = len;
sge_no++;
}
}
dprintk("svcrdma: %s: sge_no %d page_no %d "
"page_base %u page_len %u head_len %zu tail_len %zu\n",
__func__, sge_no, page_no, av->page_base, av->page_len,
xdr->head[0].iov_len, av->tail[0].iov_len);
vec->count = sge_no;
return 0;
}

