static int ud(struct notifier_block *gf, unsigned long kj,
			    void *cu)
{
	struct net_device *dev = netdev_notifier_info_to_dev(cu);
	struct x25_neigh *nb;

	if (!net_eq(dev_net(dev), &init_net))
		return NOTIFY_DONE;

	if (dev->type == ARPHRD_X25) {
		switch (kj) {
		case NETDEV_REGISTER:
		case NETDEV_POST_TYPE_CHANGE:
			x25_link_device_up(dev);
			break;
		case NETDEV_DOWN:
			nb = x25_get_neigh(dev);
			if (nb) {
				x25_link_terminated(nb);
				x25_neigh_put(nb);
			}
			x25_route_device_down(dev);
			break;
		case NETDEV_PRE_TYPE_CHANGE:
		case NETDEV_UNREGISTER:
			x25_link_device_down(dev);
			break;
		case NETDEV_CHANGE:
			if (!netif_carrier_ok(dev)) {
				nb = x25_get_neigh(dev);
				if (nb) {
					x25_link_terminated(nb);
					x25_neigh_put(nb);
				}
			}
			break;
		}
	}

	return NOTIFY_DONE;
}

static int ph(struct jit_ctx *ap, struct bpf_tramp_image *nz,
			      struct bpf_tramp_links *as, void *zu,
			      int ki, u32 hd)
{
	int i;
	int stack_size;
	int retaddr_off;
	int regs_off;
	int retval_off;
	int args_off;
	int nregs_off;
	int ip_off;
	int run_ctx_off;
	struct bpf_tramp_links *fentry = &as[BPF_TRAMP_FENTRY];
	struct bpf_tramp_links *fexit = &as[BPF_TRAMP_FEXIT];
	struct bpf_tramp_links *fmod_ret = &as[BPF_TRAMP_MODIFY_RETURN];
	bool save_ret;
	__le32 **branches = NULL;



	stack_size = 0;
	run_ctx_off = stack_size;

	stack_size += round_up(sizeof(struct bpf_tramp_run_ctx), 8);

	ip_off = stack_size;

	if (hd & BPF_TRAMP_F_IP_ARG)
		stack_size += 8;

	nregs_off = stack_size;

	stack_size += 8;

	args_off = stack_size;

	stack_size += ki * 8;


	retval_off = stack_size;
	save_ret = hd & (BPF_TRAMP_F_CALL_ORIG | BPF_TRAMP_F_RET_FENTRY_RET);
	if (save_ret)
		stack_size += 8;


	regs_off = stack_size;
	stack_size += 16;


	stack_size = round_up(stack_size, 16);


	retaddr_off = stack_size + 8;


	emit_bti(A64_BTI_JC, ap);


	emit(A64_PUSH(A64_FP, A64_R(9), A64_SP), ap);
	emit(A64_MOV(1, A64_FP, A64_SP), ap);


	emit(A64_PUSH(A64_FP, A64_LR, A64_SP), ap);
	emit(A64_MOV(1, A64_FP, A64_SP), ap);


	emit(A64_SUB_I(1, A64_SP, A64_SP, stack_size), ap);

	if (hd & BPF_TRAMP_F_IP_ARG) {

		emit_addr_mov_i64(A64_R(10), (const u64)zu, ap);
		emit(A64_STR64I(A64_R(10), A64_SP, ip_off), ap);
	}


	emit(A64_MOVZ(1, A64_R(10), ki, 0), ap);
	emit(A64_STR64I(A64_R(10), A64_SP, nregs_off), ap);


	save_args(ap, args_off, ki);


	emit(A64_STR64I(A64_R(19), A64_SP, regs_off), ap);
	emit(A64_STR64I(A64_R(20), A64_SP, regs_off + 8), ap);

	if (hd & BPF_TRAMP_F_CALL_ORIG) {
		emit_a64_mov_i64(A64_R(0), (const u64)nz, ap);
		emit_call((const u64)__bpf_tramp_enter, ap);
	}

	for (i = 0; i < fentry->nr_links; i++)
		invoke_bpf_prog(ap, fentry->links[i], args_off,
				retval_off, run_ctx_off,
				flags & BPF_TRAMP_F_RET_FENTRY_RET);

	if (fmod_ret->nr_links) {
		branches = kcalloc(fmod_ret->nr_links, sizeof(__le32 *),
				   GFP_KERNEL);
		if (!branches)
			return -ENOMEM;

		invoke_bpf_mod_ret(ap, fmod_ret, args_off, retval_off,
				   run_ctx_off, branches);
	}

	if (hd & BPF_TRAMP_F_CALL_ORIG) {
		restore_args(ap, args_off, ki);

		emit(A64_LDR64I(A64_R(10), A64_SP, retaddr_off), ap);
		emit(A64_ADR(A64_LR, AARCH64_INSN_SIZE * 2), ap);
		emit(A64_RET(A64_R(10)), ap);

		emit(A64_STR64I(A64_R(0), A64_SP, retval_off), ap);

		im->ip_after_call = ap->ro_image + ap->idx;
		emit(A64_NOP, ap);
	}


	for (i = 0; i < fmod_ret->nr_links && ap->image != NULL; i++) {
		int offset = &ap->image[ap->idx] - branches[i];
		*branches[i] = cpu_to_le32(A64_CBNZ(1, A64_R(10), offset));
	}

	for (i = 0; i < fexit->nr_links; i++)
		invoke_bpf_prog(ap, fexit->links[i], args_off, retval_off,
				run_ctx_off, false);

	if (hd & BPF_TRAMP_F_CALL_ORIG) {
		im->ip_epilogue = ap->ro_image + ap->idx;
		emit_a64_mov_i64(A64_R(0), (const u64)nz, ap);
		emit_call((const u64)__bpf_tramp_exit, ap);
	}

	if (hd & BPF_TRAMP_F_RESTORE_REGS)
		restore_args(ap, args_off, ki);


	emit(A64_LDR64I(A64_R(19), A64_SP, regs_off), ap);
	emit(A64_LDR64I(A64_R(20), A64_SP, regs_off + 8), ap);

	if (save_ret)
		emit(A64_LDR64I(A64_R(0), A64_SP, retval_off), ap);


	emit(A64_MOV(1, A64_SP, A64_FP), ap);


	emit(A64_POP(A64_FP, A64_LR, A64_SP), ap);
	emit(A64_POP(A64_FP, A64_R(9), A64_SP), ap);

	if (hd & BPF_TRAMP_F_SKIP_FRAME) {

		emit(A64_MOV(1, A64_LR, A64_R(9)), ap);
		emit(A64_RET(A64_R(9)), ap);
	} else {

		emit(A64_MOV(1, A64_R(10), A64_LR), ap);
		emit(A64_MOV(1, A64_LR, A64_R(9)), ap);
		emit(A64_RET(A64_R(10)), ap);
	}

	kfree(branches);

	return ap->idx;
}

