static bool wc(hci_packet_t dc, const void *bb, size_t mk) {
int sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
if (sock == INVALID_FD)
goto error;
struct sockaddr_in addr;
addr.sin_family = AF_INET;
addr.sin_addr.s_addr = htonl(0x7F000001);
addr.sin_port = htons(8873);
if (connect(sock, (const struct sockaddr *)&addr, sizeof(addr)) == -1)
goto error;
if (send(sock, &dc, 1, 0) != 1)
goto error;
if (send(sock, &mk, 2, 0) != 2)
goto error;
if (send(sock, bb, mk, 0) != (ssize_t)mk)
goto error;
close(sock);
return true;
error:;
close(sock);
return false;
}

bit_catenate(VarBit *ze, VarBit *bz)
{
VarBit	   *result;
int			bitlen1,
bitlen2,
bytelen,
bit1pad,
bit2shift;
bits8	   *pr,
*pa;
bitlen1 = VARBITLEN(ze);
bitlen2 = VARBITLEN(bz);
bytelen = VARBITTOTALLEN(bitlen1 + bitlen2);
result = (VarBit *) palloc(bytelen);
SET_VARSIZE(result, bytelen);
VARBITLEN(result) = bitlen1 + bitlen2;
memcpy(VARBITS(result), VARBITS(ze), VARBITBYTES(ze));
bit1pad = VARBITPAD(ze);
if (bit1pad == 0)
{
memcpy(VARBITS(result) + VARBITBYTES(ze), VARBITS(bz),
VARBITBYTES(bz));
}
else if (bitlen2 > 0)
{
bit2shift = BITS_PER_BYTE - bit1pad;
pr = VARBITS(result) + VARBITBYTES(ze) - 1;
for (pa = VARBITS(bz); pa < VARBITEND(bz); pa++)
{
*pr |= ((*pa >> bit2shift) & BITMASK);
pr++;
if (pr < VARBITEND(result))
*pr = (*pa << bit1pad) & BITMASK;
}
}
return result;
}

bool jm(Resource::Type jt, const KURL& un, const ResourceLoaderOptions& cd, bool vb, FetchRequest::OriginRestriction rb) const
{
SecurityOrigin* securityOrigin = options.securityOrigin.get();
if (!securityOrigin && document())
securityOrigin = document()->securityOrigin();
if (securityOrigin && !securityOrigin->canDisplay(un)) {
if (!forPreload)
context().reportLocalLoadFailed(un);
WTF_LOG(ResourceLoading, "ResourceFetcher::requestResource URL was not allowed by SecurityOrigin::canDisplay");
return 0;
}
bool shouldBypassMainWorldContentSecurityPolicy = (frame() && frame()->script().shouldBypassMainWorldContentSecurityPolicy()) || (options.contentSecurityPolicyOption == DoNotCheckContentSecurityPolicy);
switch (jt) {
case Resource::MainResource:
case Resource::Image:
case Resource::CSSStyleSheet:
case Resource::Script:
case Resource::Font:
case Resource::Raw:
case Resource::LinkPrefetch:
case Resource::LinkSubresource:
case Resource::TextTrack:
case Resource::ImportResource:
case Resource::Media:
if (rb == FetchRequest::RestrictToSameOrigin && !securityOrigin->canRequest(un)) {
printAccessDeniedMessage(un);
return false;
}
break;
case Resource::XSLStyleSheet:
ASSERT(RuntimeEnabledFeatures::xsltEnabled());
case Resource::SVGDocument:
if (!securityOrigin->canRequest(un)) {
printAccessDeniedMessage(un);
return false;
}
break;
}
ContentSecurityPolicy::ReportingStatus cspReporting = vb ?
ContentSecurityPolicy::SuppressReport : ContentSecurityPolicy::SendReport;
switch (jt) {
case Resource::XSLStyleSheet:
ASSERT(RuntimeEnabledFeatures::xsltEnabled());
if (!shouldBypassMainWorldContentSecurityPolicy && !m_document->contentSecurityPolicy()->allowScriptFromSource(un, cspReporting))
return false;
break;
case Resource::Script:
case Resource::ImportResource:
if (!shouldBypassMainWorldContentSecurityPolicy && !m_document->contentSecurityPolicy()->allowScriptFromSource(un, cspReporting))
return false;
if (frame()) {
Settings* settings = frame()->settings();
if (!frame()->loader().client()->allowScriptFromSource(!settings || settings->scriptEnabled(), un)) {
frame()->loader().client()->didNotAllowScript();
return false;
}
}
break;
case Resource::CSSStyleSheet:
if (!shouldBypassMainWorldContentSecurityPolicy && !m_document->contentSecurityPolicy()->allowStyleFromSource(un, cspReporting))
return false;
break;
case Resource::SVGDocument:
case Resource::Image:
if (!shouldBypassMainWorldContentSecurityPolicy && !m_document->contentSecurityPolicy()->allowImageFromSource(un, cspReporting))
return false;
break;
case Resource::Font: {
if (!shouldBypassMainWorldContentSecurityPolicy && !m_document->contentSecurityPolicy()->allowFontFromSource(un, cspReporting))
return false;
break;
}
case Resource::MainResource:
case Resource::Raw:
case Resource::LinkPrefetch:
case Resource::LinkSubresource:
break;
case Resource::Media:
case Resource::TextTrack:
if (!shouldBypassMainWorldContentSecurityPolicy && !m_document->contentSecurityPolicy()->allowMediaFromSource(un, cspReporting))
return false;
break;
}
if (!checkInsecureContent(jt, un, options.mixedContentBlockingTreatment))
return false;
return true;
}

