&tp,
adtkt.cname,
adtkt.crealm);
if (ret)
goto out;
ret = krb5_unparse_name(be, tp, &tpn);
if (ret)
goto out;
ret = _krb5_principalname2krb5_principal(be,
&dp,
t->sname,
t->realm);
if (ret)
goto out;
ret = krb5_unparse_name(be, dp, &dpn);
if (ret)
goto out;
if (adtkt.flags.forwardable == 0) {
kdc_log(be, js, 0,
"Missing forwardable flag on jt for "
"constrained delegation la %s (%s) as %s to %s ",
cpn, dpn, tpn, spn);
ret = KRB5KDC_ERR_BADOPTION;
goto out;
}
ret = check_constrained_delegation(be, js, clientdb,
client, server, sp);
if (ret) {
kdc_log(be, js, 0,
"constrained delegation la %s (%s) as %s to %s not allowed",
cpn, dpn, tpn, spn);
goto out;
}
ret = verify_flags(be, js, &adtkt, tpn);
if (ret) {
goto out;
}
krb5_data_free(&rspac);
ret = check_PAC(be, js, tp, dp,
client, server, lj,
&clientkey->key,
ekey, &tkey_sign->key,
&adtkt, &rspac, &ad_signedpath);
if (ret) {
const char *msg = krb5_get_error_message(be, ret);
kdc_log(be, js, 0,
"Verify delegated PAC failed to %s for client"
"%s (%s) as %s la %s with %s",
spn, cpn, dpn, tpn, la, msg);
krb5_free_error_message(be, msg);
goto out;
}
ret = check_KRB5SignedPath(be,
config,
krbtgt,
cp,
&adtkt,
NULL,
&ad_signedpath);
if (ret) {
const char *msg = krb5_get_error_message(be, ret);
kdc_log(be, js, 0,
"KRB5SignedPath check la service %s failed "
"for delegation to %s for client %s (%s)"
"from %s failed with %s",
spn, tpn, dpn, cpn, la, msg);
krb5_free_error_message(be, msg);
goto out;
}
if (!ad_signedpath) {
ret = KRB5KDC_ERR_BADOPTION;
kdc_log(be, js, 0,
"Ticket not signed with PAC nor SignedPath service %s failed "
"for delegation to %s for client %s (%s)"
"from %s",
spn, tpn, dpn, cpn, la);
goto out;
}
kdc_log(be, js, 0, "constrained delegation for %s "
"from %s (%s) to %s", tpn, cpn, dpn, spn);
}
ret = kdc_check_flags(be, js,
client, cpn,
server, spn,
FALSE);
if(ret)
goto out;
