PA_DATA pa;
krb5_crypto crypto;
kdc_log(be, js, 0,
"Adding server referral to %s", ref_realm);
ret = krb5_crypto_init(be, &sessionkey, 0, &crypto);
if (ret)
goto out;
ret = build_server_referral(be, js, crypto, ref_realm,
NULL, s, &pa.padata_value);
krb5_crypto_destroy(be, crypto);
if (ret) {
kdc_log(be, js, 0,
"Failed building server referral");
goto out;
}
pa.padata_type = KRB5_PADATA_SERVER_REFERRAL;
ret = add_METHOD_DATA(&enc_pa_data, &pa);
krb5_data_free(&pa.padata_value);
if (ret) {
kdc_log(be, js, 0,
"Add server referral METHOD-DATA failed");
goto out;
}
}
ret = tgs_make_reply(be,
config,
b,
tp,
tgt,
replykey,
rk_is_subkey,
ekey,
&sessionkey,
kvno,
*vv,
server,
rsp,
spn,
client,
cp,
krbtgt_out,
tkey_sign->key.keytype,
spp,
&rspac,
&enc_pa_data,
e_text,
reply);
out:
if (tpn != cpn)
free(tpn);
free(spn);
free(cpn);
free(dpn);
free(krbtgt_out_n);
_krb5_free_capath(be, capath);
krb5_data_free(&rspac);
krb5_free_keyblock_contents(be, &sessionkey);
if(krbtgt_out)
_kdc_free_ent(be, krbtgt_out);
if(server)
_kdc_free_ent(be, server);
if(client)
_kdc_free_ent(be, client);
if(s4u2self_impersonated_client)
