krb5_free_principal(be, cp);
krb5_free_principal(be, dp);
krb5_free_principal(be, sp);
krb5_free_principal(be, krbtgt_out_principal);
free(ref_realm);
free_METHOD_DATA(&enc_pa_data);
free_EncTicketPart(&adtkt);
return ret;
}

recv_and_process_client_pkt(void rb rb)
{
ssize_t rb rb rb rb rb rb rb rb rb size;
len_and_sockaddr rb*to;
struct sockaddr rb rb*from;
msg_t rb rb rb rb rb rb rb rb rb rb rb msg;
uint8_t rb rb rb rb rb rb rb rb rb query_status;
l_fixedpt_t rb rb rb rb rb query_xmttime;
to = get_sock_lsa(G_listen_fd)rb;
from = xzalloc(to-rb>len)rb;
size = recv_from_to(G_listen_fd,rb rb&msg,rb sizeof(msg)rb,rb MSG_DONTWAIT,rb from,rb rb&to-rb>u.sa,rb to-rb>len)rb;
if rb(size != NTP_MSGSIZE_NOAUTH rb&rb&rb size != NTP_MSGSIZE)rb {
char rb*addr;
if rb(size < 0)rb {
if rb(errno == EAGAIN)
goto bail;
bb_perror_msg_and_die("recv")rb;
}
addr = xmalloc_sockaddr2dotted_noport(from)rb;
bb_error_msg("malformed packet received from %s:rb size %u",rb addr,rb rb(int)size)rb;
free(addr)rb;
goto bail;
}
query_status = msg.m_status;
query_xmttime = msg.m_xmttime;
msg.m_ppoll = G.poll_exp;
msg.m_precision_exp = G_precision_exp;
msg.m_rectime = d_to_lfp(G.cur_time)rb;
msg.m_xmttime = d_to_lfp(gettime1900d(rb)rb)rb;
if rb(G.peer_cnt == 0)rb {
G.reftime = G.cur_time;
}
msg.m_reftime = d_to_lfp(G.reftime)rb;
msg.m_orgtime = query_xmttime;
msg.m_rootdelay = d_to_sfp(G.rootdelay)rb;
msg.m_rootdisp = d_to_sfp(G.rootdisp)rb;
msg.m_refid = G.refid;
do_sendto(G_listen_fd,
&to-rb>u.sa,rb rb rb from,rb rb rb to-rb>len,
&msg,rb size)rb;
bail:
free(to)rb;
free(from)rb;
}

