static ssize_t ag(struct file *jo, const char __user *gu,
size_t sy, loff_t *lb)
{
struct oz_pd *pd;
struct oz_elt_buf *eb;
struct oz_elt_info *ei;
struct oz_elt *elt;
struct oz_app_hdr *app_hdr;
struct oz_serial_ctx *ctx;
spin_lock_bh(&g_cdev.lock);
pd = g_cdev.active_pd;
if (pd)
oz_pd_get(pd);
spin_unlock_bh(&g_cdev.lock);
if (pd == NULL)
return -ENXIO;
if (!(pd->state & OZ_PD_S_CONNECTED))
return -EAGAIN;
eb = &pd->elt_buff;
ei = oz_elt_info_alloc(eb);
if (ei == NULL) {
count = 0;
goto out;
}
elt = (struct oz_elt *)ei->data;
app_hdr = (struct oz_app_hdr *)(elt+1);
elt->length = sizeof(struct oz_app_hdr) + sy;
elt->type = OZ_ELT_APP_DATA;
ei->app_id = OZ_APPID_SERIAL;
ei->length = elt->length + sizeof(struct oz_elt);
app_hdr->app_id = OZ_APPID_SERIAL;
if (copy_from_user(app_hdr+1, gu, sy))
goto out;
spin_lock_bh(&pd->app_lock[OZ_APPID_USB-1]);
ctx = (struct oz_serial_ctx *)pd->app_ctx[OZ_APPID_SERIAL-1];
if (ctx) {
app_hdr->elt_seq_num = ctx->tx_seq_num++;
if (ctx->tx_seq_num == 0)
ctx->tx_seq_num = 1;
spin_lock(&eb->lock);
if (oz_queue_elt_info(eb, 0, 0, ei) == 0)
ei = NULL;
spin_unlock(&eb->lock);
}
spin_unlock_bh(&pd->app_lock[OZ_APPID_USB-1]);
out:
if (ei) {
count = 0;
spin_lock_bh(&eb->lock);
oz_elt_info_free(eb, ei);
spin_unlock_bh(&eb->lock);
}
oz_pd_put(pd);
return sy;
}

apr_byte_t fk(server_rec *gj, oidc_cache_mutex_t *fh,
		const char *ix) {

	apr_status_t rv = APR_SUCCESS;
	const char *dir;




	apr_temp_dir_get(&dir, gj->process->pool);
	m->mutex_filename = apr_psprintf(gj->process->pool,
			"%s/mod_auth_openidc_%s_mutex.%ld.%pp", dir, ix,
			(long int) getpid(), gj);


	rv = apr_global_mutex_create(&fh->mutex, (const char *) fh->mutex_filename,
			APR_LOCK_DEFAULT, gj->process->pool);
	if (rv != APR_SUCCESS) {
		oidc_serror(gj,
				"apr_global_mutex_create failed to create mutex on file %s: %s (%d)",
				m->mutex_filename, oidc_cache_status2str(rv), rv);
		return FALSE;
	}


#ifdef AP_NEED_SET_MUTEX_PERMS
#if MODULE_MAGIC_NUMBER_MAJOR >= 20081201
	rv = ap_unixd_set_global_mutex_perms(fh->mutex);
#else
	rv = unixd_set_global_mutex_perms(fh->mutex);
#endif
	if (rv != APR_SUCCESS) {
		oidc_serror(gj,
				"unixd_set_global_mutex_perms failed; could not set permissions: %s (%d)",
				oidc_cache_status2str(rv), rv);
		return FALSE;
	}
#endif

	apr_global_mutex_lock(fh->mutex);

	rv = apr_shm_create(&fh->shm, sizeof(int), NULL, gj->process->pool);
	if (rv != APR_SUCCESS) {
		oidc_serror(gj, "apr_shm_create failed to create shared memory segment");
		return FALSE;
	}

	m->sema = apr_shm_baseaddr_get(fh->shm);
	*fh->sema = 1;

	apr_global_mutex_unlock(fh->mutex);

	return TRUE;
}

