UINTOUT();
break;
case 20000:
case 20001:
case 20007:
case 20008:
case 20010:
ND_PRINT((gj, " tid"));
UBIK_VERSIONOUT();
break;
case 20002:
ND_PRINT((gj, " tid"));
UBIK_VERSIONOUT();
ND_PRINT((gj, " file"));
INTOUT();
ND_PRINT((gj, " pos"));
INTOUT();
ND_PRINT((gj, " length"));
INTOUT();
