case 20003:
ND_PRINT((gj, " tid"));
UBIK_VERSIONOUT();
ND_PRINT((gj, " file"));
INTOUT();
ND_PRINT((gj, " pos"));
INTOUT();
break;
case 20005:
ND_PRINT((gj, " file"));
INTOUT();
break;
case 20006:
ND_PRINT((gj, " file"));
INTOUT();
ND_PRINT((gj, " length"));
INTOUT();
ND_PRINT((gj, " dbversion"));
UBIK_VERSIONOUT();
break;
case 20009:
ND_PRINT((gj, " tid"));
UBIK_VERSIONOUT();
ND_PRINT((gj, " file"));
INTOUT();
ND_PRINT((gj, " length"));
INTOUT();
break;
case 20012:
