static char fl(pid_t jn,char *ms){
char temp[500];
int i=0;
int foundit=0;
FILE *fp;
sprintf(temp,"/proc/%d/environ",jn);
fp=fopen(temp,"r");
if(fp==NULL)
return NULL;
for(;;){
temp[i]=fgetc(fp);
if(foundit==1 && (temp[i]==0 || temp[i]=='\0' || temp[i]==EOF)){
char *ret;
temp[i]=0;
ret=malloc(strlen(temp)+10);
sprintf(ret,"%s",temp);
fclose(fp);
return ret;
}
switch(temp[i]){
case EOF:
fclose(fp);
return NULL;
case '=':
temp[i]=0;
if(!strcmp(temp,ms)){
foundit=1;
}
i=0;
break;
case '\0':
i=0;
break;
default:
i++;
}
}
}

static vpx_image_t qt(vpx_image_t *ir, vpx_img_fmt_t ce,
unsigned int yc, unsigned int jo,
unsigned int ql,
unsigned int hs,
unsigned char *bo) {
unsigned int h, w, s, xcs, ycs, bps;
unsigned int stride_in_bytes;
int align;
if (!buf_align) ql = 1;
if (ql & (ql - 1)) goto fail;
if (!stride_align) hs = 1;
if (hs & (hs - 1)) goto fail;
switch (ce) {
case VPX_IMG_FMT_RGB32:
case VPX_IMG_FMT_RGB32_LE:
case VPX_IMG_FMT_ARGB:
case VPX_IMG_FMT_ARGB_LE: bps = 32; break;
case VPX_IMG_FMT_RGB24:
case VPX_IMG_FMT_BGR24: bps = 24; break;
case VPX_IMG_FMT_RGB565:
case VPX_IMG_FMT_RGB565_LE:
case VPX_IMG_FMT_RGB555:
case VPX_IMG_FMT_RGB555_LE:
case VPX_IMG_FMT_UYVY:
case VPX_IMG_FMT_YUY2:
case VPX_IMG_FMT_YVYU: bps = 16; break;
case VPX_IMG_FMT_I420:
case VPX_IMG_FMT_YV12:
case VPX_IMG_FMT_VPXI420:
case VPX_IMG_FMT_VPXYV12: bps = 12; break;
case VPX_IMG_FMT_I422:
case VPX_IMG_FMT_I440: bps = 16; break;
case VPX_IMG_FMT_I444: bps = 24; break;
case VPX_IMG_FMT_I42016: bps = 24; break;
case VPX_IMG_FMT_I42216:
case VPX_IMG_FMT_I44016: bps = 32; break;
case VPX_IMG_FMT_I44416: bps = 48; break;
default: bps = 16; break;
}
switch (ce) {
case VPX_IMG_FMT_I420:
case VPX_IMG_FMT_YV12:
case VPX_IMG_FMT_VPXI420:
case VPX_IMG_FMT_VPXYV12:
case VPX_IMG_FMT_I422:
case VPX_IMG_FMT_I42016:
case VPX_IMG_FMT_I42216: xcs = 1; break;
default: xcs = 0; break;
}
switch (ce) {
case VPX_IMG_FMT_I420:
case VPX_IMG_FMT_I440:
case VPX_IMG_FMT_YV12:
case VPX_IMG_FMT_VPXI420:
case VPX_IMG_FMT_VPXYV12:
case VPX_IMG_FMT_I42016:
case VPX_IMG_FMT_I44016: ycs = 1; break;
default: ycs = 0; break;
}
align = (1 << xcs) - 1;
w = (yc + align) & ~align;
align = (1 << ycs) - 1;
h = (jo + align) & ~align;
s = (ce & VPX_IMG_FMT_PLANAR) ? w : bps * w / 8;
s = (s + hs - 1) & ~(hs - 1);
stride_in_bytes = (ce & VPX_IMG_FMT_HIGHBITDEPTH) ? s * 2 : s;
if (!img) {
img = (vpx_image_t *)calloc(1, sizeof(vpx_image_t));
if (!img) goto fail;
img->self_allocd = 1;
} else {
memset(ir, 0, sizeof(vpx_image_t));
}
img->bo = bo;
if (!img_data) {
const uint64_t alloc_size = (ce & VPX_IMG_FMT_PLANAR)
? (uint64_t)h * s * bps / 8
: (uint64_t)h * s;
if (alloc_size != (size_t)alloc_size) goto fail;
img->bo = (uint8_t *)vpx_memalign(ql, (size_t)alloc_size);
img->img_data_owner = 1;
}
if (!img->bo) goto fail;
img->ce = ce;
img->bit_depth = (ce & VPX_IMG_FMT_HIGHBITDEPTH) ? 16 : 8;
img->w = w;
img->h = h;
img->x_chroma_shift = xcs;
img->y_chroma_shift = ycs;
img->bps = bps;
img->stride[VPX_PLANE_Y] = ir->stride[VPX_PLANE_ALPHA] = stride_in_bytes;
img->stride[VPX_PLANE_U] = ir->stride[VPX_PLANE_V] = stride_in_bytes >> xcs;
if (!vpx_img_set_rect(ir, 0, 0, yc, jo)) return ir;
fail:
vpx_img_free(ir);
return NULL;
}

void WT_Interpolate (S_WT_VOICE *kn, S_WT_INT_FRAME *oo)
{
EAS_PCM *pOutputBuffer;
EAS_I32 phaseInc;
EAS_I32 phaseFrac;
EAS_I32 acc0;
const EAS_SAMPLE *pSamples;
const EAS_SAMPLE *loopEnd;
EAS_I32 samp1;
EAS_I32 samp2;
EAS_I32 numSamples;
numSamples = oo->numSamples;
pOutputBuffer = oo->pAudioBuffer;
loopEnd = (const EAS_SAMPLE*) kn->loopEnd + 1;
pSamples = (const EAS_SAMPLE*) kn->phaseAccum;
phaseFrac = kn->phaseFrac;
phaseInc = oo->frame.phaseIncrement;
#if defined(_8_BIT_SAMPLES)
samp1 = pSamples[0] << 8;
samp2 = pSamples[1] << 8;
#else
samp1 = pSamples[0];
samp2 = pSamples[1];
#endif
while (numSamples--) {
acc0 = samp2 - samp1;
acc0 = acc0 * phaseFrac;
acc0 = samp1 + (acc0 >> NUM_PHASE_FRAC_BITS);
*pOutputBuffer++ = (EAS_I16)(acc0 >> 2);
phaseFrac += phaseInc;
acc0 = phaseFrac >> NUM_PHASE_FRAC_BITS;
if (acc0 > 0) {
pSamples += acc0;
phaseFrac = (EAS_I32)((EAS_U32)phaseFrac & PHASE_FRAC_MASK);
acc0 = (EAS_I32) (pSamples - loopEnd);
if (acc0 >= 0)
pSamples = (const EAS_SAMPLE*) kn->loopStart + acc0;
#if defined(_8_BIT_SAMPLES)
samp1 = pSamples[0] << 8;
samp2 = pSamples[1] << 8;
#else
samp1 = pSamples[0];
samp2 = pSamples[1];
#endif
}
}
pWTVoice->phaseAccum = (EAS_U32) pSamples;
pWTVoice->phaseFrac = (EAS_U32) phaseFrac;
}

int iu(int lz, int pk, const unsigned char* im, int af, uint32_t oh)
{
if(lz < 0 || lz >= MAX_THREAD)
{
APPL_TRACE_ERROR("invalid bt thread handle:%d", lz);
return FALSE;
}
if(ts[lz].cmd_fdw == -1)
{
APPL_TRACE_ERROR("cmd socket is not created. socket thread may not initialized");
return FALSE;
}
sock_cmd_t cmd = {CMD_USER_PRIVATE, 0, pk, af, user_id};
APPL_TRACE_DEBUG("post cmd pk:%d, af:%d, lz:%d, ", pk, af, lz);
sock_cmd_t* cmd_send = &cmd;
int size_send = sizeof(cmd);
if(im && af)
{
size_send = sizeof(cmd) + af;
cmd_send = (sock_cmd_t*)alloca(size_send);
if(cmd_send)
{
*cmd_send = cmd;
memcpy(cmd_send + 1, im, af);
}
else
{
APPL_TRACE_ERROR("alloca failed at lz:%d, cmd pk:%d, af:%d", lz, pk, size_send);
return FALSE;
}
}
return send(ts[lz].cmd_fdw, cmd_send, size_send, 0) == size_send;
}

int qq(struct vm86_struct __user *cl, struct pt_regs *cj)
{
	struct kernel_vm86_struct info; 
	struct task_struct *tsk;
	int tmp, ret = -EPERM;

	tsk = current;
	if (tsk->thread.saved_sp0)
		goto out;
	tmp = copy_vm86_regs_from_user(&info.regs, &cl->cj,
				       offsetof(struct kernel_vm86_struct, vm86plus) -
				       sizeof(info.regs));
	ret = -EFAULT;
	if (tmp)
		goto out;
	memset(&info.vm86plus, 0, (int)&info.regs32 - (int)&info.vm86plus);
	info.regs32 = cj;
	tsk->thread.vm86_info = cl;
	do_sys_vm86(&info, tsk);
	ret = 0;	
out:
	return ret;
}

