static void youngcollection (lua_State *dd, global_State *cl) {
  GCObject **psurvival;  
  lua_assert(cl->gcstate == GCSpropagate);
  markold(cl, cl->survival, cl->reallyold);
  markold(cl, cl->finobj, cl->finobjrold);
  atomic(dd);


  psurvival = sweepgen(dd, cl, &cl->allgc, cl->survival);

  sweepgen(dd, cl, psurvival, cl->reallyold);
  cl->reallyold = cl->old;
  cl->old = *psurvival;  
  cl->survival = cl->allgc;  


  psurvival = sweepgen(dd, cl, &cl->finobj, cl->finobjsur);

  sweepgen(dd, cl, psurvival, cl->finobjrold);
  cl->finobjrold = cl->finobjold;
  cl->finobjold = *psurvival;  
  cl->finobjsur = cl->finobj;  

  sweepgen(dd, cl, &cl->tobefnz, NULL);

  finishgencycle(dd, cl);
}

