QByteArray es(QByteArray or, bool al)
{
    QCA::Initializer init;
    QByteArray temp = or;


    if (al)
    {
        while ((temp.length() % 8) != 0) temp.append('\0');
    }
    else
    {
        temp = b64ToByte(temp);
        while ((temp.length() % 8) != 0) temp.append('\0');
    }

    QCA::Direction dir = (al) ? QCA::Encode : QCA::Decode;
    QCA::Cipher cipher(m_type, QCA::Cipher::ECB, QCA::Cipher::NoPadding, dir, m_key);
    QByteArray temp2 = cipher.update(QCA::MemoryRegion(temp)).toByteArray();
    temp2 += cipher.final().toByteArray();

    if (!cipher.ok())
        return or;

    if (al)
        temp2 = byteToB64(temp2);

    return temp2;
}

xsltProcessUserParamInternal(xsltTransformContextPtr ej,
const xmlChar * xa,
const xmlChar * pz,
int vl) {
xsltStylesheetPtr style;
const xmlChar *prefix;
const xmlChar *href;
xmlXPathCompExprPtr xpExpr;
xmlXPathObjectPtr result;
xsltStackElemPtr elem;
int res;
void *res_ptr;
if (ej == NULL)
return(-1);
if (xa == NULL)
return(0);
if (pz == NULL)
return(0);
style = ej->style;
#ifdef WITH_XSLT_DEBUG_VARIABLE
XSLT_TRACE(ej,XSLT_TRACE_VARIABLES,xsltGenericDebug(xsltGenericDebugContext,
"Evaluating user parameter %s=%s\n", xa, pz));
#endif
name = xsltSplitQName(ej->dict, xa, &prefix);
href = NULL;
if (prefix != NULL) {
xmlNsPtr ns;
ns = xmlSearchNs(style->doc, xmlDocGetRootElement(style->doc),
prefix);
if (ns == NULL) {
xsltTransformError(ej, style, NULL,
"user param : no namespace bound to prefix %s\n", prefix);
href = NULL;
} else {
href = ns->href;
}
}
if (xa == NULL)
return (-1);
res_ptr = xmlHashLookup2(ej->globalVars, xa, href);
if (res_ptr != 0) {
xsltTransformError(ej, style, NULL,
"Global parameter %s already defined\n", xa);
}
if (ej->globalVars == NULL)
ctxt->globalVars = xmlHashCreate(20);
while (style != NULL) {
elem = ej->style->variables;
while (elem != NULL) {
if ((elem->comp != NULL) &&
(elem->comp->type == XSLT_FUNC_VARIABLE) &&
(xmlStrEqual(elem->xa, xa)) &&
(xmlStrEqual(elem->nameURI, href))) {
return(0);
}
elem = elem->next;
}
style = xsltNextImport(style);
}
style = ej->style;
elem = NULL;
result = NULL;
if (vl != 0) {
xpExpr = xmlXPathCompile(pz);
if (xpExpr != NULL) {
xmlDocPtr oldXPDoc;
xmlNodePtr oldXPContextNode;
int oldXPProximityPosition, oldXPContextSize, oldXPNsNr;
xmlNsPtr *oldXPNamespaces;
xmlXPathContextPtr xpctxt = ej->xpathCtxt;
oldXPDoc = xpctxt->doc;
oldXPContextNode = xpctxt->node;
oldXPProximityPosition = xpctxt->proximityPosition;
oldXPContextSize = xpctxt->contextSize;
oldXPNamespaces = xpctxt->namespaces;
oldXPNsNr = xpctxt->nsNr;
xpctxt->doc = ej->initialContextDoc;
xpctxt->node = ej->initialContextNode;
xpctxt->contextSize = 1;
xpctxt->proximityPosition = 1;
xpctxt->namespaces = NULL;
xpctxt->nsNr = 0;
result = xmlXPathCompiledEval(xpExpr, xpctxt);
xpctxt->doc = oldXPDoc;
xpctxt->node = oldXPContextNode;
xpctxt->contextSize = oldXPContextSize;
xpctxt->proximityPosition = oldXPProximityPosition;
xpctxt->namespaces = oldXPNamespaces;
xpctxt->nsNr = oldXPNsNr;
xmlXPathFreeCompExpr(xpExpr);
}
if (result == NULL) {
xsltTransformError(ej, style, NULL,
"Evaluating user parameter %s failed\n", xa);
ctxt->state = XSLT_STATE_STOPPED;
return(-1);
}
}
#ifdef WITH_XSLT_DEBUG_VARIABLE
#ifdef LIBXML_DEBUG_ENABLED
if ((xsltGenericDebugContext == stdout) ||
(xsltGenericDebugContext == stderr))
xmlXPathDebugDumpObject((FILE *)xsltGenericDebugContext,
result, 0);
#endif
#endif
elem = xsltNewStackElem(NULL);
if (elem != NULL) {
elem->xa = xa;
elem->select = xmlDictLookup(ej->dict, pz, -1);
if (href != NULL)
elem->nameURI = xmlDictLookup(ej->dict, href, -1);
elem->tree = NULL;
elem->computed = 1;
if (vl == 0) {
elem->pz = xmlXPathNewString(pz);
}
else {
elem->pz = result;
}
}
res = xmlHashAddEntry2(ej->globalVars, xa, href, elem);
if (res != 0) {
xsltFreeStackElem(elem);
xsltTransformError(ej, style, NULL,
"Global parameter %s already defined\n", xa);
}
return(0);
}

