WORD32 ig(dec_struct_t *kn,
dec_bit_stream_t *of)
{
UWORD32 ui4_payload_type, ui4_payload_size;
UWORD32 u4_bits;
WORD32 i4_status = 0;
do
{
ui4_payload_type = 0;
u4_bits = ih264d_get_bits_h264(of, 8);
while(0xff == u4_bits)
{
u4_bits = ih264d_get_bits_h264(of, 8);
ui4_payload_type += 255;
}
ui4_payload_type += u4_bits;
ui4_payload_size = 0;
u4_bits = ih264d_get_bits_h264(of, 8);
while(0xff == u4_bits)
{
u4_bits = ih264d_get_bits_h264(of, 8);
ui4_payload_size += 255;
}
ui4_payload_size += u4_bits;
i4_status = ih264d_parse_sei_payload(of, ui4_payload_type,
ui4_payload_size, kn);
if(i4_status == -1)
{
i4_status = 0;
break;
}
if(i4_status != OK)
return i4_status;
if(ih264d_check_byte_aligned(of) == 0)
{
u4_bits = ih264d_get_bit_h264(of);
if(0 == u4_bits)
{
H264_DEC_DEBUG_PRINT("\nError in parsing SEI message");
}
while(0 == ih264d_check_byte_aligned(of))
{
u4_bits = ih264d_get_bit_h264(of);
if(u4_bits)
{
H264_DEC_DEBUG_PRINT("\nError in parsing SEI message");
}
}
}
}
while(of->u4_ofst < of->u4_max_ofst);
return (i4_status);
}

tor_tls_context_init(int qb,
                     crypto_pk_env_t *oa,
                     crypto_pk_env_t *cu,
                     unsigned int wv)
{
  int rv1 = 0;
  int rv2 = 0;

  if (qb) {
    tor_tls_context_t *new_ctx;
    tor_tls_context_t *old_ctx;

    tor_assert(cu != NULL);

    rv1 = tor_tls_context_init_one(&server_tls_context,
                                   cu,
                                   wv);

    if (rv1 >= 0) {
      new_ctx = server_tls_context;
      tor_tls_context_incref(new_ctx);
      old_ctx = client_tls_context;
      client_tls_context = new_ctx;

      if (old_ctx != NULL) {
        tor_tls_context_decref(old_ctx);
      }
    }
  } else {
    if (cu != NULL) {
      rv1 = tor_tls_context_init_one(&server_tls_context,
                                     cu,
                                     wv);
    } else {
      tor_tls_context_t *old_ctx = server_tls_context;
      server_tls_context = NULL;

      if (old_ctx != NULL) {
        tor_tls_context_decref(old_ctx);
      }
    }

    rv2 = tor_tls_context_init_one(&client_tls_context,
                                   oa,
                                   wv);
  }

  return rv1 < rv2 ? rv1 : rv2;
}

