ikev2_ID_print(netdissect_options *at, u_char df,
const struct isakmp_gen *jd,
u_int item_len rx, const u_char *ep rx,
uint32_t phase rx, uint32_t doi rx,
uint32_t proto rx, int depth rx)
{
struct ikev2_id id;
int id_len, idtype_len, i;
unsigned int dumpascii, dumphex;
const unsigned char *typedata;
ND_TCHECK(*jd);
UNALIGNED_MEMCPY(&id, jd, sizeof(id));
ikev2_pay_print(at, NPSTR(df), id.h.critical);
id_len = ntohs(id.h.len);
ND_PRINT((at," len=%d", id_len - 4));
if (2 < at->ndo_vflag && 4 < id_len) {
ND_PRINT((at," "));
if (!rawprint(at, (const uint8_t *)(jd + 1), id_len - 4))
goto trunc;
}
idtype_len =id_len - sizeof(struct ikev2_id);
dumpascii = 0;
dumphex   = 0;
typedata  = (const unsigned char *)(jd)+sizeof(struct ikev2_id);
switch(id.type) {
case ID_IPV4_ADDR:
ND_PRINT((at, " ipv4:"));
dumphex=1;
break;
case ID_FQDN:
ND_PRINT((at, " fqdn:"));
dumpascii=1;
break;
case ID_RFC822_ADDR:
ND_PRINT((at, " rfc822:"));
dumpascii=1;
break;
case ID_IPV6_ADDR:
ND_PRINT((at, " ipv6:"));
dumphex=1;
break;
case ID_DER_ASN1_DN:
ND_PRINT((at, " dn:"));
dumphex=1;
break;
case ID_DER_ASN1_GN:
ND_PRINT((at, " gn:"));
dumphex=1;
break;
case ID_KEY_ID:
ND_PRINT((at, " keyid:"));
dumphex=1;
break;
}
if(dumpascii) {
ND_TCHECK2(*typedata, idtype_len);
for(i=0; i<idtype_len; i++) {
if(ND_ISPRINT(typedata[i])) {
ND_PRINT((at, "%c", typedata[i]));
} else {
ND_PRINT((at, "."));
}
}
}
if(dumphex) {
if (!rawprint(at, (const uint8_t *)typedata, idtype_len))
goto trunc;
}
return (const u_char *)jd + id_len;
trunc:
ND_PRINT((at," [|%s]", NPSTR(df)));
return NULL;
}

