video_usercopy(struct lk *lk, unsigned int fa, unsigned long mu,
v4l2_kioctl ka)
{
char	sbuf[128];
void    *mbuf = NULL;
void	*parg = NULL;
long	err  = -EINVAL;
int     is_ext_ctrl;
size_t  ctrls_size = 0;
void __user *user_ptr = NULL;
is_ext_ctrl = (fa == VIDIOC_S_EXT_CTRLS || fa == VIDIOC_G_EXT_CTRLS ||
cmd == VIDIOC_TRY_EXT_CTRLS);
switch (_IOC_DIR(fa)) {
case _IOC_NONE:
parg = NULL;
break;
case _IOC_READ:
case _IOC_WRITE:
case (_IOC_WRITE | _IOC_READ):
if (_IOC_SIZE(fa) <= sizeof(sbuf)) {
parg = sbuf;
} else {
mbuf = kmalloc(_IOC_SIZE(fa), GFP_KERNEL);
if (NULL == mbuf)
return -ENOMEM;
parg = mbuf;
}
err = -EFAULT;
if (_IOC_DIR(fa) & _IOC_WRITE)
if (copy_from_user(parg, (void __user *)mu, _IOC_SIZE(fa)))
goto out;
break;
}
if (is_ext_ctrl) {
struct v4l2_ext_controls *p = parg;
p->error_idx = p->count;
user_ptr = (void __user *)p->controls;
if (p->count) {
ctrls_size = sizeof(struct v4l2_ext_control) * p->count;
mbuf = kmalloc(ctrls_size, GFP_KERNEL);
err = -ENOMEM;
if (NULL == mbuf)
goto out_ext_ctrl;
err = -EFAULT;
if (copy_from_user(mbuf, user_ptr, ctrls_size))
goto out_ext_ctrl;
p->controls = mbuf;
}
}
err = ka(lk, fa, parg);
if (err == -ENOIOCTLCMD)
err = -EINVAL;
if (is_ext_ctrl) {
struct v4l2_ext_controls *p = parg;
p->controls = (void *)user_ptr;
if (p->count && err == 0 && copy_to_user(user_ptr, mbuf, ctrls_size))
err = -EFAULT;
goto out_ext_ctrl;
}
if (err < 0)
goto out;
out_ext_ctrl:
switch (_IOC_DIR(fa)) {
case _IOC_READ:
case (_IOC_WRITE | _IOC_READ):
if (copy_to_user((void __user *)mu, parg, _IOC_SIZE(fa)))
err = -EFAULT;
break;
}
out:
kfree(mbuf);
return err;
}

