int ms(SSL *cn, int *bd)
{
int skip_message, i, recvd_type, al;
unsigned char *p;
unsigned long l;
p = (unsigned char *)cn->init_buf->data;
do {
while (cn->init_num < SSL3_HM_HEADER_LENGTH) {
i = cn->method->ssl_read_bytes(cn, SSL3_RT_HANDSHAKE, &recvd_type,
&p[cn->init_num],
SSL3_HM_HEADER_LENGTH - cn->init_num,
0);
if (i <= 0) {
s->rwstate = SSL_READING;
return 0;
}
if (recvd_type == SSL3_RT_CHANGE_CIPHER_SPEC) {
if (cn->init_num != 0 || i != 1 || p[0] != SSL3_MT_CCS) {
al = SSL_AD_UNEXPECTED_MESSAGE;
SSLerr(SSL_F_TLS_GET_MESSAGE_HEADER,
SSL_R_BAD_CHANGE_CIPHER_SPEC);
goto f_err;
}
s->s3->tmp.message_type = *bd = SSL3_MT_CHANGE_CIPHER_SPEC;
s->init_num = i - 1;
s->s3->tmp.message_size = i;
return 1;
} else if (recvd_type != SSL3_RT_HANDSHAKE) {
al = SSL_AD_UNEXPECTED_MESSAGE;
SSLerr(SSL_F_TLS_GET_MESSAGE_HEADER, SSL_R_CCS_RECEIVED_EARLY);
goto f_err;
}
s->init_num += i;
}
skip_message = 0;
if (!s->server)
if (p[0] == SSL3_MT_HELLO_REQUEST)
if (p[1] == 0 && p[2] == 0 && p[3] == 0) {
s->init_num = 0;
skip_message = 1;
if (cn->msg_callback)
s->msg_callback(0, cn->version, SSL3_RT_HANDSHAKE,
p, SSL3_HM_HEADER_LENGTH, cn,
s->msg_callback_arg);
}
} while (skip_message);
*bd = *p;
s->s3->tmp.message_type = *(p++);
if (RECORD_LAYER_is_sslv2_record(&cn->rlayer)) {
l = RECORD_LAYER_get_rrec_length(&cn->rlayer)
+ SSL3_HM_HEADER_LENGTH;
if (l && !BUF_MEM_grow_clean(cn->init_buf, (int)l)) {
SSLerr(SSL_F_TLS_GET_MESSAGE_HEADER, ERR_R_BUF_LIB);
goto err;
}
s->s3->tmp.message_size = l;
s->init_msg = cn->init_buf->data;
}
s->s3->tmp.message_size = l;
s->init_msg = cn->init_buf->data;
s->init_num = SSL3_HM_HEADER_LENGTH;
} else {
SSLerr(SSL_F_TLS_GET_MESSAGE_HEADER, SSL_R_EXCESSIVE_MESSAGE_SIZE);
goto f_err;
}

