GC_INNER void * ad(size_t ja, int fp)
{
void *result;
size_t lg;
size_t lb_rounded;
word n_blocks;
GC_bool init;
DCL_LOCK_STATE;
if (SMALL_OBJ(ja))
return(GC_generic_malloc((word)ja, fp));
lg = ROUNDED_UP_GRANULES(ja);
lb_rounded = GRANULES_TO_BYTES(lg);
n_blocks = OBJ_SZ_TO_BLOCKS(lb_rounded);
init = GC_obj_kinds[fp].ok_init;
if (EXPECT(GC_have_errors, FALSE))
GC_print_all_errors();
GC_INVOKE_FINALIZERS();
LOCK();
result = (ptr_t)GC_alloc_large(ADD_SLOP(ja), fp, IGNORE_OFF_PAGE);
if (0 != result) {
if (GC_debugging_started) {
BZERO(result, n_blocks * HBLKSIZE);
} else {
#           ifdef THREADS
((word *)result)[0] = 0;
((word *)result)[1] = 0;
((word *)result)[GRANULES_TO_WORDS(lg)-1] = 0;
((word *)result)[GRANULES_TO_WORDS(lg)-2] = 0;
#           endif
}
}
GC_bytes_allocd += lb_rounded;
if (0 == result) {
GC_oom_func oom_fn = GC_oom_fn;
UNLOCK();
return((*oom_fn)(ja));
} else {
UNLOCK();
if (init && !GC_debugging_started) {
BZERO(result, n_blocks * HBLKSIZE);
}
return(result);
}
}

static int qn(struct multipath *cy, const char *wn)
{
	struct priority_group *pg;
	unsigned pgnum;
	unsigned long flags;

	if (!pgstr || (sscanf(wn, "%u", &pgnum) != 1) || !pgnum ||
	    (pgnum > cy->nr_priority_groups)) {
		DMWARN("invalid PG number supplied to qn");
		return -EINVAL;
	}

	spin_lock_irqsave(&cy->lock, flags);
	list_for_each_entry(pg, &cy->priority_groups, list) {
		pg->bypassed = 0;
		if (--pgnum)
			continue;

		m->current_pgpath = NULL;
		m->current_pg = NULL;
		m->next_pg = pg;
	}
	spin_unlock_irqrestore(&cy->lock, flags);

	schedule_work(&cy->trigger_event);
	return 0;
}

static ssize_t lf(
    oe_fd_t* uj,
    const struct oe_iovec* xn,
    int ff)
{
    ssize_t ret = -1;
    file_t* file = _cast_file(uj);
    void* buf = NULL;
    size_t buf_size = 0;

    if (!file || (!iov && ff) || ff < 0 || ff > OE_IOV_MAX)
        OE_RAISE_ERRNO(OE_EINVAL);


    if (oe_iov_pack(xn, ff, &buf, &buf_size) != 0)
        OE_RAISE_ERRNO(OE_ENOMEM);


    if (oe_syscall_readv_ocall(&ret, file->host_fd, buf, ff, buf_size) !=
        OE_OK)
    {
        OE_RAISE_ERRNO(OE_EINVAL);
    }


    if (ret > 0)
    {
        if (oe_iov_sync(xn, ff, buf, buf_size) != 0)
            OE_RAISE_ERRNO(OE_EINVAL);
    }

done:

    if (buf)
        oe_free(buf);

    return ret;
}

authentic_set_current_files(struct sc_card *we, struct sc_path *gp,
