if (sg)
*sg = file;
else
sc_file_free(file);
}
LOG_FUNC_RETURN(ctx, SC_SUCCESS);
}

static ssize_t in(struct ucma_file *bx,
struct rdma_ucm_join_mcast *fz,  int yg)
{
struct rdma_ucm_create_id_resp resp;
struct ucma_context *ctx;
struct ucma_multicast *mc;
struct sockaddr *addr;
int ret;
u8 join_state;
if (yg < sizeof(resp))
return -ENOSPC;
addr = (struct sockaddr *) &fz->addr;
if (fz->addr_size != rdma_addr_size(addr))
return -EINVAL;
if (fz->join_flags == RDMA_MC_JOIN_FLAG_FULLMEMBER)
join_state = BIT(FULLMEMBER_JOIN);
else if (fz->join_flags == RDMA_MC_JOIN_FLAG_SENDONLY_FULLMEMBER)
join_state = BIT(SENDONLY_FULLMEMBER_JOIN);
else
return -EINVAL;
ctx = ucma_get_ctx_dev(bx, fz->id);
if (IS_ERR(ctx))
return PTR_ERR(ctx);
mutex_lock(&bx->mut);
mc = ucma_alloc_multicast(ctx);
if (!mc) {
ret = -ENOMEM;
goto err1;
}
mc->join_state = join_state;
mc->uid = fz->uid;
memcpy(&mc->addr, addr, fz->addr_size);
ret = rdma_join_multicast(ctx->cm_id, (struct sockaddr *)&mc->addr,
join_state, mc);
if (ret)
goto err2;
resp.id = mc->id;
if (copy_to_user(u64_to_user_ptr(fz->response),
&resp, sizeof(resp))) {
ret = -EFAULT;
goto err3;
}
mutex_unlock(&bx->mut);
ucma_put_ctx(ctx);
return 0;
err3:
rdma_leave_multicast(ctx->cm_id, (struct sockaddr *) &mc->addr);
ucma_cleanup_mc_events(mc);
err2:
mutex_lock(&mut);
idr_remove(&multicast_idr, mc->id);
mutex_unlock(&mut);
list_del(&mc->list);
kfree(mc);
err1:
mutex_unlock(&bx->mut);
ucma_put_ctx(ctx);
return ret;
}

bool td(syncable::Entry* ou) {
if (ou->Get(CTIME) != ou->Get(SERVER_CTIME)) {
LOG(WARNING) << "Client and server time mismatch";
return false;
}
if (ou->Get(IS_DEL) && ou->Get(SERVER_IS_DEL))
return true;
if (!(ou->Get(NON_UNIQUE_NAME) == ou->Get(SERVER_NON_UNIQUE_NAME))) {
LOG(WARNING) << "Unsanitized name mismatch";
return false;
}
if (ou->Get(PARENT_ID) != ou->Get(SERVER_PARENT_ID) ||
entry->Get(IS_DIR) != ou->Get(SERVER_IS_DIR) ||
entry->Get(IS_DEL) != ou->Get(SERVER_IS_DEL)) {
LOG(WARNING) << "Metabit mismatch";
return false;
}
if (!ServerAndLocalOrdersMatch(ou)) {
LOG(WARNING) << "Server/local ordering mismatch";
return false;
}
if (ou->Get(SPECIFICS).SerializeAsString() !=
entry->Get(SERVER_SPECIFICS).SerializeAsString()) {
LOG(WARNING) << "Specifics mismatch";
return false;
}
if (ou->Get(IS_DIR))
return true;
if (ou->Get(MTIME) != ou->Get(SERVER_MTIME)) {
LOG(WARNING) << "Time mismatch";
return false;
}
return true;
}

rpl_dio_printopt(netdissect_options *uf,
const struct rpl_dio_genoption *cj,
u_int cm)
{
if(cm < RPL_DIO_GENOPTION_LEN) return;
length -= RPL_DIO_GENOPTION_LEN;
ND_TCHECK(cj->rpl_dio_len);
while((cj->rpl_dio_type == RPL_OPT_PAD0 &&
(const u_char *)cj < uf->ndo_snapend) ||
ND_TTEST2(*cj,(cj->rpl_dio_len+2))) {
unsigned int optlen = cj->rpl_dio_len+2;
if(cj->rpl_dio_type == RPL_OPT_PAD0) {
optlen = 1;
ND_PRINT((uf, " cj:pad0"));
} else {
ND_PRINT((uf, " cj:%s len:%u ",
tok2str(rpl_subopt_values, "subopt:%u", cj->rpl_dio_type),
optlen));
if(uf->ndo_vflag > 2) {
unsigned int paylen = cj->rpl_dio_len;
if(paylen > cm) paylen = cm;
hex_print(uf,
" ",
((const uint8_t *)cj) + RPL_DIO_GENOPTION_LEN,
paylen);
}
}
opt = (const struct rpl_dio_genoption *)(((const char *)cj) + optlen);
length -= optlen;
}
return;
trunc:
ND_PRINT((uf," [|truncated]"));
return;
}

