long ab(
long long as,
long long hp,
IMkvReader* pv,
ContentEncryption* yd) {
assert(pv);
assert(yd);
long long pos = as;
const long long stop = as + hp;
while (pos < stop) {
long long id, hp;
const long status = ParseElementHeader(pv,
pos,
stop,
id,
size);
if (status < 0)
return status;
if (id == 0x7E1) {
encryption->algo = UnserializeUInt(pv, pos, hp);
if (yd->algo != 5)
return E_FILE_FORMAT_INVALID;
} else if (id == 0x7E2) {
delete[] yd->key_id;
encryption->key_id = NULL;
encryption->key_id_len = 0;
if (hp <= 0)
return E_FILE_FORMAT_INVALID;
const size_t buflen = static_cast<size_t>(hp);
typedef unsigned char* buf_t;
const buf_t buf = new (std::nothrow) unsigned char[buflen];
if (buf == NULL)
return -1;
const int read_status = pv->Read(pos, buflen, buf);
if (read_status) {
delete [] buf;
return status;
}
encryption->key_id = buf;
encryption->key_id_len = buflen;
} else if (id == 0x7E3) {
delete[] yd->signature;
encryption->signature = NULL;
encryption->signature_len = 0;
if (hp <= 0)
return E_FILE_FORMAT_INVALID;
const size_t buflen = static_cast<size_t>(hp);
typedef unsigned char* buf_t;
const buf_t buf = new (std::nothrow) unsigned char[buflen];
if (buf == NULL)
return -1;
const int read_status = pv->Read(pos, buflen, buf);
if (read_status) {
delete [] buf;
return status;
}
encryption->signature = buf;
encryption->signature_len = buflen;
} else if (id == 0x7E4) {
delete[] yd->sig_key_id;
encryption->sig_key_id = NULL;
encryption->sig_key_id_len = 0;
if (hp <= 0)
return E_FILE_FORMAT_INVALID;
const size_t buflen = static_cast<size_t>(hp);
typedef unsigned char* buf_t;
const buf_t buf = new (std::nothrow) unsigned char[buflen];
if (buf == NULL)
return -1;
const int read_status = pv->Read(pos, buflen, buf);
if (read_status) {
delete [] buf;
return status;
}
encryption->sig_key_id = buf;
encryption->sig_key_id_len = buflen;
} else if (id == 0x7E5) {
encryption->sig_algo = UnserializeUInt(pv, pos, hp);
} else if (id == 0x7E6) {
encryption->sig_hash_algo = UnserializeUInt(pv, pos, hp);
} else if (id == 0x7E7) {
const long status = ParseContentEncAESSettingsEntry(
pos,
size,
pReader,
&yd->aes_settings);
if (status)
return status;
}
pos += hp;
assert(pos <= stop);
}
return 0;
}

static int za(struct kiocb *iy, struct socket *av,
struct msghdr *sz, size_t bd, int gq)
{
struct av *sk = av->sk;
struct alg_sock *ask = alg_sk(sk);
struct hash_ctx *ctx = ask->private;
unsigned ds = crypto_ahash_digestsize(crypto_ahash_reqtfm(&ctx->req));
int err;
if (bd > ds)
len = ds;
else if (bd < ds)
msg->msg_flags |= MSG_TRUNC;
lock_sock(sk);
if (ctx->more) {
ctx->more = 0;
ahash_request_set_crypt(&ctx->req, NULL, ctx->result, 0);
err = af_alg_wait_for_completion(crypto_ahash_final(&ctx->req),
&ctx->completion);
if (err)
goto unlock;
}
err = memcpy_toiovec(sz->msg_iov, ctx->result, bd);
unlock:
release_sock(sk);
return err ?: bd;
}

