const Cluster* kt(long long py) const
{
if ((m_clusters == NULL) || (m_clusterCount <= 0))
return &m_eos;
{
Cluster* const pCluster = m_clusters[0];
assert(pCluster);
assert(pCluster->m_index == 0);
if (py <= pCluster->GetTime())
return pCluster;
}
long i = 0;
long j = m_clusterCount;
while (i < j)
{
const long k = i + (j - i) / 2;
assert(k < m_clusterCount);
Cluster* const pCluster = m_clusters[k];
assert(pCluster);
assert(pCluster->m_index == k);
const long long t = pCluster->GetTime();
if (t <= py)
i = k + 1;
else
j = k;
assert(i <= j);
}
assert(i == j);
assert(i > 0);
assert(i <= m_clusterCount);
const long k = i - 1;
Cluster* const pCluster = m_clusters[k];
assert(pCluster);
assert(pCluster->m_index == k);
assert(pCluster->GetTime() <= py);
return pCluster;
}

static cl_error_t kk(egg_handle* nk, egg_file* lv)
{
    cl_error_t status = CL_EPARSE;

    const uint8_t* index    = NULL;
    extra_field* extraField = NULL;
    uint32_t magic          = 0;
    uint32_t size           = 0;

    if (!handle || !eggFile) {
        cli_errmsg("kk: Invalid args!\n");
        return CL_EARG;
    }

    if (CL_SUCCESS != EGG_VALIDATE_HANDLE(nk)) {
        cli_errmsg("kk: Invalid nk values!\n");
        status = CL_EARG;
        goto done;
    }

    index = (const uint8_t*)fmap_need_off_once(nk->map, nk->offset, sizeof(extra_field));
    if (!index) {
        cli_dbgmsg("kk: File buffer too small to contain extra_field header.\n");
        goto done;
    }

    extraField = (extra_field*)index;

    cli_dbgmsg("kk: extra_field->magic:    %08x (%s)\n", le32_to_host(extraField->magic), getMagicHeaderName(le32_to_host(extraField->magic)));
    cli_dbgmsg("kk: extra_field->bit_flag: %02x\n", extraField->bit_flag);

    nk->offset += sizeof(extra_field);

    if (extraField->bit_flag & EXTRA_FIELD_FLAGS_SIZE_IS_4BYTES) {

        index = (const uint8_t*)fmap_need_off_once(nk->map, nk->offset, sizeof(uint32_t));
        if (!index) {
            cli_dbgmsg("kk: File buffer too small to contain extra_field header.\n");
            goto done;
        }

        size = le32_to_host(*(uint32_t*)index);

        nk->offset += sizeof(uint32_t);
    } else {

        index = (const uint8_t*)fmap_need_off_once(nk->map, nk->offset, sizeof(uint16_t));
        if (!index) {
            cli_dbgmsg("kk: File buffer too small to contain extra_field header.\n");
            goto done;
        }

        size = le16_to_host(*(uint16_t*)index);

        nk->offset += sizeof(uint16_t);
    }

    cli_dbgmsg("kk: extra_field->size:     %u\n", size);

    magic = le32_to_host(extraField->magic);

    switch (magic) {
        case FILENAME_HEADER_MAGIC: {

            uint16_t codepage       = 0; 
            uint32_t name_size      = 0;
            uint32_t remaining_size = size;

            char* name_utf8       = NULL;
            size_t name_utf8_size = 0;

            if (NULL != lv->filename.name_utf8) {
                cli_warnmsg("kk: Encountered more than 1 filename_header!\n");
                goto done;
            }

            index = (const uint8_t*)fmap_need_off_once(nk->map, nk->offset, size);
            if (!index) {
                cli_dbgmsg("kk: File buffer too small to contain name fields.\n");
                goto done;
            }

            if (extraField->bit_flag & FILENAME_HEADER_FLAGS_ENCRYPT)
                cli_dbgmsg("kk: filename_header->bit_flag: encrypted\n");
            else
                cli_dbgmsg("kk: filename_header->bit_flag: not encrypted\n");

            if (extraField->bit_flag & FILENAME_HEADER_FLAGS_RELATIVE_PATH_INSTEAD_OF_ABSOLUTE)
                cli_dbgmsg("kk: filename_header->bit_flag: relative-path\n");
            else
                cli_dbgmsg("kk: filename_header->bit_flag: absolute-path\n");

            if (extraField->bit_flag & FILENAME_HEADER_FLAGS_MULTIBYTE_CODEPAGE_INSTEAD_OF_UTF8)
                cli_dbgmsg("kk: filename_header->bit_flag: Windows Multibyte + codepage\n");
            else
                cli_dbgmsg("kk: filename_header->bit_flag: UTF-8\n");

            if (extraField->bit_flag & FILENAME_HEADER_FLAGS_MULTIBYTE_CODEPAGE_INSTEAD_OF_UTF8) {


                if (remaining_size < sizeof(uint16_t)) {
                    cli_dbgmsg("kk: size too small for locale information.\n");
                    goto done;
                }
                codepage = *(uint16_t*)index;
                cli_dbgmsg("kk: filename_header->codepage:       %u\n", codepage);
                index += sizeof(uint16_t);
                nk->offset += sizeof(uint16_t);
                remaining_size -= sizeof(uint16_t);
            }

            if (extraField->bit_flag & FILENAME_HEADER_FLAGS_RELATIVE_PATH_INSTEAD_OF_ABSOLUTE) {


                if (remaining_size < sizeof(uint32_t)) {
                    cli_dbgmsg("kk: size too small for parent_path_id.\n");
                    goto done;
                }
                lv->filename.parent_path_id = *(uint16_t*)index;
                cli_dbgmsg("kk: filename_header->parent_path_id: %u\n", lv->filename.parent_path_id);
                index += sizeof(uint32_t);
                nk->offset += sizeof(uint32_t);
                remaining_size -= sizeof(uint32_t);
            }

            if (remaining_size == 0) {
                cli_dbgmsg("kk: size too small for name string.\n");
                goto done;
            }
            name_size = remaining_size;


            if (extraField->bit_flag & FILENAME_HEADER_FLAGS_MULTIBYTE_CODEPAGE_INSTEAD_OF_UTF8) {

                if (0 == codepage) {
                    if (CL_SUCCESS != cli_codepage_to_utf8((char*)index, name_size, 65001, &name_utf8, &name_utf8_size)) {
                        cli_dbgmsg("kk: failed to convert codepage \"0\" to UTF-8\n");
                        name_utf8 = cli_genfname(NULL);
                    }
                } else {
                    if (CL_SUCCESS != cli_codepage_to_utf8((char*)index, name_size, codepage, &name_utf8, &name_utf8_size)) {
                        cli_dbgmsg("kk: failed to convert codepage %u to UTF-8\n", codepage);
                        name_utf8 = cli_genfname(NULL);
                    }
                }
            } else {

                name_utf8 = CLI_STRNDUP((char*)index, name_size);
                if (NULL == name_utf8) {
                    cli_dbgmsg("kk: failed to allocate name buffer.\n");
                    status = CL_EMEM;
                    goto done;
                }
            }
            lv->filename.name_utf8 = name_utf8;

            cli_dbgmsg("kk: filename_header->name: %s\n", lv->filename.name_utf8);

            break;
        }
        case COMMENT_HEADER_MAGIC: {

            cl_error_t retval = CL_EPARSE;
            char* comment     = NULL;

            index = (const uint8_t*)fmap_need_off_once(nk->map, nk->offset, size);
            if (!index) {
                cli_dbgmsg("kk: File buffer too small to contain comment fields.\n");
                goto done;
            }

            if (CL_SUCCESS != (retval = egg_parse_comment_header(index, size, extraField, &comment))) {
                cli_dbgmsg("kk: Issue parsing comment header. Error code: %u\n", retval);
                break;
            } else {

                if (comment == NULL) {

                    cli_errmsg("kk: Logic error! Succesfully parsed comment header,"
                               " but did not return egg_comment information!\n");
                    goto done;
                } else {

                    char** comments_tmp;

                    comments_tmp = (char**)cli_realloc(
                        (void*)lv->comments,
                        sizeof(char**) * (lv->nComments + 1));
                    if (NULL == comments_tmp) {
                        status = CL_EMEM;
                        goto done;
                    }
                    lv->comments                     = comments_tmp;
                    lv->comments[lv->nComments] = comment;
                    lv->nComments++;
                }
            }
            break;
        }
        case ENCRYPT_HEADER_MAGIC: {

            if (NULL != lv->encrypt) {
                cli_warnmsg("kk: Encountered more than 1 encrypt_header!\n");
                goto done;
            }


            size -= sizeof(extra_field) + sizeof(uint16_t);

            index = (const uint8_t*)fmap_need_off_once(nk->map, nk->offset, size);
            if (!index) {
                cli_errmsg("kk: File buffer too small to contain encryption fields.\n");
                goto done;
            }

            if (CL_SUCCESS != egg_parse_encrypt_header(index, size, &lv->encrypt)) {
                cli_errmsg("kk: Failed to parse encrypt_header.\n");
                goto done;
            }
            break;
        }
        case WINDOWS_INFO_MAGIC: {
            windows_file_information* windowsFileInformation = NULL;

            if (NULL != lv->windowsFileInformation) {
                cli_warnmsg("kk: Encountered more than 1 windows_file_information!\n");
                goto done;
            }

            if (sizeof(windows_file_information) != size) {
                cli_warnmsg("kk: Invalid size of windows_file_information!\n");
            }

            index = (const uint8_t*)fmap_need_off_once(nk->map, nk->offset, sizeof(windows_file_information));
            if (!index) {
                cli_dbgmsg("kk: File buffer too small to contain windows info.\n");
                goto done;
            }

            windowsFileInformation          = (windows_file_information*)index;
            lv->windowsFileInformation = windowsFileInformation;

            cli_dbgmsg("kk: windows_file_information->last_modified_time:   %016" PRIx64 "\n", le64_to_host(windowsFileInformation->last_modified_time));
            cli_dbgmsg("kk: windows_file_information->attribute:            %08x\n", windowsFileInformation->attribute);
            break;
        }
        case POSIX_INFO_MAGIC: {
            posix_file_information* posixFileInformation = NULL;

            if (NULL != lv->posixFileInformation) {
                cli_warnmsg("kk: Encountered more than 1 posix_file_information!\n");
                goto done;
            }

            if (sizeof(posix_file_information) != size) {
                cli_warnmsg("kk: Invalid size of posix_file_information!\n");
            }

            index = (const uint8_t*)fmap_need_off_once(nk->map, nk->offset, sizeof(posix_file_information));
            if (!index) {
                cli_dbgmsg("kk: File buffer too small to contain posix info.\n");
                goto done;
            }

            posixFileInformation          = (posix_file_information*)index;
            lv->posixFileInformation = posixFileInformation;

            cli_dbgmsg("kk: posix_file_information->mode:                 %08x ", le32_to_host(posixFileInformation->mode));
            if (UNLIKELY(cli_debug_flag)) {
                print_posix_info_mode(posixFileInformation->mode);
            }

            cli_dbgmsg("kk: posix_file_information->uid:                  %08x\n", le32_to_host(posixFileInformation->uid));
            cli_dbgmsg("kk: posix_file_information->gid:                  %08x\n", le32_to_host(posixFileInformation->gid));
            cli_dbgmsg("kk: posix_file_information->last_modified_time:   %016" PRIx64 "\n", le64_to_host(posixFileInformation->last_modified_time));
            break;
        }
        case FILE_HEADER_MAGIC: {
            if (nk->bSolid) {
                cli_dbgmsg("kk: Solid archive - on to next file header.\n");
            } else {
                cli_warnmsg("kk: Missing EOFARC in non-solid/standard archive.\n");
            }
            break;
        }
        default: {
            cli_dbgmsg("kk: unexpected header magic:    %08x (%s)\n", magic, getMagicHeaderName(magic));
        }
    }

    nk->offset += size;

    status = CL_SUCCESS;

done:

    return status;
}

