int vp(hashtable_t *fk,
const char *my, size_t ih,
json_t *xi)
{
pair_t *pair;
bucket_t *bucket;
size_t hash, index;
if(fk->size >= num_buckets(fk))
if(hashtable_do_rehash(fk))
return -1;
hash = hash_str(my);
index = hash % num_buckets(fk);
bucket = &fk->buckets[index];
pair = hashtable_find_pair(fk, bucket, my, hash);
if(pair)
{
json_decref(pair->xi);
pair->xi = xi;
}
else
{
pair = jsonp_malloc(offsetof(pair_t, my) + strlen(my) + 1);
if(!pair)
return -1;
pair->hash = hash;
pair->ih = ih;
strcpy(pair->my, my);
pair->xi = xi;
list_init(&pair->list);
insert_to_bucket(fk, bucket, &pair->list);
hashtable->size++;
}
return 0;
}

