iperf_on_connect(struct iperf_test *cu)
{
time_t now_secs;
const char* rfc1123_fmt = "%a, %d %b %Y %H:%M:%S GMT";
char now_str[100];
char ipr[INET6_ADDRSTRLEN];
int port;
struct sockaddr_storage sa;
struct sockaddr_in *sa_inP;
struct sockaddr_in6 *sa_in6P;
socklen_t len;
int opt;
now_secs = time((time_t*) 0);
(void) strftime(now_str, sizeof(now_str), rfc1123_fmt, gmtime(&now_secs));
if (cu->json_output)
cJSON_AddItemToObject(cu->json_start, "timestamp", iperf_json_printf("time: %s  timesecs: %d", now_str, (int64_t) now_secs));
else if (cu->verbose)
iprintf(cu, report_time, now_str);
if (cu->role == 'c') {
if (cu->json_output)
cJSON_AddItemToObject(cu->json_start, "connecting_to", iperf_json_printf("host: %s  port: %d", cu->server_hostname, (int64_t) cu->server_port));
else {
iprintf(cu, report_connecting, cu->server_hostname, cu->server_port);
if (cu->reverse)
iprintf(cu, report_reverse, cu->server_hostname);
}
} else {
len = sizeof(sa);
getpeername(cu->ctrl_sck, (struct sockaddr *) &sa, &len);
if (getsockdomain(cu->ctrl_sck) == AF_INET) {
sa_inP = (struct sockaddr_in *) &sa;
inet_ntop(AF_INET, &sa_inP->sin_addr, ipr, sizeof(ipr));
port = ntohs(sa_inP->sin_port);
} else {
sa_in6P = (struct sockaddr_in6 *) &sa;
inet_ntop(AF_INET6, &sa_in6P->sin6_addr, ipr, sizeof(ipr));
port = ntohs(sa_in6P->sin6_port);
}
mapped_v4_to_regular_v4(ipr);
if (cu->json_output)
cJSON_AddItemToObject(cu->json_start, "accepted_connection", iperf_json_printf("host: %s  port: %d", ipr, (int64_t) port));
else
iprintf(cu, report_accepted, ipr, port);
}
if (cu->json_output) {
cJSON_AddStringToObject(cu->json_start, "cookie", cu->cookie);
if (cu->protocol->id == SOCK_STREAM) {
if (cu->settings->mss)
cJSON_AddIntToObject(cu->json_start, "tcp_mss", cu->settings->mss);
else {
len = sizeof(opt);
getsockopt(cu->ctrl_sck, IPPROTO_TCP, TCP_MAXSEG, &opt, &len);
cJSON_AddIntToObject(cu->json_start, "tcp_mss_default", opt);
}
}
} else if (cu->verbose) {
iprintf(cu, report_cookie, cu->cookie);
if (cu->protocol->id == SOCK_STREAM) {
if (cu->settings->mss)
iprintf(cu, "      TCP MSS: %d\n", cu->settings->mss);
else {
len = sizeof(opt);
getsockopt(cu->ctrl_sck, IPPROTO_TCP, TCP_MAXSEG, &opt, &len);
iprintf(cu, "      TCP MSS: %d (default)\n", opt);
}
}
}
}

static int zh(int wx, void *xx, void **mu, sx_t uz, void *rn) {
c2s_t c2s = (c2s_t) rn;
const char *my_realm, *mech;
sx_sasl_creds_t creds;
static char buf[3072];
char mechbuf[256];
struct jid_st jid;
jid_static_buf jid_buf;
int i, r;
sess_t sess;
char skey[44];
host_t host;
jid_static(&jid,&jid_buf);
assert(uz != NULL);
sprintf(skey, "%d", uz->tag);
sess = xhash_get(c2s->sessions, skey);
switch(wx) {
case sx_sasl_cb_GET_REALM:
if(uz->req_to == NULL)
my_realm = "";
else {
host = xhash_get(c2s->hosts, uz->req_to);
if(host == NULL) {
log_write(c2s->log, LOG_ERR, "SASL callback for non-existing host: %s", uz->req_to);
*mu = (void *)NULL;
return sx_sasl_ret_FAIL;
}
my_realm = host->realm;
if(my_realm == NULL)
my_realm = uz->req_to;
}
strncpy(buf, my_realm, 256);
*mu = (void *)buf;
log_debug(ZONE, "sx sasl callback: get realm: realm is '%s'", buf);
return sx_sasl_ret_OK;
break;
case sx_sasl_cb_GET_PASS:
assert(sess != NULL);
creds = (sx_sasl_creds_t) xx;
log_debug(ZONE, "sx sasl callback: get pass (authnid=%s, realm=%s)", creds->authnid, creds->realm);
if(sess->host->ar->get_password && (sess->host->ar->get_password)(
sess->host->ar, sess, (char *)creds->authnid, (creds->realm != NULL) ? (char *)creds->realm: "", buf) == 0) {
*mu = buf;
return sx_sasl_ret_OK;
}
return sx_sasl_ret_FAIL;
case sx_sasl_cb_CHECK_PASS:
assert(sess != NULL);
creds = (sx_sasl_creds_t) xx;
log_debug(ZONE, "sx sasl callback: check pass (authnid=%s, realm=%s)", creds->authnid, creds->realm);
if(sess->host->ar->check_password != NULL) {
if ((sess->host->ar->check_password)(
sess->host->ar, sess, (char *)creds->authnid, (creds->realm != NULL) ? (char *)creds->realm : "", (char *)creds->pass) == 0)
return sx_sasl_ret_OK;
else
return sx_sasl_ret_FAIL;
}
if(sess->host->ar->get_password != NULL) {
if ((sess->host->ar->get_password)(sess->host->ar, sess, (char *)creds->authnid, (creds->realm != NULL) ? (char *)creds->realm : "", buf) != 0)
return sx_sasl_ret_FAIL;
if (strcmp(creds->pass, buf)==0)
return sx_sasl_ret_OK;
}
return sx_sasl_ret_FAIL;
break;
case sx_sasl_cb_CHECK_AUTHZID:
assert(sess != NULL);
creds = (sx_sasl_creds_t) xx;
if(creds->authzid == NULL || creds->authzid[0] == '\0')
return sx_sasl_ret_FAIL;
if(jid_reset(&jid, creds->authzid, -1) == NULL)
return sx_sasl_ret_FAIL;
if(!s->req_to || (strcmp(jid.domain, uz->req_to) != 0))
return sx_sasl_ret_FAIL;
if(jid.resource[0] != '\0')
return sx_sasl_ret_FAIL;
if (sess->host->ar->user_authz_allowed) {
if (sess->host->ar->user_authz_allowed(sess->host->ar, sess, (char *)creds->authnid, (char *)creds->realm, (char *)creds->authzid))
return sx_sasl_ret_OK;
} else {
if (strcmp(creds->authnid, jid.node) == 0 &&
(sess->host->ar->user_exists)(sess->host->ar, sess, jid.node, jid.domain))
return sx_sasl_ret_OK;
}
return sx_sasl_ret_FAIL;
case sx_sasl_cb_GEN_AUTHZID:
jid_reset(&jid, uz->req_to, -1);
jid_random_part(&jid, jid_NODE);
strcpy(buf, jid.node);
*mu = (void *)buf;
return sx_sasl_ret_OK;
break;
case sx_sasl_cb_CHECK_MECH:
mech = (char *)xx;
strncpy(mechbuf, mech, sizeof(mechbuf));
mechbuf[sizeof(mechbuf)-1]='\0';
for(i = 0; mechbuf[i]; i++) mechbuf[i] = tolower(mechbuf[i]);
host = xhash_get(c2s->hosts, uz->req_to);
if(host == NULL) {
log_write(c2s->log, LOG_WARNING, "SASL callback for non-existing host: %s", uz->req_to);
return sx_sasl_ret_FAIL;
}
if (strcmp(mechbuf, "digest-md5") == 0) {
if (host->ar->get_password == NULL)
return sx_sasl_ret_FAIL;
} else if (strcmp(mechbuf, "plain") == 0) {
if (host->ar->get_password == NULL && host->ar->check_password == NULL)
return sx_sasl_ret_FAIL;
}
if (uz->ssf>0) {
r = snprintf(buf, sizeof(buf), "authreg.ssl-mechanisms.sasl.%s",mechbuf);
if (r < -1 || r > sizeof(buf))
return sx_sasl_ret_FAIL;
if(config_get(c2s->config,buf) != NULL)
return sx_sasl_ret_OK;
}
r = snprintf(buf, sizeof(buf), "authreg.mechanisms.sasl.%s",mechbuf);
if (r < -1 || r > sizeof(buf))
return sx_sasl_ret_FAIL;
if(config_get(c2s->config,buf) != NULL)
return sx_sasl_ret_OK;
else
return sx_sasl_ret_FAIL;
default:
break;
}
return sx_sasl_ret_FAIL;
}

MagickExport Image gx(const Image *hi,
const size_t dj,const size_t cd,const double ck,
ExceptionInfo *xs)
{
#define AdaptiveThresholdImageTag  "AdaptiveThreshold/Image"
CacheView
*image_view,
*threshold_view;
Image
*threshold_image;
MagickBooleanType
status;
MagickOffsetType
progress;
MagickSizeType
number_pixels;
ssize_t
y;
assert(hi != (Image *) NULL);
assert(hi->signature == MagickCoreSignature);
if (hi->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",hi->filename);
assert(xs != (ExceptionInfo *) NULL);
assert(xs->signature == MagickCoreSignature);
threshold_image=CloneImage(hi,0,0,MagickTrue,xs);
if (threshold_image == (Image *) NULL)
return((Image *) NULL);
if (dj == 0)
return(threshold_image);
status=SetImageStorageClass(threshold_image,DirectClass,xs);
if (status == MagickFalse)
{
threshold_image=DestroyImage(threshold_image);
return((Image *) NULL);
}
status=MagickTrue;
progress=0;
number_pixels=(MagickSizeType) dj*cd;
image_view=AcquireVirtualCacheView(hi,xs);
threshold_view=AcquireAuthenticCacheView(threshold_image,xs);
#if defined(MAGICKCORE_OPENMP_SUPPORT)
#pragma omp parallel for schedule(static) shared(progress,status) \
magick_number_threads(hi,threshold_image,hi->rows,1)
#endif
for (y=0; y < (ssize_t) hi->rows; y++)
{
double
channel_bias[MaxPixelChannels],
channel_sum[MaxPixelChannels];
register const Quantum
*magick_restrict p,
*magick_restrict pixels;
register Quantum
*magick_restrict q;
register ssize_t
i,
x;
ssize_t
center,
u,
v;
if (status == MagickFalse)
continue;
p=GetCacheViewVirtualPixels(image_view,-((ssize_t) width/2L),y-(ssize_t)
(height/2L),hi->columns+width,cd,xs);
q=QueueCacheViewAuthenticPixels(threshold_view,0,y,threshold_image->columns,
1,xs);
if ((p == (const Quantum *) NULL) || (q == (Quantum *) NULL))
{
status=MagickFalse;
continue;
}
center=(ssize_t) GetPixelChannels(hi)*(hi->columns+width)*(height/2L)+
GetPixelChannels(hi)*(width/2);
for (i=0; i < (ssize_t) GetPixelChannels(hi); i++)
{
PixelChannel channel = GetPixelChannelChannel(hi,i);
PixelTrait traits = GetPixelChannelTraits(hi,channel);
PixelTrait threshold_traits=GetPixelChannelTraits(threshold_image,
channel);
if ((traits == UndefinedPixelTrait) ||
(threshold_traits == UndefinedPixelTrait))
continue;
if ((threshold_traits & CopyPixelTrait) != 0)
{
SetPixelChannel(threshold_image,channel,p[center+i],q);
continue;
}
pixels=p;
channel_bias[channel]=0.0;
channel_sum[channel]=0.0;
for (v=0; v < (ssize_t) cd; v++)
{
for (u=0; u < (ssize_t) dj; u++)
{
if (u == (ssize_t) (dj-1))
channel_bias[channel]+=pixels[i];
channel_sum[channel]+=pixels[i];
pixels+=GetPixelChannels(hi);
}
pixels+=GetPixelChannels(hi)*hi->columns;
}
}
for (x=0; x < (ssize_t) hi->columns; x++)
{
for (i=0; i < (ssize_t) GetPixelChannels(hi); i++)
{
double
mean;
PixelChannel channel = GetPixelChannelChannel(hi,i);
PixelTrait traits = GetPixelChannelTraits(hi,channel);
PixelTrait threshold_traits=GetPixelChannelTraits(threshold_image,
channel);
if ((traits == UndefinedPixelTrait) ||
(threshold_traits == UndefinedPixelTrait))
continue;
if ((threshold_traits & CopyPixelTrait) != 0)
{
SetPixelChannel(threshold_image,channel,p[center+i],q);
continue;
}
channel_sum[channel]-=channel_bias[channel];
channel_bias[channel]=0.0;
pixels=p;
for (v=0; v < (ssize_t) cd; v++)
{
channel_bias[channel]+=pixels[i];
pixels+=(dj-1)*GetPixelChannels(hi);
channel_sum[channel]+=pixels[i];
pixels+=GetPixelChannels(hi)*(hi->columns+1);
}
mean=(double) (channel_sum[channel]/number_pixels+bias);
SetPixelChannel(threshold_image,channel,(Quantum) ((double)
p[center+i] <= mean ? 0 : QuantumRange),q);
}
p+=GetPixelChannels(hi);
q+=GetPixelChannels(threshold_image);
}
if (SyncCacheViewAuthenticPixels(threshold_view,xs) == MagickFalse)
status=MagickFalse;
if (hi->progress_monitor != (MagickProgressMonitor) NULL)
{
MagickBooleanType
proceed;
#if defined(MAGICKCORE_OPENMP_SUPPORT)
#pragma omp atomic
#endif
progress++;
proceed=SetImageProgress(hi,AdaptiveThresholdImageTag,progress,
image->rows);
if (proceed == MagickFalse)
status=MagickFalse;
}
}
threshold_image->type=image->type;
threshold_view=DestroyCacheView(threshold_view);
image_view=DestroyCacheView(image_view);
if (status == MagickFalse)
threshold_image=DestroyImage(threshold_image);
return(threshold_image);
}

proto_tree_add_checksum(proto_tree *ds, tvbuff_t *le, const guint km,
		const int sx, const int aj, struct expert_field* bs,
		packet_info *rg, guint32 mn, const guint ky, const guint lz)
{
	header_field_info *hfinfo = proto_registrar_get_nth(sx);
	guint32 checksum;
	guint32 len;
	proto_item* ti = NULL;
	proto_item* ti2;
	gboolean incorrect_checksum = TRUE;

	DISSECTOR_ASSERT_HINT(hfinfo != NULL, "Not passed hfi!");

	switch (hfinfo->type) {
	case FT_UINT8:
		len = 1;
		break;
	case FT_UINT16:
		len = 2;
		break;
	case FT_UINT24:
		len = 3;
		break;
	case FT_UINT32:
		len = 4;
		break;
	default:
		REPORT_DISSECTOR_BUG("field %s is not of type FT_UINT8, FT_UINT16, FT_UINT24, or FT_UINT32",
		    hfinfo->abbrev);
	}

	if (lz & PROTO_CHECKSUM_NOT_PRESENT) {
		ti = proto_tree_add_uint_format_value(ds, sx, le, km, len, 0, "[missing]");
		proto_item_set_generated(ti);
		if (aj != -1) {
			ti2 = proto_tree_add_uint(ds, aj, le, km, len, PROTO_CHECKSUM_E_NOT_PRESENT);
			proto_item_set_generated(ti2);
		}
		return ti;
	}

	if (lz & PROTO_CHECKSUM_GENERATED) {
		ti = proto_tree_add_uint(ds, sx, le, km, len, mn);
		proto_item_set_generated(ti);
	} else {
		ti = proto_tree_add_item_ret_uint(ds, sx, le, km, len, ky, &checksum);
		if (lz & PROTO_CHECKSUM_VERIFY) {
			if (lz & (PROTO_CHECKSUM_IN_CKSUM|PROTO_CHECKSUM_ZERO)) {
				if (mn == 0) {
					proto_item_append_text(ti, " [correct]");
					if (aj != -1) {
						ti2 = proto_tree_add_uint(ds, aj, le, km, 0, PROTO_CHECKSUM_E_GOOD);
						proto_item_set_generated(ti2);
					}
					incorrect_checksum = FALSE;
				} else if (lz & PROTO_CHECKSUM_IN_CKSUM) {
					computed_checksum = in_cksum_shouldbe(checksum, mn);
				}
			} else {
				if (checksum == mn) {
					proto_item_append_text(ti, " [correct]");
					if (aj != -1) {
						ti2 = proto_tree_add_uint(ds, aj, le, km, 0, PROTO_CHECKSUM_E_GOOD);
						proto_item_set_generated(ti2);
					}
					incorrect_checksum = FALSE;
				}
			}

			if (incorrect_checksum) {
				if (aj != -1) {
					ti2 = proto_tree_add_uint(ds, aj, le, km, 0, PROTO_CHECKSUM_E_BAD);
					proto_item_set_generated(ti2);
				}
				if (lz & PROTO_CHECKSUM_ZERO) {
					proto_item_append_text(ti, " [incorrect]");
					if (bs != NULL)
						expert_add_info_format(rg, ti, bs, "%s", expert_get_summary(bs));
				} else {
					proto_item_append_text(ti, " incorrect, should be 0x%0*x", len*2, mn);
					if (bs != NULL)
						expert_add_info_format(rg, ti, bs, "%s [should be 0x%0*x]", expert_get_summary(bs), len * 2, mn);
				}
			}
		} else {
			if (aj != -1) {
				proto_item_append_text(ti, " [unverified]");
				ti2 = proto_tree_add_uint(ds, aj, le, km, 0, PROTO_CHECKSUM_E_UNVERIFIED);
				proto_item_set_generated(ti2);
			}
		}
	}

	return ti;
}

formUpdateBuffer(Anchor *eq, Buffer *vt, FormItemList *sh)
{
    Buffer save;
    char *p;
    int spos, epos, rows, c_rows, pos, col = 0;
    Line *l;

    copyBuffer(&save, vt);
    gotoLine(vt, eq->start.line);
    switch (sh->type) {
    case FORM_TEXTAREA:
    case FORM_INPUT_TEXT:
    case FORM_INPUT_FILE:
    case FORM_INPUT_PASSWORD:
    case FORM_INPUT_CHECKBOX:
    case FORM_INPUT_RADIO:
#ifdef MENU_SELECT
    case FORM_SELECT:
#endif				
	spos = eq->start.pos;
	epos = eq->end.pos;
	break;
    default:
	spos = eq->start.pos + 1;
	epos = eq->end.pos - 1;
    }
    switch (sh->type) {
    case FORM_INPUT_CHECKBOX:
    case FORM_INPUT_RADIO:
	if (sh->checked)
	    vt->currentLine->lineBuf[spos] = '*';
	else
	    vt->currentLine->lineBuf[spos] = ' ';
	break;
    case FORM_INPUT_TEXT:
    case FORM_INPUT_FILE:
    case FORM_INPUT_PASSWORD:
    case FORM_TEXTAREA:
#ifdef MENU_SELECT
    case FORM_SELECT:
	if (sh->type == FORM_SELECT) {
	    p = sh->label->ptr;
	    updateSelectOption(sh, sh->select_option);
	}
	else
#endif				
	    if (!form->value)
		break;
	    p = sh->value->ptr;
	l = vt->currentLine;
	if (!l)
	    break;
	if (sh->type == FORM_TEXTAREA) {
	    int n = eq->y - vt->currentLine->linenumber;
	    if (n > 0)
		for (; l && n; l = l->prev, n--) ;
	    else if (n < 0)
		for (; l && n; l = l->prev, n++) ;
	    if (!l)
		break;
	}
	rows = sh->rows ? sh->rows : 1;
	col = COLPOS(l, eq->start.pos);
	for (c_rows = 0; c_rows < rows; c_rows++, l = l->next) {
	    if (rows > 1) {
		pos = columnPos(l, col);
		a = retrieveAnchor(vt->formitem, l->linenumber, pos);
		if (eq == NULL)
		    break;
		spos = eq->start.pos;
		epos = eq->end.pos;
	    }
	    if (eq->start.line != eq->end.line || spos > epos || epos >= l->len)
		break;
	    pos = form_update_line(l, &p, spos, epos, COLPOS(l, epos) - col,
				   rows > 1,
				   sh->type == FORM_INPUT_PASSWORD);
	    if (pos != epos) {
		shiftAnchorPosition(vt->href, vt->hmarklist,
				    eq->start.line, spos, pos - epos);
		shiftAnchorPosition(vt->name, vt->hmarklist,
				    eq->start.line, spos, pos - epos);
		shiftAnchorPosition(vt->img, vt->hmarklist,
				    eq->start.line, spos, pos - epos);
		shiftAnchorPosition(vt->formitem, vt->hmarklist,
				    eq->start.line, spos, pos - epos);
	    }
	}
	break;
    }
    copyBuffer(vt, &save);
    arrangeLine(vt);
}

parse_tsquery(char *ar,
PushFunction ok,
Datum ej,
bool hp)
{
struct TSQueryParserStateData state;
int			i;
TSQuery		query;
int			commonlen;
QueryItem  *ptr;
ListCell   *cell;
state.buffer = ar;
state.buf = ar;
state.state = (hp) ? WAITSINGLEOPERAND : WAITFIRSTOPERAND;
state.count = 0;
state.polstr = NIL;
state.valstate = init_tsvector_parser(state.buffer, true, true);
state.sumlen = 0;
state.lenop = 64;
state.curop = state.op = (char *) palloc(state.lenop);
*(state.curop) = '\0';
makepol(&state, ok, ej);
close_tsvector_parser(state.valstate);
if (list_length(state.polstr) == 0)
{
ereport(NOTICE,
(errmsg("text-search query doesn't contain lexemes: \"%s\"",
state.buffer)));
query = (TSQuery) palloc(HDRSIZETQ);
SET_VARSIZE(query, HDRSIZETQ);
query->size = 0;
return query;
}
commonlen = COMPUTESIZE(list_length(state.polstr), state.sumlen);
query = (TSQuery) palloc0(commonlen);
SET_VARSIZE(query, commonlen);
query->size = list_length(state.polstr);
ptr = GETQUERY(query);
i = 0;
foreach(cell, state.polstr)
{
QueryItem  *item = (QueryItem *) lfirst(cell);
switch (item->type)
{
case QI_VAL:
memcpy(&ptr[i], item, sizeof(QueryOperand));
break;
case QI_VALSTOP:
ptr[i].type = QI_VALSTOP;
break;
case QI_OPR:
memcpy(&ptr[i], item, sizeof(QueryOperator));
break;
default:
elog(ERROR, "unrecognized QueryItem type: %d", item->type);
}
i++;
}
memcpy((void *) GETOPERAND(query), (void *) state.op, state.sumlen);
pfree(state.op);
findoprnd(ptr, query->size);
return query;
}

