static u32 di(struct rpcrdma_msg *bt,
struct rpcrdma_write_array *kj,
struct rpcrdma_write_array *qw)
{
struct rpcrdma_read_chunk *rd_ary;
struct rpcrdma_segment *arg_ch;
rd_ary = (struct rpcrdma_read_chunk *)&bt->rm_body.rm_chunks[0];
if (rd_ary->rc_discrim != xdr_zero)
return be32_to_cpu(rd_ary->rc_target.rs_handle);
if (kj && be32_to_cpu(kj->wc_nchunks)) {
arg_ch = &kj->wc_array[0].wc_target;
return be32_to_cpu(arg_ch->rs_handle);
}
if (qw && be32_to_cpu(qw->wc_nchunks)) {
arg_ch = &qw->wc_array[0].wc_target;
return be32_to_cpu(arg_ch->rs_handle);
}
return 0;
}

