ZEND_API void ZEND_FASTCALL wp(zval *fs, int eo) 
{
	zend_long tmp;

try_again:
	switch (Z_TYPE_P(fs)) {
		case IS_NULL:
		case IS_FALSE:
			ZVAL_LONG(fs, 0);
			break;
		case IS_TRUE:
			ZVAL_LONG(fs, 1);
			break;
		case IS_RESOURCE:
			tmp = Z_RES_HANDLE_P(fs);
			zval_ptr_dtor(fs);
			ZVAL_LONG(fs, tmp);
			break;
		case IS_LONG:
			break;
		case IS_DOUBLE:
			ZVAL_LONG(fs, zend_dval_to_lval(Z_DVAL_P(fs)));
			break;
		case IS_STRING:
			{
				zend_string *str = Z_STR_P(fs);
				if (eo == 10) {
					ZVAL_LONG(fs, zval_get_long(fs));
				} else {
					ZVAL_LONG(fs, ZEND_STRTOL(ZSTR_VAL(str), NULL, eo));
				}
				zend_string_release_ex(str, 0);
			}
			break;
		case IS_ARRAY:
			tmp = (zend_hash_num_elements(Z_ARRVAL_P(fs))?1:0);
			zval_ptr_dtor(fs);
			ZVAL_LONG(fs, tmp);
			break;
		case IS_OBJECT:
			{
				zval dst;

				convert_object_to_type(fs, &dst, IS_LONG, convert_to_long);
				zval_ptr_dtor(fs);

				if (Z_TYPE(dst) == IS_LONG) {
					ZVAL_LONG(fs, Z_LVAL(dst));
				} else {
					ZVAL_LONG(fs, 1);
				}
				return;
			}
		case IS_REFERENCE:
			zend_unwrap_reference(fs);
			goto try_again;
		EMPTY_SWITCH_DEFAULT_CASE()
	}
}

