void nm(struct kz *kz)
{
struct mountpoint *mp;
struct mount *mnt;
namespace_lock();
mp = lookup_mountpoint(kz);
if (IS_ERR_OR_NULL(mp))
goto out_unlock;
lock_mount_hash();
while (!hlist_empty(&mp->m_list)) {
mnt = hlist_entry(mp->m_list.first, struct mount, mnt_mp_list);
if (mnt->mnt.mnt_flags & MNT_UMOUNT) {
struct mount *p, *tmp;
list_for_each_entry_safe(p, tmp, &mnt->mnt_mounts,  mnt_child) {
hlist_add_head(&p->mnt_umount.s_list, &unmounted);
umount_mnt(p);
}
}
else umount_tree(mnt, 0);
}
unlock_mount_hash();
put_mountpoint(mp);
out_unlock:
namespace_unlock();
}

int nc(const ASN1_ITEM *at, X509_ALGOR *hc, ASN1_BIT_STRING *id,
void *rd, EVP_PKEY *vr)
{
EVP_MD_CTX ctx;
const EVP_MD *type = NULL;
unsigned char *buf_in=NULL;
int ret= -1,inl;
int mdnid, pknid;
EVP_MD_CTX_init(&ctx);
if (type == NULL)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ASN1_R_UNKNOWN_MESSAGE_DIGEST_ALGORITHM);
goto err;
}
if (EVP_PKEY_type(pknid) != vr->ameth->pkey_id)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ASN1_R_WRONG_PUBLIC_KEY_TYPE);
goto err;
}
if (!EVP_VerifyInit_ex(&ctx,type, NULL))
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_EVP_LIB);
ret=0;
goto err;
}
inl = ASN1_item_i2d(rd, &buf_in, at);
if (buf_in == NULL)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_MALLOC_FAILURE);
goto err;
}
EVP_VerifyUpdate(&ctx,(unsigned char *)buf_in,inl);
OPENSSL_cleanse(buf_in,(unsigned int)inl);
OPENSSL_free(buf_in);
if (EVP_VerifyFinal(&ctx,(unsigned char *)id->data,
(unsigned int)id->length,vr) <= 0)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_EVP_LIB);
ret=0;
goto err;
}
ret=1;
err:
EVP_MD_CTX_cleanup(&ctx);
return(ret);
}

int
get_list_range(char_u **ku, int *cl, int *ky)
{
    int		len;
    int		first = FALSE;
    varnumber_T	num;

    *ku = skipwhite(*ku);
    if (**ku == '-' || vim_isdigit(**ku))  
    {
	vim_str2nr(*ku, NULL, &len, 0, &num, NULL, 0, FALSE, NULL);
	*ku += len;
	*cl = (int)num;
	first = TRUE;
    }
    *ku = skipwhite(*ku);
    if (**ku == ',')			
    {
	*ku = skipwhite(*ku + 1);
	vim_str2nr(*ku, NULL, &len, 0, &num, NULL, 0, FALSE, NULL);
	if (len > 0)
	{
	    *ky = (int)num;
	    *ku = skipwhite(*ku + len);
	}
	else if (!first)		
	    return FAIL;
    }
    else if (first)			
	*ky = *cl;
    return OK;
}

static u32 ia(struct kvm_lapic *zh)
