int em(struct ia *ia, u8 vq, u8 we,
				  u8 ve)
{
	struct sk_buff *skb;
	struct wmi_delete_pstream_cmd *cmd;
	u16 active_tsids = 0;
	int ret;

	if (we > 3) {
		ath6kl_err("invalid traffic class: %d\n", we);
		return -EINVAL;
	}

	skb = ath6kl_wmi_get_new_buf(sizeof(*cmd));
	if (!skb)
		return -ENOMEM;

	cmd = (struct wmi_delete_pstream_cmd *) skb->data;
	cmd->we = we;
	cmd->ve = ve;

	spin_lock_bh(&ia->lock);
	active_tsids = ia->stream_exist_for_ac[we];
	spin_unlock_bh(&ia->lock);

	if (!(active_tsids & (1 << ve))) {
		dev_kfree_skb(skb);
		ath6kl_dbg(ATH6KL_DBG_WMI,
			   "TSID %d doesn't exist for traffic class: %d\n",
			   ve, we);
		return -ENODATA;
	}

	ath6kl_dbg(ATH6KL_DBG_WMI,
		   "sending delete_pstream_cmd: traffic class: %d tsid=%d\n",
		   we, ve);

	ret = ath6kl_wmi_cmd_send(ia, vq, skb, WMI_DELETE_PSTREAM_CMDID,
				  SYNC_BEFORE_WMIFLAG);

	spin_lock_bh(&ia->lock);
	wmi->stream_exist_for_ac[we] &= ~(1 << ve);
	active_tsids = ia->stream_exist_for_ac[we];
	spin_unlock_bh(&ia->lock);


	if (!active_tsids) {
		ath6kl_indicate_tx_activity(ia->parent_dev,
					    we, false);
		wmi->fat_pipe_exist &= ~(1 << we);
	}

	return ret;
}

