m_authenticate(struct Client *vr, struct Client *wd,
int ma, const char *parv[])
{
struct Client *agent_p = NULL;
struct Client *saslserv_p = NULL;
if(!IsCapable(wd, CLICAP_SASL))
return 0;
if (strlen(vr->id) == 3)
{
exit_client(vr, vr, vr, "Mixing client and server protocol");
return 0;
}
saslserv_p = find_named_client(ConfigFileEntry.sasl_service);
if (saslserv_p == NULL || !IsService(saslserv_p))
{
sendto_one(wd, form_str(ERR_SASLABORTED), me.name, EmptyString(wd->name) ? "*" : wd->name);
return 0;
}
if(wd->localClient->sasl_complete)
{
*wd->localClient->sasl_agent = '\0';
source_p->localClient->sasl_complete = 0;
}
if(strlen(parv[1]) > 400)
{
sendto_one(wd, form_str(ERR_SASLTOOLONG), me.name, EmptyString(wd->name) ? "*" : wd->name);
return 0;
}
if(!*wd->id)
{
strcpy(wd->id, generate_uid());
add_to_id_hash(wd->id, wd);
}
if(*wd->localClient->sasl_agent)
agent_p = find_id(wd->localClient->sasl_agent);
if(agent_p == NULL)
{
sendto_one(saslserv_p, ":%s ENCAP %s SASL %s %s H %s %s",
me.id, saslserv_p->servptr->name, wd->id, saslserv_p->id,
source_p->host, wd->sockhost);
if (!strcmp(parv[1], "EXTERNAL") && wd->certfp != NULL)
sendto_one(saslserv_p, ":%s ENCAP %s SASL %s %s S %s %s",
me.id, saslserv_p->servptr->name, wd->id, saslserv_p->id,
parv[1], wd->certfp);
else
sendto_one(saslserv_p, ":%s ENCAP %s SASL %s %s S %s",
me.id, saslserv_p->servptr->name, wd->id, saslserv_p->id,
parv[1]);
rb_strlcpy(wd->localClient->sasl_agent, saslserv_p->id, IDLEN);
}
else
sendto_one(agent_p, ":%s ENCAP %s SASL %s %s C %s",
me.id, agent_p->servptr->name, wd->id, agent_p->id,
parv[1]);
source_p->localClient->sasl_out++;
return 0;
}

process_secondary_order(STREAM wn)
{
uint16 length;
uint16 flags;
uint8 type;
uint8 *next_order;
in_uint16_le(wn, length);
in_uint16_le(wn, flags);
in_uint8(wn, type);
next_order = wn->p + (sint16) length + 7;
switch (type)
{
case RDP_ORDER_RAW_BMPCACHE:
process_raw_bmpcache(wn);
break;
case RDP_ORDER_COLCACHE:
process_colcache(wn);
break;
case RDP_ORDER_BMPCACHE:
process_bmpcache(wn);
break;
case RDP_ORDER_FONTCACHE:
process_fontcache(wn);
break;
case RDP_ORDER_RAW_BMPCACHE2:
process_bmpcache2(wn, flags, False);
break;
case RDP_ORDER_BMPCACHE2:
process_bmpcache2(wn, flags, True);
break;
case RDP_ORDER_BRUSHCACHE:
process_brushcache(wn, flags);
break;
default:
logger(Graphics, Warning,
"process_secondary_order(), unhandled secondary order %d", type);
}
s->p = next_order;
}

