ZEND_API void bt(zend_object_handle vq, const zend_object_handlers *handlers vt)
{
struct _store_object *obj;
int failure = 0;
if (!EG(objects_store).object_buckets) {
return;
}
obj = &EG(objects_store).object_buckets[vq].bucket.obj;
if (EG(objects_store).object_buckets[vq].valid) {
if (obj->refcount == 1) {
if (!EG(objects_store).object_buckets[vq].destructor_called) {
EG(objects_store).object_buckets[vq].destructor_called = 1;
if (obj->dtor) {
if (handlers && !obj->handlers) {
obj->handlers = handlers;
}
zend_try {
obj->dtor(obj->object, vq TSRMLS_CC);
} zend_catch {
failure = 1;
} zend_end_try();
}
}
obj = &EG(objects_store).object_buckets[vq].bucket.obj;
if (obj->refcount == 1) {
GC_REMOVE_ZOBJ_FROM_BUFFER(obj);
if (obj->free_storage) {
zend_try {
obj->free_storage(obj->object TSRMLS_CC);
} zend_catch {
failure = 1;
} zend_end_try();
}
ZEND_OBJECTS_STORE_ADD_TO_FREE_LIST();
}
}
}
obj->refcount--;
#if ZEND_DEBUG_OBJECTS
if (obj->refcount == 0) {
fprintf(stderr, "Deallocated object id #%d\n", vq);
} else {
fprintf(stderr, "Decreased refcount of object id #%d\n", vq);
}
#endif
if (failure) {
zend_bailout();
}
}

