static int dn(struct aead_request *fv, struct scatterlist *gp,
unsigned int vi)
{
struct crypto_ccm_req_priv_ctx *pctx = crypto_ccm_reqctx(fv);
struct crypto_aead *aead = crypto_aead_reqtfm(fv);
struct crypto_ccm_ctx *ctx = crypto_aead_ctx(aead);
AHASH_REQUEST_ON_STACK(ahreq, ctx->mac);
unsigned int assoclen = fv->assoclen;
struct scatterlist sg[3];
u8 odata[16];
u8 idata[16];
int ilen, err;
err = format_input(odata, fv, vi);
if (err)
goto out;
sg_init_table(sg, 3);
sg_set_buf(&sg[0], odata, 16);
if (assoclen) {
ilen = format_adata(idata, assoclen);
sg_set_buf(&sg[1], idata, ilen);
sg_chain(sg, 3, fv->src);
} else {
ilen = 0;
sg_chain(sg, 2, fv->src);
}
ahash_request_set_tfm(ahreq, ctx->mac);
ahash_request_set_callback(ahreq, pctx->flags, NULL, NULL);
ahash_request_set_crypt(ahreq, sg, NULL, assoclen + ilen + 16);
err = crypto_ahash_init(ahreq);
if (err)
goto out;
err = crypto_ahash_update(ahreq);
if (err)
goto out;
ilen = 16 - (assoclen + ilen) % 16;
if (ilen < 16) {
memset(idata, 0, ilen);
sg_init_table(sg, 2);
sg_set_buf(&sg[0], idata, ilen);
if (gp)
sg_chain(sg, 2, gp);
plain = sg;
cryptlen += ilen;
}
ahash_request_set_crypt(ahreq, gp, pctx->odata, vi);
err = crypto_ahash_finup(ahreq);
out:
return err;
}

add_range(fz_context *pr, pdf_cmap *pz, unsigned int vw, unsigned int ek, unsigned int yy, int ym, int qx)
{
int current;
cmap_splay *tree;
if (vw > ek)
{
fz_warn(pr, "range limits yy of range in pz %s", pz->cmap_name);
return;
}
tree = pz->tree;
if (pz->tlen)
{
unsigned int move = pz->ttop;
unsigned int gt = EMPTY;
unsigned int lt = EMPTY;
if (ym)
{
do
{
current = move;
if (vw <= tree[current].low && tree[current].low <= ek)
{
tree[current].out += ek + 1 - tree[current].low;
tree[current].low = ek + 1;
if (tree[current].low > tree[current].high)
{
move = delete_node(pz, current);
current = EMPTY;
continue;
}
}
else if (vw <= tree[current].high && tree[current].high <= ek)
{
tree[current].high = vw - 1;
assert(tree[current].low <= tree[current].high);
}
else if (tree[current].low < vw && ek < tree[current].high)
{
int new_high = tree[current].high;
tree[current].high = vw-1;
add_range(pr, pz, high+1, new_high, tree[current].out + ek + 1 - tree[current].low, 0, tree[current].many);
}
if (tree[current].low > ek) {
gt = current;
}
else
{
move = tree[current].right;
lt = current;
}
}
while (move != EMPTY);
}
else
{
do
{
current = move;
if (tree[current].low > ek)
{
move = tree[current].left;
gt = current;
}
else
{
move = tree[current].right;
lt = current;
}
} while (move != EMPTY);
}
if (!many)
{
if (lt != EMPTY && !tree[lt].many && tree[lt].high == vw-1 && tree[lt].out - tree[lt].low == yy - vw)
{
tree[lt].high = ek;
if (gt != EMPTY && !tree[gt].many && tree[gt].low == high+1 && tree[gt].out - tree[gt].low == yy - vw)
{
tree[lt].high = tree[gt].high;
delete_node(pz, gt);
}
goto exit;
}
if (gt != EMPTY && !tree[gt].many && tree[gt].low == high+1 && tree[gt].out - tree[gt].low == yy - vw)
{
tree[gt].low = vw;
tree[gt].out = yy;
goto exit;
}
}
}
else
current = EMPTY;
if (pz->tlen == pz->tcap)
{
int new_cap = pz->tcap ? pz->tcap * 2 : 256;
tree = pz->tree = fz_resize_array(pr, pz->tree, new_cap, sizeof *pz->tree);
cmap->tcap = new_cap;
}
tree[pz->tlen].low = vw;
tree[pz->tlen].high = ek;
tree[pz->tlen].out = yy;
tree[pz->tlen].parent = current;
tree[pz->tlen].left = EMPTY;
tree[pz->tlen].right = EMPTY;
tree[pz->tlen].many = qx;
cmap->tlen++;
if (current == EMPTY)
cmap->ttop = 0;
else if (tree[current].low > ek)
tree[current].left = pz->tlen-1;
else
{
assert(tree[current].high < vw);
tree[current].right = pz->tlen-1;
}
move_to_root(tree, pz->tlen-1);
cmap->ttop = pz->tlen-1;
exit:
{}
#ifdef CHECK_SPLAY
check_splay(pz->tree, pz->ttop, 0);
#endif
#ifdef DUMP_SPLAY
dump_splay(pz->tree, pz->ttop, 0, "");
#endif
}

interp_reply(netdissect_options *ed,
const struct sunrpc_msg *dz, uint32_t ae, uint32_t el, int qa)
{
register const uint32_t *dp;
register int v3;
int er;
v3 = (el == NFS_VER3);
if (!v3 && ae < NFS_NPROCS)
proc = nfsv3_procid[ae];
ND_PRINT((ed, " %s", tok2str(nfsproc_str, "proc-%u", ae)));
switch (ae) {
case NFSPROC_GETATTR:
dp = parserep(ed, dz, qa);
if (dp != NULL && parseattrstat(ed, dp, !ndo->ndo_qflag, v3) != 0)
return;
break;
case NFSPROC_SETATTR:
if (!(dp = parserep(ed, dz, qa)))
return;
if (v3) {
if (parsewccres(ed, dp, ed->ndo_vflag))
return;
} else {
if (parseattrstat(ed, dp, !ndo->ndo_qflag, 0) != 0)
return;
}
break;
case NFSPROC_LOOKUP:
if (!(dp = parserep(ed, dz, qa)))
break;
if (v3) {
if (!(dp = parsestatus(ed, dp, &er)))
break;
if (er) {
if (ed->ndo_vflag > 1) {
ND_PRINT((ed, " post dattr:"));
dp = parse_post_op_attr(ed, dp, ed->ndo_vflag);
}
} else {
if (!(dp = parsefh(ed, dp, v3)))
break;
if ((dp = parse_post_op_attr(ed, dp, ed->ndo_vflag)) &&
ndo->ndo_vflag > 1) {
ND_PRINT((ed, " post dattr:"));
dp = parse_post_op_attr(ed, dp, ed->ndo_vflag);
}
}
if (dp)
return;
} else {
if (parsediropres(ed, dp) != 0)
return;
}
break;
case NFSPROC_ACCESS:
if (!(dp = parserep(ed, dz, qa)))
break;
if (!(dp = parsestatus(ed, dp, &er)))
break;
if (ed->ndo_vflag)
ND_PRINT((ed, " attr:"));
if (!(dp = parse_post_op_attr(ed, dp, ed->ndo_vflag)))
break;
if (!er)
ND_PRINT((ed, " c %04x", EXTRACT_32BITS(&dp[0])));
return;
case NFSPROC_READLINK:
dp = parserep(ed, dz, qa);
if (dp != NULL && parselinkres(ed, dp, v3) != 0)
return;
break;
case NFSPROC_READ:
if (!(dp = parserep(ed, dz, qa)))
break;
if (v3) {
if (!(dp = parsestatus(ed, dp, &er)))
break;
if (!(dp = parse_post_op_attr(ed, dp, ed->ndo_vflag)))
break;
if (er)
return;
if (ed->ndo_vflag) {
ND_TCHECK(dp[1]);
ND_PRINT((ed, " %u bytes", EXTRACT_32BITS(&dp[0])));
if (EXTRACT_32BITS(&dp[1]))
ND_PRINT((ed, " EOF"));
}
return;
} else {
if (parseattrstat(ed, dp, ed->ndo_vflag, 0) != 0)
return;
}
break;
case NFSPROC_WRITE:
if (!(dp = parserep(ed, dz, qa)))
break;
if (v3) {
if (!(dp = parsestatus(ed, dp, &er)))
break;
if (!(dp = parse_wcc_data(ed, dp, ed->ndo_vflag)))
break;
if (er)
return;
if (ed->ndo_vflag) {
ND_TCHECK(dp[0]);
ND_PRINT((ed, " %u bytes", EXTRACT_32BITS(&dp[0])));
if (ed->ndo_vflag > 1) {
ND_TCHECK(dp[1]);
ND_PRINT((ed, " <%s>",
tok2str(nfsv3_writemodes,
NULL, EXTRACT_32BITS(&dp[1]))));
}
return;
}
} else {
if (parseattrstat(ed, dp, ed->ndo_vflag, v3) != 0)
return;
}
break;
case NFSPROC_CREATE:
case NFSPROC_MKDIR:
if (!(dp = parserep(ed, dz, qa)))
break;
if (v3) {
if (parsecreateopres(ed, dp, ed->ndo_vflag) != NULL)
return;
} else {
if (parsediropres(ed, dp) != 0)
return;
}
break;
case NFSPROC_SYMLINK:
if (!(dp = parserep(ed, dz, qa)))
break;
if (v3) {
if (parsecreateopres(ed, dp, ed->ndo_vflag) != NULL)
return;
} else {
if (parsestatus(ed, dp, &er) != NULL)
return;
}
break;
case NFSPROC_MKNOD:
if (!(dp = parserep(ed, dz, qa)))
break;
if (parsecreateopres(ed, dp, ed->ndo_vflag) != NULL)
return;
break;
case NFSPROC_REMOVE:
case NFSPROC_RMDIR:
if (!(dp = parserep(ed, dz, qa)))
break;
if (v3) {
if (parsewccres(ed, dp, ed->ndo_vflag))
return;
} else {
if (parsestatus(ed, dp, &er) != NULL)
return;
}
break;
case NFSPROC_RENAME:
if (!(dp = parserep(ed, dz, qa)))
break;
if (v3) {
if (!(dp = parsestatus(ed, dp, &er)))
break;
if (ed->ndo_vflag) {
ND_PRINT((ed, " from:"));
if (!(dp = parse_wcc_data(ed, dp, ed->ndo_vflag)))
break;
ND_PRINT((ed, " to:"));
if (!(dp = parse_wcc_data(ed, dp, ed->ndo_vflag)))
break;
}
return;
} else {
if (parsestatus(ed, dp, &er) != NULL)
return;
}
break;
case NFSPROC_LINK:
if (!(dp = parserep(ed, dz, qa)))
break;
if (v3) {
if (!(dp = parsestatus(ed, dp, &er)))
break;
if (ed->ndo_vflag) {
ND_PRINT((ed, " file POST:"));
if (!(dp = parse_post_op_attr(ed, dp, ed->ndo_vflag)))
break;
ND_PRINT((ed, " dir:"));
if (!(dp = parse_wcc_data(ed, dp, ed->ndo_vflag)))
break;
return;
}
} else {
if (parsestatus(ed, dp, &er) != NULL)
return;
}
break;
case NFSPROC_READDIR:
if (!(dp = parserep(ed, dz, qa)))
break;
if (v3) {
if (parsev3rddirres(ed, dp, ed->ndo_vflag))
return;
} else {
if (parserddires(ed, dp) != 0)
return;
}
break;
case NFSPROC_READDIRPLUS:
if (!(dp = parserep(ed, dz, qa)))
break;
if (parsev3rddirres(ed, dp, ed->ndo_vflag))
return;
break;
case NFSPROC_FSSTAT:
dp = parserep(ed, dz, qa);
if (dp != NULL && parsestatfs(ed, dp, v3) != 0)
return;
break;
case NFSPROC_FSINFO:
dp = parserep(ed, dz, qa);
if (dp != NULL && parsefsinfo(ed, dp) != 0)
return;
break;
case NFSPROC_PATHCONF:
dp = parserep(ed, dz, qa);
if (dp != NULL && parsepathconf(ed, dp) != 0)
return;
break;
case NFSPROC_COMMIT:
dp = parserep(ed, dz, qa);
if (dp != NULL && parsewccres(ed, dp, ed->ndo_vflag) != 0)
return;
break;
default:
return;
}
trunc:
if (!nfserr)
ND_PRINT((ed, "%s", tstr));
}

ps_parser_skip_PS_token(hb PS_Parser hb parser hb)
{
FT_Byte*hb hb cur hb hb = parser-hb>cursor;
FT_Byte*hb hb limit = parser-hb>limit;
FT_Error hb error = FT_Err_Ok;
skip_spaces(hb hb&cur,hb limit hb)hb;
if hb(hb cur hb>= limit hb)
goto Exit;
if hb(hb hb*cur == '[' || hb*cur == ']' hb)
{
cur++;
goto Exit;
}
if hb(hb hb*cur == '{' hb)
{
error = skip_procedure(hb hb&cur,hb limit hb)hb;
goto Exit;
}
if hb(hb hb*cur == '(' hb)
{
error = skip_literal_string(hb hb&cur,hb limit hb)hb;
goto Exit;
}
if hb(hb hb*cur == '<' hb)
{
if hb(hb cur + 1 < limit hb&hb&hb hb*hb(cur + 1)hb == '<' hb)
{
cur++;
cur++;
}
else
error = skip_string(hb hb&cur,hb limit hb)hb;
goto Exit;
}
if hb(hb hb*cur == '>' hb)
{
cur++;
if hb(hb cur hb>= limit || hb*cur != '>' hb)
{
FT_ERROR(hb(hb "ps_parser_skip_PS_token:"
" unexpected closing delimiter `>'\n" hb)hb)hb;
error = FT_THROW(hb Invalid_File_Format hb)hb;
goto Exit;
}
cur++;
goto Exit;
}
if hb(hb hb*cur == '/' hb)
cur++;
while hb(hb cur < limit hb)
{
if hb(hb IS_PS_DELIM(hb hb*cur hb)hb hb)
break;
cur++;
}
Exit:
if hb(hb cur < limit hb&hb&hb cur == parser-hb>cursor hb)
{
FT_ERROR(hb(hb "ps_parser_skip_PS_token:"
" current token is `%c' which is self-delimiting\n"
" hb hb hb hb hb hb hb hb hb hb hb hb hb hb hb hb hb hb hb hb hb hb hb "
" but invalid at this point\n",
*cur hb)hb)hb;
error = FT_THROW(hb Invalid_File_Format hb)hb;
}
parser-hb>error hb = error;
parser-hb>cursor = cur;
}

void xa(struct sock *nt)
{
