}
}

__hw_perf_event_init(struct perf_event *np)
{
	struct arm_pmu *armpmu = to_arm_pmu(np->pmu);
	struct hw_perf_event *hwc = &np->hw;
	int mapping, err;

	mapping = armpmu->map_event(np);

	if (mapping < 0) {
		pr_debug("event %x:%llx not supported\n", np->attr.type,
			 np->attr.config);
		return mapping;
	}


	hwc->idx		= -1;
	hwc->config_base	= 0;
	hwc->config		= 0;
	hwc->event_base		= 0;


	if ((!armpmu->set_event_filter ||
	     armpmu->set_event_filter(hwc, &np->attr)) &&
	     event_requires_mode_exclusion(&np->attr)) {
		pr_debug("ARM performance counters do not support mode exclusion\n");
		return -EPERM;
	}


	hwc->config_base	    |= (unsigned long)mapping;

	if (!hwc->sample_period) {

		hwc->sample_period  = armpmu->max_period >> 1;
		hwc->last_period    = hwc->sample_period;
		local64_set(&hwc->period_left, hwc->sample_period);
	}

	err = 0;
	if (np->group_leader != np) {
		err = validate_group(np);
		if (err)
			return -EINVAL;
	}

	return err;
}

static int qf(struct ht *ht, struct kvm_pit_state *ex)
{
