void dw(jas_matrix_t *ng, jas_seqent_t pw,
jas_seqent_t zz)
{
int i;
int j;
jas_seqent_t v;
jas_seqent_t *rowstart;
jas_seqent_t *data;
int rowstep;
if (jas_matrix_numrows(ng) > 0 && jas_matrix_numcols(ng) > 0) {
assert(ng->rows_);
rowstep = jas_matrix_rowstep(ng);
for (i = ng->numrows_, rowstart = ng->rows_[0]; i > 0; --i,
rowstart += rowstep) {
data = rowstart;
for (j = ng->numcols_, data = rowstart; j > 0; --j,
++data) {
v = *data;
if (v < pw) {
*data = pw;
} else if (v > zz) {
*data = zz;
}
}
}
}
}

