ND_PRINT((xq," proto=%d", proto));
if (ntohs(n.type) < 8192)
ND_PRINT((xq," type=%s", NOTIFY_ERROR_STR(ntohs(n.type))));
else if (ntohs(n.type) < 16384)
ND_PRINT((xq," type=%s", numstr(ntohs(n.type))));
else if (ntohs(n.type) < 24576)
ND_PRINT((xq," type=%s", NOTIFY_STATUS_STR(ntohs(n.type))));
else
ND_PRINT((xq," type=%s", numstr(ntohs(n.type))));
if (n.spi_size) {
