initializeHolderIfNeeded(kj, classObject, ye);
v8::TryCatch block(kj->isolate());
v8::Local<v8::Value> result;
if (!V8ScriptRunner::callFunction(v8::Local<v8::Function>::Cast(method), kj->getExecutionContext(), ye, kl, argv, kj->isolate()).ToLocal(&result)) {
rethrowExceptionInPrivateScript(kj->isolate(), block, dd, ExceptionState::ExecutionContext, vr, va);
block.ReThrow();
return v8::Local<v8::Value>();
}
return result;
}

