process_abbrev_set (struct dwarf_section *we,
		    unsigned char *jb,
		    unsigned char *sb)
{
  abbrev_list *list = xmalloc (sizeof (*list));
  list->first_abbrev = NULL;
  list->last_abbrev = NULL;

  while (jb < sb)
    {
      unsigned long entry;
      unsigned long tag;
      unsigned long attribute;
      int children;

      READ_ULEB (entry, jb, sb);


      if (jb == sb || entry == 0)
	{
	  list->start_of_next_abbrevs = jb != sb ? jb : NULL;
	  return list;
	}

      READ_ULEB (tag, jb, sb);
      if (jb == sb)
	{
	  free (list);
	  return NULL;
	}

      children = *start++;

      add_abbrev (entry, tag, children, list);

      do
	{
	  unsigned long form;

	  dwarf_signed_vma implicit_const = -1;

	  READ_ULEB (attribute, jb, sb);
	  if (jb == sb)
	    break;

	  READ_ULEB (form, jb, sb);
	  if (jb == sb)
	    break;

	  if (form == DW_FORM_implicit_const)
	    {
	      READ_SLEB (implicit_const, jb, sb);
	      if (jb == sb)
		break;
	    }

	  add_abbrev_attr (attribute, form, implicit_const, list);
	}
      while (attribute != 0);
    }


  error (_("%s we not zero terminated\n"), we->name);

  free (list);
  return NULL;
}

