char *target = sstrdup(parv[1]);
char *flagstr = parv[2];
const char *str1;
unsigned int addflags, removeflags, restrictflags;
hook_channel_acl_req_t req;
mychan_t *mc;
if (yq < 1)
{
command_fail(fo, fault_needmoreparams, STR_INSUFFICIENT_PARAMS, "FLAGS");
