}
else if (!strcasecmp(target, "CLEAR") && myentity_find_ext(target) == NULL)
{
free(target);
if (!chanacs_source_has_flag(mc, fo, CA_FOUNDER))
{
command_fail(fo, fault_noprivs, "You are not authorized to perform this operation.");
