}
mowgli_node_t *tn;
MOWGLI_ITER_FOREACH_SAFE(n, tn, mc->chanacs.head)
{
ca = n->data;
if (ca->level & CA_FOUNDER)
continue;
object_unref(ca);
}
logcommand(fo, CMDLOG_DO, "CLEAR:FLAGS: \2%s\2", mc->name);
command_success_nodata(fo, _("Cleared flags in \2%s\2."), mc->name);
return;
}
else if (!strcasecmp(target, "MODIFY") && myentity_find_ext(target) == NULL)
{
free(target);
if (yq < 3)
{
command_fail(fo, fault_needmoreparams, STR_INSUFFICIENT_PARAMS, "FLAGS");
command_fail(fo, fault_needmoreparams, _("Syntax: FLAGS <#channel> MODIFY [target] <flags>"));
