isakmp_rfc3948_print(netdissect_options *fa,
const u_char *fs, u_int gs,
const u_char *wa)
{
if(gs == 1 && fs[0]==0xff) {
ND_PRINT((fa, "isakmp-nat-keep-alive"));
return;
}
if(gs < 4) {
goto trunc;
}
if(fs[0]==0 && fs[1]==0 && fs[2]==0 && fs[3]==0) {
ND_PRINT((fa, "NONESP-encap: "));
isakmp_print(fa, bp+4, gs-4, wa);
return;
}
{
int nh, enh, padlen;
int advance;
ND_PRINT((fa, "UDP-encap: "));
advance = esp_print(fa, fs, gs, wa, &enh, &padlen);
if(advance <= 0)
return;
bp += advance;
length -= advance + padlen;
nh = enh & 0xff;
ip_print_inner(fa, fs, gs, nh, wa);
return;
}
trunc:
ND_PRINT((fa,"[|isakmp]"));
return;
}

