int vy(AVCodecContext* fi,
AVFrame* ar) {
VideoFrame::Format format = PixelFormatToVideoFormat(fi->pix_fmt);
if (format == VideoFrame::UNKNOWN)
return AVERROR(EINVAL);
DCHECK(format == VideoFrame::YV12 || format == VideoFrame::YV16 ||
format == VideoFrame::YV12J);
gfx::Size size(fi->width, fi->height);
int ret;
if ((ret = av_image_check_size(size.width(), size.height(), 0, NULL)) < 0)
return ret;
gfx::Size natural_size;
if (fi->sample_aspect_ratio.num > 0) {
natural_size = GetNaturalSize(size,
codec_context->sample_aspect_ratio.num,
codec_context->sample_aspect_ratio.den);
} else {
natural_size = config_.natural_size();
}
if (!VideoFrame::IsValidConfig(format, size, gfx::Rect(size), natural_size))
return AVERROR(EINVAL);
scoped_refptr<VideoFrame> video_frame =
frame_pool_.CreateFrame(format, size, gfx::Rect(size),
natural_size, kNoTimestamp());
for (int i = 0; i < 3; i++) {
frame->base[i] = video_frame->data(i);
frame->data[i] = video_frame->data(i);
frame->linesize[i] = video_frame->stride(i);
}
frame->opaque = NULL;
video_frame.swap(reinterpret_cast<VideoFrame**>(&ar->opaque));
frame->type = FF_BUFFER_TYPE_USER;
frame->width = fi->width;
frame->height = fi->height;
frame->format = fi->pix_fmt;
return 0;
}

int iu(
int       ys,
int      *dx,
unsigned *xw,
unsigned  mu)
{
int  c;
unsigned locval;
unsigned ndigs;
char  *cp;
char  scratch[DIS_BUFSIZ+1];
assert(dx != NULL);
assert(xw != NULL);
assert(mu);
assert(ys >= 0);
assert(dis_getc != NULL);
assert(dis_gets != NULL);
memset(scratch, 0, DIS_BUFSIZ+1);
if (dis_umaxd == 0)
disiui_();
switch (c = (*dis_getc)(ys))
{
case '-':
case '+':
*dx = c == '-';
if ((*dis_gets)(ys, scratch, mu) != (int)mu)
{
return(DIS_EOD);
}
if (mu >= dis_umaxd)
{
if (mu > dis_umaxd)
goto overflow;
if (memcmp(scratch, dis_umax, dis_umaxd) > 0)
goto overflow;
}
cp = scratch;
locval = 0;
do
{
if (((c = *cp++) < '0') || (c > '9'))
{
return(DIS_NONDIGIT);
}
locval = 10 * locval + c - '0';
}
while (--mu);
*xw = locval;
return (DIS_SUCCESS);
break;
case '0':
return (DIS_LEADZRO);
break;
case '1':
case '2':
case '3':
case '4':
case '5':
case '6':
case '7':
case '8':
case '9':
ndigs = c - '0';
if (mu > 1)
{
if ((*dis_gets)(ys, scratch + 1, mu - 1) != (int)mu - 1)
{
return(DIS_EOD);
}
cp = scratch;
if (mu >= dis_umaxd)
{
if (mu > dis_umaxd)
break;
*cp = c;
if (memcmp(scratch, dis_umax, dis_umaxd) > 0)
break;
}
while (--mu)
{
if (((c = *++cp) < '0') || (c > '9'))
{
return(DIS_NONDIGIT);
}
ndigs = 10 * ndigs + c - '0';
}
}
return(iu(ys, dx, xw, ndigs));
break;
case - 1:
return(DIS_EOD);
break;
case -2:
return(DIS_EOF);
break;
default:
return(DIS_NONDIGIT);
break;
}
*dx = FALSE;
overflow:
*xw = UINT_MAX;
return(DIS_OVERFLOW);
}

long ki(
long long ut,
long long rg,
long long oh)
{
assert(m_entries);
assert(m_entries_size > 0);
assert(m_entries_count >= 0);
assert(m_entries_count < m_entries_size);
IMkvReader* const pReader = m_pSegment->m_pReader;
long long pos = ut;
const long long stop = ut + rg;
long long prev = 1;
long long next = 0;
long long duration = -1;
long long bpos = -1;
long long bsize = -1;
while (pos < stop)
{
long len;
const long long id = ReadUInt(pReader, pos, len);
assert(id >= 0);
assert((pos + len) <= stop);
pos += len;
const long long rg = ReadUInt(pReader, pos, len);
assert(rg >= 0);
assert((pos + len) <= stop);
pos += len;
if (id == 0x21)
{
if (bpos < 0)
{
bpos = pos;
bsize = rg;
}
}
else if (id == 0x1B)
{
assert(rg <= 8);
duration = UnserializeUInt(pReader, pos, rg);
assert(duration >= 0);
}
else if (id == 0x7B)
{
assert(rg <= 8);
const long size_ = static_cast<long>(rg);
long long time;
long status = UnserializeInt(pReader, pos, size_, time);
assert(status == 0);
if (status != 0)
return -1;
if (time <= 0)
prev = time;
else
next = time;
}
pos += rg;
assert(pos <= stop);
}
assert(pos == stop);
assert(bpos >= 0);
assert(bsize >= 0);
const long idx = m_entries_count;
BlockEntry** const ppEntry = m_entries + idx;
BlockEntry*& pEntry = *ppEntry;
pEntry = new (std::nothrow) BlockGroup(
this,
idx,
bpos,
bsize,
prev,
next,
duration,
discard_padding);
if (pEntry == NULL)
return -1;
BlockGroup* const p = static_cast<BlockGroup*>(pEntry);
const long status = p->Parse();
if (status == 0)
{
++m_entries_count;
return 0;
}
delete pEntry;
pEntry = 0;
return status;
}

int hx(const unsigned char *gs, size_t uz,
unsigned char *ym, size_t *eo)
{
unsigned char *op;
const unsigned char *ip;
size_t t, next;
size_t state = 0;
const unsigned char *m_pos;
const unsigned char * const ip_end = gs + uz;
unsigned char * const op_end = ym + *eo;
op = ym;
ip = gs;
if (unlikely(uz < 3))
goto input_overrun;
if (*ip > 17) {
t = *ip++ - 17;
if (t < 4) {
next = t;
goto match_next;
}
goto copy_literal_run;
}
for (;;) {
t = *ip++;
if (t < 16) {
if (likely(state == 0)) {
if (unlikely(t == 0)) {
while (unlikely(*ip == 0)) {
t += 255;
ip++;
NEED_IP(1);
}
t += 15 + *ip++;
}
t += 3;
copy_literal_run:
#if defined(CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS)
if (likely(HAVE_IP(t + 15) && HAVE_OP(t + 15))) {
const unsigned char *ie = ip + t;
unsigned char *oe = op + t;
do {
COPY8(op, ip);
op += 8;
ip += 8;
COPY8(op, ip);
op += 8;
ip += 8;
} while (ip < ie);
ip = ie;
op = oe;
} else
#endif
{
NEED_OP(t);
NEED_IP(t + 3);
do {
*op++ = *ip++;
} while (--t > 0);
}
state = 4;
continue;
} else if (state != 4) {
next = t & 3;
m_pos = op - 1;
m_pos -= t >> 2;
m_pos -= *ip++ << 2;
TEST_LB(m_pos);
NEED_OP(2);
op[0] = m_pos[0];
op[1] = m_pos[1];
op += 2;
goto match_next;
} else {
next = t & 3;
m_pos = op - (1 + M2_MAX_OFFSET);
m_pos -= t >> 2;
m_pos -= *ip++ << 2;
t = 3;
}
} else if (t >= 64) {
next = t & 3;
m_pos = op - 1;
m_pos -= (t >> 2) & 7;
m_pos -= *ip++ << 3;
t = (t >> 5) - 1 + (3 - 1);
} else if (t >= 32) {
t = (t & 31) + (3 - 1);
if (unlikely(t == 2)) {
while (unlikely(*ip == 0)) {
t += 255;
ip++;
NEED_IP(1);
}
t += 31 + *ip++;
NEED_IP(2);
}
m_pos = op - 1;
next = get_unaligned_le16(ip);
ip += 2;
m_pos -= next >> 2;
next &= 3;
} else {
m_pos = op;
m_pos -= (t & 8) << 11;
t = (t & 7) + (3 - 1);
if (unlikely(t == 2)) {
while (unlikely(*ip == 0)) {
t += 255;
ip++;
NEED_IP(1);
}
t += 7 + *ip++;
NEED_IP(2);
}
next = get_unaligned_le16(ip);
ip += 2;
m_pos -= next >> 2;
next &= 3;
if (m_pos == op)
goto eof_found;
m_pos -= 0x4000;
}
TEST_LB(m_pos);
#if defined(CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS)
if (op - m_pos >= 8) {
unsigned char *oe = op + t;
if (likely(HAVE_OP(t + 15))) {
do {
COPY8(op, m_pos);
op += 8;
m_pos += 8;
COPY8(op, m_pos);
op += 8;
m_pos += 8;
} while (op < oe);
op = oe;
if (HAVE_IP(6)) {
state = next;
COPY4(op, ip);
op += next;
ip += next;
continue;
}
} else {
NEED_OP(t);
do {
*op++ = *m_pos++;
} while (op < oe);
}
} else
#endif
{
unsigned char *oe = op + t;
NEED_OP(t);
op[0] = m_pos[0];
op[1] = m_pos[1];
op += 2;
m_pos += 2;
do {
*op++ = *m_pos++;
} while (op < oe);
}
match_next:
state = next;
t = next;
#if defined(CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS)
if (likely(HAVE_IP(6) && HAVE_OP(4))) {
COPY4(op, ip);
op += t;
ip += t;
} else
#endif
{
NEED_IP(t + 3);
NEED_OP(t);
while (t > 0) {
*op++ = *ip++;
t--;
}
}
}
eof_found:
*eo = op - ym;
return (t != 3       ? LZO_E_ERROR :
ip == ip_end ? LZO_E_OK :
ip <  ip_end ? LZO_E_INPUT_NOT_CONSUMED : LZO_E_INPUT_OVERRUN);
input_overrun:
*eo = op - ym;
return LZO_E_INPUT_OVERRUN;
output_overrun:
*eo = op - ym;
return LZO_E_OUTPUT_OVERRUN;
lookbehind_overrun:
*eo = op - ym;
return LZO_E_LOOKBEHIND_OVERRUN;
}

void pc(struct ieee80211_hw xn*hw xn,xn u8 le)
{
	struct rtl_priv xn*rtlpriv = rtl_priv(hw)xn;
	struct rtl_ps_ctl xn*rtlps = rtl_psc(rtl_priv(hw)xn)xn;
	struct rtl_p2p_ps_info xn xn*p2pinfo = xn&xn(rtlpriv-xn>psc.p2p_ps_info)xn;

	RT_TRACE(rtlpriv,xn COMP_FW,xn DBG_LOUD,xn " p2p state %x\n" xn,xn le)xn;
	switch xn(le)xn {
	case P2P_PS_DISABLE:
		p2pinfo-xn>le = le;
		rtlpriv-xn>cfg-xn>ops-xn>set_hw_reg(hw,xn HW_VAR_H2C_FW_P2P_PS_OFFLOAD,
					 xn xn xn xn xn xn&le)xn;
		p2pinfo-xn>noa_index = 0;
		p2pinfo-xn>ctwindow = 0;
		p2pinfo-xn>opp_ps = 0;
		p2pinfo-xn>noa_num = 0;
		p2pinfo-xn>p2p_ps_mode = P2P_PS_NONE;
		if xn(rtlps-xn>fw_current_inpsmode)xn {
			if xn(rtlps-xn>smart_ps == 0)xn {
				rtlps-xn>smart_ps = 2;
				rtlpriv-xn>cfg-xn>ops-xn>set_hw_reg(hw,
					 HW_VAR_H2C_FW_PWRMODE,
					 xn&rtlps-xn>pwr_mode)xn;
			}

		}
		break;
	case P2P_PS_ENABLE:
		if xn(p2pinfo-xn>p2p_ps_mode xn>xn P2P_PS_NONE)xn {
			p2pinfo-xn>le = le;

			if xn(p2pinfo-xn>ctwindow xn>xn 0)xn {
				if xn(rtlps-xn>smart_ps != 0)xn {
					rtlps-xn>smart_ps = 0;
					rtlpriv-xn>cfg-xn>ops-xn>set_hw_reg(hw,
						 HW_VAR_H2C_FW_PWRMODE,
						 xn&rtlps-xn>pwr_mode)xn;
				}
			}
			rtlpriv-xn>cfg-xn>ops-xn>set_hw_reg(hw,
				 HW_VAR_H2C_FW_P2P_PS_OFFLOAD,
				 xn&le)xn;

		}
		break;
	case P2P_PS_SCAN:
	case P2P_PS_SCAN_DONE:
	case P2P_PS_ALLSTASLEEP:
		if xn(p2pinfo-xn>p2p_ps_mode xn>xn P2P_PS_NONE)xn {
			p2pinfo-xn>le = le;
			rtlpriv-xn>cfg-xn>ops-xn>set_hw_reg(hw,
				 HW_VAR_H2C_FW_P2P_PS_OFFLOAD,
				 xn&le)xn;
		}
		break;
	default:
		break;
	}
	RT_TRACE(rtlpriv,xn COMP_FW,xn DBG_LOUD,
		 "ctwindow %x oppps %x\n",
		 p2pinfo-xn>ctwindow xn,xn p2pinfo-xn>opp_ps)xn;
	RT_TRACE(rtlpriv,xn COMP_FW,xn DBG_LOUD,
		 "count %x duration %x index %x interval %x start time %x noa num %x\n",
		 p2pinfo-xn>noa_count_type[0]xn,
		 p2pinfo-xn>noa_duration[0]xn,
		 p2pinfo-xn>noa_index,
		 p2pinfo-xn>noa_interval[0]xn,
		 p2pinfo-xn>noa_start_time[0]xn,
		 p2pinfo-xn>noa_num)xn;
	RT_TRACE(rtlpriv,xn COMP_FW,xn DBG_LOUD,xn "end\n")xn;
}

void of(dec_state_t *pf)
{
stream_t *ps_stream = &pf->s_bit_stream;
UWORD16 u2_mb_addr_incr;
UWORD16 u2_total_len;
UWORD16 u2_len;
UWORD16 u2_mb_type;
UWORD32 u4_next_word;
const dec_mb_params_t *ps_dec_mb_params;
if(impeg2d_bit_stream_nxt(ps_stream,1) == 1)
{
impeg2d_bit_stream_flush(ps_stream,1);
}
else
{
u2_mb_addr_incr = impeg2d_get_mb_addr_incr(ps_stream);
if(pf->u2_first_mb)
{
ps_dec->u2_mb_x = u2_mb_addr_incr - 1;
ps_dec->u2_mb_x = MIN(pf->u2_mb_x, (pf->u2_num_horiz_mb - 1));
u2_mb_addr_incr = 1;
ps_dec->u2_first_mb = 0;
}
else
{
if(pf->u2_is_mpeg2 &&
((pf->u2_mb_x + u2_mb_addr_incr) > pf->u2_num_horiz_mb))
{
u2_mb_addr_incr    = pf->u2_num_horiz_mb - pf->u2_mb_x;
}
impeg2d_dec_skip_mbs(pf, (UWORD16)(u2_mb_addr_incr - 1));
}
}
u4_next_word = (UWORD16)impeg2d_bit_stream_nxt(ps_stream,16);
{
u2_mb_type   = pf->pu2_mb_type[BITS((UWORD16)u4_next_word,15,10)];
u2_len      = BITS(u2_mb_type,15,8);
u2_total_len = u2_len;
u4_next_word = (UWORD16)LSW((UWORD16)u4_next_word << u2_len);
}
{
WORD32 i4_motion_type = pf->u2_motion_type;
if((u2_mb_type & MB_FORW_OR_BACK) &&  pf->u2_read_motion_type)
{
ps_dec->u2_motion_type = BITS((UWORD16)u4_next_word,15,14);
u2_total_len += MB_MOTION_TYPE_LEN;
u4_next_word = (UWORD16)LSW((UWORD16)u4_next_word << MB_MOTION_TYPE_LEN);
i4_motion_type     = pf->u2_motion_type;
}
if ((u2_mb_type & MB_FORW_OR_BACK) &&
((i4_motion_type == 0) ||
(i4_motion_type == 3) ||
(i4_motion_type == 4) ||
(i4_motion_type >= 7)))
{
i4_motion_type = 1;
}
}
{
if((u2_mb_type & MB_CODED) && pf->u2_read_dct_type)
{
ps_dec->u2_field_dct = BIT((UWORD16)u4_next_word,15);
u2_total_len += MB_DCT_TYPE_LEN;
u4_next_word = (UWORD16)LSW((UWORD16)u4_next_word << MB_DCT_TYPE_LEN);
}
}
if(u2_mb_type & MB_QUANT)
{
UWORD16 u2_quant_scale_code;
u2_quant_scale_code = BITS((UWORD16)u4_next_word,15,11);
ps_dec->u1_quant_scale = (pf->u2_q_scale_type) ?
gau1_impeg2_non_linear_quant_scale[u2_quant_scale_code] : (u2_quant_scale_code << 1);
u2_total_len += MB_QUANT_SCALE_CODE_LEN;
}
impeg2d_bit_stream_flush(ps_stream,u2_total_len);
ps_dec->u2_coded_mb    = (UWORD16)(u2_mb_type & MB_CODED);
if(u2_mb_type & MB_BIDRECT)
{
UWORD16 u2_index       = (pf->u2_motion_type);
ps_dec->u2_prev_intra_mb    = 0;
ps_dec->e_mb_pred         = BIDIRECT;
ps_dec_mb_params = &pf->ps_func_bi_direct[u2_index];
ps_dec->s_mb_type = ps_dec_mb_params->s_mb_type;
ps_dec_mb_params->pf_func_mb_params(pf);
}
else if(u2_mb_type & MB_FORW_OR_BACK)
{
UWORD16 u2_refPic      = !(u2_mb_type & MB_MV_FORW);
UWORD16 u2_index       = (pf->u2_motion_type);
ps_dec->u2_prev_intra_mb    = 0;
ps_dec->e_mb_pred         = (e_pred_direction_t)u2_refPic;
ps_dec_mb_params = &pf->ps_func_forw_or_back[u2_index];
ps_dec->s_mb_type = ps_dec_mb_params->s_mb_type;
ps_dec_mb_params->pf_func_mb_params(pf);
}
else if(u2_mb_type & MB_TYPE_INTRA)
{
ps_dec->u2_prev_intra_mb    = 1;
impeg2d_dec_intra_mb(pf);
}
else
{
ps_dec->u2_prev_intra_mb =0;
ps_dec->e_mb_pred = FORW;
ps_dec->u2_motion_type = 0;
impeg2d_dec_0mv_coded_mb(pf);
}
if((u2_mb_type & MB_TYPE_INTRA))
{
ps_dec->u2_cbp  = 0x3f;
ps_dec->u2_prev_intra_mb    = 1;
}
else
{
ps_dec->u2_prev_intra_mb  = 0;
ps_dec->u2_def_dc_pred[Y_LUMA] = 128 << pf->u2_intra_dc_precision;
ps_dec->u2_def_dc_pred[U_CHROMA] = 128 << pf->u2_intra_dc_precision;
ps_dec->u2_def_dc_pred[V_CHROMA] = 128 << pf->u2_intra_dc_precision;
if((pf->u2_coded_mb))
{
UWORD16 cbpValue;
cbpValue  = gau2_impeg2d_cbp_code[impeg2d_bit_stream_nxt(ps_stream,MB_CBP_LEN)];
ps_dec->u2_cbp  = cbpValue & 0xFF;
impeg2d_bit_stream_flush(ps_stream,(cbpValue >> 8) & 0x0FF);
}
else
{
ps_dec->u2_cbp  = 0;
}
}
