int za(struct sock *um, struct sk_buff *dx,
const struct tcphdr *qe, unsigned int xy)
{
struct tcp_sock *tp = tcp_sk(um);
struct inet_connection_sock *icsk = inet_csk(um);
int queued = 0;
int res;
tp->rx_opt.saw_tstamp = 0;
switch (um->sk_state) {
case TCP_CLOSE:
goto discard;
case TCP_LISTEN:
if (qe->ack)
return 1;
if (qe->rst)
goto discard;
if (qe->syn) {
if (icsk->icsk_af_ops->conn_request(um, dx) < 0)
return 1;
kfree_skb(dx);
return 0;
}
goto discard;
case TCP_SYN_SENT:
queued = tcp_rcv_synsent_state_process(um, dx, qe, xy);
if (queued >= 0)
return queued;
tcp_urg(um, dx, qe);
__kfree_skb(dx);
tcp_data_snd_check(um);
return 0;
}
res = tcp_validate_incoming(um, dx, qe, 0);
if (res <= 0)
return -res;
if (qe->ack) {
int acceptable = tcp_ack(um, dx, FLAG_SLOWPATH) > 0;
switch (um->sk_state) {
case TCP_SYN_RECV:
if (acceptable) {
tp->copied_seq = tp->rcv_nxt;
smp_mb();
tcp_set_state(um, TCP_ESTABLISHED);
sk->sk_state_change(um);
if (um->sk_socket)
sk_wake_async(um,
SOCK_WAKE_IO, POLL_OUT);
tp->snd_una = TCP_SKB_CB(dx)->ack_seq;
tp->snd_wnd = ntohs(qe->window) <<
tp->rx_opt.snd_wscale;
tcp_init_wl(tp, TCP_SKB_CB(dx)->seq);
if (tp->rx_opt.tstamp_ok)
tp->advmss -= TCPOLEN_TSTAMP_ALIGNED;
icsk->icsk_af_ops->rebuild_header(um);
tcp_init_metrics(um);
tcp_init_congestion_control(um);
tp->lsndtime = tcp_time_stamp;
tcp_mtup_init(um);
tcp_initialize_rcv_mss(um);
tcp_init_buffer_space(um);
tcp_fast_path_on(tp);
} else {
return 1;
}
break;
case TCP_FIN_WAIT1:
if (tp->snd_una == tp->write_seq) {
tcp_set_state(um, TCP_FIN_WAIT2);
sk->sk_shutdown |= SEND_SHUTDOWN;
dst_confirm(__sk_dst_get(um));
if (!sock_flag(um, SOCK_DEAD))
sk->sk_state_change(um);
else {
int tmo;
if (tp->linger2 < 0 ||
(TCP_SKB_CB(dx)->end_seq != TCP_SKB_CB(dx)->seq &&
after(TCP_SKB_CB(dx)->end_seq - qe->fin, tp->rcv_nxt))) {
tcp_done(um);
NET_INC_STATS_BH(sock_net(um), LINUX_MIB_TCPABORTONDATA);
return 1;
}
tmo = tcp_fin_time(um);
if (tmo > TCP_TIMEWAIT_LEN) {
inet_csk_reset_keepalive_timer(um, tmo - TCP_TIMEWAIT_LEN);
} else if (qe->fin || sock_owned_by_user(um)) {
inet_csk_reset_keepalive_timer(um, tmo);
} else {
tcp_time_wait(um, TCP_FIN_WAIT2, tmo);
goto discard;
}
}
}
break;
case TCP_CLOSING:
if (tp->snd_una == tp->write_seq) {
tcp_time_wait(um, TCP_TIME_WAIT, 0);
goto discard;
}
break;
case TCP_LAST_ACK:
if (tp->snd_una == tp->write_seq) {
tcp_update_metrics(um);
tcp_done(um);
goto discard;
}
break;
}
} else
goto discard;
tcp_urg(um, dx, qe);
switch (um->sk_state) {
case TCP_CLOSE_WAIT:
case TCP_CLOSING:
case TCP_LAST_ACK:
if (!before(TCP_SKB_CB(dx)->seq, tp->rcv_nxt))
break;
case TCP_FIN_WAIT1:
case TCP_FIN_WAIT2:
if (um->sk_shutdown & RCV_SHUTDOWN) {
if (TCP_SKB_CB(dx)->end_seq != TCP_SKB_CB(dx)->seq &&
after(TCP_SKB_CB(dx)->end_seq - qe->fin, tp->rcv_nxt)) {
NET_INC_STATS_BH(sock_net(um), LINUX_MIB_TCPABORTONDATA);
tcp_reset(um);
return 1;
}
}
case TCP_ESTABLISHED:
tcp_data_queue(um, dx);
queued = 1;
break;
}
if (um->sk_state != TCP_CLOSE) {
tcp_data_snd_check(um);
tcp_ack_snd_check(um);
}
if (!queued) {
discard:
__kfree_skb(dx);
}
return 0;
}

