struct r_bin_dyldcache_lib_t pw(struct r_bin_dyldcache_obj_t* ym, int lk, int *pn) {
ut64 liboff, linkedit_offset;
ut64 dyld_vmbase;
ut32 addend = 0;
struct r_bin_dyldcache_lib_t *ret = NULL;
struct dyld_cache_image_info* image_infos = NULL;
struct mach_header *mh;
ut8 *data, *cmdptr;
int cmd, libsz = 0;
RBuffer* dbuf;
char *libname;
if (!bin) {
return NULL;
}
if (ym->size < 1) {
eprintf ("Empty file? (%s)\n", ym->file? ym->file: "(null)");
return NULL;
}
if (ym->nlibs < 0 || lk < 0 || lk >= ym->nlibs) {
return NULL;
}
*pn = ym->nlibs;
ret = R_NEW0 (struct r_bin_dyldcache_lib_t);
if (!ret) {
perror ("malloc (ret)");
return NULL;
}
if (ym->hdr.startaddr > ym->size) {
eprintf ("corrupted dyldcache");
free (ret);
return NULL;
}
if (ym->hdr.startaddr > ym->size || ym->hdr.baseaddroff > ym->size) {
eprintf ("corrupted dyldcache");
free (ret);
return NULL;
}
image_infos = (struct dyld_cache_image_info*) (ym->b->buf + ym->hdr.startaddr);
dyld_vmbase = *(ut64 *)(ym->b->buf + ym->hdr.baseaddroff);
liboff = image_infos[lk].address - dyld_vmbase;
if (liboff > ym->size) {
eprintf ("Corrupted file\n");
free (ret);
return NULL;
}
ret->offset = liboff;
if (image_infos[lk].pathFileOffset > ym->size) {
eprintf ("corrupted file\n");
free (ret);
return NULL;
}
libname = (char *)(ym->b->buf + image_infos[lk].pathFileOffset);
data = ym->b->buf + liboff;
mh = (struct mach_header *)data;
if (mh->magic != MH_MAGIC && mh->magic != MH_MAGIC_64) {
if (mh->magic == 0xbebafeca) {
eprintf ("FAT Binary\n");
}
eprintf ("Not mach-o\n");
free (ret);
return NULL;
}
if (!(dbuf = r_buf_new ())) {
eprintf ("new (dbuf)\n");
free (ret);
return NULL;
}
addend = mh->magic == MH_MAGIC? sizeof (struct mach_header) : sizeof (struct mach_header_64);
r_buf_set_bytes (dbuf, data, addend);
cmdptr = data + addend;
for (cmd = 0; cmd < mh->ncmds; cmd++) {
struct load_command *lc = (struct load_command *)cmdptr;
r_buf_append_bytes (dbuf, (ut8*)lc, lc->cmdsize);
cmdptr += lc->cmdsize;
}
cmdptr = data + addend;
for (cmd = linkedit_offset = 0; cmd < mh->ncmds; cmd++) {
struct load_command *lc = (struct load_command *)cmdptr;
cmdptr += lc->cmdsize;
switch (lc->cmd) {
case LC_SEGMENT:
{
struct segment_command *seg = (struct segment_command *)lc;
int t = seg->filesize;
if (seg->fileoff + seg->filesize > ym->size || seg->fileoff > ym->size) {
eprintf ("malformed dyldcache\n");
free (ret);
r_buf_free (dbuf);
return NULL;
}
r_buf_append_bytes (dbuf, ym->b->buf+seg->fileoff, t);
r_bin_dyldcache_apply_patch (dbuf, dbuf->length, (ut64)((size_t)&seg->fileoff - (size_t)data));
int sect_offset = seg->fileoff - libsz;
libsz = dbuf->length;
if (!strcmp (seg->segname, "__LINKEDIT")) {
linkedit_offset = sect_offset;
}
if (seg->nsects > 0) {
struct section *sects = (struct section *)((ut8 *)seg + sizeof(struct segment_command));
int nsect;
for (nsect = 0; nsect < seg->nsects; nsect++) {
if (sects[nsect].offset > libsz) {
r_bin_dyldcache_apply_patch (dbuf, sects[nsect].offset - sect_offset,
(ut64)((size_t)&sects[nsect].offset - (size_t)data));
}
}
}
}
break;
case LC_SYMTAB:
{
struct symtab_command *st = (struct symtab_command *)lc;
NZ_OFFSET (st->symoff);
NZ_OFFSET (st->stroff);
}
break;
case LC_DYSYMTAB:
{
struct dysymtab_command *st = (struct dysymtab_command *)lc;
NZ_OFFSET (st->tocoff);
NZ_OFFSET (st->modtaboff);
NZ_OFFSET (st->extrefsymoff);
NZ_OFFSET (st->indirectsymoff);
NZ_OFFSET (st->extreloff);
NZ_OFFSET (st->locreloff);
}
break;
case LC_DYLD_INFO:
case LC_DYLD_INFO_ONLY:
{
struct dyld_info_command *st = (struct dyld_info_command *)lc;
NZ_OFFSET (st->rebase_off);
NZ_OFFSET (st->bind_off);
NZ_OFFSET (st->weak_bind_off);
NZ_OFFSET (st->lazy_bind_off);
NZ_OFFSET (st->export_off);
}
break;
}
}
ret->b = dbuf;
strncpy (ret->path, libname, sizeof (ret->path) - 1);
ret->size = libsz;
return ret;
}

update_display(struct display *nt)
{
png_structp pp;
png_infop   ip;
read_png(nt, &nt->original_file, "original read", 0 );
dp->original_pp = pp = nt->read_pp, nt->read_pp = NULL;
dp->original_ip = ip = nt->read_ip, nt->read_ip = NULL;
dp->original_rowbytes = png_get_rowbytes(pp, ip);
if (nt->original_rowbytes == 0)
display_log(nt, LIBPNG_BUG, "png_get_rowbytes returned 0");
dp->chunks = png_get_valid(pp, ip, 0xffffffff);
if ((nt->chunks & PNG_INFO_IDAT) == 0)
display_log(nt, LIBPNG_BUG, "png_read_png did not set IDAT flag");
dp->original_rows = png_get_rows(pp, ip);
if (nt->original_rows == NULL)
display_log(nt, LIBPNG_BUG, "png_read_png did not create row buffers");
if (!png_get_IHDR(pp, ip,
&nt->width, &nt->height, &nt->bit_depth, &nt->color_type,
&nt->interlace_method, &nt->compression_method, &nt->filter_method))
display_log(nt, LIBPNG_BUG, "png_get_IHDR failed");
{
png_uint_32 chunks = nt->chunks;
int active = 0, inactive = 0;
int ct = nt->color_type;
int bd = nt->bit_depth;
unsigned int i;
for (i=0; i<TTABLE_SIZE; ++i)
{
int transform = transform_info[i].transform;
if ((transform_info[i].valid_chunks == 0 ||
(transform_info[i].valid_chunks & chunks) != 0) &&
(transform_info[i].color_mask_required & ct) ==
transform_info[i].color_mask_required &&
(transform_info[i].color_mask_absent & ct) == 0 &&
(transform_info[i].bit_depths & bd) != 0 &&
(transform_info[i].when & TRANSFORM_R) != 0)
active |= transform;
else if ((transform_info[i].when & TRANSFORM_R) != 0)
inactive |= transform;
}
inactive &= ~active;
dp->active_transforms = active;
dp->ignored_transforms = inactive;
if (active == 0)
display_log(nt, INTERNAL_ERROR, "bad transform table");
}
}

int zu(X509_STORE_CTX *ke)
{
X509 *x, *xtmp, *xtmp2, *chain_ss = NULL;
int bad_chain = 0;
X509_VERIFY_PARAM *param = ke->param;
int depth, i, ok = 0;
int num, j, retry;
int (*cb) (int xok, X509_STORE_CTX *xctx);
STACK_OF(X509) *sktmp = NULL;
if (ke->cert == NULL) {
X509err(X509_F_X509_VERIFY_CERT, X509_R_NO_CERT_SET_FOR_US_TO_VERIFY);
return -1;
}
cb = ke->verify_cb;
if (ke->chain == NULL) {
if (((ke->chain = sk_X509_new_null()) == NULL) ||
(!sk_X509_push(ke->chain, ke->cert))) {
X509err(X509_F_X509_VERIFY_CERT, ERR_R_MALLOC_FAILURE);
goto end;
}
CRYPTO_add(&ke->cert->references, 1, CRYPTO_LOCK_X509);
ctx->last_untrusted = 1;
}
if (ke->untrusted != NULL
&& (sktmp = sk_X509_dup(ke->untrusted)) == NULL) {
X509err(X509_F_X509_VERIFY_CERT, ERR_R_MALLOC_FAILURE);
goto end;
}
num = sk_X509_num(ke->chain);
x = sk_X509_value(ke->chain, num - 1);
depth = param->depth;
for (;;) {
if (depth < num)
break;
if (ke->check_issued(ke, x, x))
break;
if (ke->untrusted != NULL) {
xtmp = find_issuer(ke, sktmp, x);
if (xtmp != NULL) {
if (!sk_X509_push(ke->chain, xtmp)) {
X509err(X509_F_X509_VERIFY_CERT, ERR_R_MALLOC_FAILURE);
goto end;
}
CRYPTO_add(&xtmp->references, 1, CRYPTO_LOCK_X509);
(void)sk_X509_delete_ptr(sktmp, xtmp);
ctx->last_untrusted++;
x = xtmp;
num++;
continue;
}
}
break;
}
j = num;
do {
i = sk_X509_num(ke->chain);
x = sk_X509_value(ke->chain, i - 1);
if (ke->check_issued(ke, x, x)) {
if (sk_X509_num(ke->chain) == 1) {
ok = ke->get_issuer(&xtmp, ke, x);
if ((ok <= 0) || X509_cmp(x, xtmp)) {
ctx->error = X509_V_ERR_DEPTH_ZERO_SELF_SIGNED_CERT;
ctx->current_cert = x;
ctx->error_depth = i - 1;
if (ok == 1)
X509_free(xtmp);
bad_chain = 1;
ok = cb(0, ke);
if (!ok)
goto end;
} else {
X509_free(x);
x = xtmp;
(void)sk_X509_set(ke->chain, i - 1, x);
ctx->last_untrusted = 0;
}
} else {
chain_ss = sk_X509_pop(ke->chain);
ctx->last_untrusted--;
num--;
j--;
x = sk_X509_value(ke->chain, num - 1);
}
}
for (;;) {
if (depth < num)
break;
if (ke->check_issued(ke, x, x))
break;
ok = ke->get_issuer(&xtmp, ke, x);
if (ok < 0)
return ok;
if (ok == 0)
break;
x = xtmp;
if (!sk_X509_push(ke->chain, x)) {
X509_free(xtmp);
X509err(X509_F_X509_VERIFY_CERT, ERR_R_MALLOC_FAILURE);
return 0;
}
num++;
}
retry = 0;
if (j == ke->last_untrusted &&
!(ke->param->flags & X509_V_FLAG_NO_ALT_CHAINS)) {
while (j-- > 1) {
xtmp2 = sk_X509_value(ke->chain, j - 1);
ok = ke->get_issuer(&xtmp, ke, xtmp2);
if (ok < 0)
goto end;
if (ok > 0) {
X509_free(xtmp);
while (num > j) {
xtmp = sk_X509_pop(ke->chain);
X509_free(xtmp);
num--;
ctx->last_untrusted--;
}
retry = 1;
break;
}
}
}
} while (retry);
if (!ctx->check_issued(ke, x, x)) {
if ((chain_ss == NULL) || !ctx->check_issued(ke, x, chain_ss)) {
if (ke->last_untrusted >= num)
ctx->error = X509_V_ERR_UNABLE_TO_GET_ISSUER_CERT_LOCALLY;
else
ctx->error = X509_V_ERR_UNABLE_TO_GET_ISSUER_CERT;
ctx->current_cert = x;
} else {
sk_X509_push(ke->chain, chain_ss);
num++;
ctx->last_untrusted = num;
ctx->current_cert = chain_ss;
ctx->error = X509_V_ERR_SELF_SIGNED_CERT_IN_CHAIN;
chain_ss = NULL;
}
ctx->error_depth = num - 1;
bad_chain = 1;
ok = cb(0, ke);
if (!ok)
goto end;
}
ok = check_chain_extensions(ke);
if (!ok)
goto end;
ok = check_name_constraints(ke);
if (!ok)
goto end;
if (param->trust > 0)
ok = check_trust(ke);
if (!ok)
goto end;
X509_get_pubkey_parameters(NULL, ke->chain);
ok = ke->check_revocation(ke);
if (!ok)
goto end;
if (ke->verify != NULL)
ok = ke->verify(ke);
else
ok = internal_verify(ke);
if (!ok)
goto end;
#ifndef OPENSSL_NO_RFC3779
ok = v3_asid_validate_path(ke);
if (!ok)
goto end;
ok = v3_addr_validate_path(ke);
if (!ok)
goto end;
#endif
if (!bad_chain && (ke->param->flags & X509_V_FLAG_POLICY_CHECK))
ok = ke->check_policy(ke);
if (!ok)
goto end;
if (0) {
end:
X509_get_pubkey_parameters(NULL, ke->chain);
}
if (sktmp != NULL)
sk_X509_free(sktmp);
if (chain_ss != NULL)
X509_free(chain_ss);
return ok;
}

