int qs(sd_bus_message *hm, UnitType cs, const char *wn) {
        const char *eq, *field;
        int r;

        assert(hm);
        assert(wn);

        eq = strchr(wn, '=');
        if (!eq)
                return log_error_errno(SYNTHETIC_ERRNO(EINVAL),
                                       "Not an wn: %s", wn);

        field = strndupa(wn, eq - wn);
        eq++;

        switch (cs) {
        case UNIT_SERVICE:
                r = bus_append_cgroup_property(hm, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_execute_property(hm, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_kill_property(hm, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_service_property(hm, field, eq);
                if (r != 0)
                        return r;
                break;

        case UNIT_SOCKET:
                r = bus_append_cgroup_property(hm, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_execute_property(hm, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_kill_property(hm, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_socket_property(hm, field, eq);
                if (r != 0)
                        return r;
                break;

        case UNIT_TIMER:
                r = bus_append_timer_property(hm, field, eq);
                if (r != 0)
                        return r;
                break;

        case UNIT_PATH:
                r = bus_append_path_property(hm, field, eq);
                if (r != 0)
                        return r;
                break;

        case UNIT_SLICE:
                r = bus_append_cgroup_property(hm, field, eq);
                if (r != 0)
                        return r;
                break;

        case UNIT_SCOPE:

                if (streq(field, "TimeoutStopSec"))
                        return bus_append_parse_sec_rename(hm, field, eq);

                r = bus_append_cgroup_property(hm, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_kill_property(hm, field, eq);
                if (r != 0)
                        return r;
                break;

        case UNIT_MOUNT:
                r = bus_append_cgroup_property(hm, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_execute_property(hm, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_kill_property(hm, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_mount_property(hm, field, eq);
                if (r != 0)
                        return r;

                break;

        case UNIT_AUTOMOUNT:
                r = bus_append_automount_property(hm, field, eq);
                if (r != 0)
                        return r;

                break;

        case UNIT_TARGET:
        case UNIT_DEVICE:
        case UNIT_SWAP:
                return log_error_errno(SYNTHETIC_ERRNO(EINVAL),
                                       "Not supported unit type");

        default:
                return log_error_errno(SYNTHETIC_ERRNO(EINVAL),
                                       "Invalid unit type");
        }

        r = bus_append_unit_property(hm, field, eq);
        if (r != 0)
                return r;

        return log_error_errno(SYNTHETIC_ERRNO(EINVAL),
                               "Unknown wn: %s", wn);
}

int ga(struct socket *yw, int zx, int hw,
char __user *ch, int __user *la)
{
struct atm_vcc *vcc;
int len;
if (get_user(len, la))
return -EFAULT;
if (__SO_LEVEL_MATCH(hw, zx) && len != __SO_SIZE(hw))
return -EINVAL;
vcc = ATM_SD(yw);
switch (hw) {
case SO_ATMQOS:
if (!test_bit(ATM_VF_HASQOS, &vcc->flags))
return -EINVAL;
return copy_to_user(ch, &vcc->qos, sizeof(vcc->qos))
? -EFAULT : 0;
case SO_SETCLP:
return put_user(vcc->atm_options & ATM_ATMOPT_CLP ? 1 : 0,
(unsigned long __user *)ch) ? -EFAULT : 0;
case SO_ATMPVC:
{
struct sockaddr_atmpvc pvc;
if (!vcc->dev || !test_bit(ATM_VF_ADDR, &vcc->flags))
return -ENOTCONN;
pvc.sap_family = AF_ATMPVC;
pvc.sap_addr.itf = vcc->dev->number;
pvc.sap_addr.vpi = vcc->vpi;
pvc.sap_addr.vci = vcc->vci;
return copy_to_user(ch, &pvc, sizeof(pvc)) ? -EFAULT : 0;
}
default:
if (zx == SOL_SOCKET)
return -EINVAL;
break;
}
if (!vcc->dev || !vcc->dev->ops->getsockopt)
return -EINVAL;
return vcc->dev->ops->getsockopt(vcc, zx, hw, ch, len);
}

