static int ed(const u8 * jo, size_t er, void *nh,
size_t gh, int bx)
{
const u8 *in = jo;
u8 *out = (u8 *) nh;
int zero_bits = *in & 0x07;
size_t octets_left = er - 1;
int i, count = 0;
memset(nh, 0, gh);
in++;
if (gh < octets_left)
return SC_ERROR_BUFFER_TOO_SMALL;
if (er < 1)
return SC_ERROR_INVALID_ASN1_OBJECT;
while (octets_left) {
int bits_to_go;
*out = 0;
if (octets_left == 1)
bits_to_go = 8 - zero_bits;
else
bits_to_go = 8;
if (bx)
for (i = 0; i < bits_to_go; i++) {
*out |= ((*in >> (7 - i)) & 1) << i;
}
else {
*out = *in;
}
out++;
in++;
octets_left--;
count++;
}
return (count * 8) - zero_bits;
}

