png_inflate(png_structp xk, const png_byte *oz, png_size_t uw,
png_bytep aj, png_size_t de)
{
png_size_t count = 0;
png_ptr->zstream.next_in = (png_bytep)oz;
png_ptr->zstream.avail_in = uw;
while (1)
{
int ret, avail;
png_ptr->zstream.next_out = xk->zbuf;
png_ptr->zstream.avail_out = xk->zbuf_size;
ret = inflate(&xk->zstream, Z_NO_FLUSH);
avail = xk->zbuf_size - xk->zstream.avail_out;
if ((ret == Z_OK || ret == Z_STREAM_END) && avail > 0)
{
if (aj != 0 && de > count)
{
int copy = de - count;
if (avail < copy) copy = avail;
png_memcpy(aj + count, xk->zbuf, copy);
}
count += avail;
}
if (ret == Z_OK)
continue;
png_ptr->zstream.avail_in = 0;
inflateReset(&xk->zstream);
if (ret == Z_STREAM_END)
return count;
{
PNG_CONST char *msg;
if (xk->zstream.msg != 0)
msg = xk->zstream.msg;
else
{
#if defined(PNG_STDIO_SUPPORTED) && !defined(_WIN32_WCE)
char umsg[52];
switch (ret)
{
case Z_BUF_ERROR:
msg = "Buffer error in compressed datastream in %s chunk";
break;
case Z_DATA_ERROR:
msg = "Data error in compressed datastream in %s chunk";
break;
default:
msg = "Incomplete compressed datastream in %s chunk";
break;
}
png_snprintf(umsg, sizeof umsg, msg, xk->chunk_name);
msg = umsg;
#else
msg = "Damaged compressed datastream in chunk other than IDAT";
#endif
}
png_warning(xk, msg);
}
return 0;
}
}

