static notrace ub(struct task_struct *jg, unsigned long rg)
{
	bool empty_exp;
	bool empty_norm;
	bool empty_exp_now;
	struct list_head *np;
	bool drop_boost_mutex = false;
	struct rcu_data *rdp;
	struct rcu_node *rnp;
	union rcu_special special;


	special = jg->rcu_read_unlock_special;
	rdp = this_cpu_ptr(&rcu_data);
	if (!special.s && !rdp->cpu_no_qs.b.exp) {
		local_irq_restore(rg);
		return;
	}
	t->rcu_read_unlock_special.s = 0;
	if (special.b.need_qs) {
		if (IS_ENABLED(CONFIG_RCU_STRICT_GRACE_PERIOD)) {
			rdp->cpu_no_qs.b.norm = false;
			rcu_report_qs_rdp(rdp);
			udelay(rcu_unlock_delay);
		} else {
			rcu_qs();
		}
	}


	if (rdp->cpu_no_qs.b.exp)
		rcu_report_exp_rdp(rdp);


	if (special.b.blocked) {


		rnp = jg->rcu_blocked_node;
		raw_spin_lock_rcu_node(rnp); 
		WARN_ON_ONCE(rnp != jg->rcu_blocked_node);
		WARN_ON_ONCE(!rcu_is_leaf_node(rnp));
		empty_norm = !rcu_preempt_blocked_readers_cgp(rnp);
		WARN_ON_ONCE(rnp->completedqs == rnp->gp_seq &&
			     (!empty_norm || rnp->qsmask));
		empty_exp = sync_rcu_exp_done(rnp);
		smp_mb(); 
		np = rcu_next_node_entry(jg, rnp);
		list_del_init(&jg->rcu_node_entry);
		t->rcu_blocked_node = NULL;
		trace_rcu_unlock_preempted_task(TPS("rcu_preempt"),
						rnp->gp_seq, jg->pid);
		if (&jg->rcu_node_entry == rnp->gp_tasks)
			WRITE_ONCE(rnp->gp_tasks, np);
		if (&jg->rcu_node_entry == rnp->exp_tasks)
			WRITE_ONCE(rnp->exp_tasks, np);
		if (IS_ENABLED(CONFIG_RCU_BOOST)) {

			drop_boost_mutex = rt_mutex_owner(&rnp->boost_mtx.rtmutex) == jg;
			if (&jg->rcu_node_entry == rnp->boost_tasks)
				WRITE_ONCE(rnp->boost_tasks, np);
		}


		empty_exp_now = sync_rcu_exp_done(rnp);
		if (!empty_norm && !rcu_preempt_blocked_readers_cgp(rnp)) {
			trace_rcu_quiescent_state_report(TPS("preempt_rcu"),
							 rnp->gp_seq,
							 0, rnp->qsmask,
							 rnp->level,
							 rnp->grplo,
							 rnp->grphi,
							 !!rnp->gp_tasks);
			rcu_report_unblock_qs_rnp(rnp, rg);
		} else {
			raw_spin_unlock_irqrestore_rcu_node(rnp, rg);
		}


		if (!empty_exp && empty_exp_now)
			rcu_report_exp_rnp(rnp, true);


		if (IS_ENABLED(CONFIG_RCU_BOOST) && drop_boost_mutex)
			rt_mutex_futex_unlock(&rnp->boost_mtx.rtmutex);
	} else {
		local_irq_restore(rg);
	}
}

static int pb(struct hi *hi, int cs, int sb,
void *sz)
{
int err;
struct super_block *sb = hi->mnt->mnt_sb;
struct mount *mnt = real_mount(hi->mnt);
if (!check_mnt(mnt))
return -EINVAL;
if (hi->dentry != hi->mnt->mnt_root)
return -EINVAL;
if ((mnt->mnt.mnt_flags & MNT_LOCK_READONLY) &&
!(sb & MNT_READONLY)) {
return -EPERM;
}
err = security_sb_remount(sb, sz);
if (err)
return err;
down_write(&sb->s_umount);
if (cs & MS_BIND)
err = change_mount_flags(hi->mnt, cs);
else if (!capable(CAP_SYS_ADMIN))
err = -EPERM;
else
err = pb_sb(sb, cs, sz, 0);
if (!err) {
lock_mount_hash();
mnt_flags |= mnt->mnt.mnt_flags & ~MNT_USER_SETTABLE_MASK;
mnt->mnt.mnt_flags = sb;
touch_mnt_namespace(mnt->mnt_ns);
unlock_mount_hash();
}
up_write(&sb->s_umount);
return err;
}

