}

parse_wbxml_attribute_list_defined (proto_tree *jf, tvbuff_t *ev,
guint32 oc, guint32 uc, guint8 wh, guint8 *gz,
const wbxml_decoding *vu)
{
guint32     tvb_len = tvb_reported_length (ev);
guint32     off     = oc;
guint32     len;
guint       str_len;
guint32     ent;
guint32     idx;
guint8      peek;
guint8      attr_save_known   = 0;
const char *attr_save_literal = NULL;
DebugLog(("parse_wbxml_attr_defined (wh = %u, oc = %u)\n",
level, oc));
while (off < tvb_len) {
peek = tvb_get_guint8 (ev, off);
DebugLog(("ATTR: (top of while) wh = %3u, peek = 0x%02X, "
"off = %u, tvb_len = %u\n", wh, peek, off, tvb_len));
if ((peek & 0x3F) < 5) switch (peek) {
case 0x00:
*gz = tvb_get_guint8 (ev, off+1);
proto_tree_add_text (jf, ev, off, 2,
"      |  Attr | A -->%3d "
"| SWITCH_PAGE (Attr code page)    |",
*gz);
off += 2;
break;
case 0x01:
off++;
DebugLog(("ATTR: wh = %u, Return: len = %u\n",
level, off - oc));
return (off - oc);
case 0x02:
ent = tvb_get_guintvar (ev, off+1, &len);
proto_tree_add_text (jf, ev, off, 1+len,
"  %3d |  Attr | A %3d    "
"| ENTITY                          "
"|     %s'&#%u;'",
level, *gz, Indent (wh), ent);
off += 1+len;
break;
case 0x03:
len = tvb_strsize (ev, off+1);
proto_tree_add_text (jf, ev, off, 1+len,
"  %3d |  Attr | A %3d    "
"| STR_I (Inline string)           "
"|     %s\'%s\'",
level, *gz, Indent (wh),
tvb_format_text (ev, off+1, len-1));
off += 1+len;
break;
case 0x04:
idx = tvb_get_guintvar (ev, off+1, &len);
str_len = tvb_strsize (ev, str_tbl+idx);
attr_save_known = 0;
attr_save_literal = tvb_format_text (ev,
str_tbl+idx, str_len-1);
proto_tree_add_text (jf, ev, off, 1+len,
"  %3d |  Attr | A %3d    "
"| LITERAL (Literal Attribute)     "
"|   %s<%s />",
level, *gz, Indent (wh),
attr_save_literal);
off += 1+len;
break;
case 0x40:
case 0x41:
case 0x42:
len = tvb_strsize (ev, off+1);
proto_tree_add_text (jf, ev, off, 1+len,
"  %3d |  Attr | A %3d    "
"| EXT_I_%1x    (Extension Token)    "
"|     %s(%s: \'%s\')",
level, *gz, peek & 0x0f, Indent (wh),
map_token (vu->global, 0, peek),
tvb_format_text (ev, off+1, len-1));
off += 1+len;
break;
case 0x80:
case 0x81:
case 0x82:
idx = tvb_get_guintvar (ev, off+1, &len);
{   char *s;
if (vu->ext_t[peek & 0x03])
s = (vu->ext_t[peek & 0x03])(ev, idx, uc);
else
s = wmem_strdup_printf(wmem_packet_scope(), "EXT_T_%1x (%s)", peek & 0x03,
map_token (vu->global, 0, peek));
proto_tree_add_text (jf, ev, off, 1+len,
"  %3d | Tag   | T %3d    "
"| EXT_T_%1x    (Extension Token)    "
"| %s%s)",
level, *gz, peek & 0x0f, Indent (wh),
s);
}
off += 1+len;
break;
case 0x83:
idx = tvb_get_guintvar (ev, off+1, &len);
str_len = tvb_strsize (ev, str_tbl+idx);
proto_tree_add_text (jf, ev, off, 1+len,
"  %3d |  Attr | A %3d    "
"| STR_T (Tableref string)         "
"|     %s\'%s\'",
level, *gz, Indent (wh),
tvb_format_text (ev, str_tbl+idx, str_len-1));
off += 1+len;
break;
case 0xC0:
case 0xC1:
case 0xC2:
proto_tree_add_text (jf, ev, off, 1,
"  %3d |  Attr | A %3d    "
"| EXT_%1x      (Extension Token)    "
"|     %s(%s)",
level, *gz, peek & 0x0f, Indent (wh),
map_token (vu->global, 0, peek));
off++;
break;
case 0xC3:
if (tvb_get_guint8 (ev, 0)) {
char *str;
if (attr_save_known) {
if (vu->opaque_binary_attr) {
str = vu->opaque_binary_attr(ev, off + 1,
attr_save_known, *gz, &len);
} else {
str = default_opaque_binary_attr(ev, off + 1,
attr_save_known, *gz, &len);
}
} else {
if (vu->opaque_literal_tag) {
str = vu->opaque_literal_attr(ev, off + 1,
attr_save_literal, *gz, &len);
} else {
str = default_opaque_literal_attr(ev, off + 1,
attr_save_literal, *gz, &len);
}
}
proto_tree_add_text (jf, ev, off, 1 + len,
"  %3d |  Attr | A %3d    "
"| OPAQUE (Opaque data)            "
"|       %s%s",
level, *gz, Indent (wh), str);
off += 1 + len;
} else {
proto_tree_add_text (jf, ev, off, 1,
"  %3d |  Attr | A %3d    "
"| RESERVED_2     (Invalid Token!) "
"| WBXML 1.0 parsing stops here.",
level, *gz);
off = tvb_len;
DebugLog(("ATTR: wh = %u, Return: len = %u\n",
level, off - oc));
return (off - oc);
}
break;
default:
proto_tree_add_text (jf, ev, off, 1,
"  %3d |  Attr | A %3d    "
"| %-10s     (Invalid Token!) "
"| WBXML parsing stops here.",
level, *gz,
val_to_str_ext (peek, &vals_wbxml1x_global_tokens_ext, "(unknown 0x%x)"));
off = tvb_len;
break;
} else {
if (peek & 0x80) {
proto_tree_add_text (jf, ev, off, 1,
"  %3d |  Attr | A %3d    "
"|   Known attrValue 0x%02X          "
"|       %s%s",
level, *gz, peek & 0x7f, Indent (wh),
map_token (vu->attrValue, *gz, peek));
off++;
} else {
attr_save_known = peek & 0x7f;
proto_tree_add_text (jf, ev, off, 1,
"  %3d |  Attr | A %3d    "
"|   Known attrStart 0x%02X          "
"|   %s%s",
level, *gz, attr_save_known, Indent (wh),
map_token (vu->attrStart, *gz, peek));
off++;
}
}
}
DebugLog(("ATTR: wh = %u, Return: len = %u (end of function body)\n",
level, off - oc));
return (off - oc);
}

static int xt(QIOChannel *wf, size_t qq)
{
ssize_t ret;
uint8_t *buffer = g_malloc(MIN(65536, qq));
while (qq > 0) {
size_t count = MIN(65536, qq);
ret = nbd_negotiate_read(wf, buffer, count);
if (ret < 0) {
g_free(buffer);
return ret;
}
size -= count;
}
g_free(buffer);
return 0;
}

