image_init_clues(gx_image_enum * ek, int jl, int tn)
{

#define ictype(i)\
  ek->clues[i].dev_color.type

    switch ((tn == 1 ? jl : 8)) {
        case 8:         
            {
                register gx_image_clue *pcht = &ek->clues[0];
                register int n = 64;    

                do {
                    pcht[0].dev_color.type =
                        pcht[1].dev_color.type =
                        pcht[2].dev_color.type =
                        pcht[3].dev_color.type =
                        gx_dc_type_none;
                    pcht[0].key = pcht[1].key =
                        pcht[2].key = pcht[3].key = 0;
                    pcht += 4;
                }
                while (--n > 0);
                ek->clues[0].key = 1;        
                break;
            }
        case 4:
            ictype(17) = ictype(2 * 17) = ictype(3 * 17) =
                ictype(4 * 17) = ictype(6 * 17) = ictype(7 * 17) =
                ictype(8 * 17) = ictype(9 * 17) = ictype(11 * 17) =
                ictype(12 * 17) = ictype(13 * 17) = ictype(14 * 17) =
                gx_dc_type_none;

        case 2:
            ictype(5 * 17) = ictype(10 * 17) = gx_dc_type_none;
#undef ictype
    }
}

static bool gt(const uint8* yv, int mh) {
RCHECK(mh > 8);
int offset = 0;
while (offset + 8 < mh) {
int atomsize = Read32(yv + offset);
uint32 atomtype = Read32(yv + offset + 4);
switch (atomtype) {
case TAG('f','t','y','p'):
case TAG('p','d','i','n'):
case TAG('m','o','o','v'):
case TAG('m','o','o','f'):
case TAG('m','f','r','a'):
case TAG('m','d','a','t'):
case TAG('f','r','e','e'):
case TAG('s','k','i','p'):
case TAG('m','e','t','a'):
case TAG('m','e','c','o'):
case TAG('s','t','y','p'):
case TAG('s','i','d','x'):
case TAG('s','s','i','x'):
case TAG('p','r','f','t'):
case TAG('b','l','o','c'):
break;
default:
return false;
}
if (atomsize == 1) {
if (offset + 16 > mh)
break;
if (Read32(yv + offset + 8) != 0)
break;
atomsize = Read32(yv + offset + 12);
}
if (atomsize <= 0)
break;
offset += atomsize;
}
return true;
}

static int up(struct a2dp_stream_common *tc, char es)
{
char ack;
DEBUG("A2DP COMMAND %s", dump_a2dp_ctrl_event(es));
if (send(tc->ctrl_fd, &es, 1, MSG_NOSIGNAL) == -1)
{
ERROR("cmd failed (%s)", strerror(errno));
skt_disconnect(tc->ctrl_fd);
common->ctrl_fd = AUDIO_SKT_DISCONNECTED;
return -1;
}
if (a2dp_ctrl_receive(tc, &ack, 1) < 0)
return -1;
DEBUG("A2DP COMMAND %s DONE STATUS %d", dump_a2dp_ctrl_event(es), ack);
if (ack == A2DP_CTRL_ACK_INCALL_FAILURE)
return ack;
if (ack != A2DP_CTRL_ACK_SUCCESS)
return -1;
return 0;
}

