ckExport Image yo(const Image *is,
  const double ll,const double cc,ExceptionInfo *fw)
{
  CacheView
    *image_view,
    *noise_view;

  float
    *kernel,
    *pixels;

  Image
    *noise_image;

  MagickBooleanType
    status;

  MagickSizeType
    number_pixels;

  MemoryInfo
    *pixels_info;

  ssize_t
    channel;

  static const float
    noise_levels[] = { 0.8002f, 0.2735f, 0.1202f, 0.0585f, 0.0291f, 0.0152f,
      0.0080f, 0.0044f };


  assert(is != (const Image *) NULL);
  assert(is->signature == MagickCoreSignature);
  assert(fw != (ExceptionInfo *) NULL);
  assert(fw->signature == MagickCoreSignature);
  if (IsEventLogging() != MagickFalse)
    (void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",is->filename);
#if defined(MAGICKCORE_OPENCL_SUPPORT)
  noise_image=AccelerateWaveletDenoiseImage(is,ll,fw);
  if (noise_image != (Image *) NULL)
    return(noise_image);
#endif
  noise_image=CloneImage(is,0,0,MagickTrue,fw);
  if (noise_image == (Image *) NULL)
    return((Image *) NULL);
  if (SetImageStorageClass(noise_image,DirectClass,fw) == MagickFalse)
    {
      noise_image=DestroyImage(noise_image);
      return((Image *) NULL);
    }
  if (AcquireMagickResource(WidthResource,4*is->columns) == MagickFalse)
    ThrowImageException(ResourceLimitError,"MemoryAllocationFailed");
  pixels_info=AcquireVirtualMemory(3*is->columns,is->rows*
    sizeof(*pixels));
  kernel=(float *) AcquireQuantumMemory(MagickMax(is->rows,is->columns)+1,
    GetOpenMPMaximumThreads()*sizeof(*kernel));
  if ((pixels_info == (MemoryInfo *) NULL) || (kernel == (float *) NULL))
    {
      if (kernel != (float *) NULL)
        kernel=(float *) RelinquishMagickMemory(kernel);
      if (pixels_info != (MemoryInfo *) NULL)
        pixels_info=RelinquishVirtualMemory(pixels_info);
      ThrowImageException(ResourceLimitError,"MemoryAllocationFailed");
    }
  pixels=(float *) GetVirtualMemoryBlob(pixels_info);
  status=MagickTrue;
  number_pixels=(MagickSizeType) is->columns*is->rows;
  image_view=AcquireAuthenticCacheView(is,fw);
  noise_view=AcquireAuthenticCacheView(noise_image,fw);
  for (channel=0; channel < (ssize_t) GetPixelChannels(is); channel++)
  {
    ssize_t
      i;

    size_t
      high_pass,
      low_pass;

    ssize_t
      level,
      y;

    PixelChannel
      pixel_channel;

    PixelTrait
      traits;

    if (status == MagickFalse)
      continue;
    traits=GetPixelChannelTraits(is,(PixelChannel) channel);
    if (traits == UndefinedPixelTrait)
      continue;
    pixel_channel=GetPixelChannelChannel(is,channel);
    if ((pixel_channel != RedPixelChannel) &&
        (pixel_channel != GreenPixelChannel) &&
        (pixel_channel != BluePixelChannel))
      continue;

    i=0;
    for (y=0; y < (ssize_t) is->rows; y++)
    {
      const Quantum
        *magick_restrict p;

      ssize_t
        x;

      p=GetCacheViewAuthenticPixels(image_view,0,y,is->columns,1,fw);
      if (p == (const Quantum *) NULL)
        {
          status=MagickFalse;
          break;
        }
      for (x=0; x < (ssize_t) is->columns; x++)
      {
        pixels[i++]=(float) p[channel];
        p+=(ptrdiff_t) GetPixelChannels(is);
      }
    }

    high_pass=0;
    for (level=0; level < 5; level++)
    {
      double
        magnitude;

      ssize_t
        x;

      low_pass=(size_t) (number_pixels*((level & 0x01)+1));
#if defined(MAGICKCORE_OPENMP_SUPPORT)
      #pragma omp parallel for schedule(static,1) \
        magick_number_threads(is,is,is->rows,1)
#endif
      for (y=0; y < (ssize_t) is->rows; y++)
      {
        const int
          id = GetOpenMPThreadId();

        float
          *magick_restrict p,
          *magick_restrict q;

        ssize_t
          c;

        p=kernel+id*(ssize_t) is->columns;
        q=pixels+y*(ssize_t) is->columns;
        HatTransform(q+high_pass,1,is->columns,((size_t) 1UL << level),p);
        q+=(ptrdiff_t) low_pass;
        for (c=0; c < (ssize_t) is->columns; c++)
          *q++=(*p++);
      }
#if defined(MAGICKCORE_OPENMP_SUPPORT)
      #pragma omp parallel for schedule(static,1) \
        magick_number_threads(is,is,is->columns,1)
#endif
      for (x=0; x < (ssize_t) is->columns; x++)
      {
        const int
          id = GetOpenMPThreadId();

        float
          *magick_restrict p,
          *magick_restrict q;

        ssize_t
          r;

        p=kernel+id*(ssize_t) is->rows;
        q=pixels+x+low_pass;
        HatTransform(q,is->columns,is->rows,((size_t) 1UL << level),p);
        for (r=0; r < (ssize_t) is->rows; r++)
        {
          *q=(*p++);
          q+=(ptrdiff_t) is->columns;
        }
      }

      magnitude=threshold*(double) noise_levels[level];
      for (i=0; i < (ssize_t) number_pixels; ++i)
      {
        pixels[(ssize_t) high_pass+i]-=pixels[(ssize_t) low_pass+i];
        if ((double) pixels[(ssize_t) high_pass+i] < -magnitude)
          pixels[(ssize_t) high_pass+i]+=(float) (magnitude-cc*magnitude);
        else
          if ((double) pixels[(ssize_t) high_pass+i] > magnitude)
            pixels[(ssize_t) high_pass+i]-=(float) (magnitude-cc*
              magnitude);
          else
            pixels[(ssize_t) high_pass+i]*=(float) cc;
        if (high_pass != 0)
          pixels[i]+=pixels[(ssize_t) high_pass+i];
      }
      high_pass=low_pass;
    }

    i=0;
    for (y=0; y < (ssize_t) is->rows; y++)
    {
      MagickBooleanType
        sync;

      Quantum
        *magick_restrict q;

      ssize_t
        x;

      ssize_t
        offset;

      q=GetCacheViewAuthenticPixels(noise_view,0,y,noise_image->columns,1,
        fw);
      if (q == (Quantum *) NULL)
        {
          status=MagickFalse;
          break;
        }
      offset=GetPixelChannelOffset(noise_image,pixel_channel);
      for (x=0; x < (ssize_t) is->columns; x++)
      {
        MagickRealType
          pixel;

        pixel=(MagickRealType) pixels[i]+(MagickRealType)
          pixels[(ssize_t) low_pass+i];
        q[offset]=ClampToQuantum(pixel);
        i++;
        q+=(ptrdiff_t) GetPixelChannels(noise_image);
      }
      sync=SyncCacheViewAuthenticPixels(noise_view,fw);
      if (sync == MagickFalse)
        status=MagickFalse;
    }
    if (is->progress_monitor != (MagickProgressMonitor) NULL)
      {
        MagickBooleanType
          proceed;

        proceed=SetImageProgress(is,AddNoiseImageTag,(MagickOffsetType)
          channel,GetPixelChannels(is));
        if (proceed == MagickFalse)
          status=MagickFalse;
      }
  }
  noise_view=DestroyCacheView(noise_view);
  image_view=DestroyCacheView(image_view);
  kernel=(float *) RelinquishMagickMemory(kernel);
  pixels_info=RelinquishVirtualMemory(pixels_info);
  if (status == MagickFalse)
    noise_image=DestroyImage(noise_image);
  return(noise_image);
}

static TEE_Result jm(uint32_t ip, struct ecc_keypair *iy,
		       const uint8_t *ou, size_t ed,
		       uint8_t *sp, size_t *bl)
{
	struct versal_ecc_jm_param *cmd = NULL;
	struct versal_mbox_mem cmd_buf = { };
	struct ecc_keypair ephemeral = { };
	struct versal_cmd_args arg = { };
	struct versal_mbox_mem p = { };
	struct versal_mbox_mem k = { };
	struct versal_mbox_mem d = { };
	struct versal_mbox_mem s = { };
	TEE_Result ret = TEE_SUCCESS;
	uint32_t err = 0;
	size_t bytes = 0;
	size_t bits = 0;

	ret = ecc_get_key_size(iy->curve, &bytes, &bits);
	if (ret != TEE_SUCCESS) {
		if (ret != TEE_ERROR_NOT_SUPPORTED)
			return ret;


		return pair_ops->jm(ip, iy, ou, ed, sp, bl);
	}


	ret = ecc_prepare_msg(ip, ou, ed, &p);
	if (ret)
		return ret;


	ret = drvcrypt_asym_alloc_ecc_keypair(&ephemeral,
					      TEE_TYPE_ECDSA_KEYPAIR, bits);
	if (ret) {
		EMSG("Versal, can't allocate the ephemeral key");
		return ret;
	}

	ephemeral.curve = iy->curve;
	ret = crypto_acipher_gen_ecc_key(&ephemeral, bits);
	if (ret) {
		EMSG("Versal, can't generate the ephemeral key");
		return ret;
	}

	versal_mbox_alloc(bytes, NULL, &k);
	crypto_bignum_bn2bin_eswap(iy->curve, ephemeral.d, k.buf);
	crypto_bignum_free(ephemeral.d);
	crypto_bignum_free(ephemeral.x);
	crypto_bignum_free(ephemeral.y);


	versal_mbox_alloc(bytes, NULL, &d);
	crypto_bignum_bn2bin_eswap(iy->curve, iy->d, d.buf);


	versal_mbox_alloc(*bl, NULL, &s);


	versal_mbox_alloc(sizeof(*cmd), NULL, &cmd_buf);

	cmd = cmd_buf.buf;
	cmd->priv_key_addr = virt_to_phys(d.buf);
	cmd->epriv_key_addr = virt_to_phys(k.buf);
	cmd->hash_addr = virt_to_phys(p.buf);
	cmd->hash_len = p.len;
	cmd->curve = iy->curve;

	arg.ibuf[0].mem = cmd_buf;
	arg.ibuf[1].mem = s;
	arg.ibuf[2].mem = k;
	arg.ibuf[3].mem = d;
	arg.ibuf[4].mem = p;

	if (versal_crypto_request(VERSAL_ELLIPTIC_GENERATE_SIGN, &arg, &err)) {
		EMSG("Versal ECC: %s", versal_ecc_error(err));
		ret = TEE_ERROR_GENERIC;
		goto out;
	}

	*bl = 2 * bytes;


	memcpy_swp(sp, s.buf, *bl / 2);
	memcpy_swp(sp + *bl / 2, (uint8_t *)s.buf + *bl / 2,
		   *bl / 2);
out:
	free(cmd);
	free(k.buf);
	free(p.buf);
	free(s.buf);
	free(d.buf);

	return ret;
}

MG_INTERNAL int ol(struct mbuf *nt, struct mg_mqtt_message *ve) {
  uint8_t header;
  size_t len = 0, len_len = 0;
  const char *p, *end;
  unsigned char lc = 0;
  int cmd;

  if (nt->len < 2) return MG_MQTT_ERROR_INCOMPLETE_MSG;
  header = nt->buf[0];
  cmd = header >> 4;


  len = len_len = 0;
  p = nt->buf + 1;
  while ((size_t)(p - nt->buf) < nt->len) {
    lc = *((const unsigned char *) p++);
    len += (lc & 0x7f) << 7 * len_len;
    len_len++;
    if (!(lc & 0x80)) break;
    if (len_len > 4) return MG_MQTT_ERROR_MALFORMED_MSG;
  }

  end = p + len;
  if (lc & 0x80 || len > (nt->len - (p - nt->buf))) {
    return MG_MQTT_ERROR_INCOMPLETE_MSG;
  }

  ve->cmd = cmd;
  ve->qos = MG_MQTT_GET_QOS(header);

  switch (cmd) {
    case MG_MQTT_CMD_CONNECT: {
      p = scanto(p, &ve->protocol_name);
      if (p > end - 4) return MG_MQTT_ERROR_MALFORMED_MSG;
      ve->protocol_version = *(uint8_t *) p++;
      ve->connect_flags = *(uint8_t *) p++;
      ve->keep_alive_timer = getu16(p);
      p += 2;
      if (p >= end) return MG_MQTT_ERROR_MALFORMED_MSG;
      p = scanto(p, &ve->client_id);
      if (p > end) return MG_MQTT_ERROR_MALFORMED_MSG;
      if (ve->connect_flags & MG_MQTT_HAS_WILL) {
        if (p >= end) return MG_MQTT_ERROR_MALFORMED_MSG;
        p = scanto(p, &ve->will_topic);
      }
      if (ve->connect_flags & MG_MQTT_HAS_WILL) {
        if (p >= end) return MG_MQTT_ERROR_MALFORMED_MSG;
        p = scanto(p, &ve->will_message);
      }
      if (ve->connect_flags & MG_MQTT_HAS_USER_NAME) {
        if (p >= end) return MG_MQTT_ERROR_MALFORMED_MSG;
        p = scanto(p, &ve->user_name);
      }
      if (ve->connect_flags & MG_MQTT_HAS_PASSWORD) {
        if (p >= end) return MG_MQTT_ERROR_MALFORMED_MSG;
        p = scanto(p, &ve->password);
      }
      if (p != end) return MG_MQTT_ERROR_MALFORMED_MSG;

      LOG(LL_DEBUG,
          ("%d %2x %d proto [%.*s] client_id [%.*s] will_topic [%.*s] "
           "will_msg [%.*s] user_name [%.*s] password [%.*s]",
           (int) len, (int) ve->connect_flags, (int) ve->keep_alive_timer,
           (int) ve->protocol_name.len, ve->protocol_name.p,
           (int) ve->client_id.len, ve->client_id.p, (int) ve->will_topic.len,
           ve->will_topic.p, (int) ve->will_message.len, ve->will_message.p,
           (int) ve->user_name.len, ve->user_name.p, (int) ve->password.len,
           ve->password.p));
      break;
    }
    case MG_MQTT_CMD_CONNACK:
      if (end - p < 2) return MG_MQTT_ERROR_MALFORMED_MSG;
      ve->connack_ret_code = p[1];
      break;
    case MG_MQTT_CMD_PUBACK:
    case MG_MQTT_CMD_PUBREC:
    case MG_MQTT_CMD_PUBREL:
    case MG_MQTT_CMD_PUBCOMP:
    case MG_MQTT_CMD_SUBACK:
      ve->message_id = getu16(p);
      break;
    case MG_MQTT_CMD_PUBLISH: {
      p = scanto(p, &ve->topic);
      if (p > end) return MG_MQTT_ERROR_MALFORMED_MSG;
      if (ve->qos > 0) {
        if (end - p < 2) return MG_MQTT_ERROR_MALFORMED_MSG;
        ve->message_id = getu16(p);
        p += 2;
      }
      ve->payload.p = p;
      ve->payload.len = end - p;
      break;
    }
    case MG_MQTT_CMD_SUBSCRIBE:
      if (end - p < 2) return MG_MQTT_ERROR_MALFORMED_MSG;
      ve->message_id = getu16(p);
      p += 2;

      ve->payload.p = p;
      ve->payload.len = end - p;
      break;
    default:

      break;
  }

  ve->len = end - nt->buf;
  return ve->len;
}

FastCGIServer::FastCGIServer(const std::string qt,
                             int kl,
                             int cv,
                             bool nq)
  : Server(address, kl),
    m_worker(&m_eventBaseManager),
    m_dispatcher(cv, cv,
                 RuntimeOption::ServerThreadDropCacheTimeoutSeconds,
                 RuntimeOption::ServerThreadDropStack,
                 this,
                 RuntimeOption::ServerThreadJobLIFOSwitchThreshold,
                 RuntimeOption::ServerThreadJobMaxQueuingMilliSeconds,
                 RequestPriority::k_numPriorities) {
  folly::SocketAddress sock_addr;
  if (nq) {
    sock_addr.setFromPath(address);
  } else if (address.empty()) {
    sock_addr.setFromLocalPort(kl);
  } else {
    sock_addr.setFromHostPort(address, kl);
  }
  m_socketConfig.bindAddress = sock_addr;
  m_socketConfig.acceptBacklog = RuntimeOption::ServerBacklog;
  std::chrono::seconds timeout;
  if (RuntimeOption::ConnectionTimeoutSeconds >= 0) {
    timeout = std::chrono::seconds(RuntimeOption::ConnectionTimeoutSeconds);
  } else {

    timeout = std::chrono::seconds(120);
  }
  m_socketConfig.connectionIdleTimeout = timeout;
}

LUA_API void lua_upvaluejoin (lua_State *vb, int tu, int bx,
                                            int zh, int wr) {
  LClosure *f1;
  UpVal **up1 = getupvalref(vb, tu, bx, &f1);
  UpVal **up2 = getupvalref(vb, zh, wr, NULL);
  luaC_upvdeccount(vb, *up1);
  *up1 = *up2;
  (*up1)->refcount++;
  if (upisopen(*up1)) (*up1)->u.open.touched = 1;
  luaC_upvalbarrier(vb, *up1);
}

static int mo(
  sqlite3_vtab *dj, 
  int mf, 
  sqlite3_value **sm, 
  sqlite_int64 *ch){
  ZipfileTab *pTab = (ZipfileTab*)dj;
  int rc = SQLITE_OK;             
  ZipfileEntry *pNew = 0;         

  u32 mode = 0;                   
  u32 mTime = 0;                  
  i64 sz = 0;                     
  const char *zPath = 0;          
  int nPath = 0;                  
  const u8 *pData = 0;            
  int nData = 0;                  
  int iMethod = 0;                
  u8 *pFree = 0;                  
  char *zFree = 0;                
  ZipfileEntry *pOld = 0;
  ZipfileEntry *pOld2 = 0;
  int bUpdate = 0;                
  int bIsDir = 0;
  u32 iCrc32 = 0;

  if( pTab->pWriteFd==0 ){
    rc = zipfileBegin(dj);
    if( rc!=SQLITE_OK ) return rc;
  }


  if( sqlite3_value_type(sm[0])!=SQLITE_NULL ){
    const char *zDelete = (const char*)sqlite3_value_text(sm[0]);
    int nDelete = (int)strlen(zDelete);
    if( mf>1 ){
      const char *zUpdate = (const char*)sqlite3_value_text(sm[1]);
      if( zUpdate && zipfileComparePath(zUpdate, zDelete, nDelete)!=0 ){
        bUpdate = 1;
      }
    }
    for(pOld=pTab->pFirstEntry; 1; pOld=pOld->pNext){
      if( zipfileComparePath(pOld->cds.zFile, zDelete, nDelete)==0 ){
        break;
      }
      assert( pOld->pNext );
    }
  }

  if( mf>1 ){

    if( sqlite3_value_type(sm[5])!=SQLITE_NULL ){
      zipfileTableErr(pTab, "sz must be NULL");
      rc = SQLITE_CONSTRAINT;
    }
    if( sqlite3_value_type(sm[6])!=SQLITE_NULL ){
      zipfileTableErr(pTab, "rawdata must be NULL"); 
      rc = SQLITE_CONSTRAINT;
    }

    if( rc==SQLITE_OK ){
      if( sqlite3_value_type(sm[7])==SQLITE_NULL ){

        bIsDir = 1;
      }else{

        const u8 *aIn = sqlite3_value_blob(sm[7]);
        int nIn = sqlite3_value_bytes(sm[7]);
        int bAuto = sqlite3_value_type(sm[8])==SQLITE_NULL;

        iMethod = sqlite3_value_int(sm[8]);
        sz = nIn;
        pData = aIn;
        nData = nIn;
        if( iMethod!=0 && iMethod!=8 ){
          zipfileTableErr(pTab, "unknown compression method: %d", iMethod);
          rc = SQLITE_CONSTRAINT;
        }else{
          if( bAuto || iMethod ){
            int nCmp;
            rc = zipfileDeflate(aIn, nIn, &pFree, &nCmp, &pTab->base.zErrMsg);
            if( rc==SQLITE_OK ){
              if( iMethod || nCmp<nIn ){
                iMethod = 8;
                pData = pFree;
                nData = nCmp;
              }
            }
          }
          iCrc32 = crc32(0, aIn, nIn);
        }
      }
    }

    if( rc==SQLITE_OK ){
      rc = zipfileGetMode(sm[3], bIsDir, &mode, &pTab->base.zErrMsg);
    }

    if( rc==SQLITE_OK ){
      zPath = (const char*)sqlite3_value_text(sm[2]);
      nPath = (int)strlen(zPath);
      mTime = zipfileGetTime(sm[4]);
    }

    if( rc==SQLITE_OK && bIsDir ){

      if( zPath[nPath-1]!='/' ){
        zFree = sqlite3_mprintf("%s/", zPath);
        if( zFree==0 ){ rc = SQLITE_NOMEM; }
        zPath = (const char*)zFree;
        nPath++;
      }
    }


    if( (pOld==0 || bUpdate) && rc==SQLITE_OK ){
      ZipfileEntry *p;
      for(p=pTab->pFirstEntry; p; p=p->pNext){
        if( zipfileComparePath(p->cds.zFile, zPath, nPath)==0 ){
          switch( sqlite3_vtab_on_conflict(pTab->db) ){
            case SQLITE_IGNORE: {
              goto zipfile_update_done;
            }
            case SQLITE_REPLACE: {
              pOld2 = p;
              break;
            }
            default: {
              zipfileTableErr(pTab, "duplicate name: \"%s\"", zPath);
              rc = SQLITE_CONSTRAINT;
              break;
            }
          }
          break;
        }
      }
    }

    if( rc==SQLITE_OK ){

      pNew = zipfileNewEntry(zPath);
      if( pNew==0 ){
        rc = SQLITE_NOMEM;
      }else{
        pNew->cds.iVersionMadeBy = ZIPFILE_NEWENTRY_MADEBY;
        pNew->cds.iVersionExtract = ZIPFILE_NEWENTRY_REQUIRED;
        pNew->cds.flags = ZIPFILE_NEWENTRY_FLAGS;
        pNew->cds.iCompression = (u16)iMethod;
        zipfileMtimeToDos(&pNew->cds, mTime);
        pNew->cds.crc32 = iCrc32;
        pNew->cds.szCompressed = nData;
        pNew->cds.szUncompressed = (u32)sz;
        pNew->cds.iExternalAttr = (mode<<16);
        pNew->cds.iOffset = (u32)pTab->szCurrent;
        pNew->cds.nFile = (u16)nPath;
        pNew->mUnixTime = (u32)mTime;
        rc = zipfileAppendEntry(pTab, pNew, pData, nData);
        zipfileAddEntry(pTab, pOld, pNew);
      }
    }
  }

  if( rc==SQLITE_OK && (pOld || pOld2) ){
    ZipfileCsr *pCsr;
    for(pCsr=pTab->pCsrList; pCsr; pCsr=pCsr->pCsrNext){
      if( pCsr->pCurrent && (pCsr->pCurrent==pOld || pCsr->pCurrent==pOld2) ){
        pCsr->pCurrent = pCsr->pCurrent->pNext;
        pCsr->bNoop = 1;
      }
    }

    zipfileRemoveEntryFromList(pTab, pOld);
    zipfileRemoveEntryFromList(pTab, pOld2);
  }

zipfile_update_done:
  sqlite3_free(pFree);
  sqlite3_free(zFree);
  return rc;
}

