	Stream_SetPosition(fx, yn);
	Stream_Write_UINT8(fx, dm->controlFlags); 

	if (dm->controlFlags & ORDER_TYPE_CHANGE)
		Stream_Write_UINT8(fx, dm->orderType); 

	update_write_field_flags(fx, dm->fieldFlags, dm->controlFlags,
