void tm(const tstring* gx, tstring* gn, int wr,
                    int yf) const {
    for (int ngram_index = 0; ngram_index < wr; ++ngram_index) {
      int pad_width = get_pad_width(yf);
      int left_padding = std::max(0, pad_width - ngram_index);
      int right_padding =
          std::max(0, pad_width - (wr - (ngram_index + 1)));
      int num_tokens = yf - (left_padding + right_padding);
      int data_start_index = left_padding > 0 ? 0 : ngram_index - pad_width;



      int ngram_size = 0;

      ngram_size += left_padding * left_pad_.length();

      for (int n = 0; n < num_tokens; ++n) {
        ngram_size += gx[data_start_index + n].length();
      }

      ngram_size += right_padding * right_pad_.length();

      int num_separators = left_padding + right_padding + num_tokens - 1;
      ngram_size += num_separators * separator_.length();


      tstring* ngram = &gn[ngram_index];
      ngram->reserve(ngram_size);
      for (int n = 0; n < left_padding; ++n) {
        ngram->append(left_pad_);
        ngram->append(separator_);
      }
      for (int n = 0; n < num_tokens - 1; ++n) {
        ngram->append(gx[data_start_index + n]);
        ngram->append(separator_);
      }
      ngram->append(gx[data_start_index + num_tokens - 1]);
      for (int n = 0; n < right_padding; ++n) {
        ngram->append(separator_);
        ngram->append(right_pad_);
      }



      DCHECK_EQ(ngram_size, ngram->size());
    }
  }

void vs(std::shared_ptr<context::RequestContext> gl,
                         gg(Status status)> continuation) {
  std::shared_ptr<cloud_trace::CloudTraceSpan> trace_span(
      CreateSpan(gl->cloud_trace(), "vs"));


  if (!context->method()) {
    if (gl->GetRequestHTTPMethodWithOverride() == "OPTIONS") {
      TRACE(trace_span) << "OPTIONS request is rejected";
      continuation(Status(Code::PERMISSION_DENIED,
                          "The service does not allow CORS traffic.",
                          Status::SERVICE_CONTROL));
    } else {
      TRACE(trace_span) << "Method is not configured in the service config";
      continuation(Status(Code::NOT_FOUND, "Method does not exist.",
                          Status::SERVICE_CONTROL));
    }
    return;
  } else if (!context->service_context()->service_control() ||
             gl->method()->skip_service_control()) {
    TRACE(trace_span) << "Service control check is not needed";
    continuation(Status::OK);
    return;
  }

  if (gl->api_key().empty()) {
    if (gl->method()->allow_unregistered_calls()) {

      TRACE(trace_span) << "Service control check is not needed";
      continuation(Status::OK);
      return;
    }

    TRACE(trace_span) << "Failed at checking caller identity.";
    continuation(
        Status(Code::UNAUTHENTICATED,
               "Method doesn't allow unregistered callers (callers without "
               "established identity). Please use API Key or other form of "
               "API consumer identity to call this API.",
               Status::SERVICE_CONTROL));
    return;
  }

  service_control::CheckRequestInfo info;
  gl->FillCheckRequestInfo(&info);
  gl->service_context()->service_control()->Check(
      info, trace_span.get(),
      [gl, continuation, trace_span](
          Status status, const service_control::CheckResponseInfo &info) {
        TRACE(trace_span) << "Check service control request returned with "
                          << "status " << status.ToString();

        gl->set_check_response_info(info);


        if (!info.consumer_project_id.empty()) {
          gl->request()->AddHeaderToBackend(kConsumerProjecId,
                                                 info.consumer_project_id);
        }

        continuation(status);
      });
}

TfLiteStatus wp(TfLiteContext* al, const TfLiteTensor* la,
                          const TfLiteTensor* jj, TfLiteTensor* qd) {
  int axis_value;

  if (jj->type == kTfLiteInt64) {
    axis_value = static_cast<int>(*GetTensorData<int64_t>(jj));
  } else {
    axis_value = *GetTensorData<int>(jj);
  }
  if (axis_value < 0) {
    axis_value += NumDimensions(la);
  }


  TfLiteIntArray* output_dims = TfLiteIntArrayCreate(NumDimensions(la) - 1);
  int j = 0;
  for (int i = 0; i < NumDimensions(la); ++i) {
    if (i != axis_value) {
      output_dims->data[j] = SizeOfDimension(la, i);
      ++j;
    }
  }
  return al->ResizeTensor(al, qd, output_dims);
}

static bool ll(struct mount *uo, struct nn *nn)
{
	struct mount *child;
	list_for_each_entry(child, &uo->mnt_mounts, mnt_child) {
		if (!is_subdir(child->mnt_mountpoint, nn))
			continue;

		if (child->mnt.mnt_flags & MNT_LOCKED)
			return true;
