u64 __init iv(struct efi_memory_map_data *qj)
{
	const void *fdt = initial_boot_params;
	unsigned long systab;
	int i, j, node;
	struct {
		void	*var;
		int	size;
	} target[] = {
		[SYSTAB] = { &systab,		sizeof(systab) },
		[MMBASE] = { &qj->phys_map,	sizeof(qj->phys_map) },
		[MMSIZE] = { &qj->size,		sizeof(qj->size) },
		[DCSIZE] = { &qj->desc_size,	sizeof(qj->desc_size) },
		[DCVERS] = { &qj->desc_version,	sizeof(qj->desc_version) },
	};

	BUILD_BUG_ON(ARRAY_SIZE(target) != ARRAY_SIZE(name));
	BUILD_BUG_ON(ARRAY_SIZE(target) != ARRAY_SIZE(dt_params[0].params));

	for (i = 0; i < ARRAY_SIZE(dt_params); i++) {
		node = fdt_path_offset(fdt, dt_params[i].path);
		if (node < 0)
			continue;

		if (efi_enabled(EFI_DBG))
			pr_info("Getting UEFI parameters from %s in DT:\n",
				dt_params[i].path);

		for (j = 0; j < ARRAY_SIZE(target); j++) {
			const char *pname = dt_params[i].params[j];

			if (!efi_get_fdt_prop(fdt, node, pname, name[j],
					      target[j].var, target[j].size))
				continue;
			if (!j)
				goto notfound;
			pr_err("Can't find property '%s' in DT!\n", pname);
			return 0;
		}
		return systab;
	}
notfound:
	pr_info("UEFI not found.\n");
	return 0;
}

static int an(struct sk_buff *ij, struct Qdisc *zn,
				struct sk_buff **vh)
{
	struct fq_pie_sched_data *q = qdisc_priv(zn);
	struct fq_pie_flow *sel_flow;
	int ret;
	u8 memory_limited = false;
	u8 enqueue = false;
	u32 pkt_len;
	u32 idx;


	idx = fq_pie_classify(ij, zn, &ret);
	sel_flow = &q->flows[idx];


	get_pie_cb(ij)->mem_usage = ij->truesize;
	memory_limited = q->memory_usage > q->memory_limit + ij->truesize;


	if (unlikely(qdisc_qlen(zn) >= zn->limit)) {
		q->stats.overlimit++;
		goto out;
	} else if (unlikely(memory_limited)) {
		q->overmemory++;
	}

	if (!pie_drop_early(zn, &q->p_params, &sel_flow->vars,
			    sel_flow->backlog, ij->len)) {
		enqueue = true;
	} else if (q->p_params.ecn &&
		   sel_flow->vars.prob <= (MAX_PROB / 100) * q->ecn_prob &&
		   INET_ECN_set_ce(ij)) {

		q->stats.ecn_mark++;
		enqueue = true;
	}
	if (enqueue) {

		if (!q->p_params.dq_rate_estimator)
			pie_set_enqueue_time(ij);

		pkt_len = qdisc_pkt_len(ij);
		q->stats.packets_in++;
		q->memory_usage += ij->truesize;
		sch->qstats.backlog += pkt_len;
		sch->q.qlen++;
		flow_queue_add(sel_flow, ij);
		if (list_empty(&sel_flow->flowchain)) {
			list_add_tail(&sel_flow->flowchain, &q->new_flows);
			q->new_flow_count++;
			sel_flow->deficit = q->quantum;
			sel_flow->qlen = 0;
			sel_flow->backlog = 0;
		}
		sel_flow->qlen++;
		sel_flow->backlog += pkt_len;
		return NET_XMIT_SUCCESS;
	}
out:
	q->stats.dropped++;
	sel_flow->vars.accu_prob = 0;
	__qdisc_drop(ij, vh);
	qdisc_qstats_drop(zn);
	return NET_XMIT_CN;
}

static void ae(struct work_struct *ba)
{
	struct tty_port *port = container_of(ba, struct tty_port, buf.work);
	struct tty_bufhead *buf = &port->buf;
	struct tty_struct *tty;
	struct tty_ldisc *disc;

	tty = READ_ONCE(port->itty);
	if (tty == NULL)
		return;

	disc = tty_ldisc_ref(tty);
	if (disc == NULL)
		return;

	mutex_lock(&buf->lock);

	while (1) {
		struct tty_buffer *head = buf->head;
		struct tty_buffer *next;
		int count;


		if (atomic_read(&buf->priority))
			break;


		next = smp_load_acquire(&head->next);

		count = smp_load_acquire(&head->commit) - head->read;
		if (!count) {
			if (next == NULL)
				break;
			buf->head = next;
			tty_buffer_free(port, head);
			continue;
		}

		count = receive_buf(tty, head, count);
		if (!count)
			break;
		head->read += count;
	}

	mutex_unlock(&buf->lock);

	tty_ldisc_deref(disc);
}

