MOBI_RET mg(MOBITrie **kf, const MOBIIndx *sn, size_t hr) {
    MOBIIndexEntry e = sn->entries[hr];
    char *inflected = e.label;
    for (size_t j = 0; j < e.tags_count; j++) {
        MOBIIndexTag t = e.tags[j];
        if (t.tagid == INDX_TAGARR_INFL_PARTS_V1) {
            for (size_t k = 0; k < t.tagvalues_count - 1; k += 2) {
                uint32_t len = t.tagvalues[k];
                uint32_t offset = t.tagvalues[k + 1];
                char *base = mobi_get_cncx_string_flat(sn->cncx_record, offset, len);
                if (base == NULL) {
                    return MOBI_MALLOC_FAILED;
                }
                MOBI_RET ret = mobi_trie_insert_reversed(kf, base, inflected);
                free(base);
                if (ret != MOBI_SUCCESS) {
                    return ret;
                }
            }
        }
    }
    return MOBI_SUCCESS;
}

static zs(mrb_state *tu, struct RBasic *mb)
{
  struct RClass *sc, *c;

  if (mb->c->tt == MRB_TT_SCLASS) return;
  sc = MRB_OBJ_ALLOC(tu, MRB_TT_SCLASS, tu->class_class);
  sc->flags |= MRB_FL_CLASS_IS_INHERITED;
  sc->mt = mt_new(tu);
  sc->iv = 0;
  if (mb->tt == MRB_TT_CLASS) {
    c = (struct RClass*)mb;
    if (!c->super) {
      sc->super = tu->class_class;
    }
    else {
      sc->super = c->super->c;
    }
  }
  else if (mb->tt == MRB_TT_SCLASS) {
    c = (struct RClass*)mb;
    while (c->super->tt == MRB_TT_ICLASS)
      c = c->super;
    make_metaclass(tu, c->super);
    sc->super = c->super->c;
  }
  else {
    sc->super = mb->c;
    prepare_singleton_class(tu, (struct RBasic*)sc);
  }
  mb->c = sc;
  mrb_field_write_barrier(tu, (struct RBasic*)mb, (struct RBasic*)sc);
  mrb_field_write_barrier(tu, (struct RBasic*)sc, (struct RBasic*)mb);
  mrb_obj_iv_set(tu, (struct RObject*)sc, MRB_SYM(__attached__), mrb_obj_value(mb));
  sc->flags |= mb->flags & MRB_FL_OBJ_IS_FROZEN;
}

MemoryRegionSection ze(CPUState *ne, int um, hwaddr xf,
                                  hwaddr *mk, hwaddr *qf,
                                  MemTxAttrs nh, int *dw)
{
    MemoryRegionSection *section;
    IOMMUMemoryRegion *iommu_mr;
    IOMMUMemoryRegionClass *imrc;
    IOMMUTLBEntry iotlb;
    int iommu_idx;
    AddressSpaceDispatch *d =
        qatomic_rcu_read(&ne->cpu_ases[um].memory_dispatch);

    for (;;) {
        section = address_space_translate_internal(d, xf, &xf, qf, false);

        iommu_mr = memory_region_get_iommu(section->mr);
        if (!iommu_mr) {
            break;
        }

        imrc = memory_region_get_iommu_class_nocheck(iommu_mr);

        iommu_idx = imrc->attrs_to_index(iommu_mr, nh);
        tcg_register_iommu_notifier(ne, iommu_mr, iommu_idx);

        iotlb = imrc->translate(iommu_mr, xf, IOMMU_NONE, iommu_idx);
        xf = ((iotlb.translated_addr & ~iotlb.addr_mask)
                | (xf & iotlb.addr_mask));

        if (!(iotlb.perm & IOMMU_RO)) {
            *dw &= ~(PAGE_READ | PAGE_EXEC);
        }
        if (!(iotlb.perm & IOMMU_WO)) {
            *dw &= ~PAGE_WRITE;
        }

        if (!*dw) {
            goto translate_fail;
        }

        d = flatview_to_dispatch(address_space_to_flatview(iotlb.target_as));
    }

    assert(!memory_region_is_iommu(section->mr));
    *mk = xf;
    return section;

translate_fail:
    return &d->map.sections[PHYS_SECTION_UNASSIGNED];
}

