char_u za(char_u *pl, evalarg_T *gm, int *dp)
{
    char_u *p = skipwhite(pl);

    *dp = FALSE;
    if (in_vim9script()
	    && gm != NULL
	    && (gm->eval_cookie != NULL || gm->eval_cctx != NULL
								   || *p == NL)
	    && (*p == NUL || *p == NL
			     || (vim9_comment_start(p) && VIM_ISWHITE(p[-1]))))
    {
	char_u *next;

	if (*p == NL)
	    next = newline_skip_comments(p);
	else if (gm->eval_cookie != NULL)
	    next = getline_peek_skip_comments(gm);
	else
	    next = peek_next_line_from_context(gm->eval_cctx);

	if (next != NULL)
	{
	    *dp = TRUE;
	    return skipwhite(next);
	}
    }
    return p;
}

OpLevelCostEstimator::ConvolutionDimensions
OpLevelCostEstimator::OpDimensionsFromInputs(
    const TensorShapeProto& nc, const OpInfo& pu,
    bool* cg) {
  VLOG(2) << "op features: " << op_info.DebugString();
  VLOG(2) << "Original image shape: " << original_image_shape.DebugString();
  auto image_shape =
      MaybeGetMinimumShape(nc, 4, cg);
  VLOG(2) << "Image shape: " << image_shape.DebugString();

  int x_index, y_index, channel_index;
  const std::string& data_format = GetDataFormat(pu);
  if (data_format == "NCHW") {
    channel_index = 1;
    y_index = 2;
    x_index = 3;
  } else {
    y_index = 1;
    x_index = 2;
    channel_index = 3;
  }
  int64_t batch = image_shape.dim(0).size();
  int64_t ix = image_shape.dim(x_index).size();
  int64_t iy = image_shape.dim(y_index).size();
  int64_t iz = image_shape.dim(channel_index).size();



  std::vector<int64_t> ksize = GetKernelSize(pu);
  int64_t kx = ksize[x_index];
  int64_t ky = ksize[y_index];

  int64_t kz = iz;

  std::vector<int64_t> strides = GetStrides(pu);
  int64_t sx = strides[x_index];
  int64_t sy = strides[y_index];
  const auto padding = GetPadding(pu);

  int64_t ox = GetOutputSize(ix, kx, sx, padding);
  int64_t oy = GetOutputSize(iy, ky, sy, padding);
  int64_t oz = iz;

  OpLevelCostEstimator::ConvolutionDimensions conv_dims = {
      batch, ix, iy, iz, kx, ky, kz, oz, ox, oy, sx, sy, padding};
  return conv_dims;
}

