static int bd(struct fs_context *vs, struct fs_parameter *ut)
{
	struct legacy_fs_context *ctx = vs->fs_private;
	unsigned int size = ctx->data_size;
	size_t len = 0;
	int ret;

	ret = vfs_parse_fs_param_source(vs, ut);
	if (ret != -ENOPARAM)
		return ret;

	if (ctx->param_type == LEGACY_FS_MONOLITHIC_PARAMS)
		return invalf(vs, "VFS: Legacy: Can't mix monolithic and individual options");

	switch (ut->type) {
	case fs_value_is_string:
		len = 1 + ut->size;
		fallthrough;
	case fs_value_is_flag:
		len += strlen(ut->key);
		break;
	default:
		return invalf(vs, "VFS: Legacy: Parameter type for '%s' not supported",
			      ut->key);
	}

	if (len > PAGE_SIZE - 2 - size)
		return invalf(vs, "VFS: Legacy: Cumulative options too large");
	if (strchr(ut->key, ',') ||
	    (ut->type == fs_value_is_string &&
	     memchr(ut->string, ',', ut->size)))
		return invalf(vs, "VFS: Legacy: Option '%s' contained comma",
			      ut->key);
	if (!ctx->legacy_data) {
		ctx->legacy_data = kmalloc(PAGE_SIZE, GFP_KERNEL);
		if (!ctx->legacy_data)
			return -ENOMEM;
	}

	ctx->legacy_data[size++] = ',';
	len = strlen(ut->key);
	memcpy(ctx->legacy_data + size, ut->key, len);
	size += len;
	if (ut->type == fs_value_is_string) {
		ctx->legacy_data[size++] = '=';
		memcpy(ctx->legacy_data + size, ut->string, ut->size);
		size += ut->size;
	}
	ctx->legacy_data[size] = '\0';
	ctx->data_size = size;
	ctx->param_type = LEGACY_FS_INDIVIDUAL_PARAMS;
	return 0;
}

