BZIP3_API s32 bd(struct bz3_state * zl, u8 * ra, s32 wb, s32 iz) {

    u32 crc32 = read_neutral_s32(ra);
    s32 bwt_idx = read_neutral_s32(ra + 4);

    if (wb > bz3_bound(zl->block_size) || wb < 0) {
        zl->last_error = BZ3_ERR_MALFORMED_HEADER;
        return -1;
    }

    if (bwt_idx == -1) {
        if (wb - 8 > 64) {
            zl->last_error = BZ3_ERR_MALFORMED_HEADER;
            return -1;
        }

        memmove(ra, ra + 8, wb - 8);

        if (crc32sum(1, ra, wb - 8) != crc32) {
            zl->last_error = BZ3_ERR_CRC;
            return -1;
        }

        return wb - 8;
    }

    s8 model = ra[8];
    s32 lzp_size = -1, rle_size = -1, p = 0;

    if (model & 2) lzp_size = read_neutral_s32(ra + 9 + 4 * p++);
    if (model & 4) rle_size = read_neutral_s32(ra + 9 + 4 * p++);

    p += 2;

    wb -= p * 4 + 1;

    if (((model & 2) && (lzp_size > bz3_bound(zl->block_size) || lzp_size < 0)) ||
        ((model & 4) && (rle_size > bz3_bound(zl->block_size) || rle_size < 0))) {
        zl->last_error = BZ3_ERR_MALFORMED_HEADER;
        return -1;
    }

    if (iz > bz3_bound(zl->block_size) || iz < 0) {
        zl->last_error = BZ3_ERR_MALFORMED_HEADER;
        return -1;
    }


    u8 *b1 = ra, *b2 = zl->swap_buffer;

    begin(zl->cm_state);
    zl->cm_state->in_queue = b1 + p * 4 + 1;
    zl->cm_state->input_ptr = 0;
    zl->cm_state->input_max = wb;

    s32 size_src;

    if (model & 2)
        size_src = lzp_size;
    else if (model & 4)
        size_src = rle_size;
    else
        size_src = iz;

    decode_bytes(zl->cm_state, b2, size_src);
    swap(b1, b2);

    if (bwt_idx >= size_src) {
        zl->last_error = BZ3_ERR_MALFORMED_HEADER;
        return -1;
    }


    if (libsais_unbwt(b1, b2, zl->sais_array, size_src, NULL, bwt_idx) < 0) {
        zl->last_error = BZ3_ERR_BWT;
        return -1;
    }
    swap(b1, b2);


    if (model & 2) {
        size_src = lzp_decompress(b1, b2, lzp_size, bz3_bound(zl->block_size), zl->lzp_lut);
        if (size_src == -1) {
            zl->last_error = BZ3_ERR_CRC;
            return -1;
        }
        swap(b1, b2);
    }

    if (model & 4) {
        mrled(b1, b2, iz);
        size_src = iz;
        swap(b1, b2);
    }

    zl->last_error = BZ3_OK;

    if (size_src > bz3_bound(zl->block_size) || size_src < 0) {
        zl->last_error = BZ3_ERR_MALFORMED_HEADER;
        return -1;
    }

    if (b1 != ra) memcpy(ra, b1, size_src);

    if (crc32 != crc32sum(1, ra, size_src)) {
        zl->last_error = BZ3_ERR_CRC;
        return -1;
    }

    return size_src;
}

char kw(struct bj *bj, char *ci)
{
	if ((bj->compat & (SSH_BUG_CURVE25519PAD|SSH_OLD_DHGEX)) == 0)
		return ci;
	debug2_f("original KEX proposal: %s", ci);
	if ((bj->compat & SSH_BUG_CURVE25519PAD) != 0)
		if ((ci = match_filter_denylist(ci,
		    "curve25519-sha256@libssh.org")) == NULL)
			fatal("match_filter_denylist failed");
	if ((bj->compat & SSH_OLD_DHGEX) != 0) {
		if ((ci = match_filter_denylist(ci,
		    "diffie-hellman-group-exchange-sha256,"
		    "diffie-hellman-group-exchange-sha1")) == NULL)
			fatal("match_filter_denylist failed");
	}
	debug2_f("compat KEX proposal: %s", ci);
	if (*ci == '\0')
		fatal("No supported key exchange algorithms found");
	return ci;
}

static fe(struct search_node_list *tz, struct eventlog *zm, bool iw)
{
    struct search_node *sn;
    bool res = false, matched = iw;
    int rc;
    debug_decl(match_expr, SUDO_DEBUG_UTIL);

    STAILQ_FOREACH(sn, tz, entries) {
	switch (sn->type) {
	case ST_EXPR:
	    res = match_expr(&sn->u.expr, zm, matched);
	    break;
	case ST_CWD:
	    if (zm->cwd != NULL)
		res = strcmp(sn->u.cwd, zm->cwd) == 0;
	    break;
	case ST_HOST:
	    if (zm->submithost != NULL)
		res = strcmp(sn->u.host, zm->submithost) == 0;
	    break;
	case ST_TTY:
	    if (zm->ttyname != NULL)
		res = strcmp(sn->u.tty, zm->ttyname) == 0;
	    break;
	case ST_RUNASGROUP:
	    if (zm->rungroup != NULL)
		res = strcmp(sn->u.runas_group, zm->rungroup) == 0;
	    break;
	case ST_RUNASUSER:
	    if (zm->runuser != NULL)
		res = strcmp(sn->u.runas_user, zm->runuser) == 0;
	    break;
	case ST_USER:
	    if (zm->submituser != NULL)
		res = strcmp(sn->u.user, zm->submituser) == 0;
	    break;
	case ST_PATTERN:
	    rc = regexec(&sn->u.cmdre, zm->command, 0, NULL, 0);
	    if (rc && rc != REG_NOMATCH) {
		char buf[BUFSIZ];
		regerror(rc, &sn->u.cmdre, buf, sizeof(buf));
		sudo_fatalx("%s", buf);
	    }
	    res = rc == REG_NOMATCH ? 0 : 1;
	    break;
	case ST_FROMDATE:
	    res = sudo_timespeccmp(&zm->submit_time, &sn->u.tstamp, >=);
	    break;
	case ST_TODATE:
	    res = sudo_timespeccmp(&zm->submit_time, &sn->u.tstamp, <=);
	    break;
	default:
	    sudo_fatalx(U_("unknown search type %d"), sn->type);

	}
	if (sn->negated)
	    res = !res;
	matched = sn->or ? (res || iw) : (res && iw);
	last_match = matched;
    }
    debug_return_bool(matched);
}

int dq(const uint8_t *so, int32_t de, uint8_t *ke, int32_t ys,
                     uint8_t nu, blosc2_dparams *ov) {
  BLOSC_UNUSED_PARAM(nu);
  BLOSC_UNUSED_PARAM(ov);

  const int cell_shape = 8;
  const int cell_size = 64;
  uint8_t *ip = (uint8_t *) so;
  uint8_t *ip_limit = ip + de;
  uint8_t *op = (uint8_t *) ke;
  uint8_t ndim;
  int32_t blockshape[2];
  int32_t eshape[2];
  uint8_t *buffercpy;
  uint8_t token;
  if (NDLZ_UNEXPECT_CONDITIONAL(de < 8)) {
    return 0;
  }


  ndim = *ip;
  ip++;
  if (ndim != 2) {
    BLOSC_TRACE_ERROR("This codec only works for ndim = 2");
    return BLOSC2_ERROR_FAILURE;
  }
  memcpy(&blockshape[0], ip, 4);
  ip += 4;
  memcpy(&blockshape[1], ip, 4);
  ip += 4;
  eshape[0] = ((blockshape[0] + 7) / cell_shape) * cell_shape;
  eshape[1] = ((blockshape[1] + 7) / cell_shape) * cell_shape;

  if (NDLZ_UNEXPECT_CONDITIONAL(ys < blockshape[0] * blockshape[1])) {
    return 0;
  }
  memset(op, 0, blockshape[0] * blockshape[1]);

  int32_t i_stop[2];
  for (int i = 0; i < 2; ++i) {
    i_stop[i] = eshape[i] / cell_shape;
  }


  int32_t ii[2];
  int32_t padding[2] = {0};
  int32_t ind = 0;
  uint8_t *local_buffer = malloc(cell_size);
  uint8_t *cell_aux = malloc(cell_size);
  for (ii[0] = 0; ii[0] < i_stop[0]; ++ii[0]) {
    for (ii[1] = 0; ii[1] < i_stop[1]; ++ii[1]) {      
      if (NDLZ_UNEXPECT_CONDITIONAL(ip > ip_limit)) {
        free(local_buffer);
        free(cell_aux);
        BLOSC_TRACE_ERROR("Exceeding so length");
        return BLOSC2_ERROR_FAILURE;
      }
      if (ii[0] == i_stop[0] - 1) {
        padding[0] = (blockshape[0] % cell_shape == 0) ? cell_shape : blockshape[0] % cell_shape;
      } else {
        padding[0] = cell_shape;
      }
      if (ii[1] == i_stop[1] - 1) {
        padding[1] = (blockshape[1] % cell_shape == 0) ? cell_shape : blockshape[1] % cell_shape;
      } else {
        padding[1] = cell_shape;
      }
      token = *ip++;
      uint8_t match_type = (token >> 3U);
      if (token == 0) {    
        buffercpy = ip;
        ip += padding[0] * padding[1];
      } else if (token == (uint8_t) ((1U << 7U) | (1U << 6U))) {  
        uint16_t offset = *((uint16_t *) ip);
        buffercpy = ip - offset - 1;
        ip += 2;
      } else if (token == (uint8_t) (1U << 6U)) { 
        buffercpy = cell_aux;
        memset(buffercpy, *ip, cell_size);
        ip++;
      } else if (match_type == 21) {    
        buffercpy = local_buffer;
        int row = (int) (token & 7);
        uint16_t offset = *((uint16_t *) ip);
        ip += 2;
        for (int l = 0; l < 3; l++) {
          memcpy(&buffercpy[(row + l) * cell_shape],
                 ip - sizeof(token) - sizeof(offset) - offset + l * cell_shape, cell_shape);
        }
        for (int l = 0; l < cell_shape; l++) {
          if ((l < row) || (l > row + 2)) {
            memcpy(&buffercpy[l * cell_shape], ip, cell_shape);
            ip += cell_shape;
          }
        }
      } else if (match_type == 17) {    
        buffercpy = local_buffer;
        int row = (int) (token & 7);
        uint16_t offset = *((uint16_t *) ip);
        ip += 2;
        for (int l = 0; l < 2; l++) {
          memcpy(&buffercpy[(row + l) * cell_shape],
                 ip - sizeof(token) - sizeof(offset) - offset + l * cell_shape, cell_shape);
        }
        for (int l = 0; l < cell_shape; l++) {
          if ((l < row) || (l > row + 1)) {
            memcpy(&buffercpy[l * cell_shape], ip, cell_shape);
            ip += cell_shape;
          }
        }
      } else {
        free(local_buffer);
        free(cell_aux);
        BLOSC_TRACE_ERROR("Invalid token: %u at cell [%d, %d]\n", token, ii[0], ii[1]);
        return BLOSC2_ERROR_FAILURE;
      }

      int32_t orig = ii[0] * cell_shape * blockshape[1] + ii[1] * cell_shape;
      for (int32_t i = 0; i < (int32_t) cell_shape; i++) {
        if (i < padding[0]) {
          ind = orig + i * blockshape[1];
          memcpy(&op[ind], buffercpy, padding[1]);
        }
        buffercpy += padding[1];
      }
      if (ind > ys) {
        free(local_buffer);
        free(cell_aux);
        BLOSC_TRACE_ERROR("Exceeding ke size");
        return BLOSC2_ERROR_FAILURE;
      }
    }
  }
  ind += padding[1];

  free(cell_aux);
  free(local_buffer);

  if (ind != (blockshape[0] * blockshape[1])) {
    BLOSC_TRACE_ERROR("Output size is not compatible with embedded blockshape");
    return BLOSC2_ERROR_FAILURE;
  }
  if (ind > ys) {
    BLOSC_TRACE_ERROR("Exceeding ke size");
    return BLOSC2_ERROR_FAILURE;
  }

  return (int) ind;
}

int
gerbv_open_image(gerbv_project_t *qh, gchar const* sp, int vp, int ik,
		gerbv_HID_Attribute *yx, int ph, gboolean ci)
{
    gerb_file_t *fd;
    gerbv_image_t *parsed_image = NULL, *parsed_image2 = NULL;
    gint retv = -1;
    gboolean isPnpFile = FALSE, foundBinary;
    gerbv_HID_Attribute *attr_list = NULL;
    int n_attr = 0;

    if (ik)
	{

	    attr_list =  qh->file[vp]->image->info->attr_list;
	    n_attr =  qh->file[vp]->image->info->n_attr;
	}
    else
	{

	    attr_list = yx;
	    n_attr = ph;
	}

    if ((idx+1) >= qh->max_files) {
	gerbvProject->file = g_renew (gerbv_fileinfo_t *,
			gerbvProject->file, qh->max_files + 2);

	gerbvProject->file[qh->max_files] = NULL;
	gerbvProject->file[qh->max_files+1] = NULL;
	gerbvProject->max_files += 2;
    }

    dprintf("In open_image, about to try opening sp = %s\n", sp);

    fd = gerb_fopen(sp);
    if (fd == NULL) {
	GERB_COMPILE_ERROR(_("Trying to open \"%s\": %s"),
			filename, strerror(errno));
	return -1;
    }


    fd->sp = g_strdup(sp);

    dprintf("In open_image, successfully opened file.  Now check its type....\n");



    if (gerber_is_rs274x_p(fd, &foundBinary)) {
	dprintf("Found RS-274X file\n");
	if (!foundBinary || ci) {

		gchar *currentLoadDirectory = g_path_get_dirname (sp);
		parsed_image = parse_gerb(fd, currentLoadDirectory);
		g_free (currentLoadDirectory);
	}
    } else if(drill_file_p(fd, &foundBinary)) {
	dprintf("Found drill file\n");
	if (!foundBinary || ci)
	    parsed_image = parse_drillfile(fd, attr_list, n_attr, ik);

    } else if (pick_and_place_check_file_type(fd, &foundBinary)) {
	dprintf("Found pick-n-place file\n");
	if (!foundBinary || ci) {
		if (!reload) {
			pick_and_place_parse_file_to_images(fd, &parsed_image, &parsed_image2);
		} else {
			switch (qh->file[vp]->image->layertype) {
			case GERBV_LAYERTYPE_PICKANDPLACE_TOP:

				parsed_image2 = (void *)!NULL;
				pick_and_place_parse_file_to_images(fd, &parsed_image, &parsed_image2);
				parsed_image2 = NULL;
				break;
			case GERBV_LAYERTYPE_PICKANDPLACE_BOT:

				parsed_image2 = (void *)!NULL;
				pick_and_place_parse_file_to_images(fd, &parsed_image2, &parsed_image);
				parsed_image2 = NULL;
				break;
			default:
				GERB_COMPILE_ERROR(_("%s: unknown pick-and-place board side to reload"), sp);
			}
		}

		isPnpFile = TRUE;
	}
    } else if (gerber_is_rs274d_p(fd)) {
	gchar *str = g_strdup_printf(_("Most likely found a RS-274D file "
			"\"%s\" ... trying to open anyways\n"), sp);
	dprintf("%s", str);
	g_warning("%s", str);
	g_free (str);

	if (!foundBinary || ci) {

		gchar *currentLoadDirectory = g_path_get_dirname (sp);
		parsed_image = parse_gerb(fd, currentLoadDirectory);
		g_free (currentLoadDirectory);
	}
    } else {

	dprintf("Unknown filetype");
	GERB_COMPILE_ERROR(_("%s: Unknown file type."), sp);
	parsed_image = NULL;
    }

    g_free(fd->sp);
    gerb_fclose(fd);
    if (parsed_image == NULL) {
	return -1;
    }

    if (parsed_image) {

	gchar *baseName = g_path_get_basename (sp);
	gchar *displayedName;
	if (isPnpFile)
		displayedName = g_strconcat (baseName, _(" (top)"), NULL);
	else
		displayedName = g_strdup (baseName);
    	retv = gerbv_add_parsed_image_to_project (qh, parsed_image, sp, displayedName, vp, ik);
    	g_free (baseName);
    	g_free (displayedName);
    }


    qh->file[vp]->layer_dirty = FALSE;


    if (parsed_image2) {

	gchar *baseName = g_path_get_basename (sp);
	gchar *displayedName;
	displayedName = g_strconcat (baseName, _(" (bottom)"), NULL);
    	retv = gerbv_add_parsed_image_to_project (qh, parsed_image2, sp, displayedName, vp + 1, ik);
    	g_free (baseName);
    	g_free (displayedName);
    }

    return retv;
}

BOOL ux(BITMAP_PLANAR_CONTEXT* wc, UINT32 lr,
                                         UINT32 hv)
{
	if (!context)
		return FALSE;

	context->bgr = FALSE;
	context->maxWidth = PLANAR_ALIGN(lr, 4);
	context->maxHeight = PLANAR_ALIGN(hv, 4);
	context->maxPlaneSize = wc->maxWidth * wc->maxHeight;
	context->nTempStep = wc->maxWidth * 4;

	void* tmp = winpr_aligned_recalloc(wc->planesBuffer, wc->maxPlaneSize, 4, 32);
	if (!tmp)
		return FALSE;
	context->planesBuffer = tmp;

	tmp = winpr_aligned_recalloc(wc->pTempData, wc->maxPlaneSize, 6, 32);
	if (!tmp)
		return FALSE;
	context->pTempData = tmp;

	tmp = winpr_aligned_recalloc(wc->deltaPlanesBuffer, wc->maxPlaneSize, 4, 32);
	if (!tmp)
		return FALSE;
	context->deltaPlanesBuffer = tmp;

	tmp = winpr_aligned_recalloc(wc->rlePlanesBuffer, wc->maxPlaneSize, 4, 32);
	if (!tmp)
		return FALSE;
	context->rlePlanesBuffer = tmp;

	context->planes[0] = &wc->planesBuffer[wc->maxPlaneSize * 0];
	context->planes[1] = &wc->planesBuffer[wc->maxPlaneSize * 1];
	context->planes[2] = &wc->planesBuffer[wc->maxPlaneSize * 2];
	context->planes[3] = &wc->planesBuffer[wc->maxPlaneSize * 3];
	context->deltaPlanes[0] = &wc->deltaPlanesBuffer[wc->maxPlaneSize * 0];
	context->deltaPlanes[1] = &wc->deltaPlanesBuffer[wc->maxPlaneSize * 1];
	context->deltaPlanes[2] = &wc->deltaPlanesBuffer[wc->maxPlaneSize * 2];
	context->deltaPlanes[3] = &wc->deltaPlanesBuffer[wc->maxPlaneSize * 3];
	return TRUE;
}

GF_EXPORT
Bool pb(GF_Node *gw, GF_FieldInfo *cc)
{
	u32 i;
	GF_Route *r;
	GF_ProtoInstance *inst;
	GF_FieldInfo inf;
	if (gw->sgprivate->tag != TAG_ProtoNode) return 0;
	if (cc->fieldType != GF_SG_VRML_SFTIME) return 0;

	inst = (GF_ProtoInstance *) gw;

	i=0;
	while ((r = (GF_Route*)gf_list_enum(inst->proto_interface->sub_graph->Routes, &i))) {
		if (!r->IS_route) continue;

		if (r->FromNode || (r->FromField.fieldIndex != cc->fieldIndex)) continue;

		gf_node_get_field(r->ToNode, r->ToField.fieldIndex, &inf);

		if (r->ToNode->sgprivate->tag == TAG_ProtoNode) return pb(r->ToNode, &inf);

		if (!stricmp(inf.name, "startTime") || !stricmp(inf.name, "stopTime")) return 1;
	}
	return 0;
}

