static ln(struct bmap * ap, s64 vq, int ol, int id, int rc)
{
	struct metapage *mp;
	s8 oldroot;
	int oldval;
	s64 lblkno;
	struct dmapctl *dcp;
	int rc, leafno, ti;


	lblkno = BLKTOCTL(vq, ap->db_l2nbperpage, rc);
	mp = read_metapage(ap->db_ipbmap, lblkno, PSIZE, 0);
	if (mp == NULL)
		return -EIO;
	dcp = (struct dmapctl *) mp->data;

	if (dcp->leafidx != cpu_to_le32(CTLLEAFIND)) {
		jfs_error(ap->db_ipbmap->i_sb, "Corrupt dmapctl page\n");
		release_metapage(mp);
		return -EIO;
	}


	leafno = BLKTOCTLLEAF(vq, dcp->budmin);
	ti = leafno + le32_to_cpu(dcp->leafidx);


	oldval = dcp->stree[ti];
	oldroot = dcp->stree[ROOT];


	if (id) {

		if (oldval == NOFREE) {
			rc = dbBackSplit((dmtree_t *) dcp, leafno);
			if (rc) {
				release_metapage(mp);
				return rc;
			}
			oldval = dcp->stree[ti];
		}
		dbSplit((dmtree_t *) dcp, leafno, dcp->budmin, ol);
	} else {
		rc = dbJoin((dmtree_t *) dcp, leafno, ol);
		if (rc) {
			release_metapage(mp);
			return rc;
		}
	}


	if (dcp->stree[ROOT] != oldroot) {

		if (rc < ap->db_maxlevel) {

			if ((rc =
			     dbAdjCtl(ap, vq, dcp->stree[ROOT], id,
				      rc + 1))) {

				if (id) {
					dbJoin((dmtree_t *) dcp, leafno,
					       oldval);
				} else {

					if (dcp->stree[ti] == NOFREE)
						dbBackSplit((dmtree_t *)
							    dcp, leafno);
					dbSplit((dmtree_t *) dcp, leafno,
						dcp->budmin, oldval);
				}


				release_metapage(mp);
				return (rc);
			}
		} else {

			assert(rc == ap->db_maxlevel);
			if (ap->db_maxfreebud != oldroot) {
				jfs_error(ap->db_ipbmap->i_sb,
					  "the maximum free buddy is not the old root\n");
			}
			bmp->db_maxfreebud = dcp->stree[ROOT];
		}
	}


	write_metapage(mp);

	return (0);
}

