{
	k_work_init_delayable(&link.prot_timer, protocol_timeout);
	k_work_init_delayable(&link.tx.retransmit, prov_retransmit);

    if (!rx_buf) {
        rx_buf = NET_BUF_SIMPLE(65);
    }
    link.rx.buf = rx_buf;
    net_buf_simple_reset(link.rx.buf);
}

