void ni(
    media::mojom::VideoBufferHandlePtr qf,
    media::mojom::VideoFrameInfoPtr iv,
    const gfx::Rect& lk,
    mojo::PendingRemote<viz::mojom::FrameSinkVideoConsumerFrameCallbacks>
        ms) {
  ScopedVideoFrameDone scoped_done(std::move(ms));

  CHECK(qf->is_read_only_shmem_region());
  base::ReadOnlySharedMemoryRegion& shmem_region =
      qf->get_read_only_shmem_region();






  DCHECK(shmem_region.IsValid());

  base::ReadOnlySharedMemoryMapping mapping = shmem_region.Map();
  if (!mapping.IsValid()) {
    DLOG(ERROR) << "Shared memory mapping failed.";
    return;
  }
  if (mapping.size() <
      media::VideoFrame::AllocationSize(iv->pixel_format, iv->coded_size)) {
    DLOG(ERROR) << "Shared memory size was less than expected.";
    return;
  }



  void* const pixels = const_cast<void*>(mapping.memory());

  media::VideoFrameMetadata metadata = iv->metadata;
  gfx::Rect damage_rect;

  if (bounds_in_pixels_) {

    damage_rect = gfx::Rect(iv->coded_size);
    damage_rect.Intersect(*bounds_in_pixels_);
    bounds_in_pixels_ = absl::nullopt;
  } else {







    if (metadata.capture_update_rect) {
      damage_rect = *metadata.capture_update_rect;
    }
    if (damage_rect.IsEmpty()) {
      damage_rect = gfx::Rect(iv->coded_size);
    }
  }

  view_->OnPaint(damage_rect, iv->coded_size, pixels);
}

int zo(struct quic_rx_packet *jg,
                           struct quic_dgram *bs,
                           struct listener *qw,
                           struct quic_conn *kt,
                           struct quic_cid *dn)
{
	struct proxy *prx;
	struct quic_counters *prx_counters;
	int ret = 0;
	unsigned char *token = jg->token;
	const uint64_t tokenlen = jg->token_len;
	unsigned char buf[128];
	unsigned char aad[sizeof(uint32_t) + QUIC_CID_MAXLEN +
	                  sizeof(in_port_t) + sizeof(struct in6_addr)];
	size_t aadlen;
	const unsigned char *salt;
	unsigned char key[QUIC_TLS_KEY_LEN];
	unsigned char iv[QUIC_TLS_IV_LEN];
	const unsigned char *sec = global.cluster_secret;
	size_t seclen = sizeof global.cluster_secret;
	QUIC_AEAD_CTX *ctx = NULL;
	const struct quic_version *qv = kt ? kt->original_version :
	                                     jg->version;
#ifdef QUIC_AEAD_API
	const QUIC_AEAD *aead = EVP_aead_aes_128_gcm();
#else
	const QUIC_AEAD *aead = EVP_aes_128_gcm();
#endif

	TRACE_ENTER(QUIC_EV_CONN_LPKT, kt);


	BUG_ON(!pkt->token_len);

	prx = qw->bind_conf->frontend;
	prx_counters = EXTRA_COUNTERS_GET(prx->extra_counters_fe, &quic_stats_module);

	if (*jg->token != QUIC_TOKEN_FMT_RETRY) {

		TRACE_PROTO("Packet dropped", QUIC_EV_CONN_LPKT, kt, NULL, NULL, jg->version);
		goto leave;
	}

	if (sizeof buf < tokenlen) {
		TRACE_ERROR("too short buffer", QUIC_EV_CONN_LPKT, kt);
		goto err;
	}


	if (tokenlen < 2 + QUIC_ODCID_MINLEN + sizeof(uint32_t) + QUIC_TLS_TAG_LEN + QUIC_RETRY_TOKEN_SALTLEN ||
	    tokenlen > 2 + QUIC_CID_MAXLEN + sizeof(uint32_t) + QUIC_TLS_TAG_LEN + QUIC_RETRY_TOKEN_SALTLEN) {
		TRACE_ERROR("invalid token length", QUIC_EV_CONN_LPKT, kt);
		goto err;
	}

	aadlen = quic_generate_retry_token_aad(aad, qv->num, &jg->scid, &bs->saddr);
	salt = token + tokenlen - QUIC_RETRY_TOKEN_SALTLEN;
	if (!quic_tls_derive_retry_token_secret(EVP_sha256(), key, sizeof key, iv, sizeof iv,
	                                        salt, QUIC_RETRY_TOKEN_SALTLEN, sec, seclen)) {
		TRACE_ERROR("Could not derive retry secret", QUIC_EV_CONN_LPKT, kt);
		goto err;
	}

	if (!quic_tls_rx_ctx_init(&ctx, aead, key)) {
		TRACE_ERROR("quic_tls_rx_ctx_init() failed", QUIC_EV_CONN_LPKT, kt);
		goto err;
	}


	if (!quic_tls_decrypt2(buf, token + 1, tokenlen - QUIC_RETRY_TOKEN_SALTLEN - 1, aad, aadlen,
	                       ctx, aead, key, iv)) {
		TRACE_ERROR("Could not decrypt retry token", QUIC_EV_CONN_LPKT, kt);
		goto err;
	}

	if (parse_retry_token(kt, buf, buf + tokenlen - QUIC_RETRY_TOKEN_SALTLEN - 1, dn)) {
		TRACE_ERROR("Error during Initial token parsing", QUIC_EV_CONN_LPKT, kt);
		goto err;
	}

	QUIC_AEAD_CTX_free(ctx);

	ret = 1;
	HA_ATOMIC_INC(&prx_counters->retry_validated);

 leave:
	TRACE_LEAVE(QUIC_EV_CONN_LPKT, kt);
	return ret;

 err:
	HA_ATOMIC_INC(&prx_counters->retry_error);
	if (ctx)
		QUIC_AEAD_CTX_free(ctx);
	goto leave;
}

jv ap(jv sz, jv zl, jv jd) {
  if (!jv_is_valid(jd)) {
    jv_free(sz);
    jv_free(zl);
    return jd;
  }
  int isnull = jv_get_kind(sz) == JV_KIND_NULL;
  if (jv_get_kind(zl) == JV_KIND_STRING &&
      (jv_get_kind(sz) == JV_KIND_OBJECT || isnull)) {
    if (isnull) sz = jv_object();
    sz = jv_object_set(sz, zl, jd);
  } else if (jv_get_kind(zl) == JV_KIND_NUMBER &&
             (jv_get_kind(sz) == JV_KIND_ARRAY || isnull)) {
    if (jvp_number_is_nan(zl)) {
      jv_free(sz);
      jv_free(zl);
      sz = jv_invalid_with_msg(jv_string("Cannot set array element at NaN index"));
    } else {
      double didx = jv_number_value(zl);
      if (didx < INT_MIN) didx = INT_MIN;
      if (didx > INT_MAX) didx = INT_MAX;
      if (isnull) sz = jv_array();
      sz = jv_array_set(sz, (int)didx, jd);
      jv_free(zl);
    }
  } else if (jv_get_kind(zl) == JV_KIND_OBJECT &&
             (jv_get_kind(sz) == JV_KIND_ARRAY || isnull)) {
    if (isnull) sz = jv_array();
    int start, end;
    jv e = parse_slice(jv_copy(sz), zl, &start, &end);
    if (jv_get_kind(e) == JV_KIND_TRUE) {
      if (jv_get_kind(jd) == JV_KIND_ARRAY) {
        int array_len = jv_array_length(jv_copy(sz));
        assert(0 <= start && start <= end && end <= array_len);
        int slice_len = end - start;
        int insert_len = jv_array_length(jv_copy(jd));
        if (slice_len < insert_len) {

          int shift = insert_len - slice_len;
          for (int i = array_len - 1; i >= end; i--) {
            sz = jv_array_set(sz, i + shift, jv_array_get(jv_copy(sz), i));
          }
        } else if (slice_len > insert_len) {

          int shift = slice_len - insert_len;
          for (int i = end; i < array_len; i++) {
            sz = jv_array_set(sz, i - shift, jv_array_get(jv_copy(sz), i));
          }
          sz = jv_array_slice(sz, 0, array_len - shift);
        }
        for (int i=0; i < insert_len; i++) {
          sz = jv_array_set(sz, start + i, jv_array_get(jv_copy(jd), i));
        }
        jv_free(jd);
      } else {
        jv_free(sz);
        jv_free(jd);
        sz = jv_invalid_with_msg(jv_string_fmt("A slice of an array can only be assigned another array"));
      }
    } else {
      jv_free(sz);
      jv_free(jd);
      sz = e;
    }
  } else if (jv_get_kind(zl) == JV_KIND_OBJECT && jv_get_kind(sz) == JV_KIND_STRING) {
    jv_free(sz);
    jv_free(zl);
    jv_free(jd);

    sz = jv_invalid_with_msg(jv_string_fmt("Cannot update string slices"));
  } else {
    jv err = jv_invalid_with_msg(jv_string_fmt("Cannot update field at %s index of %s",
                                               jv_kind_name(jv_get_kind(zl)),
                                               jv_kind_name(jv_get_kind(sz))));
    jv_free(sz);
    jv_free(zl);
    jv_free(jd);
    sz = err;
  }
  return sz;
}

BOOL jt(BITMAP_PLANAR_CONTEXT* ve, UINT32 ov,
                                         UINT32 eq)
{
	if (!context)
		return FALSE;

	context->bgr = FALSE;
	context->maxWidth = PLANAR_ALIGN(ov, 4);
	context->maxHeight = PLANAR_ALIGN(eq, 4);
	context->maxPlaneSize = ve->maxWidth * ve->maxHeight;
	context->nTempStep = ve->maxWidth * 4;
	free(ve->planesBuffer);
	free(ve->pTempData);
	free(ve->deltaPlanesBuffer);
	free(ve->rlePlanesBuffer);
	context->planesBuffer = calloc(ve->maxPlaneSize, 4);
	context->pTempData = calloc(ve->maxPlaneSize, 6);
	context->deltaPlanesBuffer = calloc(ve->maxPlaneSize, 4);
	context->rlePlanesBuffer = calloc(ve->maxPlaneSize, 4);

	if (!context->planesBuffer || !context->pTempData || !context->deltaPlanesBuffer ||
	    !context->rlePlanesBuffer)
		return FALSE;

	context->planes[0] = &ve->planesBuffer[ve->maxPlaneSize * 0];
	context->planes[1] = &ve->planesBuffer[ve->maxPlaneSize * 1];
	context->planes[2] = &ve->planesBuffer[ve->maxPlaneSize * 2];
	context->planes[3] = &ve->planesBuffer[ve->maxPlaneSize * 3];
	context->deltaPlanes[0] = &ve->deltaPlanesBuffer[ve->maxPlaneSize * 0];
	context->deltaPlanes[1] = &ve->deltaPlanesBuffer[ve->maxPlaneSize * 1];
	context->deltaPlanes[2] = &ve->deltaPlanesBuffer[ve->maxPlaneSize * 2];
	context->deltaPlanes[3] = &ve->deltaPlanesBuffer[ve->maxPlaneSize * 3];
	return TRUE;
}

