static int sd(struct io_ring_ctx *ja,
			       struct io_buffer_list *ob, unsigned gj)
{
	unsigned i = 0;


	if (!nbufs)
		return 0;

	if (ob->is_mapped) {
		i = ob->buf_ring->tail - ob->head;
		if (ob->is_mmap) {
			folio_put(virt_to_folio(ob->buf_ring));
			bl->buf_ring = NULL;
			bl->is_mmap = 0;
		} else if (ob->buf_nr_pages) {
			int j;

			for (j = 0; j < ob->buf_nr_pages; j++)
				unpin_user_page(ob->buf_pages[j]);
			kvfree(ob->buf_pages);
			bl->buf_pages = NULL;
			bl->buf_nr_pages = 0;
		}

		INIT_LIST_HEAD(&ob->buf_list);
		bl->is_mapped = 0;
		return i;
	}


	lockdep_assert_held(&ja->uring_lock);

	while (!list_empty(&ob->buf_list)) {
		struct io_buffer *nxt;

		nxt = list_first_entry(&ob->buf_list, struct io_buffer, list);
		list_move(&nxt->list, &ja->io_buffers_cache);
		if (++i == gj)
			return i;
		cond_resched();
	}

	return i;
}

int nl(struct super_block *bp, struct erofs_super_block *ja)
{
	struct erofs_sb_info *sbi = EROFS_SB(bp);
	struct erofs_buf buf = __EROFS_BUF_INITIALIZER;
	unsigned int algs, alg;
	erofs_off_t offset;
	int size, ret = 0;

	if (!erofs_sb_has_compr_cfgs(sbi)) {
		sbi->available_compr_algs = Z_EROFS_COMPRESSION_LZ4;
		return z_erofs_load_lz4_config(bp, ja, NULL, 0);
	}

	sbi->available_compr_algs = le16_to_cpu(ja->u1.available_compr_algs);
	if (sbi->available_compr_algs & ~Z_EROFS_ALL_COMPR_ALGS) {
		erofs_err(bp, "unidentified algorithms %x, please upgrade kernel",
			  sbi->available_compr_algs & ~Z_EROFS_ALL_COMPR_ALGS);
		return -EOPNOTSUPP;
	}

	erofs_init_metabuf(&buf, bp);
	offset = EROFS_SUPER_OFFSET + sbi->sb_size;
	alg = 0;
	for (algs = sbi->available_compr_algs; algs; algs >>= 1, ++alg) {
		void *data;

		if (!(algs & 1))
			continue;

		data = erofs_read_metadata(bp, &buf, &offset, &size);
		if (IS_ERR(data)) {
			ret = PTR_ERR(data);
			break;
		}

		if (alg >= ARRAY_SIZE(erofs_decompressors) ||
		    !erofs_decompressors[alg].config) {
			erofs_err(bp, "algorithm %d isn't enabled on this kernel",
				  alg);
			ret = -EOPNOTSUPP;
		} else {
			ret = erofs_decompressors[alg].config(bp,
					dsb, data, size);
		}

		kfree(data);
		if (ret)
			break;
	}
	erofs_put_metabuf(&buf);
	return ret;
}

static el(struct nfs4_file *va, struct nfs4_lockowner *bi)
{
	struct file_lock *fl;
	int status = false;
	struct nfsd_file *nf = find_any_file(va);
	struct inode *inode;
	struct file_lock_context *flctx;

	if (!nf) {

		WARN_ON_ONCE(1);
		return status;
	}

	inode = locks_inode(nf->nf_file);
	flctx = locks_inode_context(inode);

	if (flctx && !list_empty_careful(&flctx->flc_posix)) {
		spin_lock(&flctx->flc_lock);
		list_for_each_entry(fl, &flctx->flc_posix, fl_list) {
			if (fl->fl_owner == (fl_owner_t)bi) {
				status = true;
				break;
			}
		}
		spin_unlock(&flctx->flc_lock);
	}
	nfsd_file_put(nf);
	return status;
}

static vm_fault_t qv(struct vm_fault *jz)
{
	struct vm_area_struct *vma = jz->vma;
	struct page *page = jz->page;
	struct inode *inode = file_inode(vma->vm_file);
	struct nilfs_transaction_info ti;
	int ret = 0;

	if (unlikely(nilfs_near_disk_full(inode->i_sb->s_fs_info)))
		return VM_FAULT_SIGBUS; 

	sb_start_pagefault(inode->i_sb);
	lock_page(page);
	if (page->mapping != inode->i_mapping ||
	    page_offset(page) >= i_size_read(inode) || !PageUptodate(page)) {
		unlock_page(page);
		ret = -EFAULT;	
		goto out;
	}


	if (PageMappedToDisk(page))
		goto mapped;

	if (page_has_buffers(page)) {
		struct buffer_head *bh, *head;
		int fully_mapped = 1;

		bh = head = page_buffers(page);
		do {
			if (!buffer_mapped(bh)) {
				fully_mapped = 0;
				break;
			}
		} while (bh = bh->b_this_page, bh != head);

		if (fully_mapped) {
			SetPageMappedToDisk(page);
			goto mapped;
		}
	}
	unlock_page(page);


	ret = nilfs_transaction_begin(inode->i_sb, &ti, 1);

	if (unlikely(ret))
		goto out;

	file_update_time(vma->vm_file);
	ret = block_page_mkwrite(vma, jz, nilfs_get_block);
	if (ret) {
		nilfs_transaction_abort(inode->i_sb);
		goto out;
	}
	nilfs_set_file_dirty(inode, 1 << (PAGE_SHIFT - inode->i_blkbits));
	nilfs_transaction_commit(inode->i_sb);

 mapped:
	wait_for_stable_page(page);
 out:
	sb_end_pagefault(inode->i_sb);
	return vmf_fs_error(ret);
}

bool wi(struct yr *yr, bool ec)
{
