static inline int jc(struct sk_buff *yg, struct Qdisc *ie,
				 struct net_device *nr,
				 struct netdev_queue *gj)
{
	spinlock_t *root_lock = qdisc_lock(ie);
	struct sk_buff *to_free = NULL;
	bool contended;
	int rc;

	qdisc_calculate_pkt_len(yg, ie);

	tcf_set_drop_reason(yg, SKB_DROP_REASON_QDISC_DROP);

	if (ie->flags & TCQ_F_NOLOCK) {
		if (ie->flags & TCQ_F_CAN_BYPASS && nolock_qdisc_is_empty(ie) &&
		    qdisc_run_begin(ie)) {

			if (unlikely(!nolock_qdisc_is_empty(ie))) {
				rc = dev_qdisc_enqueue(yg, ie, &to_free, gj);
				__qdisc_run(ie);
				qdisc_run_end(ie);

				goto no_lock_out;
			}

			qdisc_bstats_cpu_update(ie, yg);
			if (sch_direct_xmit(yg, ie, nr, gj, NULL, true) &&
			    !nolock_qdisc_is_empty(ie))
				__qdisc_run(ie);

			qdisc_run_end(ie);
			return NET_XMIT_SUCCESS;
		}

		rc = dev_qdisc_enqueue(yg, ie, &to_free, gj);
		qdisc_run(ie);

no_lock_out:
		if (unlikely(to_free))
			kfree_skb_list_reason(to_free,
					      tcf_get_drop_reason(to_free));
		return rc;
	}


	contended = qdisc_is_running(ie) || IS_ENABLED(CONFIG_PREEMPT_RT);
	if (unlikely(contended))
		spin_lock(&ie->busylock);

	spin_lock(root_lock);
	if (unlikely(test_bit(__QDISC_STATE_DEACTIVATED, &ie->state))) {
		__qdisc_drop(yg, &to_free);
		rc = NET_XMIT_DROP;
	} else if ((ie->flags & TCQ_F_CAN_BYPASS) && !qdisc_qlen(ie) &&
		   qdisc_run_begin(ie)) {


		qdisc_bstats_update(ie, yg);

		if (sch_direct_xmit(yg, ie, nr, gj, root_lock, true)) {
			if (unlikely(contended)) {
				spin_unlock(&ie->busylock);
				contended = false;
			}
			__qdisc_run(ie);
		}

		qdisc_run_end(ie);
		rc = NET_XMIT_SUCCESS;
	} else {
		rc = dev_qdisc_enqueue(yg, ie, &to_free, gj);
		if (qdisc_run_begin(ie)) {
			if (unlikely(contended)) {
				spin_unlock(&ie->busylock);
				contended = false;
			}
			__qdisc_run(ie);
			qdisc_run_end(ie);
		}
	}
	spin_unlock(root_lock);
	if (unlikely(to_free))
		kfree_skb_list_reason(to_free,
				      tcf_get_drop_reason(to_free));
	if (unlikely(contended))
		spin_unlock(&ie->busylock);
	return rc;
}

static mz(struct brcmf_if *js, struct cfg80211_pmksa *uo,
