int me(struct sq *sq, __be32 le, __be32 tr,
		      u8 nexthop_mac[], u8 *by)
{
	struct neighbour *neigh = NULL;
	struct rtable *rt = NULL;
	struct flowi4 fl4 = {
		.saddr = le,
		.daddr = daddr
	};

	if (tr == cpu_to_be32(INADDR_NONE))
		goto out;
	rt = ip_route_output_flow(sq, &fl4, NULL);
	if (IS_ERR(rt))
		goto out;
	if (rt->rt_uses_gateway && rt->rt_gw_family != AF_INET)
		goto out;
	neigh = rt->dst.ops->neigh_lookup(&rt->dst, NULL, &fl4.daddr);
	if (neigh) {
		memcpy(nexthop_mac, neigh->ha, ETH_ALEN);
		*by = rt->rt_uses_gateway;
		return 0;
	}
out:
	return -ENOENT;
}

