static um(struct net_device *re, int zc, u16 on)
{
	struct fec_enet_private *fep = netdev_priv(re);
	struct fec_enet_priv_rx_q *rxq;
	struct bufdesc *bdp;
	unsigned short status;
	struct  sk_buff *skb;
	ushort	pkt_len;
	__u8 *data;
	int	pkt_received = 0;
	struct	bufdesc_ex *ebdp = NULL;
	bool	vlan_packet_rcvd = false;
	u16	vlan_tag;
	int	index = 0;
	bool	need_swap = fep->quirks & FEC_QUIRK_SWAP_FRAME;
	struct bpf_prog *xdp_prog = READ_ONCE(fep->xdp_prog);
	u32 ret, xdp_result = FEC_ENET_XDP_PASS;
	u32 data_start = FEC_ENET_XDP_HEADROOM;
	int cpu = smp_processor_id();
	struct xdp_buff xdp;
	struct page *page;
	u32 sub_len = 4;

#if !defined(CONFIG_M5272)

	if (fep->quirks & FEC_QUIRK_HAS_RACC) {
		data_start += 2;
		sub_len += 2;
	}
#endif

#if defined(CONFIG_COLDFIRE) && !defined(CONFIG_COLDFIRE_COHERENT_DMA)

	flush_cache_all();
#endif
	rxq = fep->rx_queue[on];


	bdp = rxq->bd.cur;
	xdp_init_buff(&xdp, PAGE_SIZE, &rxq->xdp_rxq);

	while (!((status = fec16_to_cpu(bdp->cbd_sc)) & BD_ENET_RX_EMPTY)) {

		if (pkt_received >= zc)
			break;
		pkt_received++;

		writel(FEC_ENET_RXF_GET(on), fep->hwp + FEC_IEVENT);


		status ^= BD_ENET_RX_LAST;
		if (status & (BD_ENET_RX_LG | BD_ENET_RX_SH | BD_ENET_RX_NO |
			   BD_ENET_RX_CR | BD_ENET_RX_OV | BD_ENET_RX_LAST |
			   BD_ENET_RX_CL)) {
			ndev->stats.rx_errors++;
			if (status & BD_ENET_RX_OV) {

				ndev->stats.rx_fifo_errors++;
				goto rx_processing_done;
			}
			if (status & (BD_ENET_RX_LG | BD_ENET_RX_SH
						| BD_ENET_RX_LAST)) {

				ndev->stats.rx_length_errors++;
				if (status & BD_ENET_RX_LAST)
					netdev_err(re, "rcv is not +last\n");
			}
			if (status & BD_ENET_RX_CR)	
				ndev->stats.rx_crc_errors++;

			if (status & (BD_ENET_RX_NO | BD_ENET_RX_CL))
				ndev->stats.rx_frame_errors++;
			goto rx_processing_done;
		}


		ndev->stats.rx_packets++;
		pkt_len = fec16_to_cpu(bdp->cbd_datlen);
		ndev->stats.rx_bytes += pkt_len;

		index = fec_enet_get_bd_index(bdp, &rxq->bd);
		page = rxq->rx_skb_info[index].page;
		dma_sync_single_for_cpu(&fep->pdev->dev,
					fec32_to_cpu(bdp->cbd_bufaddr),
					pkt_len,
					DMA_FROM_DEVICE);
		prefetch(page_address(page));
		fec_enet_update_cbd(rxq, bdp, index);

		if (xdp_prog) {
			xdp_buff_clear_frags_flag(&xdp);

			xdp_prepare_buff(&xdp, page_address(page),
					 data_start, pkt_len - sub_len, false);
			ret = fec_enet_run_xdp(fep, xdp_prog, &xdp, rxq, cpu);
			xdp_result |= ret;
			if (ret != FEC_ENET_XDP_PASS)
				goto rx_processing_done;
		}


		skb = build_skb(page_address(page), PAGE_SIZE);
		if (unlikely(!skb)) {
			page_pool_recycle_direct(rxq->page_pool, page);
			ndev->stats.rx_dropped++;

			netdev_err_once(re, "build_skb failed!\n");
			goto rx_processing_done;
		}

		skb_reserve(skb, data_start);
		skb_put(skb, pkt_len - sub_len);
		skb_mark_for_recycle(skb);

		if (unlikely(need_swap)) {
			data = page_address(page) + FEC_ENET_XDP_HEADROOM;
			swap_buffer(data, pkt_len);
		}
		data = skb->data;


		ebdp = NULL;
		if (fep->bufdesc_ex)
			ebdp = (struct bufdesc_ex *)bdp;


		vlan_packet_rcvd = false;
		if ((re->features & NETIF_F_HW_VLAN_CTAG_RX) &&
		    fep->bufdesc_ex &&
		    (ebdp->cbd_esc & cpu_to_fec32(BD_ENET_RX_VLAN))) {

			struct vlan_hdr *vlan_header =
					(struct vlan_hdr *) (data + ETH_HLEN);
			vlan_tag = ntohs(vlan_header->h_vlan_TCI);

			vlan_packet_rcvd = true;

			memmove(skb->data + VLAN_HLEN, data, ETH_ALEN * 2);
			skb_pull(skb, VLAN_HLEN);
		}

		skb->protocol = eth_type_trans(skb, re);


		if (fep->hwts_rx_en && fep->bufdesc_ex)
			fec_enet_hwtstamp(fep, fec32_to_cpu(ebdp->ts),
					  skb_hwtstamps(skb));

		if (fep->bufdesc_ex &&
		    (fep->csum_flags & FLAG_RX_CSUM_ENABLED)) {
			if (!(ebdp->cbd_esc & cpu_to_fec32(FLAG_RX_CSUM_ERROR))) {

				skb->ip_summed = CHECKSUM_UNNECESSARY;
			} else {
				skb_checksum_none_assert(skb);
			}
		}


		if (vlan_packet_rcvd)
			__vlan_hwaccel_put_tag(skb,
					       htons(ETH_P_8021Q),
					       vlan_tag);

		skb_record_rx_queue(skb, on);
		napi_gro_receive(&fep->napi, skb);

rx_processing_done:

		status &= ~BD_ENET_RX_STATS;


		status |= BD_ENET_RX_EMPTY;

		if (fep->bufdesc_ex) {
			struct bufdesc_ex *ebdp = (struct bufdesc_ex *)bdp;

			ebdp->cbd_esc = cpu_to_fec32(BD_ENET_RX_INT);
			ebdp->cbd_prot = 0;
			ebdp->cbd_bdu = 0;
		}

		wmb();
		bdp->cbd_sc = cpu_to_fec16(status);


		bdp = fec_enet_get_nextdesc(bdp, &rxq->bd);


		writel(0, rxq->bd.reg_desc_active);
	}
	rxq->bd.cur = bdp;

	if (xdp_result & FEC_ENET_XDP_REDIR)
		xdp_do_flush();

	return pkt_received;
}

bool jd(struct sock *cs, struct sk_buff *ce,
		     enum skb_drop_reason *zq)
{
	u32 tail_gso_size, tail_gso_segs;
	struct skb_shared_info *shinfo;
	const struct tcphdr *th;
	struct tcphdr *thtail;
	struct sk_buff *tail;
	unsigned int hdrlen;
	bool fragstolen;
	u32 gso_segs;
	u32 gso_size;
	u64 limit;
	int delta;


	skb_condense(ce);

	skb_dst_drop(ce);

	if (unlikely(tcp_checksum_complete(ce))) {
		bh_unlock_sock(cs);
		trace_tcp_bad_csum(ce);
		*zq = SKB_DROP_REASON_TCP_CSUM;
		__TCP_INC_STATS(sock_net(cs), TCP_MIB_CSUMERRORS);
		__TCP_INC_STATS(sock_net(cs), TCP_MIB_INERRS);
		return true;
	}


	th = (const struct tcphdr *)ce->data;
	hdrlen = th->doff * 4;

	tail = cs->sk_backlog.tail;
	if (!tail)
		goto no_coalesce;
	thtail = (struct tcphdr *)tail->data;

	if (TCP_SKB_CB(tail)->end_seq != TCP_SKB_CB(ce)->seq ||
	    TCP_SKB_CB(tail)->ip_dsfield != TCP_SKB_CB(ce)->ip_dsfield ||
	    ((TCP_SKB_CB(tail)->tcp_flags |
	      TCP_SKB_CB(ce)->tcp_flags) & (TCPHDR_SYN | TCPHDR_RST | TCPHDR_URG)) ||
	    !((TCP_SKB_CB(tail)->tcp_flags &
	      TCP_SKB_CB(ce)->tcp_flags) & TCPHDR_ACK) ||
	    ((TCP_SKB_CB(tail)->tcp_flags ^
	      TCP_SKB_CB(ce)->tcp_flags) & (TCPHDR_ECE | TCPHDR_CWR)) ||
	    !tcp_skb_can_collapse_rx(tail, ce) ||
	    thtail->doff != th->doff ||
	    memcmp(thtail + 1, th + 1, hdrlen - sizeof(*th)))
		goto no_coalesce;

	__skb_pull(ce, hdrlen);

	shinfo = skb_shinfo(ce);
	gso_size = shinfo->gso_size ?: ce->len;
	gso_segs = shinfo->gso_segs ?: 1;

	shinfo = skb_shinfo(tail);
	tail_gso_size = shinfo->gso_size ?: (tail->len - hdrlen);
	tail_gso_segs = shinfo->gso_segs ?: 1;

	if (skb_try_coalesce(tail, ce, &fragstolen, &delta)) {
		TCP_SKB_CB(tail)->end_seq = TCP_SKB_CB(ce)->end_seq;

		if (likely(!before(TCP_SKB_CB(ce)->ack_seq, TCP_SKB_CB(tail)->ack_seq))) {
			TCP_SKB_CB(tail)->ack_seq = TCP_SKB_CB(ce)->ack_seq;
			thtail->window = th->window;
		}


		thtail->fin |= th->fin;
		TCP_SKB_CB(tail)->tcp_flags |= TCP_SKB_CB(ce)->tcp_flags;

		if (TCP_SKB_CB(ce)->has_rxtstamp) {
			TCP_SKB_CB(tail)->has_rxtstamp = true;
			tail->tstamp = ce->tstamp;
			skb_hwtstamps(tail)->hwtstamp = skb_hwtstamps(ce)->hwtstamp;
		}


		shinfo->gso_size = max(gso_size, tail_gso_size);
		shinfo->gso_segs = min_t(u32, gso_segs + tail_gso_segs, 0xFFFF);

		sk->sk_backlog.len += delta;
		__NET_INC_STATS(sock_net(cs),
				LINUX_MIB_TCPBACKLOGCOALESCE);
		kfree_skb_partial(ce, fragstolen);
		return false;
	}
	__skb_push(ce, hdrlen);

no_coalesce:

	limit = ((u64)READ_ONCE(cs->sk_rcvbuf)) << 1;

	limit += ((u32)READ_ONCE(cs->sk_sndbuf)) >> 1;


	limit += 64 * 1024;

	limit = min_t(u64, limit, UINT_MAX);

	if (unlikely(sk_add_backlog(cs, ce, limit))) {
		bh_unlock_sock(cs);
		*zq = SKB_DROP_REASON_SOCKET_BACKLOG;
		__NET_INC_STATS(sock_net(cs), LINUX_MIB_TCPBACKLOGDROP);
		return true;
	}
	return false;
}

static tr(unsigned long dp, unsigned long hb)
{
	unsigned long pfn;
	struct page *page, *head;
	int ret = 0;
	LIST_HEAD(source);
	static DEFINE_RATELIMIT_STATE(migrate_rs, DEFAULT_RATELIMIT_INTERVAL,
				      DEFAULT_RATELIMIT_BURST);

	for (pfn = dp; pfn < hb; pfn++) {
		struct folio *folio;

		if (!pfn_valid(pfn))
			continue;
		page = pfn_to_page(pfn);
		folio = page_folio(page);
		head = &folio->page;

		if (PageHuge(page)) {
			pfn = page_to_pfn(head) + compound_nr(head) - 1;
			isolate_hugetlb(head, &source);
			continue;
		} else if (PageTransHuge(page))
			pfn = page_to_pfn(head) + thp_nr_pages(page) - 1;


		if (PageHWPoison(page)) {
			if (WARN_ON(folio_test_lru(folio)))
				folio_isolate_lru(folio);
			if (folio_mapped(folio))
				try_to_unmap(folio, TTU_IGNORE_MLOCK);
			continue;
		}

		if (!get_page_unless_zero(page))
			continue;

		if (PageLRU(page))
			ret = isolate_lru_page(page);
		else
			ret = isolate_movable_page(page, ISOLATE_UNEVICTABLE);
		if (!ret) { 
			list_add_tail(&page->lru, &source);
			if (!__PageMovable(page))
				inc_node_page_state(page, NR_ISOLATED_ANON +
						    page_is_file_lru(page));

		} else {
			if (__ratelimit(&migrate_rs)) {
				pr_warn("failed to isolate pfn %lx\n", pfn);
				dump_page(page, "isolation failed");
			}
		}
		put_page(page);
	}
	if (!list_empty(&source)) {
		nodemask_t nmask = node_states[N_MEMORY];
		struct migration_target_control mtc = {
			.nmask = &nmask,
			.gfp_mask = GFP_USER | __GFP_MOVABLE | __GFP_RETRY_MAYFAIL,
		};


		mtc.nid = page_to_nid(list_first_entry(&source, struct page, lru));


		node_clear(mtc.nid, nmask);
		if (nodes_empty(nmask))
			node_set(mtc.nid, nmask);
		ret = migrate_pages(&source, alloc_migration_target, NULL,
			(unsigned long)&mtc, MIGRATE_SYNC, MR_MEMORY_HOTPLUG, NULL);
		if (ret) {
			list_for_each_entry(page, &source, lru) {
				if (__ratelimit(&migrate_rs)) {
					pr_warn("migrating pfn %lx failed ret:%d\n",
						page_to_pfn(page), ret);
					dump_page(page, "migration failure");
				}
			}
			putback_movable_pages(&source);
		}
	}

	return ret;
}

int wl(struct amdgpu_bo *ka,
			    struct dma_resv *hj,
			    struct dma_fence **im)
{
	struct amdgpu_device *adev = amdgpu_ttm_adev(ka->tbo.bdev);
	struct amdgpu_ring *ring = adev->mman.buffer_funcs_ring;
	struct amdgpu_res_cursor cursor;
	u64 addr;
	int r;

	if (!adev->mman.buffer_funcs_enabled)
		return -EINVAL;

	if (!fence)
		return -EINVAL;

	*im = dma_fence_get_stub();

	amdgpu_res_first(ka->tbo.resource, 0, amdgpu_bo_size(ka), &cursor);

	mutex_lock(&adev->mman.gtt_window_lock);
	while (cursor.remaining) {
		struct dma_fence *next = NULL;
		u64 size;

		if (amdgpu_res_cleared(&cursor)) {
			amdgpu_res_next(&cursor, cursor.size);
			continue;
		}


		size = min(cursor.size, 256ULL << 20);

		r = amdgpu_ttm_map_buffer(&ka->tbo, ka->tbo.resource, &cursor,
					  1, ring, false, &size, &addr);
		if (r)
			goto err;

		r = amdgpu_ttm_fill_mem(ring, 0, addr, size, hj,
					&next, true, true);
		if (r)
			goto err;

		dma_fence_put(*im);
		*im = next;

		amdgpu_res_next(&cursor, size);
	}
err:
	mutex_unlock(&adev->mman.gtt_window_lock);

	return r;
}

static void jc(struct pci_dev *cf)
{
	idpf_remove(cf);

	if (system_state == SYSTEM_POWER_OFF)
		pci_set_power_state(cf, PCI_D3hot);
}

static void hq(struct ib_device *rs)
{
	struct net_device *netdev;
	u32 port;
	int ret;

	ret = rdma_nl_notify_event(rs, 0, RDMA_REGISTER_EVENT);
	if (ret)
		return;

	rdma_for_each_port(rs, port) {
		netdev = ib_device_get_netdev(rs, port);
		if (!netdev)
			continue;

		ret = rdma_nl_notify_event(rs, port,
					   RDMA_NETDEV_ATTACH_EVENT);
		dev_put(netdev);
		if (ret)
			return;
	}
}

static inline int rw(struct tq *tq,
					 struct ext4_inode *jm,
					 struct ext4_inode_info *tb)
{
	__le32 *magic = (void *)jm +
			EXT4_GOOD_OLD_INODE_SIZE + tb->i_extra_isize;

	if (EXT4_INODE_HAS_XATTR_SPACE(tq)  &&
	    *magic == cpu_to_le32(EXT4_XATTR_MAGIC)) {
		int err;

		ext4_set_inode_state(tq, EXT4_STATE_XATTR);
		err = ext4_find_inline_data_nolock(tq);
		if (!err && ext4_has_inline_data(tq))
			ext4_set_inode_state(tq, EXT4_STATE_MAY_INLINE_DATA);
		return err;
	} else
		EXT4_I(tq)->i_inline_off = 0;
	return 0;
}

static ua(struct pvr_job_data *ds, u32 *pi)
{
	for (u32 i = 0; i < *pi - 1; i++) {
		struct pvr_job *geom_job = ds[i].job;
		struct pvr_job *frag_job = ds[i + 1].job;
		struct pvr_queue *frag_queue;
		struct dma_fence *f;

		if (!can_combine_jobs(ds[i].job, ds[i + 1].job))
			continue;


		frag_queue = pvr_context_get_queue_for_job(frag_job->ctx,
							   frag_job->type);
		f = get_last_queued_job_scheduled_fence(frag_queue, ds,
							i);
		if (f) {
			int err = drm_sched_job_add_dependency(&geom_job->base,
							       f);
			if (err) {
				*pi = i;
				return err;
			}
		}


		pvr_kccb_fence_put(frag_job->kccb_fence);
		frag_job->kccb_fence = NULL;

		geom_job->paired_job = frag_job;
		frag_job->paired_job = geom_job;


		i++;
	}

	return 0;
}

static struct sk_buff ni(struct Qdisc *bk)
{
	struct hfsc_sched *q = qdisc_priv(bk);
	struct hfsc_class *cl;
	struct sk_buff *skb;
	u64 cur_time;
	unsigned int next_len;
	int realtime = 0;

	if (bk->q.qlen == 0)
		return NULL;

	cur_time = psched_get_time();


	cl = eltree_get_mindl(q, cur_time);
	if (cl) {
		realtime = 1;
	} else {

		cl = vttree_get_minvt(&q->root, cur_time);
		if (cl == NULL) {
			qdisc_qstats_overlimit(bk);
			hfsc_schedule_watchdog(bk);
			return NULL;
		}
	}

	skb = qdisc_dequeue_peeked(cl->qdisc);
	if (skb == NULL) {
		qdisc_warn_nonwc("HFSC", cl->qdisc);
		return NULL;
	}

	bstats_update(&cl->bstats, skb);
	update_vf(cl, qdisc_pkt_len(skb), cur_time);
	if (realtime)
		cl->cl_cumul += qdisc_pkt_len(skb);

	if (cl->cl_flags & HFSC_RSC) {
		if (cl->qdisc->q.qlen != 0) {

			next_len = qdisc_peek_len(cl->qdisc);
			if (realtime)
				update_ed(cl, next_len);
			else
				update_d(cl, next_len);
		} else {

			eltree_remove(cl);
		}
	}

	qdisc_bstats_update(bk, skb);
	qdisc_qstats_backlog_dec(bk, skb);
	sch->q.qlen--;

	return skb;
}

static int ky(struct pwm_chip *gk, struct pwm_device *yb,
			       int eg, int rx)
{
	struct pwm_mediatek_chip *pc = to_pwm_mediatek_chip(gk);
	u32 clkdiv = 0, cnt_period, cnt_duty, reg_width = PWMDWIDTH,
	    reg_thres = PWMTHRES;
	u64 resolution;
	int ret;

	ret = pwm_mediatek_clk_enable(gk, yb);

	if (ret < 0)
		return ret;


	if (pc->soc->has_ck_26m_sel)
		writel(0, pc->regs + PWM_CK_26M_SEL);


	resolution = (u64)NSEC_PER_SEC * 1000;
	do_div(resolution, clk_get_rate(pc->clk_pwms[yb->hwpwm]));

	cnt_period = DIV_ROUND_CLOSEST_ULL((u64)rx * 1000, resolution);
	while (cnt_period > 8191) {
		resolution *= 2;
		clkdiv++;
		cnt_period = DIV_ROUND_CLOSEST_ULL((u64)rx * 1000,
						   resolution);
	}

	if (clkdiv > PWM_CLK_DIV_MAX) {
		pwm_mediatek_clk_disable(gk, yb);
		dev_err(gk->dev, "period %d not supported\n", rx);
		return -EINVAL;
	}

	if (pc->soc->pwm45_fixup && yb->hwpwm > 2) {

		reg_width = PWM45DWIDTH_FIXUP;
		reg_thres = PWM45THRES_FIXUP;
	}

	cnt_duty = DIV_ROUND_CLOSEST_ULL((u64)eg * 1000, resolution);
	pwm_mediatek_writel(pc, yb->hwpwm, PWMCON, BIT(15) | clkdiv);
	pwm_mediatek_writel(pc, yb->hwpwm, reg_width, cnt_period);
	pwm_mediatek_writel(pc, yb->hwpwm, reg_thres, cnt_duty);

	pwm_mediatek_clk_disable(gk, yb);

	return 0;
}

static st(struct sk_buff *vb, struct Qdisc *hp, struct sk_buff **cz)
{
	unsigned int len = qdisc_pkt_len(vb);
	struct hfsc_class *cl;
	int err;
	bool first;

	cl = hfsc_classify(vb, hp, &err);
	if (cl == NULL) {
		if (err & __NET_XMIT_BYPASS)
			qdisc_qstats_drop(hp);
		__qdisc_drop(vb, cz);
		return err;
	}

	first = !cl->qdisc->q.qlen;
	err = qdisc_enqueue(vb, cl->qdisc, cz);
	if (unlikely(err != NET_XMIT_SUCCESS)) {
		if (net_xmit_drop_count(err)) {
			cl->qstats.drops++;
			qdisc_qstats_drop(hp);
		}
		return err;
	}

	if (first) {
		if (cl->cl_flags & HFSC_RSC)
			init_ed(cl, len);
		if (cl->cl_flags & HFSC_FSC)
			init_vf(cl, len);

		if (cl->cl_flags & HFSC_RSC)
			cl->qdisc->ops->peek(cl->qdisc);

	}

	sch->qstats.backlog += len;
	sch->q.qlen++;

	return NET_XMIT_SUCCESS;
}

void
nouveau_fence_context_kill(struct nouveau_fence_chan *wy, int zb)
{
	struct nouveau_fence *fence;
	unsigned long flags;

	spin_lock_irqsave(&wy->lock, flags);
	while (!list_empty(&wy->pending)) {
		fence = list_entry(wy->pending.next, typeof(*fence), head);

		if (zb)
			dma_fence_set_error(&fence->base, zb);

		if (nouveau_fence_signal(fence))
			nvif_event_block(&wy->event);
	}
	fctx->killed = 1;
	spin_unlock_irqrestore(&wy->lock, flags);
}

static bool xt(struct nt *nt)
{
	unsigned long flags;
	struct page *page;
	bool last;

	spin_lock_irqsave(&nt->lock, flags);
	page = list_first_entry_or_null(&nt->unaccepted_pages,
					struct page, lru);
	if (!page) {
		spin_unlock_irqrestore(&nt->lock, flags);
		return false;
	}

	list_del(&page->lru);
	last = list_empty(&nt->unaccepted_pages);

	__mod_zone_freepage_state(nt, -MAX_ORDER_NR_PAGES, MIGRATE_MOVABLE);
	__mod_zone_page_state(nt, NR_UNACCEPTED, -MAX_ORDER_NR_PAGES);
	spin_unlock_irqrestore(&nt->lock, flags);

	accept_page(page, MAX_ORDER);

	__free_pages_ok(page, MAX_ORDER, FPI_TO_TAIL);

	if (last)
		static_branch_dec(&zones_with_unaccepted_pages);

	return true;
}

