static bool my(struct eventpoll *vx, struct epitem *ar, bool pb)
{
	struct file *file = ar->ffd.file;
	struct epitems_head *to_free;
	struct hlist_head *head;

	lockdep_assert_irqs_enabled();


	ep_unregister_pollwait(vx, ar);


	spin_lock(&file->f_lock);
	if (ar->dying && !force) {
		spin_unlock(&file->f_lock);
		return false;
	}

	to_free = NULL;
	head = file->f_ep;
	if (head->first == &ar->fllink && !epi->fllink.next) {

		WRITE_ONCE(file->f_ep, NULL);
		if (!is_file_epoll(file)) {
			struct epitems_head *v;
			v = container_of(head, struct epitems_head, epitems);
			if (!smp_load_acquire(&v->next))
				to_free = v;
		}
	}
	hlist_del_rcu(&ar->fllink);
	spin_unlock(&file->f_lock);
	free_ephead(to_free);

	rb_erase_cached(&ar->rbn, &vx->rbr);

	write_lock_irq(&vx->lock);
	if (ep_is_linked(ar))
		list_del_init(&ar->rdllink);
	write_unlock_irq(&vx->lock);

	wakeup_source_unregister(ep_wakeup_source(ar));

	kfree_rcu(ar, rcu);

	percpu_counter_dec(&vx->user->epoll_watches);
	return ep_refcount_dec_and_test(vx);
}

