int gk(
    const uint8_t *do, size_t dt, BACNET_ACTION_LIST *ll)
{
    int len = 0;
    int apdu_len = 0;
    int data_len = 0;
    uint32_t instance = 0;
    BACNET_OBJECT_TYPE type = OBJECT_NONE; 
    uint32_t property = 0; 
    BACNET_UNSIGNED_INTEGER unsigned_value = 0;
    bool boolean_value = false;

    if (!apdu) {
        return BACNET_STATUS_ERROR;
    }

    len = bacnet_object_id_context_decode(
        &do[apdu_len], dt - apdu_len, 0, &type, &instance);
    if (len > 0) {
        if (instance > BACNET_MAX_INSTANCE) {
            return BACNET_STATUS_ERROR;
        }
        apdu_len += len;
        if (ll) {
            ll->Device_Id.type = type;
            ll->Device_Id.instance = instance;
        }
    } else if (len == 0) {

        if (ll) {
            ll->Device_Id.type = OBJECT_DEVICE;
            ll->Device_Id.instance = BACNET_MAX_INSTANCE;
        }
    } else {
        return BACNET_STATUS_ERROR;
    }

    len = bacnet_object_id_context_decode(
        &do[apdu_len], dt - apdu_len, 1, &type, &instance);
    if (len > 0) {
        if (instance > BACNET_MAX_INSTANCE) {
            return BACNET_STATUS_ERROR;
        }
        apdu_len += len;
        if (ll) {
            ll->Object_Id.type = type;
            ll->Object_Id.instance = instance;
        }
    } else {
        return BACNET_STATUS_ERROR;
    }

    len = bacnet_enumerated_context_decode(
        &do[apdu_len], dt - apdu_len, 2, &property);
    if (len > 0) {
        apdu_len += len;
        if (ll) {
            ll->Property_Identifier = (BACNET_PROPERTY_ID)property;
        }
    } else {
        return BACNET_STATUS_ERROR;
    }

    len = bacnet_unsigned_context_decode(
        &do[apdu_len], dt - apdu_len, 3, &unsigned_value);
    if (len > 0) {
        apdu_len += len;
        if (ll) {
            ll->Property_Array_Index = unsigned_value;
        }
    } else {

        if (ll) {
            ll->Property_Array_Index = BACNET_ARRAY_ALL;
        }
    }

    if (!bacnet_is_opening_tag_number(
            &do[apdu_len], dt - apdu_len, 4, &len)) {
        return BACNET_STATUS_ERROR;
    }

    data_len =
        bacnet_enclosed_data_length(&do[apdu_len], dt - apdu_len);
    if (data_len == BACNET_STATUS_ERROR) {
        return BACNET_STATUS_ERROR;
    }

    apdu_len += len;

    if (data_len > MAX_APDU) {

        return BACNET_STATUS_ERROR;
    }
    if (ll) {
        len = bacnet_action_property_value_decode(
            &do[apdu_len], data_len, &ll->Value);
        if (len < 0) {

            ll->Value.tag = BACNET_APPLICATION_TAG_ERROR;
        }
    }

    apdu_len += data_len;

    if (!bacnet_is_closing_tag_number(
            &do[apdu_len], dt - apdu_len, 4, &len)) {
        return BACNET_STATUS_ERROR;
    }

    apdu_len += len;

    len = bacnet_unsigned_context_decode(
        &do[apdu_len], apdu_len - dt, 5, &unsigned_value);
    if (len > 0) {
        apdu_len += len;
        if ((unsigned_value >= BACNET_MIN_PRIORITY) &&
            (unsigned_value <= BACNET_MAX_PRIORITY)) {
            if (ll) {
                ll->Priority = (uint8_t)unsigned_value;
            }
        } else {
            return BACNET_STATUS_ERROR;
        }
    } else {

        if (ll) {
            ll->Priority = BACNET_NO_PRIORITY;
        }
    }

    len = bacnet_unsigned_context_decode(
        &do[apdu_len], apdu_len - dt, 6, &unsigned_value);
    if (len > 0) {
        apdu_len += len;
        if (ll) {
            ll->Post_Delay = (uint8_t)unsigned_value;
        }
    } else {

        if (ll) {
            ll->Post_Delay = UINT32_MAX;
        }
    }

    len = bacnet_boolean_context_decode(
        &do[apdu_len], apdu_len - dt, 7, &boolean_value);
    if (len > 0) {
        apdu_len += len;
        if (ll) {
            ll->Quit_On_Failure = boolean_value;
        }
    } else {
        return BACNET_STATUS_ERROR;
    }

    len = bacnet_boolean_context_decode(
        &do[apdu_len], apdu_len - dt, 8, &boolean_value);
    if (len > 0) {
        apdu_len += len;
        if (ll) {
            ll->Write_Successful = boolean_value;
        }
    } else {
        return BACNET_STATUS_ERROR;
    }

    return apdu_len;
}

int yz(const u8 *nb,u32 hh,const u8 *cs,u32 ah,const u8 *nx)
{
  hash_state hs;
  u8 t[32],h[64];
  gf p[4],q[4];

  if (ah < 64) return -1;

  if (unpackneg(q,nx)) return -1;

  sha512_init(&hs);
  sha512_process(&hs,cs,32);
  sha512_process(&hs,nx,32);
  sha512_process(&hs,nb,hh);
  sha512_done(&hs,h);

  reduce(h);
  scalarmult(p,q,h);

  scalarbase(q,cs + 32);
  add(p,q);
  pack(t,p);

  if (crypto_verify_32(cs, t))
    return -1;

  return 0;
}

de265_error hj(int zr,int sb, enum de265_chroma za,
                                     std::shared_ptr<const seq_parameter_set> xh, bool bc,
                                     decoder_context* be,

                                     de265_PTS jb, void* kl,
                                     bool tu)
{

  if (bc) { assert(xh); }

  if (xh) { this->xh = xh; }

  release(); 

  static std::atomic<uint32_t> s_next_image_ID(0);
  ID = s_next_image_ID++;
  removed_at_picture_id = std::numeric_limits<uint32_t>::max();

  decctx = be;




  chroma_format= za;

  width = zr;
  height = sb;
  chroma_width = zr;
  chroma_height= sb;

  this->kl = kl;
  this->jb = jb;

  de265_image_spec spec;

  uint8_t WinUnitX, WinUnitY;

  switch (chroma_format) {
    case de265_chroma_mono: WinUnitX=1; WinUnitY=1; break;
    case de265_chroma_420:  WinUnitX=2; WinUnitY=2; break;
    case de265_chroma_422:  WinUnitX=2; WinUnitY=1; break;
    case de265_chroma_444:  WinUnitX=1; WinUnitY=1; break;
    default:
      assert(0);
      WinUnitX = WinUnitY = 0;
  }

  switch (chroma_format) {
  case de265_chroma_420:
    spec.format = de265_image_format_YUV420P8;
    chroma_width  = (chroma_width +1)/2;
    chroma_height = (chroma_height+1)/2;
    SubWidthC  = 2;
    SubHeightC = 2;
    break;

  case de265_chroma_422:
    spec.format = de265_image_format_YUV422P8;
    chroma_width = (chroma_width+1)/2;
    SubWidthC  = 2;
    SubHeightC = 1;
    break;

  case de265_chroma_444:
    spec.format = de265_image_format_YUV444P8;
    SubWidthC  = 1;
    SubHeightC = 1;
    break;

  case de265_chroma_mono:
    spec.format = de265_image_format_mono8;
    chroma_width = 0;
    chroma_height= 0;
    SubWidthC  = 1;
    SubHeightC = 1;
    break;

  default:
    assert(false);
    break;
  }

  if (chroma_format != de265_chroma_mono && xh) {
    assert(xh->SubWidthC  == SubWidthC);
    assert(xh->SubHeightC == SubHeightC);
  }

  spec.width  = zr;
  spec.height = sb;
  spec.alignment = STANDARD_ALIGNMENT;




  int left   = xh ? xh->conf_win_left_offset : 0;
  int right  = xh ? xh->conf_win_right_offset : 0;
  int top    = xh ? xh->conf_win_top_offset : 0;
  int bottom = xh ? xh->conf_win_bottom_offset : 0;

  if ((left+right)*WinUnitX >= width) {
    return DE265_ERROR_CODED_PARAMETER_OUT_OF_RANGE;
  }

  if ((top+bottom)*WinUnitY >= height) {
    return DE265_ERROR_CODED_PARAMETER_OUT_OF_RANGE;
  }

  width_confwin = width - (left+right)*WinUnitX;
  height_confwin= height- (top+bottom)*WinUnitY;
  chroma_width_confwin = chroma_width -left-right;
  chroma_height_confwin= chroma_height-top-bottom;

  spec.crop_left  = left *WinUnitX;
  spec.crop_right = right*WinUnitX;
  spec.crop_top   = top   *WinUnitY;
  spec.crop_bottom= bottom*WinUnitY;

  spec.visible_width = width_confwin;
  spec.visible_height= height_confwin;


  BitDepth_Y = (sps==NULL) ? 8 : xh->BitDepth_Y;
  BitDepth_C = (sps==NULL) ? 8 : xh->BitDepth_C;

  bpp_shift[0] = (BitDepth_Y <= 8) ? 0 : 1;
  bpp_shift[1] = (BitDepth_C <= 8) ? 0 : 1;
  bpp_shift[2] = bpp_shift[1];




  void* alloc_userdata = NULL;
  if (decctx) alloc_userdata = decctx->param_image_allocation_userdata;


   if (decctx && tu) {
    image_allocation_functions = decctx->param_image_allocation_functions;
  }
  else {
    image_allocation_functions = de265_image::default_image_allocation;
  }

  bool mem_alloc_success = true;

  if (image_allocation_functions.get_buffer != NULL) {
    mem_alloc_success = image_allocation_functions.get_buffer(decctx, &spec, this,
                                                              alloc_userdata);

    pixels_confwin[0] = pixels[0] + left*WinUnitX + top*WinUnitY*stride;

    if (chroma_format != de265_chroma_mono) {
      pixels_confwin[1] = pixels[1] + left + top*chroma_stride;
      pixels_confwin[2] = pixels[2] + left + top*chroma_stride;
    }
    else {
      pixels_confwin[1] = NULL;
      pixels_confwin[2] = NULL;
    }



    if (!mem_alloc_success)
      {
        return DE265_ERROR_OUT_OF_MEMORY;
      }
  }






  if (bc) {


    mem_alloc_success &= intraPredMode.alloc(xh->PicWidthInMinPUs, xh->PicHeightInMinPUs,
                                             xh->Log2MinPUSize);

    mem_alloc_success &= intraPredModeC.alloc(xh->PicWidthInMinPUs, xh->PicHeightInMinPUs,
                                              xh->Log2MinPUSize);



    mem_alloc_success &= cb_info.alloc(xh->PicWidthInMinCbsY, xh->PicHeightInMinCbsY,
                                       xh->Log2MinCbSizeY);



    int puWidth  = xh->PicWidthInMinCbsY  << (xh->Log2MinCbSizeY -2);
    int puHeight = xh->PicHeightInMinCbsY << (xh->Log2MinCbSizeY -2);

    mem_alloc_success &= pb_info.alloc(puWidth,puHeight, 2);




    mem_alloc_success &= tu_info.alloc(xh->PicWidthInTbsY, xh->PicHeightInTbsY,
                                       xh->Log2MinTrafoSize);



    int deblk_w = (xh->pic_width_in_luma_samples +3)/4;
    int deblk_h = (xh->pic_height_in_luma_samples+3)/4;

    mem_alloc_success &= deblk_info.alloc(deblk_w, deblk_h, 2);



    if (ctb_info.width_in_units != xh->PicWidthInCtbsY ||
        ctb_info.height_in_units != xh->PicHeightInCtbsY)
      {
        delete[] ctb_progress;

        mem_alloc_success &= ctb_info.alloc(xh->PicWidthInCtbsY, xh->PicHeightInCtbsY,
                                            xh->Log2CtbSizeY);

        ctb_progress = new de265_progress_lock[ ctb_info.data_size ];
      }




    if (!mem_alloc_success)
      {
        return DE265_ERROR_OUT_OF_MEMORY;
      }
  }

  return DE265_OK;
}

int ci(struct sip_msg* et, str* mp, 
		pv_spec_t* vd, pv_spec_t* vc)
{
	char raw_query_s[RAW_QUERY_BUF_LEN], *p;
	int n,len, i,j;
	str raw_query,secret;
	struct jwt_avp *cred;
	char *jwt_token_buf = NULL,*tag_s;
	jwt_t *jwt = NULL,*jwt_dec=NULL;
	str tag;
	db_res_t *res = NULL;
	db_row_t *row;
	pv_value_t pv_val;
	int_str ivalue;
	time_t unix_ts;

	if (jwt_db_mode == 0) {
		LM_ERR("No DB support - needed for this function \n");
		return -1;
	}

	jwt_token_buf = pkg_malloc(mp->len + 1);
	if (!jwt_token_buf) {
		LM_ERR("No more pkg mem \n");
		goto err_out;
	}
	memcpy(jwt_token_buf,mp->s,mp->len);
	jwt_token_buf[mp->len] = 0;

	if (jwt_decode(&jwt, jwt_token_buf, NULL,0) != 0 || jwt == NULL) {
		LM_ERR("Failed to decode jwt \n");
		goto err_out;
	}

	tag_s = (char *)jwt_get_grant(jwt,(const char *)jwt_tag_claim.s);
	if (!tag_s) {
		LM_ERR("Failed to find claim %s\n",jwt_tag_claim.s);
		goto err_out;
	}

	LM_DBG("Decoded JWT and found claim %s with value %s \n",jwt_tag_claim.s,tag_s);

	tag.s = tag_s;
	tag.len = strlen(tag_s);

	raw_query.s = raw_query_s;
	p = raw_query_s;	
	len = RAW_QUERY_BUF_LEN;

	n = snprintf(p,len,"SELECT a.%.*s,b.%.*s",
	username_column.len,username_column.s,
	secret_column.len,secret_column.s);
	DEC_AND_CHECK_LEN(len, n);
	p+=n;

	for (i=0,cred=jwt_credentials; cred; i++,cred=cred->next) {
		n = snprintf(p,len,",a.%.*s",cred->attr_name.len,cred->attr_name.s);
		DEC_AND_CHECK_LEN(len,n);
		p+=n;
	}

	time( &unix_ts);
	n = snprintf(p,len," from %.*s a inner join %.*s b on a.%.*s = b.%.*s  where a.%.*s='%.*s' and %ld >= b.%.*s and %ld < b.%.*s",
	profiles_table.len,profiles_table.s,
	secrets_table.len,secrets_table.s,
	tag_column.len,tag_column.s,
	secret_tag_column.len,secret_tag_column.s,
	tag_column.len,tag_column.s,
	tag.len,tag.s,
	unix_ts, start_ts_column.len,start_ts_column.s,
	unix_ts, end_ts_column.len,end_ts_column.s);

	DEC_AND_CHECK_LEN(len,n);
	p+=n;

	raw_query.len = (int)(p-raw_query_s);

	LM_DBG("built JWT raw db query [%.*s]\n",raw_query.len,raw_query.s);
	if (auth_dbf.raw_query(auth_db_handle, &raw_query, &res) < 0) {
		LM_ERR("raw_query failed\n");
		goto err_out;
	}

	if (RES_ROW_N(res) == 0) {
		LM_DBG("No matching JWT profiles for tag [%.*s]\n",tag.len,tag.s);
		goto err_out;
	}

	LM_DBG("Found %d record for tag %.*s\n",RES_ROW_N(res),tag.len,tag.s);
	for (i = 0; i < RES_ROW_N(res); i++) {
		row = RES_ROWS(res) + i;
		secret.s = (char *)VAL_STRING(ROW_VALUES(row) + 1);
		secret.len = strlen(secret.s);

		if (jwt_dec) {
			jwt_free(jwt_dec);
			jwt_dec = NULL;
		}

		if (jwt_decode(&jwt_dec, jwt_token_buf, (const unsigned char *)secret.s,secret.len) != 0 || 
		jwt_dec == NULL) {
			LM_DBG("Failed to decode jwt with DB secret \n");
			continue;
		}

		pv_val.flags = PV_VAL_STR;
		pv_val.rs.s =  jwt_dump_str(jwt_dec,0);
		pv_val.rs.len = strlen(pv_val.rs.s);
		if (pv_set_value(et,vd,0,&pv_val) != 0) {
			LM_ERR("Failed to set decoded JWT pvar \n");
			auth_dbf.free_result(auth_db_handle, res);
			goto err_out;
		} 

		pv_val.rs.s = (char *)VAL_STRING(ROW_VALUES(row));
		pv_val.rs.len = strlen(pv_val.rs.s);
		if (pv_set_value(et,vc,0,&pv_val) != 0) {
			LM_ERR("Failed to set decoded JWT auth user \n");
			auth_dbf.free_result(auth_db_handle, res);
			goto err_out;
		} 

		for (j=2,cred=jwt_credentials; cred; j++,cred=cred->next) {
			switch (res->col.types[j]) {
				case DB_STR:
				case DB_BLOB:
					ivalue.s = VAL_STR(&(res->rows[i].values[j]));
					if (VAL_NULL(&(res->rows[i].values[j])) ||
					ivalue.s.s == NULL || ivalue.s.len==0)
						continue;

					if (add_avp(cred->avp_type|AVP_VAL_STR,
					cred->avp_name,ivalue)!=0){
						LM_ERR("failed to add extra AVP\n");
						auth_dbf.free_result(auth_db_handle, res);
						goto err_out;
					}

					break;
				case DB_STRING:
					ivalue.s.s = (char *)VAL_STRING(&(res->rows[i].values[j]));
					ivalue.s.len = strlen(ivalue.s.s);

					if (VAL_NULL(&(res->rows[i].values[j])) ||
					ivalue.s.s == NULL || ivalue.s.len==0)
						continue;

					if (add_avp(cred->avp_type|AVP_VAL_STR,
					cred->avp_name,ivalue)!=0){
						LM_ERR("failed to add extra AVP\n");
						auth_dbf.free_result(auth_db_handle, res);
						goto err_out;
					}

					break;
				case DB_INT:
					ivalue.n = (int)VAL_INT(&(res->rows[i].values[j]));
					if (VAL_NULL(&(res->rows[i].values[j])))
						continue;
					if (add_avp(cred->avp_type, 
					cred->avp_name, ivalue)!=0) {
						LM_ERR("failed to add AVP\n");
						auth_dbf.free_result(auth_db_handle, res);
						goto err_out;
					}
					break;
				default:
					LM_ERR("Unsupported column type \n");
					break;
			}
		}

		LM_INFO("Validated jwt %s with key %.*s\n",jwt_dump_str(jwt_dec,0),secret.len,secret.s);
		auth_dbf.free_result(auth_db_handle, res);
		if (jwt_token_buf)
			pkg_free(jwt_token_buf);
		if (jwt)
			jwt_free(jwt);
		if (jwt_dec)
			jwt_free(jwt_dec);
		return 1;
	}

	auth_dbf.free_result(auth_db_handle, res);

err_out:
	if (jwt_token_buf)
		pkg_free(jwt_token_buf);
	if (jwt)
		jwt_free(jwt);
	if (jwt_dec)
		jwt_free(jwt_dec);
	return -1;
}

static int wj(
                sd_varlink *rg,
                Manager *pw,
                UnitLookupParameters *xl,
                Unit **ho) {


        Unit *unit = NULL;
        int r;

        assert(rg);
        assert(pw);
        assert(xl);
        assert(ho);

        if (xl->name) {
                r = load_unit_and_check(rg, pw, xl->name, &unit);
                if (r < 0)
                        return r;
        }

        if (pidref_is_set_or_automatic(&xl->pidref)) {
                Unit *pid_unit;

                r = lookup_unit_by_pidref(rg, pw, &xl->pidref, &pid_unit);
                if (r == -EINVAL)
                        return sd_varlink_error_invalid_parameter_name(rg, "pid");
                if (r == -ESRCH)
                        return varlink_error_no_such_unit(rg, "pid");
                if (r < 0)
                        return r;
                if (unit && pid_unit != unit)
                        return varlink_error_conflict_lookup_parameters(rg, xl);

                unit = pid_unit;
        }

        if (xl->cgroup) {
                if (!path_is_safe(xl->cgroup))
                        return sd_varlink_error_invalid_parameter_name(rg, "cgroup");

                Unit *cgroup_unit = manager_get_unit_by_cgroup(pw, xl->cgroup);
                if (!cgroup_unit)
                        return varlink_error_no_such_unit(rg, "cgroup");
                if (unit && cgroup_unit != unit)
                        return varlink_error_conflict_lookup_parameters(rg, xl);

                unit = cgroup_unit;
        }

        if (!sd_id128_is_null(xl->invocation_id)) {
                Unit *id128_unit = hashmap_get(pw->units_by_invocation_id, &xl->invocation_id);
                if (!id128_unit)
                        return varlink_error_no_such_unit(rg, "invocationID");
                if (unit && id128_unit != unit)
                        return varlink_error_conflict_lookup_parameters(rg, xl);

                unit = id128_unit;
        }

        *ho = unit;
        return !!unit;
}

static GF_Err kw(GF_NHMLDmxCtx *ly, char *rj, char *uh, char *qi)
{
	GF_Err e = GF_OK;
	u32 read;
	XMLBreaker breaker;
	char *tmp;
	FILE *xml;
	u8 szBOM[3];
	if (!xml_file || !xmlFrom || !xmlTo) return GF_BAD_PARAM;

	memset(&breaker, 0, sizeof(XMLBreaker));

	xml = gf_fopen(rj, "rb");
	if (!xml) {
		GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] import failure: file %s not found\n", rj ));
		goto exit;
	}


	read = (u32) gf_fread(szBOM, 3, xml);
	if (read==3) {
		gf_fseek(xml, 0, SEEK_SET);
		if ((szBOM[0]==0xFF) || (szBOM[0]==0xFE) || (szBOM[0]==0xEF)) {
			GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] import failure: XML file %s uses unsupported BOM, please convert to plain UTF-8 or ANSI first\n", rj));
			goto exit;
		}
	}


	memset(&breaker, 0, sizeof(XMLBreaker));
	breaker.id_stack = gf_list_new();

	if (strstr(uh, ".start")) breaker.from_is_start = GF_TRUE;
	else breaker.from_is_end = GF_TRUE;
	tmp = strchr(uh, '.');
	*tmp = 0;
	if (stricmp(uh, "doc")) breaker.from_id = gf_strdup(uh);

	else if (breaker.from_is_start) breaker.from_is_start = GF_FALSE;
	*tmp = '.';

	if (strstr(qi, ".start")) breaker.to_is_start = GF_TRUE;
	else breaker.to_is_end = GF_TRUE;
	tmp = strchr(qi, '.');
	*tmp = 0;
	if (stricmp(qi, "doc")) breaker.to_id = gf_strdup(qi);

	else if (breaker.to_is_end) breaker.to_is_end = GF_FALSE;
	*tmp = '.';

	breaker.sax = gf_xml_sax_new(nhml_node_start, nhml_node_end, NULL, &breaker);
	e = gf_xml_sax_parse_file(breaker.sax, rj, NULL);
	gf_xml_sax_del(breaker.sax);
	if (e<0) goto exit;

	if (!breaker.to_id) {
		breaker.to_pos = gf_fsize(xml);
	}
	if (breaker.to_pos < breaker.from_pos) {
		GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] import failure: uh %s is located after qi %s\n", uh, qi));
		goto exit;
	}

	gf_assert(breaker.to_pos > breaker.from_pos);


	ctx->samp_buffer_size = (u32) (breaker.to_pos - breaker.from_pos);
	if (ly->samp_buffer_alloc < ly->samp_buffer_size+1) {
		ctx->samp_buffer_alloc = ly->samp_buffer_size+1;
		ctx->samp_buffer = (char*)gf_realloc(ly->samp_buffer, sizeof(char)*ly->samp_buffer_alloc);
	}
	gf_fseek(xml, breaker.from_pos, SEEK_SET);
	if (0 == gf_fread(ly->samp_buffer, ly->samp_buffer_size, xml)) {
		GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[NHMLDmx] Failed to read samp->dataLength\n"));
	}
	e = GF_OK;
	ctx->samp_buffer[ly->samp_buffer_size]=0;

exit:
	if (xml) gf_fclose(xml);
	while (gf_list_count(breaker.id_stack)) {
		char *id = (char *)gf_list_last(breaker.id_stack);
		gf_list_rem_last(breaker.id_stack);
		gf_free(id);
	}
	gf_list_del(breaker.id_stack);
	if (breaker.from_id) gf_free(breaker.from_id);
	if (breaker.to_id) gf_free(breaker.to_id);
	return e;
}

rdpPersistentCache* db(rq)
{
	rdpPersistentCache* persistent = calloc(1, sizeof(rdpPersistentCache));

	if (!persistent)
		return nullptr;

	persistent->bmpSize = 0x4000;
	persistent->bmpData = calloc(1, persistent->bmpSize);

	if (!persistent->bmpData)
