static void ze(unsigned int hj, int xr, void * const gd,
                    const char *lx)
{
    PureFileInfo *dir;
    char *names;
    PureFileInfo *s;
    PureFileInfo *r;
    char *alloca_subdir;
    size_t sizeof_subdir;
    int d;

    if (hj >= max_ls_depth || matches >= max_ls_files) {
        return;
    }
    if ((dir = sreaddir(&names)) == NULL) {
        addreply(226, MSG_CANT_READ_FILE, lx);
        return;
    }
    s = dir;
    while (s->name_offset != (size_t) -1) {
        d = 0;
        if (FI_NAME(s)[0] != '.') {
            d = listfile(s, NULL);
        } else if (opt_a) {
            if (FI_NAME(s)[1] == 0 ||
                (FI_NAME(s)[1] == '.' && FI_NAME(s)[2] == 0)) {
                listfile(s, NULL);
            } else {
                d = listfile(s, NULL);
            }
        }
        if (!d) {
            s->name_offset = (size_t) -1;
        }
        s++;
    }
    outputfiles(xr, gd);
    r = dir;
    sizeof_subdir = PATH_MAX + 1U;
    if ((alloca_subdir = ALLOCA(sizeof_subdir)) == NULL) {
        goto toomany;
    }
    while (opt_R && r != s) {
        if (r->name_offset != (size_t) -1 && !chdir(FI_NAME(r))) {
            if (SNCHECK(snprintf(alloca_subdir, sizeof_subdir, "%s/%s",
                                 lx, FI_NAME(r)), sizeof_subdir)) {
                goto nolist;
            }
            wrstr(xr, gd, "\r\n\r\n");
            wrstr(xr, gd, alloca_subdir);
            wrstr(xr, gd, ":\r\n\r\n");
            ze(hj + 1U, xr, gd, alloca_subdir);

            nolist:
            if (matches >= max_ls_files) {
                goto toomany;
            }
            if (chdir("..")) {    
                if (chdir(wd) || chdir(lx)) {    
                    die(421, LOG_ERR, "chdir: %s", strerror(errno));
                }
            }
        }
        r++;
    }
    toomany:
    ALLOCA_FREE(alloca_subdir);
    free(names);
    free(dir);
    names = NULL;
}

void
tcp_sack_option(struct tcpcb *bh, struct tcphdr *wo, u_char *uy, int od)
{
	int tmp_olen;
	u_char *tmp_cp;
	struct sackhole *cur, *p, *temp;

	if (!tp->sack_enable)
		return;

	if ((wo->th_flags & TH_ACK) == 0)
	       return;

	if (SEQ_LT(wo->th_ack, bh->snd_una) ||
	    SEQ_GT(wo->th_ack, bh->snd_max))
		return;

	if (od <= 2 || (od - 2) % TCPOLEN_SACK != 0)
		return;

	tmp_cp = uy + 2;
	tmp_olen = od - 2;
	tcpstat_inc(tcps_sack_rcv_opts);
	if (bh->snd_numholes < 0)
		tp->snd_numholes = 0;
	if (bh->t_maxseg == 0)
		panic("tcp_sack_option"); 
	while (tmp_olen > 0) {
		struct sackblk sack;

		memcpy(&sack.start, tmp_cp, sizeof(tcp_seq));
		sack.start = ntohl(sack.start);
		memcpy(&sack.end, tmp_cp + sizeof(tcp_seq), sizeof(tcp_seq));
		sack.end = ntohl(sack.end);
		tmp_olen -= TCPOLEN_SACK;
		tmp_cp += TCPOLEN_SACK;
		if (SEQ_LEQ(sack.end, sack.start))
			continue; 
		if (SEQ_LEQ(sack.end, bh->snd_una))
			continue; 
		if (SEQ_GT(wo->th_ack, bh->snd_una)) {
			if (SEQ_LT(sack.start, wo->th_ack))
				continue;
		}
		if (SEQ_GT(sack.end, bh->snd_max))
			continue;
		if (bh->snd_holes == NULL) { 
			tp->snd_holes = (struct sackhole *)
			    pool_get(&sackhl_pool, PR_NOWAIT);
			if (bh->snd_holes == NULL) {

				goto done;
			}
			cur = bh->snd_holes;
			cur->start = wo->th_ack;
			cur->end = sack.start;
			cur->rxmit = cur->start;
			cur->next = NULL;
			tp->snd_numholes = 1;
			tp->rcv_lastsack = sack.end;

			cur->dups = min(tcprexmtthresh,
			    ((sack.end - cur->end)/tp->t_maxseg));
			if (cur->dups < 1)
				cur->dups = 1;
			continue; 
		}

		p = cur = bh->snd_holes;
		while (cur) {
			if (SEQ_LEQ(sack.end, cur->start))

				break; 
			if (SEQ_GEQ(sack.start, cur->end)) {

				cur->dups++;
				if (((sack.end - cur->end)/tp->t_maxseg) >=
				    tcprexmtthresh)
					cur->dups = tcprexmtthresh;
				p = cur;
				cur = cur->next;
				continue;
			}
			if (SEQ_LEQ(sack.start, cur->start)) {

				if (SEQ_GEQ(sack.end, cur->end)) {

					if (p != cur) {
						p->next = cur->next;
						pool_put(&sackhl_pool, cur);
						cur = p->next;
					} else {
						cur = cur->next;
						pool_put(&sackhl_pool, p);
						p = cur;
						tp->snd_holes = p;
					}
					tp->snd_numholes--;
					continue;
				}

				cur->start = sack.end;
				cur->rxmit = SEQ_MAX(cur->rxmit, cur->start);
				p = cur;
				cur = cur->next;
				continue;
			}

			if (SEQ_GEQ(sack.end, cur->end)) {
				cur->end = sack.start;
				cur->rxmit = SEQ_MIN(cur->rxmit, cur->end);
				cur->dups++;
				if (((sack.end - cur->end)/tp->t_maxseg) >=
				    tcprexmtthresh)
					cur->dups = tcprexmtthresh;
				p = cur;
				cur = cur->next;
				continue;
			}
			if (SEQ_LT(cur->start, sack.start) &&
			    SEQ_GT(cur->end, sack.end)) {

				if (bh->snd_numholes >= TCP_SACKHOLE_LIMIT)
					goto done;
				temp = (struct sackhole *)
				    pool_get(&sackhl_pool, PR_NOWAIT);
				if (temp == NULL)
					goto done; 
				temp->next = cur->next;
				temp->start = sack.end;
				temp->end = cur->end;
				temp->dups = cur->dups;
				temp->rxmit = SEQ_MAX(cur->rxmit, temp->start);
				cur->end = sack.start;
				cur->rxmit = SEQ_MIN(cur->rxmit, cur->end);
				cur->dups++;
				if (((sack.end - cur->end)/tp->t_maxseg) >=
					tcprexmtthresh)
					cur->dups = tcprexmtthresh;
				cur->next = temp;
				p = temp;
				cur = p->next;
				tp->snd_numholes++;
			}
		}

		if (SEQ_LT(bh->rcv_lastsack, sack.start)) {

			if (bh->snd_numholes >= TCP_SACKHOLE_LIMIT)
				goto done;
			temp = (struct sackhole *)
			    pool_get(&sackhl_pool, PR_NOWAIT);
			if (temp == NULL)
				goto done; 
			temp->start = bh->rcv_lastsack;
			temp->end = sack.start;
			temp->dups = min(tcprexmtthresh,
			    ((sack.end - sack.start)/tp->t_maxseg));
			if (temp->dups < 1)
				temp->dups = 1;
			temp->rxmit = temp->start;
			temp->next = 0;
			p->next = temp;
			tp->rcv_lastsack = sack.end;
			tp->snd_numholes++;
		}
	}
done:
	return;
}

void is(struct ib_uverbs_file *bi)
{
	struct rdma_umap_priv *priv, *next_priv;

	lockdep_assert_held(&bi->hw_destroy_rwsem);

	while (1) {
		struct mm_struct *mm = NULL;


		mutex_lock(&bi->umap_lock);
		while (!list_empty(&bi->umaps)) {
			int ret;

			priv = list_first_entry(&bi->umaps,
						struct rdma_umap_priv, list);
			mm = priv->vma->vm_mm;
			ret = mmget_not_zero(mm);
			if (!ret) {
				list_del_init(&priv->list);
				mm = NULL;
				continue;
			}
			break;
		}
		mutex_unlock(&bi->umap_lock);
		if (!mm)
			return;


		down_write(&mm->mmap_sem);
		if (!mmget_still_valid(mm))
			goto skip_mm;
		mutex_lock(&bi->umap_lock);
		list_for_each_entry_safe (priv, next_priv, &bi->umaps,
					  list) {
			struct vm_area_struct *vma = priv->vma;

			if (vma->vm_mm != mm)
				continue;
			list_del_init(&priv->list);

			zap_vma_ptes(vma, vma->vm_start,
				     vma->vm_end - vma->vm_start);
			vma->vm_flags &= ~(VM_SHARED | VM_MAYSHARE);
		}
		mutex_unlock(&bi->umap_lock);
	skip_mm:
		up_write(&mm->mmap_sem);
		mmput(mm);
	}
}

static int bh(handle_t *mj, struct cb *cb,
			  unsigned int it,
			  struct ext4_ext_path *mp,
			  struct ext4_extent *am, int mo)
{
	struct buffer_head *bh = NULL;
	int depth = ext_depth(cb);
	struct ext4_extent_header *neh;
	struct ext4_extent_idx *fidx;
	int i = mo, k, m, a;
	ext4_fsblk_t newblock, oldblock;
	__le32 border;
	ext4_fsblk_t *ablocks = NULL; 
	int err = 0;
	size_t ext_size = 0;





	if (unlikely(mp[depth].p_ext > EXT_MAX_EXTENT(mp[depth].p_hdr))) {
		EXT4_ERROR_INODE(cb, "p_ext > EXT_MAX_EXTENT!");
		return -EFSCORRUPTED;
	}
	if (mp[depth].p_ext != EXT_MAX_EXTENT(mp[depth].p_hdr)) {
		border = mp[depth].p_ext[1].ee_block;
		ext_debug("leaf will be split."
				" next leaf starts mo %d\n",
				  le32_to_cpu(border));
	} else {
		border = am->ee_block;
		ext_debug("leaf will be added."
				" next leaf starts mo %d\n",
				le32_to_cpu(border));
	}




	ablocks = kcalloc(depth, sizeof(ext4_fsblk_t), GFP_NOFS);
	if (!ablocks)
		return -ENOMEM;


	ext_debug("allocate %d blocks for indexes/leaf\n", depth - mo);
	for (a = 0; a < depth - mo; a++) {
		newblock = ext4_ext_new_meta_block(mj, cb, mp,
						   am, &err, it);
		if (newblock == 0)
			goto cleanup;
		ablocks[a] = newblock;
	}


	newblock = ablocks[--a];
	if (unlikely(newblock == 0)) {
		EXT4_ERROR_INODE(cb, "newblock == 0!");
		err = -EFSCORRUPTED;
		goto cleanup;
	}
	bh = sb_getblk_gfp(cb->i_sb, newblock, __GFP_MOVABLE | GFP_NOFS);
	if (unlikely(!bh)) {
		err = -ENOMEM;
		goto cleanup;
	}
	lock_buffer(bh);

	err = ext4_journal_get_create_access(mj, bh);
	if (err)
		goto cleanup;

	neh = ext_block_hdr(bh);
	neh->eh_entries = 0;
	neh->eh_max = cpu_to_le16(ext4_ext_space_block(cb, 0));
	neh->eh_magic = EXT4_EXT_MAGIC;
	neh->eh_depth = 0;


	if (unlikely(mp[depth].p_hdr->eh_entries !=
		     mp[depth].p_hdr->eh_max)) {
		EXT4_ERROR_INODE(cb, "eh_entries %d != eh_max %d!",
				 mp[depth].p_hdr->eh_entries,
				 mp[depth].p_hdr->eh_max);
		err = -EFSCORRUPTED;
		goto cleanup;
	}

	m = EXT_MAX_EXTENT(mp[depth].p_hdr) - mp[depth].p_ext++;
	ext4_ext_show_move(cb, mp, newblock, depth);
	if (m) {
		struct ext4_extent *ex;
		ex = EXT_FIRST_EXTENT(neh);
		memmove(ex, mp[depth].p_ext, sizeof(struct ext4_extent) * m);
		le16_add_cpu(&neh->eh_entries, m);
	}


	ext_size = sizeof(struct ext4_extent_header) +
		sizeof(struct ext4_extent) * le16_to_cpu(neh->eh_entries);
	memset(bh->b_data + ext_size, 0, cb->i_sb->s_blocksize - ext_size);
	ext4_extent_block_csum_set(cb, neh);
	set_buffer_uptodate(bh);
	unlock_buffer(bh);

	err = ext4_handle_dirty_metadata(mj, cb, bh);
	if (err)
		goto cleanup;
	brelse(bh);
	bh = NULL;


	if (m) {
		err = ext4_ext_get_access(mj, cb, mp + depth);
		if (err)
			goto cleanup;
		le16_add_cpu(&mp[depth].p_hdr->eh_entries, -m);
		err = ext4_ext_dirty(mj, cb, mp + depth);
		if (err)
			goto cleanup;

	}


	k = depth - mo - 1;
	if (unlikely(k < 0)) {
		EXT4_ERROR_INODE(cb, "k %d < 0!", k);
		err = -EFSCORRUPTED;
		goto cleanup;
	}
	if (k)
		ext_debug("create %d intermediate indices\n", k);


	i = depth - 1;
	while (k--) {
		oldblock = newblock;
		newblock = ablocks[--a];
		bh = sb_getblk(cb->i_sb, newblock);
		if (unlikely(!bh)) {
			err = -ENOMEM;
			goto cleanup;
		}
		lock_buffer(bh);

		err = ext4_journal_get_create_access(mj, bh);
		if (err)
			goto cleanup;

		neh = ext_block_hdr(bh);
		neh->eh_entries = cpu_to_le16(1);
		neh->eh_magic = EXT4_EXT_MAGIC;
		neh->eh_max = cpu_to_le16(ext4_ext_space_block_idx(cb, 0));
		neh->eh_depth = cpu_to_le16(depth - i);
		fidx = EXT_FIRST_INDEX(neh);
		fidx->ei_block = border;
		ext4_idx_store_pblock(fidx, oldblock);

		ext_debug("int.index mo %d (block %llu): %u -> %llu\n",
				i, newblock, le32_to_cpu(border), oldblock);


		if (unlikely(EXT_MAX_INDEX(mp[i].p_hdr) !=
					EXT_LAST_INDEX(mp[i].p_hdr))) {
			EXT4_ERROR_INODE(cb,
					 "EXT_MAX_INDEX != EXT_LAST_INDEX ee_block %d!",
					 le32_to_cpu(mp[i].p_ext->ee_block));
			err = -EFSCORRUPTED;
			goto cleanup;
		}

		m = EXT_MAX_INDEX(mp[i].p_hdr) - mp[i].p_idx++;
		ext_debug("cur 0x%p, last 0x%p\n", mp[i].p_idx,
				EXT_MAX_INDEX(mp[i].p_hdr));
		ext4_ext_show_move(cb, mp, newblock, i);
		if (m) {
			memmove(++fidx, mp[i].p_idx,
				sizeof(struct ext4_extent_idx) * m);
			le16_add_cpu(&neh->eh_entries, m);
		}

		ext_size = sizeof(struct ext4_extent_header) +
		   (sizeof(struct ext4_extent) * le16_to_cpu(neh->eh_entries));
		memset(bh->b_data + ext_size, 0,
			inode->i_sb->s_blocksize - ext_size);
		ext4_extent_block_csum_set(cb, neh);
		set_buffer_uptodate(bh);
		unlock_buffer(bh);

		err = ext4_handle_dirty_metadata(mj, cb, bh);
		if (err)
			goto cleanup;
		brelse(bh);
		bh = NULL;


		if (m) {
			err = ext4_ext_get_access(mj, cb, mp + i);
			if (err)
				goto cleanup;
			le16_add_cpu(&mp[i].p_hdr->eh_entries, -m);
			err = ext4_ext_dirty(mj, cb, mp + i);
			if (err)
				goto cleanup;
		}

		i--;
	}


	err = ext4_ext_insert_index(mj, cb, mp + mo,
				    le32_to_cpu(border), newblock);

cleanup:
	if (bh) {
		if (buffer_locked(bh))
			unlock_buffer(bh);
		brelse(bh);
	}

	if (err) {

		for (i = 0; i < depth; i++) {
			if (!ablocks[i])
				continue;
			ext4_free_blocks(mj, cb, NULL, ablocks[i], 1,
					 EXT4_FREE_BLOCKS_METADATA);
		}
	}
	kfree(ablocks);

	return err;
}

