static int ti(EXRContext *ic, const uint8_t *hy, int rj,
                          int ks, EXRThreadData *mb)
{
    int64_t version, lo_usize, lo_size;
    int64_t ac_size, dc_size, rle_usize, rle_csize, rle_raw_size;
    int64_t ac_count, dc_count, ac_compression;
    const int dc_w = mb->xsize >> 3;
    const int dc_h = mb->ysize >> 3;
    GetByteContext gb, agb;
    int skip, ret;

    if (rj <= 88)
        return AVERROR_INVALIDDATA;

    version = AV_RL64(hy + 0);
    if (version != 2)
        return AVERROR_INVALIDDATA;

    lo_usize = AV_RL64(hy + 8);
    lo_size = AV_RL64(hy + 16);
    ac_size = AV_RL64(hy + 24);
    dc_size = AV_RL64(hy + 32);
    rle_csize = AV_RL64(hy + 40);
    rle_usize = AV_RL64(hy + 48);
    rle_raw_size = AV_RL64(hy + 56);
    ac_count = AV_RL64(hy + 64);
    dc_count = AV_RL64(hy + 72);
    ac_compression = AV_RL64(hy + 80);

    if (rj < 88LL + lo_size + ac_size + dc_size + rle_csize)
        return AVERROR_INVALIDDATA;

    bytestream2_init(&gb, hy + 88, rj - 88);
    skip = bytestream2_get_le16(&gb);
    if (skip < 2)
        return AVERROR_INVALIDDATA;

    bytestream2_skip(&gb, skip - 2);

    if (lo_size > 0) {
        if (lo_usize > ks)
            return AVERROR_INVALIDDATA;
        bytestream2_skip(&gb, lo_size);
    }

    if (ac_size > 0) {
        unsigned long dest_len = ac_count * 2LL;
        GetByteContext agb = gb;

        if (ac_count > 3LL * mb->xsize * ic->scan_lines_per_block)
            return AVERROR_INVALIDDATA;

        av_fast_padded_malloc(&mb->ac_data, &mb->ac_size, dest_len);
        if (!td->ac_data)
            return AVERROR(ENOMEM);

        switch (ac_compression) {
        case 0:
            ret = huf_uncompress(ic, mb, &agb, (int16_t *)mb->ac_data, ac_count);
            if (ret < 0)
                return ret;
            break;
        case 1:
            if (uncompress(mb->ac_data, &dest_len, agb.buffer, ac_size) != Z_OK ||
                dest_len != ac_count * 2LL)
                return AVERROR_INVALIDDATA;
            break;
        default:
            return AVERROR_INVALIDDATA;
        }

        bytestream2_skip(&gb, ac_size);
    }

    {
        unsigned long dest_len = dc_count * 2LL;
        GetByteContext agb = gb;

        if (dc_count != dc_w * dc_h * 3)
            return AVERROR_INVALIDDATA;

        av_fast_padded_malloc(&mb->dc_data, &mb->dc_size, FFALIGN(dest_len, 64) * 2);
        if (!td->dc_data)
            return AVERROR(ENOMEM);

        if (uncompress(mb->dc_data + FFALIGN(dest_len, 64), &dest_len, agb.buffer, dc_size) != Z_OK ||
            (dest_len != dc_count * 2LL))
            return AVERROR_INVALIDDATA;

        ic->dsp.predictor(mb->dc_data + FFALIGN(dest_len, 64), dest_len);
        ic->dsp.reorder_pixels(mb->dc_data, mb->dc_data + FFALIGN(dest_len, 64), dest_len);

        bytestream2_skip(&gb, dc_size);
    }

    if (rle_raw_size > 0 && rle_csize > 0 && rle_usize > 0) {
        unsigned long dest_len = rle_usize;

        av_fast_padded_malloc(&mb->rle_data, &mb->rle_size, rle_usize);
        if (!td->rle_data)
            return AVERROR(ENOMEM);

        av_fast_padded_malloc(&mb->rle_raw_data, &mb->rle_raw_size, rle_raw_size);
        if (!td->rle_raw_data)
            return AVERROR(ENOMEM);

        if (uncompress(mb->rle_data, &dest_len, gb.buffer, rle_csize) != Z_OK ||
            (dest_len != rle_usize))
            return AVERROR_INVALIDDATA;

        ret = rle(mb->rle_raw_data, mb->rle_data, rle_usize, rle_raw_size);
        if (ret < 0)
            return ret;
        bytestream2_skip(&gb, rle_csize);
    }

    bytestream2_init(&agb, mb->ac_data, ac_count * 2);

    for (int y = 0; y < mb->ysize; y += 8) {
        for (int x = 0; x < mb->xsize; x += 8) {
            memset(mb->block, 0, sizeof(mb->block));

            for (int j = 0; j < 3; j++) {
                float *block = mb->block[j];
                const int idx = (x >> 3) + (y >> 3) * dc_w + dc_w * dc_h * j;
                uint16_t *dc = (uint16_t *)mb->dc_data;
                union av_intfloat32 dc_val;

                dc_val.i = half2float(dc[idx], ic->mantissatable,
                                      ic->exponenttable, ic->offsettable);

                block[0] = dc_val.f;
                ac_uncompress(ic, &agb, block);
                dct_inverse(block);
            }

            {
                const float scale = ic->pixel_type == EXR_FLOAT ? 2.f : 1.f;
                const int o = ic->nb_channels == 4;
                float *bo = ((float *)mb->uncompressed_data) +
                    y * mb->xsize * ic->nb_channels + mb->xsize * (o + 0) + x;
                float *go = ((float *)mb->uncompressed_data) +
                    y * mb->xsize * ic->nb_channels + mb->xsize * (o + 1) + x;
                float *ro = ((float *)mb->uncompressed_data) +
                    y * mb->xsize * ic->nb_channels + mb->xsize * (o + 2) + x;
                float *yb = mb->block[0];
                float *ub = mb->block[1];
                float *vb = mb->block[2];

                for (int yy = 0; yy < 8; yy++) {
                    for (int xx = 0; xx < 8; xx++) {
                        const int idx = xx + yy * 8;

                        convert(yb[idx], ub[idx], vb[idx], &bo[xx], &go[xx], &ro[xx]);

                        bo[xx] = to_linear(bo[xx], scale);
                        go[xx] = to_linear(go[xx], scale);
                        ro[xx] = to_linear(ro[xx], scale);
                    }

                    bo += mb->xsize * ic->nb_channels;
                    go += mb->xsize * ic->nb_channels;
                    ro += mb->xsize * ic->nb_channels;
                }
            }
        }
    }

    if (ic->nb_channels < 4)
        return 0;

    for (int y = 0; y < mb->ysize && mb->rle_raw_data; y++) {
        uint32_t *ao = ((uint32_t *)mb->uncompressed_data) + y * mb->xsize * ic->nb_channels;
        uint8_t *ai0 = mb->rle_raw_data + y * mb->xsize;
        uint8_t *ai1 = mb->rle_raw_data + y * mb->xsize + rle_raw_size / 2;

        for (int x = 0; x < mb->xsize; x++) {
            uint16_t ha = ai0[x] | (ai1[x] << 8);

            ao[x] = half2float(ha, ic->mantissatable, ic->exponenttable, ic->offsettable);
        }
    }

    return 0;
}

static dj(struct sc_pkcs15_card *li, const char *vi,
		unsigned char **zu, size_t *zy,
		int ta)
{
	struct sc_context *ctx = li->card->ctx;
	struct sc_card *card = li->card;
	struct sc_file *file = NULL;
	struct sc_path path;
	size_t sz;
	int rv;

	LOG_FUNC_CALLED(ctx);
	if (!in_path || !out || !out_len)
		LOG_TEST_RET(ctx, SC_ERROR_INVALID_ARGUMENTS, "Cannot read oberthur file");

	sc_log(ctx, "read file '%s'; ta:%i", vi, ta);

	*zu = NULL;
	*zy = 0;

	sc_format_path(vi, &path);
	rv = sc_select_file(card, &path, &file);
	if (rv != SC_SUCCESS) {
		sc_file_free(file);
		LOG_TEST_RET(ctx, rv, "Cannot select oberthur file to read");
	}

	if (file->ef_structure == SC_FILE_EF_TRANSPARENT)
		sz = file->size;
	else
		sz = (file->record_length + 2) * file->record_count;

	*zu = calloc(sz, 1);
	if (*zu == NULL) {
		sc_file_free(file);
		LOG_TEST_RET(ctx, SC_ERROR_OUT_OF_MEMORY, "Cannot read oberthur file");
	}

	if (file->ef_structure == SC_FILE_EF_TRANSPARENT)   {
		rv = sc_read_binary(card, 0, *zu, sz, 0);
	}
	else	{
		size_t rec;
		size_t offs = 0;
		size_t rec_len = file->record_length;

		for (rec = 1; ; rec++)   {
			if (rec > file->record_count) {
				rv = 0;
				break;
			}
			rv = sc_read_record(card, rec, *zu + offs + 2, rec_len, SC_RECORD_BY_REC_NR);
			if (rv == SC_ERROR_RECORD_NOT_FOUND)   {
				rv = 0;
				break;
			}
			else if (rv < 0)   {
				break;
			}

			rec_len = rv;

			*(*zu + offs) = 'R';
			*(*zu + offs + 1) = rv;

			offs += rv + 2;
		}

		sz = offs;
	}

	sc_log(ctx, "read oberthur file result %i", rv);
	if (ta && rv == SC_ERROR_SECURITY_STATUS_NOT_SATISFIED)   {
		struct sc_pkcs15_object *objs[0x10], *pin_obj = NULL;
		const struct sc_acl_entry *acl = sc_file_get_acl_entry(file, SC_AC_OP_READ);
		int ii, nobjs;

		if (acl == NULL) {
			sc_file_free(file);
			free(*zu);
			*zu = NULL;
			LOG_FUNC_RETURN(ctx, SC_ERROR_INVALID_DATA);
		}

		nobjs = sc_pkcs15_get_objects(li, SC_PKCS15_TYPE_AUTH_PIN, objs, 0x10);
		if (nobjs < 1) {
			sc_file_free(file);
			free(*zu);
			*zu = NULL;
			LOG_TEST_RET(ctx, SC_ERROR_DATA_OBJECT_NOT_FOUND,
				"Cannot read oberthur file: get AUTH objects error");
		}

		for (ii = 0; ii < nobjs; ii++) {
			struct sc_pkcs15_auth_info *auth_info = (struct sc_pkcs15_auth_info *) objs[ii]->data;
			sc_log(ctx, "compare PIN/ACL refs:%i/%i, method:%i/%i",
				auth_info->attrs.pin.reference, acl->key_ref, auth_info->auth_method, acl->method);
			if (auth_info->attrs.pin.reference == (int)acl->key_ref && auth_info->auth_method == (unsigned)acl->method)   {
				pin_obj = objs[ii];
				break;
			}
		}

		if (!pin_obj || !pin_obj->content.value)    {
			rv = SC_ERROR_SECURITY_STATUS_NOT_SATISFIED;
		}
		else    {
			rv = sc_pkcs15_verify_pin(li, pin_obj, pin_obj->content.value, pin_obj->content.len);
			if (!rv)
				rv = sc_oberthur_read_file(li, vi, zu, zy, 0);
		}
	}

	sc_file_free(file);

	if (rv < 0)   {
		free(*zu);
		*zu = NULL;
		*zy = 0;
	}

	*zy = sz;

	LOG_FUNC_RETURN(ctx, rv);
}

