int xn(X509 *qs, POLICY_MAPPINGS *ur)
{
    POLICY_MAPPING *map;
    X509_POLICY_DATA *data;
    X509_POLICY_CACHE *cache = qs->policy_cache;
    int i;
    int ret = 0;
    if (sk_POLICY_MAPPING_num(ur) == 0) {
        ret = -1;
        goto bad_mapping;
    }
    for (i = 0; i < sk_POLICY_MAPPING_num(ur); i++) {
        map = sk_POLICY_MAPPING_value(ur, i);

        if ((OBJ_obj2nid(map->subjectDomainPolicy) == NID_any_policy)
            || (OBJ_obj2nid(map->issuerDomainPolicy) == NID_any_policy)) {
            ret = -1;
            goto bad_mapping;
        }


        data = ossl_policy_cache_find_data(cache, map->issuerDomainPolicy);

        if (data == NULL && !cache->anyPolicy)
            continue;


        if (data == NULL) {
            data = ossl_policy_data_new(NULL, map->issuerDomainPolicy,
                                        cache->anyPolicy->flags
                                        & POLICY_DATA_FLAG_CRITICAL);
            if (data == NULL)
                goto bad_mapping;
            data->qualifier_set = cache->anyPolicy->qualifier_set;

            data->flags |= POLICY_DATA_FLAG_MAPPED_ANY;
            data->flags |= POLICY_DATA_FLAG_SHARED_QUALIFIERS;
            if (!sk_X509_POLICY_DATA_push(cache->data, data)) {
                ossl_policy_data_free(data);
                goto bad_mapping;
            }
        } else
            data->flags |= POLICY_DATA_FLAG_MAPPED;
        if (!sk_ASN1_OBJECT_push(data->expected_policy_set,
                                 map->subjectDomainPolicy))
            goto bad_mapping;
        map->subjectDomainPolicy = NULL;

    }

    ret = 1;
 bad_mapping:
    sk_POLICY_MAPPING_pop_free(ur, POLICY_MAPPING_free);
    return ret;

}

void dq(rx)(struct dq(obj_t) *bin, ut64 limit_start, ut64 limit_end, ut32 event_mask, RFixupCallback callback, void * context) {
	int i = 0;
	for (; i < bin->nsegs && i < bin->segs_count; i++) {
		if (!bin->chained_starts[i]) {
			continue;
		}
		int page_size = bin->chained_starts[i]->page_size;
		if (page_size < 1) {
			page_size = 4096;
		}
		ut64 start = bin->segs[i].fileoff;
		ut64 end = start + bin->segs[i].filesize;
		if (end >= limit_start && start <= limit_end) {
			ut64 page_idx = (R_MAX (start, limit_start) - start) / page_size;
			ut64 page_end_idx = (R_MIN (limit_end, end) - start) / page_size;
			for (; page_idx <= page_end_idx; page_idx++) {
				if (page_idx >= bin->chained_starts[i]->page_count) {
					break;
				}
				ut16 page_start = bin->chained_starts[i]->page_start[page_idx];
				if (page_start == DYLD_CHAINED_PTR_START_NONE) {
					continue;
				}
				ut64 cursor = start + page_idx * page_size + page_start;
				while (cursor < limit_end && cursor < end) {
					ut8 tmp[8];
					bool previous_rebasing = bin->rebasing_buffer;
					bin->rebasing_buffer = true;
					if (r_buf_read_at (bin->b, cursor, tmp, 8) != 8) {
						bin->rebasing_buffer = previous_rebasing;
						break;
					}
					bin->rebasing_buffer = previous_rebasing;
					ut64 raw_ptr = r_read_le64 (tmp);
					ut64 ptr_value = raw_ptr;
					ut64 delta, stride, addend;
					ut16 pointer_format = bin->chained_starts[i]->pointer_format;
					RFixupEvent event = R_FIXUP_EVENT_NONE;
					ut8 key = 0, addr_div = 0;
					ut16 diversity = 0;
					ut32 ordinal = UT32_MAX;
					if (pointer_format == DYLD_CHAINED_PTR_ARM64E) {
						stride = 8;
						bool is_auth = IS_PTR_AUTH (raw_ptr);
						bool is_bind = IS_PTR_BIND (raw_ptr);
						if (is_auth && is_bind) {
							struct dyld_chained_ptr_arm64e_auth_bind *p =
									(struct dyld_chained_ptr_arm64e_auth_bind *) &raw_ptr;
							event = R_FIXUP_EVENT_BIND_AUTH;
							delta = p->next;
							ordinal = p->ordinal;
							key = p->key;
							addr_div = p->addrDiv;
							diversity = p->diversity;
						} else if (!is_auth && is_bind) {
							struct dyld_chained_ptr_arm64e_bind *p =
									(struct dyld_chained_ptr_arm64e_bind *) &raw_ptr;
							event = R_FIXUP_EVENT_BIND;
							delta = p->next;
							ordinal = p->ordinal;
							addend = p->addend;
						} else if (is_auth && !is_bind) {
							struct dyld_chained_ptr_arm64e_auth_rebase *p =
									(struct dyld_chained_ptr_arm64e_auth_rebase *) &raw_ptr;
							event = R_FIXUP_EVENT_REBASE_AUTH;
							delta = p->next;
							ptr_value = p->target + bin->baddr;
							key = p->key;
							addr_div = p->addrDiv;
							diversity = p->diversity;
						} else {
							struct dyld_chained_ptr_arm64e_rebase *p =
									(struct dyld_chained_ptr_arm64e_rebase *) &raw_ptr;
							event = R_FIXUP_EVENT_REBASE;
							delta = p->next;
							ptr_value = ((ut64)p->high8 << 56) | p->target;
						}
					} else if (pointer_format == DYLD_CHAINED_PTR_ARM64E_USERLAND24) {
						stride = 8;
						struct dyld_chained_ptr_arm64e_bind24 *bind =
								(struct dyld_chained_ptr_arm64e_bind24 *) &raw_ptr;
						if (bind->bind) {
							delta = bind->next;
							if (bind->auth) {
								struct dyld_chained_ptr_arm64e_auth_bind24 *p =
										(struct dyld_chained_ptr_arm64e_auth_bind24 *) &raw_ptr;
								event = R_FIXUP_EVENT_BIND_AUTH;
								ordinal = p->ordinal;
								key = p->key;
								addr_div = p->addrDiv;
								diversity = p->diversity;
							} else {
								event = R_FIXUP_EVENT_BIND;
								ordinal = bind->ordinal;
								addend = bind->addend;
							}
						} else {
							if (bind->auth) {
								struct dyld_chained_ptr_arm64e_auth_rebase *p =
										(struct dyld_chained_ptr_arm64e_auth_rebase *) &raw_ptr;
								event = R_FIXUP_EVENT_REBASE_AUTH;
								delta = p->next;
								ptr_value = p->target + bin->baddr;
								key = p->key;
								addr_div = p->addrDiv;
								diversity = p->diversity;
							} else {
								struct dyld_chained_ptr_arm64e_rebase *p =
									(struct dyld_chained_ptr_arm64e_rebase *) &raw_ptr;
								event = R_FIXUP_EVENT_REBASE;
								delta = p->next;
								ptr_value = bin->baddr + (((ut64)p->high8 << 56) | p->target);
							}
						}
					} else if (pointer_format == DYLD_CHAINED_PTR_64_OFFSET) {
						stride = 4;
						struct dyld_chained_ptr_64_bind *bind =
								(struct dyld_chained_ptr_64_bind *) &raw_ptr;
						if (bind->bind) {
							event = R_FIXUP_EVENT_BIND;
							delta = bind->next;
							ordinal = bind->ordinal;
							addend = bind->addend;
						} else {
							struct dyld_chained_ptr_64_rebase *p =
								(struct dyld_chained_ptr_64_rebase *) &raw_ptr;
							event = R_FIXUP_EVENT_REBASE;
							delta = p->next;
							ptr_value = bin->baddr + (((ut64)p->high8 << 56) | p->target);
						}
					} else {
						eprintf ("Unsupported chained pointer format %d\n", pointer_format);
						return;
					}
					if (cursor >= limit_start && cursor <= limit_end - 8 && (event & event_mask) != 0) {
						bool carry_on;
						switch (event) {
							case R_FIXUP_EVENT_BIND: {
								RFixupBindEventDetails event_details;

								event_details.type = event;
								event_details.bin = bin;
								event_details.offset = cursor;
								event_details.raw_ptr = raw_ptr;
								event_details.ordinal = ordinal;
								event_details.addend = addend;

								carry_on = callback (context, (RFixupEventDetails *) &event_details);
								break;
							}
							case R_FIXUP_EVENT_BIND_AUTH: {
								RFixupBindAuthEventDetails event_details;

								event_details.type = event;
								event_details.bin = bin;
								event_details.offset = cursor;
								event_details.raw_ptr = raw_ptr;
								event_details.ordinal = ordinal;
								event_details.key = key;
								event_details.addr_div = addr_div;
								event_details.diversity = diversity;

								carry_on = callback (context, (RFixupEventDetails *) &event_details);
								break;
							}
							case R_FIXUP_EVENT_REBASE: {
								RFixupRebaseEventDetails event_details;

								event_details.type = event;
								event_details.bin = bin;
								event_details.offset = cursor;
								event_details.raw_ptr = raw_ptr;
								event_details.ptr_value = ptr_value;

								carry_on = callback (context, (RFixupEventDetails *) &event_details);
								break;
							}
							case R_FIXUP_EVENT_REBASE_AUTH: {
								RFixupRebaseAuthEventDetails event_details;

								event_details.type = event;
								event_details.bin = bin;
								event_details.offset = cursor;
								event_details.raw_ptr = raw_ptr;
								event_details.ptr_value = ptr_value;
								event_details.key = key;
								event_details.addr_div = addr_div;
								event_details.diversity = diversity;

								carry_on = callback (context, (RFixupEventDetails *) &event_details);
								break;
							}
							default:
								eprintf ("Unexpected event while iterating chained fixups\n");
								carry_on = false;
						}
						if (!carry_on) {
							return;
						}
					}
					cursor += delta * stride;
					if (!delta) {
						break;
					}
				}
			}
		}
	}
}

static BOOL qo(ZGFX_CONTEXT* zb, wStream* tp, size_t vq)
{
	BYTE c;
	BYTE flags;
	UINT32 extra = 0;
	int opIndex;
	UINT32 haveBits;
	UINT32 inPrefix;
	UINT32 count;
	UINT32 distance;
	BYTE* pbSegment;
	size_t cbSegment;

	if (!zgfx || !stream || (vq < 2))
		return FALSE;

	cbSegment = vq - 1;

	if ((Stream_GetRemainingLength(tp) < vq) || (vq > UINT32_MAX))
		return FALSE;

	Stream_Read_UINT8(tp, flags); 
	zgfx->OutputCount = 0;
	pbSegment = Stream_Pointer(tp);
	if (!Stream_SafeSeek(tp, cbSegment))
		return FALSE;

	if (!(flags & PACKET_COMPRESSED))
	{
		zgfx_history_buffer_ring_write(zb, pbSegment, cbSegment);

		if (cbSegment > sizeof(zb->OutputBuffer))
			return FALSE;

		CopyMemory(zb->OutputBuffer, pbSegment, cbSegment);
		zgfx->OutputCount = cbSegment;
		return TRUE;
	}

	zgfx->pbInputCurrent = pbSegment;
	zgfx->pbInputEnd = &pbSegment[cbSegment - 1];

	zgfx->cBitsRemaining = 8 * (cbSegment - 1) - *zb->pbInputEnd;
	zgfx->cBitsCurrent = 0;
	zgfx->BitsCurrent = 0;

	while (zb->cBitsRemaining)
	{
		haveBits = 0;
		inPrefix = 0;

		for (opIndex = 0; ZGFX_TOKEN_TABLE[opIndex].prefixLength != 0; opIndex++)
		{
			while (haveBits < ZGFX_TOKEN_TABLE[opIndex].prefixLength)
			{
				zgfx_GetBits(zb, 1);
				inPrefix = (inPrefix << 1) + zb->bits;
				haveBits++;
			}

			if (inPrefix == ZGFX_TOKEN_TABLE[opIndex].prefixCode)
			{
				if (ZGFX_TOKEN_TABLE[opIndex].tokenType == 0)
				{

					zgfx_GetBits(zb, ZGFX_TOKEN_TABLE[opIndex].valueBits);
					c = (BYTE)(ZGFX_TOKEN_TABLE[opIndex].valueBase + zb->bits);
					zgfx->HistoryBuffer[zb->HistoryIndex] = c;

					if (++zgfx->HistoryIndex == zb->HistoryBufferSize)
						zgfx->HistoryIndex = 0;

					if (zb->OutputCount >= sizeof(zb->OutputBuffer))
						return FALSE;

					zgfx->OutputBuffer[zb->OutputCount++] = c;
				}
				else
				{
					zgfx_GetBits(zb, ZGFX_TOKEN_TABLE[opIndex].valueBits);
					distance = ZGFX_TOKEN_TABLE[opIndex].valueBase + zb->bits;

					if (distance != 0)
					{

						zgfx_GetBits(zb, 1);

						if (zb->bits == 0)
						{
							count = 3;
						}
						else
						{
							count = 4;
							extra = 2;
							zgfx_GetBits(zb, 1);

							while (zb->bits == 1)
							{
								count *= 2;
								extra++;
								zgfx_GetBits(zb, 1);
							}

							zgfx_GetBits(zb, extra);
							count += zb->bits;
						}

						if (count > sizeof(zb->OutputBuffer) - zb->OutputCount)
							return FALSE;

						zgfx_history_buffer_ring_read(
						    zb, distance, &(zb->OutputBuffer[zb->OutputCount]), count);
						zgfx_history_buffer_ring_write(
						    zb, &(zb->OutputBuffer[zb->OutputCount]), count);
						zgfx->OutputCount += count;
					}
					else
					{

						zgfx_GetBits(zb, 15);
						count = zb->bits;
						zgfx->cBitsRemaining -= zb->cBitsCurrent;
						zgfx->cBitsCurrent = 0;
						zgfx->BitsCurrent = 0;

						if (count > sizeof(zb->OutputBuffer) - zb->OutputCount)
							return FALSE;

						if (count > zb->cBitsRemaining / 8)
							return FALSE;

						CopyMemory(&(zb->OutputBuffer[zb->OutputCount]), zb->pbInputCurrent,
						           count);
						zgfx_history_buffer_ring_write(zb, zb->pbInputCurrent, count);
						zgfx->pbInputCurrent += count;
						zgfx->cBitsRemaining -= (8 * count);
						zgfx->OutputCount += count;
					}
				}

				break;
			}
		}
	}

	return TRUE;
}

static void zy(GF_SceneDumper *ki, GF_Node *gs, GF_FieldInfo jh, Bool kh)
{
	u32 i, sf_type;
	void *slot_ptr;

	if (gf_sg_vrml_is_sf_field(field.fieldType)) {
		DUMP_IND(ki);
		if (ki->XMLDump) {
			if (ki->X3DDump) {
				gf_fprintf(ki->trace, "<field name=\"%s\" type=\"%s\" accessType=\"%s\"",
				        field.name, gf_sg_vrml_get_field_type_name(field.fieldType), gf_sg_vrml_get_event_type_name(field.eventType, 1));
			} else {
				gf_fprintf(ki->trace, "<field name=\"%s\" type=\"%s\" vrml97Hint=\"%s\"",
				        field.name, GetXMTFieldTypeName(field.fieldType), gf_sg_vrml_get_event_type_name(field.eventType, 0));
			}

			if ((field.eventType == GF_SG_EVENT_FIELD) || (field.eventType == GF_SG_EVENT_EXPOSED_FIELD)) {
				if (field.fieldType == GF_SG_VRML_SFNODE) {
					if (!sdump->X3DDump) {
						gf_fprintf(ki->trace, ">\n");
						sdump->indent++;
						gf_fprintf(ki->trace, "<node>");
						gf_dump_vrml_node(ki, field.far_ptr ? *(GF_Node **)field.far_ptr : NULL, 0, NULL);
						gf_fprintf(ki->trace, "</node>");
						sdump->indent--;
						if (!has_sublist)
							gf_fprintf(ki->trace, "</field>\n");
					} else {
						if (field.far_ptr) {
							gf_fprintf(ki->trace, ">\n");
							gf_dump_vrml_node(ki, *(GF_Node **)field.far_ptr, 0, NULL);
							gf_fprintf(ki->trace, "</field>\n");
						} else {
							gf_fprintf(ki->trace, "/>\n");
						}
					}
					DUMP_IND(ki);
				} else {
					if (ki->X3DDump) {
						gf_fprintf(ki->trace, " value=\"");
					} else {
						gf_fprintf(ki->trace, " %s=\"", GetXMTFieldTypeValueName(field.fieldType));
					}
					if (field.far_ptr)
						gf_dump_vrml_sffield(ki, field.fieldType, field.far_ptr, 0, gs);
					if (kh)
						gf_fprintf(ki->trace, "\">\n");
					else
						gf_fprintf(ki->trace, "\"/>\n");
				}
			} else {
				gf_fprintf(ki->trace, "/>\n");
			}
		} else {
			gf_fprintf(ki->trace, "%s %s %s", gf_sg_vrml_get_event_type_name(field.eventType, ki->X3DDump), gf_sg_vrml_get_field_type_name(field.fieldType), field.name);
			if ((field.eventType==GF_SG_EVENT_FIELD) || (field.eventType==GF_SG_EVENT_EXPOSED_FIELD)) {
				gf_fprintf(ki->trace, " ");
				if (field.fieldType == GF_SG_VRML_SFNODE) {
					gf_dump_vrml_node(ki, field.far_ptr ? *(GF_Node **)field.far_ptr : NULL, 0, NULL);
				} else if (field.far_ptr) {
					gf_dump_vrml_simple_field(ki, jh, gs);
				}
			}
			gf_fprintf(ki->trace, "\n");
		}
	} else if (field.far_ptr) {
		GenMFField *mffield = (GenMFField *) field.far_ptr;
		sf_type = gf_sg_vrml_get_sf_type(field.fieldType);

		DUMP_IND(ki);
		if (!sdump->XMLDump) {
			gf_fprintf(ki->trace, "%s %s %s", gf_sg_vrml_get_event_type_name(field.eventType, ki->X3DDump), gf_sg_vrml_get_field_type_name(field.fieldType), field.name);
			if ((field.eventType==GF_SG_EVENT_FIELD) || (field.eventType==GF_SG_EVENT_EXPOSED_FIELD)) {
				gf_fprintf(ki->trace, " [");

				if (sf_type == GF_SG_VRML_SFNODE) {
					GF_ChildNodeItem *l = *(GF_ChildNodeItem **)field.far_ptr;
					gf_fprintf(ki->trace, "\n");
					sdump->indent++;
					while (l) {
						gf_dump_vrml_node(ki, l->gs, 1, NULL);
						l = l->next;
					}
					sdump->indent--;
					DUMP_IND(ki);
				} else {
					for (i=0; mffield && (i<mffield->count); i++) {
						if (i) gf_fprintf(ki->trace, " ");
						if (field.fieldType != GF_SG_VRML_MFNODE) {
							gf_sg_vrml_mf_get_item(field.far_ptr, field.fieldType, &slot_ptr, i);
							gf_dump_vrml_sffield(ki, sf_type, slot_ptr, (mffield->count>1) ? 1 : 0, gs);
						}
					}
				}
				gf_fprintf(ki->trace, "]");
			}
			gf_fprintf(ki->trace, "\n");
		} else {
			if (ki->X3DDump) {
				gf_fprintf(ki->trace, "<field name=\"%s\" type=\"%s\" accessType=\"%s\"",
				        field.name, gf_sg_vrml_get_field_type_name(field.fieldType), gf_sg_vrml_get_event_type_name(field.eventType, 1));
			} else {
				gf_fprintf(ki->trace, "<field name=\"%s\" type=\"%s\" vrml97Hint=\"%s\"",
				        field.name, GetXMTFieldTypeName(field.fieldType), gf_sg_vrml_get_event_type_name(field.eventType, 0));
			}

			if ((field.eventType==GF_SG_EVENT_FIELD) || (field.eventType==GF_SG_EVENT_EXPOSED_FIELD)) {
				if (sf_type == GF_SG_VRML_SFNODE) {
					GF_ChildNodeItem *list = *(GF_ChildNodeItem **)field.far_ptr;
					gf_fprintf(ki->trace, ">\n");
					sdump->indent++;
					if (!sdump->X3DDump) gf_fprintf(ki->trace, "<nodes>");
					while (list) {
						gf_dump_vrml_node(ki, list->gs, 1, NULL);
						list = list->next;
					}
					if (!sdump->X3DDump) gf_fprintf(ki->trace, "</nodes>");
					sdump->indent++;
					DUMP_IND(ki);
					if (!has_sublist)
						gf_fprintf(ki->trace, "</field>\n");
				} else {
					if (ki->X3DDump) {
						gf_fprintf(ki->trace, " value=\"");
					} else {
						gf_fprintf(ki->trace, " %s=\"", GetXMTFieldTypeValueName(field.fieldType));
					}
					for (i=0; mffield && (i<mffield->count); i++) {
						if (i) gf_fprintf(ki->trace, " ");
						if (field.fieldType != GF_SG_VRML_MFNODE) {
							gf_sg_vrml_mf_get_item(field.far_ptr, field.fieldType, &slot_ptr, i);
							gf_dump_vrml_sffield(ki, sf_type, slot_ptr, (mffield->count>1) ? 1 : 0, gs);
						}
					}
					if (kh)
						gf_fprintf(ki->trace, "\">\n");
					else
						gf_fprintf(ki->trace, "\"/>\n");
				}
			} else {
				gf_fprintf(ki->trace, "/>\n");
			}
		}
	}
}

njs_int_t
njs_function_frame_save(njs_vm_t *lh, njs_frame_t *ok, u_char *xd)
{
    size_t              value_count, n;
    njs_value_t         *start, *end, *p, **new, *value, **local;
    njs_function_t      *function;
    njs_native_frame_t  *active, *native;

    *ok = *lh->active_frame;

    ok->previous_active_frame = NULL;

    native = &ok->native;
    native->size = 0;
    native->free = NULL;
    native->free_size = 0;

    active = &lh->active_frame->native;
    value_count = njs_function_frame_value_count(active);

    function = active->function;

    new = (njs_value_t **) ((u_char *) native + NJS_FRAME_SIZE);
    value = (njs_value_t *) (new + value_count
                             + function->u.lambda->temp);


    native->arguments = value;
    native->arguments_offset = value + (function->args_offset - 1);
    native->local = new + njs_function_frame_args_count(active);
    native->temp = new + value_count;
    native->xd = xd;

    start = njs_function_frame_values(active, &end);
    p = native->arguments;

    while (start < end) {
        *p = *start++;
        *new++ = p++;
    }



    p = native->arguments;
    local = native->local + function->args_offset;

    for (n = 0; n < function->args_count; n++) {
        if (!njs_is_valid(p)) {
            njs_set_undefined(p);
        }

        *local++ = p++;
    }

    return NJS_OK;
}

