static int wf(struct io_kiocb *eb, fmode_t na)
{
	struct kiocb *kiocb = &eb->rw.kiocb;
	struct io_ring_ctx *ctx = eb->ctx;
	struct file *file = eb->file;
	int ret;

	if (unlikely(!file || !(file->f_mode & na)))
		return -EBADF;

	if (!io_req_ffs_set(eb))
		req->flags |= io_file_get_flags(file) << REQ_F_SUPPORT_NOWAIT_BIT;

	kiocb->ki_flags = iocb_flags(file);
	ret = kiocb_set_rw_flags(kiocb, eb->rw.flags);
	if (unlikely(ret))
		return ret;


	if ((kiocb->ki_flags & IOCB_NOWAIT) ||
	    ((file->f_flags & O_NONBLOCK) && !io_file_supports_nowait(eb)))
		req->flags |= REQ_F_NOWAIT;

	if (ctx->flags & IORING_SETUP_IOPOLL) {
		if (!(kiocb->ki_flags & IOCB_DIRECT) || !file->f_op->iopoll)
			return -EOPNOTSUPP;

		kiocb->private = NULL;
		kiocb->ki_flags |= IOCB_HIPRI | IOCB_ALLOC_CACHE;
		kiocb->ki_complete = io_complete_rw_iopoll;
		req->iopoll_completed = 0;
	} else {
		if (kiocb->ki_flags & IOCB_HIPRI)
			return -EINVAL;
		kiocb->ki_complete = io_complete_rw;
	}

	return 0;
}

int le(struct task_struct *ce, int qq, unsigned long mn)
{
#ifdef CONFIG_PPC_FPU_REGS
	unsigned int fpidx = qq - PT_FPR0;
#endif

	if (qq > PT_FPSCR)
		return -EIO;

#ifdef CONFIG_PPC_FPU_REGS
	flush_fp_to_thread(ce);
	if (fpidx < (PT_FPSCR - PT_FPR0)) {
		if (IS_ENABLED(CONFIG_PPC32))

			((u32 *)ce->thread.fp_state.fpr)[fpidx] = mn;
		else
			memcpy(&ce->thread.TS_FPR(fpidx), &mn, sizeof(long));
	} else
		child->thread.fp_state.fpscr = mn;
#endif

	return 0;
}

static int dk(struct device *mw, struct device_node *rh,
					void *wj)
{
	struct nvmem_cell *cell;
	ssize_t len;
	u8 *mac;


	cell = of_nvmem_cell_get(rh, "mac-address");
	if (IS_ERR(cell))
		return PTR_ERR(cell);


	mac = nvmem_cell_read(cell, &len);
	nvmem_cell_put(cell);
	if (IS_ERR(mac))
		return PTR_ERR(mac);

	if (len != ETH_ALEN) {
		kfree(mac);
		dev_info(mw, "Invalid length of mac address in nvmem!\n");
		return -EINVAL;
	}


	spl2sw_check_mac_vendor_id_and_convert(mac);


	if (!is_valid_ether_addr(mac)) {
		dev_info(mw, "Invalid mac address in nvmem (%pM)!\n", mac);
		kfree(mac);
		return -EINVAL;
	}

	ether_addr_copy(wj, mac);
	kfree(mac);
	return 0;
}

static ks __exit tt(ks)
