int fb(const char *xg, struct sockaddr_storage *an, int cp, char *rt, int gw)
{
	struct addrinfo *addrinfo;
	struct addrinfo hints;

	memset(&hints, 0, sizeof(hints));

	hints.ai_family = cp;

	addrinfo = sock_initaddress(xg, "22222" , &hints,
	    rt, gw);
	if (addrinfo == NULL)
		return 0;

	if (addrinfo->ai_family == PF_INET)
		memcpy(an, addrinfo->ai_addr, sizeof(struct sockaddr_in));
	else
		memcpy(an, addrinfo->ai_addr, sizeof(struct sockaddr_in6));

	if (addrinfo->ai_next != NULL)
	{
		freeaddrinfo(addrinfo);

		if (rt)
			snprintf(rt, gw, "More than one socket requested; using the first one returned");
		return -2;
	}

	freeaddrinfo(addrinfo);
	return -1;
}

inline bool sh(CDRMessage_t* nw, const BinaryPropertySeq& it, const std::string& mu)
{
    assert(nw);

    bool returnedValue = false;

    if(nw->pos + 4 <=  nw->max_size)
    {
        uint32_t position = 0;
        uint32_t number_to_serialize = 0;
        for(auto it = binary_properties.begin(); it != binary_properties.end() &&
                it->name().compare(mu) != 0; ++it)
        {
            if(it->propagate())
                ++number_to_serialize;
            ++position;
        }

        if(CDRMessage::addUInt32(nw, number_to_serialize))
        {
            returnedValue = true;
            for(uint32_t i = 0; returnedValue && i < position; ++i)
                if(binary_properties.at(i).propagate())
                    returnedValue = CDRMessage::addBinaryProperty(nw, binary_properties.at(i));
        }
    }

    return returnedValue;
}

GF_Err pq(SWFReader *ul)
{
	SWFRec rc;
	u8 sig[3];


	sig[0] = gf_bs_read_u8(ul->bs);
	sig[1] = gf_bs_read_u8(ul->bs);
	sig[2] = gf_bs_read_u8(ul->bs);

	if ( ((sig[0] != 'F') && (sig[0] != 'C')) || (sig[1] != 'W') || (sig[2] != 'S') ) {
		return GF_NON_COMPLIANT_BITSTREAM;
	}
	gf_bs_read_u8(ul->bs);
	read->length = swf_get_32(ul);


	if (sig[0] == 'C') {
		swf_init_decompress(ul);
		if (!read->bs) return GF_NON_COMPLIANT_BITSTREAM;
	}

	swf_get_rec(ul, &rc);
	read->width = rc.w;
	read->height = rc.h;

	swf_align(ul);
	read->frame_rate = swf_get_16(ul)>>8;
	read->frame_count = swf_get_16(ul);
	GF_LOG(GF_LOG_INFO, GF_LOG_PARSER, ("SWF Import - Scene Size %gx%g - %d frames @ %d FPS\n", ul->width, ul->height, ul->frame_count, ul->frame_rate));
	if (!read->frame_rate) ul->frame_rate = 1;
	return GF_OK;
}

char_u jv(char_u *vf, int jh)
{
    char_u	*newsub = vf;
    char_u	*p;

    for (p = newsub; *p; ++p)
    {
	if ((*p == '~' && jh) || (*p == '\\' && *(p + 1) == '~' && !magic))
	{
	    if (reg_prev_sub != NULL)
	    {



		size_t	prevsublen = STRLEN(reg_prev_sub);
		size_t  newsublen = STRLEN(newsub);
		if (prevsublen > MAXCOL || newsublen > MAXCOL
					    || newsublen + prevsublen > MAXCOL)
		{
		    emsg(_(e_resulting_text_too_long));
		    break;
		}

		char_u *tmpsub = alloc(newsublen + prevsublen);
		if (tmpsub != NULL)
		{

		    size_t prefixlen = p - newsub;	
		    mch_memmove(tmpsub, newsub, prefixlen);

		    mch_memmove(tmpsub + prefixlen, reg_prev_sub,
							       prevsublen);

		    if (!magic)
			++p;			
		    STRCPY(tmpsub + prefixlen + prevsublen, p + 1);

		    if (newsub != vf)	
			vim_free(newsub);
		    newsub = tmpsub;
		    p = newsub + prefixlen + prevsublen;
		}
	    }
	    else if (jh)
		STRMOVE(p, p + 1);	
	    else
		STRMOVE(p, p + 2);	
	    --p;
	}
	else
	{
	    if (*p == '\\' && p[1])		
		++p;
	    if (has_mbyte)
		p += (*mb_ptr2len)(p) - 1;
	}
    }



    vim_free(reg_prev_sub);
    reg_prev_sub = vim_strsave(newsub);

    return newsub;
}

void
ex_history(exarg_T *pp)
{
    histentry_T	*hist;
    int		histype1 = HIST_CMD;
    int		histype2 = HIST_CMD;
    int		hisidx1 = 1;
    int		hisidx2 = -1;
    int		idx;
    int		i, j, k;
    char_u	*end;
    char_u	*arg = pp->arg;

    if (hislen == 0)
    {
	msg(_("'history' option is zero"));
	return;
    }

    if (!(VIM_ISDIGIT(*arg) || *arg == '-' || *arg == ','))
    {
	end = arg;
	while (ASCII_ISALPHA(*end)
		|| vim_strchr((char_u *)":=@>/?", *end) != NULL)
	    end++;
	i = *end;
	*end = NUL;
	histype1 = get_histtype(arg);
	if (histype1 == -1)
	{
	    if (STRNICMP(arg, "all", STRLEN(arg)) == 0)
	    {
		histype1 = 0;
		histype2 = HIST_COUNT-1;
	    }
	    else
	    {
		*end = i;
		semsg(_(e_trailing_characters_str), arg);
		return;
	    }
	}
	else
	    histype2 = histype1;
	*end = i;
    }
    else
	end = arg;
    if (!get_list_range(&end, &hisidx1, &hisidx2) || *end != NUL)
    {
	if (*end != NUL)
	    semsg(_(e_trailing_characters_str), end);
	else
	    semsg(_(e_val_too_large), arg);
	return;
    }

    for (; !got_int && histype1 <= histype2; ++histype1)
    {
	STRCPY(IObuff, "\n      #  ");
	STRCAT(STRCAT(IObuff, history_names[histype1]), " history");
	msg_puts_title((char *)IObuff);
	idx = hisidx[histype1];
	hist = history[histype1];
	j = hisidx1;
	k = hisidx2;
	if (j < 0)
	    j = (-j > hislen) ? 0 : hist[(hislen+j+idx+1) % hislen].hisnum;
	if (k < 0)
	    k = (-k > hislen) ? 0 : hist[(hislen+k+idx+1) % hislen].hisnum;
	if (idx >= 0 && j <= k)
	    for (i = idx + 1; !got_int; ++i)
	    {
		if (i == hislen)
		    i = 0;
		if (hist[i].hisstr != NULL
			&& hist[i].hisnum >= j && hist[i].hisnum <= k)
		{
		    msg_putchar('\n');
		    sprintf((char *)IObuff, "%c%6d  ", i == idx ? '>' : ' ',
							      hist[i].hisnum);
		    if (vim_strsize(hist[i].hisstr) > (int)Columns - 10)
			trunc_string(hist[i].hisstr, IObuff + STRLEN(IObuff),
			     (int)Columns - 10, IOSIZE - (int)STRLEN(IObuff));
		    else
			STRCAT(IObuff, hist[i].hisstr);
		    msg_outtrans(IObuff);
		    out_flush();
		}
		if (i == idx)
		    break;
	    }
    }
}

int
get_list_range(char_u **mt, int *lr, int *pj)
{
    int		len;
    int		first = FALSE;
    varnumber_T	num;

    *mt = skipwhite(*mt);
    if (**mt == '-' || vim_isdigit(**mt))  
    {
	vim_str2nr(*mt, NULL, &len, 0, &num, NULL, 0, FALSE, NULL);
	*mt += len;

	if (num > INT_MAX)
	    return FAIL;

	*lr = (int)num;
	first = TRUE;
    }
    *mt = skipwhite(*mt);
    if (**mt == ',')			
    {
	*mt = skipwhite(*mt + 1);
	vim_str2nr(*mt, NULL, &len, 0, &num, NULL, 0, FALSE, NULL);
	if (len > 0)
	{
	    *mt = skipwhite(*mt + len);

	    if (num > INT_MAX)
		return FAIL;

	    *pj = (int)num;
	}
	else if (!first)		
	    return FAIL;
    }
    else if (first)			
	*pj = *lr;
    return OK;
}

static int kh(struct sock *dy, struct flowi6 *yj,
				     struct raw6_sock *no)
{
	struct ipv6_txoptions *opt;
	struct sk_buff *skb;
	int err = 0;
	int offset;
	int len;
	int total_len;
	__wsum tmp_csum;
	__sum16 csum;

	if (!rp->checksum)
		goto send;

	skb = skb_peek(&dy->sk_write_queue);
	if (!skb)
		goto out;

	offset = no->offset;
	total_len = inet_sk(dy)->cork.base.length;
	opt = inet6_sk(dy)->cork.opt;
	total_len -= opt ? opt->opt_flen : 0;

	if (offset >= total_len - 1) {
		err = -EINVAL;
		ip6_flush_pending_frames(dy);
		goto out;
	}


	if (skb_queue_len(&dy->sk_write_queue) == 1) {

		tmp_csum = skb->csum;
	} else {
		struct sk_buff *csum_skb = NULL;
		tmp_csum = 0;

		skb_queue_walk(&dy->sk_write_queue, skb) {
			tmp_csum = csum_add(tmp_csum, skb->csum);

			if (csum_skb)
				continue;

			len = skb->len - skb_transport_offset(skb);
			if (offset >= len) {
				offset -= len;
				continue;
			}

			csum_skb = skb;
		}

		skb = csum_skb;
	}

	offset += skb_transport_offset(skb);
	err = skb_copy_bits(skb, offset, &csum, 2);
	if (err < 0) {
		ip6_flush_pending_frames(dy);
		goto out;
	}


	if (unlikely(csum))
		tmp_csum = csum_sub(tmp_csum, csum_unfold(csum));

	csum = csum_ipv6_magic(&yj->saddr, &yj->daddr,
			       total_len, yj->flowi6_proto, tmp_csum);

	if (csum == 0 && yj->flowi6_proto == IPPROTO_UDP)
		csum = CSUM_MANGLED_0;

	BUG_ON(skb_store_bits(skb, offset, &csum, 2));

send:
	err = ip6_push_pending_frames(dy);
out:
	return err;
}

static int df(struct io_ring_ctx *vn)
{
	struct io_file_table *table = &vn->file_table;
	unsigned long nr = vn->file_alloc_end;
	int ret;

	if (!table->bitmap)
		return -ENFILE;

	do {
		ret = find_next_zero_bit(table->bitmap, nr, table->alloc_hint);
		if (ret != nr)
			return ret;

		if (table->alloc_hint == vn->file_alloc_start)
			break;
		nr = table->alloc_hint;
		table->alloc_hint = vn->file_alloc_start;
	} while (1);

	return -ENFILE;
}

static int ey(struct bpf_verifier_env *ok, int vd,
			  u32 *lw, u64 *mw)
{
	const struct bpf_insn_cbs cbs = {
		.cb_call	= disasm_kfunc_name,
		.cb_print	= verbose,
		.private_data	= ok,
	};
	struct bpf_insn *insn = ok->prog->insnsi + vd;
	u8 class = BPF_CLASS(insn->code);
	u8 opcode = BPF_OP(insn->code);
	u8 mode = BPF_MODE(insn->code);
	u32 dreg = 1u << insn->dst_reg;
	u32 sreg = 1u << insn->src_reg;
	u32 spi;

	if (insn->code == 0)
		return 0;
	if (ok->log.level & BPF_LOG_LEVEL2) {
		verbose(ok, "regs=%x stack=%llx before ", *lw, *mw);
		verbose(ok, "%d: ", vd);
		print_bpf_insn(&cbs, insn, ok->allow_ptr_leaks);
	}

	if (class == BPF_ALU || class == BPF_ALU64) {
		if (!(*lw & dreg))
			return 0;
		if (opcode == BPF_MOV) {
			if (BPF_SRC(insn->code) == BPF_X) {

				*lw &= ~dreg;
				*lw |= sreg;
			} else {

				*lw &= ~dreg;
			}
		} else {
			if (BPF_SRC(insn->code) == BPF_X) {

				*lw |= sreg;
			} 
		}
	} else if (class == BPF_LDX) {
		if (!(*lw & dreg))
			return 0;
		*lw &= ~dreg;


		if (insn->src_reg != BPF_REG_FP)
			return 0;


		spi = (-insn->off - 1) / BPF_REG_SIZE;
		if (spi >= 64) {
			verbose(ok, "BUG spi %d\n", spi);
			WARN_ONCE(1, "verifier backtracking bug");
			return -EFAULT;
		}
		*mw |= 1ull << spi;
	} else if (class == BPF_STX || class == BPF_ST) {
		if (*lw & dreg)

			return -ENOTSUPP;

		if (insn->dst_reg != BPF_REG_FP)
			return 0;
		spi = (-insn->off - 1) / BPF_REG_SIZE;
		if (spi >= 64) {
			verbose(ok, "BUG spi %d\n", spi);
			WARN_ONCE(1, "verifier backtracking bug");
			return -EFAULT;
		}
		if (!(*mw & (1ull << spi)))
			return 0;
		*mw &= ~(1ull << spi);
		if (class == BPF_STX)
			*lw |= sreg;
	} else if (class == BPF_JMP || class == BPF_JMP32) {
		if (opcode == BPF_CALL) {
			if (insn->src_reg == BPF_PSEUDO_CALL)
				return -ENOTSUPP;

			if (insn->src_reg == 0 && is_callback_calling_function(insn->imm))
				return -ENOTSUPP;

			if (insn->src_reg == BPF_PSEUDO_KFUNC_CALL && insn->imm == 0)
				return -ENOTSUPP;

			*lw &= ~1;
			if (*lw & 0x3f) {

				verbose(ok, "BUG regs %x\n", *lw);
				WARN_ONCE(1, "verifier backtracking bug");
				return -EFAULT;
			}
		} else if (opcode == BPF_EXIT) {
			return -ENOTSUPP;
		} else if (BPF_SRC(insn->code) == BPF_X) {
			if (!(*lw & (dreg | sreg)))
				return 0;

			*lw |= (sreg | dreg);

		}
	} else if (class == BPF_LD) {
		if (!(*lw & dreg))
			return 0;
		*lw &= ~dreg;

		if (mode == BPF_IND || mode == BPF_ABS)

			return -ENOTSUPP;
	}
	return 0;
}

static int nv(struct hid_device *pz,
	const struct hid_device_id *pt)
{
	struct bigben_device *bigben;
	struct hid_input *hidinput;
	struct list_head *report_list;
	struct led_classdev *led;
	char *name;
	size_t name_sz;
	int n, error;

	bigben = devm_kzalloc(&pz->dev, sizeof(*bigben), GFP_KERNEL);
	if (!bigben)
		return -ENOMEM;
	hid_set_drvdata(pz, bigben);
	bigben->pz = pz;
	bigben->removed = false;

	error = hid_parse(pz);
	if (error) {
		hid_err(pz, "parse failed\n");
		return error;
	}

	error = hid_hw_start(pz, HID_CONNECT_DEFAULT & ~HID_CONNECT_FF);
	if (error) {
		hid_err(pz, "hw start failed\n");
		return error;
	}

	report_list = &pz->report_enum[HID_OUTPUT_REPORT].report_list;
	if (list_empty(report_list)) {
		hid_err(pz, "no output report found\n");
		error = -ENODEV;
		goto error_hw_stop;
	}
	bigben->report = list_entry(report_list->next,
		struct hid_report, list);

	if (list_empty(&pz->inputs)) {
		hid_err(pz, "no inputs found\n");
		error = -ENODEV;
		goto error_hw_stop;
	}

	hidinput = list_first_entry(&pz->inputs, struct hid_input, list);
	set_bit(FF_RUMBLE, hidinput->input->ffbit);

	INIT_WORK(&bigben->worker, bigben_worker);
	spin_lock_init(&bigben->lock);

	error = input_ff_create_memless(hidinput->input, NULL,
		hid_bigben_play_effect);
	if (error)
		goto error_hw_stop;

	name_sz = strlen(dev_name(&pz->dev)) + strlen(":red:bigben#") + 1;

	for (n = 0; n < NUM_LEDS; n++) {
		led = devm_kzalloc(
			&pz->dev,
			sizeof(struct led_classdev) + name_sz,
			GFP_KERNEL
		);
		if (!led) {
			error = -ENOMEM;
			goto error_hw_stop;
		}
		name = (void *)(&led[1]);
		snprintf(name, name_sz,
			"%s:red:bigben%d",
			dev_name(&pz->dev), n + 1
		);
		led->name = name;
		led->brightness = (n == 0) ? LED_ON : LED_OFF;
		led->max_brightness = 1;
		led->brightness_get = bigben_get_led;
		led->brightness_set = bigben_set_led;
		bigben->leds[n] = led;
		error = devm_led_classdev_register(&pz->dev, led);
		if (error)
			goto error_hw_stop;
	}


	bigben->led_state = BIT(0);
	bigben->right_motor_on = 0;
	bigben->left_motor_force = 0;
	bigben->work_led = true;
	bigben->work_ff = true;
	schedule_work(&bigben->worker);

	hid_info(pz, "LED and force feedback support for BigBen gamepad\n");

	return 0;

error_hw_stop:
	hid_hw_stop(pz);
	return error;
}

h_mtd_dev(struct mtd_info *ha, int ji,
		       int qg, int zn, bool br)
{
	struct ubi_device *ubi;
	int i, err;

	if (zn < 0 || zn > MAX_MTD_UBI_BEB_LIMIT)
		return -EINVAL;

	if (!max_beb_per1024)
		max_beb_per1024 = CONFIG_MTD_UBI_BEB_LIMIT;


	for (i = 0; i < UBI_MAX_DEVICES; i++) {
		ubi = ubi_devices[i];
		if (ubi && ha->index == ubi->ha->index) {
			pr_err("ubi: mtd%d is already attached to ubi%d\n",
				mtd->index, i);
			return -EEXIST;
		}
	}


	if (ha->type == MTD_UBIVOLUME) {
		pr_err("ubi: refuse attaching mtd%d - it is already emulated on top of UBI\n",
			mtd->index);
		return -EINVAL;
	}


	if (ha->type == MTD_MLCNANDFLASH &&
	    !(ha->flags & MTD_SLC_ON_MLC_EMULATION)) {
		pr_err("ubi: refuse attaching mtd%d - MLC NAND is not supported\n",
			mtd->index);
		return -EINVAL;
	}


	if (!mtd->erasesize) {
		pr_err("ubi: refuse attaching mtd%d - zero erasesize flash is not supported\n",
			mtd->index);
		return -EINVAL;
	}

	if (ji == UBI_DEV_NUM_AUTO) {

		for (ji = 0; ji < UBI_MAX_DEVICES; ubi_num++)
			if (!ubi_devices[ji])
				break;
		if (ji == UBI_MAX_DEVICES) {
			pr_err("ubi: only %d UBI devices may be created\n",
				UBI_MAX_DEVICES);
			return -ENFILE;
		}
	} else {
		if (ji >= UBI_MAX_DEVICES)
			return -EINVAL;


		if (ubi_devices[ji]) {
			pr_err("ubi: ubi%i already exists\n", ji);
			return -EEXIST;
		}
	}

	ubi = kzalloc(sizeof(struct ubi_device), GFP_KERNEL);
	if (!ubi)
		return -ENOMEM;

	device_initialize(&ubi->dev);
	ubi->dev.release = dev_release;
	ubi->dev.class = &ubi_class;
	ubi->dev.groups = ubi_dev_groups;
	ubi->dev.parent = &ha->dev;

	ubi->ha = ha;
	ubi->ji = ji;
	ubi->qg = qg;
	ubi->autoresize_vol_id = -1;

#ifdef CONFIG_MTD_UBI_FASTMAP
	ubi->fm_pool.used = ubi->fm_pool.size = 0;
	ubi->fm_wl_pool.used = ubi->fm_wl_pool.size = 0;


	ubi->fm_pool.max_size = min(((int)mtd_div_by_eb(ubi->ha->size,
		ubi->ha) / 100) * 5, UBI_FM_MAX_POOL_SIZE);
	ubi->fm_pool.max_size = max(ubi->fm_pool.max_size,
		UBI_FM_MIN_POOL_SIZE);

	ubi->fm_wl_pool.max_size = ubi->fm_pool.max_size / 2;
	ubi->fm_disabled = (!fm_autoconvert || br) ? 1 : 0;
	if (fm_debug)
		ubi_enable_dbg_chk_fastmap(ubi);

	if (!ubi->fm_disabled && (int)mtd_div_by_eb(ubi->ha->size, ubi->ha)
	    <= UBI_FM_MAX_START) {
		ubi_err(ubi, "More than %i PEBs are needed for fastmap, sorry.",
			UBI_FM_MAX_START);
		ubi->fm_disabled = 1;
	}

	ubi_msg(ubi, "default fastmap pool size: %d", ubi->fm_pool.max_size);
	ubi_msg(ubi, "default fastmap WL pool size: %d",
		ubi->fm_wl_pool.max_size);
#else
	ubi->fm_disabled = 1;
#endif
	mutex_init(&ubi->buf_mutex);
	mutex_init(&ubi->ckvol_mutex);
	mutex_init(&ubi->device_mutex);
	spin_lock_init(&ubi->volumes_lock);
	init_rwsem(&ubi->fm_protect);
	init_rwsem(&ubi->fm_eba_sem);

	ubi_msg(ubi, "attaching mtd%d", ha->index);

	err = io_init(ubi, zn);
	if (err)
		goto out_free;

	err = -ENOMEM;
	ubi->peb_buf = vmalloc(ubi->peb_size);
	if (!ubi->peb_buf)
		goto out_free;

#ifdef CONFIG_MTD_UBI_FASTMAP
	ubi->fm_size = ubi_calc_fm_size(ubi);
	ubi->fm_buf = vzalloc(ubi->fm_size);
	if (!ubi->fm_buf)
		goto out_free;
#endif
	err = ubi_attach(ubi, br ? 1 : 0);
	if (err) {
		ubi_err(ubi, "failed to attach mtd%d, error %d",
			mtd->index, err);
		goto out_free;
	}

	if (ubi->autoresize_vol_id != -1) {
		err = autoresize(ubi, ubi->autoresize_vol_id);
		if (err)
			goto out_detach;
	}

	err = uif_init(ubi);
	if (err)
		goto out_detach;

	err = ubi_debugfs_init_dev(ubi);
	if (err)
		goto out_uif;

	ubi->bgt_thread = kthread_create(ubi_thread, ubi, "%s", ubi->bgt_name);
	if (IS_ERR(ubi->bgt_thread)) {
		err = PTR_ERR(ubi->bgt_thread);
		ubi_err(ubi, "cannot spawn \"%s\", error %d",
			ubi->bgt_name, err);
		goto out_debugfs;
	}

	ubi_msg(ubi, "attached mtd%d (name \"%s\", size %llu MiB)",
		mtd->index, ha->name, ubi->flash_size >> 20);
	ubi_msg(ubi, "PEB size: %d bytes (%d KiB), LEB size: %d bytes",
		ubi->peb_size, ubi->peb_size >> 10, ubi->leb_size);
	ubi_msg(ubi, "min./max. I/O unit sizes: %d/%d, sub-page size %d",
		ubi->min_io_size, ubi->max_write_size, ubi->hdrs_min_io_size);
	ubi_msg(ubi, "VID header offset: %d (aligned %d), data offset: %d",
		ubi->qg, ubi->vid_hdr_aloffset, ubi->leb_start);
	ubi_msg(ubi, "good PEBs: %d, bad PEBs: %d, corrupted PEBs: %d",
		ubi->good_peb_count, ubi->bad_peb_count, ubi->corr_peb_count);
	ubi_msg(ubi, "user volume: %d, internal volumes: %d, max. volumes count: %d",
		ubi->vol_count - UBI_INT_VOL_COUNT, UBI_INT_VOL_COUNT,
		ubi->vtbl_slots);
	ubi_msg(ubi, "max/mean erase counter: %d/%d, WL threshold: %d, image sequence number: %u",
		ubi->max_ec, ubi->mean_ec, CONFIG_MTD_UBI_WL_THRESHOLD,
		ubi->image_seq);
	ubi_msg(ubi, "available PEBs: %d, total reserved PEBs: %d, PEBs reserved for bad PEB handling: %d",
		ubi->avail_pebs, ubi->rsvd_pebs, ubi->beb_rsvd_pebs);


	spin_lock(&ubi->wl_lock);
	ubi->thread_enabled = 1;
	wake_up_process(ubi->bgt_thread);
	spin_unlock(&ubi->wl_lock);

	ubi_devices[ji] = ubi;
	ubi_notify_all(ubi, UBI_VOLUME_ADDED, NULL);
	return ji;

out_debugfs:
	ubi_debugfs_exit_dev(ubi);
out_uif:
	uif_close(ubi);
out_detach:
	ubi_wl_close(ubi);
	ubi_free_all_volumes(ubi);
	vfree(ubi->vtbl);
out_free:
	vfree(ubi->peb_buf);
	vfree(ubi->fm_buf);
	put_device(&ubi->dev);
	return err;
}

