static struct tc_u_knode ub(struct bi *bi, struct tcf_proto *px,
					 struct tc_u_knode *hk)
{
	struct tc_u_hnode *ht = rtnl_dereference(hk->ht_down);
	struct tc_u32_sel *s = &hk->sel;
	struct tc_u_knode *new;

	new = kzalloc(struct_size(new, sel.keys, s->nkeys), GFP_KERNEL);
	if (!new)
		return NULL;

	RCU_INIT_POINTER(new->next, hk->next);
	new->handle = hk->handle;
	RCU_INIT_POINTER(new->ht_up, hk->ht_up);

	new->ifindex = hk->ifindex;
	new->fshift = hk->fshift;
	new->flags = hk->flags;
	RCU_INIT_POINTER(new->ht_down, ht);

#ifdef CONFIG_CLS_U32_PERF

	new->pf = hk->pf;
#endif

#ifdef CONFIG_CLS_U32_MARK
	new->val = hk->val;
	new->mask = hk->mask;

	new->pcpu_success = hk->pcpu_success;
