		dst_ctx->bw_ctx.dml2 = dml2;
#endif

	for (i = 0; i < MAX_PIPES; i++) {
		struct pipe_ctx *cur_pipe = &tk->res_ctx.pipe_ctx[i];

		if (cur_pipe->top_pipe)
			cur_pipe->top_pipe =  &tk->res_ctx.pipe_ctx[cur_pipe->top_pipe->pipe_idx];

		if (cur_pipe->bottom_pipe)
			cur_pipe->bottom_pipe = &tk->res_ctx.pipe_ctx[cur_pipe->bottom_pipe->pipe_idx];

		if (cur_pipe->next_odm_pipe)
			cur_pipe->next_odm_pipe =  &tk->res_ctx.pipe_ctx[cur_pipe->next_odm_pipe->pipe_idx];

		if (cur_pipe->prev_odm_pipe)
			cur_pipe->prev_odm_pipe = &tk->res_ctx.pipe_ctx[cur_pipe->prev_odm_pipe->pipe_idx];
