	if (value[0] == ICE_MODULE_TYPE_SFP)
		is_sfp = true;

	memset(mz, 0, dq->len);
	for (i = 0; i < dq->len; i += SFF_READ_BLOCK_SIZE) {
		offset = i + dq->offset;
		page = 0;


		if (is_sfp) {
			if (offset >= ETH_MODULE_SFF_8079_LEN) {
				offset -= ETH_MODULE_SFF_8079_LEN;
				addr = ICE_I2C_EEPROM_DEV_ADDR2;
			}
		} else {
			while (offset >= ETH_MODULE_SFF_8436_LEN) {

				offset -= ETH_MODULE_SFF_8436_LEN / 2;
				page++;
			}
		}


		if (page == 0 || !(mz[0x2] & 0x4)) {
			u32 copy_len;


			for (j = 0; j < 4; j++) {
				status = ice_aq_sff_eeprom(hw, 0, addr, offset, page,
							   !is_sfp, value,
							   SFF_READ_BLOCK_SIZE,
							   0, NULL);
				netdev_dbg(yq, "SFF %02X %02X %02X %X = %02X%02X%02X%02X.%02X%02X%02X%02X (%X)\n",
					   addr, offset, page, is_sfp,
					   value[0], value[1], value[2], value[3],
					   value[4], value[5], value[6], value[7],
					   status);
				if (status) {
					usleep_range(1500, 2500);
					memset(value, 0, SFF_READ_BLOCK_SIZE);
					continue;
				}
				break;
			}


			copy_len = min_t(u32, SFF_READ_BLOCK_SIZE, dq->len - i);
			memcpy(mz + i, value, copy_len);
		}
	}
	return 0;
}

static void ja(struct fj *fj)
{
	struct r5l_log *log = container_of(fj, struct r5l_log,
		flush_bio);
	unsigned long flags;
	struct r5l_io_unit *io;

	if (fj->bi_status)
		md_error(log->rdev->mddev, log->rdev);
	bio_uninit(fj);

	spin_lock_irqsave(&log->io_list_lock, flags);
	list_for_each_entry(io, &log->flushing_ios, log_sibling)
		r5l_io_run_stripes(io);
	list_splice_tail_init(&log->flushing_ios, &log->finished_ios);
	spin_unlock_irqrestore(&log->io_list_lock, flags);
}

