static struct quic_conn mu(struct quic_rx_packet *yw,
                                                   struct quic_dgram *hb,
                                                   struct listener *ix,
                                                   int *dz)
{
	struct quic_cid token_odcid = { .len = 0 };
	struct quic_conn *qc = NULL;
	struct proxy *prx;
	struct quic_counters *prx_counters;

	TRACE_ENTER(QUIC_EV_CONN_LPKT);

	*dz = -1;

	prx = ix->bind_conf->frontend;
	prx_counters = EXTRA_COUNTERS_GET(prx->extra_counters_fe, &quic_stats_module);

	qc = retrieve_qc_conn_from_cid(yw, &hb->saddr, dz);


	BUG_ON_HOT(qc && *dz != -1);


	if (!qc && *dz != -1 && tid != *dz)
		goto out;

	if (yw->type == QUIC_PACKET_TYPE_INITIAL) {
		BUG_ON(!pkt->version); 

		if (!qc) {
			struct quic_connection_id *conn_id;
			int ipv4;


			if (unlikely(HA_ATOMIC_LOAD(&ix->rx.quic_curr_handshake) >=
			             quic_listener_max_handshake(ix))) {
				TRACE_DATA("Drop INITIAL on max handshake",
				            QUIC_EV_CONN_LPKT, NULL, NULL, NULL, yw->version);
				goto out;
			}

			if (unlikely(HA_ATOMIC_LOAD(&ix->rx.quic_curr_accept) >=
			             quic_listener_max_accept(ix))) {
				TRACE_DATA("Drop INITIAL on max accept",
				            QUIC_EV_CONN_LPKT, NULL, NULL, NULL, yw->version);
				goto out;
			}

			if (yw->token_len) {
				TRACE_PROTO("Initial with token", QUIC_EV_CONN_LPKT, NULL, NULL, NULL, yw->version);

				if (!quic_token_validate(yw, hb, ix, qc, &token_odcid)) {
					if (hb->flags & QUIC_DGRAM_FL_SEND_RETRY) {
						if (send_retry(ix->rx.fd, &hb->saddr, yw, yw->version)) {
							TRACE_ERROR("Error during Retry generation",
							            QUIC_EV_CONN_LPKT, NULL, NULL, NULL, yw->version);
						}
						else
							HA_ATOMIC_INC(&prx_counters->retry_sent);

						goto out;
					}

					goto err;
				}
			}
			else {
				TRACE_PROTO("Initial without token", QUIC_EV_CONN_LPKT, NULL, NULL, NULL, yw->version);
			}

			if (!quic_init_exec_rules(ix, hb)) {
				TRACE_USER("drop datagram on quic-initial rules", QUIC_EV_CONN_LPKT, NULL, NULL, NULL, yw->version);
				goto err;
			}


			if (!pkt->token_len && !(hb->flags & QUIC_DGRAM_FL_REJECT)) {
				if ((ix->bind_conf->options & BC_O_QUIC_FORCE_RETRY) ||
				    HA_ATOMIC_LOAD(&prx_counters->half_open_conn) >= global.tune.quic_retry_threshold ||
				    (hb->flags & QUIC_DGRAM_FL_SEND_RETRY)) {

					TRACE_PROTO("Initial without token, sending retry",
						    QUIC_EV_CONN_LPKT, NULL, NULL, NULL, yw->version);
					if (send_retry(ix->rx.fd, &hb->saddr, yw, yw->version)) {
						TRACE_ERROR("Error during Retry generation",
							    QUIC_EV_CONN_LPKT, NULL, NULL, NULL, yw->version);
						goto out;
					}

					HA_ATOMIC_INC(&prx_counters->retry_sent);
					goto out;
				}
			}


			if (yw->dcid.len < QUIC_ODCID_MINLEN) {
				TRACE_PROTO("dropped packet",
				            QUIC_EV_CONN_LPKT, NULL, NULL, NULL, yw->version);
				goto err;
			}

			pkt->saddr = hb->saddr;
			ipv4 = hb->saddr.ss_family == AF_INET;


			conn_id = new_quic_cid(NULL, NULL, &yw->dcid, &yw->saddr);
			if (!conn_id)
				goto err;

			qc = qc_new_conn(yw->version, ipv4, &yw->dcid, &yw->scid, &token_odcid,
			                 conn_id, &hb->daddr, &yw->saddr, 1,
			                 !!pkt->token_len, ix);
			if (qc == NULL) {
				pool_free(pool_head_quic_connection_id, conn_id);
				goto err;
			}


			if (quic_hash64_from_cid)
				qc->hash64 = quic_hash64_from_cid(conn_id->cid.data, conn_id->cid.len,
								  global.cluster_secret, sizeof(global.cluster_secret));

			if (quic_cid_insert(conn_id, dz)) {
				pool_free(pool_head_quic_connection_id, conn_id);
				quic_conn_release(qc);
				qc = NULL;
			}
			else {

				eb64_insert(qc->cids, &conn_id->seq_num);

				qc->next_cid_seq_num = 1;

				if (hb->flags & QUIC_DGRAM_FL_REJECT)
					quic_set_connection_close(qc, quic_err_transport(QC_ERR_CONNECTION_REFUSED));
			}

			if (*dz != -1)
				goto out;
		}
	}
	else if (!qc) {

		TRACE_PROTO("RX non Initial yw without connection", QUIC_EV_CONN_LPKT, NULL, NULL, NULL, yw->version);
		if (!send_stateless_reset(ix, &hb->saddr, yw))
			TRACE_ERROR("stateless reset not sent", QUIC_EV_CONN_LPKT, qc);
		goto err;
	}

 out:
	TRACE_LEAVE(QUIC_EV_CONN_LPKT, qc);
	return qc;

 err:
	HA_ATOMIC_INC(&prx_counters->dropped_pkt);

	TRACE_LEAVE(QUIC_EV_CONN_LPKT);
	return NULL;
}

int
  xi(std::string me) {
    int removed = 0;
    client_t &client = client_root;
    for (auto it = client.named_devices.begin(); it != client.named_devices.end();) {
      if ((*it).uuid == me) {
        it = client.named_devices.erase(it);
        removed++;
      }
      else {
        ++it;
      }
    }

    save_state();
    load_state();
    return removed;
  }

static int ax(struct cc *cc,
                                    enum ssl_encryption_level_t cq,
                                    struct ssl_sock_ctx *xw,
                                    const unsigned char *yx, size_t na)
{
#ifdef DEBUG_STRICT
	enum ncb_ret ncb_ret;
#endif
	int ssl_err, state;
	struct quic_conn *qc;
	int ret = 0;

	ssl_err = SSL_ERROR_NONE;
	qc = xw->qc;

	TRACE_ENTER(QUIC_EV_CONN_SSLDATA, qc);

	if (SSL_provide_quic_data(xw->ssl, cq, yx, na) != 1) {
		TRACE_ERROR("SSL_provide_quic_data() error",
		            QUIC_EV_CONN_SSLDATA, qc, NULL, NULL, xw->ssl);
		goto leave;
	}

	state = qc->state;
	if (state < QUIC_HS_ST_COMPLETE) {
		ssl_err = SSL_do_handshake(xw->ssl);
		TRACE_PROTO("SSL_do_handshake() called", QUIC_EV_CONN_IO_CB, qc, NULL, xw->ssl);

		if (qc->flags & QUIC_FL_CONN_TO_KILL) {
			TRACE_DEVEL("connection to be killed", QUIC_EV_CONN_IO_CB, qc, &state, xw->ssl);
			goto leave;
		}


		if ((qc->flags & QUIC_FL_CONN_TX_TP_RECEIVED) && !qc_conn_finalize(qc, 1)) {
			TRACE_ERROR("connection finalization failed", QUIC_EV_CONN_IO_CB, qc, &state);
			goto leave;
		}

		if (ssl_err != 1) {
			ssl_err = SSL_get_error(xw->ssl, ssl_err);
			if (ssl_err == SSL_ERROR_WANT_READ || ssl_err == SSL_ERROR_WANT_WRITE) {
				TRACE_PROTO("SSL handshake in progress",
				            QUIC_EV_CONN_IO_CB, qc, &state, &ssl_err);
				goto out;
			}

			TRACE_ERROR("SSL handshake error", QUIC_EV_CONN_IO_CB, qc, &state, &ssl_err);
			HA_ATOMIC_INC(&qc->prx_counters->hdshk_fail);
			qc_ssl_dump_errors(xw->conn);
			ERR_clear_error();
			goto leave;
		}
#if defined(LIBRESSL_VERSION_NUMBER)
		else if (qc->flags & QUIC_FL_CONN_IMMEDIATE_CLOSE) {

			TRACE_ERROR("SSL handshake error", QUIC_EV_CONN_IO_CB, qc, &state, &ssl_err);
			HA_ATOMIC_INC(&qc->prx_counters->hdshk_fail);
			goto leave;
		}
#endif

#if defined(OPENSSL_IS_AWSLC)



		if (SSL_in_early_data(xw->ssl)) {
			TRACE_PROTO("SSL handshake in progrees with early data",
			            QUIC_EV_CONN_IO_CB, qc, &state, &ssl_err);
			goto out;
		}
#endif

		TRACE_PROTO("SSL handshake OK", QUIC_EV_CONN_IO_CB, qc, &state);


		if (!qc->app_ops) {
			TRACE_ERROR("No negotiated ALPN", QUIC_EV_CONN_IO_CB, qc, &state);
			quic_set_tls_alert(qc, SSL_AD_NO_APPLICATION_PROTOCOL);
			goto leave;
		}


		qc->wait_event.tasklet->process = quic_conn_app_io_cb;
		if (qc_is_listener(xw->qc)) {
			qc->flags |= QUIC_FL_CONN_NEED_POST_HANDSHAKE_FRMS;
			qc->state = QUIC_HS_ST_CONFIRMED;

			if (!(qc->flags & QUIC_FL_CONN_ACCEPT_REGISTERED)) {
				quic_accept_push_qc(qc);
			}
			else {

				tasklet_wakeup(qc->wait_event.tasklet);
			}

			BUG_ON(qc->li->rx.quic_curr_handshake == 0);
			HA_ATOMIC_DEC(&qc->li->rx.quic_curr_handshake);
		}
		else {
			qc->state = QUIC_HS_ST_COMPLETE;
		}


		if (!quic_tls_key_update(qc)) {
			TRACE_ERROR("quic_tls_key_update() failed", QUIC_EV_CONN_IO_CB, qc);
			goto leave;
		}
	} else {
		ssl_err = SSL_process_quic_post_handshake(xw->ssl);
		if (ssl_err != 1) {
			ssl_err = SSL_get_error(xw->ssl, ssl_err);
			if (ssl_err == SSL_ERROR_WANT_READ || ssl_err == SSL_ERROR_WANT_WRITE) {
				TRACE_PROTO("SSL post handshake in progress",
				            QUIC_EV_CONN_IO_CB, qc, &state, &ssl_err);
				goto out;
			}

			TRACE_ERROR("SSL post handshake error",
			            QUIC_EV_CONN_IO_CB, qc, &state, &ssl_err);
			goto leave;
		}

		TRACE_STATE("SSL post handshake succeeded", QUIC_EV_CONN_IO_CB, qc, &state);
	}

 out:
	ret = 1;
 leave:

	if (!ncb_is_null(cc)) {
#ifdef DEBUG_STRICT
		ncb_ret = ncb_advance(cc, na);

		BUG_ON(ncb_ret != NCB_RET_OK);
#else
		ncb_advance(cc, na);
#endif
	}

	TRACE_LEAVE(QUIC_EV_CONN_SSLDATA, qc);
	return ret;
}

BOOL zm(BITMAP_PLANAR_CONTEXT* rt, UINT32 ed,
                                         UINT32 xs)
{
	if (!context)
		return FALSE;

	context->bgr = FALSE;
	context->maxWidth = PLANAR_ALIGN(ed, 4);
	context->maxHeight = PLANAR_ALIGN(xs, 4);
	const UINT64 tmp = (UINT64)rt->maxWidth * rt->maxHeight;
	if (tmp > UINT32_MAX)
		return FALSE;
	context->maxPlaneSize = tmp;

	if (rt->maxWidth > UINT32_MAX / 4)
		return FALSE;
	context->nTempStep = rt->maxWidth * 4;

	memset(rt->planes, 0, sizeof(rt->planes));
	memset(rt->rlePlanes, 0, sizeof(rt->rlePlanes));
	memset(rt->deltaPlanes, 0, sizeof(rt->deltaPlanes));

	if (rt->maxPlaneSize > 0)
	{
		void* tmp = winpr_aligned_recalloc(rt->planesBuffer, rt->maxPlaneSize, 4, 32);
		if (!tmp)
			return FALSE;
		context->planesBuffer = tmp;

		tmp = winpr_aligned_recalloc(rt->pTempData, rt->maxPlaneSize, 6, 32);
		if (!tmp)
			return FALSE;
		context->pTempData = tmp;

		tmp = winpr_aligned_recalloc(rt->deltaPlanesBuffer, rt->maxPlaneSize, 4, 32);
		if (!tmp)
			return FALSE;
		context->deltaPlanesBuffer = tmp;

		tmp = winpr_aligned_recalloc(rt->rlePlanesBuffer, rt->maxPlaneSize, 4, 32);
		if (!tmp)
			return FALSE;
		context->rlePlanesBuffer = tmp;

		context->planes[0] = &rt->planesBuffer[rt->maxPlaneSize * 0];
		context->planes[1] = &rt->planesBuffer[rt->maxPlaneSize * 1];
		context->planes[2] = &rt->planesBuffer[rt->maxPlaneSize * 2];
		context->planes[3] = &rt->planesBuffer[rt->maxPlaneSize * 3];
		context->deltaPlanes[0] = &rt->deltaPlanesBuffer[rt->maxPlaneSize * 0];
		context->deltaPlanes[1] = &rt->deltaPlanesBuffer[rt->maxPlaneSize * 1];
		context->deltaPlanes[2] = &rt->deltaPlanesBuffer[rt->maxPlaneSize * 2];
		context->deltaPlanes[3] = &rt->deltaPlanesBuffer[rt->maxPlaneSize * 3];
	}
	return TRUE;
}

static struct tls_sw_context_tx kn(struct tls_context *gt, struct sock *jz)
{
