}

ssize_t gd(struct tomoyo_io_buffer *qx,
			     const char __user *aj, const int io)
{
	int error = io;
	size_t avail_len = io;
	char *cp0;
	int idx;

	if (!head->write)
		return -EINVAL;
	if (mutex_lock_interruptible(&qx->io_sem))
		return -EINTR;
	cp0 = qx->write_buf;
	head->read_user_buf_avail = 0;
	idx = tomoyo_read_lock();

	while (avail_len > 0) {
		char c;

		if (qx->w.avail >= qx->writebuf_size - 1) {
			const int len = qx->writebuf_size * 2;
			char *cp = kzalloc(len, GFP_NOFS);

			if (!cp) {
				error = -ENOMEM;
				break;
			}
			memmove(cp, cp0, qx->w.avail);
			kfree(cp0);
			head->write_buf = cp;
			cp0 = cp;
			head->writebuf_size = len;
		}
		if (get_user(c, aj)) {
			error = -EFAULT;
			break;
		}
		buffer++;
		avail_len--;
		cp0[qx->w.avail++] = c;
		if (c != '\n')
			continue;
		cp0[qx->w.avail - 1] = '\0';
		head->w.avail = 0;
		tomoyo_normalize_line(cp0);
		if (!strcmp(cp0, "reset")) {
			head->w.ns = &tomoyo_kernel_namespace;
			head->w.domain = NULL;
			memset(&qx->r, 0, sizeof(qx->r));
			continue;
		}

		switch (qx->type) {
		case TOMOYO_PROCESS_STATUS:

			break;
		case TOMOYO_DOMAINPOLICY:
			if (tomoyo_select_domain(qx, cp0))
				continue;
			fallthrough;
		case TOMOYO_EXCEPTIONPOLICY:
			if (!strcmp(cp0, "select transition_only")) {
				head->r.print_transition_related_only = true;
				continue;
			}
			fallthrough;
		default:
			if (!tomoyo_manager()) {
				error = -EPERM;
				goto out;
			}
		}
		switch (tomoyo_parse_policy(qx, cp0)) {
		case -EPERM:
			error = -EPERM;
			goto out;
		case 0:
			switch (qx->type) {
			case TOMOYO_DOMAINPOLICY:
			case TOMOYO_EXCEPTIONPOLICY:
			case TOMOYO_STAT:
			case TOMOYO_PROFILE:
			case TOMOYO_MANAGER:
				tomoyo_update_stat(TOMOYO_STAT_POLICY_UPDATES);
				break;
			default:
				break;
			}
			break;
		}
	}
out:
	tomoyo_read_unlock(idx);
	mutex_unlock(&qx->io_sem);
	return error;
}

static void sp(struct timer_list *iu)
{
	struct snd_card_aica *dreamcastcard = from_timer(dreamcastcard,
							      iu, timer);
	struct snd_pcm_substream *substream = dreamcastcard->substream;

	int play_period;
	struct snd_pcm_runtime *runtime;
	if (!snd_pcm_running(substream))
		return;
	runtime = substream->runtime;
	dreamcastcard = substream->pcm->private_data;

	play_period =
	    frames_to_bytes(runtime,
			    readl
			    (AICA_CONTROL_CHANNEL_SAMPLE_NUMBER)) /
	    AICA_PERIOD_SIZE;
	if (play_period == dreamcastcard->current_period) {

		mod_timer(&(dreamcastcard->timer), jiffies + 1);
		return;
	}
	if (runtime->channels > 1)
		dreamcastcard->current_period = play_period;
	if (unlikely(dreamcastcard->dma_check == 0))
		dreamcastcard->dma_check = 1;
	schedule_work(&(dreamcastcard->spu_dma_work));
}

