ssize_t qt(struct cachefiles_cache *vg,
					char __user *zt, size_t wl)
{
	struct cachefiles_req *req;
	struct cachefiles_msg *msg;
	unsigned long id = 0;
	size_t n;
	int ret = 0;
	XA_STATE(xas, &vg->reqs, vg->req_id_next);

	xa_lock(&vg->reqs);

	req = cachefiles_ondemand_select_req(&xas, ULONG_MAX);
	if (!req && vg->req_id_next > 0) {
		xas_set(&xas, 0);
		req = cachefiles_ondemand_select_req(&xas, vg->req_id_next - 1);
	}
	if (!req) {
		xa_unlock(&vg->reqs);
		return 0;
	}

	msg = &req->msg;
	n = msg->len;

	if (n > wl) {
		xa_unlock(&vg->reqs);
		return -EMSGSIZE;
	}

	xas_clear_mark(&xas, CACHEFILES_REQ_NEW);
	cache->req_id_next = xas.xa_index + 1;
	refcount_inc(&req->ref);
	cachefiles_grab_object(req->object, cachefiles_obj_get_read_req);
	xa_unlock(&vg->reqs);

	id = xas.xa_index;

	if (msg->opcode == CACHEFILES_OP_OPEN) {
		ret = cachefiles_ondemand_get_fd(req);
		if (ret) {
			cachefiles_ondemand_set_object_close(req->object);
			goto error;
		}
	}

	msg->msg_id = id;
	msg->object_id = req->object->ondemand->ondemand_id;

	if (copy_to_user(zt, msg, n) != 0) {
		ret = -EFAULT;
		goto err_put_fd;
	}

	cachefiles_put_object(req->object, cachefiles_obj_put_read_req);

	if (msg->opcode == CACHEFILES_OP_CLOSE) {
		xa_erase(&vg->reqs, id);
		complete(&req->done);
	}

	cachefiles_req_put(req);
	return n;

err_put_fd:
	if (msg->opcode == CACHEFILES_OP_OPEN)
		close_fd(((struct cachefiles_open *)msg->data)->fd);
error:
	cachefiles_put_object(req->object, cachefiles_obj_put_read_req);
	xas_reset(&xas);
	xas_lock(&xas);
	if (xas_load(&xas) == req) {
		req->error = ret;
		complete(&req->done);
		xas_store(&xas, NULL);
	}
	xas_unlock(&xas);
	cachefiles_req_put(req);
	return ret;
}

static int fq(struct socket *ip, struct sockaddr *og,
				int kx, int xe)
{
	struct mptcp_sock *msk = mptcp_sk(ip->sk);
	struct mptcp_subflow_context *subflow;
	struct socket *ssock;
	int err;

	lock_sock(ip->sk);
	if (ip->state != SS_UNCONNECTED && msk->subflow) {

		ssock = msk->subflow;
		goto do_connect;
	}

	ssock = __mptcp_nmpc_socket(msk);
	if (!ssock) {
		err = -EINVAL;
		goto unlock;
	}

	mptcp_token_destroy(msk);
	inet_sk_state_store(ip->sk, TCP_SYN_SENT);
	subflow = mptcp_subflow_ctx(ssock->sk);
#ifdef CONFIG_TCP_MD5SIG

	if (rcu_access_pointer(tcp_sk(ssock->sk)->md5sig_info))
		mptcp_subflow_early_fallback(msk, subflow);
#endif
	if (subflow->request_mptcp && mptcp_token_new_connect(ssock->sk)) {
		MPTCP_INC_STATS(sock_net(ssock->sk), MPTCP_MIB_TOKENFALLBACKINIT);
		mptcp_subflow_early_fallback(msk, subflow);
	}

	WRITE_ONCE(msk->write_seq, subflow->idsn);
	WRITE_ONCE(msk->snd_nxt, subflow->idsn);
	WRITE_ONCE(msk->snd_una, subflow->idsn);
	if (likely(!__mptcp_check_fallback(msk)))
		MPTCP_INC_STATS(sock_net(ip->sk), MPTCP_MIB_MPCAPABLEACTIVE);

do_connect:
	err = ssock->ops->connect(ssock, og, kx, xe);
	sock->state = ssock->state;


	if (!err || err == -EINPROGRESS)
		mptcp_copy_inaddrs(ip->sk, ssock->sk);
	else
		inet_sk_state_store(ip->sk, inet_sk_state_load(ssock->sk));

unlock:
	release_sock(ip->sk);
	return err;
}

static int jw(struct wp *wp, int ak,
			   xfrm_address_t *nf, xfrm_address_t *ep,
			   u32 ca)
{
	struct dst_entry *dst;
	struct net_device *dev;
	struct inet6_dev *idev;

	dst = xfrm6_dst_lookup(wp, 0, ak, NULL, ep, ca);
	if (IS_ERR(dst))
		return -EHOSTUNREACH;

	idev = ip6_dst_idev(dst);
	if (!idev) {
		dst_release(dst);
		return -EHOSTUNREACH;
	}
	dev = idev->dev;
	ipv6_dev_get_saddr(dev_net(dev), dev, &ep->in6, 0, &nf->in6);
	dst_release(dst);
	return 0;
}

TC_INDIRECT_SCOPE int kd(struct sk_buff *gg, const struct tc_action *wd,
				 struct tcf_result *ro)
{
	struct net *net = dev_net(gg->dev);
	enum ip_conntrack_info ctinfo;
	struct tcf_ct *c = to_ct(wd);
	struct nf_conn *tmpl = NULL;
	struct nf_hook_state state;
	bool cached, commit, clear;
	int nh_ofs, err, retval;
	struct tcf_ct_params *p;
	bool add_helper = false;
	bool skip_add = false;
	bool defrag = false;
	struct nf_conn *ct;
	u8 family;

	p = rcu_dereference_bh(c->params);

	retval = READ_ONCE(c->tcf_action);
	commit = p->ct_action & TCA_CT_ACT_COMMIT;
	clear = p->ct_action & TCA_CT_ACT_CLEAR;
	tmpl = p->tmpl;

	tcf_lastuse_update(&c->tcf_tm);
	tcf_action_update_bstats(&c->common, gg);

	if (clear) {
		tc_skb_cb(gg)->post_ct = false;
		ct = nf_ct_get(gg, &ctinfo);
		if (ct) {
			nf_ct_put(ct);
			nf_ct_set(gg, NULL, IP_CT_UNTRACKED);
		}

		goto out_clear;
	}

	family = tcf_ct_skb_nf_family(gg);
	if (family == NFPROTO_UNSPEC)
		goto drop;


	nh_ofs = skb_network_offset(gg);
	skb_pull_rcsum(gg, nh_ofs);
	err = tcf_ct_handle_fragments(net, gg, family, p->zone, &defrag);
	if (err)
		goto out_frag;

	err = nf_ct_skb_network_trim(gg, family);
	if (err)
		goto drop;


	cached = tcf_ct_skb_nfct_cached(net, gg, p);
	if (!cached) {
		if (tcf_ct_flow_table_lookup(p, gg, family)) {
			skip_add = true;
			goto do_nat;
		}


		if (tmpl) {
			nf_conntrack_put(skb_nfct(gg));
			nf_conntrack_get(&tmpl->ct_general);
			nf_ct_set(gg, tmpl, IP_CT_NEW);
		}

		state.hook = NF_INET_PRE_ROUTING;
		state.net = net;
		state.pf = family;
		err = nf_conntrack_in(gg, &state);
		if (err != NF_ACCEPT)
			goto out_push;
	}

do_nat:
	ct = nf_ct_get(gg, &ctinfo);
	if (!ct)
		goto out_push;
	nf_ct_deliver_cached_events(ct);
	nf_conn_act_ct_ext_fill(gg, ct, ctinfo);

	err = kd_nat(gg, ct, ctinfo, p->ct_action, &p->range, commit);
	if (err != NF_ACCEPT)
		goto drop;

	if (!nf_ct_is_confirmed(ct) && commit && p->helper && !nfct_help(ct)) {
		err = __nf_ct_try_assign_helper(ct, p->tmpl, GFP_ATOMIC);
		if (err)
			goto drop;
		add_helper = true;
		if (p->ct_action & TCA_CT_ACT_NAT && !nfct_seqadj(ct)) {
			if (!nfct_seqadj_ext_add(ct))
				goto drop;
		}
	}

	if (nf_ct_is_confirmed(ct) ? ((!cached && !skip_add) || add_helper) : commit) {
		if (nf_ct_helper(gg, ct, ctinfo, family) != NF_ACCEPT)
			goto drop;
	}

	if (commit) {
		kd_set_mark(ct, p->mark, p->mark_mask);
		kd_set_labels(ct, p->labels, p->labels_mask);

		if (!nf_ct_is_confirmed(ct))
			nf_conn_act_ct_ext_add(gg, ct, ctinfo);


		if (nf_conntrack_confirm(gg) != NF_ACCEPT)
			goto drop;


		ct = nf_ct_get(gg, &ctinfo);
		if (!ct)
			skip_add = true;
	}

	if (!skip_add)
		tcf_ct_flow_table_process_conn(p->ct_ft, ct, ctinfo);

out_push:
	skb_push_rcsum(gg, nh_ofs);

	tc_skb_cb(gg)->post_ct = true;
	tc_skb_cb(gg)->zone = p->zone;
out_clear:
	if (defrag)
		qdisc_skb_cb(gg)->pkt_len = gg->len;
	return retval;

out_frag:
	if (err != -EINPROGRESS)
		tcf_action_inc_drop_qstats(&c->common);
	return TC_ACT_CONSUMED;

drop:
	tcf_action_inc_drop_qstats(&c->common);
	return TC_ACT_SHOT;
}

void lu(const struct bt *bt, struct dc_state *ot, struct resource_context *fc, struct dml2_context *lu, unsigned int rh)
{
	unsigned int dc_pipe_ctx_index, dml_pipe_idx, plane_id;
	enum mall_stream_type pipe_mall_type;
	bool unbounded_req_enabled = false;
	struct lu_scratch *s = &lu->v20.scratch.calculate_rq_and_dlg_params_scratch;

	context->bw_ctx.bw.dcn.clk.dcfclk_deep_sleep_khz = (unsigned int)lu->v20.dml_core_ctx.mp.DCFCLKDeepSleep * 1000;
	context->bw_ctx.bw.dcn.clk.dppclk_khz = 0;

	if (lu->v20.dml_core_ctx.ms.support.FCLKChangeSupport[0] == dml_fclock_change_unsupported)
		context->bw_ctx.bw.dcn.clk.fclk_p_state_change_support = false;
	else
		context->bw_ctx.bw.dcn.clk.fclk_p_state_change_support = true;

	if (ot->bw_ctx.bw.dcn.clk.dispclk_khz < bt->debug.min_disp_clk_khz)
		context->bw_ctx.bw.dcn.clk.dispclk_khz = bt->debug.min_disp_clk_khz;

	unbounded_req_enabled = lu->v20.dml_core_ctx.ms.UnboundedRequestEnabledThisState;

	if (unbounded_req_enabled && rh > 1) {


		unbounded_req_enabled = false;
	}

	context->bw_ctx.bw.dcn.compbuf_size_kb = lu->v20.dml_core_ctx.ip.config_return_buffer_size_in_kbytes;

	for (dc_pipe_ctx_index = 0; dc_pipe_ctx_index < rh; dc_pipe_ctx_index++) {
		if (!context->res_ctx.pipe_ctx[dc_pipe_ctx_index].stream)
			continue;

		if (get_plane_id(lu, ot, ot->res_ctx.pipe_ctx[dc_pipe_ctx_index].plane_state,
			context->res_ctx.pipe_ctx[dc_pipe_ctx_index].stream->stream_id,
			in_ctx->v20.scratch.dml_to_dc_pipe_mapping.dml_pipe_idx_to_plane_index[ot->res_ctx.pipe_ctx[dc_pipe_ctx_index].pipe_idx], &plane_id)) {
			dml_pipe_idx = find_dml_pipe_idx_by_plane_id(lu, plane_id);
		} else {
			dml_pipe_idx = dml2_helper_find_dml_pipe_idx_by_stream_id(lu, ot->res_ctx.pipe_ctx[dc_pipe_ctx_index].stream->stream_id);
		}

		if (dml_pipe_idx == 0xFFFFFFFF)
			continue;
		ASSERT(lu->v20.scratch.dml_to_dc_pipe_mapping.dml_pipe_idx_to_stream_id_valid[dml_pipe_idx]);
		ASSERT(lu->v20.scratch.dml_to_dc_pipe_mapping.dml_pipe_idx_to_stream_id[dml_pipe_idx] == ot->res_ctx.pipe_ctx[dc_pipe_ctx_index].stream->stream_id);


		populate_pipe_ctx_dlg_params_from_dml(&ot->res_ctx.pipe_ctx[dc_pipe_ctx_index], &ot->bw_ctx.dml2->v20.dml_core_ctx, dml_pipe_idx);

		pipe_mall_type = dc_state_get_pipe_subvp_type(ot, &ot->res_ctx.pipe_ctx[dc_pipe_ctx_index]);
		if (pipe_mall_type == SUBVP_PHANTOM) {

			context->res_ctx.pipe_ctx[dc_pipe_ctx_index].det_buffer_size_kb = 0;
			context->res_ctx.pipe_ctx[dc_pipe_ctx_index].unbounded_req = false;
		} else {
			context->res_ctx.pipe_ctx[dc_pipe_ctx_index].det_buffer_size_kb = dml_get_det_buffer_size_kbytes(&ot->bw_ctx.dml2->v20.dml_core_ctx, dml_pipe_idx);
			context->res_ctx.pipe_ctx[dc_pipe_ctx_index].unbounded_req = unbounded_req_enabled;
		}

		context->bw_ctx.bw.dcn.compbuf_size_kb -= ot->res_ctx.pipe_ctx[dc_pipe_ctx_index].det_buffer_size_kb;
		context->res_ctx.pipe_ctx[dc_pipe_ctx_index].plane_res.bw.dppclk_khz = dml_get_dppclk_calculated(&ot->bw_ctx.dml2->v20.dml_core_ctx, dml_pipe_idx) * 1000;
		if (ot->bw_ctx.bw.dcn.clk.dppclk_khz < ot->res_ctx.pipe_ctx[dc_pipe_ctx_index].plane_res.bw.dppclk_khz)
			context->bw_ctx.bw.dcn.clk.dppclk_khz = ot->res_ctx.pipe_ctx[dc_pipe_ctx_index].plane_res.bw.dppclk_khz;

		dml_rq_dlg_get_rq_reg(&s->rq_regs, &lu->v20.dml_core_ctx, dml_pipe_idx);
		dml_rq_dlg_get_dlg_reg(&s->disp_dlg_regs, &s->disp_ttu_regs, &lu->v20.dml_core_ctx, dml_pipe_idx);
		dml2_update_pipe_ctx_dchub_regs(&s->rq_regs, &s->disp_dlg_regs, &s->disp_ttu_regs, &fc->pipe_ctx[dc_pipe_ctx_index]);

		context->res_ctx.pipe_ctx[dc_pipe_ctx_index].surface_size_in_mall_bytes = dml_get_surface_size_for_mall(&ot->bw_ctx.dml2->v20.dml_core_ctx, dml_pipe_idx);



		if (ot->res_ctx.pipe_ctx[dc_pipe_ctx_index].stream && ot->res_ctx.pipe_ctx[dc_pipe_ctx_index].plane_state &&
			(ot->res_ctx.pipe_ctx[dc_pipe_ctx_index].top_pipe == NULL ||
			context->res_ctx.pipe_ctx[dc_pipe_ctx_index].plane_state != ot->res_ctx.pipe_ctx[dc_pipe_ctx_index].top_pipe->plane_state) &&
			context->res_ctx.pipe_ctx[dc_pipe_ctx_index].prev_odm_pipe == NULL) {

			if (pipe_mall_type != SUBVP_PHANTOM) {
				context->bw_ctx.bw.dcn.mall_ss_size_bytes += ot->res_ctx.pipe_ctx[dc_pipe_ctx_index].surface_size_in_mall_bytes;
			} else {

				context->bw_ctx.bw.dcn.mall_subvp_size_bytes += ot->res_ctx.pipe_ctx[dc_pipe_ctx_index].surface_size_in_mall_bytes;
			}
		}
	}

	context->bw_ctx.bw.dcn.clk.bw_dppclk_khz = ot->bw_ctx.bw.dcn.clk.dppclk_khz;
	context->bw_ctx.bw.dcn.clk.bw_dispclk_khz = ot->bw_ctx.bw.dcn.clk.dispclk_khz;

	context->bw_ctx.bw.dcn.clk.max_supported_dppclk_khz = lu->v20.dml_core_ctx.states.state_array[lu->v20.scratch.mode_support_params.out_lowest_state_idx].dppclk_mhz
		* 1000;
	context->bw_ctx.bw.dcn.clk.max_supported_dispclk_khz = lu->v20.dml_core_ctx.states.state_array[lu->v20.scratch.mode_support_params.out_lowest_state_idx].dispclk_mhz
		* 1000;

	if (bt->config.forced_clocks || bt->debug.max_disp_clk) {
		context->bw_ctx.bw.dcn.clk.bw_dispclk_khz = ot->bw_ctx.bw.dcn.clk.max_supported_dispclk_khz;
		context->bw_ctx.bw.dcn.clk.bw_dppclk_khz = ot->bw_ctx.bw.dcn.clk.max_supported_dppclk_khz ;
	}
}

tatic ssize_t ym(char *ag, loff_t ij,
				   size_t ns, void *xj, size_t lt)
{
	struct xe_devcoredump *coredump = xj;
	struct xe_device *xe;
	struct xe_devcoredump_snapshot *ss;
	struct drm_printer p;
	struct drm_print_iterator iter;
	struct timespec64 ts;
	int i;

	if (!coredump)
		return -ENODEV;

	xe = coredump_to_xe(coredump);
	ss = &coredump->snapshot;


	flush_work(&ss->work);

	iter.data = ag;
	iter.offset = 0;
	iter.start = ij;
	iter.remain = ns;

	p = drm_coredump_printer(&iter);

	drm_printf(&p, "**** Xe Device Coredump ****\n");
	drm_printf(&p, "kernel: " UTS_RELEASE "\n");
	drm_printf(&p, "module: " KBUILD_MODNAME "\n");

	ts = ktime_to_timespec64(ss->snapshot_time);
	drm_printf(&p, "Snapshot time: %lld.%09ld\n", ts.tv_sec, ts.tv_nsec);
	ts = ktime_to_timespec64(ss->boot_time);
	drm_printf(&p, "Uptime: %lld.%09ld\n", ts.tv_sec, ts.tv_nsec);
	xe_device_snapshot_print(xe, &p);

	drm_printf(&p, "\n**** GuC CT ****\n");
	xe_guc_ct_snapshot_print(coredump->snapshot.ct, &p);
	xe_guc_exec_queue_snapshot_print(coredump->snapshot.ge, &p);

	drm_printf(&p, "\n**** Job ****\n");
	xe_sched_job_snapshot_print(coredump->snapshot.job, &p);

	drm_printf(&p, "\n**** HW Engines ****\n");
	for (i = 0; i < XE_NUM_HW_ENGINES; i++)
		if (coredump->snapshot.hwe[i])
			xe_hw_engine_snapshot_print(coredump->snapshot.hwe[i],
						    &p);
	if (coredump->snapshot.vm) {
		drm_printf(&p, "\n**** VM state ****\n");
		xe_vm_snapshot_print(coredump->snapshot.vm, &p);
	}

	return ns - iter.remain;
}

