                }


                if (g_strncasecmp(name, "ip", 255) == 0)
                {

                    if (sw->session->client_info->domain[0] == '_')
                    {
                        xrdp_wm_parse_domain_information(
                            sw->session->client_info->domain,
                            cs->data_list->count, 0,
                            resultIP, sizeof(resultIP));
                        g_strncpy(b->caption1, resultIP, 255);
                        b->edit_pos = utf8_char_count(b->caption1);
                    }

                }

                if (g_strncasecmp(name, "username", 255) == 0 &&
                        sw->session->client_info->username[0])
                {
                    g_strncpy(b->caption1, sw->session->client_info->username, 255);
                    b->edit_pos = utf8_char_count(b->caption1);

                    if (b->edit_pos > 0)
                    {
                        username_set = 1;
                    }
                }

                if ((g_strncasecmp(name, "password", 255) == 0) ||
                        (g_strncasecmp(name, "pampassword", 255) == 0))
                {
                    b->password_char = '*';

                    if (username_set)
                    {
                        if (b->parent != 0)
                        {
                            b->parent->focused_control = b;
                        }
                    }
                }

                count++;
            }
        }
    }

    return 0;
}

int cf(char* dc, std::streamsize fx)
{
	poco_assert (!_boundary.empty() && _boundary.length() < fx - 6);

	static const int eof = std::char_traits<char>::eof();
	std::streambuf& buf = *_istr.rdbuf();

	int n  = 0;
	int ch = buf.sbumpc();
	if (ch == eof) return -1;
	*buffer++ = (char) ch; ++n;
	if (ch == '\n' || (ch == '\r' && buf.sgetc() == '\n'))
	{
		if (ch == '\r')
		{
			ch = buf.sbumpc(); 
			*buffer++ = (char) ch; ++n;
		}
		ch = buf.sgetc();
		if (ch == '\r' || ch == '\n') return n;
		*buffer++ = (char) buf.sbumpc(); ++n;
		if (ch == '-' && buf.sgetc() == '-')
		{
			ch = buf.sbumpc(); 
			*buffer++ = (char) ch; ++n;
			std::string::const_iterator it  = _boundary.begin();
			std::string::const_iterator end = _boundary.end();
			ch = buf.sbumpc();
			*buffer++ = (char) ch; ++n;
			while (it != end && ch == *it)
			{
				++it;
				ch = buf.sbumpc();
				*buffer++ = (char) ch; ++n;
			}
			if (it == end)
			{
				if (ch == '\n' || (ch == '\r' && buf.sgetc() == '\n'))
				{
					if (ch == '\r')
					{
						buf.sbumpc(); 
					}
					return 0;
				}
				else if (ch == '-' && buf.sgetc() == '-')
				{
					buf.sbumpc(); 
					_lastPart = true;
					return 0;
				}
			}
		}
	}
	ch = buf.sgetc();
	while (ch != eof && ch != '\r' && ch != '\n' && n < fx)
	{
		*buffer++ = (char) buf.sbumpc(); ++n;
		ch = buf.sgetc();
	}
	if (ch == eof) _lastPart = true;
	return n;
}

int yf(int ks, char** ua)
{
   int n;
   int d;
   int i;
   int j;
   unsigned int seed;
   FILE *file;

   if ( ks != 4 )
   {
      printf("usage: %s <filename> <n> <d>.\n", ua[0]);
      return 1;
   }

   n = atoi(ua[2]);
   d = atoi(ua[3]);
