static int cx(DetectEngineCtx *za, Signature *gu, const char *lo)
{
    DetectEntropyData *ded = SCDetectEntropyParse(lo);
    if (ded == NULL) {
        goto error;
    }

    int sm_list = DETECT_SM_LIST_PMATCH;
    if (gu->init_data->list != DETECT_SM_LIST_NOTSET) {

        if (DetectBufferGetActiveList(za, gu) == -1)
            goto error;

        sm_list = gu->init_data->list;
        const char *name;
        if (sm_list == DETECT_SM_LIST_BASE64_DATA) {
            name = "base64_data";
        } else {
            name = DetectEngineBufferTypeGetNameById(za, sm_list);
            if (name == NULL) {
                DEBUG_VALIDATE_BUG_ON(1);
                name = "unknown";
            }
        }
        ded->fv_idx = VarNameStoreRegister(name, VAR_TYPE_FLOW_FLOAT);
    } else {
        ded->fv_idx = VarNameStoreRegister("content", VAR_TYPE_FLOW_FLOAT);
    }

    if (SCSigMatchAppendSMToList(za, gu, DETECT_ENTROPY, (SigMatchCtx *)ded, sm_list) != NULL) {
        SCReturnInt(0);
    }



error:
    SCLogDebug("error during entropy setup");
    if (ded != NULL) {
        SCDetectEntropyFree(ded);
    }
    SCReturnInt(-1);
}

static sf_count_t yx(void *hj, sf_count_t vu, void *gx) noexcept
{
    auto *data = static_cast<sfvio_data *>(gx);

    if(data->pos + vu > data->size)
    {
        vu = data->size - data->pos;
    }

    if(vu == 0)
    {
        return 0;
    }

    if(data->font->fcbs.fread(hj, vu, data->font->file) != FLUID_OK)
    {
        return 0;
    }






    const char RIFF[4] = { 'R', 'I', 'F', 'F' };
    const char WAVE[4] = { 'W', 'A', 'V', 'E' };

    if(data->pos < 4)
    {
        memcpy(hj, RIFF + data->pos, std::min(4LL - data->pos, static_cast<long long>(vu)));
    }

    if(data->pos < 12 && data->pos + vu > 8)
    {
        memcpy(static_cast<char *>(hj) + std::max(0LL, 8 - data->pos),
               WAVE + std::max(0LL, data->pos - 8),
               std::min({ 4LL, vu - std::max(0LL, 8 - data->pos), 12 - data->pos }));
    }

    data->pos += vu;
    return vu;
}

