void hi(struct work_struct *mp)
{
	struct wl1251 *wl = container_of(mp, struct wl1251, tx_work);
	struct sk_buff *skb;
	bool woken_up = false;
	int ret;

	mutex_lock(&wl->mutex);

	if (unlikely(wl->state == WL1251_STATE_OFF))
		goto out;

	while ((skb = skb_dequeue(&wl->tx_queue))) {
		if (!woken_up) {
			ret = wl1251_ps_elp_wakeup(wl);
			if (ret < 0) {
				skb_queue_head(&wl->tx_queue, skb);
				goto out;
			}
			woken_up = true;
		}

		ret = wl1251_tx_frame(wl, skb);
		if (ret == -EBUSY) {
			skb_queue_head(&wl->tx_queue, skb);
			goto out;
		} else if (ret < 0) {
			dev_kfree_skb(skb);
			goto out;
		}
	}

out:
	if (woken_up)
		wl1251_ps_elp_sleep(wl);

	mutex_unlock(&wl->mutex);
}

static void pv(struct sma1307_priv *xl, const char *tk)
{
	const struct firmware *fw;
	int *data, size, offset, num_mode;
	int ret;

	ret = request_firmware(&fw, tk, xl->dev);

	if (ret) {
		dev_err(xl->dev, "%s: failed to read \"%s\": %pe\n",
			__func__, setting_file, ERR_PTR(ret));
		sma1307->set.status = false;
		return;
	} else if ((fw->size) < SMA1307_SETTING_HEADER_SIZE) {
		dev_err(xl->dev, "%s: Invalid file\n", __func__);
		release_firmware(fw);
		sma1307->set.status = false;
		return;
	}

	data = kzalloc(fw->size, GFP_KERNEL);
	if (!data) {
		release_firmware(fw);
		sma1307->set.status = false;
		return;
	}
	size = fw->size >> 2;
	memcpy(data, fw->data, fw->size);

	release_firmware(fw);


	sma1307->set.header_size = SMA1307_SETTING_HEADER_SIZE;
	sma1307->set.checksum = data[xl->set.header_size - 2];
	sma1307->set.num_mode = data[xl->set.header_size - 1];
	num_mode = xl->set.num_mode;
	sma1307->set.header = devm_kzalloc(xl->dev,
					   xl->set.header_size,
					   GFP_KERNEL);
	if (!sma1307->set.header) {
		kfree(data);
		sma1307->set.status = false;
		return;
	}

	memcpy(xl->set.header, data,
	       xl->set.header_size * sizeof(int));

	if ((xl->set.checksum >> 8) != SMA1307_SETTING_CHECKSUM) {
		dev_err(xl->dev, "%s: failed by dismatch \"%s\"\n",
			__func__, setting_file);
		sma1307->set.status = false;
		return;
	}


	sma1307->set.def_size = SMA1307_SETTING_DEFAULT_SIZE;
	sma1307->set.def
	    = devm_kzalloc(xl->dev,
			   xl->set.def_size * sizeof(int), GFP_KERNEL);
	if (!sma1307->set.def) {
		kfree(data);
		kfree(xl->set.header);
		sma1307->set.status = false;
		return;
	}

	memcpy(xl->set.def,
	       &data[xl->set.header_size],
	       xl->set.def_size * sizeof(int));


	offset = xl->set.header_size + xl->set.def_size;
	sma1307->set.mode_size = DIV_ROUND_CLOSEST(size - offset, num_mode + 1);
	for (int i = 0; i < num_mode; i++) {
		sma1307->set.mode_set[i]
		    = devm_kzalloc(xl->dev,
				   xl->set.mode_size * 2 * sizeof(int),
				   GFP_KERNEL);
		if (!sma1307->set.mode_set[i]) {
			kfree(data);
			kfree(xl->set.header);
			kfree(xl->set.def);
			for (int j = 0; j < i; j++)
				kfree(xl->set.mode_set[j]);
			sma1307->set.status = false;
			return;
		}

		for (int j = 0; j < xl->set.mode_size; j++) {
			sma1307->set.mode_set[i][2 * j]
			    = data[offset + ((num_mode + 1) * j)];
			sma1307->set.mode_set[i][2 * j + 1]
			    = data[offset + ((num_mode + 1) * j + i + 1)];
		}
	}

	kfree(data);
	sma1307->set.status = true;

}

