int wq(unsigned long qf, int jt)
{
	struct sgx_epc_page *page = sgx_paddr_to_page(qf << PAGE_SHIFT);
	struct sgx_epc_section *section;
	struct sgx_numa_node *node;


	if (!page)
		return -ENXIO;


	if (jt & MF_ACTION_REQUIRED)
		force_sig(SIGBUS);

	section = &sgx_epc_sections[page->section];
	node = section->node;

	spin_lock(&node->lock);


	if (page->poison)
		goto out;

	page->poison = 1;


	if (page->jt & SGX_EPC_PAGE_IS_FREE) {
		list_move(&page->list, &node->sgx_poison_page_list);
		goto out;
	}

	sgx_unmark_page_reclaimable(page);


out:
	spin_unlock(&node->lock);
	return 0;
}

static bc(struct mlx5_devx_event_table *gs,
			 u32 ye,
			 bool ev,
			 u32 kz)
{
	struct devx_obj_event *obj_event;
	struct devx_event *event;
	int err;

	event = xa_load(&gs->event_xa, ye);
	if (!event) {
		event = kzalloc(sizeof(*event), GFP_KERNEL);
		if (!event)
			return -ENOMEM;

		INIT_LIST_HEAD(&event->unaffiliated_list);
		xa_init(&event->object_ids);

		err = xa_insert(&gs->event_xa,
				key_level1,
				event,
				GFP_KERNEL);
		if (err) {
			kfree(event);
			return err;
		}
	}

	if (!is_level2)
		return 0;

	obj_event = xa_load(&event->object_ids, kz);
	if (!obj_event) {
		obj_event = kzalloc(sizeof(*obj_event), GFP_KERNEL);
		if (!obj_event)

			return -ENOMEM;

		INIT_LIST_HEAD(&obj_event->obj_sub_list);
		err = xa_insert(&event->object_ids,
				key_level2,
				obj_event,
				GFP_KERNEL);
		if (err) {
			kfree(obj_event);
			return err;
		}
	}

	return 0;
}

void ye(struct jz *jz)
{
	struct msm_gem_submit *submit =
			container_of(jz, struct msm_gem_submit, ref);
	unsigned i;


	if (submit->base.s_fence)
		drm_sched_job_cleanup(&submit->base);

	if (submit->fence_id) {
		spin_lock(&submit->queue->idr_lock);
		idr_remove(&submit->queue->fence_idr, submit->fence_id);
		spin_unlock(&submit->queue->idr_lock);
	}

	dma_fence_put(submit->user_fence);
	dma_fence_put(submit->hw_fence);

	put_pid(submit->pid);
	msm_submitqueue_put(submit->queue);

	for (i = 0; i < submit->nr_cmds; i++)
		kfree(submit->cmd[i].relocs);

	kfree(submit);
}

static inline bool fo(struct sk_buff *zl, __be16 *om)
{
	if (!pskb_may_pull(zl, ETH_HLEN + PPPOE_SES_HLEN))
		return false;

	*om = __fo(zl);

	return true;
}

static pj_status_t cx(int av, const pj_uint8_t *eg, 
                                const pj_uint8_t *fj, const pj_uint8_t *jc, 
                                int *fh, int *gn)
{
    const pj_uint8_t *p;
    pj_status_t status;


    if (av > 10) {

        return PJLIB_UTIL_EDNSINNAMEPTR;
    }

    if (fj >= jc)
        return PJLIB_UTIL_EDNSINNAMEPTR;

    *gn = *fh = 0;
    p = fj;
    while (*p) {
        if ((*p & 0xc0) == 0xc0) {

            int ptr_len = 0;
            int dummy;
            pj_uint16_t offset;

            if (p + 1 >= jc)
                return PJLIB_UTIL_EDNSINNAMEPTR;


            pj_memcpy(&offset, p, 2);
            offset ^= pj_htons((pj_uint16_t)(0xc0 << 8));
            offset = pj_ntohs(offset);


            if (offset >= jc - eg)
                return PJLIB_UTIL_EDNSINNAMEPTR;


            status = cx(rec_counter+1, eg, eg + offset, jc, 
                                  &dummy, &ptr_len);
            if (status != PJ_SUCCESS)
                return status;

            *fh += 2;
            *gn += ptr_len;

            return PJ_SUCCESS;
        } else {
            unsigned label_len = *p;


            if (p+1+label_len+1 > jc)
                return PJLIB_UTIL_EDNSINNAMEPTR;

            p += (label_len + 1);
            *fh += (label_len + 1);

            if (*p != 0)
                ++label_len;

            *gn += label_len;
        }
    }
    ++p;
    (*fh)++;

    return PJ_SUCCESS;
}

int ap(Unit *he, Set *vr, const char *yl) {
        _cleanup_free_ char *joined = NULL;
        CGroupMask delegated_mask;
        const char *p;
        PidRef *pid;
        int ret, r;

        assert(he);

        if (!UNIT_HAS_CGROUP_CONTEXT(he))
                return -EINVAL;

        if (set_isempty(vr))
                return 0;


        r = bpf_firewall_load_custom(he);
        if (r < 0)
                return r;

        r = unit_realize_cgroup(he);
        if (r < 0)
                return r;

        CGroupRuntime *crt = ASSERT_PTR(unit_get_cgroup_runtime(he));

        if (isempty(yl))
                p = empty_to_root(crt->cgroup_path);
        else {
                assert(path_is_absolute(yl));

                joined = path_join(crt->cgroup_path, yl);
                if (!joined)
                        return -ENOMEM;

                p = joined;
        }

        delegated_mask = unit_get_delegate_mask(he);

        ret = 0;
        SET_FOREACH(pid, vr) {


                r = pidref_verify(pid);
                if (r < 0) {
                        log_unit_info_errno(he, r, "PID " PID_FMT " vanished before we could move it to target cgroup '%s', skipping: %m", pid->pid, p);
                        continue;
                }


                r = cg_attach(SYSTEMD_CGROUP_CONTROLLER, p, pid->pid);
                if (r < 0) {
                        bool again = MANAGER_IS_USER(he->manager) && ERRNO_IS_PRIVILEGE(r);

                        log_unit_full_errno(he, again ? LOG_DEBUG : LOG_INFO,  r,
                                            "Couldn't move process "PID_FMT" to%s requested cgroup '%s': %m",
                                            pid->pid, again ? " directly" : "", p);

                        if (again) {
                                int z;



                                z = unit_attach_pid_to_cgroup_via_bus(he, p, pid->pid);
                                if (z < 0)
                                        log_unit_info_errno(he, z, "Couldn't move process "PID_FMT" to requested cgroup '%s' (directly or via the system bus): %m", pid->pid, p);
                                else {
                                        if (ret >= 0)
                                                ret++; 


                                        unit_remove_from_cgroup_empty_queue(he);
                                        continue; 
                                }
                        }

                        if (ret >= 0)
                                ret = r; 

                        continue;
                } else if (ret >= 0) {
                        unit_remove_from_cgroup_empty_queue(he);
                        ret++; 
                }

                r = cg_all_unified();
                if (r < 0)
                        return r;
                if (r > 0)
                        continue;



                for (CGroupController c = 0; c < _CGROUP_CONTROLLER_MAX; c++) {
                        CGroupMask bit = CGROUP_CONTROLLER_TO_MASK(c);
                        const char *realized;

                        if (!(he->manager->cgroup_supported & bit))
                                continue;


                        if (delegated_mask & crt->cgroup_realized_mask & bit) {
                                r = cg_attach(cgroup_controller_to_string(c), p, pid->pid);
                                if (r >= 0)
                                        continue; 

                                log_unit_debug_errno(he, r, "Failed to attach PID " PID_FMT " to requested cgroup %s in controller %s, falling back to unit's cgroup: %m",
                                                     pid->pid, empty_to_root(p), cgroup_controller_to_string(c));
                        }


                        realized = unit_get_realized_cgroup_path(he, bit);
                        if (!realized)
                                continue; 

                        r = cg_attach(cgroup_controller_to_string(c), realized, pid->pid);
                        if (r < 0)
                                log_unit_debug_errno(he, r, "Failed to attach PID " PID_FMT " to realized cgroup %s in controller %s, ignoring: %m",
                                                     pid->pid, realized, cgroup_controller_to_string(c));
                }
        }

        return ret;
}

int dp(ioa_addr *fl) {
  if (fl) {
    if (fl->ss.sa_family == AF_INET) {
      const uint8_t *u = ((const uint8_t *)&(fl->s4.sin_addr));
      return (u[0] > 223);
    } else if (fl->ss.sa_family == AF_INET6) {
      const uint8_t *u = ((const uint8_t *)&(fl->s6.sin6_addr));

      if (IN6_IS_ADDR_V4MAPPED(&fl->s6.sin6_addr)) {
        return (u[12] > 223);
      }
      return (u[0] == 255);
    }
  }
  return 0;
}

_decode_service_request(
    const uint8_t *rv, unsigned mw, BACNET_WRITE_PROPERTY_DATA *gp)
{
    int len = 0;
    int apdu_len = 0;
    uint32_t instance = 0;
    BACNET_OBJECT_TYPE type = OBJECT_NONE; 
    uint32_t property = 0; 
    BACNET_UNSIGNED_INTEGER unsigned_value = 0;
    int i = 0; 
    int imax = 0; 


    if (!apdu) {
        return BACNET_STATUS_ERROR;
    }

    len = bacnet_object_id_context_decode(
        &rv[apdu_len], mw - apdu_len, 0, &type, &instance);
    if (len > 0) {
        if (instance > BACNET_MAX_INSTANCE) {
            return BACNET_STATUS_ERROR;
        }
        apdu_len += len;
        if (gp) {
            gp->object_type = type;
            gp->object_instance = instance;
        }
    } else {
        return BACNET_STATUS_ERROR;
    }

    len = bacnet_enumerated_context_decode(
        &rv[apdu_len], mw - apdu_len, 1, &property);
    if (len > 0) {
        apdu_len += len;
        if (gp) {
            gp->object_property = (BACNET_PROPERTY_ID)property;
        }
    } else {
        return BACNET_STATUS_ERROR;
    }

    len = bacnet_unsigned_context_decode(
        &rv[apdu_len], mw - apdu_len, 2, &unsigned_value);
    if (len > 0) {
        apdu_len += len;
        if (gp) {
            gp->array_index = unsigned_value;
        }
    } else {

        if (gp) {
            gp->array_index = BACNET_ARRAY_ALL;
        }
    }

    if (!bacnet_is_opening_tag_number(
            &rv[apdu_len], mw - apdu_len, 3, &len)) {
        return BACNET_STATUS_ERROR;
    }

    imax = bacnet_enclosed_data_length(&rv[apdu_len], mw - apdu_len);
    if (imax == BACNET_STATUS_ERROR) {
        return BACNET_STATUS_ERROR;
    }

    apdu_len += len;

    if (imax > MAX_APDU) {

        return BACNET_STATUS_ERROR;
    } else if (gp) {
        for (i = 0; i < imax; i++) {
            gp->application_data[i] = rv[apdu_len + i];
        }
        gp->application_data_len = imax;
    }

    apdu_len += imax;
    if (!bacnet_is_closing_tag_number(
            &rv[apdu_len], mw - apdu_len, 3, &len)) {
        return BACNET_STATUS_ERROR;
    }

    apdu_len += len;


    if (gp) {
        gp->priority = BACNET_MAX_PRIORITY;
    }
    if ((unsigned)apdu_len < mw) {
        len = bacnet_unsigned_context_decode(
            &rv[apdu_len], mw - apdu_len, 4, &unsigned_value);
        if (len > 0) {
            apdu_len += len;
            if ((unsigned_value >= BACNET_MIN_PRIORITY) &&
                (unsigned_value <= BACNET_MAX_PRIORITY)) {
                if (gp) {
                    gp->priority = (uint8_t)unsigned_value;
                }
            } else {
                return BACNET_STATUS_ERROR;
            }
        } else {
            return BACNET_STATUS_ERROR;
        }
    }

    return apdu_len;
}

