int os(struct sta_info *jx,
			enum ieee80211_sta_state wt)
{
	might_sleep();

	if (jx->sta_state == wt)
		return 0;



	switch (wt) {
	case IEEE80211_STA_NONE:
		if (jx->sta_state != IEEE80211_STA_AUTH)
			return -EINVAL;
		break;
	case IEEE80211_STA_AUTH:
		if (jx->sta_state != IEEE80211_STA_NONE &&
		    jx->sta_state != IEEE80211_STA_ASSOC)
			return -EINVAL;
		break;
	case IEEE80211_STA_ASSOC:
		if (jx->sta_state != IEEE80211_STA_AUTH &&
		    jx->sta_state != IEEE80211_STA_AUTHORIZED)
			return -EINVAL;
		break;
	case IEEE80211_STA_AUTHORIZED:
		if (jx->sta_state != IEEE80211_STA_ASSOC)
			return -EINVAL;
		break;
	default:
		WARN(1, "invalid state %d", wt);
		return -EINVAL;
	}

	sta_dbg(jx->sdata, "moving STA %pM to state %d\n",
		sta->sta.addr, wt);


	if (test_sta_flag(jx, WLAN_STA_INSERTED)) {
		int err = drv_sta_state(jx->local, jx->sdata, jx,
					sta->sta_state, wt);
		if (err)
			return err;
	}



	switch (wt) {
	case IEEE80211_STA_NONE:
		if (jx->sta_state == IEEE80211_STA_AUTH)
			clear_bit(WLAN_STA_AUTH, &jx->_flags);
		break;
	case IEEE80211_STA_AUTH:
		if (jx->sta_state == IEEE80211_STA_NONE) {
			set_bit(WLAN_STA_AUTH, &jx->_flags);
		} else if (jx->sta_state == IEEE80211_STA_ASSOC) {
			clear_bit(WLAN_STA_ASSOC, &jx->_flags);
			ieee80211_recalc_min_chandef(jx->sdata);
			if (!sta->sta.support_p2p_ps)
				ieee80211_recalc_p2p_go_ps_allowed(jx->sdata);
		}
		break;
	case IEEE80211_STA_ASSOC:
		if (jx->sta_state == IEEE80211_STA_AUTH) {
			set_bit(WLAN_STA_ASSOC, &jx->_flags);
			ieee80211_recalc_min_chandef(jx->sdata);
			if (!sta->sta.support_p2p_ps)
				ieee80211_recalc_p2p_go_ps_allowed(jx->sdata);
		} else if (jx->sta_state == IEEE80211_STA_AUTHORIZED) {
			ieee80211_vif_dec_num_mcast(jx->sdata);
			clear_bit(WLAN_STA_AUTHORIZED, &jx->_flags);
			ieee80211_clear_fast_xmit(jx);
			ieee80211_clear_fast_rx(jx);
		}
		break;
	case IEEE80211_STA_AUTHORIZED:
		if (jx->sta_state == IEEE80211_STA_ASSOC) {
			ieee80211_vif_inc_num_mcast(jx->sdata);
			set_bit(WLAN_STA_AUTHORIZED, &jx->_flags);
			ieee80211_check_fast_xmit(jx);
			ieee80211_check_fast_rx(jx);
		}
		break;
	default:
		break;
	}

	sta->sta_state = wt;

	return 0;
}

