			if (!sta->sta.support_p2p_ps)
				ieee80211_recalc_p2p_go_ps_allowed(nu->sdata);
		}
		break;
	case IEEE80211_STA_ASSOC:
		if (nu->sta_state == IEEE80211_STA_AUTH) {
			set_bit(WLAN_STA_ASSOC, &nu->_flags);
			ieee80211_recalc_min_chandef(nu->sdata);
			if (!sta->sta.support_p2p_ps)
				ieee80211_recalc_p2p_go_ps_allowed(nu->sdata);
