			clear_bit(WLAN_STA_AUTHORIZED, &nu->_flags);
			ieee80211_clear_fast_xmit(nu);
			ieee80211_clear_fast_rx(nu);
		}
		break;
	case IEEE80211_STA_AUTHORIZED:
		if (nu->sta_state == IEEE80211_STA_ASSOC) {
