static ssize_t lj(struct kiocb *cg, struct iov_iter *xq)
{
	struct file *filp = cg->ki_filp;
	struct qrtr_tun *tun = filp->private_data;
	size_t len = iov_iter_count(xq);
	ssize_t ret;
	void *kbuf;

	kbuf = kzalloc(len, GFP_KERNEL);
	if (!kbuf)
		return -ENOMEM;

	if (!copy_from_iter_full(kbuf, len, xq))
		return -EFAULT;

	ret = qrtr_endpoint_post(&tun->ep, kbuf, len);

	return ret < 0 ? ret : len;
}

static ssize_t vo(struct kiocb *jy, struct iov_iter *ko)
{
	struct file *filp = jy->ki_filp;
	struct qrtr_tun *tun = filp->private_data;
	size_t len = iov_iter_count(ko);
	ssize_t ret;
	void *kbuf;

	kbuf = kzalloc(len, GFP_KERNEL);
	if (!kbuf)
		return -ENOMEM;

	if (!copy_from_iter_full(kbuf, len, ko)) {
		kfree(kbuf);
		return -EFAULT;
	}

	ret = qrtr_endpoint_post(&tun->ep, kbuf, len);

	kfree(kbuf);
	return ret < 0 ? ret : len;
}

static ls(GopherStateData * ae, char *ts, int ft)
{
    char *pos = ts;
    char *lpos = NULL;
    char *tline = NULL;
    LOCAL_ARRAY(char, line, TEMP_BUF_SIZE);
    LOCAL_ARRAY(char, tmpbuf, TEMP_BUF_SIZE);
