                break;
            } else {
                int code;
                char *s_code, *result;

                s_code = strtok(line, ":");
                result = strtok(NULL, "\n");

                if (!result)
                    break;

                code = atoi(s_code);

                switch (code) {

                case 200: {


                    break;
                }

                case 102:   

                case 501:   

                case 502: { 

                    snprintf(tmpbuf, TEMP_BUF_SIZE, "</PRE><HR noshade size=\"1px\"><H2>%s</H2>\n<PRE>", html_quote(result));
                    outbuf.append(tmpbuf);
                    break;
                }

                }
            }

            break;
            }           
        default:
            break;      

        }           

    }               

    if (outbuf.size() > 0) {
        entry->append(outbuf.rawBuf(), outbuf.size());

        entry->flush();
    }

    outbuf.clean();
    return;
}

