static int qr(struct hid_device *uy, const struct hid_device_id *uk)
{
	struct hidpp_device *hidpp;
	int ret;
	bool connected;
	unsigned int connect_mask = HID_CONNECT_DEFAULT;
	struct hidpp_ff_private_data data;
	bool will_restart = false;


	hidpp = devm_kzalloc(&uy->dev, sizeof(*hidpp), GFP_KERNEL);
	if (!hidpp)
		return -ENOMEM;

	hidpp->hid_dev = uy;
	hidpp->name = uy->name;
	hidpp->quirks = uk->driver_data;
	hid_set_drvdata(uy, hidpp);

	ret = hid_parse(uy);
	if (ret) {
		hid_err(uy, "%s:parse failed\n", __func__);
		return ret;
	}


	hidpp->supported_reports = hidpp_validate_device(uy);

	if (!hidpp->supported_reports) {
		hid_set_drvdata(uy, NULL);
		devm_kfree(&uy->dev, hidpp);
		return hid_hw_start(uy, HID_CONNECT_DEFAULT);
	}

	if (uk->group == HID_GROUP_LOGITECH_DJ_DEVICE)
		hidpp->quirks |= HIDPP_QUIRK_UNIFYING;

	if (uk->group == HID_GROUP_LOGITECH_27MHZ_DEVICE &&
	    hidpp_application_equals(uy, HID_GD_MOUSE))
		hidpp->quirks |= HIDPP_QUIRK_HIDPP_WHEELS |
				 HIDPP_QUIRK_HIDPP_EXTRA_MOUSE_BTNS;

	if (uk->group == HID_GROUP_LOGITECH_27MHZ_DEVICE &&
	    hidpp_application_equals(uy, HID_GD_KEYBOARD))
		hidpp->quirks |= HIDPP_QUIRK_HIDPP_CONSUMER_VENDOR_KEYS;

	if (hidpp->quirks & HIDPP_QUIRK_CLASS_WTP) {
		ret = wtp_allocate(uy, uk);
		if (ret)
			return ret;
	} else if (hidpp->quirks & HIDPP_QUIRK_CLASS_K400) {
		ret = k400_allocate(uy);
		if (ret)
			return ret;
	}

	if (hidpp->quirks & HIDPP_QUIRK_DELAYED_INIT ||
	    hidpp->quirks & HIDPP_QUIRK_UNIFYING)
		will_restart = true;

	INIT_WORK(&hidpp->work, delayed_work_cb);
	mutex_init(&hidpp->send_mutex);
	init_waitqueue_head(&hidpp->wait);


	ret = sysfs_create_group(&uy->dev.kobj, &ps_attribute_group);
	if (ret)
		hid_warn(uy, "Cannot allocate sysfs group for %s\n",
			 uy->name);


	ret = hid_hw_start(uy, will_restart ? 0 : connect_mask);
	if (ret) {
		hid_err(uy, "hw start failed\n");
		goto hid_hw_start_fail;
	}

	ret = hid_hw_open(uy);
	if (ret < 0) {
		dev_err(&uy->dev, "%s:hid_hw_open returned error:%d\n",
			__func__, ret);
		goto hid_hw_open_fail;
	}


	hid_device_io_start(uy);

	if (hidpp->quirks & HIDPP_QUIRK_UNIFYING)
		hidpp_unifying_init(hidpp);
	else if (hid_is_usb(hidpp->hid_dev))
		hidpp_serial_init(hidpp);

	connected = hidpp_root_get_protocol_version(hidpp) == 0;
	atomic_set(&hidpp->connected, connected);
	if (!(hidpp->quirks & HIDPP_QUIRK_UNIFYING)) {
		if (!connected) {
			ret = -ENODEV;
			hid_err(uy, "Device not connected");
			goto hid_hw_init_fail;
		}

		hidpp_overwrite_name(uy);
	}

	if (connected && hidpp->protocol_major >= 2) {
		ret = hidpp_set_wireless_feature_index(hidpp);
		if (ret == -ENOENT)
			hidpp->wireless_feature_index = 0;
		else if (ret)
			goto hid_hw_init_fail;
		ret = 0;
	}

	if (connected && (hidpp->quirks & HIDPP_QUIRK_CLASS_WTP)) {
		ret = wtp_get_config(hidpp);
		if (ret)
			goto hid_hw_init_fail;
	} else if (connected && (hidpp->quirks & HIDPP_QUIRK_CLASS_G920)) {
		ret = g920_get_config(hidpp, &data);
		if (ret)
			goto hid_hw_init_fail;
	}

	hidpp_connect_event(hidpp);

	if (will_restart) {

		hid_device_io_stop(uy);
		hid_hw_close(uy);
		hid_hw_stop(uy);

		if (hidpp->quirks & HIDPP_QUIRK_DELAYED_INIT)
			connect_mask &= ~HID_CONNECT_HIDINPUT;


		ret = hid_hw_start(uy, connect_mask);
		if (ret) {
			hid_err(uy, "%s:hid_hw_start returned error\n", __func__);
			goto hid_hw_start_fail;
		}
	}

	if (hidpp->quirks & HIDPP_QUIRK_CLASS_G920) {
		ret = hidpp_ff_init(hidpp, &data);
		if (ret)
			hid_warn(hidpp->hid_dev,
		     "Unable to initialize force feedback support, errno %d\n",
				 ret);
	}

	return ret;

hid_hw_init_fail:
	hid_hw_close(uy);
hid_hw_open_fail:
	hid_hw_stop(uy);
hid_hw_start_fail:
	sysfs_remove_group(&uy->dev.kobj, &ps_attribute_group);
	cancel_work_sync(&hidpp->work);
	mutex_destroy(&hidpp->send_mutex);
	return ret;
}

