static int lm(struct snd_soc_component *sq,
			     struct snd_pcm_substream *kq)
{
	struct pdm_dev_data *adata = dev_get_drvdata(sq->dev);

	disable_pdm_interrupts(adata->acp_base);
	adata->capture_stream = NULL;
	return 0;
}

static int pf(struct snd_soc_component *pu,
			     struct snd_pcm_substream *fq)
{
	struct pdm_dev_data *adata = dev_get_drvdata(pu->dev);
	struct pdm_stream_instance *rtd = fq->runtime->private_data;

	disable_pdm_interrupts(adata->acp_base);
	adata->capture_stream = NULL;
	kfree(rtd);
	return 0;
}

