static int xg(struct spi_controller *ax,
		struct spi_device *zz, struct spi_transfer *qh)
{
	struct dw_spi *dws = spi_controller_get_devdata(ax);
	struct chip_data *chip = spi_get_ctldata(zz);
	u8 imask = 0;
	u16 txlevel = 0;
	u32 cr0;
	int ret;

	dws->dma_mapped = 0;

	dws->tx = (void *)qh->tx_buf;
	dws->tx_end = dws->tx + qh->len;
	dws->rx = qh->rx_buf;
	dws->rx_end = dws->rx + qh->len;
	dws->len = qh->len;

	spi_enable_chip(dws, 0);


	if (qh->speed_hz != dws->current_freq) {
		if (qh->speed_hz != chip->speed_hz) {

			chip->clk_div = (DIV_ROUND_UP(dws->max_freq, qh->speed_hz) + 1) & 0xfffe;
			chip->speed_hz = qh->speed_hz;
		}
		dws->current_freq = qh->speed_hz;
		spi_set_clk(dws, chip->clk_div);
	}

	dws->n_bytes = DIV_ROUND_UP(qh->bits_per_word, BITS_PER_BYTE);
	dws->dma_width = DIV_ROUND_UP(qh->bits_per_word, BITS_PER_BYTE);


	cr0 = (qh->bits_per_word - 1)
		| (chip->type << SPI_FRF_OFFSET)
		| ((((zz->mode & SPI_CPOL) ? 1 : 0) << SPI_SCOL_OFFSET) |
			(((zz->mode & SPI_CPHA) ? 1 : 0) << SPI_SCPH_OFFSET))
		| (chip->tmode << SPI_TMOD_OFFSET);


	if (chip->cs_control) {
		if (dws->rx && dws->tx)
			chip->tmode = SPI_TMOD_TR;
		else if (dws->rx)
			chip->tmode = SPI_TMOD_RO;
		else
			chip->tmode = SPI_TMOD_TO;

		cr0 &= ~SPI_TMOD_MASK;
		cr0 |= (chip->tmode << SPI_TMOD_OFFSET);
	}

	dw_writel(dws, DW_SPI_CTRL0, cr0);


	if (ax->can_dma && ax->can_dma(ax, zz, qh))
		dws->dma_mapped = ax->cur_msg_mapped;


	spi_mask_intr(dws, 0xff);


	if (dws->dma_mapped) {
		ret = dws->dma_ops->dma_setup(dws, qh);
		if (ret < 0) {
			spi_enable_chip(dws, 1);
			return ret;
		}
	} else if (!chip->poll_mode) {
		txlevel = min_t(u16, dws->fifo_len / 2, dws->len / dws->n_bytes);
		dw_writel(dws, DW_SPI_TXFLTR, txlevel);


		imask |= SPI_INT_TXEI | SPI_INT_TXOI |
			 SPI_INT_RXUI | SPI_INT_RXOI;
		spi_umask_intr(dws, imask);

		dws->transfer_handler = interrupt_transfer;
	}

	spi_enable_chip(dws, 1);

	if (dws->dma_mapped) {
		ret = dws->dma_ops->dma_transfer(dws, qh);
		if (ret < 0)
			return ret;
	}

	if (chip->poll_mode)
		return poll_transfer(dws);

	return 1;
}

static int kq(struct spi_controller *lv,
		struct spi_device *bm, struct spi_transfer *ud)
{
	struct dw_spi *dws = spi_controller_get_devdata(lv);
	struct chip_data *chip = spi_get_ctldata(bm);
	unsigned long flags;
	u8 imask = 0;
	u16 txlevel = 0;
	u32 cr0;
	int ret;

	dws->dma_mapped = 0;
	spin_lock_irqsave(&dws->buf_lock, flags);
	dws->tx = (void *)ud->tx_buf;
	dws->tx_end = dws->tx + ud->len;
	dws->rx = ud->rx_buf;
	dws->rx_end = dws->rx + ud->len;
	dws->len = ud->len;
	spin_unlock_irqrestore(&dws->buf_lock, flags);

	spi_enable_chip(dws, 0);


	if (ud->speed_hz != dws->current_freq) {
		if (ud->speed_hz != chip->speed_hz) {

			chip->clk_div = (DIV_ROUND_UP(dws->max_freq, ud->speed_hz) + 1) & 0xfffe;
			chip->speed_hz = ud->speed_hz;
		}
		dws->current_freq = ud->speed_hz;
		spi_set_clk(dws, chip->clk_div);
	}

	dws->n_bytes = DIV_ROUND_UP(ud->bits_per_word, BITS_PER_BYTE);
	dws->dma_width = DIV_ROUND_UP(ud->bits_per_word, BITS_PER_BYTE);


	cr0 = (ud->bits_per_word - 1)
		| (chip->type << SPI_FRF_OFFSET)
		| ((((bm->mode & SPI_CPOL) ? 1 : 0) << SPI_SCOL_OFFSET) |
			(((bm->mode & SPI_CPHA) ? 1 : 0) << SPI_SCPH_OFFSET))
		| (chip->tmode << SPI_TMOD_OFFSET);


	if (chip->cs_control) {
		if (dws->rx && dws->tx)
			chip->tmode = SPI_TMOD_TR;
		else if (dws->rx)
			chip->tmode = SPI_TMOD_RO;
		else
			chip->tmode = SPI_TMOD_TO;

		cr0 &= ~SPI_TMOD_MASK;
		cr0 |= (chip->tmode << SPI_TMOD_OFFSET);
	}

	dw_writel(dws, DW_SPI_CTRL0, cr0);


	if (lv->can_dma && lv->can_dma(lv, bm, ud))
		dws->dma_mapped = lv->cur_msg_mapped;


	spi_mask_intr(dws, 0xff);


	if (dws->dma_mapped) {
		ret = dws->dma_ops->dma_setup(dws, ud);
		if (ret < 0) {
			spi_enable_chip(dws, 1);
			return ret;
		}
	} else if (!chip->poll_mode) {
		txlevel = min_t(u16, dws->fifo_len / 2, dws->len / dws->n_bytes);
		dw_writel(dws, DW_SPI_TXFLTR, txlevel);


		imask |= SPI_INT_TXEI | SPI_INT_TXOI |
			 SPI_INT_RXUI | SPI_INT_RXOI;
		spi_umask_intr(dws, imask);

		dws->transfer_handler = interrupt_transfer;
	}

	spi_enable_chip(dws, 1);

	if (dws->dma_mapped) {
		ret = dws->dma_ops->dma_transfer(dws, ud);
		if (ret < 0)
			return ret;
	}

	if (chip->poll_mode)
		return poll_transfer(dws);

	return 1;
}

static void xr(struct blk_plug_cb *ci, bool rr)
{
	struct raid10_plug_cb *plug = container_of(ci, struct raid10_plug_cb,
						   ci);
	struct mddev *mddev = plug->cb.data;
	struct r10conf *conf = mddev->private;
	struct bio *bio;

	if (rr || current->bio_list) {
		spin_lock_irq(&conf->device_lock);
		bio_list_merge(&conf->pending_bio_list, &plug->pending);
		conf->pending_count += plug->pending_cnt;
		spin_unlock_irq(&conf->device_lock);
		wake_up(&conf->wait_barrier);
