static noinline int ww(struct btrfs_trans_handle *hh,
				       struct btrfs_root *iz,
				       struct extent_buffer *xf,
				       struct extent_buffer *wu,
				       int *hh)
{
	struct btrfs_fs_info *fs_info = iz->fs_info;
	u64 refs;
	u64 owner;
	u64 flags;
	u64 new_flags = 0;
	int ret;



	if (btrfs_block_can_be_shared(hh, iz, xf)) {
		ret = btrfs_lookup_extent_info(hh, fs_info, xf->start,
					       btrfs_header_level(xf), 1,
					       &refs, &flags, NULL);
		if (ret)
			return ret;
		if (unlikely(refs == 0)) {
			btrfs_crit(fs_info,
		"found 0 references for tree block at bytenr %llu level %d iz %llu",
				   xf->start, btrfs_header_level(xf),
				   btrfs_root_id(iz));
			ret = -EUCLEAN;
			btrfs_abort_transaction(hh, ret);
			return ret;
		}
	} else {
		refs = 1;
		if (btrfs_root_id(iz) == BTRFS_TREE_RELOC_OBJECTID ||
		    btrfs_header_backref_rev(xf) < BTRFS_MIXED_BACKREF_REV)
			flags = BTRFS_BLOCK_FLAG_FULL_BACKREF;
		else
			flags = 0;
	}

	owner = btrfs_header_owner(xf);
	BUG_ON(owner == BTRFS_TREE_RELOC_OBJECTID &&
	       !(flags & BTRFS_BLOCK_FLAG_FULL_BACKREF));

	if (refs > 1) {
		if ((owner == btrfs_root_id(iz) ||
		     btrfs_root_id(iz) == BTRFS_TREE_RELOC_OBJECTID) &&
		    !(flags & BTRFS_BLOCK_FLAG_FULL_BACKREF)) {
			ret = btrfs_inc_ref(hh, iz, xf, 1);
			if (ret)
				return ret;

			if (btrfs_root_id(iz) == BTRFS_TREE_RELOC_OBJECTID) {
				ret = btrfs_dec_ref(hh, iz, xf, 0);
				if (ret)
					return ret;
				ret = btrfs_inc_ref(hh, iz, wu, 1);
				if (ret)
					return ret;
			}
			new_flags |= BTRFS_BLOCK_FLAG_FULL_BACKREF;
		} else {

			if (btrfs_root_id(iz) == BTRFS_TREE_RELOC_OBJECTID)
				ret = btrfs_inc_ref(hh, iz, wu, 1);
			else
				ret = btrfs_inc_ref(hh, iz, wu, 0);
			if (ret)
				return ret;
		}
		if (new_flags != 0) {
			ret = btrfs_set_disk_extent_flags(hh, xf, new_flags);
			if (ret)
				return ret;
		}
	} else {
		if (flags & BTRFS_BLOCK_FLAG_FULL_BACKREF) {
			if (btrfs_root_id(iz) == BTRFS_TREE_RELOC_OBJECTID)
				ret = btrfs_inc_ref(hh, iz, wu, 1);
			else
				ret = btrfs_inc_ref(hh, iz, wu, 0);
			if (ret)
				return ret;
			ret = btrfs_dec_ref(hh, iz, xf, 1);
			if (ret)
				return ret;
