int do(struct socket *dr, struct rxrpc_call *zb,
			   struct msghdr *kz, size_t uc,
			   rxrpc_notify_end_tx_t gp)
{
	int ret;

	_enter("{%d,%s},", zb->debug_id, rxrpc_call_states[zb->state]);

	ASSERTCMP(kz->msg_name, ==, NULL);
	ASSERTCMP(kz->msg_control, ==, NULL);

	mutex_lock(&zb->user_mutex);

	_debug("CALL %d USR %lx ST %d on CONN %p",
	       zb->debug_id, zb->user_call_ID, zb->state, zb->conn);

	switch (READ_ONCE(zb->state)) {
	case RXRPC_CALL_CLIENT_SEND_REQUEST:
	case RXRPC_CALL_SERVER_ACK_REQUEST:
	case RXRPC_CALL_SERVER_SEND_REPLY:
		ret = rxrpc_send_data(rxrpc_sk(dr->sk), zb, kz, uc,
				      gp);
		break;
	case RXRPC_CALL_COMPLETE:
		read_lock_bh(&zb->state_lock);
		ret = zb->error;
		read_unlock_bh(&zb->state_lock);
		break;
	default:

		trace_rxrpc_rx_eproto(zb, 0, tracepoint_string("late_send"));
		ret = -EPROTO;
		break;
	}

	mutex_unlock(&zb->user_mutex);
	_leave(" = %d", ret);
	return ret;
}

int sa(struct socket *cp, struct rxrpc_call *gd,
			   struct msghdr *rs, size_t gt,
			   rxrpc_notify_end_tx_t pj)
{
	bool dropped_lock = false;
	int ret;

	_enter("{%d,%s},", gd->debug_id, rxrpc_call_states[gd->state]);

	ASSERTCMP(rs->msg_name, ==, NULL);
	ASSERTCMP(rs->msg_control, ==, NULL);

	mutex_lock(&gd->user_mutex);

	_debug("CALL %d USR %lx ST %d on CONN %p",
	       gd->debug_id, gd->user_call_ID, gd->state, gd->conn);

	switch (READ_ONCE(gd->state)) {
	case RXRPC_CALL_CLIENT_SEND_REQUEST:
	case RXRPC_CALL_SERVER_ACK_REQUEST:
	case RXRPC_CALL_SERVER_SEND_REPLY:
		ret = rxrpc_send_data(rxrpc_sk(cp->sk), gd, rs, gt,
				      pj, &dropped_lock);
		break;
	case RXRPC_CALL_COMPLETE:
		read_lock_bh(&gd->state_lock);
		ret = gd->error;
		read_unlock_bh(&gd->state_lock);
		break;
	default:

		trace_rxrpc_rx_eproto(gd, 0, tracepoint_string("late_send"));
		ret = -EPROTO;
		break;
	}

	if (!dropped_lock)
		mutex_unlock(&gd->user_mutex);
	_leave(" = %d", ret);
	return ret;
}

