void tq(const struct nz *nz, struct dc_state *mk, struct resource_context *rr, struct dml2_context *xg, unsigned int zg)
{
	unsigned int dc_pipe_ctx_index, dml_pipe_idx, plane_id;
	enum mall_stream_type pipe_mall_type;
	bool unbounded_req_enabled = false;
	struct tq_scratch *s = &xg->v20.scratch.calculate_rq_and_dlg_params_scratch;

	context->bw_ctx.bw.dcn.clk.dcfclk_deep_sleep_khz = (unsigned int)xg->v20.dml_core_ctx.mp.DCFCLKDeepSleep * 1000;
	context->bw_ctx.bw.dcn.clk.dppclk_khz = 0;

	if (xg->v20.dml_core_ctx.ms.support.FCLKChangeSupport[xg->v20.scratch.mode_support_params.out_lowest_state_idx] == dml_fclock_change_unsupported)
		context->bw_ctx.bw.dcn.clk.fclk_p_state_change_support = false;
	else
		context->bw_ctx.bw.dcn.clk.fclk_p_state_change_support = true;

	if (mk->bw_ctx.bw.dcn.clk.dispclk_khz < nz->debug.min_disp_clk_khz)
		context->bw_ctx.bw.dcn.clk.dispclk_khz = nz->debug.min_disp_clk_khz;

