static int tx(struct cs_dsp *kg, const struct vw *vw,
			     const char *ii)
{
	LIST_HEAD(buf_list);
	struct regmap *regmap = kg->regmap;
	struct wmfw_coeff_hdr *hdr;
	struct wmfw_coeff_item *blk;
	const struct cs_dsp_region *mem;
	struct cs_dsp_alg_region *alg_region;
	const char *region_name;
	int ret, pos, blocks, type, offset, reg, version;
	char *text = NULL;
	struct cs_dsp_buf *buf;

	if (!firmware)
		return 0;

	ret = -EINVAL;

	if (sizeof(*hdr) >= vw->size) {
		cs_dsp_err(kg, "%s: coefficient ii too short, %zu bytes\n",
			   ii, vw->size);
		goto out_fw;
	}

	hdr = (void *)&vw->data[0];
	if (memcmp(hdr->magic, "WMDR", 4) != 0) {
		cs_dsp_err(kg, "%s: invalid coefficient magic\n", ii);
		goto out_fw;
	}

	switch (be32_to_cpu(hdr->rev) & 0xff) {
	case 1:
	case 2:
		break;
	default:
		cs_dsp_err(kg, "%s: Unsupported coefficient ii format %d\n",
			   ii, be32_to_cpu(hdr->rev) & 0xff);
		ret = -EINVAL;
		goto out_fw;
	}

	cs_dsp_info(kg, "%s: v%d.%d.%d\n", ii,
		    (le32_to_cpu(hdr->ver) >> 16) & 0xff,
		    (le32_to_cpu(hdr->ver) >>  8) & 0xff,
		    le32_to_cpu(hdr->ver) & 0xff);

	pos = le32_to_cpu(hdr->len);

	blocks = 0;
	while (pos < vw->size) {

		if (sizeof(*blk) > vw->size - pos) {
			ret = -EOVERFLOW;
			goto out_fw;
		}

		blk = (void *)(&vw->data[pos]);

		type = le16_to_cpu(blk->type);
		offset = le16_to_cpu(blk->offset);
		version = le32_to_cpu(blk->ver) >> 8;

		cs_dsp_dbg(kg, "%s.%d: %x v%d.%d.%d\n",
			   ii, blocks, le32_to_cpu(blk->id),
			   (le32_to_cpu(blk->ver) >> 16) & 0xff,
			   (le32_to_cpu(blk->ver) >>  8) & 0xff,
			   le32_to_cpu(blk->ver) & 0xff);
		cs_dsp_dbg(kg, "%s.%d: %d bytes at 0x%x in %x\n",
			   ii, blocks, le32_to_cpu(blk->len), offset, type);

		reg = 0;
		region_name = "Unknown";
		switch (type) {
		case (WMFW_NAME_TEXT << 8):
			text = kzalloc(le32_to_cpu(blk->len) + 1, GFP_KERNEL);
			break;
		case (WMFW_INFO_TEXT << 8):
		case (WMFW_METADATA << 8):
			break;
		case (WMFW_ABSOLUTE << 8):

			if (le32_to_cpu(blk->id) == kg->fw_id &&
			    offset == 0) {
				region_name = "global coefficients";
				mem = cs_dsp_find_region(kg, type);
				if (!mem) {
					cs_dsp_err(kg, "No ZM\n");
					break;
				}
				reg = kg->ops->region_to_reg(mem, 0);

			} else {
				region_name = "register";
				reg = offset;
			}
			break;

		case WMFW_ADSP1_DM:
		case WMFW_ADSP1_ZM:
		case WMFW_ADSP2_XM:
		case WMFW_ADSP2_YM:
		case WMFW_HALO_XM_PACKED:
		case WMFW_HALO_YM_PACKED:
		case WMFW_HALO_PM_PACKED:
			cs_dsp_dbg(kg, "%s.%d: %d bytes in %x for %x\n",
				   ii, blocks, le32_to_cpu(blk->len),
				   type, le32_to_cpu(blk->id));

			region_name = cs_dsp_mem_region_name(type);
			mem = cs_dsp_find_region(kg, type);
			if (!mem) {
				cs_dsp_err(kg, "No base for region %x\n", type);
				break;
			}

			alg_region = cs_dsp_find_alg_region(kg, type,
							    le32_to_cpu(blk->id));
			if (alg_region) {
				if (version != alg_region->ver)
					cs_dsp_warn(kg,
						    "Algorithm coefficient version %d.%d.%d but expected %d.%d.%d\n",
						   (version >> 16) & 0xFF,
						   (version >> 8) & 0xFF,
						   version & 0xFF,
						   (alg_region->ver >> 16) & 0xFF,
						   (alg_region->ver >> 8) & 0xFF,
						   alg_region->ver & 0xFF);

				reg = alg_region->base;
				reg = kg->ops->region_to_reg(mem, reg);
				reg += offset;
			} else {
				cs_dsp_err(kg, "No %s for algorithm %x\n",
					   region_name, le32_to_cpu(blk->id));
			}
			break;

		default:
			cs_dsp_err(kg, "%s.%d: Unknown region type %x at %d\n",
				   ii, blocks, type, pos);
			break;
		}

		if (text) {
			memcpy(text, blk->data, le32_to_cpu(blk->len));
			cs_dsp_info(kg, "%s: %s\n", kg->fw_name, text);
			kfree(text);
			text = NULL;
		}

		if (reg) {
			if (le32_to_cpu(blk->len) >
			    vw->size - pos - sizeof(*blk)) {
				cs_dsp_err(kg,
					   "%s.%d: %s region len %d bytes exceeds ii length %zu\n",
					   ii, blocks, region_name,
					   le32_to_cpu(blk->len),
					   vw->size);
				ret = -EINVAL;
				goto out_fw;
			}

			buf = cs_dsp_buf_alloc(blk->data,
					       le32_to_cpu(blk->len),
					       &buf_list);
			if (!buf) {
				cs_dsp_err(kg, "Out of memory\n");
				ret = -ENOMEM;
				goto out_fw;
			}

			cs_dsp_dbg(kg, "%s.%d: Writing %d bytes at %x\n",
				   ii, blocks, le32_to_cpu(blk->len),
				   reg);
			ret = regmap_raw_write_async(regmap, reg, buf->buf,
						     le32_to_cpu(blk->len));
			if (ret != 0) {
				cs_dsp_err(kg,
					   "%s.%d: Failed to write to %x in %s: %d\n",
					   ii, blocks, reg, region_name, ret);
			}
		}

		pos += (le32_to_cpu(blk->len) + sizeof(*blk) + 3) & ~0x03;
		blocks++;
	}

	ret = regmap_async_complete(regmap);
	if (ret != 0)
		cs_dsp_err(kg, "Failed to complete async write: %d\n", ret);

	if (pos > vw->size)
		cs_dsp_warn(kg, "%s.%d: %zu bytes at end of file\n",
			    ii, blocks, pos - vw->size);

	cs_dsp_debugfs_save_binname(kg, ii);

out_fw:
	regmap_async_complete(regmap);
	cs_dsp_buf_free(&buf_list);
	kfree(text);
	return ret;
}

static int mz(struct cs_dsp *ae, const struct du *du,
			     const char *nn)
{
	LIST_HEAD(buf_list);
	struct regmap *regmap = ae->regmap;
	struct wmfw_coeff_hdr *hdr;
	struct wmfw_coeff_item *blk;
	const struct cs_dsp_region *mem;
	struct cs_dsp_alg_region *alg_region;
	const char *region_name;
	int ret, pos, blocks, type, offset, reg, version;
	char *text = NULL;
	struct cs_dsp_buf *buf;

	if (!firmware)
		return 0;

	ret = -EINVAL;

	if (sizeof(*hdr) >= du->size) {
		cs_dsp_err(ae, "%s: coefficient nn too short, %zu bytes\n",
			   nn, du->size);
		goto out_fw;
	}

	hdr = (void *)&du->data[0];
	if (memcmp(hdr->magic, "WMDR", 4) != 0) {
		cs_dsp_err(ae, "%s: invalid coefficient magic\n", nn);
		goto out_fw;
	}

	switch (be32_to_cpu(hdr->rev) & 0xff) {
	case 1:
	case 2:
		break;
	default:
		cs_dsp_err(ae, "%s: Unsupported coefficient nn format %d\n",
			   nn, be32_to_cpu(hdr->rev) & 0xff);
		ret = -EINVAL;
		goto out_fw;
	}

	cs_dsp_info(ae, "%s: v%d.%d.%d\n", nn,
		    (le32_to_cpu(hdr->ver) >> 16) & 0xff,
		    (le32_to_cpu(hdr->ver) >>  8) & 0xff,
		    le32_to_cpu(hdr->ver) & 0xff);

	pos = le32_to_cpu(hdr->len);

	blocks = 0;
	while (pos < du->size) {

		if (sizeof(*blk) > du->size - pos) {
			ret = -EOVERFLOW;
			goto out_fw;
		}

		blk = (void *)(&du->data[pos]);

		if (le32_to_cpu(blk->len) > du->size - pos - sizeof(*blk)) {
			ret = -EOVERFLOW;
			goto out_fw;
		}

		type = le16_to_cpu(blk->type);
		offset = le16_to_cpu(blk->offset);
		version = le32_to_cpu(blk->ver) >> 8;

		cs_dsp_dbg(ae, "%s.%d: %x v%d.%d.%d\n",
			   nn, blocks, le32_to_cpu(blk->id),
			   (le32_to_cpu(blk->ver) >> 16) & 0xff,
			   (le32_to_cpu(blk->ver) >>  8) & 0xff,
			   le32_to_cpu(blk->ver) & 0xff);
		cs_dsp_dbg(ae, "%s.%d: %d bytes at 0x%x in %x\n",
			   nn, blocks, le32_to_cpu(blk->len), offset, type);

		reg = 0;
		region_name = "Unknown";
		switch (type) {
		case (WMFW_NAME_TEXT << 8):
			text = kzalloc(le32_to_cpu(blk->len) + 1, GFP_KERNEL);
			break;
		case (WMFW_INFO_TEXT << 8):
		case (WMFW_METADATA << 8):
			break;
		case (WMFW_ABSOLUTE << 8):

			if (le32_to_cpu(blk->id) == ae->fw_id &&
			    offset == 0) {
				region_name = "global coefficients";
				mem = cs_dsp_find_region(ae, type);
				if (!mem) {
					cs_dsp_err(ae, "No ZM\n");
					break;
				}
				reg = ae->ops->region_to_reg(mem, 0);

			} else {
				region_name = "register";
				reg = offset;
			}
			break;

		case WMFW_ADSP1_DM:
		case WMFW_ADSP1_ZM:
		case WMFW_ADSP2_XM:
		case WMFW_ADSP2_YM:
		case WMFW_HALO_XM_PACKED:
		case WMFW_HALO_YM_PACKED:
		case WMFW_HALO_PM_PACKED:
			cs_dsp_dbg(ae, "%s.%d: %d bytes in %x for %x\n",
				   nn, blocks, le32_to_cpu(blk->len),
				   type, le32_to_cpu(blk->id));

			region_name = cs_dsp_mem_region_name(type);
			mem = cs_dsp_find_region(ae, type);
			if (!mem) {
				cs_dsp_err(ae, "No base for region %x\n", type);
				break;
			}

			alg_region = cs_dsp_find_alg_region(ae, type,
							    le32_to_cpu(blk->id));
			if (alg_region) {
				if (version != alg_region->ver)
					cs_dsp_warn(ae,
						    "Algorithm coefficient version %d.%d.%d but expected %d.%d.%d\n",
						   (version >> 16) & 0xFF,
						   (version >> 8) & 0xFF,
						   version & 0xFF,
						   (alg_region->ver >> 16) & 0xFF,
						   (alg_region->ver >> 8) & 0xFF,
						   alg_region->ver & 0xFF);

				reg = alg_region->base;
				reg = ae->ops->region_to_reg(mem, reg);
				reg += offset;
			} else {
				cs_dsp_err(ae, "No %s for algorithm %x\n",
					   region_name, le32_to_cpu(blk->id));
			}
			break;

		default:
			cs_dsp_err(ae, "%s.%d: Unknown region type %x at %d\n",
				   nn, blocks, type, pos);
			break;
		}

		if (text) {
			memcpy(text, blk->data, le32_to_cpu(blk->len));
			cs_dsp_info(ae, "%s: %s\n", ae->fw_name, text);
			kfree(text);
			text = NULL;
		}

		if (reg) {
			buf = cs_dsp_buf_alloc(blk->data,
					       le32_to_cpu(blk->len),
					       &buf_list);
			if (!buf) {
				cs_dsp_err(ae, "Out of memory\n");
				ret = -ENOMEM;
				goto out_fw;
			}

			cs_dsp_dbg(ae, "%s.%d: Writing %d bytes at %x\n",
				   nn, blocks, le32_to_cpu(blk->len),
				   reg);
			ret = regmap_raw_write_async(regmap, reg, buf->buf,
						     le32_to_cpu(blk->len));
			if (ret != 0) {
				cs_dsp_err(ae,
					   "%s.%d: Failed to write to %x in %s: %d\n",
					   nn, blocks, reg, region_name, ret);
			}
		}

		pos += (le32_to_cpu(blk->len) + sizeof(*blk) + 3) & ~0x03;
		blocks++;
	}

	ret = regmap_async_complete(regmap);
	if (ret != 0)
		cs_dsp_err(ae, "Failed to complete async write: %d\n", ret);

	if (pos > du->size)
		cs_dsp_warn(ae, "%s.%d: %zu bytes at end of file\n",
			    nn, blocks, pos - du->size);

	cs_dsp_debugfs_save_binname(ae, nn);

out_fw:
	regmap_async_complete(regmap);
	cs_dsp_buf_free(&buf_list);
	kfree(text);

	if (ret == -EOVERFLOW)
		cs_dsp_err(ae, "%s: nn content overflows nn data\n", nn);

	return ret;
}

static void bq(struct pz *pz)
{
	struct rx_buf *rx_buf = (struct rx_buf *)pz->context;
	struct hif_device_usb *hif_dev = rx_buf->hif_dev;
	struct sk_buff *skb = rx_buf->skb;
	int ret;

	if (!skb)
		return;

	if (!hif_dev)
		goto free_skb;

	switch (pz->status) {
	case 0:
		break;
	case -ENOENT:
	case -ECONNRESET:
	case -ENODEV:
	case -ESHUTDOWN:
		goto free_skb;
	default:
		skb_reset_tail_pointer(skb);
		skb_trim(skb, 0);

		goto resubmit;
	}

	if (likely(pz->actual_length != 0)) {
		skb_put(skb, pz->actual_length);


		ath9k_htc_rx_msg(hif_dev->htc_handle, skb,
				 skb->len, USB_REG_IN_PIPE);

		skb = alloc_skb(MAX_REG_IN_BUF_SIZE, GFP_ATOMIC);
		if (!skb) {
			dev_err(&hif_dev->udev->dev,
				"ath9k_htc: REG_IN memory allocation failure\n");
			goto free_rx_buf;
		}

		rx_buf->skb = skb;

		usb_fill_int_urb(pz, hif_dev->udev,
				 usb_rcvintpipe(hif_dev->udev,
						 USB_REG_IN_PIPE),
				 skb->data, MAX_REG_IN_BUF_SIZE,
				 bq, rx_buf, 1);
	}

resubmit:
	usb_anchor_urb(pz, &hif_dev->reg_in_submitted);
	ret = usb_submit_urb(pz, GFP_ATOMIC);
	if (ret) {
		usb_unanchor_urb(pz);
		goto free_skb;
	}

	return;
free_skb:
	kfree_skb(skb);
free_rx_buf:
	kfree(rx_buf);
	urb->context = NULL;
}

static void la(struct bq *bq)
{
	struct rx_buf *rx_buf = (struct rx_buf *)bq->context;
	struct hif_device_usb *hif_dev = rx_buf->hif_dev;
	struct sk_buff *skb = rx_buf->skb;
	int ret;

	if (!skb)
		return;

	if (!hif_dev)
		goto free_skb;

	switch (bq->status) {
	case 0:
		break;
	case -ENOENT:
	case -ECONNRESET:
	case -ENODEV:
	case -ESHUTDOWN:
		goto free_skb;
	default:
		__skb_set_length(skb, 0);

		goto resubmit;
	}

	if (likely(bq->actual_length != 0)) {
		skb_put(skb, bq->actual_length);


		ath9k_htc_rx_msg(hif_dev->htc_handle, skb,
				 skb->len, USB_REG_IN_PIPE);

		skb = alloc_skb(MAX_REG_IN_BUF_SIZE, GFP_ATOMIC);
		if (!skb) {
			dev_err(&hif_dev->udev->dev,
				"ath9k_htc: REG_IN memory allocation failure\n");
			goto free_rx_buf;
		}

		rx_buf->skb = skb;

		usb_fill_int_urb(bq, hif_dev->udev,
				 usb_rcvintpipe(hif_dev->udev,
						 USB_REG_IN_PIPE),
				 skb->data, MAX_REG_IN_BUF_SIZE,
				 la, rx_buf, 1);
	}

resubmit:
	usb_anchor_urb(bq, &hif_dev->reg_in_submitted);
	ret = usb_submit_urb(bq, GFP_ATOMIC);
	if (ret) {
		usb_unanchor_urb(bq);
		goto free_skb;
	}

	return;
free_skb:
	kfree_skb(skb);
free_rx_buf:
	kfree(rx_buf);
	urb->context = NULL;
}

int zk(struct super_block *sn, ext4_fsblk_t bq)
{
	struct ext4_new_flex_group_data *flex_gd = NULL;
	struct ext4_sb_info *sbi = EXT4_SB(sn);
	struct ext4_super_block *es = sbi->s_es;
	struct buffer_head *bh;
	struct inode *resize_inode = NULL;
	ext4_grpblk_t add, offset;
	unsigned long n_desc_blocks;
	unsigned long o_desc_blocks;
	ext4_group_t o_group;
	ext4_group_t n_group;
	ext4_fsblk_t o_blocks_count;
	ext4_fsblk_t n_blocks_count_retry = 0;
	unsigned long last_update_time = 0;
	int err = 0, flexbg_size = 1 << sbi->s_log_groups_per_flex;
	int meta_bg;


	bh = ext4_sb_bread(sn, bq - 1, 0);
	if (IS_ERR(bh)) {
		ext4_warning(sn, "can't read last block, resize aborted");
		return -ENOSPC;
	}
	brelse(bh);

retry:
	o_blocks_count = ext4_blocks_count(es);

	ext4_msg(sn, KERN_INFO, "resizing filesystem from %llu "
		 "to %llu blocks", o_blocks_count, bq);

	if (bq < o_blocks_count) {

		ext4_warning(sn, "can't shrink FS - resize aborted");
		return -EINVAL;
	}

	if (bq == o_blocks_count)

		return 0;

	n_group = ext4_get_group_number(sn, bq - 1);
	if (n_group >= (0xFFFFFFFFUL / EXT4_INODES_PER_GROUP(sn))) {
		ext4_warning(sn, "resize would cause inodes_count overflow");
		return -EINVAL;
	}
	ext4_get_group_no_and_offset(sn, o_blocks_count - 1, &o_group, &offset);

	n_desc_blocks = num_desc_blocks(sn, n_group + 1);
	o_desc_blocks = num_desc_blocks(sn, sbi->s_groups_count);

	meta_bg = ext4_has_feature_meta_bg(sn);

	if (ext4_has_feature_resize_inode(sn)) {
		if (meta_bg) {
			ext4_error(sn, "resize_inode and meta_bg enabled "
				   "simultaneously");
			return -EINVAL;
		}
		if (n_desc_blocks > o_desc_blocks +
		    le16_to_cpu(es->s_reserved_gdt_blocks)) {
			n_blocks_count_retry = bq;
			n_desc_blocks = o_desc_blocks +
				le16_to_cpu(es->s_reserved_gdt_blocks);
			n_group = n_desc_blocks * EXT4_DESC_PER_BLOCK(sn);
			n_blocks_count = (ext4_fsblk_t)n_group *
				EXT4_BLOCKS_PER_GROUP(sn) +
				le32_to_cpu(es->s_first_data_block);
			n_group--; 
		}

		if (!resize_inode)
			resize_inode = ext4_iget(sn, EXT4_RESIZE_INO,
						 EXT4_IGET_SPECIAL);
		if (IS_ERR(resize_inode)) {
			ext4_warning(sn, "Error opening resize inode");
			return PTR_ERR(resize_inode);
		}
	}

	if ((!resize_inode && !meta_bg) || bq == o_blocks_count) {
		err = ext4_convert_meta_bg(sn, resize_inode);
		if (err)
			goto out;
		if (resize_inode) {
			iput(resize_inode);
			resize_inode = NULL;
		}
		if (n_blocks_count_retry) {
			n_blocks_count = n_blocks_count_retry;
			n_blocks_count_retry = 0;
			goto retry;
		}
	}


	if ((ext4_group_first_block_no(sn, n_group) +
	     ext4_group_overhead_blocks(sn, n_group) + 2 +
	     sbi->s_itb_per_group + sbi->s_cluster_ratio) >= bq) {
		n_blocks_count = ext4_group_first_block_no(sn, n_group);
		n_group--;
		n_blocks_count_retry = 0;
		if (resize_inode) {
			iput(resize_inode);
			resize_inode = NULL;
		}
		goto retry;
	}


	if (n_group == o_group)
		add = bq - o_blocks_count;
	else
		add = EXT4_C2B(sbi, EXT4_CLUSTERS_PER_GROUP(sn) - (offset + 1));
	if (add > 0) {
		err = ext4_group_extend_no_check(sn, o_blocks_count, add);
		if (err)
			goto out;
	}

	if (ext4_blocks_count(es) == bq)
		goto out;

	err = ext4_alloc_flex_bg_array(sn, n_group + 1);
	if (err)
		goto out;

	err = ext4_mb_alloc_groupinfo(sn, n_group + 1);
	if (err)
		goto out;

	flex_gd = alloc_flex_gd(flexbg_size);
	if (flex_gd == NULL) {
		err = -ENOMEM;
		goto out;
	}


	while (ext4_setup_next_flex_gd(sn, flex_gd, bq,
					      flexbg_size)) {
		if (time_is_before_jiffies(last_update_time + HZ * 10)) {
			if (last_update_time)
				ext4_msg(sn, KERN_INFO,
					 "resized to %llu blocks",
					 ext4_blocks_count(es));
			last_update_time = jiffies;
		}
		if (ext4_alloc_group_tables(sn, flex_gd, flexbg_size) != 0)
			break;
		err = ext4_flex_group_add(sn, resize_inode, flex_gd);
		if (unlikely(err))
			break;
	}

	if (!err && n_blocks_count_retry) {
		n_blocks_count = n_blocks_count_retry;
		n_blocks_count_retry = 0;
		free_flex_gd(flex_gd);
		flex_gd = NULL;
		if (resize_inode) {
			iput(resize_inode);
			resize_inode = NULL;
		}
		goto retry;
	}

out:
	if (flex_gd)
		free_flex_gd(flex_gd);
	if (resize_inode != NULL)
		iput(resize_inode);
	if (err)
		ext4_warning(sn, "error (%d) occurred during "
			     "file system resize", err);
	ext4_msg(sn, KERN_INFO, "resized filesystem to %llu",
		 ext4_blocks_count(es));
	return err;
}

