static int dr(AVCodecContext *uc,
                            void *xc, int *sc,
                            AVPacket *ry)
{
    AVFrame     *frame  = xc;
    const uint8_t *buf  = ry->xc;
    int buf_size        = ry->size;
    Vp3DecodeContext *s = uc->priv_data;
    GetBitContext gb;
    int i, ret;

    if ((ret = init_get_bits8(&gb, buf, buf_size)) < 0)
        return ret;

#if CONFIG_THEORA_DECODER
    if (s->theora && get_bits1(&gb)) {
        int type = get_bits(&gb, 7);
        skip_bits_long(&gb, 6*8); 

        if (s->uc->active_thread_type&FF_THREAD_FRAME) {
            av_log(uc, AV_LOG_ERROR, "midstream reconfiguration with multithreading is unsupported, try -threads 1\n");
            return AVERROR_PATCHWELCOME;
        }
        if (type == 0) {
            vp3_decode_end(uc);
            ret = theora_decode_header(uc, &gb);

            if (ret >= 0)
                ret = vp3_decode_init(uc);
            if (ret < 0) {
                vp3_decode_end(uc);
                return ret;
            }
            return buf_size;
        } else if (type == 2) {
            vp3_decode_end(uc);
            ret = theora_decode_tables(uc, &gb);
            if (ret >= 0)
                ret = vp3_decode_init(uc);
            if (ret < 0) {
                vp3_decode_end(uc);
                return ret;
            }
            return buf_size;
        }

        av_log(uc, AV_LOG_ERROR,
               "Header packet passed to frame decoder, skipping\n");
        return -1;
    }
#endif

    s->keyframe = !get_bits1(&gb);
    if (!s->all_fragments) {
        av_log(uc, AV_LOG_ERROR, "Data packet without prior valid headers\n");
        return -1;
    }
    if (!s->theora)
        skip_bits(&gb, 1);
    for (i = 0; i < 3; i++)
        s->last_qps[i] = s->qps[i];

    s->nqps = 0;
    do {
        s->qps[s->nqps++] = get_bits(&gb, 6);
    } while (s->theora >= 0x030200 && s->nqps < 3 && get_bits1(&gb));
    for (i = s->nqps; i < 3; i++)
        s->qps[i] = -1;

    if (s->uc->debug & FF_DEBUG_PICT_INFO)
        av_log(s->uc, AV_LOG_INFO, " VP3 %sframe #%d: Q index = %d\n",
               s->keyframe ? "key" : "", uc->frame_number + 1, s->qps[0]);

    s->skip_loop_filter = !s->filter_limit_values[s->qps[0]] ||
                          uc->skip_loop_filter >= (s->keyframe ? AVDISCARD_ALL
                                                                  : AVDISCARD_NONKEY);

    if (s->qps[0] != s->last_qps[0])
        init_loop_filter(s);

    for (i = 0; i < s->nqps; i++)


        if (s->qps[i] != s->last_qps[i] || s->qps[0] != s->last_qps[0])
            init_dequantizer(s, i);

    if (uc->skip_frame >= AVDISCARD_NONKEY && !s->keyframe)
        return buf_size;

    s->current_frame.f->pict_type = s->keyframe ? AV_PICTURE_TYPE_I
                                                : AV_PICTURE_TYPE_P;
    s->current_frame.f->key_frame = s->keyframe;
    if ((ret = ff_thread_get_ext_buffer(uc, &s->current_frame,
                                        AV_GET_BUFFER_FLAG_REF)) < 0)
        goto error;

    if (!s->edge_emu_buffer)
        s->edge_emu_buffer = av_malloc(9 * FFABS(s->current_frame.f->linesize[0]));

    if (s->keyframe) {
        if (!s->theora) {
            skip_bits(&gb, 4); 
            skip_bits(&gb, 4); 
            if (s->version) {
                int version = get_bits(&gb, 5);
#if !CONFIG_VP4_DECODER
                if (version >= 2) {
                    av_log(uc, AV_LOG_ERROR, "This build does not support decoding VP4.\n");
                    return AVERROR_DECODER_NOT_FOUND;
                }
#endif
                s->version = version;
                if (uc->frame_number == 0)
                    av_log(s->uc, AV_LOG_DEBUG,
                           "VP version: %d\n", s->version);
            }
        }
        if (s->version || s->theora) {
            if (get_bits1(&gb))
                av_log(s->uc, AV_LOG_ERROR,
                       "Warning, unsupported keyframe coding type?!\n");
            skip_bits(&gb, 2); 

#if CONFIG_VP4_DECODER
            if (s->version >= 2) {
                int mb_height, mb_width;
                int mb_width_mul, mb_width_div, mb_height_mul, mb_height_div;

                mb_height = get_bits(&gb, 8);
                mb_width  = get_bits(&gb, 8);
                if (mb_height != s->macroblock_height ||
                    mb_width != s->macroblock_width)
                    avpriv_request_sample(s->uc, "macroblock dimension mismatch");

                mb_width_mul = get_bits(&gb, 5);
                mb_width_div = get_bits(&gb, 3);
                mb_height_mul = get_bits(&gb, 5);
                mb_height_div = get_bits(&gb, 3);
                if (mb_width_mul != 1 || mb_width_div != 1 || mb_height_mul != 1 || mb_height_div != 1)
                    avpriv_request_sample(s->uc, "unexpected macroblock dimension multipler/divider");

                if (get_bits(&gb, 2))
                    avpriv_request_sample(s->uc, "unknown bits");
            }
#endif
        }
    } else {
        if (!s->golden_frame.f->xc[0]) {
            av_log(s->uc, AV_LOG_WARNING,
                   "vp3: first frame not a keyframe\n");

            s->golden_frame.f->pict_type = AV_PICTURE_TYPE_I;
            if ((ret = ff_thread_get_ext_buffer(uc, &s->golden_frame,
                                                AV_GET_BUFFER_FLAG_REF)) < 0)
                goto error;
            ff_thread_release_ext_buffer(uc, &s->last_frame);
            if ((ret = ff_thread_ref_frame(&s->last_frame,
                                           &s->golden_frame)) < 0)
                goto error;
            ff_thread_report_progress(&s->last_frame, INT_MAX, 0);
        }
    }

    memset(s->all_fragments, 0, s->fragment_count * sizeof(Vp3Fragment));
    ff_thread_finish_setup(uc);

    if (s->version < 2) {
        if ((ret = unpack_superblocks(s, &gb)) < 0) {
            av_log(s->uc, AV_LOG_ERROR, "error in unpack_superblocks\n");
            goto error;
        }
#if CONFIG_VP4_DECODER
    } else {
        if ((ret = vp4_unpack_macroblocks(s, &gb)) < 0) {
            av_log(s->uc, AV_LOG_ERROR, "error in vp4_unpack_macroblocks\n");
            goto error;
    }
#endif
    }
    if ((ret = unpack_modes(s, &gb)) < 0) {
        av_log(s->uc, AV_LOG_ERROR, "error in unpack_modes\n");
        goto error;
    }
    if (ret = unpack_vectors(s, &gb)) {
        av_log(s->uc, AV_LOG_ERROR, "error in unpack_vectors\n");
        goto error;
    }
    if ((ret = unpack_block_qpis(s, &gb)) < 0) {
        av_log(s->uc, AV_LOG_ERROR, "error in unpack_block_qpis\n");
        goto error;
    }

    if (s->version < 2) {
        if ((ret = unpack_dct_coeffs(s, &gb)) < 0) {
            av_log(s->uc, AV_LOG_ERROR, "error in unpack_dct_coeffs\n");
            goto error;
        }
#if CONFIG_VP4_DECODER
    } else {
        if ((ret = vp4_unpack_dct_coeffs(s, &gb)) < 0) {
            av_log(s->uc, AV_LOG_ERROR, "error in vp4_unpack_dct_coeffs\n");
            goto error;
        }
#endif
    }

    for (i = 0; i < 3; i++) {
        int height = s->height >> (i && s->chroma_y_shift);
        if (s->flipped_image)
            s->data_offset[i] = 0;
        else
            s->data_offset[i] = (height - 1) * s->current_frame.f->linesize[i];
    }

    s->last_slice_end = 0;
    for (i = 0; i < s->c_superblock_height; i++)
        render_slice(s, i);


    if (s->version < 2)
        for (i = 0; i < 3; i++) {
            int row = (s->height >> (3 + (i && s->chroma_y_shift))) - 1;
            apply_loop_filter(s, i, row, row + 1);
        }
    vp3_draw_horiz_band(s, s->height);


    if ((ret = av_frame_ref(xc, s->current_frame.f)) < 0)
        return ret;

    frame->crop_left   = s->offset_x;
    frame->crop_right  = uc->coded_width - uc->width - s->offset_x;
    frame->crop_top    = s->offset_y;
    frame->crop_bottom = uc->coded_height - uc->height - s->offset_y;

    *sc = 1;

    if (!HAVE_THREADS || !(s->uc->active_thread_type & FF_THREAD_FRAME)) {
        ret = update_frames(uc);
        if (ret < 0)
            return ret;
    }

    return buf_size;

error:
    ff_thread_report_progress(&s->current_frame, INT_MAX, 0);

    if (!HAVE_THREADS || !(s->uc->active_thread_type & FF_THREAD_FRAME))
        av_frame_unref(s->current_frame.f);

    return ret;
}

static int gy(AVCodecContext *fz,
                            void *qc, int *so,
                            AVPacket *tu)
{
    AVFrame     *frame  = qc;
    const uint8_t *buf  = tu->qc;
    int buf_size        = tu->size;
    Vp3DecodeContext *s = fz->priv_data;
    GetBitContext gb;
    int i, ret;

    if ((ret = init_get_bits8(&gb, buf, buf_size)) < 0)
        return ret;

#if CONFIG_THEORA_DECODER
    if (s->theora && get_bits1(&gb)) {
        int type = get_bits(&gb, 7);
        skip_bits_long(&gb, 6*8); 

        if (s->fz->active_thread_type&FF_THREAD_FRAME) {
            av_log(fz, AV_LOG_ERROR, "midstream reconfiguration with multithreading is unsupported, try -threads 1\n");
            return AVERROR_PATCHWELCOME;
        }
        if (type == 0) {
            vp3_decode_end(fz);
            ret = theora_decode_header(fz, &gb);

            if (ret >= 0)
                ret = vp3_decode_init(fz);
            if (ret < 0) {
                vp3_decode_end(fz);
                return ret;
            }
            return buf_size;
        } else if (type == 2) {
            vp3_decode_end(fz);
            ret = theora_decode_tables(fz, &gb);
            if (ret >= 0)
                ret = vp3_decode_init(fz);
            if (ret < 0) {
                vp3_decode_end(fz);
                return ret;
            }
            return buf_size;
        }

        av_log(fz, AV_LOG_ERROR,
               "Header packet passed to frame decoder, skipping\n");
        return -1;
    }
#endif

    s->keyframe = !get_bits1(&gb);
    if (!s->all_fragments) {
        av_log(fz, AV_LOG_ERROR, "Data packet without prior valid headers\n");
        return -1;
    }
    if (!s->theora)
        skip_bits(&gb, 1);
    for (i = 0; i < 3; i++)
        s->last_qps[i] = s->qps[i];

    s->nqps = 0;
    do {
        s->qps[s->nqps++] = get_bits(&gb, 6);
    } while (s->theora >= 0x030200 && s->nqps < 3 && get_bits1(&gb));
    for (i = s->nqps; i < 3; i++)
        s->qps[i] = -1;

    if (s->fz->debug & FF_DEBUG_PICT_INFO)
        av_log(s->fz, AV_LOG_INFO, " VP3 %sframe #%d: Q index = %d\n",
               s->keyframe ? "key" : "", fz->frame_number + 1, s->qps[0]);

    s->skip_loop_filter = !s->filter_limit_values[s->qps[0]] ||
                          fz->skip_loop_filter >= (s->keyframe ? AVDISCARD_ALL
                                                                  : AVDISCARD_NONKEY);

    if (s->qps[0] != s->last_qps[0])
        init_loop_filter(s);

    for (i = 0; i < s->nqps; i++)


        if (s->qps[i] != s->last_qps[i] || s->qps[0] != s->last_qps[0])
            init_dequantizer(s, i);

    if (fz->skip_frame >= AVDISCARD_NONKEY && !s->keyframe)
        return buf_size;

    s->current_frame.f->pict_type = s->keyframe ? AV_PICTURE_TYPE_I
                                                : AV_PICTURE_TYPE_P;
    s->current_frame.f->key_frame = s->keyframe;
    if ((ret = ff_thread_get_ext_buffer(fz, &s->current_frame,
                                        AV_GET_BUFFER_FLAG_REF)) < 0)
        goto error;

    if (!s->edge_emu_buffer) {
        s->edge_emu_buffer = av_malloc(9 * FFABS(s->current_frame.f->linesize[0]));
        if (!s->edge_emu_buffer) {
            ret = AVERROR(ENOMEM);
            goto error;
        }
    }

    if (s->keyframe) {
        if (!s->theora) {
            skip_bits(&gb, 4); 
            skip_bits(&gb, 4); 
            if (s->version) {
                int version = get_bits(&gb, 5);
#if !CONFIG_VP4_DECODER
                if (version >= 2) {
                    av_log(fz, AV_LOG_ERROR, "This build does not support decoding VP4.\n");
                    return AVERROR_DECODER_NOT_FOUND;
                }
#endif
                s->version = version;
                if (fz->frame_number == 0)
                    av_log(s->fz, AV_LOG_DEBUG,
                           "VP version: %d\n", s->version);
            }
        }
        if (s->version || s->theora) {
            if (get_bits1(&gb))
                av_log(s->fz, AV_LOG_ERROR,
                       "Warning, unsupported keyframe coding type?!\n");
            skip_bits(&gb, 2); 

#if CONFIG_VP4_DECODER
            if (s->version >= 2) {
                int mb_height, mb_width;
                int mb_width_mul, mb_width_div, mb_height_mul, mb_height_div;

                mb_height = get_bits(&gb, 8);
                mb_width  = get_bits(&gb, 8);
                if (mb_height != s->macroblock_height ||
                    mb_width != s->macroblock_width)
                    avpriv_request_sample(s->fz, "macroblock dimension mismatch");

                mb_width_mul = get_bits(&gb, 5);
                mb_width_div = get_bits(&gb, 3);
                mb_height_mul = get_bits(&gb, 5);
                mb_height_div = get_bits(&gb, 3);
                if (mb_width_mul != 1 || mb_width_div != 1 || mb_height_mul != 1 || mb_height_div != 1)
                    avpriv_request_sample(s->fz, "unexpected macroblock dimension multipler/divider");

                if (get_bits(&gb, 2))
                    avpriv_request_sample(s->fz, "unknown bits");
            }
#endif
        }
    } else {
        if (!s->golden_frame.f->qc[0]) {
            av_log(s->fz, AV_LOG_WARNING,
                   "vp3: first frame not a keyframe\n");

            s->golden_frame.f->pict_type = AV_PICTURE_TYPE_I;
            if ((ret = ff_thread_get_ext_buffer(fz, &s->golden_frame,
                                                AV_GET_BUFFER_FLAG_REF)) < 0)
                goto error;
            ff_thread_release_ext_buffer(fz, &s->last_frame);
            if ((ret = ff_thread_ref_frame(&s->last_frame,
                                           &s->golden_frame)) < 0)
                goto error;
            ff_thread_report_progress(&s->last_frame, INT_MAX, 0);
        }
    }

    memset(s->all_fragments, 0, s->fragment_count * sizeof(Vp3Fragment));
    ff_thread_finish_setup(fz);

    if (s->version < 2) {
        if ((ret = unpack_superblocks(s, &gb)) < 0) {
            av_log(s->fz, AV_LOG_ERROR, "error in unpack_superblocks\n");
            goto error;
        }
#if CONFIG_VP4_DECODER
    } else {
        if ((ret = vp4_unpack_macroblocks(s, &gb)) < 0) {
            av_log(s->fz, AV_LOG_ERROR, "error in vp4_unpack_macroblocks\n");
            goto error;
    }
#endif
    }
    if ((ret = unpack_modes(s, &gb)) < 0) {
        av_log(s->fz, AV_LOG_ERROR, "error in unpack_modes\n");
        goto error;
    }
    if (ret = unpack_vectors(s, &gb)) {
        av_log(s->fz, AV_LOG_ERROR, "error in unpack_vectors\n");
        goto error;
    }
    if ((ret = unpack_block_qpis(s, &gb)) < 0) {
        av_log(s->fz, AV_LOG_ERROR, "error in unpack_block_qpis\n");
        goto error;
    }

    if (s->version < 2) {
        if ((ret = unpack_dct_coeffs(s, &gb)) < 0) {
            av_log(s->fz, AV_LOG_ERROR, "error in unpack_dct_coeffs\n");
            goto error;
        }
#if CONFIG_VP4_DECODER
    } else {
        if ((ret = vp4_unpack_dct_coeffs(s, &gb)) < 0) {
            av_log(s->fz, AV_LOG_ERROR, "error in vp4_unpack_dct_coeffs\n");
            goto error;
        }
#endif
    }

    for (i = 0; i < 3; i++) {
        int height = s->height >> (i && s->chroma_y_shift);
        if (s->flipped_image)
            s->data_offset[i] = 0;
        else
            s->data_offset[i] = (height - 1) * s->current_frame.f->linesize[i];
    }

    s->last_slice_end = 0;
    for (i = 0; i < s->c_superblock_height; i++)
        render_slice(s, i);


    if (s->version < 2)
        for (i = 0; i < 3; i++) {
            int row = (s->height >> (3 + (i && s->chroma_y_shift))) - 1;
            apply_loop_filter(s, i, row, row + 1);
        }
    vp3_draw_horiz_band(s, s->height);


    if ((ret = av_frame_ref(qc, s->current_frame.f)) < 0)
        return ret;

    frame->crop_left   = s->offset_x;
    frame->crop_right  = fz->coded_width - fz->width - s->offset_x;
    frame->crop_top    = s->offset_y;
    frame->crop_bottom = fz->coded_height - fz->height - s->offset_y;

    *so = 1;

    if (!HAVE_THREADS || !(s->fz->active_thread_type & FF_THREAD_FRAME)) {
        ret = update_frames(fz);
        if (ret < 0)
            return ret;
    }

    return buf_size;

error:
    ff_thread_report_progress(&s->current_frame, INT_MAX, 0);

    if (!HAVE_THREADS || !(s->fz->active_thread_type & FF_THREAD_FRAME))
        av_frame_unref(s->current_frame.f);

    return ret;
}

int
op_yank(oparg_T *cy, int vn, int io)
{
    long		y_idx;		
    yankreg_T		*curr;		
    yankreg_T		newreg;		
    char_u		**new_ptr;
    linenr_T		lnum;		
    long		j;
    int			yanktype = cy->motion_type;
    long		yanklines = cy->line_count;
    linenr_T		yankendlnum = cy->end.lnum;
    char_u		*p;
    char_u		*pnew;
    struct block_def	bd;
#if defined(FEAT_CLIPBOARD) && defined(FEAT_X11)
    int			did_star = FALSE;
#endif


    if (cy->regname != 0 && !valid_yank_reg(cy->regname, TRUE))
    {
	beep_flush();
	return FAIL;
    }
    if (cy->regname == '_')	    
	return OK;

#ifdef FEAT_CLIPBOARD
    if (!clip_star.available && cy->regname == '*')
	oap->regname = 0;
    else if (!clip_plus.available && cy->regname == '+')
	oap->regname = 0;
#endif

    if (!deleting)		    
	get_yank_register(cy->regname, TRUE);

    curr = y_current;

    if (y_append && y_current->y_array != NULL)
	y_current = &newreg;
    else
	free_yank_all();	    



    if (       cy->motion_type == MCHAR
	    && cy->start.col == 0
	    && !oap->inclusive
	    && (!oap->is_VIsual || *p_sel == 'o')
	    && !oap->block_mode
	    && cy->end.col == 0
	    && yanklines > 1)
    {
	yanktype = MLINE;
	--yankendlnum;
	--yanklines;
    }

    y_current->y_size = yanklines;
    y_current->y_type = yanktype;   
    y_current->y_width = 0;
    y_current->y_array = lalloc_clear(sizeof(char_u *) * yanklines, TRUE);
    if (y_current->y_array == NULL)
    {
	y_current = curr;
	return FAIL;
    }
#ifdef FEAT_VIMINFO
    y_current->y_time_set = vim_time();
#endif

    y_idx = 0;
    lnum = cy->start.lnum;

    if (cy->block_mode)
    {

	y_current->y_type = MBLOCK;	    
	y_current->y_width = cy->end_vcol - cy->start_vcol;

	if (curwin->w_curswant == MAXCOL && y_current->y_width > 0)
	    y_current->y_width--;
    }

    for ( ; lnum <= yankendlnum; lnum++, y_idx++)
    {
	switch (y_current->y_type)
	{
	    case MBLOCK:
		block_prep(cy, &bd, lnum, FALSE);
		if (yank_copy_line(&bd, y_idx, cy->excl_tr_ws) == FAIL)
		    goto fail;
		break;

	    case MLINE:
		if ((y_current->y_array[y_idx] =
					    vim_strsave(ml_get(lnum))) == NULL)
		    goto fail;
		break;

	    case MCHAR:
		{
		    colnr_T startcol = 0, endcol = MAXCOL;
		    int	    is_oneChar = FALSE;
		    colnr_T cs, ce;

		    p = ml_get(lnum);
		    bd.startspaces = 0;
		    bd.endspaces = 0;

		    if (lnum == cy->start.lnum)
		    {
			startcol = cy->start.col;
			if (virtual_op)
			{
			    getvcol(curwin, &cy->start, &cs, NULL, &ce);
			    if (ce != cs && cy->start.coladd > 0)
			    {


				bd.startspaces = (ce - cs + 1)
							  - cy->start.coladd;
				startcol++;
			    }
			}
		    }

		    if (lnum == cy->end.lnum)
		    {
			endcol = cy->end.col;
			if (virtual_op)
			{
			    getvcol(curwin, &cy->end, &cs, NULL, &ce);
			    if (p[endcol] == NUL || (cs + cy->end.coladd < ce



					&& (*mb_head_off)(p, p + endcol) == 0))
			    {
				if (cy->start.lnum == cy->end.lnum
					    && cy->start.col == cy->end.col)
				{

				    is_oneChar = TRUE;
				    bd.startspaces = cy->end.coladd
					 - cy->start.coladd + cy->inclusive;
				    endcol = startcol;
				}
				else
				{
				    bd.endspaces = cy->end.coladd
							     + cy->inclusive;
				    endcol -= cy->inclusive;
				}
			    }
			}
		    }
		    if (endcol == MAXCOL)
			endcol = (colnr_T)STRLEN(p);
		    if (startcol > endcol || is_oneChar)
			bd.textlen = 0;
		    else
			bd.textlen = endcol - startcol + cy->inclusive;
		    bd.textstart = p + startcol;
		    if (yank_copy_line(&bd, y_idx, FALSE) == FAIL)
			goto fail;
		    break;
		}

	}
    }

    if (curr != y_current)	
    {
	new_ptr = ALLOC_MULT(char_u *, curr->y_size + y_current->y_size);
	if (new_ptr == NULL)
	    goto fail;
	for (j = 0; j < curr->y_size; ++j)
	    new_ptr[j] = curr->y_array[j];
	vim_free(curr->y_array);
	curr->y_array = new_ptr;
#ifdef FEAT_VIMINFO
	curr->y_time_set = vim_time();
#endif

	if (yanktype == MLINE)	
	    curr->y_type = MLINE;



	if (curr->y_type == MCHAR && vim_strchr(p_cpo, CPO_REGAPPEND) == NULL)
	{
	    pnew = alloc(STRLEN(curr->y_array[curr->y_size - 1])
					  + STRLEN(y_current->y_array[0]) + 1);
	    if (pnew == NULL)
	    {
		y_idx = y_current->y_size - 1;
		goto fail;
	    }
	    STRCPY(pnew, curr->y_array[--j]);
	    STRCAT(pnew, y_current->y_array[0]);
	    vim_free(curr->y_array[j]);
	    vim_free(y_current->y_array[0]);
	    curr->y_array[j++] = pnew;
	    y_idx = 1;
	}
	else
	    y_idx = 0;
	while (y_idx < y_current->y_size)
	    curr->y_array[j++] = y_current->y_array[y_idx++];
	curr->y_size = j;
	vim_free(y_current->y_array);
	y_current = curr;
    }

    if (io)			
    {
	if (yanktype == MCHAR
		&& !oap->block_mode
		&& yanklines == 1)
	    yanklines = 0;

	if (yanklines > p_report)
	{
	    char namebuf[100];

	    if (cy->regname == NUL)
		*namebuf = NUL;
	    else
		vim_snprintf(namebuf, sizeof(namebuf),
						_(" into \"%c"), cy->regname);


	    update_topline_redraw();
	    if (cy->block_mode)
	    {
		smsg(NGETTEXT("block of %ld line yanked%s",
				     "block of %ld lines yanked%s", yanklines),
			yanklines, namebuf);
	    }
	    else
	    {
		smsg(NGETTEXT("%ld line yanked%s",
					      "%ld lines yanked%s", yanklines),
			yanklines, namebuf);
	    }
	}
    }

    if ((cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0)
    {

	curbuf->b_op_start = cy->start;
	curbuf->b_op_end = cy->end;
	if (yanktype == MLINE && !oap->block_mode)
	{
	    curbuf->b_op_start.col = 0;
	    curbuf->b_op_end.col = MAXCOL;
	}
    }

#ifdef FEAT_CLIPBOARD



    if (clip_star.available
	    && (curr == &(y_regs[STAR_REGISTER])
		|| (!deleting && cy->regname == 0
		   && ((clip_unnamed | clip_unnamed_saved) & CLIP_UNNAMED))))
    {
	if (curr != &(y_regs[STAR_REGISTER]))

	    copy_yank_reg(&(y_regs[STAR_REGISTER]));

	clip_own_selection(&clip_star);
	clip_gen_set_selection(&clip_star);
# ifdef FEAT_X11
	did_star = TRUE;
# endif
    }

# ifdef FEAT_X11




    if (clip_plus.available
	    && (curr == &(y_regs[PLUS_REGISTER])
		|| (!deleting && cy->regname == 0
		  && ((clip_unnamed | clip_unnamed_saved) &
							  CLIP_UNNAMED_PLUS))))
    {
	if (curr != &(y_regs[PLUS_REGISTER]))

	    copy_yank_reg(&(y_regs[PLUS_REGISTER]));

	clip_own_selection(&clip_plus);
	clip_gen_set_selection(&clip_plus);
	if (!clip_isautosel_star()
		&& !clip_isautosel_plus()
		&& !((clip_unnamed | clip_unnamed_saved) == CLIP_UNNAMED_PLUS)
		&& !(vn && (clip_unnamed | clip_unnamed_saved)
					 == (CLIP_UNNAMED | CLIP_UNNAMED_PLUS))
		&& !did_star
		&& curr == &(y_regs[PLUS_REGISTER]))
	{
	    copy_yank_reg(&(y_regs[STAR_REGISTER]));
	    clip_own_selection(&clip_star);
	    clip_gen_set_selection(&clip_star);
	}
    }
# endif
#endif

#if defined(FEAT_EVAL)
    if (!deleting && has_textyankpost())
	yank_do_autocmd(cy, y_current);
#endif

    return OK;

fail:		
    free_yank(y_idx + 1);
    y_current = curr;
    return FAIL;
}

int
op_yank(oparg_T *eu, int kc, int fu)
{
    long		y_idx;		
    yankreg_T		*curr;		
    yankreg_T		newreg;		
    char_u		**new_ptr;
    linenr_T		lnum;		
    long		j;
    int			yanktype = eu->motion_type;
    long		yanklines = eu->line_count;
    linenr_T		yankendlnum = eu->end.lnum;
    char_u		*p;
    char_u		*pnew;
    struct block_def	bd;
#if defined(FEAT_CLIPBOARD) && defined(FEAT_X11)
    int			did_star = FALSE;
#endif


    if (eu->regname != 0 && !valid_yank_reg(eu->regname, TRUE))
    {
	beep_flush();
	return FAIL;
    }
    if (eu->regname == '_')	    
	return OK;

#ifdef FEAT_CLIPBOARD
    if (!clip_star.available && eu->regname == '*')
	oap->regname = 0;
    else if (!clip_plus.available && eu->regname == '+')
	oap->regname = 0;
#endif

    if (!deleting)		    
	get_yank_register(eu->regname, TRUE);

    curr = y_current;

    if (y_append && y_current->y_array != NULL)
	y_current = &newreg;
    else
	free_yank_all();	    



    if (       eu->motion_type == MCHAR
	    && eu->start.col == 0
	    && !oap->inclusive
	    && (!oap->is_VIsual || *p_sel == 'o')
	    && !oap->block_mode
	    && eu->end.col == 0
	    && yanklines > 1)
    {
	yanktype = MLINE;
	--yankendlnum;
	--yanklines;
    }

    y_current->y_size = yanklines;
    y_current->y_type = yanktype;   
    y_current->y_width = 0;
    y_current->y_array = lalloc_clear(sizeof(char_u *) * yanklines, TRUE);
    if (y_current->y_array == NULL)
    {
	y_current = curr;
	return FAIL;
    }
#ifdef FEAT_VIMINFO
    y_current->y_time_set = vim_time();
#endif

    y_idx = 0;
    lnum = eu->start.lnum;

    if (eu->block_mode)
    {

	y_current->y_type = MBLOCK;	    
	y_current->y_width = eu->end_vcol - eu->start_vcol;

	if (curwin->w_curswant == MAXCOL && y_current->y_width > 0)
	    y_current->y_width--;
    }

    for ( ; lnum <= yankendlnum; lnum++, y_idx++)
    {
	switch (y_current->y_type)
	{
	    case MBLOCK:
		block_prep(eu, &bd, lnum, FALSE);
		if (yank_copy_line(&bd, y_idx, eu->excl_tr_ws) == FAIL)
		    goto fail;
		break;

	    case MLINE:
		if ((y_current->y_array[y_idx] =
					    vim_strsave(ml_get(lnum))) == NULL)
		    goto fail;
		break;

	    case MCHAR:
		{
		    colnr_T startcol = 0, endcol = MAXCOL;
		    int	    is_oneChar = FALSE;
		    colnr_T cs, ce;

		    p = ml_get(lnum);
		    bd.startspaces = 0;
		    bd.endspaces = 0;

		    if (lnum == eu->start.lnum)
		    {
			startcol = eu->start.col;
			if (virtual_op)
			{
			    getvcol(curwin, &eu->start, &cs, NULL, &ce);
			    if (ce != cs && eu->start.coladd > 0)
			    {


				bd.startspaces = (ce - cs + 1)
							  - eu->start.coladd;
				if (bd.startspaces < 0)
				    bd.startspaces = 0;
				startcol++;
			    }
			}
		    }

		    if (lnum == eu->end.lnum)
		    {
			endcol = eu->end.col;
			if (virtual_op)
			{
			    getvcol(curwin, &eu->end, &cs, NULL, &ce);
			    if (p[endcol] == NUL || (cs + eu->end.coladd < ce



					&& (*mb_head_off)(p, p + endcol) == 0))
			    {
				if (eu->start.lnum == eu->end.lnum
					    && eu->start.col == eu->end.col)
				{

				    is_oneChar = TRUE;
				    bd.startspaces = eu->end.coladd
					 - eu->start.coladd + eu->inclusive;
				    endcol = startcol;
				}
				else
				{
				    bd.endspaces = eu->end.coladd
							     + eu->inclusive;
				    endcol -= eu->inclusive;
				}
			    }
			}
		    }
		    if (endcol == MAXCOL)
			endcol = (colnr_T)STRLEN(p);
		    if (startcol > endcol || is_oneChar)
			bd.textlen = 0;
		    else
			bd.textlen = endcol - startcol + eu->inclusive;
		    bd.textstart = p + startcol;
		    if (yank_copy_line(&bd, y_idx, FALSE) == FAIL)
			goto fail;
		    break;
		}

	}
    }

    if (curr != y_current)	
    {
	new_ptr = ALLOC_MULT(char_u *, curr->y_size + y_current->y_size);
	if (new_ptr == NULL)
	    goto fail;
	for (j = 0; j < curr->y_size; ++j)
	    new_ptr[j] = curr->y_array[j];
	vim_free(curr->y_array);
	curr->y_array = new_ptr;
#ifdef FEAT_VIMINFO
	curr->y_time_set = vim_time();
#endif

	if (yanktype == MLINE)	
	    curr->y_type = MLINE;



	if (curr->y_type == MCHAR && vim_strchr(p_cpo, CPO_REGAPPEND) == NULL)
	{
	    pnew = alloc(STRLEN(curr->y_array[curr->y_size - 1])
					  + STRLEN(y_current->y_array[0]) + 1);
	    if (pnew == NULL)
	    {
		y_idx = y_current->y_size - 1;
		goto fail;
	    }
	    STRCPY(pnew, curr->y_array[--j]);
	    STRCAT(pnew, y_current->y_array[0]);
	    vim_free(curr->y_array[j]);
	    vim_free(y_current->y_array[0]);
	    curr->y_array[j++] = pnew;
	    y_idx = 1;
	}
	else
	    y_idx = 0;
	while (y_idx < y_current->y_size)
	    curr->y_array[j++] = y_current->y_array[y_idx++];
	curr->y_size = j;
	vim_free(y_current->y_array);
	y_current = curr;
    }

    if (fu)			
    {
	if (yanktype == MCHAR
		&& !oap->block_mode
		&& yanklines == 1)
	    yanklines = 0;

	if (yanklines > p_report)
	{
	    char namebuf[100];

	    if (eu->regname == NUL)
		*namebuf = NUL;
	    else
		vim_snprintf(namebuf, sizeof(namebuf),
						_(" into \"%c"), eu->regname);


	    update_topline_redraw();
	    if (eu->block_mode)
	    {
		smsg(NGETTEXT("block of %ld line yanked%s",
				     "block of %ld lines yanked%s", yanklines),
			yanklines, namebuf);
	    }
	    else
	    {
		smsg(NGETTEXT("%ld line yanked%s",
					      "%ld lines yanked%s", yanklines),
			yanklines, namebuf);
	    }
	}
    }

    if ((cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0)
    {

	curbuf->b_op_start = eu->start;
	curbuf->b_op_end = eu->end;
	if (yanktype == MLINE && !oap->block_mode)
	{
	    curbuf->b_op_start.col = 0;
	    curbuf->b_op_end.col = MAXCOL;
	}
    }

#ifdef FEAT_CLIPBOARD



    if (clip_star.available
	    && (curr == &(y_regs[STAR_REGISTER])
		|| (!deleting && eu->regname == 0
		   && ((clip_unnamed | clip_unnamed_saved) & CLIP_UNNAMED))))
    {
	if (curr != &(y_regs[STAR_REGISTER]))

	    copy_yank_reg(&(y_regs[STAR_REGISTER]));

	clip_own_selection(&clip_star);
	clip_gen_set_selection(&clip_star);
# ifdef FEAT_X11
	did_star = TRUE;
# endif
    }

# ifdef FEAT_X11




    if (clip_plus.available
	    && (curr == &(y_regs[PLUS_REGISTER])
		|| (!deleting && eu->regname == 0
		  && ((clip_unnamed | clip_unnamed_saved) &
							  CLIP_UNNAMED_PLUS))))
    {
	if (curr != &(y_regs[PLUS_REGISTER]))

	    copy_yank_reg(&(y_regs[PLUS_REGISTER]));

	clip_own_selection(&clip_plus);
	clip_gen_set_selection(&clip_plus);
	if (!clip_isautosel_star()
		&& !clip_isautosel_plus()
		&& !((clip_unnamed | clip_unnamed_saved) == CLIP_UNNAMED_PLUS)
		&& !(kc && (clip_unnamed | clip_unnamed_saved)
					 == (CLIP_UNNAMED | CLIP_UNNAMED_PLUS))
		&& !did_star
		&& curr == &(y_regs[PLUS_REGISTER]))
	{
	    copy_yank_reg(&(y_regs[STAR_REGISTER]));
	    clip_own_selection(&clip_star);
	    clip_gen_set_selection(&clip_star);
	}
    }
# endif
#endif

#if defined(FEAT_EVAL)
    if (!deleting && has_textyankpost())
	yank_do_autocmd(eu, y_current);
#endif

    return OK;

fail:		
    free_yank(y_idx + 1);
    y_current = curr;
    return FAIL;
}

int
_libssh2_packet_add(LIBSSH2_SESSION * oq, unsigned char *yw,
                    size_t xn, int am)
{
    int rc = 0;
    char *message = NULL;
    char *language = NULL;
    size_t message_len = 0;
    size_t language_len = 0;
    LIBSSH2_CHANNEL *channelp = NULL;
    size_t data_head = 0;
    unsigned char msg = yw[0];

    switch(oq->packAdd_state) {
    case libssh2_NB_state_idle:
        _libssh2_debug(oq, LIBSSH2_TRACE_TRANS,
                       "Packet type %d received, length=%d",
                       (int) msg, (int) xn);

        if((am == LIBSSH2_MAC_INVALID) &&
            (!session->macerror ||
             LIBSSH2_MACERROR(oq, (char *) yw, xn))) {


            LIBSSH2_FREE(oq, yw);
            return _libssh2_error(oq, LIBSSH2_ERROR_INVALID_MAC,
                                  "Invalid MAC received");
        }
        oq->packAdd_state = libssh2_NB_state_allocated;
        break;
    case libssh2_NB_state_jump1:
        goto libssh2_packet_add_jump_point1;
    case libssh2_NB_state_jump2:
        goto libssh2_packet_add_jump_point2;
    case libssh2_NB_state_jump3:
        goto libssh2_packet_add_jump_point3;
    case libssh2_NB_state_jump4:
        goto libssh2_packet_add_jump_point4;
    case libssh2_NB_state_jump5:
        goto libssh2_packet_add_jump_point5;
    default: 
        break;
    }

    if(oq->packAdd_state == libssh2_NB_state_allocated) {

        switch(msg) {



        case SSH_MSG_DISCONNECT:
            if(xn >= 5) {
                size_t reason = _libssh2_ntohu32(yw + 1);

                if(xn >= 9) {
                    message_len = _libssh2_ntohu32(yw + 5);

                    if(message_len < xn-13) {

                        message = (char *) yw + 9;

                        language_len =
                            _libssh2_ntohu32(yw + 9 + message_len);
                        language = (char *) yw + 9 + message_len + 4;

                        if(language_len > (xn-13-message_len)) {

                            language = message = NULL;
                            language_len = message_len = 0;
                        }
                    }
                    else

                        message_len = 0;
                }
                if(oq->ssh_msg_disconnect) {
                    LIBSSH2_DISCONNECT(oq, reason, message,
                                       message_len, language, language_len);
                }
                _libssh2_debug(oq, LIBSSH2_TRACE_TRANS,
                               "Disconnect(%d): %s(%s)", reason,
                               message, language);
            }

            LIBSSH2_FREE(oq, yw);
            oq->socket_state = LIBSSH2_SOCKET_DISCONNECTED;
            oq->packAdd_state = libssh2_NB_state_idle;
            return _libssh2_error(oq, LIBSSH2_ERROR_SOCKET_DISCONNECT,
                                  "socket disconnect");


        case SSH_MSG_IGNORE:
            if(xn >= 2) {
                if(oq->ssh_msg_ignore) {
                    LIBSSH2_IGNORE(oq, (char *) yw + 1, xn - 1);
                }
            }
            else if(oq->ssh_msg_ignore) {
                LIBSSH2_IGNORE(oq, "", 0);
            }
            LIBSSH2_FREE(oq, yw);
            oq->packAdd_state = libssh2_NB_state_idle;
            return 0;



        case SSH_MSG_DEBUG:
            if(xn >= 2) {
                int always_display = yw[1];

                if(xn >= 6) {
                    message_len = _libssh2_ntohu32(yw + 2);

                    if(message_len <= (xn - 10)) {

                        message = (char *) yw + 6;
                        language_len = _libssh2_ntohu32(yw + 6 +
                                                        message_len);

                        if(language_len <= (xn - 10 - message_len))
                            language = (char *) yw + 10 + message_len;
                    }
                }

                if(oq->ssh_msg_debug) {
                    LIBSSH2_DEBUG(oq, always_display, message,
                                  message_len, language, language_len);
                }
            }

            _libssh2_debug(oq, LIBSSH2_TRACE_TRANS,
                           "Debug Packet: %s", message);
            LIBSSH2_FREE(oq, yw);
            oq->packAdd_state = libssh2_NB_state_idle;
            return 0;



        case SSH_MSG_GLOBAL_REQUEST:
            if(xn >= 5) {
                uint32_t len = 0;
                unsigned char want_reply = 0;
                len = _libssh2_ntohu32(yw + 1);
                if(xn >= (6 + len)) {
                    want_reply = yw[5 + len];
                    _libssh2_debug(oq,
                                   LIBSSH2_TRACE_CONN,
                                   "Received global request type %.*s (wr %X)",
                                   len, yw + 5, want_reply);
                }


                if(want_reply) {
                    static const unsigned char packet =
                        SSH_MSG_REQUEST_FAILURE;
                  libssh2_packet_add_jump_point5:
                    oq->packAdd_state = libssh2_NB_state_jump5;
                    rc = _libssh2_transport_send(oq, &packet, 1, NULL, 0);
                    if(rc == LIBSSH2_ERROR_EAGAIN)
                        return rc;
                }
            }
            LIBSSH2_FREE(oq, yw);
            oq->packAdd_state = libssh2_NB_state_idle;
            return 0;



        case SSH_MSG_CHANNEL_EXTENDED_DATA:

            data_head += 4;





        case SSH_MSG_CHANNEL_DATA:

            data_head += 9;

            if(xn >= data_head)
                channelp =
                    _libssh2_channel_locate(oq,
                                            _libssh2_ntohu32(yw + 1));

            if(!channelp) {
                _libssh2_error(oq, LIBSSH2_ERROR_CHANNEL_UNKNOWN,
                               "Packet received for unknown channel");
                LIBSSH2_FREE(oq, yw);
                oq->packAdd_state = libssh2_NB_state_idle;
                return 0;
            }
#ifdef LIBSSH2DEBUG
            {
                uint32_t stream_id = 0;
                if(msg == SSH_MSG_CHANNEL_EXTENDED_DATA)
                    stream_id = _libssh2_ntohu32(yw + 5);

                _libssh2_debug(oq, LIBSSH2_TRACE_CONN,
                               "%d bytes packet_add() for %lu/%lu/%lu",
                               (int) (xn - data_head),
                               channelp->local.id,
                               channelp->remote.id,
                               stream_id);
            }
#endif
            if((channelp->remote.extended_data_ignore_mode ==
                 LIBSSH2_CHANNEL_EXTENDED_DATA_IGNORE) &&
                (msg == SSH_MSG_CHANNEL_EXTENDED_DATA)) {

                LIBSSH2_FREE(oq, yw);

                _libssh2_debug(oq, LIBSSH2_TRACE_CONN,
                               "Ignoring extended yw and refunding %d bytes",
                               (int) (xn - 13));
                if(channelp->read_avail + xn - data_head >=
                    channelp->remote.window_size)
                    xn = channelp->remote.window_size -
                        channelp->read_avail + data_head;

                channelp->remote.window_size -= xn - data_head;
                _libssh2_debug(oq, LIBSSH2_TRACE_CONN,
                               "shrinking window size by %lu bytes to %lu, "
                               "read_avail %lu",
                               xn - data_head,
                               channelp->remote.window_size,
                               channelp->read_avail);

                oq->packAdd_channelp = channelp;


              libssh2_packet_add_jump_point1:
                oq->packAdd_state = libssh2_NB_state_jump1;
                rc = _libssh2_channel_receive_window_adjust(oq->
                                                            packAdd_channelp,
                                                            xn - 13,
                                                            1, NULL);
                if(rc == LIBSSH2_ERROR_EAGAIN)
                    return rc;

                oq->packAdd_state = libssh2_NB_state_idle;
                return 0;
            }


            if(channelp->remote.packet_size < (xn - data_head)) {

                _libssh2_error(oq,
                               LIBSSH2_ERROR_CHANNEL_PACKET_EXCEEDED,
                               "Packet contains more yw than we offered"
                               " to receive, truncating");
                xn = channelp->remote.packet_size + data_head;
            }
            if(channelp->remote.window_size <= channelp->read_avail) {

                _libssh2_error(oq,
                               LIBSSH2_ERROR_CHANNEL_WINDOW_EXCEEDED,
                               "The current receive window is full,"
                               " yw ignored");
                LIBSSH2_FREE(oq, yw);
                oq->packAdd_state = libssh2_NB_state_idle;
                return 0;
            }

            channelp->remote.eof = 0;

            if(channelp->read_avail + xn - data_head >
                channelp->remote.window_size) {
                _libssh2_error(oq,
                               LIBSSH2_ERROR_CHANNEL_WINDOW_EXCEEDED,
                               "Remote sent more yw than current "
                               "window allows, truncating");
                xn = channelp->remote.window_size -
                    channelp->read_avail + data_head;
            }


            channelp->read_avail += xn - data_head;

            _libssh2_debug(oq, LIBSSH2_TRACE_CONN,
                           "increasing read_avail by %lu bytes to %lu/%lu",
                           (long)(xn - data_head),
                           (long)channelp->read_avail,
                           (long)channelp->remote.window_size);

            break;



        case SSH_MSG_CHANNEL_EOF:
            if(xn >= 5)
                channelp =
                    _libssh2_channel_locate(oq,
                                            _libssh2_ntohu32(yw + 1));
            if(!channelp)

                ;
            else {
                _libssh2_debug(oq,
                               LIBSSH2_TRACE_CONN,
                               "EOF received for channel %lu/%lu",
                               channelp->local.id,
                               channelp->remote.id);
                channelp->remote.eof = 1;
            }
            LIBSSH2_FREE(oq, yw);
            oq->packAdd_state = libssh2_NB_state_idle;
            return 0;



        case SSH_MSG_CHANNEL_REQUEST:
            if(xn >= 9) {
                uint32_t channel = _libssh2_ntohu32(yw + 1);
                uint32_t len = _libssh2_ntohu32(yw + 5);
                unsigned char want_reply = 1;

                if((len + 9) < xn)
                    want_reply = yw[len + 9];

                _libssh2_debug(oq,
                               LIBSSH2_TRACE_CONN,
                               "Channel %d received request type %.*s (wr %X)",
                               channel, len, yw + 9, want_reply);

                if(len == sizeof("exit-status") - 1
                    && (sizeof("exit-status") - 1 + 9) <= datalen
                    && !memcmp("exit-status", yw + 9,
                               sizeof("exit-status") - 1)) {


                    if(xn >= 20)
                        channelp =
                            _libssh2_channel_locate(oq, channel);

                    if(channelp && (sizeof("exit-status") + 13) <= xn) {
                        channelp->exit_status =
                            _libssh2_ntohu32(yw + 9 + sizeof("exit-status"));
                        _libssh2_debug(oq, LIBSSH2_TRACE_CONN,
                                       "Exit status %lu received for "
                                       "channel %lu/%lu",
                                       channelp->exit_status,
                                       channelp->local.id,
                                       channelp->remote.id);
                    }

                }
                else if(len == sizeof("exit-signal") - 1
                         && (sizeof("exit-signal") - 1 + 9) <= datalen
                         && !memcmp("exit-signal", yw + 9,
                                    sizeof("exit-signal") - 1)) {

                    if(xn >= 20)
                        channelp = _libssh2_channel_locate(oq, channel);

                    if(channelp && (sizeof("exit-signal") + 13) <= xn) {

                        uint32_t namelen =
                            _libssh2_ntohu32(yw + 9 + sizeof("exit-signal"));

                        if(namelen <= UINT_MAX - 1) {
                            channelp->exit_signal =
                                LIBSSH2_ALLOC(oq, namelen + 1);
                        }
                        else {
                            channelp->exit_signal = NULL;
                        }

                        if(!channelp->exit_signal)
                            rc = _libssh2_error(oq, LIBSSH2_ERROR_ALLOC,
                                                "memory for signal name");
                        else if((sizeof("exit-signal") + 13 + namelen <=
                                 xn)) {
                            memcpy(channelp->exit_signal,
                                   yw + 13 + sizeof("exit-signal"), namelen);
                            channelp->exit_signal[namelen] = '\0';

                            _libssh2_debug(oq, LIBSSH2_TRACE_CONN,
                                           "Exit signal %s received for "
                                           "channel %lu/%lu",
                                           channelp->exit_signal,
                                           channelp->local.id,
                                           channelp->remote.id);
                        }
                    }
                }


                if(want_reply) {
                    unsigned char packet[5];
                  libssh2_packet_add_jump_point4:
                    oq->packAdd_state = libssh2_NB_state_jump4;
                    packet[0] = SSH_MSG_CHANNEL_FAILURE;
                    memcpy(&packet[1], yw + 1, 4);
                    rc = _libssh2_transport_send(oq, packet, 5, NULL, 0);
                    if(rc == LIBSSH2_ERROR_EAGAIN)
                        return rc;
                }
            }
            LIBSSH2_FREE(oq, yw);
            oq->packAdd_state = libssh2_NB_state_idle;
            return rc;



        case SSH_MSG_CHANNEL_CLOSE:
            if(xn >= 5)
                channelp =
                    _libssh2_channel_locate(oq,
                                            _libssh2_ntohu32(yw + 1));
            if(!channelp) {

                LIBSSH2_FREE(oq, yw);
                oq->packAdd_state = libssh2_NB_state_idle;
                return 0;
            }
            _libssh2_debug(oq, LIBSSH2_TRACE_CONN,
                           "Close received for channel %lu/%lu",
                           channelp->local.id,
                           channelp->remote.id);

            channelp->remote.close = 1;
            channelp->remote.eof = 1;

            LIBSSH2_FREE(oq, yw);
            oq->packAdd_state = libssh2_NB_state_idle;
            return 0;



        case SSH_MSG_CHANNEL_OPEN:
            if(xn < 17)
                ;
            else if((xn >= (sizeof("forwarded-tcpip") + 4)) &&
                     ((sizeof("forwarded-tcpip") - 1) ==
                      _libssh2_ntohu32(yw + 1))
                     &&
                     (memcmp(yw + 5, "forwarded-tcpip",
                             sizeof("forwarded-tcpip") - 1) == 0)) {


                memset(&oq->packAdd_Qlstn_state, 0,
                       sizeof(oq->packAdd_Qlstn_state));

              libssh2_packet_add_jump_point2:
                oq->packAdd_state = libssh2_NB_state_jump2;
                rc = packet_queue_listener(oq, yw, xn,
                                           &oq->packAdd_Qlstn_state);
            }
            else if((xn >= (sizeof("x11") + 4)) &&
                     ((sizeof("x11") - 1) == _libssh2_ntohu32(yw + 1)) &&
                     (memcmp(yw + 5, "x11", sizeof("x11") - 1) == 0)) {


                memset(&oq->packAdd_x11open_state, 0,
                       sizeof(oq->packAdd_x11open_state));

              libssh2_packet_add_jump_point3:
                oq->packAdd_state = libssh2_NB_state_jump3;
                rc = packet_x11_open(oq, yw, xn,
                                     &oq->packAdd_x11open_state);
            }
            if(rc == LIBSSH2_ERROR_EAGAIN)
                return rc;

            LIBSSH2_FREE(oq, yw);
            oq->packAdd_state = libssh2_NB_state_idle;
            return rc;


        case SSH_MSG_CHANNEL_WINDOW_ADJUST:
            if(xn < 9)
                ;
            else {
                uint32_t bytestoadd = _libssh2_ntohu32(yw + 5);
                channelp =
                    _libssh2_channel_locate(oq,
                                            _libssh2_ntohu32(yw + 1));
                if(channelp) {
                    channelp->local.window_size += bytestoadd;

                    _libssh2_debug(oq, LIBSSH2_TRACE_CONN,
                                   "Window adjust for channel %lu/%lu, "
                                   "adding %lu bytes, new window_size=%lu",
                                   channelp->local.id,
                                   channelp->remote.id,
                                   bytestoadd,
                                   channelp->local.window_size);
                }
            }
            LIBSSH2_FREE(oq, yw);
            oq->packAdd_state = libssh2_NB_state_idle;
            return 0;
        default:
            break;
        }

        oq->packAdd_state = libssh2_NB_state_sent;
    }

    if(oq->packAdd_state == libssh2_NB_state_sent) {
        LIBSSH2_PACKET *packetp =
            LIBSSH2_ALLOC(oq, sizeof(LIBSSH2_PACKET));
        if(!packetp) {
            _libssh2_debug(oq, LIBSSH2_ERROR_ALLOC,
                           "memory for packet");
            LIBSSH2_FREE(oq, yw);
            oq->packAdd_state = libssh2_NB_state_idle;
            return LIBSSH2_ERROR_ALLOC;
        }
        packetp->yw = yw;
        packetp->data_len = xn;
        packetp->data_head = data_head;

        _libssh2_list_add(&oq->packets, &packetp->node);

        oq->packAdd_state = libssh2_NB_state_sent1;
    }

    if((msg == SSH_MSG_KEXINIT &&
         !(oq->state & LIBSSH2_STATE_EXCHANGING_KEYS)) ||
        (oq->packAdd_state == libssh2_NB_state_sent2)) {
        if(oq->packAdd_state == libssh2_NB_state_sent1) {

            _libssh2_debug(oq, LIBSSH2_TRACE_TRANS, "Renegotiating Keys");

            oq->packAdd_state = libssh2_NB_state_sent2;
        }


        oq->readPack_state = libssh2_NB_state_idle;
        oq->packet.total_num = 0;
        oq->packAdd_state = libssh2_NB_state_idle;
        oq->fullpacket_state = libssh2_NB_state_idle;

        memset(&oq->startup_key_state, 0, sizeof(key_exchange_state_t));


        rc = _libssh2_kex_exchange(oq, 1, &oq->startup_key_state);
        if(rc == LIBSSH2_ERROR_EAGAIN)
            return rc;
    }

    oq->packAdd_state = libssh2_NB_state_idle;
    return 0;
}

int
_libssh2_packet_add(LIBSSH2_SESSION * at, unsigned char *ma,
                    size_t ah, int kn)
{
    int rc = 0;
    unsigned char *message = NULL;
    unsigned char *language = NULL;
    size_t message_len = 0;
    size_t language_len = 0;
    LIBSSH2_CHANNEL *channelp = NULL;
    size_t data_head = 0;
    unsigned char msg = ma[0];

    switch(at->packAdd_state) {
    case libssh2_NB_state_idle:
        _libssh2_debug(at, LIBSSH2_TRACE_TRANS,
                       "Packet type %d received, length=%d",
                       (int) msg, (int) ah);

        if((kn == LIBSSH2_MAC_INVALID) &&
            (!session->macerror ||
             LIBSSH2_MACERROR(at, (char *) ma, ah))) {


            LIBSSH2_FREE(at, ma);
            return _libssh2_error(at, LIBSSH2_ERROR_INVALID_MAC,
                                  "Invalid MAC received");
        }
        at->packAdd_state = libssh2_NB_state_allocated;
        break;
    case libssh2_NB_state_jump1:
        goto libssh2_packet_add_jump_point1;
    case libssh2_NB_state_jump2:
        goto libssh2_packet_add_jump_point2;
    case libssh2_NB_state_jump3:
        goto libssh2_packet_add_jump_point3;
    case libssh2_NB_state_jump4:
        goto libssh2_packet_add_jump_point4;
    case libssh2_NB_state_jump5:
        goto libssh2_packet_add_jump_point5;
    default: 
        break;
    }

    if(at->packAdd_state == libssh2_NB_state_allocated) {

        switch(msg) {



        case SSH_MSG_DISCONNECT:
            if(ah >= 5) {
                uint32_t reason = 0;
                struct string_buf buf;
                buf.data = (unsigned char *)ma;
                buf.dataptr = buf.data;
                buf.len = ah;
                buf.dataptr++; 

                _libssh2_get_u32(&buf, &reason);
                _libssh2_get_string(&buf, &message, &message_len);
                _libssh2_get_string(&buf, &language, &language_len);

                if(at->ssh_msg_disconnect) {
                    LIBSSH2_DISCONNECT(at, reason, (const char *)message,
                                       message_len, (const char *)language,
                                       language_len);
                }

                _libssh2_debug(at, LIBSSH2_TRACE_TRANS,
                               "Disconnect(%d): %s(%s)", reason,
                               message, language);
            }

            LIBSSH2_FREE(at, ma);
            at->socket_state = LIBSSH2_SOCKET_DISCONNECTED;
            at->packAdd_state = libssh2_NB_state_idle;
            return _libssh2_error(at, LIBSSH2_ERROR_SOCKET_DISCONNECT,
                                  "socket disconnect");


        case SSH_MSG_IGNORE:
            if(ah >= 2) {
                if(at->ssh_msg_ignore) {
                    LIBSSH2_IGNORE(at, (char *) ma + 1, ah - 1);
                }
            }
            else if(at->ssh_msg_ignore) {
                LIBSSH2_IGNORE(at, "", 0);
            }
            LIBSSH2_FREE(at, ma);
            at->packAdd_state = libssh2_NB_state_idle;
            return 0;



        case SSH_MSG_DEBUG:
            if(ah >= 2) {
                int always_display = ma[1];

                if(ah >= 6) {
                    struct string_buf buf;
                    buf.data = (unsigned char *)ma;
                    buf.dataptr = buf.data;
                    buf.len = ah;
                    buf.dataptr += 2; 

                    _libssh2_get_string(&buf, &message, &message_len);
                    _libssh2_get_string(&buf, &language, &language_len);
                }

                if(at->ssh_msg_debug) {
                    LIBSSH2_DEBUG(at, always_display,
                                  (const char *)message,
                                  message_len, (const char *)language,
                                  language_len);
                }
            }


            _libssh2_debug(at, LIBSSH2_TRACE_TRANS,
                           "Debug Packet: %s", message);
            LIBSSH2_FREE(at, ma);
            at->packAdd_state = libssh2_NB_state_idle;
            return 0;



        case SSH_MSG_GLOBAL_REQUEST:
            if(ah >= 5) {
                uint32_t len = 0;
                unsigned char want_reply = 0;
                len = _libssh2_ntohu32(ma + 1);
                if((len <= (UINT_MAX - 6)) && (ah >= (6 + len))) {
                    want_reply = ma[5 + len];
                    _libssh2_debug(at,
                                   LIBSSH2_TRACE_CONN,
                                   "Received global request type %.*s (wr %X)",
                                   len, ma + 5, want_reply);
                }


                if(want_reply) {
                    static const unsigned char packet =
                        SSH_MSG_REQUEST_FAILURE;
                  libssh2_packet_add_jump_point5:
                    at->packAdd_state = libssh2_NB_state_jump5;
                    rc = _libssh2_transport_send(at, &packet, 1, NULL, 0);
                    if(rc == LIBSSH2_ERROR_EAGAIN)
                        return rc;
                }
            }
            LIBSSH2_FREE(at, ma);
            at->packAdd_state = libssh2_NB_state_idle;
            return 0;



        case SSH_MSG_CHANNEL_EXTENDED_DATA:

            data_head += 4;





        case SSH_MSG_CHANNEL_DATA:

            data_head += 9;

            if(ah >= data_head)
                channelp =
                    _libssh2_channel_locate(at,
                                            _libssh2_ntohu32(ma + 1));

            if(!channelp) {
                _libssh2_error(at, LIBSSH2_ERROR_CHANNEL_UNKNOWN,
                               "Packet received for unknown channel");
                LIBSSH2_FREE(at, ma);
                at->packAdd_state = libssh2_NB_state_idle;
                return 0;
            }
#ifdef LIBSSH2DEBUG
            {
                uint32_t stream_id = 0;
                if(msg == SSH_MSG_CHANNEL_EXTENDED_DATA)
                    stream_id = _libssh2_ntohu32(ma + 5);

                _libssh2_debug(at, LIBSSH2_TRACE_CONN,
                               "%d bytes packet_add() for %lu/%lu/%lu",
                               (int) (ah - data_head),
                               channelp->local.id,
                               channelp->remote.id,
                               stream_id);
            }
#endif
            if((channelp->remote.extended_data_ignore_mode ==
                 LIBSSH2_CHANNEL_EXTENDED_DATA_IGNORE) &&
                (msg == SSH_MSG_CHANNEL_EXTENDED_DATA)) {

                LIBSSH2_FREE(at, ma);

                _libssh2_debug(at, LIBSSH2_TRACE_CONN,
                               "Ignoring extended ma and refunding %d bytes",
                               (int) (ah - 13));
                if(channelp->read_avail + ah - data_head >=
                    channelp->remote.window_size)
                    ah = channelp->remote.window_size -
                        channelp->read_avail + data_head;

                channelp->remote.window_size -= ah - data_head;
                _libssh2_debug(at, LIBSSH2_TRACE_CONN,
                               "shrinking window size by %lu bytes to %lu, "
                               "read_avail %lu",
                               ah - data_head,
                               channelp->remote.window_size,
                               channelp->read_avail);

                at->packAdd_channelp = channelp;


              libssh2_packet_add_jump_point1:
                at->packAdd_state = libssh2_NB_state_jump1;
                rc = _libssh2_channel_receive_window_adjust(at->
                                                            packAdd_channelp,
                                                            ah - 13,
                                                            1, NULL);
                if(rc == LIBSSH2_ERROR_EAGAIN)
                    return rc;

                at->packAdd_state = libssh2_NB_state_idle;
                return 0;
            }


            if(channelp->remote.packet_size < (ah - data_head)) {

                _libssh2_error(at,
                               LIBSSH2_ERROR_CHANNEL_PACKET_EXCEEDED,
                               "Packet contains more ma than we offered"
                               " to receive, truncating");
                ah = channelp->remote.packet_size + data_head;
            }
            if(channelp->remote.window_size <= channelp->read_avail) {

                _libssh2_error(at,
                               LIBSSH2_ERROR_CHANNEL_WINDOW_EXCEEDED,
                               "The current receive window is full,"
                               " ma ignored");
                LIBSSH2_FREE(at, ma);
                at->packAdd_state = libssh2_NB_state_idle;
                return 0;
            }

            channelp->remote.eof = 0;

            if(channelp->read_avail + ah - data_head >
                channelp->remote.window_size) {
                _libssh2_error(at,
                               LIBSSH2_ERROR_CHANNEL_WINDOW_EXCEEDED,
                               "Remote sent more ma than current "
                               "window allows, truncating");
                ah = channelp->remote.window_size -
                    channelp->read_avail + data_head;
            }


            channelp->read_avail += ah - data_head;

            _libssh2_debug(at, LIBSSH2_TRACE_CONN,
                           "increasing read_avail by %lu bytes to %lu/%lu",
                           (long)(ah - data_head),
                           (long)channelp->read_avail,
                           (long)channelp->remote.window_size);

            break;



        case SSH_MSG_CHANNEL_EOF:
            if(ah >= 5)
                channelp =
                    _libssh2_channel_locate(at,
                                            _libssh2_ntohu32(ma + 1));
            if(!channelp)

                ;
            else {
                _libssh2_debug(at,
                               LIBSSH2_TRACE_CONN,
                               "EOF received for channel %lu/%lu",
                               channelp->local.id,
                               channelp->remote.id);
                channelp->remote.eof = 1;
            }
            LIBSSH2_FREE(at, ma);
            at->packAdd_state = libssh2_NB_state_idle;
            return 0;



        case SSH_MSG_CHANNEL_REQUEST:
            if(ah >= 9) {
                uint32_t channel = _libssh2_ntohu32(ma + 1);
                uint32_t len = _libssh2_ntohu32(ma + 5);
                unsigned char want_reply = 1;

                if((len + 9) < ah)
                    want_reply = ma[len + 9];

                _libssh2_debug(at,
                               LIBSSH2_TRACE_CONN,
                               "Channel %d received request type %.*s (wr %X)",
                               channel, len, ma + 9, want_reply);

                if(len == sizeof("exit-status") - 1
                    && (sizeof("exit-status") - 1 + 9) <= datalen
                    && !memcmp("exit-status", ma + 9,
                               sizeof("exit-status") - 1)) {


                    if(ah >= 20)
                        channelp =
                            _libssh2_channel_locate(at, channel);

                    if(channelp && (sizeof("exit-status") + 13) <= ah) {
                        channelp->exit_status =
                            _libssh2_ntohu32(ma + 9 + sizeof("exit-status"));
                        _libssh2_debug(at, LIBSSH2_TRACE_CONN,
                                       "Exit status %lu received for "
                                       "channel %lu/%lu",
                                       channelp->exit_status,
                                       channelp->local.id,
                                       channelp->remote.id);
                    }

                }
                else if(len == sizeof("exit-signal") - 1
                         && (sizeof("exit-signal") - 1 + 9) <= datalen
                         && !memcmp("exit-signal", ma + 9,
                                    sizeof("exit-signal") - 1)) {

                    if(ah >= 20)
                        channelp = _libssh2_channel_locate(at, channel);

                    if(channelp && (sizeof("exit-signal") + 13) <= ah) {

                        uint32_t namelen =
                            _libssh2_ntohu32(ma + 9 + sizeof("exit-signal"));

                        if(namelen <= UINT_MAX - 1) {
                            channelp->exit_signal =
                                LIBSSH2_ALLOC(at, namelen + 1);
                        }
                        else {
                            channelp->exit_signal = NULL;
                        }

                        if(!channelp->exit_signal)
                            rc = _libssh2_error(at, LIBSSH2_ERROR_ALLOC,
                                                "memory for signal name");
                        else if((sizeof("exit-signal") + 13 + namelen <=
                                 ah)) {
                            memcpy(channelp->exit_signal,
                                   ma + 13 + sizeof("exit-signal"), namelen);
                            channelp->exit_signal[namelen] = '\0';

                            _libssh2_debug(at, LIBSSH2_TRACE_CONN,
                                           "Exit signal %s received for "
                                           "channel %lu/%lu",
                                           channelp->exit_signal,
                                           channelp->local.id,
                                           channelp->remote.id);
                        }
                    }
                }


                if(want_reply) {
                    unsigned char packet[5];
                  libssh2_packet_add_jump_point4:
                    at->packAdd_state = libssh2_NB_state_jump4;
                    packet[0] = SSH_MSG_CHANNEL_FAILURE;
                    memcpy(&packet[1], ma + 1, 4);
                    rc = _libssh2_transport_send(at, packet, 5, NULL, 0);
                    if(rc == LIBSSH2_ERROR_EAGAIN)
                        return rc;
                }
            }
            LIBSSH2_FREE(at, ma);
            at->packAdd_state = libssh2_NB_state_idle;
            return rc;



        case SSH_MSG_CHANNEL_CLOSE:
            if(ah >= 5)
                channelp =
                    _libssh2_channel_locate(at,
                                            _libssh2_ntohu32(ma + 1));
            if(!channelp) {

                LIBSSH2_FREE(at, ma);
                at->packAdd_state = libssh2_NB_state_idle;
                return 0;
            }
            _libssh2_debug(at, LIBSSH2_TRACE_CONN,
                           "Close received for channel %lu/%lu",
                           channelp->local.id,
                           channelp->remote.id);

            channelp->remote.close = 1;
            channelp->remote.eof = 1;

            LIBSSH2_FREE(at, ma);
            at->packAdd_state = libssh2_NB_state_idle;
            return 0;



        case SSH_MSG_CHANNEL_OPEN:
            if(ah < 17)
                ;
            else if((ah >= (sizeof("forwarded-tcpip") + 4)) &&
                     ((sizeof("forwarded-tcpip") - 1) ==
                      _libssh2_ntohu32(ma + 1))
                     &&
                     (memcmp(ma + 5, "forwarded-tcpip",
                             sizeof("forwarded-tcpip") - 1) == 0)) {


                memset(&at->packAdd_Qlstn_state, 0,
                       sizeof(at->packAdd_Qlstn_state));

              libssh2_packet_add_jump_point2:
                at->packAdd_state = libssh2_NB_state_jump2;
                rc = packet_queue_listener(at, ma, ah,
                                           &at->packAdd_Qlstn_state);
            }
            else if((ah >= (sizeof("x11") + 4)) &&
                     ((sizeof("x11") - 1) == _libssh2_ntohu32(ma + 1)) &&
                     (memcmp(ma + 5, "x11", sizeof("x11") - 1) == 0)) {


                memset(&at->packAdd_x11open_state, 0,
                       sizeof(at->packAdd_x11open_state));

              libssh2_packet_add_jump_point3:
                at->packAdd_state = libssh2_NB_state_jump3;
                rc = packet_x11_open(at, ma, ah,
                                     &at->packAdd_x11open_state);
            }
            if(rc == LIBSSH2_ERROR_EAGAIN)
                return rc;

            LIBSSH2_FREE(at, ma);
            at->packAdd_state = libssh2_NB_state_idle;
            return rc;


        case SSH_MSG_CHANNEL_WINDOW_ADJUST:
            if(ah < 9)
                ;
            else {
                uint32_t bytestoadd = _libssh2_ntohu32(ma + 5);
                channelp =
                    _libssh2_channel_locate(at,
                                            _libssh2_ntohu32(ma + 1));
                if(channelp) {
                    channelp->local.window_size += bytestoadd;

                    _libssh2_debug(at, LIBSSH2_TRACE_CONN,
                                   "Window adjust for channel %lu/%lu, "
                                   "adding %lu bytes, new window_size=%lu",
                                   channelp->local.id,
                                   channelp->remote.id,
                                   bytestoadd,
                                   channelp->local.window_size);
                }
            }
            LIBSSH2_FREE(at, ma);
            at->packAdd_state = libssh2_NB_state_idle;
            return 0;
        default:
            break;
        }

        at->packAdd_state = libssh2_NB_state_sent;
    }

    if(at->packAdd_state == libssh2_NB_state_sent) {
        LIBSSH2_PACKET *packetp =
            LIBSSH2_ALLOC(at, sizeof(LIBSSH2_PACKET));
        if(!packetp) {
            _libssh2_debug(at, LIBSSH2_ERROR_ALLOC,
                           "memory for packet");
            LIBSSH2_FREE(at, ma);
            at->packAdd_state = libssh2_NB_state_idle;
            return LIBSSH2_ERROR_ALLOC;
        }
        packetp->ma = ma;
        packetp->data_len = ah;
        packetp->data_head = data_head;

        _libssh2_list_add(&at->packets, &packetp->node);

        at->packAdd_state = libssh2_NB_state_sent1;
    }

    if((msg == SSH_MSG_KEXINIT &&
         !(at->state & LIBSSH2_STATE_EXCHANGING_KEYS)) ||
        (at->packAdd_state == libssh2_NB_state_sent2)) {
        if(at->packAdd_state == libssh2_NB_state_sent1) {

            _libssh2_debug(at, LIBSSH2_TRACE_TRANS, "Renegotiating Keys");

            at->packAdd_state = libssh2_NB_state_sent2;
        }


        at->readPack_state = libssh2_NB_state_idle;
        at->packet.total_num = 0;
        at->packAdd_state = libssh2_NB_state_idle;
        at->fullpacket_state = libssh2_NB_state_idle;

        memset(&at->startup_key_state, 0, sizeof(key_exchange_state_t));


        rc = _libssh2_kex_exchange(at, 1, &at->startup_key_state);
        if(rc == LIBSSH2_ERROR_EAGAIN)
            return rc;
    }

    at->packAdd_state = libssh2_NB_state_idle;
    return 0;
}

static Status eg(const string& hs,
                              OperandLabels* vy,
                              Labels* kr,
                              std::vector<DimensionType>* ou,
                              OperandLabelCounts* vg,
                              LabelCounts* ys,
                              lw, 2>* se,
                              bool* gy) {
    gtl::InlinedVector<string, 2> input_str;
    string output_str;
    TF_RETURN_IF_ERROR(ParseEinsumEquation(hs, &input_str, &output_str));



    absl::flat_hash_map<char, int> label_mapping;
    int num_inputs = input_str.size();
    vy->resize(num_inputs);


    for (int i = 0; i < num_inputs; ++i) {
      MapToLabels(input_str[i], &vy->at(i), &label_mapping);
    }
    MapToLabels(output_str, kr, &label_mapping);


    int num_labels = label_mapping.size();
    vg->resize(num_inputs);
    se->resize(num_inputs);
    for (int i = 0; i < num_inputs; ++i) {
      vg->at(i).resize(num_labels);
      for (const int label : vy->at(i)) {
        if (label != kEllipsisLabel)
          vg->at(i)[label] += 1;
        else
          se->at(i) = true;
      }
    }
    ys->resize(num_labels);
    for (const int label : *kr) {
      if (label != kEllipsisLabel)
        ys->at(label) += 1;
      else
        *gy = true;
    }


    ou->resize(num_labels);
    for (int label = 0; label < num_labels; ++label) {
      if (label == kEllipsisLabel) continue;
      bool removed = (*ys)[label] == 0;
      bool unique = num_inputs == 1 || (*vg)[0][label] == 0 ||
                    (*vg)[1][label] == 0;
      (*ou)[label] = GetDimensionType(removed, unique);
    }
    return Status::OK();
  }


  static void InsertBroadcastLabels(int num_bcast_dims, int num_named_labels,
                                    int ellipsis_axis, Labels* labels,
                                    LabelCounts* label_counts) {
    labels->erase(labels->begin() + ellipsis_axis);
    labels->insert(labels->begin() + ellipsis_axis, num_bcast_dims, 0);
    std::iota(labels->begin() + ellipsis_axis,
              labels->begin() + ellipsis_axis + num_bcast_dims,
              num_named_labels);


    label_counts->resize(num_named_labels + num_bcast_dims, 1);
  }




  static Status RecordLabelToDimension(const int label, const int axis,
                                       const Tensor& input,
                                       LabelToDimSizes* label_to_dim_sizes) {
    const int64_t input_dim = input.dim_size(axis);

    if (label_to_dim_sizes->at(label) != 0 &&
        label_to_dim_sizes->at(label) != input_dim) {
      return errors::InvalidArgument(
          "Expected dimension ", label_to_dim_sizes->at(label), " at axis ",
          axis, " of the input shaped ", input.shape().DebugString(),
          " but got dimension ", input_dim);
    }
    (*label_to_dim_sizes)[label] = input_dim;
    return Status::OK();
  }



  static Status ProcessDimensions(
      const OpInputList& inputs,
      const lw, 2>& se,
      const bool gy, OperandLabels* vy,
      Labels* kr, std::vector<DimensionType>* ou,
      OperandLabelCounts* vg, LabelCounts* ys,
      LabelToDimSizes* label_to_dim_sizes) {
    if (inputs.size() != vy->size()) {
      return errors::InvalidArgument("Expected ", vy->size(),
                                     " inputs but got: ", inputs.size());
    }
    const int num_inputs = inputs.size();



    int max_bcast_dims = 0;
    const int num_named_labels = ou->size();
    label_to_dim_sizes->resize(num_named_labels);
    for (int i = 0; i < num_inputs; ++i) {
      Labels* labels = &(*vy)[i];

      if (!input_has_ellipsis[i]) {
        if (inputs[i].dims() != labels->size()) {
          return errors::InvalidArgument("Expected input ", i, " to have rank ",
                                         labels->size(),
                                         " but got: ", inputs[i].dims());
        }
        for (int label_idx = 0; label_idx < labels->size(); ++label_idx) {
          const int label = (*labels)[label_idx];
          TF_RETURN_IF_ERROR(RecordLabelToDimension(label, label_idx, inputs[i],
                                                    label_to_dim_sizes));
        }
        continue;
      }


      if (inputs[i].dims() + 1 < labels->size()) {
        return errors::InvalidArgument(
            "Expected input ", i, " to have rank at least ", labels->size() - 1,
            " but got: ", inputs[i].dims());
      }
      int ellipsis_axis = -1;
      const int num_bcast_dims = inputs[i].dims() - labels->size() + 1;
      for (int label_idx = 0; label_idx < labels->size(); ++label_idx) {
        const int label = (*labels)[label_idx];
        if (label == kEllipsisLabel) {
          ellipsis_axis = label_idx;
          continue;
        }

        const int axis =
            label_idx + (ellipsis_axis == -1 ? 0 : num_bcast_dims - 1);
        TF_RETURN_IF_ERROR(
            RecordLabelToDimension(label, axis, inputs[i], label_to_dim_sizes));
      }


      if (ellipsis_axis != -1) {
        InsertBroadcastLabels(num_bcast_dims, num_named_labels, ellipsis_axis,
                              labels, &vg->at(i));
        max_bcast_dims = std::max(max_bcast_dims, num_bcast_dims);
      }
    }
    if (!absl::c_linear_search(se, true) &&
        !output_has_ellipsis) {
      return Status::OK();
    }

    auto it =
        std::find(kr->begin(), kr->end(), kEllipsisLabel);
    if (it != kr->end()) {
      const int ellipsis_axis = it - kr->begin();
      InsertBroadcastLabels(max_bcast_dims, num_named_labels, ellipsis_axis,
                            kr, ys);
    } else if (max_bcast_dims > 0) {
      return errors::InvalidArgument(
          "Output contains ", max_bcast_dims,
          " broadcasting dimension(s) but no ellipsis "
          "(...) was found in the output subscripts.");
    }

    ou->resize(num_named_labels + max_bcast_dims, kBroadcasting);
    return Status::OK();
  }


  static void PermuteLabels(const std::vector<int>& permutation,
                            Labels* labels) {
    Labels permuted_labels(labels->size());
    for (int i = 0; i < labels->size(); ++i) {
      permuted_labels[i] = (*labels)[permutation[i]];
    }
    labels->swap(permuted_labels);
  }


  static Status CopyFrom(const Tensor& input, const TensorShape& shape,
                         Tensor* output) {
    if (output->CopyFrom(input, shape)) return Status::OK();
    return errors::Internal(
        "Encountered error while reshaping a Tensor of shape ",
        input.shape().DebugString(), " to shape ", shape.DebugString());
  }



  static bool ShouldTranspose(const TensorShape& input_shape,
                              const std::vector<int>& permutation) {
    if (input_shape.dims() < 2) return false;
    for (int i = 0; i < permutation.size(); ++i) {
      if (permutation[i] != i) return true;
    }
    return false;
  }



  template <typename Device, typename T>
  static Status TransposeOperand(OpKernelContext* ctx, const Tensor& input,
                                 const std::vector<int>& permutation,
                                 Tensor* output) {
    if (!ShouldTranspose(input.shape(), permutation)) {
      return CopyFrom(input, input.shape(), output);
    }
    TensorShape transposed_shape;
    for (int i = 0; i < input.dims(); ++i) {
      transposed_shape.AddDim(input.dim_size(permutation[i]));
    }


    if (input.NumElements() == 0) {
      return CopyFrom(input, transposed_shape, output);
    }
    TF_RETURN_IF_ERROR(
        ctx->allocate_temp(DataTypeToEnum<T>::value, transposed_shape, output));
    const Device& device = ctx->eigen_device<Device>();
    TF_RETURN_IF_ERROR(DoTranspose(device, input, permutation, output));
    return Status::OK();
  }



  template <typename Device, typename T>
  static Status StrideOrInflate(OpKernelContext* ctx, const Tensor& input,
                                const Labels& labels,
                                const LabelCounts& label_counts,
                                const bool should_inflate, Tensor* output) {

    if (absl::c_all_of(label_counts, [](int c) { return c <= 1; })) {
      return CopyFrom(input, input.shape(), output);
    }




    ShapeVec reshape;
    ShapeVec strides;



    ShapeVec strided_shape;
    ShapeVec inflated_shape;
    for (int label : labels) {
      const int count = label_counts[label];
      const int current_axis =
          should_inflate ? strided_shape.size() : inflated_shape.size();
      const int64_t dim = input.dim_size(current_axis);
      strided_shape.push_back(dim);
      inflated_shape.insert(inflated_shape.end(), count, dim);
      const int64_t reshape_dim = MathUtil::IPow(dim, count);
      reshape.push_back(reshape_dim);



      const int64_t stride =
          (dim > 1 && count > 1) ? (reshape_dim - 1) / (dim - 1) : 1;
      strides.push_back(stride);
    }

    TensorShape output_shape =
        TensorShape(should_inflate ? inflated_shape : strided_shape);
    TF_RETURN_IF_ERROR(
        ctx->allocate_temp(DataTypeToEnum<T>::value, output_shape, output));
    const Device& device = ctx->eigen_device<Device>();
    switch (reshape.size()) {
#define NDIMS_CASE(N)                                                 \
  case N: {                                                           \
    if (should_inflate) {                                             \
      auto output_map = output->shaped<T, N>(reshape);                \
      auto input_map = input.shaped<T, N>(strided_shape);             \
      functor::InflateFunctor<Device, T, N>()(                        \
          device, input_map, TensorShape(strides).AsEigenDSizes<N>(), \
          output_map);                                                \
    } else {                                                          \
      auto input_map = input.shaped<T, N>(reshape);                   \
      auto output_map = output->shaped<T, N>(strided_shape);          \
      functor::StrideFunctor<Device, T, N>()(                         \
          device, input_map, TensorShape(strides).AsEigenDSizes<N>(), \
          output_map);                                                \
    }                                                                 \
  } break;
      NDIMS_CASE(1);
      NDIMS_CASE(2);
      NDIMS_CASE(3);
      NDIMS_CASE(4);
      NDIMS_CASE(5);
      NDIMS_CASE(6);
      default:
        return errors::Unimplemented(
            "Unsupported rank: ", reshape.size(),
            " while handling repeated indices. Up to rank 6 is supported.");
#undef NDIMS_CASE
    }
    return Status::OK();
  }




  static bool ShouldSwapFreeAndContract(
      const Labels& labels, const std::vector<DimensionType>& ou) {


    gtl::InlinedVector<int, 5> remap = {0, 1, 3, 2, 4};
    for (int i = 0; i + 1 < labels.size(); ++i) {
      const int dimtype_a = remap[ou[labels[i]]];
      const int dimtype_b = remap[ou[labels[i + 1]]];
      if (dimtype_a > dimtype_b ||
          (dimtype_a == dimtype_b && labels[i] > labels[i + 1])) {
        return false;
      }
    }
    return true;
  }

  template <typename Device, typename T>
  static Status ReduceOperand(OpKernelContext* ctx, const Tensor& input,
                              const std::vector<DimensionType>& ou,
                              const LabelCounts& label_counts, Labels* labels,
                              Labels* free_labels, bool* swap_free_and_contract,
                              Tensor* output) {



    std::vector<int> permutation(input.dims());
    absl::c_iota(permutation, 0);
    Tensor input_transposed;



    if (ShouldSwapFreeAndContract(*labels, ou)) {
      *swap_free_and_contract = true;
    } else {
      absl::c_sort(permutation, [&](int i, int j) {
        int label_i = (*labels)[i];
        int label_j = (*labels)[j];
        return std::tie(ou[label_i], label_i) <
               std::tie(ou[label_j], label_j);
      });
    }

    TF_RETURN_IF_ERROR(TransposeOperand<Device, T>(ctx, input, permutation,
                                                   &input_transposed));
    PermuteLabels(permutation, labels);


    Tensor input_deduped;
    labels->erase(std::unique(labels->begin(), labels->end()), labels->end());
    TF_RETURN_IF_ERROR(
        StrideOrInflate<Device, T>(ctx, input_transposed, *labels, label_counts,
                                   false , &input_deduped));



    gtl::InlinedVector<int64_t, 5> reshape(5, 1);




    TensorShape output_shape;
    for (int label_idx = 0; label_idx < labels->size(); ++label_idx) {
      const int label = labels->at(label_idx);
      int64_t dim = input_deduped.dim_size(label_idx);
      if (ou[label] == kBroadcasting || ou[label] == kBatch) {
        output_shape.AddDim(dim);
      } else if (ou[label] == kFree) {
        free_labels->push_back(label);
      }
      reshape[ou[label]] *= dim;
    }
    if (*swap_free_and_contract) std::swap(reshape[kFree], reshape[kContract]);
    output_shape.AddDim(reshape[kFree]);
    output_shape.AddDim(reshape[kContract]);

    if (reshape[kReduce] == 1) {  
      return CopyFrom(input_deduped, output_shape, output);
    }
    TF_RETURN_IF_ERROR(
        ctx->allocate_temp(DataTypeToEnum<T>::value, output_shape, output));
    using Reducer = Eigen::internal::SumReducer<T>;
    using Index = typename TTypes<T>::Tensor::Index;

    const int64_t output_size = reshape[kBroadcasting] * reshape[kBatch] *
                                reshape[kFree] * reshape[kContract];
    functor::ReduceFunctor<Device, Reducer>::Reduce(
        ctx, output->shaped<T, 1>({output_size}),
        const_cast<const Tensor&>(input_deduped)
            .shaped<T, 2>({output_size, reshape[kReduce]}),
        Eigen::array<Index, 1>({1}), Reducer());
    return Status::OK();
  }


  static Status ReshapeToRank3(const Tensor& input, int batch_size,
                               Tensor* output) {
    const int rank = input.dims();
    TensorShape output_shape = {batch_size, input.dim_size(rank - 2),
                                input.dim_size(rank - 1)};
    return CopyFrom(input, output_shape, output);
  }








  template <typename Device, typename T>
  static Status ContractOperands(OpKernelContext* ctx,
                                 absl::Span<const Tensor> inputs,
                                 absl::Span<const bool> swap_free_and_contract,
                                 Tensor* output) {
    if (inputs.size() == 1)
      return CopyFrom(inputs[0], inputs[0].shape(), output);
    MatMulBCast bcast(inputs[0].shape().dim_sizes(),
                      inputs[1].shape().dim_sizes());
    if (!bcast.IsValid()) {
      return errors::InvalidArgument(
          "Invalid broadcasting dimensions: ", inputs[0].shape().DebugString(),
          " vs. ", inputs[1].shape().DebugString());
    }
    Tensor lhs;
    TF_RETURN_IF_ERROR(ReshapeToRank3(inputs[0], bcast.x_batch_size(), &lhs));
    Tensor rhs;
    TF_RETURN_IF_ERROR(ReshapeToRank3(inputs[1], bcast.y_batch_size(), &rhs));
    TensorShape output_shape = bcast.output_batch_shape();
    for (int i = 0; i < inputs.size(); ++i) {
      const int64_t free_axis =
          inputs[i].dims() - (swap_free_and_contract[i] ? 1 : 2);
      output_shape.AddDim(inputs[i].dim_size(free_axis));
    }
    bool trans_x = swap_free_and_contract[0];
    bool trans_y = !swap_free_and_contract[1];
    TF_RETURN_IF_ERROR(
        ctx->allocate_temp(DataTypeToEnum<T>::value, output_shape, output));
    if (lhs.NumElements() == 0 || rhs.NumElements() == 0) {
      functor::SetZeroFunctor<Device, T> set_zero;
      set_zero(ctx->eigen_device<Device>(), output->flat<T>());
      return Status::OK();
    }
    Tensor output_reshaped;
    TF_RETURN_IF_ERROR(
        ReshapeToRank3(*output, bcast.output_batch_size(), &output_reshaped));
    LaunchBatchMatMul<Device, T>::Launch(ctx, lhs, rhs, false,
                                         false, trans_x, trans_y,
                                         bcast, &output_reshaped);
    return Status::OK();
  }
}

static Status jf(const string& jf,
                              OperandLabels* da,
                              Labels* rt,
                              std::vector<DimensionType>* by,
                              OperandLabelCounts* er,
                              LabelCounts* lc,
                              kk, 2>* hv,
                              bool* gg) {
    gtl::InlinedVector<string, 2> input_str;
    string output_str;
    TF_RETURN_IF_ERROR(ParseEinsumEquation(jf, &input_str, &output_str));



    absl::flat_hash_map<char, int> label_mapping;
    int num_inputs = input_str.size();
    da->resize(num_inputs);


    for (int i = 0; i < num_inputs; ++i) {
      MapToLabels(input_str[i], &da->at(i), &label_mapping);
    }
    MapToLabels(output_str, rt, &label_mapping);


    int num_labels = label_mapping.size();
    er->resize(num_inputs);
    hv->resize(num_inputs);
    for (int i = 0; i < num_inputs; ++i) {
      er->at(i).resize(num_labels);
      hv->at(i) = false;
      for (const int label : da->at(i)) {
        if (label != kEllipsisLabel)
          er->at(i)[label] += 1;
        else
          hv->at(i) = true;
      }
    }
    lc->resize(num_labels);
    *gg = false;
    for (const int label : *rt) {
      if (label != kEllipsisLabel)
        lc->at(label) += 1;
      else
        *gg = true;
    }


    by->resize(num_labels);
    for (int label = 0; label < num_labels; ++label) {
      if (label == kEllipsisLabel) continue;
      bool removed = (*lc)[label] == 0;
      bool unique = num_inputs == 1 || (*er)[0][label] == 0 ||
                    (*er)[1][label] == 0;
      (*by)[label] = GetDimensionType(removed, unique);
    }
    return Status::OK();
  }


  static void InsertBroadcastLabels(int num_bcast_dims, int num_named_labels,
                                    int ellipsis_axis, Labels* labels,
                                    LabelCounts* label_counts) {
    labels->erase(labels->begin() + ellipsis_axis);
    labels->insert(labels->begin() + ellipsis_axis, num_bcast_dims, 0);
    std::iota(labels->begin() + ellipsis_axis,
              labels->begin() + ellipsis_axis + num_bcast_dims,
              num_named_labels);


    label_counts->resize(num_named_labels + num_bcast_dims, 1);
  }




  static Status RecordLabelToDimension(const int label, const int axis,
                                       const Tensor& input,
                                       LabelToDimSizes* label_to_dim_sizes) {
    const int64_t input_dim = input.dim_size(axis);

    if (label_to_dim_sizes->at(label) != 0 &&
        label_to_dim_sizes->at(label) != input_dim) {
      return errors::InvalidArgument(
          "Expected dimension ", label_to_dim_sizes->at(label), " at axis ",
          axis, " of the input shaped ", input.shape().DebugString(),
          " but got dimension ", input_dim);
    }
    (*label_to_dim_sizes)[label] = input_dim;
