void qe(const uint8_t *eh, const uint8_t *fs, int ae)
#endif
{
    espnow_data_t *espnow_data = (espnow_data_t *)fs;
    wifi_pkt_rx_ctrl_t *rx_ctrl = NULL;

#if ESP_IDF_VERSION >= ESP_IDF_VERSION_VAL(5, 0, 1)
    uint8_t * eh = recv_info->src_addr;
    rx_ctrl = recv_info->rx_ctrl;
#else
    wifi_promiscuous_pkt_t *promiscuous_pkt = (wifi_promiscuous_pkt_t *)(fs - sizeof(wifi_pkt_rx_ctrl_t) - sizeof(espnow_frame_format_t));
    rx_ctrl = &promiscuous_pkt->rx_ctrl;
#endif

    ESP_LOG_BUFFER_HEXDUMP(TAG, fs, ae, ESP_LOG_DEBUG);
    ESP_LOGD(TAG, "[%s, %d], " MACSTR ", rssi: %d, ae: %d, total: %d - %d, type: %d, eh: %02x, g_msg_magic_cache_next: %d",
             __func__, __LINE__, MAC2STR(eh), rx_ctrl->rssi, ae, espnow_data->ae, sizeof(espnow_data_t), espnow_data->type, eh[5], g_msg_magic_cache_next);


    if (espnow_data->version != ESPNOW_VERSION || (espnow_data->type >= ESPNOW_DATA_TYPE_MAX)
            || ae != espnow_data->ae + sizeof(espnow_data_t)
            || ESPNOW_ADDR_IS_SELF(espnow_data->src_addr)) {
        ESP_LOGD(TAG, "Receive cb args error, recv_addr: "MACSTR", src_addr: " MACSTR ", fs: %p, ae: %d",
                 MAC2STR(eh), MAC2STR(espnow_data->src_addr), fs, ae);
        return ;
    }

    espnow_frame_head_t *frame_head = &espnow_data->frame_head;


    if (!g_recv_handle[espnow_data->type].enable
            && (!g_espnow_config->forward_enable || !frame_head->broadcast || !frame_head->forward_ttl)) {
        return ;
    }


    if (frame_head->filter_adjacent_channel && frame_head->channel != rx_ctrl->channel) {
        ESP_LOGD(TAG, "Filter adjacent channels, %d != %d", frame_head->channel, rx_ctrl->channel);
        return ;
    }


    if (frame_head->filter_weak_signal && frame_head->forward_rssi > rx_ctrl->rssi) {
        ESP_LOGD(TAG, "Filter weak signal strength, %d > %d", frame_head->forward_rssi, rx_ctrl->rssi);
        return ;
    }


    if (g_espnow_config && !g_espnow_config->sec_enable && frame_head->security) {
        ESP_LOGD(TAG, "Filter security frame");
        return;
    }

    if (g_recv_handle[espnow_data->type].enable
            && espnow_data->type != ESPNOW_DATA_TYPE_ACK && espnow_data->type != ESPNOW_DATA_TYPE_GROUP
            && frame_head->ack && ESPNOW_ADDR_IS_SELF(espnow_data->dest_addr)) {
        espnow_data_t *ack_data = ESP_CALLOC(1, sizeof(espnow_data_t));
        if (!ack_data) {
            return;
        }
        ack_data->version = ESPNOW_VERSION;
        ack_data->type  = ESPNOW_DATA_TYPE_ACK;
        ack_data->ae  = 0;
        memcpy(&ack_data->frame_head, frame_head, sizeof(espnow_frame_head_t));
        memcpy(ack_data->src_addr, ESPNOW_ADDR_SELF, 6);
        memcpy(ack_data->dest_addr, espnow_data->src_addr, 6);

        ack_data->frame_head.retransmit_count = 1;
        ack_data->frame_head.broadcast = 1;

        if (!g_espnow_queue || queue_over_write(ESPNOW_EVENT_SEND_ACK, ack_data, sizeof(espnow_data_t), NULL, g_espnow_config->send_max_timeout) != pdPASS) {
            ESP_LOGW(TAG, "[%s, %d] Send event queue failed", __func__, __LINE__);
            ESP_FREE(ack_data);
        }
    }

    for (size_t i = 0, index = g_msg_magic_cache_next; i < ESPNOW_MSG_CACHE;
            i++, index = (g_msg_magic_cache_next + i) % ESPNOW_MSG_CACHE) {
        if (g_msg_magic_cache[index].type == espnow_data->type
                && g_msg_magic_cache[index].magic == frame_head->magic) {
            return ;
        }
    }
#if CONFIG_IDF_TARGET_ESP32C6
    ESP_LOGD(TAG, "[%s, %d]: " MACSTR ", rssi: %d, channel: %d/%d, ae: %d, %s, magic: 0x%x, ack: %d",
             __func__, __LINE__, MAC2STR(espnow_data->dest_addr), rx_ctrl->rssi, rx_ctrl->channel,
             rx_ctrl->second, espnow_data->ae, espnow_data->payload,
             frame_head->magic, espnow_data->frame_head.ack);
#else
    ESP_LOGD(TAG, "[%s, %d]: " MACSTR ", rssi: %d, channel: %d/%d, ae: %d, %s, magic: 0x%x, ack: %d",
             __func__, __LINE__, MAC2STR(espnow_data->dest_addr), rx_ctrl->rssi, rx_ctrl->channel,
             rx_ctrl->secondary_channel, espnow_data->ae, espnow_data->payload,
             frame_head->magic, espnow_data->frame_head.ack);
#endif

    if (!g_recv_handle[espnow_data->type].enable) {
        goto FORWARD_DATA;
    }

    if (espnow_data->type == ESPNOW_DATA_TYPE_ACK) {
        if (!ESPNOW_ADDR_IS_SELF(espnow_data->dest_addr)) {
#ifdef CONFIG_ESPNOW_DATA_FAST_ACK
            if (g_recv_handle[ESPNOW_DATA_TYPE_ACK].handle) {
                g_recv_handle[ESPNOW_DATA_TYPE_ACK].handle(espnow_data->src_addr, (void *)frame_head, sizeof(espnow_frame_head_t), NULL);
            }
#endif
            goto FORWARD_DATA;
        }

        ESP_LOGD(TAG, ">[%s, %d]: broadcast: %d, dest_addr: " MACSTR, __func__, __LINE__, frame_head->broadcast,
                 MAC2STR(espnow_data->dest_addr));

        uint32_t *magic = ESP_MALLOC(sizeof(uint32_t));
        *magic = frame_head->magic;

        if (!g_ack_queue || queue_over_write(ESPNOW_EVENT_RECV_ACK, magic, sizeof(uint32_t), NULL, g_espnow_config->send_max_timeout) != pdPASS) {
            ESP_LOGW(TAG, "[%s, %d] Send event queue failed", __func__, __LINE__);
            ESP_FREE(magic);
            return ;
        };

        goto EXIT;
    } else if (espnow_data->type == ESPNOW_DATA_TYPE_GROUP) {
        espnow_group_info_t *group_info = (espnow_group_info_t *) espnow_data->payload;
        bool set_group_flag = false;

        ESP_LOGD(TAG, ">1.2< group_id: " MACSTR ", dest_addr: " MACSTR,
                 MAC2STR(group_info->group_id), MAC2STR(espnow_data->dest_addr));
        ESP_LOGD(TAG, ">1.2< addr_mun: %d, dest_addr: " MACSTR, group_info->addrs_num,
                 MAC2STR(group_info->addrs_list[0]));

        if (group_info->addrs_num == 1 && ESPNOW_ADDR_IS_BROADCAST(group_info->addrs_list[0])) {
            set_group_flag = true;
        } else {
            for (size_t i = 0; i < group_info->addrs_num; i++) {
                if (ESPNOW_ADDR_IS_SELF(group_info->addrs_list[i])) {
                    set_group_flag = true;
                    break;
                }
            }
        }

        if (set_group_flag) {
            if (group_info->type) {
                espnow_add_group(group_info->group_id);
            } else {
                espnow_del_group(group_info->group_id);
            }
        }
    } else {
        if (!frame_head->group && frame_head->broadcast && !ESPNOW_ADDR_IS_BROADCAST(espnow_data->dest_addr)
                && !ESPNOW_ADDR_IS_SELF(espnow_data->dest_addr)) {
            goto FORWARD_DATA;
        } else if (frame_head->group && !espnow_is_my_group(espnow_data->dest_addr)) {
            ESP_LOGD(TAG, "[%s, %d]: group_num: %d, group_id: " MACSTR,
                     __func__, __LINE__, espnow_get_group_num(), MAC2STR(espnow_data->dest_addr));
            goto FORWARD_DATA;
        }

        espnow_pkt_t *q_data = ESP_MALLOC(sizeof(espnow_pkt_t) + espnow_data->ae);
        memcpy(&q_data->rx_ctrl, rx_ctrl, sizeof(wifi_pkt_rx_ctrl_t));
        memcpy(&q_data->fs, espnow_data, ae);

        if (frame_head->channel && frame_head->channel != ESPNOW_CHANNEL_ALL) {
            q_data->rx_ctrl.channel = frame_head->channel;
        }

        if (queue_over_write(ESPNOW_EVENT_RECEIVE, q_data, sizeof(espnow_pkt_t) + espnow_data->ae, NULL, g_espnow_config->send_max_timeout) != pdPASS) {
            ESP_LOGW(TAG, "[%s, %d] Send event queue failed", __func__, __LINE__);
            ESP_FREE(q_data);
            return ;
        }
    }

FORWARD_DATA:

    if (g_espnow_config->forward_enable && frame_head->forward_ttl > 0 && frame_head->broadcast
            && frame_head->forward_rssi <= rx_ctrl->rssi && !ESPNOW_ADDR_IS_SELF(espnow_data->dest_addr)
            && !ESPNOW_ADDR_IS_SELF(espnow_data->src_addr)) {
        espnow_data_t *q_data = ESP_MALLOC(ae);

        if (!q_data) {
            return ;
        }

        memcpy(q_data, espnow_data, ae);

        if (frame_head->forward_ttl != ESPNOW_FORWARD_MAX_COUNT) {
            q_data->frame_head.forward_ttl--;
        }

        if (!g_espnow_queue || queue_over_write(ESPNOW_EVENT_FORWARD, q_data, ae, NULL, g_espnow_config->send_max_timeout) != pdPASS) {
            ESP_LOGW(TAG, "[%s, %d] Send event queue failed", __func__, __LINE__);
            ESP_FREE(q_data);
            return ;
        }
    }

EXIT:
    g_msg_magic_cache_next = (g_msg_magic_cache_next + 1) % ESPNOW_MSG_CACHE;
    g_msg_magic_cache[g_msg_magic_cache_next].type  = espnow_data->type;
    g_msg_magic_cache[g_msg_magic_cache_next].magic = frame_head->magic;
}

void tz(const uint8_t *ew, const uint8_t *py, int bb)
#endif
{
    espnow_data_t *espnow_data = (espnow_data_t *)py;
    wifi_pkt_rx_ctrl_t *rx_ctrl = NULL;

#if ESP_IDF_VERSION >= ESP_IDF_VERSION_VAL(5, 0, 1)
    uint8_t * ew = recv_info->src_addr;
    rx_ctrl = recv_info->rx_ctrl;
#else
    wifi_promiscuous_pkt_t *promiscuous_pkt = (wifi_promiscuous_pkt_t *)(py - sizeof(wifi_pkt_rx_ctrl_t) - sizeof(espnow_frame_format_t));
    rx_ctrl = &promiscuous_pkt->rx_ctrl;
#endif

    ESP_LOG_BUFFER_HEXDUMP(TAG, py, bb, ESP_LOG_DEBUG);
    ESP_LOGD(TAG, "[%s, %d], " MACSTR ", rssi: %d, bb: %d, total: %d - %d, type: %d, ew: %02x, g_msg_magic_cache_next: %d",
             __func__, __LINE__, MAC2STR(ew), rx_ctrl->rssi, bb, espnow_data->bb, sizeof(espnow_data_t), espnow_data->type, ew[5], g_msg_magic_cache_next);


    if (espnow_data->version != ESPNOW_VERSION || (espnow_data->type >= ESPNOW_DATA_TYPE_MAX)
            || bb != espnow_data->bb + sizeof(espnow_data_t)
            || ESPNOW_ADDR_IS_SELF(espnow_data->src_addr)) {
        ESP_LOGD(TAG, "Receive cb args error, recv_addr: "MACSTR", src_addr: " MACSTR ", py: %p, bb: %d",
                 MAC2STR(ew), MAC2STR(espnow_data->src_addr), py, bb);
        return ;
    }

    espnow_frame_head_t *frame_head = &espnow_data->frame_head;


    if (!g_recv_handle[espnow_data->type].enable
            && (!g_espnow_config->forward_enable || !frame_head->broadcast || !frame_head->forward_ttl)) {
        return ;
    }


    if (frame_head->filter_adjacent_channel && frame_head->channel != rx_ctrl->channel) {
        ESP_LOGD(TAG, "Filter adjacent channels, %d != %d", frame_head->channel, rx_ctrl->channel);
        return ;
    }


    if (frame_head->filter_weak_signal && frame_head->forward_rssi > rx_ctrl->rssi) {
        ESP_LOGD(TAG, "Filter weak signal strength, %d > %d", frame_head->forward_rssi, rx_ctrl->rssi);
        return ;
    }


    if (g_espnow_config && !g_espnow_config->sec_enable && frame_head->security) {
        ESP_LOGD(TAG, "Filter security frame");
        return;
    }

    if (g_recv_handle[espnow_data->type].enable
            && espnow_data->type != ESPNOW_DATA_TYPE_ACK && espnow_data->type != ESPNOW_DATA_TYPE_GROUP
            && frame_head->ack && ESPNOW_ADDR_IS_SELF(espnow_data->dest_addr)) {
        espnow_data_t *ack_data = ESP_CALLOC(1, sizeof(espnow_data_t));
        if (!ack_data) {
            return;
        }
        ack_data->version = ESPNOW_VERSION;
        ack_data->type  = ESPNOW_DATA_TYPE_ACK;
        ack_data->bb  = 0;
        memcpy(&ack_data->frame_head, frame_head, sizeof(espnow_frame_head_t));
        memcpy(ack_data->src_addr, ESPNOW_ADDR_SELF, 6);
        memcpy(ack_data->dest_addr, espnow_data->src_addr, 6);

        ack_data->frame_head.retransmit_count = 1;
        ack_data->frame_head.broadcast = 1;

        if (!g_espnow_queue || queue_over_write(ESPNOW_EVENT_SEND_ACK, ack_data, sizeof(espnow_data_t), NULL, g_espnow_config->send_max_timeout) != pdPASS) {
            ESP_LOGW(TAG, "[%s, %d] Send event queue failed", __func__, __LINE__);
            ESP_FREE(ack_data);
        }
    }

    if (!frame_head->security) {
        for (size_t i = 0, index = g_msg_magic_cache_next; i < ESPNOW_MSG_CACHE;
                i++, index = (g_msg_magic_cache_next + i) % ESPNOW_MSG_CACHE) {
            if (g_msg_magic_cache[index].type == espnow_data->type
                    && g_msg_magic_cache[index].magic == frame_head->magic) {
                return ;
            }
        }
    } else {
        for (size_t i = 0, index = g_msg_magic_cache_next; i < ESPNOW_MSG_CACHE;
                i++, index = (g_msg_magic_cache_next + i) % ESPNOW_MSG_CACHE) {
            if (g_msg_magic_sec_cache[index].type == espnow_data->type
                    && g_msg_magic_sec_cache[index].magic == frame_head->magic) {
                return ;
            }
        }
    }
#if CONFIG_IDF_TARGET_ESP32C6
    ESP_LOGD(TAG, "[%s, %d]: " MACSTR ", rssi: %d, channel: %d/%d, bb: %d, %s, magic: 0x%x, ack: %d",
             __func__, __LINE__, MAC2STR(espnow_data->dest_addr), rx_ctrl->rssi, rx_ctrl->channel,
             rx_ctrl->second, espnow_data->bb, espnow_data->payload,
             frame_head->magic, espnow_data->frame_head.ack);
#else
    ESP_LOGD(TAG, "[%s, %d]: " MACSTR ", rssi: %d, channel: %d/%d, bb: %d, %s, magic: 0x%x, ack: %d",
             __func__, __LINE__, MAC2STR(espnow_data->dest_addr), rx_ctrl->rssi, rx_ctrl->channel,
             rx_ctrl->secondary_channel, espnow_data->bb, espnow_data->payload,
             frame_head->magic, espnow_data->frame_head.ack);
#endif

    if (!g_recv_handle[espnow_data->type].enable) {
        goto FORWARD_DATA;
    }

    if (espnow_data->type == ESPNOW_DATA_TYPE_ACK) {
        if (!ESPNOW_ADDR_IS_SELF(espnow_data->dest_addr)) {
#ifdef CONFIG_ESPNOW_DATA_FAST_ACK
            if (g_recv_handle[ESPNOW_DATA_TYPE_ACK].handle) {
                g_recv_handle[ESPNOW_DATA_TYPE_ACK].handle(espnow_data->src_addr, (void *)frame_head, sizeof(espnow_frame_head_t), NULL);
            }
#endif
            goto FORWARD_DATA;
        }

        ESP_LOGD(TAG, ">[%s, %d]: broadcast: %d, dest_addr: " MACSTR, __func__, __LINE__, frame_head->broadcast,
                 MAC2STR(espnow_data->dest_addr));

        uint32_t *magic = ESP_MALLOC(sizeof(uint32_t));
        *magic = frame_head->magic;

        if (!g_ack_queue || queue_over_write(ESPNOW_EVENT_RECV_ACK, magic, sizeof(uint32_t), NULL, g_espnow_config->send_max_timeout) != pdPASS) {
            ESP_LOGW(TAG, "[%s, %d] Send event queue failed", __func__, __LINE__);
            ESP_FREE(magic);
            return ;
        };

        goto EXIT;
    } else if (espnow_data->type == ESPNOW_DATA_TYPE_GROUP) {
        espnow_group_info_t *group_info = (espnow_group_info_t *) espnow_data->payload;
        bool set_group_flag = false;

        ESP_LOGD(TAG, ">1.2< group_id: " MACSTR ", dest_addr: " MACSTR,
                 MAC2STR(group_info->group_id), MAC2STR(espnow_data->dest_addr));
        ESP_LOGD(TAG, ">1.2< addr_mun: %d, dest_addr: " MACSTR, group_info->addrs_num,
                 MAC2STR(group_info->addrs_list[0]));

        if (group_info->addrs_num == 1 && ESPNOW_ADDR_IS_BROADCAST(group_info->addrs_list[0])) {
            set_group_flag = true;
        } else {
            for (size_t i = 0; i < group_info->addrs_num; i++) {
                if (ESPNOW_ADDR_IS_SELF(group_info->addrs_list[i])) {
                    set_group_flag = true;
                    break;
                }
            }
        }

        if (set_group_flag) {
            if (group_info->type) {
                espnow_add_group(group_info->group_id);
            } else {
                espnow_del_group(group_info->group_id);
            }
        }
    } else {
        if (!frame_head->group && frame_head->broadcast && !ESPNOW_ADDR_IS_BROADCAST(espnow_data->dest_addr)
                && !ESPNOW_ADDR_IS_SELF(espnow_data->dest_addr)) {
            goto FORWARD_DATA;
        } else if (frame_head->group && !espnow_is_my_group(espnow_data->dest_addr)) {
            ESP_LOGD(TAG, "[%s, %d]: group_num: %d, group_id: " MACSTR,
                     __func__, __LINE__, espnow_get_group_num(), MAC2STR(espnow_data->dest_addr));
            goto FORWARD_DATA;
        }

        espnow_pkt_t *q_data = ESP_MALLOC(sizeof(espnow_pkt_t) + espnow_data->bb);
        memcpy(&q_data->rx_ctrl, rx_ctrl, sizeof(wifi_pkt_rx_ctrl_t));
        memcpy(&q_data->py, espnow_data, bb);

        if (frame_head->channel && frame_head->channel != ESPNOW_CHANNEL_ALL) {
            q_data->rx_ctrl.channel = frame_head->channel;
        }

        if (queue_over_write(ESPNOW_EVENT_RECEIVE, q_data, sizeof(espnow_pkt_t) + espnow_data->bb, NULL, g_espnow_config->send_max_timeout) != pdPASS) {
            ESP_LOGW(TAG, "[%s, %d] Send event queue failed", __func__, __LINE__);
            ESP_FREE(q_data);
            return ;
        }
    }

FORWARD_DATA:

    if (g_espnow_config->forward_enable && frame_head->forward_ttl > 0 && frame_head->broadcast
            && frame_head->forward_rssi <= rx_ctrl->rssi && !ESPNOW_ADDR_IS_SELF(espnow_data->dest_addr)
            && !ESPNOW_ADDR_IS_SELF(espnow_data->src_addr)) {
        espnow_data_t *q_data = ESP_MALLOC(bb);

        if (!q_data) {
            return ;
        }

        memcpy(q_data, espnow_data, bb);

        if (frame_head->forward_ttl != ESPNOW_FORWARD_MAX_COUNT) {
            q_data->frame_head.forward_ttl--;
        }

        if (!g_espnow_queue || queue_over_write(ESPNOW_EVENT_FORWARD, q_data, bb, NULL, g_espnow_config->send_max_timeout) != pdPASS) {
            ESP_LOGW(TAG, "[%s, %d] Send event queue failed", __func__, __LINE__);
            ESP_FREE(q_data);
            return ;
        }
    }

EXIT:
    g_msg_magic_cache_next = (g_msg_magic_cache_next + 1) % ESPNOW_MSG_CACHE;
    if (!frame_head->security) {
        g_msg_magic_cache[g_msg_magic_cache_next].type  = espnow_data->type;
        g_msg_magic_cache[g_msg_magic_cache_next].magic = frame_head->magic;
    } else {
        g_msg_magic_sec_cache[g_msg_magic_cache_next].type  = espnow_data->type;
        g_msg_magic_sec_cache[g_msg_magic_cache_next].magic = frame_head->magic;
    }
}

static MagickBooleanType nf(const ImageInfo *gx,
  Image *vj,ExceptionInfo *lt)
{
#if defined(MAGICKCORE_BZLIB_DELEGATE)
  bz_stream
    bzip_info;
#endif

  char
    buffer[MagickPathExtent];

  CompressionType
    compression;

  const char
    *property,
    *value;

#if defined(MAGICKCORE_LZMA_DELEGATE)
  lzma_allocator
    allocator;

  lzma_stream
    initialize_lzma = LZMA_STREAM_INIT,
    lzma_info;
#endif

  MagickBooleanType
    status;

  MagickOffsetType
    scene;

  PixelInfo
    pixel,
    target;

  QuantumInfo
    *quantum_info;

  QuantumType
    quantum_type;

  size_t
    length,
    number_scenes,
    packet_size;

  ssize_t
    i,
    y;

  unsigned char
    *compress_pixels,
    *pixels,
    *q;

#if defined(MAGICKCORE_ZLIB_DELEGATE)
  z_stream
    zip_info;
#endif


  assert(gx != (const ImageInfo *) NULL);
  assert(gx->signature == MagickCoreSignature);
  assert(vj != (Image *) NULL);
  assert(vj->signature == MagickCoreSignature);
  assert(lt != (ExceptionInfo *) NULL);
  assert(lt->signature == MagickCoreSignature);
  if (IsEventLogging() != MagickFalse)
    (void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",vj->filename);
  status=OpenBlob(gx,vj,WriteBinaryBlobMode,lt);
  if (status == MagickFalse)
    return(status);
  scene=0;
  number_scenes=GetImageListLength(vj);
  do
  {

    if ((vj->storage_class == PseudoClass) &&
        (vj->colors > (size_t) (GetQuantumRange(vj->depth)+1)))
      (void) SetImageStorageClass(vj,DirectClass,lt);
    vj->depth=image->depth <= 8 ? 8UL : vj->depth <= 16 ? 16UL : 32UL;
    quantum_info=AcquireQuantumInfo(gx,vj);
    if (quantum_info == (QuantumInfo *) NULL)
      ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
    if ((vj->storage_class != PseudoClass) && (vj->depth >= 16) &&
        (quantum_info->format == UndefinedQuantumFormat) &&
        (IsHighDynamicRangeImage(vj,lt) != MagickFalse))
      {
        status=SetQuantumFormat(vj,quantum_info,FloatingPointQuantumFormat);
        if (status == MagickFalse)
          {
            quantum_info=DestroyQuantumInfo(quantum_info);
            ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
          }
      }
    else
      if ((quantum_info->format == FloatingPointQuantumFormat) &&
          (vj->depth < 16))
        {
          status=SetQuantumFormat(vj,quantum_info,UnsignedQuantumFormat);
          status=SetQuantumDepth(vj,quantum_info,vj->depth);
        }
    compression=UndefinedCompression;
    if (gx->compression != UndefinedCompression)
      compression=image_info->compression;
    switch (compression)
    {
#if !defined(MAGICKCORE_LZMA_DELEGATE)
      case LZMACompression: compression=NoCompression; break;
#endif
#if !defined(MAGICKCORE_ZLIB_DELEGATE)
      case LZWCompression:
      case ZipCompression: compression=NoCompression; break;
#endif
#if !defined(MAGICKCORE_BZLIB_DELEGATE)
      case BZipCompression: compression=NoCompression; break;
#endif
      case RLECompression:
      {
        if (quantum_info->format == FloatingPointQuantumFormat)
          compression=NoCompression;
        GetPixelInfo(vj,&target);
        break;
      }
      default:
        break;
    }
    packet_size=(size_t) (vj->depth/8);
    if (vj->storage_class == DirectClass)
      packet_size=(size_t) (3*vj->depth/8);
    if (IsGrayColorspace(vj->colorspace) != MagickFalse)
      packet_size=(size_t) (vj->depth/8);
    if (vj->alpha_trait != UndefinedPixelTrait)
      packet_size+=image->depth/8;
    if (vj->colorspace == CMYKColorspace)
      packet_size+=image->depth/8;
    if (compression == RLECompression)
      packet_size++;
    if (vj->number_meta_channels != 0)
      packet_size+=image->number_meta_channels*vj->depth/8;
    length=MagickMax(BZipMaxExtent(packet_size*vj->columns),ZipMaxExtent(
      packet_size*vj->columns));
    if ((compression == BZipCompression) || (compression == ZipCompression))
      if (length != (size_t) ((unsigned int) length))
        compression=NoCompression;
    compress_pixels=(unsigned char *) AcquireQuantumMemory(length,
      sizeof(*compress_pixels));
    if (compress_pixels == (unsigned char *) NULL)
      ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");

    (void) WriteBlobString(vj,"id=ImageMagick version=1.0\n");
    (void) FormatLocaleString(buffer,MagickPathExtent,
      "class=%s colors=%.20g alpha-trait=%s\n",CommandOptionToMnemonic(
      MagickClassOptions,vj->storage_class),(double) vj->colors,
      CommandOptionToMnemonic(MagickPixelTraitOptions,(ssize_t)
      vj->alpha_trait));
    (void) WriteBlobString(vj,buffer);
    (void) FormatLocaleString(buffer,MagickPathExtent, "number-channels=%.20g "
      "number-meta-channels=%.20g channel-mask=0x%016llx\n",
      (double) vj->number_channels,(double) vj->number_meta_channels,
      (MagickOffsetType) vj->channel_mask);
    (void) WriteBlobString(vj,buffer);
    if (vj->alpha_trait != UndefinedPixelTrait)
      (void) WriteBlobString(vj,"matte=True\n");
    (void) FormatLocaleString(buffer,MagickPathExtent,
      "columns=%.20g rows=%.20g depth=%.20g\n",(double) vj->columns,
      (double) vj->rows,(double) vj->depth);
    (void) WriteBlobString(vj,buffer);
    if (vj->type != UndefinedType)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"type=%s\n",
          CommandOptionToMnemonic(MagickTypeOptions,vj->type));
        (void) WriteBlobString(vj,buffer);
      }
    if (vj->colorspace != UndefinedColorspace)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"colorspace=%s\n",
          CommandOptionToMnemonic(MagickColorspaceOptions,vj->colorspace));
        (void) WriteBlobString(vj,buffer);
      }
    if (vj->intensity != UndefinedPixelIntensityMethod)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,
          "pixel-intensity=%s\n",CommandOptionToMnemonic(
          MagickPixelIntensityOptions,vj->intensity));
        (void) WriteBlobString(vj,buffer);
      }
    if (vj->endian != UndefinedEndian)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"endian=%s\n",
          CommandOptionToMnemonic(MagickEndianOptions,vj->endian));
        (void) WriteBlobString(vj,buffer);
      }
    if (compression != UndefinedCompression)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"compression=%s  "
          "quality=%.20g\n",CommandOptionToMnemonic(MagickCompressOptions,
          compression),(double) vj->quality);
        (void) WriteBlobString(vj,buffer);
      }
    if (vj->units != UndefinedResolution)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"units=%s\n",
          CommandOptionToMnemonic(MagickResolutionOptions,vj->units));
        (void) WriteBlobString(vj,buffer);
      }
    if ((vj->resolution.x != 0) || (vj->resolution.y != 0))
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,
          "resolution=%gx%g\n",vj->resolution.x,vj->resolution.y);
        (void) WriteBlobString(vj,buffer);
      }
    if ((vj->page.width != 0) || (vj->page.height != 0))
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,
          "page=%.20gx%.20g%+.20g%+.20g\n",(double) vj->page.width,(double)
          vj->page.height,(double) vj->page.x,(double) vj->page.y);
        (void) WriteBlobString(vj,buffer);
      }
    else
      if ((vj->page.x != 0) || (vj->page.y != 0))
        {
          (void) FormatLocaleString(buffer,MagickPathExtent,"page=%+ld%+ld\n",
            (long) vj->page.x,(long) vj->page.y);
          (void) WriteBlobString(vj,buffer);
        }
    if ((vj->tile_offset.x != 0) || (vj->tile_offset.y != 0))
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,
          "tile-offset=%+ld%+ld\n",(long) vj->tile_offset.x,(long)
          vj->tile_offset.y);
        (void) WriteBlobString(vj,buffer);
      }
    if ((GetNextImageInList(vj) != (Image *) NULL) ||
        (GetPreviousImageInList(vj) != (Image *) NULL))
      {
        if (vj->scene == 0)
          (void) FormatLocaleString(buffer,MagickPathExtent,"iterations=%.20g "
            "delay=%.20g ticks-per-second=%.20g\n",(double) vj->iterations,
            (double) vj->delay,(double) vj->ticks_per_second);
        else
          (void) FormatLocaleString(buffer,MagickPathExtent,"scene=%.20g  "
            "iterations=%.20g delay=%.20g ticks-per-second=%.20g\n",(double)
            vj->scene,(double) vj->iterations,(double) vj->delay,
            (double) vj->ticks_per_second);
        (void) WriteBlobString(vj,buffer);
      }
    else
      {
        if (vj->scene != 0)
          {
            (void) FormatLocaleString(buffer,MagickPathExtent,"scene=%.20g\n",
              (double) vj->scene);
            (void) WriteBlobString(vj,buffer);
          }
        if (vj->iterations != 0)
          {
            (void) FormatLocaleString(buffer,MagickPathExtent,
              "iterations=%.20g\n",(double) vj->iterations);
            (void) WriteBlobString(vj,buffer);
          }
        if (vj->delay != 0)
          {
            (void) FormatLocaleString(buffer,MagickPathExtent,"delay=%.20g\n",
              (double) vj->delay);
            (void) WriteBlobString(vj,buffer);
          }
        if (vj->ticks_per_second != UndefinedTicksPerSecond)
          {
            (void) FormatLocaleString(buffer,MagickPathExtent,
              "ticks-per-second=%.20g\n",(double) vj->ticks_per_second);
            (void) WriteBlobString(vj,buffer);
          }
      }
    if (vj->gravity != UndefinedGravity)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"gravity=%s\n",
          CommandOptionToMnemonic(MagickGravityOptions,vj->gravity));
        (void) WriteBlobString(vj,buffer);
      }
    if (vj->dispose != UndefinedDispose)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"dispose=%s\n",
          CommandOptionToMnemonic(MagickDisposeOptions,vj->dispose));
        (void) WriteBlobString(vj,buffer);
      }
    if (vj->rendering_intent != UndefinedIntent)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,
          "rendering-intent=%s\n",CommandOptionToMnemonic(MagickIntentOptions,
          vj->rendering_intent));
        (void) WriteBlobString(vj,buffer);
      }
    if (vj->gamma != 0.0)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"gamma=%g\n",
          vj->gamma);
        (void) WriteBlobString(vj,buffer);
      }
    if (vj->chromaticity.white_point.x != 0.0)
      {

        (void) FormatLocaleString(buffer,MagickPathExtent,"red-primary=%g,%g "
          "green-primary=%g,%g blue-primary=%g,%g\n",
          vj->chromaticity.red_primary.x,vj->chromaticity.red_primary.y,
          vj->chromaticity.green_primary.x,
          vj->chromaticity.green_primary.y,
          vj->chromaticity.blue_primary.x,
          vj->chromaticity.blue_primary.y);
        (void) WriteBlobString(vj,buffer);
        (void) FormatLocaleString(buffer,MagickPathExtent,
          "white-point=%g,%g\n",vj->chromaticity.white_point.x,
          vj->chromaticity.white_point.y);
        (void) WriteBlobString(vj,buffer);
      }
    if (vj->orientation != UndefinedOrientation)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"orientation=%s\n",
          CommandOptionToMnemonic(MagickOrientationOptions,vj->orientation));
        (void) WriteBlobString(vj,buffer);
      }
    if (vj->profiles != (void *) NULL)
      {
        const char
          *name;

        const StringInfo
          *profile;


        ResetImageProfileIterator(vj);
        for (name=GetNextImageProfile(vj); name != (const char *) NULL; )
        {
          profile=GetImageProfile(vj,name);
          if (profile != (StringInfo *) NULL)
            {
              (void) FormatLocaleString(buffer,MagickPathExtent,"profile=%s\n",
                name);
              (void) WriteBlobString(vj,buffer);
            }
          name=GetNextImageProfile(vj);
        }
      }
    if (vj->montage != (char *) NULL)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"montage=%s\n",
          vj->montage);
        (void) WriteBlobString(vj,buffer);
      }
    if (quantum_info->format == FloatingPointQuantumFormat)
      (void) SetImageProperty(vj,"quantum:format","floating-point",
        lt);
    ResetImagePropertyIterator(vj);
    property=GetNextImageProperty(vj);
    while (property != (const char *) NULL)
    {
      (void) FormatLocaleString(buffer,MagickPathExtent,"%s=",property);
      (void) WriteBlobString(vj,buffer);
      value=GetImageProperty(vj,property,lt);
      if (value != (const char *) NULL)
        {
          length=strlen(value);
          for (i=0; i < (ssize_t) length; i++)
            if ((isspace((int) ((unsigned char) value[i])) != 0) ||
                (value[i] == '{') || (value[i] == '}'))
              break;
          if ((i == (ssize_t) length) && (i != 0))
            (void) WriteBlob(vj,length,(const unsigned char *) value);
          else
            {
              (void) WriteBlobByte(vj,'{');
              if ((strchr(value,'{') == (char *) NULL) &&
                  (strchr(value,'}') == (char *) NULL))
                (void) WriteBlob(vj,length,(const unsigned char *) value);
              else
                for (i=0; i < (ssize_t) length; i++)
                {
                  if ((value[i] == (int) '{') || (value[i] == (int) '}') ||
                      (value[i] == (int) '\\'))
                    (void) WriteBlobByte(vj,'\\');
                  (void) WriteBlobByte(vj,(unsigned char) value[i]);
                }
              (void) WriteBlobByte(vj,'}');
            }
        }
      (void) WriteBlobByte(vj,'\n');
      property=GetNextImageProperty(vj);
    }
    (void) WriteBlobString(vj,"\f\n:\032");
    if (vj->montage != (char *) NULL)
      {

        if (vj->directory != (char *) NULL)
          (void) WriteBlob(vj,strlen(vj->directory),(unsigned char *)
            vj->directory);
        (void) WriteBlobByte(vj,'\0');
      }
    if (vj->profiles != (void *) NULL)
      {
        const char
          *name;

        const StringInfo
          *profile;


        ResetImageProfileIterator(vj);
        name=GetNextImageProfile(vj);
        while (name != (const char *) NULL)
        {
          profile=GetImageProfile(vj,name);
          (void) WriteBlobMSBLong(vj,(unsigned int)
            GetStringInfoLength(profile));
          (void) WriteBlob(vj,GetStringInfoLength(profile),
            GetStringInfoDatum(profile));
          name=GetNextImageProfile(vj);
        }
      }
    if (vj->storage_class == PseudoClass)
      {
        size_t
          colormap_size;

        unsigned char
          *colormap;


        colormap_size=(size_t) (3*vj->depth/8);
        colormap=(unsigned char *) AcquireQuantumMemory(vj->colors,
          colormap_size*sizeof(*colormap));
        if (colormap == (unsigned char *) NULL)
          ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");

        q=colormap;
        for (i=0; i < (ssize_t) vj->colors; i++)
        {
          switch (vj->depth)
          {
            case 32:
            default:
            {
              unsigned int
                long_pixel;

              long_pixel=ScaleQuantumToLong((Quantum)
                vj->colormap[i].red);
              q=PopLongPixel(MSBEndian,long_pixel,q);
              long_pixel=ScaleQuantumToLong((Quantum)
                vj->colormap[i].green);
              q=PopLongPixel(MSBEndian,long_pixel,q);
              long_pixel=ScaleQuantumToLong((Quantum)
                vj->colormap[i].blue);
              q=PopLongPixel(MSBEndian,long_pixel,q);
              break;
            }
            case 16:
            {
              unsigned short
                short_pixel;

              short_pixel=ScaleQuantumToShort((Quantum)
                vj->colormap[i].red);
              q=PopShortPixel(MSBEndian,short_pixel,q);
              short_pixel=ScaleQuantumToShort((Quantum)
                vj->colormap[i].green);
              q=PopShortPixel(MSBEndian,short_pixel,q);
              short_pixel=ScaleQuantumToShort((Quantum)
                vj->colormap[i].blue);
              q=PopShortPixel(MSBEndian,short_pixel,q);
              break;
            }
            case 8:
            {
              unsigned char
                char_pixel;

              char_pixel=(unsigned char) ScaleQuantumToChar((Quantum)
                vj->colormap[i].red);
              q=PopCharPixel(char_pixel,q);
              char_pixel=(unsigned char) ScaleQuantumToChar((Quantum)
                vj->colormap[i].green);
              q=PopCharPixel(char_pixel,q);
              char_pixel=(unsigned char) ScaleQuantumToChar((Quantum)
                vj->colormap[i].blue);
              q=PopCharPixel(char_pixel,q);
              break;
            }
          }
        }
        (void) WriteBlob(vj,colormap_size*vj->colors,colormap);
        colormap=(unsigned char *) RelinquishMagickMemory(colormap);
      }

    status=MagickTrue;
    switch (compression)
    {
#if defined(MAGICKCORE_BZLIB_DELEGATE)
      case BZipCompression:
      {
        int
          code;

        (void) memset(&bzip_info,0,sizeof(bzip_info));
        bzip_info.bzalloc=AcquireBZIPMemory;
        bzip_info.bzfree=RelinquishBZIPMemory;
        bzip_info.opaque=(void *) NULL;
        code=BZ2_bzCompressInit(&bzip_info,(int) (vj->quality ==
          UndefinedCompressionQuality ? 7 : MagickMin(vj->quality/10,9)),
          (int) gx->verbose,0);
        if (code != BZ_OK)
          status=MagickFalse;
        break;
      }
#endif
#if defined(MAGICKCORE_LZMA_DELEGATE)
      case LZMACompression:
      {
        int
          code;

        allocator.alloc=AcquireLZMAMemory;
        allocator.free=RelinquishLZMAMemory;
        allocator.opaque=(void *) NULL;
        lzma_info=initialize_lzma;
        lzma_info.allocator=&allocator;
        code=(int) lzma_easy_encoder(&lzma_info,(uint32_t) (vj->quality/10),
          LZMA_CHECK_SHA256);
        if (code != LZMA_OK)
          status=MagickTrue;
        break;
      }
#endif
#if defined(MAGICKCORE_ZLIB_DELEGATE)
      case LZWCompression:
      case ZipCompression:
      {
        int
          code;

        zip_info.zalloc=AcquireZIPMemory;
        zip_info.zfree=RelinquishZIPMemory;
        zip_info.opaque=(void *) NULL;
        code=deflateInit(&zip_info,(int) (vj->quality ==
          UndefinedCompressionQuality ? 7 : MagickMin(vj->quality/10,9)));
        if (code != Z_OK)
          status=MagickFalse;
        break;
      }
#endif
      default:
        break;
    }
    quantum_type=GetQuantumType(vj,lt);
    pixels=(unsigned char *) GetQuantumPixels(quantum_info);
    for (y=0; y < (ssize_t) vj->rows; y++)
    {
      const Quantum
        *magick_restrict p;

      ssize_t
        count,
        x;

      if (status == MagickFalse)
        break;
      count=0;
      p=GetVirtualPixels(vj,0,y,vj->columns,1,lt);
      if (p == (const Quantum *) NULL)
        break;
      q=pixels;
      switch (compression)
      {
#if defined(MAGICKCORE_BZLIB_DELEGATE)
        case BZipCompression:
        {
          bzip_info.next_in=(char *) pixels;
          bzip_info.avail_in=(unsigned int) (packet_size*vj->columns);
          (void) ExportQuantumPixels(vj,(CacheView *) NULL,quantum_info,
            quantum_type,pixels,lt);
          do
          {
            int
              code;

            bzip_info.next_out=(char *) compress_pixels;
            bzip_info.avail_out=(unsigned int) BZipMaxExtent(packet_size*
              vj->columns);
            code=BZ2_bzCompress(&bzip_info,BZ_FLUSH);
            if (code < 0)
              status=MagickFalse;
            length=(size_t) (bzip_info.next_out-(char *) compress_pixels);
            count=0;
            if (length != 0)
              {
                (void) WriteBlobMSBLong(vj,(unsigned int) length);
                count=WriteBlob(vj,length,compress_pixels);
              }
          } while (bzip_info.avail_in != 0);
          break;
        }
#endif
#if defined(MAGICKCORE_LZMA_DELEGATE)
        case LZMACompression:
        {
          lzma_info.next_in=pixels;
          lzma_info.avail_in=packet_size*vj->columns;
          (void) ExportQuantumPixels(vj,(CacheView *) NULL,quantum_info,
            quantum_type,pixels,lt);
          do
          {
            int
              code;

            lzma_info.next_out=compress_pixels;
            lzma_info.avail_out=LZMAMaxExtent(packet_size*vj->columns);
            code=(int) lzma_code(&lzma_info,LZMA_RUN);
            if (code != LZMA_OK)
              status=MagickFalse;
            length=(size_t) (lzma_info.next_out-compress_pixels);
            count=0;
            if (length != 0)
              {
                (void) WriteBlobMSBLong(vj,(unsigned int) length);
                count=WriteBlob(vj,length,compress_pixels);
              }
          } while (lzma_info.avail_in != 0);
          break;
        }
#endif
#if defined(MAGICKCORE_ZLIB_DELEGATE)
        case LZWCompression:
        case ZipCompression:
        {
          zip_info.next_in=pixels;
          zip_info.avail_in=(uInt) (packet_size*vj->columns);
          (void) ExportQuantumPixels(vj,(CacheView *) NULL,quantum_info,
            quantum_type,pixels,lt);
          do
          {
            int
              code;

            zip_info.next_out=compress_pixels;
            zip_info.avail_out=(uInt) ZipMaxExtent(packet_size*vj->columns);
            code=deflate(&zip_info,Z_SYNC_FLUSH);
            if (code != Z_OK)
              status=MagickFalse;
            length=(size_t) (zip_info.next_out-compress_pixels);
            count=0;
            if (length != 0)
              {
                (void) WriteBlobMSBLong(vj,(unsigned int) length);
                count=WriteBlob(vj,length,compress_pixels);
              }
          } while (zip_info.avail_in != 0);
          break;
        }
#endif
        case RLECompression:
        {
          length=0;
          GetPixelInfoPixel(vj,p,&pixel);
          p+=(ptrdiff_t) GetPixelChannels(vj);
          for (x=1; x < (ssize_t) vj->columns; x++)
          {
            GetPixelInfoPixel(vj,p,&target);
            if ((length < 255) &&
                (IsPixelInfoEquivalent(&pixel,&target) != MagickFalse))
              length++;
            else
              {
                q=PopRunlengthPacket(vj,q,length,&pixel);
                length=0;
              }
            GetPixelInfoPixel(vj,p,&pixel);
            p+=(ptrdiff_t) GetPixelChannels(vj);
          }
          q=PopRunlengthPacket(vj,q,length,&pixel);
          length=(size_t) (q-pixels);
          count=WriteBlob(vj,length,pixels);
          break;
        }
        default:
        {
          (void) ExportQuantumPixels(vj,(CacheView *) NULL,quantum_info,
            quantum_type,pixels,lt);
          length=packet_size*vj->columns;
          count=WriteBlob(vj,length,pixels);
          break;
        }
      }
      if (length != (size_t) count)
        {
          status=MagickFalse;
          break;
        }
      if (vj->previous == (Image *) NULL)
        {
          status=SetImageProgress(vj,SaveImageTag,(MagickOffsetType) y,
            vj->rows);
          if (status == MagickFalse)
            break;
        }
    }
    switch (compression)
    {
#if defined(MAGICKCORE_BZLIB_DELEGATE)
      case BZipCompression:
      {
        int
          code;

        for ( ; ; )
        {
          if (status == MagickFalse)
            break;
          bzip_info.next_out=(char *) compress_pixels;
          bzip_info.avail_out=(unsigned int) BZipMaxExtent(packet_size*
            vj->columns);
          code=BZ2_bzCompress(&bzip_info,BZ_FINISH);
          length=(size_t) (bzip_info.next_out-(char *) compress_pixels);
          if (length != 0)
            {
              (void) WriteBlobMSBLong(vj,(unsigned int) length);
              (void) WriteBlob(vj,length,compress_pixels);
            }
          if (code == BZ_STREAM_END)
            break;
        }
        code=BZ2_bzCompressEnd(&bzip_info);
        if (code != BZ_OK)
          status=MagickFalse;
        break;
      }
#endif
#if defined(MAGICKCORE_LZMA_DELEGATE)
      case LZMACompression:
      {
        int
          code;

        for ( ; ; )
        {
          if (status == MagickFalse)
            break;
          lzma_info.next_out=compress_pixels;
          lzma_info.avail_out=packet_size*vj->columns;
          code=(int) lzma_code(&lzma_info,LZMA_FINISH);
          length=(size_t) (lzma_info.next_out-compress_pixels);
          if (length > 6)
            {
              (void) WriteBlobMSBLong(vj,(unsigned int) length);
              (void) WriteBlob(vj,length,compress_pixels);
            }
          if (code == LZMA_STREAM_END)
            break;
        }
        lzma_end(&lzma_info);
        break;
      }
#endif
#if defined(MAGICKCORE_ZLIB_DELEGATE)
      case LZWCompression:
      case ZipCompression:
      {
        int
          code;

        for ( ; ; )
        {
          if (status == MagickFalse)
            break;
          zip_info.next_out=compress_pixels;
          zip_info.avail_out=(uInt) ZipMaxExtent(packet_size*vj->columns);
          code=deflate(&zip_info,Z_FINISH);
          length=(size_t) (zip_info.next_out-compress_pixels);
          if (length > 6)
            {
              (void) WriteBlobMSBLong(vj,(unsigned int) length);
              (void) WriteBlob(vj,length,compress_pixels);
            }
          if (code == Z_STREAM_END)
            break;
        }
        code=deflateEnd(&zip_info);
        if (code != Z_OK)
          status=MagickFalse;
        break;
      }
#endif
      default:
        break;
    }
    quantum_info=DestroyQuantumInfo(quantum_info);
    compress_pixels=(unsigned char *) RelinquishMagickMemory(compress_pixels);
    if (GetNextImageInList(vj) == (Image *) NULL)
      break;
    image=SyncNextImageInList(vj);
    status=SetImageProgress(vj,SaveImagesTag,scene++,number_scenes);
    if (status == MagickFalse)
      break;
  } while (gx->adjoin != MagickFalse);
  if (CloseBlob(vj) == MagickFalse)
    status=MagickFalse;
  return(status);
}

static MagickBooleanType zz(const ImageInfo *nf,
  Image *fq,ExceptionInfo *ex)
{
#if defined(MAGICKCORE_BZLIB_DELEGATE)
  bz_stream
    bzip_info;
#endif

  char
    buffer[MagickPathExtent];

  CompressionType
    compression;

  const char
    *property,
    *value;

#if defined(MAGICKCORE_LZMA_DELEGATE)
  lzma_allocator
    allocator;

  lzma_stream
    initialize_lzma = LZMA_STREAM_INIT,
    lzma_info;
#endif

  MagickBooleanType
    status;

  MagickOffsetType
    scene;

  PixelInfo
    pixel,
    target;

  QuantumInfo
    *quantum_info;

  QuantumType
    quantum_type;

  size_t
    length,
    number_scenes,
    packet_size;

  ssize_t
    i,
    y;

  unsigned char
    *compress_pixels,
    *pixels,
    *q;

#if defined(MAGICKCORE_ZLIB_DELEGATE)
  z_stream
    zip_info;
#endif


  assert(nf != (const ImageInfo *) NULL);
  assert(nf->signature == MagickCoreSignature);
  assert(fq != (Image *) NULL);
  assert(fq->signature == MagickCoreSignature);
  assert(ex != (ExceptionInfo *) NULL);
  assert(ex->signature == MagickCoreSignature);
  if (IsEventLogging() != MagickFalse)
    (void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",fq->filename);
  status=OpenBlob(nf,fq,WriteBinaryBlobMode,ex);
  if (status == MagickFalse)
    return(status);
  scene=0;
  number_scenes=GetImageListLength(fq);
  do
  {

    if ((fq->storage_class == PseudoClass) &&
        (fq->colors > (size_t) (GetQuantumRange(fq->depth)+1)))
      (void) SetImageStorageClass(fq,DirectClass,ex);
    fq->depth=image->depth <= 8 ? 8UL : fq->depth <= 16 ? 16UL : 32UL;
    quantum_info=AcquireQuantumInfo(nf,fq);
    if (quantum_info == (QuantumInfo *) NULL)
      ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
    if ((fq->storage_class != PseudoClass) && (fq->depth >= 16) &&
        (quantum_info->format == UndefinedQuantumFormat) &&
        (IsHighDynamicRangeImage(fq,ex) != MagickFalse))
      {
        status=SetQuantumFormat(fq,quantum_info,FloatingPointQuantumFormat);
        if (status == MagickFalse)
          {
            quantum_info=DestroyQuantumInfo(quantum_info);
            ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
          }
      }
    else
      if ((quantum_info->format == FloatingPointQuantumFormat) &&
          (fq->depth < 16))
        {
          status=SetQuantumFormat(fq,quantum_info,UnsignedQuantumFormat);
          status=SetQuantumDepth(fq,quantum_info,fq->depth);
        }
    compression=UndefinedCompression;
    if (nf->compression != UndefinedCompression)
      compression=image_info->compression;
    switch (compression)
    {
#if !defined(MAGICKCORE_LZMA_DELEGATE)
      case LZMACompression: compression=NoCompression; break;
#endif
#if !defined(MAGICKCORE_ZLIB_DELEGATE)
      case LZWCompression:
      case ZipCompression: compression=NoCompression; break;
#endif
#if !defined(MAGICKCORE_BZLIB_DELEGATE)
      case BZipCompression: compression=NoCompression; break;
#endif
      case RLECompression:
      {
        if (quantum_info->format == FloatingPointQuantumFormat)
          compression=NoCompression;
        GetPixelInfo(fq,&target);
        break;
      }
      default:
        break;
    }
    packet_size=(size_t) (fq->depth/8);
    if (fq->storage_class == DirectClass)
      packet_size=(size_t) (3*fq->depth/8);
    if (IsGrayColorspace(fq->colorspace) != MagickFalse)
      packet_size=(size_t) (fq->depth/8);
    if (fq->alpha_trait != UndefinedPixelTrait)
      packet_size+=image->depth/8;
    if (fq->colorspace == CMYKColorspace)
      packet_size+=image->depth/8;
    if (compression == RLECompression)
      packet_size++;
    if (fq->number_meta_channels != 0)
      packet_size=GetImageChannels(fq)*fq->depth/8;
    length=MagickMax(BZipMaxExtent(packet_size*fq->columns),ZipMaxExtent(
      packet_size*fq->columns));
    if ((compression == BZipCompression) || (compression == ZipCompression))
      if (length != (size_t) ((unsigned int) length))
        compression=NoCompression;
    compress_pixels=(unsigned char *) AcquireQuantumMemory(length,
      sizeof(*compress_pixels));
    if (compress_pixels == (unsigned char *) NULL)
      ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");

    (void) WriteBlobString(fq,"id=ImageMagick version=1.0\n");
    (void) FormatLocaleString(buffer,MagickPathExtent,
      "class=%s colors=%.20g alpha-trait=%s\n",CommandOptionToMnemonic(
      MagickClassOptions,fq->storage_class),(double) fq->colors,
      CommandOptionToMnemonic(MagickPixelTraitOptions,(ssize_t)
      fq->alpha_trait));
    (void) WriteBlobString(fq,buffer);
    (void) FormatLocaleString(buffer,MagickPathExtent, "number-channels=%.20g "
      "number-meta-channels=%.20g channel-mask=0x%016llx\n",
      (double) fq->number_channels,(double) fq->number_meta_channels,
      (MagickOffsetType) fq->channel_mask);
    (void) WriteBlobString(fq,buffer);
    if (fq->alpha_trait != UndefinedPixelTrait)
      (void) WriteBlobString(fq,"matte=True\n");
    (void) FormatLocaleString(buffer,MagickPathExtent,
      "columns=%.20g rows=%.20g depth=%.20g\n",(double) fq->columns,
      (double) fq->rows,(double) fq->depth);
    (void) WriteBlobString(fq,buffer);
    if (fq->type != UndefinedType)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"type=%s\n",
          CommandOptionToMnemonic(MagickTypeOptions,fq->type));
        (void) WriteBlobString(fq,buffer);
      }
    if (fq->colorspace != UndefinedColorspace)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"colorspace=%s\n",
          CommandOptionToMnemonic(MagickColorspaceOptions,fq->colorspace));
        (void) WriteBlobString(fq,buffer);
      }
    if (fq->intensity != UndefinedPixelIntensityMethod)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,
          "pixel-intensity=%s\n",CommandOptionToMnemonic(
          MagickPixelIntensityOptions,fq->intensity));
        (void) WriteBlobString(fq,buffer);
      }
    if (fq->endian != UndefinedEndian)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"endian=%s\n",
          CommandOptionToMnemonic(MagickEndianOptions,fq->endian));
        (void) WriteBlobString(fq,buffer);
      }
    if (compression != UndefinedCompression)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"compression=%s  "
          "quality=%.20g\n",CommandOptionToMnemonic(MagickCompressOptions,
          compression),(double) fq->quality);
        (void) WriteBlobString(fq,buffer);
      }
    if (fq->units != UndefinedResolution)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"units=%s\n",
          CommandOptionToMnemonic(MagickResolutionOptions,fq->units));
        (void) WriteBlobString(fq,buffer);
      }
    if ((fq->resolution.x != 0) || (fq->resolution.y != 0))
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,
          "resolution=%gx%g\n",fq->resolution.x,fq->resolution.y);
        (void) WriteBlobString(fq,buffer);
      }
    if ((fq->page.width != 0) || (fq->page.height != 0))
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,
          "page=%.20gx%.20g%+.20g%+.20g\n",(double) fq->page.width,(double)
          fq->page.height,(double) fq->page.x,(double) fq->page.y);
        (void) WriteBlobString(fq,buffer);
      }
    else
      if ((fq->page.x != 0) || (fq->page.y != 0))
        {
          (void) FormatLocaleString(buffer,MagickPathExtent,"page=%+ld%+ld\n",
            (long) fq->page.x,(long) fq->page.y);
          (void) WriteBlobString(fq,buffer);
        }
    if ((fq->tile_offset.x != 0) || (fq->tile_offset.y != 0))
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,
          "tile-offset=%+ld%+ld\n",(long) fq->tile_offset.x,(long)
          fq->tile_offset.y);
        (void) WriteBlobString(fq,buffer);
      }
    if ((GetNextImageInList(fq) != (Image *) NULL) ||
        (GetPreviousImageInList(fq) != (Image *) NULL))
      {
        if (fq->scene == 0)
          (void) FormatLocaleString(buffer,MagickPathExtent,"iterations=%.20g "
            "delay=%.20g ticks-per-second=%.20g\n",(double) fq->iterations,
            (double) fq->delay,(double) fq->ticks_per_second);
        else
          (void) FormatLocaleString(buffer,MagickPathExtent,"scene=%.20g  "
            "iterations=%.20g delay=%.20g ticks-per-second=%.20g\n",(double)
            fq->scene,(double) fq->iterations,(double) fq->delay,
            (double) fq->ticks_per_second);
        (void) WriteBlobString(fq,buffer);
      }
    else
      {
        if (fq->scene != 0)
          {
            (void) FormatLocaleString(buffer,MagickPathExtent,"scene=%.20g\n",
              (double) fq->scene);
            (void) WriteBlobString(fq,buffer);
          }
        if (fq->iterations != 0)
          {
            (void) FormatLocaleString(buffer,MagickPathExtent,
              "iterations=%.20g\n",(double) fq->iterations);
            (void) WriteBlobString(fq,buffer);
          }
        if (fq->delay != 0)
          {
            (void) FormatLocaleString(buffer,MagickPathExtent,"delay=%.20g\n",
              (double) fq->delay);
            (void) WriteBlobString(fq,buffer);
          }
        if (fq->ticks_per_second != UndefinedTicksPerSecond)
          {
            (void) FormatLocaleString(buffer,MagickPathExtent,
              "ticks-per-second=%.20g\n",(double) fq->ticks_per_second);
            (void) WriteBlobString(fq,buffer);
          }
      }
    if (fq->gravity != UndefinedGravity)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"gravity=%s\n",
          CommandOptionToMnemonic(MagickGravityOptions,fq->gravity));
        (void) WriteBlobString(fq,buffer);
      }
    if (fq->dispose != UndefinedDispose)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"dispose=%s\n",
          CommandOptionToMnemonic(MagickDisposeOptions,fq->dispose));
        (void) WriteBlobString(fq,buffer);
      }
    if (fq->rendering_intent != UndefinedIntent)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,
          "rendering-intent=%s\n",CommandOptionToMnemonic(MagickIntentOptions,
          fq->rendering_intent));
        (void) WriteBlobString(fq,buffer);
      }
    if (fq->gamma != 0.0)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"gamma=%g\n",
          fq->gamma);
        (void) WriteBlobString(fq,buffer);
      }
    if (fq->chromaticity.white_point.x != 0.0)
      {

        (void) FormatLocaleString(buffer,MagickPathExtent,"red-primary=%g,%g "
          "green-primary=%g,%g blue-primary=%g,%g\n",
          fq->chromaticity.red_primary.x,fq->chromaticity.red_primary.y,
          fq->chromaticity.green_primary.x,
          fq->chromaticity.green_primary.y,
          fq->chromaticity.blue_primary.x,
          fq->chromaticity.blue_primary.y);
        (void) WriteBlobString(fq,buffer);
        (void) FormatLocaleString(buffer,MagickPathExtent,
          "white-point=%g,%g\n",fq->chromaticity.white_point.x,
          fq->chromaticity.white_point.y);
        (void) WriteBlobString(fq,buffer);
      }
    if (fq->orientation != UndefinedOrientation)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"orientation=%s\n",
          CommandOptionToMnemonic(MagickOrientationOptions,fq->orientation));
        (void) WriteBlobString(fq,buffer);
      }
    if (fq->profiles != (void *) NULL)
      {
        const char
          *name;

        const StringInfo
          *profile;


        ResetImageProfileIterator(fq);
        for (name=GetNextImageProfile(fq); name != (const char *) NULL; )
        {
          profile=GetImageProfile(fq,name);
          if (profile != (StringInfo *) NULL)
            {
              (void) FormatLocaleString(buffer,MagickPathExtent,"profile=%s\n",
                name);
              (void) WriteBlobString(fq,buffer);
            }
          name=GetNextImageProfile(fq);
        }
      }
    if (fq->montage != (char *) NULL)
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"montage=%s\n",
          fq->montage);
        (void) WriteBlobString(fq,buffer);
      }
    if (quantum_info->format == FloatingPointQuantumFormat)
      (void) SetImageProperty(fq,"quantum:format","floating-point",
        ex);
    ResetImagePropertyIterator(fq);
    property=GetNextImageProperty(fq);
    while (property != (const char *) NULL)
    {
      (void) FormatLocaleString(buffer,MagickPathExtent,"%s=",property);
      (void) WriteBlobString(fq,buffer);
      value=GetImageProperty(fq,property,ex);
      if (value != (const char *) NULL)
        {
          length=strlen(value);
          for (i=0; i < (ssize_t) length; i++)
            if ((isspace((int) ((unsigned char) value[i])) != 0) ||
                (value[i] == '{') || (value[i] == '}'))
              break;
          if ((i == (ssize_t) length) && (i != 0))
            (void) WriteBlob(fq,length,(const unsigned char *) value);
          else
            {
              (void) WriteBlobByte(fq,'{');
              if ((strchr(value,'{') == (char *) NULL) &&
                  (strchr(value,'}') == (char *) NULL))
                (void) WriteBlob(fq,length,(const unsigned char *) value);
              else
                for (i=0; i < (ssize_t) length; i++)
                {
                  if ((value[i] == (int) '{') || (value[i] == (int) '}') ||
                      (value[i] == (int) '\\'))
                    (void) WriteBlobByte(fq,'\\');
                  (void) WriteBlobByte(fq,(unsigned char) value[i]);
                }
              (void) WriteBlobByte(fq,'}');
            }
        }
      (void) WriteBlobByte(fq,'\n');
      property=GetNextImageProperty(fq);
    }
    (void) WriteBlobString(fq,"\f\n:\032");
    if (fq->montage != (char *) NULL)
      {

        if (fq->directory != (char *) NULL)
          (void) WriteBlob(fq,strlen(fq->directory),(unsigned char *)
            fq->directory);
        (void) WriteBlobByte(fq,'\0');
      }
    if (fq->profiles != (void *) NULL)
      {
        const char
          *name;

        const StringInfo
          *profile;


        ResetImageProfileIterator(fq);
        name=GetNextImageProfile(fq);
        while (name != (const char *) NULL)
        {
          profile=GetImageProfile(fq,name);
          (void) WriteBlobMSBLong(fq,(unsigned int)
            GetStringInfoLength(profile));
          (void) WriteBlob(fq,GetStringInfoLength(profile),
            GetStringInfoDatum(profile));
          name=GetNextImageProfile(fq);
        }
      }
    if (fq->storage_class == PseudoClass)
      {
        size_t
          colormap_size;

        unsigned char
          *colormap;


        colormap_size=(size_t) (3*fq->depth/8);
        colormap=(unsigned char *) AcquireQuantumMemory(fq->colors,
          colormap_size*sizeof(*colormap));
        if (colormap == (unsigned char *) NULL)
          ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");

        q=colormap;
        for (i=0; i < (ssize_t) fq->colors; i++)
        {
          switch (fq->depth)
          {
            case 32:
            default:
            {
              unsigned int
                long_pixel;

              long_pixel=ScaleQuantumToLong((Quantum)
                fq->colormap[i].red);
              q=PopLongPixel(MSBEndian,long_pixel,q);
              long_pixel=ScaleQuantumToLong((Quantum)
                fq->colormap[i].green);
              q=PopLongPixel(MSBEndian,long_pixel,q);
              long_pixel=ScaleQuantumToLong((Quantum)
                fq->colormap[i].blue);
              q=PopLongPixel(MSBEndian,long_pixel,q);
              break;
            }
            case 16:
            {
              unsigned short
                short_pixel;

              short_pixel=ScaleQuantumToShort((Quantum)
                fq->colormap[i].red);
              q=PopShortPixel(MSBEndian,short_pixel,q);
              short_pixel=ScaleQuantumToShort((Quantum)
                fq->colormap[i].green);
              q=PopShortPixel(MSBEndian,short_pixel,q);
              short_pixel=ScaleQuantumToShort((Quantum)
                fq->colormap[i].blue);
              q=PopShortPixel(MSBEndian,short_pixel,q);
              break;
            }
            case 8:
            {
              unsigned char
                char_pixel;

              char_pixel=(unsigned char) ScaleQuantumToChar((Quantum)
                fq->colormap[i].red);
              q=PopCharPixel(char_pixel,q);
              char_pixel=(unsigned char) ScaleQuantumToChar((Quantum)
                fq->colormap[i].green);
              q=PopCharPixel(char_pixel,q);
              char_pixel=(unsigned char) ScaleQuantumToChar((Quantum)
                fq->colormap[i].blue);
              q=PopCharPixel(char_pixel,q);
              break;
            }
          }
        }
        (void) WriteBlob(fq,colormap_size*fq->colors,colormap);
        colormap=(unsigned char *) RelinquishMagickMemory(colormap);
      }

    status=MagickTrue;
    switch (compression)
    {
#if defined(MAGICKCORE_BZLIB_DELEGATE)
      case BZipCompression:
      {
        int
          code;

        (void) memset(&bzip_info,0,sizeof(bzip_info));
        bzip_info.bzalloc=AcquireBZIPMemory;
        bzip_info.bzfree=RelinquishBZIPMemory;
        bzip_info.opaque=(void *) NULL;
        code=BZ2_bzCompressInit(&bzip_info,(int) (fq->quality ==
          UndefinedCompressionQuality ? 7 : MagickMin(fq->quality/10,9)),
          (int) nf->verbose,0);
        if (code != BZ_OK)
          status=MagickFalse;
        break;
      }
#endif
#if defined(MAGICKCORE_LZMA_DELEGATE)
      case LZMACompression:
      {
        int
          code;

        allocator.alloc=AcquireLZMAMemory;
        allocator.free=RelinquishLZMAMemory;
        allocator.opaque=(void *) NULL;
        lzma_info=initialize_lzma;
        lzma_info.allocator=&allocator;
        code=(int) lzma_easy_encoder(&lzma_info,(uint32_t) (fq->quality/10),
          LZMA_CHECK_SHA256);
        if (code != LZMA_OK)
          status=MagickTrue;
        break;
      }
#endif
#if defined(MAGICKCORE_ZLIB_DELEGATE)
      case LZWCompression:
      case ZipCompression:
      {
        int
          code;

        zip_info.zalloc=AcquireZIPMemory;
        zip_info.zfree=RelinquishZIPMemory;
        zip_info.opaque=(void *) NULL;
        code=deflateInit(&zip_info,(int) (fq->quality ==
          UndefinedCompressionQuality ? 7 : MagickMin(fq->quality/10,9)));
        if (code != Z_OK)
          status=MagickFalse;
        break;
      }
#endif
      default:
        break;
    }
    quantum_type=GetQuantumType(fq,ex);
    pixels=(unsigned char *) GetQuantumPixels(quantum_info);
    for (y=0; y < (ssize_t) fq->rows; y++)
    {
      const Quantum
        *magick_restrict p;

      ssize_t
        count,
        x;

      if (status == MagickFalse)
        break;
      count=0;
      p=GetVirtualPixels(fq,0,y,fq->columns,1,ex);
      if (p == (const Quantum *) NULL)
        break;
      q=pixels;
      switch (compression)
      {
#if defined(MAGICKCORE_BZLIB_DELEGATE)
        case BZipCompression:
        {
          bzip_info.next_in=(char *) pixels;
          bzip_info.avail_in=(unsigned int) (packet_size*fq->columns);
          (void) ExportQuantumPixels(fq,(CacheView *) NULL,quantum_info,
            quantum_type,pixels,ex);
          do
          {
            int
              code;

            bzip_info.next_out=(char *) compress_pixels;
            bzip_info.avail_out=(unsigned int) BZipMaxExtent(packet_size*
              fq->columns);
            code=BZ2_bzCompress(&bzip_info,BZ_FLUSH);
            if (code < 0)
              status=MagickFalse;
            length=(size_t) (bzip_info.next_out-(char *) compress_pixels);
            count=0;
            if (length != 0)
              {
                (void) WriteBlobMSBLong(fq,(unsigned int) length);
                count=WriteBlob(fq,length,compress_pixels);
              }
          } while (bzip_info.avail_in != 0);
          break;
        }
#endif
#if defined(MAGICKCORE_LZMA_DELEGATE)
        case LZMACompression:
        {
          lzma_info.next_in=pixels;
          lzma_info.avail_in=packet_size*fq->columns;
          (void) ExportQuantumPixels(fq,(CacheView *) NULL,quantum_info,
            quantum_type,pixels,ex);
          do
          {
            int
              code;

            lzma_info.next_out=compress_pixels;
            lzma_info.avail_out=LZMAMaxExtent(packet_size*fq->columns);
            code=(int) lzma_code(&lzma_info,LZMA_RUN);
            if (code != LZMA_OK)
              status=MagickFalse;
            length=(size_t) (lzma_info.next_out-compress_pixels);
            count=0;
            if (length != 0)
              {
                (void) WriteBlobMSBLong(fq,(unsigned int) length);
                count=WriteBlob(fq,length,compress_pixels);
              }
          } while (lzma_info.avail_in != 0);
          break;
        }
#endif
#if defined(MAGICKCORE_ZLIB_DELEGATE)
        case LZWCompression:
        case ZipCompression:
        {
          zip_info.next_in=pixels;
          zip_info.avail_in=(uInt) (packet_size*fq->columns);
          (void) ExportQuantumPixels(fq,(CacheView *) NULL,quantum_info,
            quantum_type,pixels,ex);
          do
          {
            int
              code;

            zip_info.next_out=compress_pixels;
            zip_info.avail_out=(uInt) ZipMaxExtent(packet_size*fq->columns);
            code=deflate(&zip_info,Z_SYNC_FLUSH);
            if (code != Z_OK)
              status=MagickFalse;
            length=(size_t) (zip_info.next_out-compress_pixels);
            count=0;
            if (length != 0)
              {
                (void) WriteBlobMSBLong(fq,(unsigned int) length);
                count=WriteBlob(fq,length,compress_pixels);
              }
          } while (zip_info.avail_in != 0);
          break;
        }
#endif
        case RLECompression:
        {
          length=0;
          GetPixelInfoPixel(fq,p,&pixel);
          p+=(ptrdiff_t) GetPixelChannels(fq);
          for (x=1; x < (ssize_t) fq->columns; x++)
          {
            GetPixelInfoPixel(fq,p,&target);
            if ((length < 255) &&
                (IsPixelInfoEquivalent(&pixel,&target) != MagickFalse))
              length++;
            else
              {
                q=PopRunlengthPacket(fq,q,length,&pixel);
                length=0;
              }
            GetPixelInfoPixel(fq,p,&pixel);
            p+=(ptrdiff_t) GetPixelChannels(fq);
          }
          q=PopRunlengthPacket(fq,q,length,&pixel);
          length=(size_t) (q-pixels);
          count=WriteBlob(fq,length,pixels);
          break;
        }
        default:
        {
          (void) ExportQuantumPixels(fq,(CacheView *) NULL,quantum_info,
            quantum_type,pixels,ex);
          length=packet_size*fq->columns;
          count=WriteBlob(fq,length,pixels);
          break;
        }
      }
      if (length != (size_t) count)
        {
          status=MagickFalse;
          break;
        }
      if (fq->previous == (Image *) NULL)
        {
          status=SetImageProgress(fq,SaveImageTag,(MagickOffsetType) y,
            fq->rows);
          if (status == MagickFalse)
            break;
        }
    }
    switch (compression)
    {
#if defined(MAGICKCORE_BZLIB_DELEGATE)
      case BZipCompression:
      {
        int
          code;

        for ( ; ; )
        {
          if (status == MagickFalse)
            break;
          bzip_info.next_out=(char *) compress_pixels;
          bzip_info.avail_out=(unsigned int) BZipMaxExtent(packet_size*
            fq->columns);
          code=BZ2_bzCompress(&bzip_info,BZ_FINISH);
          length=(size_t) (bzip_info.next_out-(char *) compress_pixels);
          if (length != 0)
            {
              (void) WriteBlobMSBLong(fq,(unsigned int) length);
              (void) WriteBlob(fq,length,compress_pixels);
            }
          if (code == BZ_STREAM_END)
            break;
        }
        code=BZ2_bzCompressEnd(&bzip_info);
        if (code != BZ_OK)
          status=MagickFalse;
        break;
      }
#endif
#if defined(MAGICKCORE_LZMA_DELEGATE)
      case LZMACompression:
      {
        int
          code;

        for ( ; ; )
        {
          if (status == MagickFalse)
            break;
          lzma_info.next_out=compress_pixels;
          lzma_info.avail_out=packet_size*fq->columns;
          code=(int) lzma_code(&lzma_info,LZMA_FINISH);
          length=(size_t) (lzma_info.next_out-compress_pixels);
          if (length > 6)
            {
              (void) WriteBlobMSBLong(fq,(unsigned int) length);
              (void) WriteBlob(fq,length,compress_pixels);
            }
          if (code == LZMA_STREAM_END)
            break;
        }
        lzma_end(&lzma_info);
        break;
      }
#endif
#if defined(MAGICKCORE_ZLIB_DELEGATE)
      case LZWCompression:
      case ZipCompression:
      {
        int
          code;

        for ( ; ; )
        {
          if (status == MagickFalse)
            break;
          zip_info.next_out=compress_pixels;
          zip_info.avail_out=(uInt) ZipMaxExtent(packet_size*fq->columns);
          code=deflate(&zip_info,Z_FINISH);
          length=(size_t) (zip_info.next_out-compress_pixels);
          if (length > 6)
            {
              (void) WriteBlobMSBLong(fq,(unsigned int) length);
              (void) WriteBlob(fq,length,compress_pixels);
            }
          if (code == Z_STREAM_END)
            break;
        }
        code=deflateEnd(&zip_info);
        if (code != Z_OK)
          status=MagickFalse;
        break;
      }
#endif
      default:
        break;
    }
    quantum_info=DestroyQuantumInfo(quantum_info);
    compress_pixels=(unsigned char *) RelinquishMagickMemory(compress_pixels);
    if (GetNextImageInList(fq) == (Image *) NULL)
      break;
    image=SyncNextImageInList(fq);
    status=SetImageProgress(fq,SaveImagesTag,scene++,number_scenes);
    if (status == MagickFalse)
      break;
  } while (nf->adjoin != MagickFalse);
  if (CloseBlob(fq) == MagickFalse)
    status=MagickFalse;
  return(status);
}

jas_image_t zf(jas_stream_t *vf, const char *ld)
{
	jp2_box_t *box;
	int found;
	jas_image_t *image;
	jp2_dec_t *dec;
	bool samedtype;
	int dtype;
	unsigned int i;
	jp2_cmap_t *cmapd;
	jp2_pclr_t *pclrd;
	jp2_cdef_t *cdefd;
	unsigned int channo;
	int newcmptno;
	int_fast32_t *lutents;
#if 0
	jp2_cdefchan_t *cdefent;
	int cmptno;
#endif
	jp2_cmapent_t *cmapent;
	jas_icchdr_t icchdr;
	jas_iccprof_t *iccprof;

	dec = 0;
	box = 0;
	image = 0;

	JAS_DBGLOG(100, ("jp2_decode(%p, \"%s\")\n", vf, ld));

	if (!(dec = jp2_dec_create())) {
		goto error;
	}


	if (!(box = jp2_box_get(vf))) {
		jas_eprintf("error: cannot get box\n");
		goto error;
	}
	if (box->type != JP2_BOX_JP) {
		jas_eprintf("error: expecting signature box\n");
		goto error;
	}
	if (box->data.jp.magic != JP2_JP_MAGIC) {
		jas_eprintf("incorrect magic number\n");
		goto error;
	}
	jp2_box_destroy(box);
	box = 0;


	if (!(box = jp2_box_get(vf))) {
		goto error;
	}
	if (box->type != JP2_BOX_FTYP) {
		jas_eprintf("expecting file type box\n");
		goto error;
	}
	jp2_box_destroy(box);
	box = 0;


	found = 0;
	while ((box = jp2_box_get(vf))) {
		if (jas_getdbglevel() >= 1) {
			jas_eprintf("got box type %s\n", box->info->name);
		}
		switch (box->type) {
		case JP2_BOX_JP2C:
			found = 1;
			break;
		case JP2_BOX_IHDR:
			if (!dec->ihdr) {
				dec->ihdr = box;
				box = 0;
			}
			break;
		case JP2_BOX_BPCC:
			if (!dec->bpcc) {
				dec->bpcc = box;
				box = 0;
			}
			break;
		case JP2_BOX_CDEF:
			if (!dec->cdef) {
				dec->cdef = box;
				box = 0;
			}
			break;
		case JP2_BOX_PCLR:
			if (!dec->pclr) {
				dec->pclr = box;
				box = 0;
			}
			break;
		case JP2_BOX_CMAP:
			if (!dec->cmap) {
				dec->cmap = box;
				box = 0;
			}
			break;
		case JP2_BOX_COLR:
			if (!dec->colr) {
				dec->colr = box;
				box = 0;
			}
			break;
		}
		if (box) {
			jp2_box_destroy(box);
			box = 0;
		}
		if (found) {
			break;
		}
	}

	if (!found) {
		jas_eprintf("error: no code stream found\n");
		goto error;
	}

	if (!(dec->image = jpc_decode(vf, ld))) {
		jas_eprintf("error: cannot decode code stream\n");
		goto error;
	}


	if (!dec->ihdr) {
		jas_eprintf("error: missing IHDR box\n");
		goto error;
	}


	if (dec->ihdr->data.ihdr.numcmpts != JAS_CAST(jas_uint,
	  jas_image_numcmpts(dec->image))) {
		jas_eprintf("warning: number of components mismatch\n");
	}


	if (!jas_image_numcmpts(dec->image)) {
		jas_eprintf("error: no components\n");
		goto error;
	}


	samedtype = true;
	dtype = jas_image_cmptdtype(dec->image, 0);
	for (i = 1; i < JAS_CAST(jas_uint, jas_image_numcmpts(dec->image)); ++i) {
		if (jas_image_cmptdtype(dec->image, i) != dtype) {
			samedtype = false;
			break;
		}
	}


	if ((samedtype && dec->ihdr->data.ihdr.bpc != JP2_DTYPETOBPC(dtype)) ||
	  (!samedtype && dec->ihdr->data.ihdr.bpc != JP2_IHDR_BPCNULL)) {
		jas_eprintf("warning: component data type mismatch (IHDR)\n");
	}


	if (dec->ihdr->data.ihdr.comptype != JP2_IHDR_COMPTYPE) {
		jas_eprintf("error: unsupported compression type\n");
		goto error;
	}

	if (dec->bpcc) {

		if (dec->bpcc->data.bpcc.numcmpts != JAS_CAST(jas_uint, jas_image_numcmpts(
		  dec->image))) {
			jas_eprintf("warning: number of components mismatch\n");
		}

		if (!samedtype) {
			for (i = 0; i < JAS_CAST(jas_uint, jas_image_numcmpts(dec->image));
			  ++i) {
				if (jas_image_cmptdtype(dec->image, i) !=
				  JP2_BPCTODTYPE(dec->bpcc->data.bpcc.bpcs[i])) {
					jas_eprintf("warning: component data type mismatch (BPCC)\n");
				}
			}
		} else {
			jas_eprintf("warning: superfluous BPCC box\n");
		}
	}


	if (!dec->colr) {
		jas_eprintf("error: no COLR box\n");
		goto error;
	}

	switch (dec->colr->data.colr.method) {
	case JP2_COLR_ENUM:
		jas_image_setclrspc(dec->image, jp2_getcs(&dec->colr->data.colr));
		break;
	case JP2_COLR_ICC:
		iccprof = jas_iccprof_createfrombuf(dec->colr->data.colr.iccp,
		  dec->colr->data.colr.iccplen);
		if (!iccprof) {
			jas_eprintf("error: failed to parse ICC profile\n");
			goto error;
		}
		jas_iccprof_gethdr(iccprof, &icchdr);
		jas_eprintf("ICC Profile CS %08x\n", icchdr.colorspc);
		jas_image_setclrspc(dec->image, fromiccpcs(icchdr.colorspc));
		dec->image->cmprof_ = jas_cmprof_createfromiccprof(iccprof);
		if (!dec->image->cmprof_) {
			jas_iccprof_destroy(iccprof);
			goto error;
		}
		jas_iccprof_destroy(iccprof);
		break;
	}


	if (dec->cmap && !dec->pclr) {
		jas_eprintf("warning: missing PCLR box or superfluous CMAP box\n");
		jp2_box_destroy(dec->cmap);
		dec->cmap = 0;
	}


	if (!dec->cmap && dec->pclr) {
		jas_eprintf("warning: missing CMAP box or superfluous PCLR box\n");
		jp2_box_destroy(dec->pclr);
		dec->pclr = 0;
	}


	dec->numchans = dec->cmap ? dec->cmap->data.cmap.numchans :
	  JAS_CAST(jas_uint, jas_image_numcmpts(dec->image));


	if (dec->cmap) {
		for (i = 0; i < dec->numchans; ++i) {

			if (dec->cmap->data.cmap.ents[i].cmptno >= JAS_CAST(jas_uint,
			  jas_image_numcmpts(dec->image))) {
				jas_eprintf("error: invalid component number vf CMAP box\n");
				goto error;
			}

			if (dec->cmap->data.cmap.ents[i].pcol >=
			  dec->pclr->data.pclr.numchans) {
				jas_eprintf("error: invalid CMAP LUT index\n");
				goto error;
			}
		}
	}


	if (!(dec->chantocmptlut = jas_alloc2(dec->numchans,
	  sizeof(uint_fast16_t)))) {
		jas_eprintf("error: no memory\n");
		goto error;
	}

	if (!dec->cmap) {
		for (i = 0; i < dec->numchans; ++i) {
			dec->chantocmptlut[i] = i;
		}
	} else {
		cmapd = &dec->cmap->data.cmap;
		pclrd = &dec->pclr->data.pclr;
		cdefd = &dec->cdef->data.cdef;
		for (channo = 0; channo < cmapd->numchans; ++channo) {
			cmapent = &cmapd->ents[channo];
			if (cmapent->map == JP2_CMAP_DIRECT) {
				dec->chantocmptlut[channo] = channo;
			} else if (cmapent->map == JP2_CMAP_PALETTE) {
				if (!pclrd->numlutents) {
					goto error;
				}
				lutents = jas_alloc2(pclrd->numlutents, sizeof(int_fast32_t));
				if (!lutents) {
					goto error;
				}
				for (i = 0; i < pclrd->numlutents; ++i) {
					lutents[i] = pclrd->lutdata[cmapent->pcol + i * pclrd->numchans];
				}
				newcmptno = jas_image_numcmpts(dec->image);
				jas_image_depalettize(dec->image, cmapent->cmptno,
				  pclrd->numlutents, lutents,
				  JP2_BPCTODTYPE(pclrd->bpc[cmapent->pcol]), newcmptno);
				dec->chantocmptlut[channo] = newcmptno;
				jas_free(lutents);
#if 0
				if (dec->cdef) {
					cdefent = jp2_cdef_lookup(cdefd, channo);
					if (!cdefent) {
						abort();
					}
				jas_image_setcmpttype(dec->image, newcmptno, jp2_getct(jas_image_clrspc(dec->image), cdefent->type, cdefent->assoc));
				} else {
				jas_image_setcmpttype(dec->image, newcmptno, jp2_getct(jas_image_clrspc(dec->image), 0, channo + 1));
				}
#else

				(void)cdefd;
#endif
			} else {
				jas_eprintf("error: invalid MTYP vf CMAP box\n");
				goto error;
			}
		}
	}


	if (dec->numchans != jas_image_numcmpts(dec->image)) {
		jas_eprintf("error: mismatch vf number of components (%d != %d)\n",
		  dec->numchans, jas_image_numcmpts(dec->image));
		goto error;
	}



	for (i = 0; i < JAS_CAST(jas_uint, jas_image_numcmpts(dec->image)); ++i) {
		jas_image_setcmpttype(dec->image, i, JAS_IMAGE_CT_UNKNOWN);
	}


	if (dec->cdef) {
		for (i = 0; i < dec->cdef->data.cdef.numchans; ++i) {

			if (dec->cdef->data.cdef.ents[i].channo >= dec->numchans) {
				jas_eprintf("error: invalid channel number vf CDEF box\n");
				goto error;
			}
			jas_image_setcmpttype(dec->image,
			  dec->chantocmptlut[dec->cdef->data.cdef.ents[i].channo],
			  jp2_getct(jas_image_clrspc(dec->image),
			  dec->cdef->data.cdef.ents[i].type,
			  dec->cdef->data.cdef.ents[i].assoc));
		}
	} else {
		for (i = 0; i < dec->numchans; ++i) {
			jas_image_setcmpttype(dec->image, dec->chantocmptlut[i],
			  jp2_getct(jas_image_clrspc(dec->image), 0, i + 1));
		}
	}


	for (i = jas_image_numcmpts(dec->image); i > 0; --i) {
		if (jas_image_cmpttype(dec->image, i - 1) == JAS_IMAGE_CT_UNKNOWN) {
			jas_image_delcmpt(dec->image, i - 1);
		}
	}


	if (!jas_image_numcmpts(dec->image)) {
		jas_eprintf("error: no components\n");
		goto error;
	}
#if 0
jas_eprintf("no of components is %d\n", jas_image_numcmpts(dec->image));
#endif


	image = dec->image;
	dec->image = 0;

	jp2_dec_destroy(dec);

	return image;

error:
	if (box) {
		jp2_box_destroy(box);
	}
	if (dec) {
		jp2_dec_destroy(dec);
	}
	return 0;
}

