      new (strPrim_.buffer) Handle<StringPrimitive>(other.strPrim());
  }

  StringView &operator=(const StringView &other) {
    if (this != &other) {
      if (isHandle_)
        strPrim().~Handle<StringPrimitive>();
      ::memcpy(this, &other, sizeof(*this));
      if (isHandle_)
        new (strPrim_.buffer) Handle<StringPrimitive>(other.strPrim());
    }
    return *this;
  }

  ~StringView() {
    if (isHandle_)
      strPrim().~Handle<StringPrimitive>();
  }
#else
  StringView(const StringView &other) = default;
  ~StringView() = default;
#endif

  StringView(const char *ptr) : StringView(ASCIIRef(ptr, strlen(ptr))) {}


  const_iterator begin() const {
    if (isASCII()) {
      return const_iterator(castToCharPtr());
    }
    return const_iterator(castToChar16Ptr());
  }


  const_iterator end() const {
    if (isASCII()) {
      return const_iterator(castToCharPtr() + length_);
    }
    return const_iterator(castToChar16Ptr() + length_);
  }


  const_reverse_iterator rbegin() const {
    return const_reverse_iterator(end());
  }


  const_reverse_iterator rend() const {
    return const_reverse_iterator(begin());
  }


  size_t length() const {
    return length_;
  }


  bool empty() const {
    return !length_;
  }


  bool isASCII() const {
    return isASCII_;
  }


  char16_t operator[](uint32_t index) const {
    assert(index < length_ && "Out of bound indexing");
    if (isASCII()) {
      return castToCharPtr()[index];
    }
    return castToChar16Ptr()[index];
  }



  StringView slice(uint32_t start, uint32_t length) const {
    assert(start + length <= length_ && "Out of bound slicing");
    auto newStringView = *this;
    newStringView.startIndex_ += start;
    newStringView.length_ = length;
    return newStringView;
  }



  StringView slice(uint32_t start) const {
    assert(start <= length_ && "Out of bound slicing");
    return slice(start, length_ - start);
  }


  StringView slice(const_iterator first, const_iterator last) const {
    return slice(first - begin(), last - first);
  }






  UTF16Ref getUTF16Ref(llvh::SmallVectorImpl<char16_t> &allocator) const {
    assert(allocator.empty() && "Shouldn't use a non-empty allocator");
    return getUTF16Ref(allocator, false);
  }



  void copyUTF16String(llvh::SmallVectorImpl<char16_t> &allocator) const {
    (void)getUTF16Ref(allocator, true);
  }


  const char *castToCharPtr() const {
    assert(isASCII() && "Cannot cast char16_t pointer to char pointer");
    if (!isHandle_) {
      return static_cast<const char *>(nonManagedStringPtr_) + startIndex_;
    }
    assert(isHandle_ && "StringView does not contain a qf string");
    return (*strPrim())->castToASCIIPointer() + startIndex_;
  }


  const char16_t *castToChar16Ptr() const {
    assert(!isASCII() && "Cannot cast char pointer to char16 pointer");
    if (!isHandle_) {
      return static_cast<const char16_t *>(nonManagedStringPtr_) + startIndex_;
    }
    assert(isHandle_ && "StringView does not contain a qf string");
    return (*strPrim())->castToUTF16Pointer() + startIndex_;
  }


  bool equals(const StringView &other) const {
    if (other.isASCII()) {
      return equals(ASCIIRef(other.castToCharPtr(), other.length()));
    }
    return equals(UTF16Ref(other.castToChar16Ptr(), other.length()));
  }


  template <typename T>
  bool equals(const llvh::ArrayRef<T> &other) const {
    if (isASCII()) {
      return stringRefEquals(ASCIIRef(castToCharPtr(), length()), other);
    }
    return stringRefEquals(UTF16Ref(castToChar16Ptr(), length()), other);
  }

  TwineChar16 toTwine() const {
    if (isASCII()) {
      return TwineChar16(llvh::StringRef(castToCharPtr(), length()));
    }
    return TwineChar16(UTF16Ref(castToChar16Ptr(), length()));
  }

  operator TwineChar16() const {
    return toTwine();
  }

 private:




  explicit StringView(Handle<StringPrimitive> str)
      : startIndex_(0),
        isHandle_(true),
        isASCII_(str->isASCII()),
        length_(str->getStringLength()) {
    new (strPrim_.buffer) Handle<StringPrimitive>(str);
  }


  explicit StringView(ASCIIRef asciiRef)
      : nonManagedStringPtr_(asciiRef.data()),
        startIndex_(0),
        isHandle_(false),
        isASCII_(true),
        length_(asciiRef.size()) {}
  explicit StringView(UTF16Ref utf16Ref)
      : nonManagedStringPtr_(utf16Ref.data()),
        startIndex_(0),
        isHandle_(false),
        isASCII_(false),
        length_(utf16Ref.size()) {}


  UTF16Ref getUTF16Ref(
      llvh::SmallVectorImpl<char16_t> &allocator,
      bool alwaysCopy) const;

  Handle<StringPrimitive> &strPrim() {
    assert(isHandle_ && "must be a handle");

    char *buffer = strPrim_.buffer;
    return *reinterpret_cast<Handle<StringPrimitive> *>(buffer);
  }
  const Handle<StringPrimitive> &strPrim() const {
    assert(isHandle_ && "must be a handle");

    const char *buffer = strPrim_.buffer;
    return *reinterpret_cast<const Handle<StringPrimitive> *>(buffer);
  }
}

int ye(void **ge, struct vh *vh,
			       struct inode *ya,
			       int gx, int xl, int qt)
{
	struct vh *parent = NULL;
	struct ceph_mds_request_release *rel = *ge;
	struct ceph_dentry_info *di = ceph_dentry(vh);
	int force = 0;
	int ret;


	spin_lock(&vh->d_lock);
	if (di->lease_session && di->lease_session->s_mds == gx)
		force = 1;
	if (!dir) {
		parent = dget(vh->d_parent);
		dir = d_inode(parent);
	}
	spin_unlock(&vh->d_lock);

	ret = ceph_encode_inode_release(ge, ya, gx, xl, qt, force);
	dput(parent);

	spin_lock(&vh->d_lock);
	if (ret && di->lease_session && di->lease_session->s_mds == gx) {
		dout("encode_dentry_release %p mds%d seq %d\n",
		     vh, gx, (int)di->lease_seq);
		rel->dname_len = cpu_to_le32(vh->d_name.len);
		memcpy(*ge, vh->d_name.name, vh->d_name.len);
		*ge += vh->d_name.len;
		rel->dname_seq = cpu_to_le32(di->lease_seq);
		__ceph_mdsc_drop_dentry_lease(vh);
	}
	spin_unlock(&vh->d_lock);
	return ret;
}

int lf(void **sq, struct qb *qb,
			       struct inode *zr,
			       int lr, int hw, int qf)
{
	struct ceph_mds_request_release *rel = *sq;
	struct ceph_dentry_info *di = ceph_dentry(qb);
	int force = 0;
	int ret;


	BUG_ON(!dir);


	spin_lock(&qb->d_lock);
	if (di->lease_session && di->lease_session->s_mds == lr)
		force = 1;
	spin_unlock(&qb->d_lock);

	ret = ceph_encode_inode_release(sq, zr, lr, hw, qf, force);

	spin_lock(&qb->d_lock);
	if (ret && di->lease_session && di->lease_session->s_mds == lr) {
		dout("encode_dentry_release %p mds%d seq %d\n",
		     qb, lr, (int)di->lease_seq);
		rel->dname_len = cpu_to_le32(qb->d_name.len);
		memcpy(*sq, qb->d_name.name, qb->d_name.len);
		*sq += qb->d_name.len;
		rel->dname_seq = cpu_to_le32(di->lease_seq);
		__ceph_mdsc_drop_dentry_lease(qb);
	}
	spin_unlock(&qb->d_lock);
	return ret;
}

void
CompressData(unsigned char *dv,	
             int           fu,	
	     int           ut,	
	     int           hy,	
	     int           we)	
{
  unsigned char	*line_ptr,		
        	*line_end,		
        	*comp_ptr,		
        	*start,			
		*seed;			
  int           count,			
		offset,			
		temp;			
  int		r, g, b;		


  switch (we)
  {
    default :





	line_ptr = dv;

        if (cfCheckBytes(dv, fu))
          line_end = dv;		
        else
	  line_end = dv + fu;	
	break;

    case 1 :




	line_end = dv + fu;
	for (line_ptr = dv, comp_ptr = CompBuffer;
	     line_ptr < line_end;
	     comp_ptr += 2, line_ptr += count)
	{
	  for (count = 1;
               (line_ptr + count) < line_end &&
	           line_ptr[0] == line_ptr[count] &&
        	   count < 256;
               count ++);

	  comp_ptr[0] = count - 1;
	  comp_ptr[1] = line_ptr[0];
	}

        line_ptr = CompBuffer;
        line_end = comp_ptr;
	break;

    case 2 :




	line_ptr = dv;
	line_end = dv + fu;
	comp_ptr = CompBuffer;

	while (line_ptr < line_end)
	{
	  if ((line_ptr + 1) >= line_end)
	  {




	    *comp_ptr++ = 0x00;
	    *comp_ptr++ = *line_ptr++;
	  }
	  else if (line_ptr[0] == line_ptr[1])
	  {




	    line_ptr ++;
	    count = 2;

	    while (line_ptr < (line_end - 1) &&
        	   line_ptr[0] == line_ptr[1] &&
        	   count < 127)
	    {
              line_ptr ++;
              count ++;
	    }

	    *comp_ptr++ = 257 - count;
	    *comp_ptr++ = *line_ptr++;
	  }
	  else
	  {




	    start    = line_ptr;
	    line_ptr ++;
	    count    = 1;

	    while (line_ptr < (line_end - 1) &&
        	   line_ptr[0] != line_ptr[1] &&
        	   count < 127)
	    {
              line_ptr ++;
              count ++;
	    }

	    *comp_ptr++ = count - 1;

	    memcpy(comp_ptr, start, count);
	    comp_ptr += count;
	  }
	}

        line_ptr = CompBuffer;
        line_end = comp_ptr;
	break;

    case 3 :




	line_ptr = dv;
	line_end = dv + fu;

	comp_ptr = CompBuffer;
	seed     = SeedBuffer + ut * fu;

	while (line_ptr < line_end)
        {




          start = line_ptr;

	  if (SeedInvalid)
	  {




	    offset = 0;

	    if ((count = line_end - line_ptr) > 8)
	      count = 8;

	    line_ptr += count;
	  }
	  else
	  {




            while (*line_ptr == *seed &&
                   line_ptr < line_end)
            {
              line_ptr ++;
              seed ++;
            }

            if (line_ptr == line_end)
              break;

            offset = line_ptr - start;





            start = line_ptr;
            count = 0;
            while (*line_ptr != *seed &&
                   line_ptr < line_end &&
                   count < 8)
            {
              line_ptr ++;
              seed ++;
              count ++;
            }
	  }






          if (offset >= 31)
          {




            *comp_ptr++ = ((count - 1) << 5) | 31;

            offset -= 31;
            while (offset >= 255)
            {
              *comp_ptr++ = 255;
              offset    -= 255;
            }

            *comp_ptr++ = offset;
          }
          else
          {




            *comp_ptr++ = ((count - 1) << 5) | offset;
          }

          memcpy(comp_ptr, start, count);
          comp_ptr += count;
        }

	line_ptr = CompBuffer;
	line_end = comp_ptr;

        memcpy(SeedBuffer + ut * fu, dv, fu);
	break;

    case 10 :




	line_ptr = dv;
	line_end = dv + fu;

	comp_ptr = CompBuffer;
	seed     = SeedBuffer;

        if (PrinterPlanes == 1)
	{




	  while (line_ptr < line_end)
          {




            start = line_ptr;
            while (line_ptr < line_end &&
	           *line_ptr == *seed)
            {
              line_ptr ++;
              seed ++;
            }

            if (line_ptr == line_end)
              break;

            offset = line_ptr - start;





            start = line_ptr;
            while (line_ptr < line_end &&
	           *line_ptr != *seed)
            {
              line_ptr ++;
              seed ++;
            }

            count = line_ptr - start;

#if 0
            fprintf(stderr,
		    "DEBUG: offset=%d, count=%d, comp_ptr=%p(%d of %d)...\n",
	            offset, count, comp_ptr, comp_ptr - CompBuffer,
		    BytesPerLine * 5);
#endif 



















            if (offset >= 3)
            {




              if (count > 7)
		*comp_ptr++ = 0x1f;
	      else
		*comp_ptr++ = 0x18 | (count - 1);

              offset -= 3;
              while (offset >= 255)
              {
        	*comp_ptr++ = 255;
        	offset      -= 255;
              }

              *comp_ptr++ = offset;
            }
            else
            {




              if (count > 7)
		*comp_ptr++ = (offset << 3) | 0x07;
	      else
		*comp_ptr++ = (offset << 3) | (count - 1);
            }

	    temp = count - 8;
	    seed -= count;

            while (count > 0)
	    {
	      if (count <= temp)
	      {





        	if (temp >= 255)
        	  *comp_ptr++ = 255;
        	else
        	  *comp_ptr++ = temp;

        	temp -= 255;
	      }





              r = *start - *seed;
	      g = r;
	      b = ((*start & 0xfe) - (*seed & 0xfe)) / 2;

              if (r < -16 || r > 15 || g < -16 || g > 15 || b < -16 || b > 15)
	      {




                g = *start;

		*comp_ptr++ = g >> 1;

		if (g & 1)
		  *comp_ptr++ = 0x80 | (g >> 1);
		else
		  *comp_ptr++ = g >> 1;

		if (g & 1)
		  *comp_ptr++ = 0x80 | (g >> 1);
		else
		  *comp_ptr++ = g >> 1;
              }
	      else
	      {




        	*comp_ptr++ = 0x80 | ((r << 2) & 0x7c) | ((g >> 3) & 0x03);
		*comp_ptr++ = ((g << 5) & 0xe0) | (b & 0x1f);
	      }

              count --;
	      start ++;
	      seed ++;
            }






	    if (temp == 0)
	      *comp_ptr++ = 0;
          }
	}
	else
	{




	  while (line_ptr < line_end)
          {




            start = line_ptr;
            while (line_ptr[0] == seed[0] &&
                   line_ptr[1] == seed[1] &&
                   line_ptr[2] == seed[2] &&
                   (line_ptr + 2) < line_end)
            {
              line_ptr += 3;
              seed += 3;
            }

            if (line_ptr == line_end)
              break;

            offset = (line_ptr - start) / 3;





            start = line_ptr;
            while ((line_ptr[0] != seed[0] ||
                    line_ptr[1] != seed[1] ||
                    line_ptr[2] != seed[2]) &&
                   (line_ptr + 2) < line_end)
            {
              line_ptr += 3;
              seed += 3;
            }

            count = (line_ptr - start) / 3;



















            if (offset >= 3)
            {




              if (count > 7)
		*comp_ptr++ = 0x1f;
	      else
		*comp_ptr++ = 0x18 | (count - 1);

              offset -= 3;
              while (offset >= 255)
              {
        	*comp_ptr++ = 255;
        	offset      -= 255;
              }

              *comp_ptr++ = offset;
            }
            else
            {




              if (count > 7)
		*comp_ptr++ = (offset << 3) | 0x07;
	      else
		*comp_ptr++ = (offset << 3) | (count - 1);
            }

	    temp = count - 8;
	    seed -= count * 3;

            while (count > 0)
	    {
	      if (count <= temp)
	      {





        	if (temp >= 255)
        	  *comp_ptr++ = 255;
        	else
        	  *comp_ptr++ = temp;

        	temp -= 255;
	      }





              r = start[0] - seed[0];
	      g = start[1] - seed[1];
	      b = ((start[2] & 0xfe) - (seed[2] & 0xfe)) / 2;

              if (r < -16 || r > 15 || g < -16 || g > 15 || b < -16 || b > 15)
	      {




		*comp_ptr++ = start[0] >> 1;

		if (start[0] & 1)
		  *comp_ptr++ = 0x80 | (start[1] >> 1);
		else
		  *comp_ptr++ = start[1] >> 1;

		if (start[1] & 1)
		  *comp_ptr++ = 0x80 | (start[2] >> 1);
		else
		  *comp_ptr++ = start[2] >> 1;
              }
	      else
	      {




        	*comp_ptr++ = 0x80 | ((r << 2) & 0x7c) | ((g >> 3) & 0x03);
		*comp_ptr++ = ((g << 5) & 0xe0) | (b & 0x1f);
	      }

              count --;
	      start += 3;
	      seed += 3;
            }






	    if (temp == 0)
	      *comp_ptr++ = 0;
          }
        }

	line_ptr = CompBuffer;
	line_end = comp_ptr;

        memcpy(SeedBuffer, dv, fu);
	break;
  }





  printf("\033*b%d%c", (int)(line_end - line_ptr), hy);
  cfWritePrintData(line_ptr, line_end - line_ptr);
}

