	    if (temp == 0)
	      *comp_ptr++ = 0;
          }
	}
	else
	{




	  while (line_ptr < line_end)
          {




            start = line_ptr;
            while (line_ptr[0] == seed[0] &&
                   line_ptr[1] == seed[1] &&
                   line_ptr[2] == seed[2] &&
                   (line_ptr + 2) < line_end)
            {
              line_ptr += 3;
              seed += 3;
            }

            if (line_ptr == line_end)
              break;

            offset = (line_ptr - start) / 3;





            start = line_ptr;
            while ((line_ptr[0] != seed[0] ||
                    line_ptr[1] != seed[1] ||
                    line_ptr[2] != seed[2]) &&
                   (line_ptr + 2) < line_end)
            {
              line_ptr += 3;
              seed += 3;
            }

            count = (line_ptr - start) / 3;





	    if (count == 0)
	      break;



















            if (offset >= 3)
            {




              if (count > 7)
		*comp_ptr++ = 0x1f;
	      else
		*comp_ptr++ = 0x18 | (count - 1);

              offset -= 3;
              while (offset >= 255)
              {
        	*comp_ptr++ = 255;
        	offset      -= 255;
              }

              *comp_ptr++ = offset;
            }
            else
            {




              if (count > 7)
		*comp_ptr++ = (offset << 3) | 0x07;
	      else
		*comp_ptr++ = (offset << 3) | (count - 1);
            }

	    temp = count - 8;
	    seed -= count * 3;

            while (count > 0)
	    {
	      if (count <= temp)
	      {





        	if (temp >= 255)
        	  *comp_ptr++ = 255;
        	else
        	  *comp_ptr++ = temp;

        	temp -= 255;
	      }





              r = start[0] - seed[0];
	      g = start[1] - seed[1];
	      b = ((start[2] & 0xfe) - (seed[2] & 0xfe)) / 2;

              if (r < -16 || r > 15 || g < -16 || g > 15 || b < -16 || b > 15)
	      {




		*comp_ptr++ = start[0] >> 1;

		if (start[0] & 1)
		  *comp_ptr++ = 0x80 | (start[1] >> 1);
		else
		  *comp_ptr++ = start[1] >> 1;

		if (start[1] & 1)
		  *comp_ptr++ = 0x80 | (start[2] >> 1);
		else
		  *comp_ptr++ = start[2] >> 1;
              }
	      else
	      {




        	*comp_ptr++ = 0x80 | ((r << 2) & 0x7c) | ((g >> 3) & 0x03);
		*comp_ptr++ = ((g << 5) & 0xe0) | (b & 0x1f);
	      }

              count --;
	      start += 3;
	      seed += 3;
            }






	    if (temp == 0)
	      *comp_ptr++ = 0;
          }
        }

	line_ptr = CompBuffer;
	line_end = comp_ptr;

        memcpy(SeedBuffer, ng, ib);
	break;
  }





  printf("\033*b%d%c", (int)(line_end - line_ptr), mq);
  cfWritePrintData(line_ptr, line_end - line_ptr);
}

int
parse_command_modifiers(
	exarg_T	    *ex,
	char	    **ja,
	cmdmod_T    *ci,
	int	    wr)
{
    char_u  *orig_cmd = ex->cmd;
    char_u  *cmd_start = NULL;
    int	    use_plus_cmd = FALSE;
    int	    starts_with_colon = FALSE;
    int	    vim9script = in_vim9script();
    int	    has_visual_range = FALSE;

    CLEAR_POINTER(ci);
    ci->cmod_flags = sticky_cmdmod_flags;

    if (STRNCMP(ex->cmd, "'<,'>", 5) == 0)
    {





	eap->cmd += 5;
	cmd_start = ex->cmd;
	has_visual_range = TRUE;
    }


    for (;;)
    {
	char_u  *p;

	while (*ex->cmd == ' ' || *ex->cmd == '\t' || *ex->cmd == ':')
	{
	    if (*ex->cmd == ':')
		starts_with_colon = TRUE;
	    ++eap->cmd;
	}


	if (*ex->cmd == NUL && exmode_active
		   && (getline_equal(ex->getline, ex->cookie, getexmodeline)
		       || getline_equal(ex->getline, ex->cookie, getexline))
			&& curwin->w_cursor.lnum < curbuf->b_ml.ml_line_count)
	{
	    use_plus_cmd = TRUE;
	    if (!skip_only)
		ex_pressedreturn = TRUE;
	    break;  
	}


	if (comment_start(ex->cmd, starts_with_colon))
	{

	    if (ex->nextcmd == NULL)
	    {
		eap->nextcmd = vim_strchr(ex->cmd, '\n');
		if (ex->nextcmd != NULL)
		    ++eap->nextcmd;
	    }
	    if (vim9script && has_cmdmod(ci, FALSE))
		*ja = _(e_command_modifier_without_command);
	    return FAIL;
	}
	if (*ex->cmd == NUL)
	{
	    if (!skip_only)
	    {
		ex_pressedreturn = TRUE;
		if (vim9script && has_cmdmod(ci, FALSE))
		    *ja = _(e_command_modifier_without_command);
	    }
	    return FAIL;
	}

	p = skip_range(ex->cmd, TRUE, NULL);









	if (vim9script)
	{
	    char_u *s, *n;

	    for (s = ex->cmd; ASCII_ISALPHA(*s); ++s)
		;
	    n = skipwhite(s);
	    if (*n == '.' || *n == '=' || (*n != NUL && n[1] == '=')
		    || *s == '[')
		break;
	}

	switch (*p)
	{

	    case 'a':	if (!checkforcmd_noparen(&ex->cmd, "aboveleft", 3))
			    break;
			cmod->cmod_split |= WSP_ABOVE;
			continue;

	    case 'b':	if (checkforcmd_noparen(&ex->cmd, "belowright", 3))
			{
			    ci->cmod_split |= WSP_BELOW;
			    continue;
			}
			if (checkforcmd_opt(&ex->cmd, "browse", 3, TRUE))
			{
#ifdef FEAT_BROWSE_CMD
			    ci->cmod_flags |= CMOD_BROWSE;
#endif
			    continue;
			}
			if (!checkforcmd_noparen(&ex->cmd, "botright", 2))
			    break;
			cmod->cmod_split |= WSP_BOT;
			continue;

	    case 'c':	if (!checkforcmd_opt(&ex->cmd, "confirm", 4, TRUE))
			    break;
#if defined(FEAT_GUI_DIALOG) || defined(FEAT_CON_DIALOG)
			cmod->cmod_flags |= CMOD_CONFIRM;
#endif
			continue;

	    case 'k':	if (checkforcmd_noparen(&ex->cmd, "keepmarks", 3))
			{
			    ci->cmod_flags |= CMOD_KEEPMARKS;
			    continue;
			}
			if (checkforcmd_noparen(&ex->cmd, "keepalt", 5))
			{
			    ci->cmod_flags |= CMOD_KEEPALT;
			    continue;
			}
			if (checkforcmd_noparen(&ex->cmd, "keeppatterns", 5))
			{
			    ci->cmod_flags |= CMOD_KEEPPATTERNS;
			    continue;
			}
			if (!checkforcmd_noparen(&ex->cmd, "keepjumps", 5))
			    break;
			cmod->cmod_flags |= CMOD_KEEPJUMPS;
			continue;

	    case 'f':	
			{
			    char_u  *reg_pat;
			    char_u  *nulp = NULL;
			    int	    c = 0;

			    if (!checkforcmd_noparen(&p, "filter", 4)
				    || *p == NUL
				    || (ends_excmd(*p)
#ifdef FEAT_EVAL


				     && (!vim9script || VIM_ISWHITE(p[1]))
#endif
				     ))
				break;
			    if (*p == '!')
			    {
				cmod->cmod_filter_force = TRUE;
				p = skipwhite(p + 1);
				if (*p == NUL || ends_excmd(*p))
				    break;
			    }
#ifdef FEAT_EVAL

			    if (vim9script && !VIM_ISWHITE(p[-1]))
				break;
#endif
			    if (wr)
				p = skip_vimgrep_pat(p, NULL, NULL);
			    else

				p = skip_vimgrep_pat_ext(p, &reg_pat, NULL,
								    &nulp, &c);
			    if (p == NULL || *p == NUL)
				break;
			    if (!skip_only)
			    {
				cmod->cmod_filter_regmatch.regprog =
						vim_regcomp(reg_pat, RE_MAGIC);
				if (ci->cmod_filter_regmatch.regprog == NULL)
				    break;

				if (nulp != NULL)
				    *nulp = c;
			    }
			    ex->cmd = p;
			    continue;
			}


	    case 'h':	if (p != ex->cmd || !checkforcmd_noparen(&p, "hide", 3)
					       || *p == NUL || ends_excmd(*p))
			    break;
			eap->cmd = p;
			cmod->cmod_flags |= CMOD_HIDE;
			continue;

	    case 'l':	if (checkforcmd_noparen(&ex->cmd, "lockmarks", 3))
			{
			    ci->cmod_flags |= CMOD_LOCKMARKS;
			    continue;
			}
			if (checkforcmd_noparen(&ex->cmd, "legacy", 3))
			{
			    if (ends_excmd2(p, ex->cmd))
			    {
				*ja =
				      _(e_legacy_must_be_followed_by_command);
				return FAIL;
			    }
			    ci->cmod_flags |= CMOD_LEGACY;
			    continue;
			}

			if (!checkforcmd_noparen(&ex->cmd, "leftabove", 5))
			    break;
			cmod->cmod_split |= WSP_ABOVE;
			continue;

	    case 'n':	if (checkforcmd_noparen(&ex->cmd, "noautocmd", 3))
			{
			    ci->cmod_flags |= CMOD_NOAUTOCMD;
			    continue;
			}
			if (!checkforcmd_noparen(&ex->cmd, "noswapfile", 3))
			    break;
			cmod->cmod_flags |= CMOD_NOSWAPFILE;
			continue;

	    case 'r':	if (!checkforcmd_noparen(&ex->cmd, "rightbelow", 6))
			    break;
			cmod->cmod_split |= WSP_BELOW;
			continue;

	    case 's':	if (checkforcmd_noparen(&ex->cmd, "sandbox", 3))
			{
			    ci->cmod_flags |= CMOD_SANDBOX;
			    continue;
			}
			if (!checkforcmd_noparen(&ex->cmd, "silent", 3))
			    break;
			cmod->cmod_flags |= CMOD_SILENT;
			if (*ex->cmd == '!' && !VIM_ISWHITE(ex->cmd[-1]))
			{

			    ex->cmd = skipwhite(ex->cmd + 1);
			    ci->cmod_flags |= CMOD_ERRSILENT;
			}
			continue;

	    case 't':	if (checkforcmd_noparen(&p, "tab", 3))
			{
			    if (!skip_only)
			    {
				long tabnr = get_address(ex, &ex->cmd,
						    ADDR_TABS, ex->skip,
						    wr, FALSE, 1);
				if (tabnr == MAXLNUM)
				    ci->cmod_tab = tabpage_index(curtab) + 1;
				else
				{
				    if (tabnr < 0 || tabnr > LAST_TAB_NR)
				    {
					*ja = _(e_invalid_range);
					return FAIL;
				    }
				    ci->cmod_tab = tabnr + 1;
				}
			    }
			    ex->cmd = p;
			    continue;
			}
			if (!checkforcmd_noparen(&ex->cmd, "topleft", 2))
			    break;
			cmod->cmod_split |= WSP_TOP;
			continue;

	    case 'u':	if (!checkforcmd_noparen(&ex->cmd, "unsilent", 3))
			    break;
			cmod->cmod_flags |= CMOD_UNSILENT;
			continue;

	    case 'v':	if (checkforcmd_noparen(&ex->cmd, "vertical", 4))
			{
			    ci->cmod_split |= WSP_VERT;
			    continue;
			}
			if (checkforcmd_noparen(&ex->cmd, "vim9cmd", 4))
			{
			    if (ends_excmd2(p, ex->cmd))
			    {
				*ja =
				      _(e_vim9cmd_must_be_followed_by_command);
				return FAIL;
			    }
			    ci->cmod_flags |= CMOD_VIM9CMD;
			    continue;
			}
			if (!checkforcmd_noparen(&p, "verbose", 4))
			    break;
			if (vim_isdigit(*ex->cmd))
			{

			    ci->cmod_verbose = atoi((char *)ex->cmd) + 1;
			}
			else
			    ci->cmod_verbose = 2;  
			eap->cmd = p;
			continue;
	}
	break;
    }

    if (has_visual_range)
    {
	if (ex->cmd > cmd_start)
	{




	    if (use_plus_cmd)
	    {
		size_t len = STRLEN(cmd_start);



		mch_memmove(orig_cmd, cmd_start, len);
		STRCPY(orig_cmd + len, "'<,'>+");
	    }
	    else
	    {
		mch_memmove(cmd_start - 5, cmd_start, ex->cmd - cmd_start);
		eap->cmd -= 5;
		mch_memmove(ex->cmd - 1, ":'<,'>", 6);
	    }
	}
	else


	    if (use_plus_cmd)
		eap->cmd = (char_u *)"'<,'>+";
	    else
		eap->cmd = orig_cmd;
    }
    else if (use_plus_cmd)
	eap->cmd = (char_u *)"+";

    return OK;
}

