    return OK;
}

static inline u32 yz(struct hbg_ring *pf)
{
	return (pf->ntu + pf->len - pf->ntc) % pf->len;
}

static inline u32 zf(struct hbg_ring *hm)
{
	u32 len = READ_ONCE(hm->len);

	if (!len)
		return 0;

	return (READ_ONCE(hm->ntu) + len - READ_ONCE(hm->ntc)) % len;
}

t_peb(struct ubi_device *un, int ms, int gh,
		   int lc, int hi)
{
	int err;
	struct ubi_wl_entry *e;

	dbg_wl("PEB %d", lc);
	ubi_assert(lc >= 0);
	ubi_assert(lc < un->peb_count);

	down_read(&un->fm_protect);

retry:
	spin_lock(&un->wl_lock);
	e = un->lookuptbl[lc];
	if (e == un->move_from) {

		dbg_wl("PEB %d is being moved, wait", lc);
		spin_unlock(&un->wl_lock);


		mutex_lock(&un->move_mutex);
		mutex_unlock(&un->move_mutex);
		goto retry;
	} else if (e == un->move_to) {

		dbg_wl("PEB %d is the target of data moving", lc);
		ubi_assert(!ubi->move_to_put);
		ubi->move_to_put = 1;
		spin_unlock(&un->wl_lock);
		up_read(&un->fm_protect);
		return 0;
	} else {
		if (in_wl_tree(e, &un->used)) {
			self_check_in_wl_tree(un, e, &un->used);
			rb_erase(&e->u.rb, &un->used);
		} else if (in_wl_tree(e, &un->scrub)) {
			self_check_in_wl_tree(un, e, &un->scrub);
			rb_erase(&e->u.rb, &un->scrub);
		} else if (in_wl_tree(e, &un->erroneous)) {
			self_check_in_wl_tree(un, e, &un->erroneous);
			rb_erase(&e->u.rb, &un->erroneous);
			ubi->erroneous_peb_count -= 1;
			ubi_assert(un->erroneous_peb_count >= 0);

			torture = 1;
		} else {
			err = prot_queue_del(un, e->lc);
			if (err) {
				ubi_err(un, "PEB %d not found", lc);
				ubi_ro_mode(un);
				spin_unlock(&un->wl_lock);
				up_read(&un->fm_protect);
				return err;
			}
		}
	}
	spin_unlock(&un->wl_lock);

	err = schedule_erase(un, e, ms, gh, hi, false);
	if (err) {
		spin_lock(&un->wl_lock);
		wl_tree_add(e, &un->used);
		spin_unlock(&un->wl_lock);
	}

	up_read(&un->fm_protect);
	return err;
}

