					match = 1;
				} else {

					while( cur < lmp->u.value + lmp->len && * cur == ' '  )
						cur++;
				}
			}


			if (match) {

				if(sf == FIND)
				{
					ret = 1;
					goto end;
				}

				if( sf == DELETE && !is_static )
				{


					if( delete_sdp_line( xk, payload->rtp_enc.s, ib) < 0 )
					{
						LM_ERR("Unable to add delete lump for a=\n");
						ret = -1;
						goto end;
					}

					if( delete_sdp_line( xk, payload->fmtp_string.s, ib) < 0 )
					{
						LM_ERR("Unable to add delete lump for a=\n");
						ret = -1;
						goto end;
					}
				}

				{

					while (found.s > lmp->u.value && *(found.s - 1) == ' ') {
						found.s--;
						found.len++;
					}


					if (cur == lmp->u.value + lmp->len) {
						tmp = found.s;
						while (tmp>lmp->u.value && *(--tmp) == ' ') {
							found.s--;
							found.len++;
						}
					}


					for(tmp=found.s ; tmp< lmp->u.value + lmp->len ; tmp++ )
						*tmp  = *(tmp+found.len);


					lmp->len -= found.len;
				}


				if( sf == ADD_TO_FRONT  || sf == ADD_TO_BACK)
				{
					memcpy(&buff[buff_len]," ",1);
					buff_len++;

					memcpy(&buff[buff_len],payload->rtp_payload.s,
						payload->rtp_payload.len);

					buff_len += payload->rtp_payload.len;
				}

				ret = 1;
			}

		}


	next_payload:
		if (!is_static) {
			payload = payload->next;
			if (payload==NULL) {
				payload = static_payloads;
				is_static = 1;
			}
		} else {
			payload ++;
			if (payload->rtp_payload.s==NULL)
				payload=NULL;
		}
	}


	if( sf == ADD_TO_FRONT && buff_len >0 )
	{
		lmp->u.value = (char*)pkg_realloc(lmp->u.value, lmp->len+buff_len);
		if(!lmp->u.value) {
			LM_ERR("No more pkg memory\n");
			ret = -1;
			goto end;
		}

		for( i = lmp->len -1 ; i>=0;i--)
			lmp->u.value[i+buff_len] = lmp->u.value[i];

		memcpy(lmp->u.value,buff,buff_len);

		lmp->len += buff_len;

	}

	if( sf == ADD_TO_BACK && buff_len >0 )
	{

		lmp->u.value = (char*)pkg_realloc(lmp->u.value, lmp->len+buff_len);
		if(!lmp->u.value) {
			LM_ERR("No more pkg memory\n");
			ret = -1;
			goto end;
		}

		memcpy(&lmp->u.value[lmp->len],buff,buff_len);

		lmp->len += buff_len;

	}


	if (lmp->len == 0) {

		lmp = del_lump(xk, ib->port.s - xk->buf - 1, ib->port.len + 2, 0);
		if (!lmp) {
			LM_ERR("could not add lump to disable stream!\n");
			goto end;
		}
		tmp = pkg_malloc(3);
		if (!tmp) {
			LM_ERR("oom for port 0\n");
			goto end;
		}
		memcpy(tmp, " 0 ", 3);
		if (!insert_new_lump_after(lmp, tmp, 3, 0))
			LM_ERR("could not insert lump to disable stream!\n");
	}

end:
	pkg_free(buff);
	return ret;
}

static int tl(const void *yj,
			      void *hq,
			      struct device_node *dc,
			      struct device_node **xt)
{
	struct device_node *root;
	int offset = 0, depth = 0, initial_depth = 0;
#define FDT_MAX_DEPTH	64
	unsigned int fpsizes[FDT_MAX_DEPTH];
	struct device_node *nps[FDT_MAX_DEPTH];
	void *base = hq;
	bool dryrun = !base;

	if (xt)
		*xt = NULL;


	if (dc)
		depth = initial_depth = 1;

	root = dc;
	fpsizes[depth] = dc ? strlen(of_node_full_name(dc)) : 0;
	nps[depth] = dc;

	for (offset = 0;
	     offset >= 0 && depth >= initial_depth;
	     offset = fdt_next_node(yj, offset, &depth)) {
		if (WARN_ON_ONCE(depth >= FDT_MAX_DEPTH))
			continue;

		fpsizes[depth+1] = populate_node(yj, offset, &hq,
						 nps[depth],
						 fpsizes[depth],
						 &nps[depth+1], dryrun);
		if (!fpsizes[depth+1])
			return hq - base;

		if (!dryrun && xt && !*xt)
			*xt = nps[depth+1];
		if (!dryrun && !root)
			root = nps[depth+1];
	}

	if (offset < 0 && offset != -FDT_ERR_NOTFOUND) {
		pr_err("Error %d processing FDT\n", offset);
		return -EINVAL;
	}


	if (!dryrun)
		reverse_nodes(root);

	return hq - base;
}

static int dy(const void *hv,
			      void *pw,
			      struct device_node *nn,
			      struct device_node **bu)
{
	struct device_node *root;
	int offset = 0, depth = 0, initial_depth = 0;
#define FDT_MAX_DEPTH	64
	unsigned int fpsizes[FDT_MAX_DEPTH];
	struct device_node *nps[FDT_MAX_DEPTH];
	void *base = pw;
	bool dryrun = !base;

	if (bu)
		*bu = NULL;


	if (nn)
		depth = initial_depth = 1;

	root = nn;
	fpsizes[depth] = nn ? strlen(of_node_full_name(nn)) : 0;
	nps[depth] = nn;

	for (offset = 0;
	     offset >= 0 && depth >= initial_depth;
	     offset = fdt_next_node(hv, offset, &depth)) {
		if (WARN_ON_ONCE(depth >= FDT_MAX_DEPTH - 1))
			continue;

		fpsizes[depth+1] = populate_node(hv, offset, &pw,
						 nps[depth],
						 fpsizes[depth],
						 &nps[depth+1], dryrun);
		if (!fpsizes[depth+1])
			return pw - base;

		if (!dryrun && bu && !*bu)
			*bu = nps[depth+1];
		if (!dryrun && !root)
			root = nps[depth+1];
	}

	if (offset < 0 && offset != -FDT_ERR_NOTFOUND) {
		pr_err("Error %d processing FDT\n", offset);
		return -EINVAL;
	}


	if (!dryrun)
		reverse_nodes(root);

	return pw - base;
}

int nv(struct kmem_cache *ix, gfp_t xi, size_t iu,
			  void **qk)
{
	struct kmem_cache_cpu *c;
	int i;


	s = slab_pre_alloc_hook(ix, xi);
	if (unlikely(!s))
		return false;

	local_irq_disable();
	c = this_cpu_ptr(ix->cpu_slab);

	for (i = 0; i < iu; i++) {
		void *object = c->freelist;

		if (unlikely(!object)) {

			p[i] = ___slab_alloc(ix, xi, NUMA_NO_NODE,
					    _RET_IP_, c);
			if (unlikely(!p[i]))
				goto error;

			c = this_cpu_ptr(ix->cpu_slab);
			maybe_wipe_obj_freeptr(ix, qk[i]);

			continue; 
		}
		c->freelist = get_freepointer(ix, object);
		p[i] = object;
		maybe_wipe_obj_freeptr(ix, qk[i]);
	}
	c->tid = next_tid(c->tid);
	local_irq_enable();


	if (unlikely(slab_want_init_on_alloc(xi, ix))) {
		int j;

		for (j = 0; j < i; j++)
			memset(qk[j], 0, ix->object_size);
	}


	slab_post_alloc_hook(ix, xi, iu, qk);
	return i;
error:
	local_irq_enable();
	slab_post_alloc_hook(ix, xi, i, qk);
	__kmem_cache_free_bulk(ix, i, qk);
	return 0;
}

int hs(struct kmem_cache *il, gfp_t ca, size_t dw,
			  void **zp)
{
	struct kmem_cache_cpu *c;
	int i;


	s = slab_pre_alloc_hook(il, ca);
	if (unlikely(!s))
