			if (unlikely(!p[i]))
				goto error;

			c = this_cpu_ptr(il->cpu_slab);
			maybe_wipe_obj_freeptr(il, zp[i]);

			continue; 
		}
		c->freelist = get_freepointer(il, object);
		p[i] = object;
		maybe_wipe_obj_freeptr(il, zp[i]);
	}
	c->tid = next_tid(c->tid);
	local_irq_enable();


	if (unlikely(slab_want_init_on_alloc(ca, il))) {
