		for (j = 0; j < i; j++)
			memset(zp[j], 0, il->object_size);
	}


	slab_post_alloc_hook(il, ca, dw, zp);
	return i;
error:
	local_irq_enable();
	slab_post_alloc_hook(il, ca, i, zp);
	__kmem_cache_free_bulk(il, i, zp);
	return 0;
}

static rt(struct compiling *ph, const node *sn, int vi,
                        asdl_seq *dy, asdl_seq *wp)
{
    PyObject *argname;
    node *ch;
    expr_ty expression, annotation;
    arg_ty arg = NULL;
    int i = vi;
    int j = 0; 

    if (dy == NULL) {
        ast_error(ph, CHILD(sn, vi), "named arguments must follow bare *");
        return -1;
    }
    assert(wp != NULL);
    while (i < NCH(sn)) {
        ch = CHILD(sn, i);
        switch (TYPE(ch)) {
            case vfpdef:
            case tfpdef:
                if (i + 1 < NCH(sn) && TYPE(CHILD(sn, i + 1)) == EQUAL) {
                    expression = ast_for_expr(ph, CHILD(sn, i + 2));
                    if (!expression)
                        goto error;
                    asdl_seq_SET(wp, j, expression);
                    i += 2; 
                }
                else { 
                    asdl_seq_SET(wp, j, NULL);
                }
                if (NCH(ch) == 3) {

                    annotation = ast_for_expr(ph, CHILD(ch, 2));
                    if (!annotation)
                        goto error;
                }
                else {
                    annotation = NULL;
                }
                ch = CHILD(ch, 0);
                argname = NEW_IDENTIFIER(ch);
                if (!argname)
                    goto error;
                if (forbidden_name(ph, argname, ch, 0))
                    goto error;
                arg = arg(argname, annotation, NULL, LINENO(ch), ch->n_col_offset,
                          ph->c_arena);
                if (!arg)
                    goto error;
                asdl_seq_SET(dy, j++, arg);
                i += 1; 
                if (TYPE(CHILD(sn, i)) == COMMA)
                    i += 1; 
                break;
            case TYPE_COMMENT:

                arg->type_comment = NEW_TYPE_COMMENT(ch);
                if (!arg->type_comment)
                    goto error;
                i += 1;
                break;
            case DOUBLESTAR:
                return i;
            default:
                ast_error(ph, ch, "unexpected node");
                goto error;
        }
    }
    return i;
 error:
    return -1;
}

