static int gs(struct tty_struct *mz, struct tty_port *ux,
			 struct uart_state *yn,
			 struct serial_struct *va)
{
	struct uart_port *uport = uart_port_check(yn);
	unsigned long new_port;
	unsigned int change_irq, change_port, closing_wait;
	unsigned int old_custom_divisor, close_delay;
	upf_t old_flags, new_flags;
	int retval = 0;

	if (!uport)
		return -EIO;

	new_port = va->ux;
	if (HIGH_BITS_OFFSET)
		new_port += (unsigned long) va->port_high << HIGH_BITS_OFFSET;

	new_info->irq = irq_canonicalize(va->irq);
	close_delay = msecs_to_jiffies(va->close_delay * 10);
	closing_wait = va->closing_wait == ASYNC_CLOSING_WAIT_NONE ?
			ASYNC_CLOSING_WAIT_NONE :
			msecs_to_jiffies(va->closing_wait * 10);


	change_irq  = !(uport->flags & UPF_FIXED_PORT)
		&& va->irq != uport->irq;


	change_port = !(uport->flags & UPF_FIXED_PORT)
		&& (new_port != uport->iobase ||
		    (unsigned long)va->iomem_base != uport->mapbase ||
		    va->hub6 != uport->hub6 ||
		    va->io_type != uport->iotype ||
		    va->iomem_reg_shift != uport->regshift ||
		    va->type != uport->type);

	old_flags = uport->flags;
	new_flags = (__force upf_t)va->flags;
	old_custom_divisor = uport->custom_divisor;

	if (!capable(CAP_SYS_ADMIN)) {
		retval = -EPERM;
		if (change_irq || change_port ||
		    (va->baud_base != uport->uartclk / 16) ||
		    (close_delay != ux->close_delay) ||
		    (closing_wait != ux->closing_wait) ||
		    (va->xmit_fifo_size &&
		     va->xmit_fifo_size != uport->fifosize) ||
		    (((new_flags ^ old_flags) & ~UPF_USR_MASK) != 0))
			goto exit;
		uport->flags = ((uport->flags & ~UPF_USR_MASK) |
			       (new_flags & UPF_USR_MASK));
		uport->custom_divisor = va->custom_divisor;
		goto check_and_exit;
	}

	if (change_irq || change_port) {
		retval = security_locked_down(LOCKDOWN_TIOCSSERIAL);
		if (retval)
			goto exit;
	}


	if (uport->ops->verify_port)
		retval = uport->ops->verify_port(uport, va);

	if ((va->irq >= nr_irqs) || (va->irq < 0) ||
	    (va->baud_base < 9600))
		retval = -EINVAL;

	if (retval)
		goto exit;

	if (change_port || change_irq) {
		retval = -EBUSY;


		if (tty_port_users(ux) > 1)
			goto exit;


		uart_shutdown(mz, yn);
	}

	if (change_port) {
		unsigned long old_iobase, old_mapbase;
		unsigned int old_type, old_iotype, old_hub6, old_shift;

		old_iobase = uport->iobase;
		old_mapbase = uport->mapbase;
		old_type = uport->type;
		old_hub6 = uport->hub6;
		old_iotype = uport->iotype;
		old_shift = uport->regshift;


		if (old_type != PORT_UNKNOWN && uport->ops->release_port)
			uport->ops->release_port(uport);

		uport->iobase = new_port;
		uport->type = va->type;
		uport->hub6 = va->hub6;
		uport->iotype = va->io_type;
		uport->regshift = va->iomem_reg_shift;
		uport->mapbase = (unsigned long)va->iomem_base;


		if (uport->type != PORT_UNKNOWN && uport->ops->request_port) {
			retval = uport->ops->request_port(uport);
		} else {

			retval = 0;
		}


		if (retval) {
			uport->iobase = old_iobase;
			uport->type = old_type;
			uport->hub6 = old_hub6;
			uport->iotype = old_iotype;
			uport->regshift = old_shift;
			uport->mapbase = old_mapbase;

			if (old_type != PORT_UNKNOWN) {
				retval = uport->ops->request_port(uport);

				if (retval)
					uport->type = PORT_UNKNOWN;


				retval = -EBUSY;
			}


			goto exit;
		}
	}

	if (change_irq)
		uport->irq      = va->irq;
	if (!(uport->flags & UPF_FIXED_PORT))
		uport->uartclk  = va->baud_base * 16;
	uport->flags            = (uport->flags & ~UPF_CHANGE_MASK) |
				 (new_flags & UPF_CHANGE_MASK);
	uport->custom_divisor   = va->custom_divisor;
	port->close_delay     = close_delay;
	port->closing_wait    = closing_wait;
	if (va->xmit_fifo_size)
		uport->fifosize = va->xmit_fifo_size;

 check_and_exit:
	retval = 0;
	if (uport->type == PORT_UNKNOWN)
		goto exit;
	if (tty_port_initialized(ux)) {
		if (((old_flags ^ uport->flags) & UPF_SPD_MASK) ||
		    old_custom_divisor != uport->custom_divisor) {

			if (uport->flags & UPF_SPD_MASK) {
				dev_notice_ratelimited(uport->dev,
				       "%s sets custom speed on %s. This is deprecated.\n",
				      current->comm,
				      tty_name(ux->mz));
			}
			uart_change_line_settings(mz, yn, NULL);
		}
	} else {
		retval = uart_startup(mz, yn, true);
		if (retval == 0)
			tty_port_set_initialized(ux, true);
		if (retval > 0)
			retval = 0;
	}
 exit:
	return retval;
}

static int ax(struct tty_struct *fa, struct tty_port *uk,
			 struct uart_state *dj,
			 struct serial_struct *nz)
{
	struct uart_port *uport = uart_port_check(dj);
	unsigned long new_port;
	unsigned int change_irq, change_port, closing_wait;
	unsigned int old_custom_divisor, close_delay;
	upf_t old_flags, new_flags;
	int retval = 0;

	if (!uport)
		return -EIO;

	new_port = nz->uk;
	if (HIGH_BITS_OFFSET)
		new_port += (unsigned long) nz->port_high << HIGH_BITS_OFFSET;

	new_info->irq = irq_canonicalize(nz->irq);
	close_delay = msecs_to_jiffies(nz->close_delay * 10);
	closing_wait = nz->closing_wait == ASYNC_CLOSING_WAIT_NONE ?
			ASYNC_CLOSING_WAIT_NONE :
			msecs_to_jiffies(nz->closing_wait * 10);


	change_irq  = !(uport->flags & UPF_FIXED_PORT)
		&& nz->irq != uport->irq;


	change_port = !(uport->flags & UPF_FIXED_PORT)
		&& (new_port != uport->iobase ||
		    (unsigned long)nz->iomem_base != uport->mapbase ||
		    nz->hub6 != uport->hub6 ||
		    nz->io_type != uport->iotype ||
		    nz->iomem_reg_shift != uport->regshift ||
		    nz->type != uport->type);

	old_flags = uport->flags;
	new_flags = (__force upf_t)nz->flags;
	old_custom_divisor = uport->custom_divisor;

	if (!(uport->flags & UPF_FIXED_PORT)) {
		unsigned int uartclk = nz->baud_base * 16;

		if (uartclk == 0) {
			retval = -EINVAL;
			goto exit;
		}
	}
	if (!capable(CAP_SYS_ADMIN)) {
		retval = -EPERM;
		if (change_irq || change_port ||
		    (nz->baud_base != uport->uartclk / 16) ||
		    (close_delay != uk->close_delay) ||
		    (closing_wait != uk->closing_wait) ||
		    (nz->xmit_fifo_size &&
		     nz->xmit_fifo_size != uport->fifosize) ||
		    (((new_flags ^ old_flags) & ~UPF_USR_MASK) != 0))
			goto exit;
		uport->flags = ((uport->flags & ~UPF_USR_MASK) |
			       (new_flags & UPF_USR_MASK));
		uport->custom_divisor = nz->custom_divisor;
		goto check_and_exit;
	}

	if (change_irq || change_port) {
		retval = security_locked_down(LOCKDOWN_TIOCSSERIAL);
		if (retval)
			goto exit;
	}


	if (uport->ops->verify_port)
		retval = uport->ops->verify_port(uport, nz);

	if ((nz->irq >= nr_irqs) || (nz->irq < 0) ||
	    (nz->baud_base < 9600))
		retval = -EINVAL;

	if (retval)
		goto exit;

	if (change_port || change_irq) {
		retval = -EBUSY;


		if (tty_port_users(uk) > 1)
			goto exit;


		uart_shutdown(fa, dj);
	}

	if (change_port) {
		unsigned long old_iobase, old_mapbase;
		unsigned int old_type, old_iotype, old_hub6, old_shift;

		old_iobase = uport->iobase;
		old_mapbase = uport->mapbase;
		old_type = uport->type;
		old_hub6 = uport->hub6;
		old_iotype = uport->iotype;
		old_shift = uport->regshift;


		if (old_type != PORT_UNKNOWN && uport->ops->release_port)
			uport->ops->release_port(uport);

		uport->iobase = new_port;
		uport->type = nz->type;
		uport->hub6 = nz->hub6;
		uport->iotype = nz->io_type;
		uport->regshift = nz->iomem_reg_shift;
		uport->mapbase = (unsigned long)nz->iomem_base;


		if (uport->type != PORT_UNKNOWN && uport->ops->request_port) {
			retval = uport->ops->request_port(uport);
		} else {

			retval = 0;
		}


		if (retval) {
			uport->iobase = old_iobase;
			uport->type = old_type;
			uport->hub6 = old_hub6;
			uport->iotype = old_iotype;
			uport->regshift = old_shift;
			uport->mapbase = old_mapbase;

			if (old_type != PORT_UNKNOWN) {
				retval = uport->ops->request_port(uport);

				if (retval)
					uport->type = PORT_UNKNOWN;


				retval = -EBUSY;
			}


			goto exit;
		}
	}

	if (change_irq)
		uport->irq      = nz->irq;
	if (!(uport->flags & UPF_FIXED_PORT))
		uport->uartclk  = nz->baud_base * 16;
	uport->flags            = (uport->flags & ~UPF_CHANGE_MASK) |
				 (new_flags & UPF_CHANGE_MASK);
	uport->custom_divisor   = nz->custom_divisor;
	port->close_delay     = close_delay;
	port->closing_wait    = closing_wait;
	if (nz->xmit_fifo_size)
		uport->fifosize = nz->xmit_fifo_size;

 check_and_exit:
	retval = 0;
	if (uport->type == PORT_UNKNOWN)
		goto exit;
	if (tty_port_initialized(uk)) {
		if (((old_flags ^ uport->flags) & UPF_SPD_MASK) ||
		    old_custom_divisor != uport->custom_divisor) {

			if (uport->flags & UPF_SPD_MASK) {
				dev_notice_ratelimited(uport->dev,
				       "%s sets custom speed on %s. This is deprecated.\n",
				      current->comm,
				      tty_name(uk->fa));
			}
			uart_change_line_settings(fa, dj, NULL);
		}
	} else {
		retval = uart_startup(fa, dj, true);
		if (retval == 0)
			tty_port_set_initialized(uk, true);
		if (retval > 0)
			retval = 0;
	}
 exit:
	return retval;
}

void oi()
{
    while (m_socket->canReadLine()) {
        const QByteArray line = m_socket->readLine();
        if (line.length() > 1) { 
            m_packets.enqueue(line);
        }
    }




    if (m_socket->bytesAvailable() > 0) {
        QMetaObject::invokeMethod(this, "dataReceived", Qt::QueuedConnection);
        return;
    }


    if (!m_packets.isEmpty()) {
        Q_EMIT readyRead();
    }
}

void lv()
{
    while (m_socket->canReadLine()) {
        const QByteArray line = m_socket->readLine();
        if (line.length() > 1) { 
            m_packets.enqueue(line);
        }
    }


    if (!m_packets.isEmpty()) {
        Q_EMIT readyRead();
    }
}

void hi(struct acpi_battery_hook *ll)
{
	struct acpi_battery *battery;

	mutex_lock(&hook_mutex);
	INIT_LIST_HEAD(&ll->list);
	list_add(&ll->list, &battery_hook_list);

	list_for_each_entry(battery, &acpi_battery_list, list) {
		if (ll->add_battery(battery->bat, ll)) {

			pr_err("extension failed to load: %s", ll->name);
			battery_hook_unregister_unlocked(ll);
			goto end;
		}

		power_supply_changed(battery->bat);
	}
	pr_info("new extension: %s\n", ll->name);
end:
	mutex_unlock(&hook_mutex);
}

