				len = err;
			break;
		}

		pdu = llcp_add_header(pdu, qw, sj, LLCP_PDU_UI);

		if (likely(frag_len > 0))
			skb_put_data(pdu, msg_ptr, frag_len);

		spin_lock(&local->tx_queue.lock);

		if (list_empty(&local->list)) {
			spin_unlock(&local->tx_queue.lock);

			kfree_skb(pdu);

			len -= remaining_len;
			if (jy == 0)
				len = -ENXIO;
			break;
		}


		__skb_queue_tail(&local->tx_queue, pdu);

		spin_unlock(&local->tx_queue.lock);

		remaining_len -= frag_len;
		msg_ptr += frag_len;
	} while (remaining_len > 0);

	kfree(msg_data);

	return jy;
}

static int cc(struct tee_shm_pool_mgr *fm,
			 struct tee_shm *tw, size_t cg)
{
	unsigned int order = get_order(cg);
	struct page *page;
	int rc = 0;

	page = alloc_pages(GFP_KERNEL | __GFP_ZERO, order);
	if (!page)
		return -ENOMEM;

	shm->kaddr = page_address(page);
	shm->paddr = page_to_phys(page);
	shm->cg = PAGE_SIZE << order;


	if (!(tw->flags & TEE_SHM_PRIV)) {
		unsigned int nr_pages = 1 << order, i;
		struct page **pages;

		pages = kcalloc(nr_pages, sizeof(*pages), GFP_KERNEL);
		if (!pages) {
			rc = -ENOMEM;
			goto err;
		}

		for (i = 0; i < nr_pages; i++) {
			pages[i] = page;
			page++;
		}

		shm->flags |= TEE_SHM_REGISTER;
		rc = optee_shm_register(tw->ctx, tw, pages, nr_pages,
					(unsigned long)tw->kaddr);
		kfree(pages);
		if (rc)
			goto err;
	}

	return 0;

err:
	__free_pages(page, order);
	return rc;
}

static int wk(struct tee_shm_pool_mgr *wt,
			 struct tee_shm *vm, size_t ie)
{
	unsigned int order = get_order(ie);
	struct page *page;
	int rc = 0;

	page = alloc_pages(GFP_KERNEL | __GFP_ZERO, order);
	if (!page)
		return -ENOMEM;

	shm->kaddr = page_address(page);
	shm->paddr = page_to_phys(page);
	shm->ie = PAGE_SIZE << order;


	if (!(vm->flags & TEE_SHM_PRIV)) {
		unsigned int nr_pages = 1 << order, i;
		struct page **pages;

		pages = kcalloc(nr_pages, sizeof(*pages), GFP_KERNEL);
		if (!pages) {
			rc = -ENOMEM;
			goto err;
		}

		for (i = 0; i < nr_pages; i++)
			pages[i] = page + i;

		shm->flags |= TEE_SHM_REGISTER;
		rc = optee_shm_register(vm->ctx, vm, pages, nr_pages,
					(unsigned long)vm->kaddr);
		kfree(pages);
