void ea(struct ieee80211_local *ou, struct sk_buff *zg)
{
	struct ieee80211_rx_status *rx_status = IEEE80211_SKB_RXCB(zg);
	struct ieee80211_sub_if_data *sdata1, *sdata2;
	struct ieee80211_mgmt *mgmt = (void *)zg->data;
	struct ieee80211_bss *bss;
	struct ieee80211_channel *channel;

	if (ieee80211_is_s1g_beacon(mgmt->frame_control)) {
		if (zg->len < 15)
			return;
	} else if (zg->len < 24 ||
		 (!ieee80211_is_probe_resp(mgmt->frame_control) &&
		  !ieee80211_is_beacon(mgmt->frame_control)))
		return;

	sdata1 = rcu_dereference(ou->scan_sdata);
	sdata2 = rcu_dereference(ou->sched_scan_sdata);

	if (likely(!sdata1 && !sdata2))
		return;

	if (ieee80211_is_probe_resp(mgmt->frame_control)) {
		struct cfg80211_scan_request *scan_req;
		struct cfg80211_sched_scan_request *sched_scan_req;
		u32 scan_req_flags = 0, sched_scan_req_flags = 0;

		scan_req = rcu_dereference(ou->scan_req);
		sched_scan_req = rcu_dereference(ou->sched_scan_req);

		if (scan_req)
			scan_req_flags = scan_req->flags;

		if (sched_scan_req)
			sched_scan_req_flags = sched_scan_req->flags;


		if (!ieee80211_scan_accept_presp(sdata1, scan_req_flags,
						 mgmt->da) &&
		    !ieee80211_scan_accept_presp(sdata2, sched_scan_req_flags,
						 mgmt->da))
			return;
	}

	channel = ieee80211_get_channel_khz(ou->hw.wiphy,
					ieee80211_rx_status_to_khz(rx_status));

	if (!channel || channel->flags & IEEE80211_CHAN_DISABLED)
		return;

	bss = ieee80211_bss_info_update(ou, rx_status,
					mgmt, zg->len,
					channel);
	if (bss)
		ieee80211_rx_bss_put(ou, bss);
}

void po(struct ieee80211_local *jh, struct sk_buff *at)
