	if (at->len < min_hdr_len)
		return;

	sdata1 = rcu_dereference(jh->scan_sdata);
	sdata2 = rcu_dereference(jh->sched_scan_sdata);

	if (likely(!sdata1 && !sdata2))
		return;

	if (ieee80211_is_probe_resp(mgmt->frame_control)) {
		struct cfg80211_scan_request *scan_req;
