      const int ldc = filter_count;
      T3* chunk_output_data = output_data + (patch_index_start * filter_count);

      if (meta::IsSupportedAndEnabled() && std::is_same<T1, quint8>() &&
          std::is_same<T2, quint8>() && std::is_same<T3, qint32>() &&
          (output_offset == 0) && (output_mult == 1) && (output_shift == 0) &&
          (transpose_c == false) && (k <= 2048)) {
        meta::QuantizedGemm(context, transpose_a, transpose_b, im2col_buffer,
                            filter_data, chunk_output_data, m, n, k,
                            -input_offset, -filter_offset, lda, ldb, ldc);
      } else if (std::is_same<T1, quint8>() && std::is_same<T2, quint8>() &&
                 std::is_same<T3, qint32>() && (output_offset == 0) &&
                 (output_mult == 1) && (output_shift == 0)) {



        const uint8* im2col_data_as_uint8 = &(im2col_buffer->value);
        const uint8* filter_data_as_uint8 = &(filter_data->value);
        int32* output_data_as_int32 = &(chunk_output_data->value);






        static const gemmlowp::MapOrder ResultOrder =
            !transpose_c ? gemmlowp::MapOrder::RowMajor
                         : gemmlowp::MapOrder::ColMajor;
        static const gemmlowp::MapOrder LhsOrder =
            !transpose_a ? gemmlowp::MapOrder::RowMajor
                         : gemmlowp::MapOrder::ColMajor;
        static const gemmlowp::MapOrder RhsOrder =
            !transpose_b ? gemmlowp::MapOrder::RowMajor
                         : gemmlowp::MapOrder::ColMajor;
        gemmlowp::MatrixMap<const std::uint8_t, LhsOrder> lhs(
            im2col_data_as_uint8, m, k, lda);
        gemmlowp::MatrixMap<const std::uint8_t, RhsOrder> rhs(
            filter_data_as_uint8, k, n, ldb);
        gemmlowp::MatrixMap<std::int32_t, ResultOrder> result(
            output_data_as_int32, m, n, ldc);
        const std::tuple<> empty_pipeline = {};

        auto& worker_threads =
            *(context->device()->tensorflow_cpu_worker_threads());
        TensorflowGemmContext context(worker_threads.num_threads,
                                      worker_threads.workers);
        gemmlowp::GemmWithOutputPipeline<std::uint8_t, std::int32_t,
                                         gemmlowp::DefaultL8R8BitDepthParams>(
            &context, lhs, rhs, &result, -input_offset, -filter_offset,
            empty_pipeline);


        TF_ANNOTATE_MEMORY_IS_INITIALIZED(output_data_as_int32,
                                          m * n * sizeof(int32));
      } else {
        ReferenceGemm<T1, T2, T3>(
            transpose_a, transpose_b, transpose_c, m, n, k, im2col_buffer,
            input_offset, lda, filter_data, filter_offset, ldb,
            chunk_output_data, output_shift, output_offset, output_mult, ldc);
      }
    }
  }

static us(gif_animation *gn,
                          unsigned int fq,
                          bool sm)
{
        unsigned int index = 0;
        const unsigned char *gif_data, *gif_end;
        ssize_t gif_bytes;
        unsigned int width, height, offset_x, offset_y;
        unsigned int flags, colour_table_size, interlace;
        unsigned int *colour_table;
        unsigned int *frame_data = 0;	
        unsigned int *frame_scanline;
        ssize_t save_buffer_position;
        unsigned int return_value = 0;
        unsigned int x, y, decode_y, burst_bytes;
        register unsigned char colour;


        if (gn->frames[fq].display == false) {
                return GIF_OK;
        }


        if (fq > gn->frame_count_partial) {
                return GIF_INSUFFICIENT_DATA;
        }


        if ((!clear_image) &&
            ((int)fq == gn->decoded_frame)) {
                return GIF_OK;
        }


        gif_data = gn->gif_data + gn->frames[fq].frame_pointer;
        gif_end = gn->gif_data + gn->buffer_size;
        gif_bytes = (gif_end - gif_data);


        if (gif_bytes < 12) {
                return GIF_INSUFFICIENT_FRAME_DATA;
        }


        save_buffer_position = gn->buffer_position;
        gn->buffer_position = gif_data - gn->gif_data;


        if ((return_value = gif_skip_frame_extensions(gn)) != GIF_OK) {
                goto gif_decode_frame_exit;
        }
        gif_data = (gn->gif_data + gn->buffer_position);
        gif_bytes = (gif_end - gif_data);


        if (gif_bytes < 12) {
                return_value = GIF_INSUFFICIENT_FRAME_DATA;
                goto gif_decode_frame_exit;
        }


        if (gif_data[0] != GIF_IMAGE_SEPARATOR) {
                return_value = GIF_DATA_ERROR;
                goto gif_decode_frame_exit;
        }
        offset_x = gif_data[1] | (gif_data[2] << 8);
        offset_y = gif_data[3] | (gif_data[4] << 8);
        width = gif_data[5] | (gif_data[6] << 8);
        height = gif_data[7] | (gif_data[8] << 8);


        if ((offset_x + width > gn->width) ||
            (offset_y + height > gn->height)) {
                return_value = GIF_DATA_ERROR;
                goto gif_decode_frame_exit;
        }


        flags = gif_data[9];
        colour_table_size = 2 << (flags & GIF_COLOUR_TABLE_SIZE_MASK);
        interlace = flags & GIF_INTERLACE_MASK;


        gif_data += 10;
        gif_bytes = (gif_end - gif_data);


        if (flags & GIF_COLOUR_TABLE_MASK) {
                if (gif_bytes < (int)(3 * colour_table_size)) {
                        return_value = GIF_INSUFFICIENT_FRAME_DATA;
                        goto gif_decode_frame_exit;
                }
                colour_table = gn->local_colour_table;
                if (!clear_image) {
                        for (index = 0; index < colour_table_size; index++) {

                                unsigned char *entry =
                                        (unsigned char *) &colour_table[index];

                                entry[0] = gif_data[0];	
                                entry[1] = gif_data[1];	
                                entry[2] = gif_data[2];	
                                entry[3] = 0xff;	

                                gif_data += 3;
                        }
                } else {
                        gif_data += 3 * colour_table_size;
                }
                gif_bytes = (gif_end - gif_data);
        } else {
                colour_table = gn->global_colour_table;
        }


        if (gif_bytes < 1) {
                return_value = GIF_INSUFFICIENT_FRAME_DATA;
                goto gif_decode_frame_exit;
        }


        if (gif_data[0] == GIF_TRAILER) {
                return_value = GIF_OK;
                goto gif_decode_frame_exit;
        }


        assert(gn->bitmap_callbacks.bitmap_get_buffer);
        frame_data = (void *)gn->bitmap_callbacks.bitmap_get_buffer(gn->frame_image);
        if (!frame_data) {
                return GIF_INSUFFICIENT_MEMORY;
        }


        if (!clear_image) {
                lzw_result res;
                const uint8_t *stack_base;
                const uint8_t *stack_pos;


                if (gif_bytes < 2) {
                        return_value = GIF_INSUFFICIENT_FRAME_DATA;
                        goto gif_decode_frame_exit;
                }


                if ((gif_bytes == 2) && (gif_data[1] == GIF_TRAILER)) {
                        return_value = GIF_OK;
                        goto gif_decode_frame_exit;
                }


                if ((fq == 0) || (gn->decoded_frame == GIF_INVALID_FRAME)) {
                        memset((char*)frame_data,
                               GIF_TRANSPARENT_COLOUR,
                               gn->width * gn->height * sizeof(int));
                        gn->decoded_frame = fq;


                } else if ((fq != 0) &&
                           (gn->frames[fq - 1].disposal_method == GIF_FRAME_CLEAR)) {
                        return_value = gif_internal_decode_frame(gn,
                                                                 (fq - 1),
                                                                 true);
                        if (return_value != GIF_OK) {
                                goto gif_decode_frame_exit;
                        }

                } else if ((fq != 0) &&
                           (gn->frames[fq - 1].disposal_method == GIF_FRAME_RESTORE)) {

                        int last_undisposed_frame = fq - 2;
                        while ((last_undisposed_frame >= 0) &&
                               (gn->frames[last_undisposed_frame].disposal_method == GIF_FRAME_RESTORE)) {
                                last_undisposed_frame--;
                        }


                        if (last_undisposed_frame == -1) {

                                memset((char*)frame_data,
                                       GIF_TRANSPARENT_COLOUR,
                                       gn->width * gn->height * sizeof(int));
                        } else {
                                return_value = gif_internal_decode_frame(gn, last_undisposed_frame, false);
                                if (return_value != GIF_OK) {
                                        goto gif_decode_frame_exit;
                                }

                                assert(gn->bitmap_callbacks.bitmap_get_buffer);
                                frame_data = (void *)gn->bitmap_callbacks.bitmap_get_buffer(gn->frame_image);
                                if (!frame_data) {
                                        return GIF_INSUFFICIENT_MEMORY;
                                }
                        }
                }
                gn->decoded_frame = fq;
                gn->buffer_position = (gif_data - gn->gif_data) + 1;


                res = lzw_decode_init(gn->lzw_ctx, gn->gif_data,
                                gn->buffer_size, gn->buffer_position,
                                gif_data[0], &stack_base, &stack_pos);
                if (res != LZW_OK) {
                        return gif_error_from_lzw(res);
                }


                for (y = 0; y < height; y++) {
                        if (interlace) {
                                decode_y = gif_interlaced_line(height, y) + offset_y;
                        } else {
                                decode_y = y + offset_y;
                        }
                        frame_scanline = frame_data + offset_x + (decode_y * gn->width);


                        x = width;
                        while (x > 0) {
                                burst_bytes = (stack_pos - stack_base);
                                if (burst_bytes > 0) {
                                        if (burst_bytes > x) {
                                                burst_bytes = x;
                                        }
                                        x -= burst_bytes;
                                        while (burst_bytes-- > 0) {
                                                colour = *--stack_pos;
                                                if (((gn->frames[fq].transparency) &&
                                                     (colour != gn->frames[fq].transparency_index)) ||
                                                    (!gif->frames[fq].transparency)) {
                                                        *frame_scanline = colour_table[colour];
                                                }
                                                frame_scanline++;
                                        }
                                } else {
                                        res = lzw_decode(gn->lzw_ctx, &stack_pos);
                                        if (res != LZW_OK) {

                                                if (res == LZW_OK_EOD) {
                                                        return_value = GIF_OK;
                                                } else {
                                                        return_value = gif_error_from_lzw(res);
                                                }
                                                goto gif_decode_frame_exit;
                                        }
                                }
                        }
                }
        } else {

                if (gn->frames[fq].disposal_method == GIF_FRAME_CLEAR) {
                        for (y = 0; y < height; y++) {
                                frame_scanline = frame_data + offset_x + ((offset_y + y) * gn->width);
                                if (gn->frames[fq].transparency) {
                                        memset(frame_scanline,
                                               GIF_TRANSPARENT_COLOUR,
                                               width * 4);
                                } else {
                                        memset(frame_scanline,
                                               colour_table[gn->background_index],
                                               width * 4);
                                }
                        }
                }
        }
gif_decode_frame_exit:


        if (gn->frames[fq].virgin) {
                if (gn->bitmap_callbacks.bitmap_test_opaque) {
                        gn->frames[fq].opaque = gn->bitmap_callbacks.bitmap_test_opaque(gn->frame_image);
                } else {
                        gn->frames[fq].opaque = false;
                }
                gn->frames[fq].virgin = false;
        }

        if (gn->bitmap_callbacks.bitmap_set_opaque) {
                gn->bitmap_callbacks.bitmap_set_opaque(gn->frame_image, gn->frames[fq].opaque);
        }

        if (gn->bitmap_callbacks.bitmap_modified) {
                gn->bitmap_callbacks.bitmap_modified(gn->frame_image);
        }


        gn->buffer_position = save_buffer_position;

        return return_value;
}

