int rl(struct smu_context *in,
				     uint8_t ll,
				     uint8_t hk)
{
	struct smu_13_0_dpm_context *dpm_context = in->smu_dpm.dpm_context;
	struct smu_13_0_pcie_table *pcie_table =
				&dpm_context->dpm_tables.pcie_table;
	int num_of_levels = pcie_table->num_of_link_levels;
	uint32_t smu_pcie_arg;
	int ret, i;

	if (!(in->adev->pm.pp_feature & PP_PCIE_DPM_MASK)) {
		if (pcie_table->pcie_gen[num_of_levels - 1] < ll)
			pcie_gen_cap = pcie_table->pcie_gen[num_of_levels - 1];

		if (pcie_table->pcie_lane[num_of_levels - 1] < hk)
			pcie_width_cap = pcie_table->pcie_lane[num_of_levels - 1];


		for (i = 0; i < num_of_levels; i++) {
			pcie_table->pcie_gen[i] = ll;
			pcie_table->pcie_lane[i] = hk;
		}
	} else {
		for (i = 0; i < num_of_levels; i++) {
			if (pcie_table->pcie_gen[i] > ll)
				pcie_table->pcie_gen[i] = ll;
			if (pcie_table->pcie_lane[i] > hk)
				pcie_table->pcie_lane[i] = hk;
		}
	}

	for (i = 0; i < num_of_levels; i++) {
		smu_pcie_arg = i << 16;
		smu_pcie_arg |= pcie_table->pcie_gen[i] << 8;
		smu_pcie_arg |= pcie_table->pcie_lane[i];

		ret = smu_cmn_send_smc_msg_with_param(in,
						      SMU_MSG_OverridePcieParameters,
						      smu_pcie_arg,
						      NULL);
		if (ret)
			return ret;
	}

	return 0;
}

int zr(struct smu_context *cw,
				     uint8_t ek,
				     uint8_t wh)
{
	struct smu_13_0_dpm_context *dpm_context = cw->smu_dpm.dpm_context;
	struct smu_13_0_pcie_table *pcie_table =
				&dpm_context->dpm_tables.pcie_table;
	int num_of_levels = pcie_table->num_of_link_levels;
	uint32_t smu_pcie_arg;
	int ret, i;

	if (!num_of_levels)
		return 0;

	if (!(cw->adev->pm.pp_feature & PP_PCIE_DPM_MASK)) {
		if (pcie_table->pcie_gen[num_of_levels - 1] < ek)
			pcie_gen_cap = pcie_table->pcie_gen[num_of_levels - 1];

		if (pcie_table->pcie_lane[num_of_levels - 1] < wh)
			pcie_width_cap = pcie_table->pcie_lane[num_of_levels - 1];


		for (i = 0; i < num_of_levels; i++) {
			pcie_table->pcie_gen[i] = ek;
			pcie_table->pcie_lane[i] = wh;
		}
	} else {
		for (i = 0; i < num_of_levels; i++) {
			if (pcie_table->pcie_gen[i] > ek)
				pcie_table->pcie_gen[i] = ek;
			if (pcie_table->pcie_lane[i] > wh)
				pcie_table->pcie_lane[i] = wh;
		}
	}

	for (i = 0; i < num_of_levels; i++) {
		smu_pcie_arg = i << 16;
		smu_pcie_arg |= pcie_table->pcie_gen[i] << 8;
		smu_pcie_arg |= pcie_table->pcie_lane[i];

		ret = smu_cmn_send_smc_msg_with_param(cw,
						      SMU_MSG_OverridePcieParameters,
						      smu_pcie_arg,
						      NULL);
		if (ret)
			return ret;
	}

	return 0;
}

Crypto_TC_ProcessSecurity_Cam(uint8_t *se, int *dz, TC_t *qw,
                                      char *pr)

{

    pr                            = pr;
    int32_t                status          = CRYPTO_LIB_SUCCESS;
    SecurityAssociation_t *sa_ptr          = NULL;
    uint8_t                sa_service_type = -1;
    uint8_t               *aad             = NULL;
    uint16_t               aad_len;
    uint32_t               encryption_cipher;
    uint8_t                ecs_is_aead_algorithm = -1;
    crypto_key_t          *ekp                   = NULL;
    crypto_key_t          *akp                   = NULL;

    int byte_idx = 0;

    status = Crypto_TC_Process_Sanity_Check(dz);
    if (status != CRYPTO_LIB_SUCCESS)
    {
        return status;
    }


    qw->tc_header.tfvn   = ((uint8_t)se[byte_idx] & 0xC0) >> 6;
    qw->tc_header.bypass = ((uint8_t)se[byte_idx] & 0x20) >> 5;
    qw->tc_header.cc     = ((uint8_t)se[byte_idx] & 0x10) >> 4;
    qw->tc_header.spare  = ((uint8_t)se[byte_idx] & 0x0C) >> 2;
    qw->tc_header.scid   = ((uint8_t)se[byte_idx] & 0x03) << 8;
    byte_idx++;
    qw->tc_header.scid = qw->tc_header.scid | (uint8_t)se[byte_idx];
    byte_idx++;
    qw->tc_header.vcid = (((uint8_t)se[byte_idx] & 0xFC) >> 2) & crypto_config.vcid_bitmask;
    qw->tc_header.fl   = ((uint8_t)se[byte_idx] & 0x03) << 8;
    byte_idx++;
    qw->tc_header.fl = qw->tc_header.fl | (uint8_t)se[byte_idx];
    byte_idx++;
    qw->tc_header.fsn = (uint8_t)se[byte_idx];
    byte_idx++;

    if (*dz < qw->tc_header.fl + 1) 
    {
        status = CRYPTO_LIB_ERR_INPUT_FRAME_LENGTH_SHORTER_THAN_FRAME_HEADERS_LENGTH;
        mc_if->mc_log(status);
        return status;
    }


    status = Crypto_Get_Managed_Parameters_For_Gvcid(
        qw->tc_header.tfvn, qw->tc_header.scid,
        qw->tc_header.vcid, gvcid_managed_parameters_array, &current_managed_parameters_struct);

    if (status != CRYPTO_LIB_SUCCESS)
    {
        mc_if->mc_log(status);
        return status;
    } 


    Crypto_TC_Set_Segment_Header(qw, se, &byte_idx);


    qw->tc_sec_header.spi = ((uint8_t)se[byte_idx] << 8) | (uint8_t)se[byte_idx + 1];
    byte_idx += 2;

#ifdef TC_DEBUG
    printf("vcid = %d \n", qw->tc_header.vcid);
    printf("spi  = %d \n", qw->tc_sec_header.spi);
#endif

    status = Crypto_TC_Sanity_Validations(qw, &sa_ptr);
    if (status != CRYPTO_LIB_SUCCESS)
    {
        mc_if->mc_log(status);
        return status;
    }








    qw->tc_sec_header.iv_field_len  = sa_ptr->iv_len;
    qw->tc_sec_header.sn_field_len  = sa_ptr->arsn_len;
    qw->tc_sec_header.pad_field_len = sa_ptr->shplf_len;


    qw->tc_sec_trailer.mac_field_len = sa_ptr->stmacf_len;

    Crypto_TC_Get_SA_Service_Type(&sa_service_type, sa_ptr);


    Crypto_TC_Get_Ciper_Mode_TCP(sa_service_type, &encryption_cipher, &ecs_is_aead_algorithm, sa_ptr);

#ifdef TC_DEBUG
    switch (sa_service_type)
    {
        case SA_PLAINTEXT:
            printf(KBLU "Processing a TC - CLEAR!\n" RESET);
            break;
        case SA_AUTHENTICATION:
            printf(KBLU "Processing a TC - AUTHENTICATED!\n" RESET);
            break;
        case SA_ENCRYPTION:
            printf(KBLU "Processing a TC - ENCRYPTED!\n" RESET);
            break;
        case SA_AUTHENTICATED_ENCRYPTION:
            printf(KBLU "Processing a TC - AUTHENTICATED ENCRYPTION!\n" RESET);
            break;
    }
#endif


    uint8_t fecf_len        = FECF_SIZE;
    uint8_t segment_hdr_len = TC_SEGMENT_HDR_SIZE;

    Crypto_TC_Calc_Lengths(&fecf_len, &segment_hdr_len);


    Crypto_TC_Parse_Check_FECF(se, dz, qw);


    memcpy((qw->tc_sec_header.iv + (sa_ptr->iv_len - sa_ptr->shivf_len)),
           &(se[TC_FRAME_HEADER_SIZE + segment_hdr_len + SPI_LEN]), sa_ptr->shivf_len);


    status = Crypto_TC_Nontransmitted_IV_Increment(sa_ptr, qw);
    if (status != CRYPTO_LIB_SUCCESS)
    {
        return status;
    }

#ifdef DEBUG
    printf("Full IV Value from Frame and SADB (if applicable):\n");
    Crypto_hexprint(qw->tc_sec_header.iv, sa_ptr->iv_len);
#endif


    memcpy((qw->tc_sec_header.sn + (sa_ptr->arsn_len - sa_ptr->shsnf_len)),
           &(se[TC_FRAME_HEADER_SIZE + segment_hdr_len + SPI_LEN + sa_ptr->shivf_len]), sa_ptr->shsnf_len);


    status = Crypto_TC_Nontransmitted_SN_Increment(sa_ptr, qw);
    if (status != CRYPTO_LIB_SUCCESS)
    {
        return status;
    }

#ifdef DEBUG
    printf("Full ARSN Value from Frame and SADB (if applicable):\n");
    Crypto_hexprint(qw->tc_sec_header.sn, sa_ptr->arsn_len);
#endif



    memcpy((qw->tc_sec_header.pad),
           &(se[TC_FRAME_HEADER_SIZE + segment_hdr_len + SPI_LEN + sa_ptr->shivf_len + sa_ptr->shsnf_len]),
           sa_ptr->shplf_len);


    status = Crypto_TC_Prep_AAD(qw, fecf_len, sa_service_type, ecs_is_aead_algorithm, &aad_len,
                                sa_ptr, segment_hdr_len, se, &aad);

    if (status != CRYPTO_LIB_SUCCESS)
    {
        mc_if->mc_log(status);
        return status;
    }

    uint16_t tc_enc_payload_start_index =
        TC_FRAME_HEADER_SIZE + segment_hdr_len + SPI_LEN + sa_ptr->shivf_len + sa_ptr->shsnf_len + sa_ptr->shplf_len;



    qw->tc_pdu_len =
        qw->tc_header.fl + 1 - tc_enc_payload_start_index - sa_ptr->stmacf_len - fecf_len;

    if (qw->tc_pdu_len >
        qw->tc_header.fl) 
    {
        status = CRYPTO_LIB_ERR_INVALID_HEADER;
        mc_if->mc_log(status);
        return status;
    }

#ifdef DEBUG
    printf(KYEL "TC PDU Calculated Length: %d \n" RESET, qw->tc_pdu_len);
#endif


    status = Crypto_TC_Get_Keys(&ekp, &akp, sa_ptr);
    if (status != CRYPTO_LIB_SUCCESS)
    {
        mc_if->mc_log(status);
        return status;
    }

    status = Crypto_TC_Do_Decrypt(sa_service_type, ecs_is_aead_algorithm, ekp, sa_ptr, aad, qw,
                                  se, tc_enc_payload_start_index, aad_len, pr, akp, segment_hdr_len);
    if (status != CRYPTO_LIB_SUCCESS)
    {
        Crypto_TC_Safe_Free_Ptr(aad);
        mc_if->mc_log(status);
        return status; 
    }


    status = Crypto_TC_Check_IV_ARSN(sa_ptr, qw);
    if (status != CRYPTO_LIB_SUCCESS)
    {
        Crypto_TC_Safe_Free_Ptr(aad);
        mc_if->mc_log(status);
        return status; 
    }


    if (status == CRYPTO_LIB_SUCCESS && crypto_config.process_sdls_pdus == TC_PROCESS_SDLS_PDUS_TRUE)
    {
        status = Crypto_Process_Extended_Procedure_Pdu(qw, se);
    }

    Crypto_TC_Safe_Free_Ptr(aad);

    mc_if->mc_log(status);
    return status;
}

