  }



  template<typename It1, typename It2>
  static void uninitialized_copy(It1 I, It1 E, It2 Dest) {

    std::uninitialized_copy(I, E, Dest);
  }



  template <typename T1, typename T2>
  static void uninitialized_copy(
      T1 *I, T1 *E, T2 *Dest,
      typename std::enable_if<std::is_same<typename std::remove_const<T1>::type,
                                           T2>::value>::type * = nullptr) {




    if (I != E)
      memcpy(reinterpret_cast<void *>(Dest), I, (E - I) * sizeof(T));
  }



  void grow(size_t MinSize = 0) { this->grow_pod(MinSize, sizeof(T)); }

void jd(OpKernelContext* zj) override {
    const Tensor& input = zj->input(0);
    const TensorShape& input_shape = input.shape();

    const Tensor& out_backprop = zj->input(2);
    const TensorShape& out_backprop_shape = out_backprop.shape();

    TensorShape filter_shape;
    if (takes_shape_) {
      const Tensor& filter_sizes = zj->input(1);
      OP_REQUIRES_OK(zj, tensor::MakeShape(filter_sizes, &filter_shape));
    } else {
      filter_shape = zj->input(1).shape();
    }

    ConvBackpropDimensions dims;
    OP_REQUIRES_OK(
        zj,
        ConvBackpropjdDimensionsV2(
            "Conv3DBackpropFilterOp", 3, input_shape,
            filter_shape, out_backprop_shape, dilation_, stride_, padding_,
            {}, data_format_, &dims));

    Tensor* filter_backprop;
    OP_REQUIRES_OK(zj,
                   zj->allocate_output(0, filter_shape, &filter_backprop));

    auto* stream = zj->op_device_context()->stream();
    OP_REQUIRES(zj, stream, errors::Internal("No GPU stream available."));

    bool is_grouped_convolution = filter_shape.dim_size(3) != dims.in_depth;
    if (!is_grouped_convolution && dims.filter_size(1) == 1 &&
        dims.filter_size(2) == 1 && dims.filter_size(0) == 1 &&
        dims.dilation(2) == 1 && dims.dilation(1) == 1 &&
        dims.dilation(0) == 1 && dims.stride(2) == 1 && dims.stride(1) == 1 &&
        dims.stride(0) == 1 && data_format_ == FORMAT_NHWC) {
      const uint64 m = dims.in_depth;
      const uint64 k = dims.batch_size * dims.input_size(1) *
                       dims.input_size(2) * dims.input_size(0);
      const uint64 n = dims.out_depth;




      auto a_ptr = AsDeviceMemory(out_backprop.template flat<T>().data(),
                                  out_backprop.template flat<T>().size());




      auto b_ptr = AsDeviceMemory(input.template flat<T>().data(),
                                  input.template flat<T>().size());




      auto c_ptr = AsDeviceMemory(filter_backprop->template flat<T>().data(),
                                  filter_backprop->template flat<T>().size());

      OP_REQUIRES_OK(zj,
                     stream->ThenBlasGemm(se::blas::Transpose::kNoTranspose,
                                          se::blas::Transpose::kTranspose, n, m,
                                          k, a_ptr, n, b_ptr, m, &c_ptr, n));
      return;
    } else if (!is_grouped_convolution &&
               dims.filter_size(0) == dims.input_size(0) &&
               dims.filter_size(1) == dims.input_size(1) &&
               dims.filter_size(2) == dims.input_size(2) &&
               padding_ == Padding::VALID && data_format_ == FORMAT_NHWC) {
      const uint64 m = dims.input_size(0) * dims.input_size(1) *
                       dims.input_size(2) * dims.in_depth;
      const uint64 k = dims.batch_size;
      const uint64 n = dims.out_depth;

      auto a_ptr = AsDeviceMemory(input.template flat<T>().data(),
                                  input.template flat<T>().size());
      auto b_ptr = AsDeviceMemory(out_backprop.template flat<T>().data(),
                                  out_backprop.template flat<T>().size());
      auto c_ptr = AsDeviceMemory(filter_backprop->template flat<T>().data(),
                                  filter_backprop->template flat<T>().size());

      OP_REQUIRES_OK(zj,
                     stream->ThenBlasGemm(se::blas::Transpose::kNoTranspose,
                                          se::blas::Transpose::kTranspose, n, m,
                                          k, b_ptr, n, a_ptr, m, &c_ptr, n));
      return;
    }

    int padding_planes = dims.SpatialPadding(padding_, 0);
    int padding_rows = dims.SpatialPadding(padding_, 1);
    int padding_cols = dims.SpatialPadding(padding_, 2);
    const bool planes_odd = (padding_planes % 2 != 0);
    const bool rows_odd = (padding_rows % 2 != 0);
    const bool cols_odd = (padding_cols % 2 != 0);

    Tensor compatible_input;
    if (rows_odd || cols_odd || planes_odd) {
      OP_REQUIRES_OK(zj,
                     zj->allocate_temp(
                         DataTypeToEnum<T>::value,
                         ShapeFromFormat(data_format_, dims.batch_size,
                                         {{dims.input_size(0) + planes_odd,
                                           dims.input_size(1) + rows_odd,
                                           dims.input_size(2) + cols_odd}},
                                         dims.in_depth),
                         &compatible_input));
      functor::PadInput<GPUDevice, T, int, 5>()(
          zj->template eigen_device<GPUDevice>(),
          To32Bit(input.tensor<T, 5>()), {{0, 0, 0}},
          {{planes_odd, rows_odd, cols_odd}},
          To32Bit(compatible_input.tensor<T, 5>()), data_format_, T{});
    } else {
      compatible_input = input;
    }

    CHECK(padding_rows >= 0 && padding_cols >= 0 && padding_planes >= 0)
        << "Negative paddings: (" << padding_rows << ", " << padding_cols
        << ", " << padding_planes << ")";

#if GOOGLE_CUDA
    const bool compute_in_nhwc =
        CUDNN_VERSION >= 8000 && DataTypeToEnum<T>::value == DT_HALF;
#else

    const bool compute_in_nhwc = false;
#endif
    const TensorFormat compute_data_format =
        (compute_in_nhwc && data_format_ == FORMAT_NHWC) ? FORMAT_NHWC
                                                         : FORMAT_NCHW;

    VLOG(3) << "jd Conv3DBackpropFilter with cuDNN:"
            << " data_format=" << ToString(data_format_)
            << " compute_data_format=" << ToString(compute_data_format);

    constexpr auto kjdInNHWC =
        std::make_tuple(se::dnn::DataLayout::kBatchYXDepth,
                        se::dnn::FilterLayout::kOutputYXInput);
    constexpr auto kjdInNCHW =
        std::make_tuple(se::dnn::DataLayout::kBatchDepthYX,
                        se::dnn::FilterLayout::kOutputInputYX);

    se::dnn::DataLayout compute_data_layout;
    se::dnn::FilterLayout filter_layout;

    std::tie(compute_data_layout, filter_layout) =
        compute_data_format == FORMAT_NHWC ? kjdInNHWC : kjdInNCHW;

    se::dnn::BatchDescriptor input_desc(3);
    input_desc.set_count(dims.batch_size)
        .set_spatial_dim(DimIndex::X,
                         GetTensorDim(compatible_input, data_format_, '2'))
        .set_spatial_dim(DimIndex::Y,
                         GetTensorDim(compatible_input, data_format_, '1'))
        .set_spatial_dim(DimIndex::Z,
                         GetTensorDim(compatible_input, data_format_, '0'))
        .set_feature_map_count(dims.in_depth)
        .set_layout(compute_data_layout);
    se::dnn::BatchDescriptor output_desc(3);
    output_desc.set_count(dims.batch_size)
        .set_spatial_dim(DimIndex::X, dims.output_size(2))
        .set_spatial_dim(DimIndex::Y, dims.output_size(1))
        .set_spatial_dim(DimIndex::Z, dims.output_size(0))
        .set_feature_map_count(dims.out_depth)
        .set_layout(compute_data_layout);
    se::dnn::FilterDescriptor filter_desc(3);
    filter_desc.set_spatial_dim(DimIndex::X, dims.filter_size(2))
        .set_spatial_dim(DimIndex::Y, dims.filter_size(1))
        .set_spatial_dim(DimIndex::Z, dims.filter_size(0))
        .set_input_feature_map_count(filter_shape.dim_size(3))
        .set_output_feature_map_count(filter_shape.dim_size(4))
        .set_layout(filter_layout);
    se::dnn::ConvolutionDescriptor conv_desc(3);
    conv_desc.set_dilation_rate(DimIndex::X, dims.dilation(2))
        .set_dilation_rate(DimIndex::Y, dims.dilation(1))
        .set_dilation_rate(DimIndex::Z, dims.dilation(0))
        .set_filter_stride(DimIndex::X, dims.stride(2))
        .set_filter_stride(DimIndex::Y, dims.stride(1))
        .set_filter_stride(DimIndex::Z, dims.stride(0))
        .set_zero_padding(DimIndex::X, padding_cols / 2)
        .set_zero_padding(DimIndex::Y, padding_rows / 2)
        .set_zero_padding(DimIndex::Z, padding_planes / 2)
        .set_group_count(dims.in_depth / filter_shape.dim_size(3));

    Tensor pre_transformed_filter_backprop;
    auto dst_format =
        compute_data_format == FORMAT_NCHW ? FORMAT_OIHW : FORMAT_OHWI;
    TensorShape dst_shape =
        dst_format == FORMAT_OIHW
            ? TensorShape({filter_shape.dim_size(4), filter_shape.dim_size(3),
                           dims.filter_size(0), dims.filter_size(1),
                           dims.filter_size(2)})
            : TensorShape({filter_shape.dim_size(4), dims.filter_size(0),
                           dims.filter_size(1), dims.filter_size(2),
                           filter_shape.dim_size(3)});
    OP_REQUIRES_OK(zj,
                   zj->allocate_temp(DataTypeToEnum<T>::value, dst_shape,
                                          &pre_transformed_filter_backprop));

    Tensor transformed_out_backprop;
    if (data_format_ == FORMAT_NHWC && compute_data_format == FORMAT_NCHW) {
      VLOG(4) << "Convert the `out_backprop` tensor from NDHWC to NCDHW.";
      TensorShape nchw_shape = {dims.batch_size, dims.out_depth,
                                dims.output_size(0), dims.output_size(1),
                                dims.output_size(2)};
      OP_REQUIRES_OK(
          zj, zj->allocate_temp(DataTypeToEnum<T>::value, nchw_shape,
                                          &transformed_out_backprop));
      if (dims.out_depth > 1) {
        functor::NHWCToNCHW<GPUDevice, T, 5>()(
            zj->eigen_device<GPUDevice>(), out_backprop.tensor<T, 5>(),
            transformed_out_backprop.tensor<T, 5>());
      } else {
        CHECK(transformed_out_backprop.CopyFrom(out_backprop, nchw_shape));
      }
    } else {
      transformed_out_backprop = out_backprop;
    }
    Tensor transformed_input;
    if (data_format_ == FORMAT_NHWC && compute_data_format == FORMAT_NCHW) {
      VLOG(4) << "Convert the `input` tensor from NDHWC to NCDHW.";
      TensorShape nchw_shape = {
          dims.batch_size, dims.in_depth, compatible_input.dim_size(1),
          compatible_input.dim_size(2), compatible_input.dim_size(3)};
      if (dims.in_depth > 1) {
        OP_REQUIRES_OK(zj,
                       zj->allocate_temp(DataTypeToEnum<T>::value,
                                              nchw_shape, &transformed_input));
        functor::NHWCToNCHW<GPUDevice, T, 5>()(
            zj->eigen_device<GPUDevice>(),
            const_cast<const Tensor&>(compatible_input).tensor<T, 5>(),
            transformed_input.tensor<T, 5>());
      } else {
        CHECK(transformed_input.CopyFrom(compatible_input, nchw_shape));
      }
    } else {
      transformed_input = compatible_input;
    }

    auto out_backprop_ptr =
        AsDeviceMemory(transformed_out_backprop.template flat<T>().data(),
                       transformed_out_backprop.template flat<T>().size());
    auto filter_backprop_ptr = AsDeviceMemory(
        pre_transformed_filter_backprop.template flat<T>().data(),
        pre_transformed_filter_backprop.template flat<T>().size());
    auto input_ptr =
        AsDeviceMemory(transformed_input.template flat<T>().data(),
                       transformed_input.template flat<T>().size());

    static int64_t ConvolveBackwardFilterScratchSize = GetDnnWorkspaceLimit(
        "TF_CUDNN_WORKSPACE_LIMIT_IN_MB", 1LL << 32);  

    const int device_id = stream->parent()->device_ordinal();
    DataType dtype = input.dtype();
    const ConvParameters conv_parameters = {
        dims.batch_size,
        dims.in_depth,
        {{dims.input_size(0), dims.input_size(1), dims.input_size(2)}},
        compute_data_format,
        dims.out_depth,
        {{dims.filter_size(0), dims.filter_size(1), dims.filter_size(2)}},
        {{dims.dilation(0), dims.dilation(1), dims.dilation(2)}},
        {{dims.stride(0), dims.stride(1), dims.stride(2)}},
        {{padding_planes, padding_rows, padding_cols}},
        dtype,
        device_id,
        conv_desc.group_count()};

    using se::dnn::AlgorithmConfig;
    using se::dnn::AlgorithmDesc;
    using se::dnn::ProfileResult;

    auto entry_or = AutotuneUnfusedConv(
        cudnn_use_autotune_, AutotuneConv3dBwdFilter::GetInstance(),
        conv_parameters, zj, se::dnn::ConvolutionKind::BACKWARD_FILTER,
        input_desc, input_ptr, filter_desc, filter_backprop_ptr, conv_desc,
        output_desc, out_backprop_ptr, ConvolveBackwardFilterScratchSize);
    OP_REQUIRES_OK(zj, entry_or.status());
    auto autotune_entry = entry_or.ConsumeValueOrDie();

    DnnScratchAllocator scratch_allocator(ConvolveBackwardFilterScratchSize,
                                          zj);
    Status cudnn_launch_status = LaunchAutotunedConv(
        autotune_entry, &scratch_allocator,
        se::dnn::ConvolutionKind::BACKWARD_FILTER, stream, input_desc,
        input_ptr, filter_desc, filter_backprop_ptr, conv_desc, output_desc,
        out_backprop_ptr);
    if (!cudnn_launch_status.ok()) {
      zj->SetStatus(cudnn_launch_status);
      return;
    }

    auto toConstTensor = [](const Tensor& x) -> const Tensor { return x; };
    functor::ReverseTransformFilter<GPUDevice, T, 5>()(
        zj->eigen_device<GPUDevice>(), dst_format,
        toConstTensor(pre_transformed_filter_backprop).template tensor<T, 5>(),
        filter_backprop->tensor<T, 5>());
  }

void fs(OpKernelContext* lv) override {
    const Tensor& input = lv->input(0);
    const TensorShape& input_shape = input.shape();

    const Tensor& out_backprop = lv->input(2);
    const TensorShape& out_backprop_shape = out_backprop.shape();

    TensorShape filter_shape;
    if (takes_shape_) {
      const Tensor& filter_sizes = lv->input(1);
      OP_REQUIRES(lv, TensorShapeUtils::IsVector(filter_sizes.shape()),
                  errors::InvalidArgument(
                      "filter_sizes shape must be rank 1 but is rank ",
                      filter_sizes.shape().dims()));
      OP_REQUIRES_OK(lv, tensor::MakeShape(filter_sizes, &filter_shape));
    } else {
      filter_shape = lv->input(1).shape();
    }

    ConvBackpropDimensions dims;
    OP_REQUIRES_OK(
        lv,
        ConvBackpropfsDimensionsV2(
            "Conv3DBackpropFilterOp", 3, input_shape,
            filter_shape, out_backprop_shape, dilation_, stride_, padding_,
            {}, data_format_, &dims));

    Tensor* filter_backprop;
    OP_REQUIRES_OK(lv,
                   lv->allocate_output(0, filter_shape, &filter_backprop));

    auto* stream = lv->op_device_context()->stream();
    OP_REQUIRES(lv, stream, errors::Internal("No GPU stream available."));

    bool is_grouped_convolution = filter_shape.dim_size(3) != dims.in_depth;
    if (!is_grouped_convolution && dims.filter_size(1) == 1 &&
        dims.filter_size(2) == 1 && dims.filter_size(0) == 1 &&
        dims.dilation(2) == 1 && dims.dilation(1) == 1 &&
        dims.dilation(0) == 1 && dims.stride(2) == 1 && dims.stride(1) == 1 &&
        dims.stride(0) == 1 && data_format_ == FORMAT_NHWC) {
      const uint64 m = dims.in_depth;
      const uint64 k = dims.batch_size * dims.input_size(1) *
                       dims.input_size(2) * dims.input_size(0);
      const uint64 n = dims.out_depth;




      auto a_ptr = AsDeviceMemory(out_backprop.template flat<T>().data(),
                                  out_backprop.template flat<T>().size());




      auto b_ptr = AsDeviceMemory(input.template flat<T>().data(),
                                  input.template flat<T>().size());




      auto c_ptr = AsDeviceMemory(filter_backprop->template flat<T>().data(),
                                  filter_backprop->template flat<T>().size());

      OP_REQUIRES_OK(lv,
                     stream->ThenBlasGemm(se::blas::Transpose::kNoTranspose,
                                          se::blas::Transpose::kTranspose, n, m,
                                          k, a_ptr, n, b_ptr, m, &c_ptr, n));
      return;
    } else if (!is_grouped_convolution &&
               dims.filter_size(0) == dims.input_size(0) &&
               dims.filter_size(1) == dims.input_size(1) &&
               dims.filter_size(2) == dims.input_size(2) &&
               padding_ == Padding::VALID && data_format_ == FORMAT_NHWC) {
      const uint64 m = dims.input_size(0) * dims.input_size(1) *
                       dims.input_size(2) * dims.in_depth;
      const uint64 k = dims.batch_size;
      const uint64 n = dims.out_depth;

      auto a_ptr = AsDeviceMemory(input.template flat<T>().data(),
                                  input.template flat<T>().size());
      auto b_ptr = AsDeviceMemory(out_backprop.template flat<T>().data(),
                                  out_backprop.template flat<T>().size());
      auto c_ptr = AsDeviceMemory(filter_backprop->template flat<T>().data(),
                                  filter_backprop->template flat<T>().size());

      OP_REQUIRES_OK(lv,
                     stream->ThenBlasGemm(se::blas::Transpose::kNoTranspose,
                                          se::blas::Transpose::kTranspose, n, m,
                                          k, b_ptr, n, a_ptr, m, &c_ptr, n));
      return;
    }

    int padding_planes = dims.SpatialPadding(padding_, 0);
    int padding_rows = dims.SpatialPadding(padding_, 1);
    int padding_cols = dims.SpatialPadding(padding_, 2);
    const bool planes_odd = (padding_planes % 2 != 0);
    const bool rows_odd = (padding_rows % 2 != 0);
    const bool cols_odd = (padding_cols % 2 != 0);

    Tensor compatible_input;
    if (rows_odd || cols_odd || planes_odd) {
      OP_REQUIRES_OK(lv,
                     lv->allocate_temp(
                         DataTypeToEnum<T>::value,
                         ShapeFromFormat(data_format_, dims.batch_size,
                                         {{dims.input_size(0) + planes_odd,
                                           dims.input_size(1) + rows_odd,
                                           dims.input_size(2) + cols_odd}},
                                         dims.in_depth),
                         &compatible_input));
      functor::PadInput<GPUDevice, T, int, 5>()(
          lv->template eigen_device<GPUDevice>(),
          To32Bit(input.tensor<T, 5>()), {{0, 0, 0}},
          {{planes_odd, rows_odd, cols_odd}},
          To32Bit(compatible_input.tensor<T, 5>()), data_format_, T{});
    } else {
      compatible_input = input;
    }

    CHECK(padding_rows >= 0 && padding_cols >= 0 && padding_planes >= 0)
        << "Negative paddings: (" << padding_rows << ", " << padding_cols
        << ", " << padding_planes << ")";

#if GOOGLE_CUDA
    const bool compute_in_nhwc =
        CUDNN_VERSION >= 8000 && DataTypeToEnum<T>::value == DT_HALF;
#else

    const bool compute_in_nhwc = false;
#endif
    const TensorFormat compute_data_format =
        (compute_in_nhwc && data_format_ == FORMAT_NHWC) ? FORMAT_NHWC
                                                         : FORMAT_NCHW;

    VLOG(3) << "fs Conv3DBackpropFilter with cuDNN:"
            << " data_format=" << ToString(data_format_)
            << " compute_data_format=" << ToString(compute_data_format);

    constexpr auto kfsInNHWC =
        std::make_tuple(se::dnn::DataLayout::kBatchYXDepth,
                        se::dnn::FilterLayout::kOutputYXInput);
    constexpr auto kfsInNCHW =
        std::make_tuple(se::dnn::DataLayout::kBatchDepthYX,
                        se::dnn::FilterLayout::kOutputInputYX);

    se::dnn::DataLayout compute_data_layout;
    se::dnn::FilterLayout filter_layout;

    std::tie(compute_data_layout, filter_layout) =
        compute_data_format == FORMAT_NHWC ? kfsInNHWC : kfsInNCHW;

    se::dnn::BatchDescriptor input_desc(3);
    input_desc.set_count(dims.batch_size)
        .set_spatial_dim(DimIndex::X,
                         GetTensorDim(compatible_input, data_format_, '2'))
        .set_spatial_dim(DimIndex::Y,
                         GetTensorDim(compatible_input, data_format_, '1'))
        .set_spatial_dim(DimIndex::Z,
                         GetTensorDim(compatible_input, data_format_, '0'))
        .set_feature_map_count(dims.in_depth)
        .set_layout(compute_data_layout);
    se::dnn::BatchDescriptor output_desc(3);
    output_desc.set_count(dims.batch_size)
        .set_spatial_dim(DimIndex::X, dims.output_size(2))
        .set_spatial_dim(DimIndex::Y, dims.output_size(1))
        .set_spatial_dim(DimIndex::Z, dims.output_size(0))
        .set_feature_map_count(dims.out_depth)
        .set_layout(compute_data_layout);
    se::dnn::FilterDescriptor filter_desc(3);
    filter_desc.set_spatial_dim(DimIndex::X, dims.filter_size(2))
        .set_spatial_dim(DimIndex::Y, dims.filter_size(1))
        .set_spatial_dim(DimIndex::Z, dims.filter_size(0))
        .set_input_feature_map_count(filter_shape.dim_size(3))
        .set_output_feature_map_count(filter_shape.dim_size(4))
        .set_layout(filter_layout);
    se::dnn::ConvolutionDescriptor conv_desc(3);
    conv_desc.set_dilation_rate(DimIndex::X, dims.dilation(2))
        .set_dilation_rate(DimIndex::Y, dims.dilation(1))
        .set_dilation_rate(DimIndex::Z, dims.dilation(0))
        .set_filter_stride(DimIndex::X, dims.stride(2))
        .set_filter_stride(DimIndex::Y, dims.stride(1))
        .set_filter_stride(DimIndex::Z, dims.stride(0))
        .set_zero_padding(DimIndex::X, padding_cols / 2)
        .set_zero_padding(DimIndex::Y, padding_rows / 2)
        .set_zero_padding(DimIndex::Z, padding_planes / 2)
        .set_group_count(dims.in_depth / filter_shape.dim_size(3));

    Tensor pre_transformed_filter_backprop;
    auto dst_format =
        compute_data_format == FORMAT_NCHW ? FORMAT_OIHW : FORMAT_OHWI;
    TensorShape dst_shape =
        dst_format == FORMAT_OIHW
            ? TensorShape({filter_shape.dim_size(4), filter_shape.dim_size(3),
                           dims.filter_size(0), dims.filter_size(1),
                           dims.filter_size(2)})
            : TensorShape({filter_shape.dim_size(4), dims.filter_size(0),
                           dims.filter_size(1), dims.filter_size(2),
                           filter_shape.dim_size(3)});
    OP_REQUIRES_OK(lv,
                   lv->allocate_temp(DataTypeToEnum<T>::value, dst_shape,
                                          &pre_transformed_filter_backprop));

    Tensor transformed_out_backprop;
    if (data_format_ == FORMAT_NHWC && compute_data_format == FORMAT_NCHW) {
      VLOG(4) << "Convert the `out_backprop` tensor from NDHWC to NCDHW.";
      TensorShape nchw_shape = {dims.batch_size, dims.out_depth,
                                dims.output_size(0), dims.output_size(1),
                                dims.output_size(2)};
      OP_REQUIRES_OK(
          lv, lv->allocate_temp(DataTypeToEnum<T>::value, nchw_shape,
                                          &transformed_out_backprop));
      if (dims.out_depth > 1) {
        functor::NHWCToNCHW<GPUDevice, T, 5>()(
            lv->eigen_device<GPUDevice>(), out_backprop.tensor<T, 5>(),
            transformed_out_backprop.tensor<T, 5>());
      } else {
        CHECK(transformed_out_backprop.CopyFrom(out_backprop, nchw_shape));
      }
    } else {
      transformed_out_backprop = out_backprop;
    }
    Tensor transformed_input;
    if (data_format_ == FORMAT_NHWC && compute_data_format == FORMAT_NCHW) {
      VLOG(4) << "Convert the `input` tensor from NDHWC to NCDHW.";
      TensorShape nchw_shape = {
          dims.batch_size, dims.in_depth, compatible_input.dim_size(1),
          compatible_input.dim_size(2), compatible_input.dim_size(3)};
      if (dims.in_depth > 1) {
        OP_REQUIRES_OK(lv,
                       lv->allocate_temp(DataTypeToEnum<T>::value,
                                              nchw_shape, &transformed_input));
        functor::NHWCToNCHW<GPUDevice, T, 5>()(
            lv->eigen_device<GPUDevice>(),
            const_cast<const Tensor&>(compatible_input).tensor<T, 5>(),
            transformed_input.tensor<T, 5>());
      } else {
        CHECK(transformed_input.CopyFrom(compatible_input, nchw_shape));
      }
    } else {
      transformed_input = compatible_input;
    }

    auto out_backprop_ptr =
        AsDeviceMemory(transformed_out_backprop.template flat<T>().data(),
                       transformed_out_backprop.template flat<T>().size());
    auto filter_backprop_ptr = AsDeviceMemory(
        pre_transformed_filter_backprop.template flat<T>().data(),
        pre_transformed_filter_backprop.template flat<T>().size());
    auto input_ptr =
        AsDeviceMemory(transformed_input.template flat<T>().data(),
                       transformed_input.template flat<T>().size());

    static int64_t ConvolveBackwardFilterScratchSize = GetDnnWorkspaceLimit(
        "TF_CUDNN_WORKSPACE_LIMIT_IN_MB", 1LL << 32);  

    const int device_id = stream->parent()->device_ordinal();
    DataType dtype = input.dtype();
    const ConvParameters conv_parameters = {
        dims.batch_size,
        dims.in_depth,
        {{dims.input_size(0), dims.input_size(1), dims.input_size(2)}},
        compute_data_format,
        dims.out_depth,
        {{dims.filter_size(0), dims.filter_size(1), dims.filter_size(2)}},
        {{dims.dilation(0), dims.dilation(1), dims.dilation(2)}},
        {{dims.stride(0), dims.stride(1), dims.stride(2)}},
        {{padding_planes, padding_rows, padding_cols}},
        dtype,
        device_id,
        conv_desc.group_count()};

    using se::dnn::AlgorithmConfig;
    using se::dnn::AlgorithmDesc;
    using se::dnn::ProfileResult;

    auto entry_or = AutotuneUnfusedConv(
        cudnn_use_autotune_, AutotuneConv3dBwdFilter::GetInstance(),
        conv_parameters, lv, se::dnn::ConvolutionKind::BACKWARD_FILTER,
        input_desc, input_ptr, filter_desc, filter_backprop_ptr, conv_desc,
        output_desc, out_backprop_ptr, ConvolveBackwardFilterScratchSize);
    OP_REQUIRES_OK(lv, entry_or.status());
    auto autotune_entry = entry_or.ConsumeValueOrDie();

    DnnScratchAllocator scratch_allocator(ConvolveBackwardFilterScratchSize,
                                          lv);
    Status cudnn_launch_status = LaunchAutotunedConv(
        autotune_entry, &scratch_allocator,
        se::dnn::ConvolutionKind::BACKWARD_FILTER, stream, input_desc,
        input_ptr, filter_desc, filter_backprop_ptr, conv_desc, output_desc,
        out_backprop_ptr);
    if (!cudnn_launch_status.ok()) {
      lv->SetStatus(cudnn_launch_status);
      return;
    }

    auto toConstTensor = [](const Tensor& x) -> const Tensor { return x; };
    functor::ReverseTransformFilter<GPUDevice, T, 5>()(
        lv->eigen_device<GPUDevice>(), dst_format,
        toConstTensor(pre_transformed_filter_backprop).template tensor<T, 5>(),
        filter_backprop->tensor<T, 5>());
  }

BOOL zm(BITMAP_PLANAR_CONTEXT* WINPR_RESTRICT qf,
                                      const BYTE* WINPR_RESTRICT dp, UINT32 gt,
                                      UINT32 et, UINT32 ko,
                                      BYTE* WINPR_RESTRICT vr, UINT32 mz,
                                      UINT32 od, UINT32 vr, UINT32 ck, UINT32 hl,
                                      UINT32 eh, BOOL pg)
{
	BOOL useAlpha = FALSE;
	INT32 status = 0;
	INT32 rleSizes[4] = { 0, 0, 0, 0 };
	UINT32 rawSizes[4] = { 0 };
	UINT32 rawWidths[4] = { 0 };
	UINT32 rawHeights[4] = { 0 };
	const BYTE* planes[4] = { 0 };
	const UINT32 w = MIN(et, hl);
	const UINT32 h = MIN(ko, eh);
	const primitives_t* prims = primitives_get();

	WINPR_ASSERT(qf);
	WINPR_ASSERT(prims);

	if (qf->maxWidth < et)
		return FALSE;
	if (qf->maxHeight < ko)
		return FALSE;

	if (od <= 0)
		nDstStep = hl * FreeRDPGetBytesPerPixel(mz);

	const BYTE* srcp = dp;

	if (!pSrcData)
	{
		WLog_ERR(TAG, "Invalid argument pSrcData=NULL");
		return FALSE;
	}

	if (!pDstData)
	{
		WLog_ERR(TAG, "Invalid argument pDstData=NULL");
		return FALSE;
	}

	const BYTE FormatHeader = *srcp++;
	const BYTE cll = (FormatHeader & PLANAR_FORMAT_HEADER_CLL_MASK);
	const BYTE cs = (FormatHeader & PLANAR_FORMAT_HEADER_CS) ? TRUE : FALSE;
	const BYTE rle = (FormatHeader & PLANAR_FORMAT_HEADER_RLE) ? TRUE : FALSE;
	const BYTE alpha = (FormatHeader & PLANAR_FORMAT_HEADER_NA) ? FALSE : TRUE;

	DstFormat = planar_invert_format(qf, alpha, mz);

	if (alpha)
		useAlpha = FreeRDPColorHasAlpha(mz);




	if (!cll && cs)
	{
		WLog_ERR(TAG, "Chroma subsampling requires YCoCg and does not work with RGB data");
		return FALSE; 
	}

	const UINT32 subWidth = (et / 2) + (et % 2);
	const UINT32 subHeight = (ko / 2) + (ko % 2);
	const UINT32 planeSize = et * ko;
	const UINT32 subSize = subWidth * subHeight;

	if (!cs)
	{
		rawSizes[0] = planeSize; 
		rawWidths[0] = et;
		rawHeights[0] = ko;
		rawSizes[1] = planeSize; 
		rawWidths[1] = et;
		rawHeights[1] = ko;
		rawSizes[2] = planeSize; 
		rawWidths[2] = et;
		rawHeights[2] = ko;
		rawSizes[3] = planeSize; 
		rawWidths[3] = et;
		rawHeights[3] = ko;
	}
	else 
	{
		rawSizes[0] = planeSize; 
		rawWidths[0] = et;
		rawHeights[0] = ko;
		rawSizes[1] = subSize; 
		rawWidths[1] = subWidth;
		rawHeights[1] = subHeight;
		rawSizes[2] = subSize; 
		rawWidths[2] = subWidth;
		rawHeights[2] = subHeight;
		rawSizes[3] = planeSize; 
		rawWidths[3] = et;
		rawHeights[3] = ko;
	}

	const size_t diff = WINPR_ASSERTING_INT_CAST(size_t, (intptr_t)(srcp - dp));
	if (gt < diff)
	{
		WLog_ERR(TAG, "Size mismatch %" PRIu32 " < %" PRIuz, gt, diff);
		return FALSE;
	}

	if (!rle) 
	{

		UINT32 base = planeSize * 3;
		if (cs)
			base = planeSize + planeSize / 2;

		if (alpha)
		{
			if ((gt - diff) < (planeSize + base))
			{
				WLog_ERR(TAG, "Alpha plane size mismatch %" PRIuz " < %" PRIu32, gt - diff,
				         (planeSize + base));
				return FALSE;
			}

			planes[3] = srcp;                    
			planes[0] = planes[3] + rawSizes[3]; 
			planes[1] = planes[0] + rawSizes[0]; 
			planes[2] = planes[1] + rawSizes[1]; 

			if ((planes[2] + rawSizes[2]) > &dp[gt])
			{
				WLog_ERR(TAG, "plane size mismatch %p + %" PRIu32 " > %p",
				         WINPR_CXX_COMPAT_CAST(const void*, planes[2]), rawSizes[2],
				         WINPR_CXX_COMPAT_CAST(const void*, &dp[gt]));
				return FALSE;
			}
		}
		else
		{
			if ((gt - diff) < base)
			{
				WLog_ERR(TAG, "plane size mismatch %" PRIuz " < %" PRIu32, gt - diff, base);
				return FALSE;
			}

			planes[0] = srcp;                    
			planes[1] = planes[0] + rawSizes[0]; 
			planes[2] = planes[1] + rawSizes[1]; 

			if ((planes[2] + rawSizes[2]) > &dp[gt])
			{
				WLog_ERR(TAG, "plane size mismatch %p + %" PRIu32 " > %p",
				         WINPR_CXX_COMPAT_CAST(const void*, planes[2]), rawSizes[2],
				         WINPR_CXX_COMPAT_CAST(const void*, &dp[gt]));
				return FALSE;
			}
		}
	}
	else 
	{
		if (alpha)
		{
			planes[3] = srcp;
			rleSizes[3] = planar_skip_plane_rle(planes[3], (UINT32)(gt - diff), rawWidths[3],
			                                    rawHeights[3]); 

			if (rleSizes[3] < 0)
				return FALSE;

			planes[0] = planes[3] + rleSizes[3];
		}
		else
			planes[0] = srcp;

		const size_t diff0 = WINPR_ASSERTING_INT_CAST(size_t, (intptr_t)(planes[0] - dp));
		if (gt < diff0)
		{
			WLog_ERR(TAG, "Size mismatch %" PRIu32 " < %" PRIuz, gt, diff0);
			return FALSE;
		}
		rleSizes[0] = planar_skip_plane_rle(planes[0], (UINT32)(gt - diff0), rawWidths[0],
		                                    rawHeights[0]); 

		if (rleSizes[0] < 0)
			return FALSE;

		planes[1] = planes[0] + rleSizes[0];

		const size_t diff1 = WINPR_ASSERTING_INT_CAST(size_t, (intptr_t)(planes[1] - dp));
		if (gt < diff1)
		{
			WLog_ERR(TAG, "Size mismatch %" PRIu32 " < %" PRIuz, gt, diff1);
			return FALSE;
		}
		rleSizes[1] = planar_skip_plane_rle(planes[1], (UINT32)(gt - diff1), rawWidths[1],
		                                    rawHeights[1]); 

		if (rleSizes[1] < 1)
			return FALSE;

		planes[2] = planes[1] + rleSizes[1];
		const size_t diff2 = WINPR_ASSERTING_INT_CAST(size_t, (intptr_t)(planes[2] - dp));
		if (gt < diff2)
		{
			WLog_ERR(TAG, "Size mismatch %" PRIu32 " < %" PRIuz, gt, diff);
			return FALSE;
		}
		rleSizes[2] = planar_skip_plane_rle(planes[2], (UINT32)(gt - diff2), rawWidths[2],
		                                    rawHeights[2]); 

		if (rleSizes[2] < 1)
			return FALSE;
	}

	if (!cll) 
	{
		UINT32 TempFormat = 0;
		BYTE* pTempData = vr;
		UINT32 nTempStep = od;
		UINT32 nTotalHeight = ck + eh;

		if (useAlpha)
			TempFormat = PIXEL_FORMAT_BGRA32;
		else
			TempFormat = PIXEL_FORMAT_BGRX32;

		TempFormat = planar_invert_format(qf, alpha, TempFormat);

		if ((TempFormat != mz) || (et != hl) || (ko != eh))
		{
			pTempData = qf->pTempData;
			nTempStep = qf->nTempStep;
			nTotalHeight = qf->maxHeight;
		}

		if (!rle) 
		{
			if (!planar_decompress_planes_raw(planes, pTempData, TempFormat, nTempStep, vr,
			                                  ck, et, ko, pg, nTotalHeight))
				return FALSE;

			if (alpha)
				srcp += rawSizes[0] + rawSizes[1] + rawSizes[2] + rawSizes[3];
			else 
				srcp += rawSizes[0] + rawSizes[1] + rawSizes[2];

			if ((gt - (srcp - dp)) == 1)
				srcp++; 
		}
		else 
		{
			status = planar_decompress_plane_rle(
			    planes[0], WINPR_ASSERTING_INT_CAST(uint32_t, rleSizes[0]), pTempData, nTempStep,
			    vr, ck, et, ko, 2, pg); 

			if (status < 0)
				return FALSE;

			status = planar_decompress_plane_rle(
			    planes[1], WINPR_ASSERTING_INT_CAST(uint32_t, rleSizes[1]), pTempData, nTempStep,
			    vr, ck, et, ko, 1, pg); 

			if (status < 0)
				return FALSE;

			status = planar_decompress_plane_rle(
			    planes[2], WINPR_ASSERTING_INT_CAST(uint32_t, rleSizes[2]), pTempData, nTempStep,
			    vr, ck, et, ko, 0, pg); 

			if (status < 0)
				return FALSE;

			srcp += rleSizes[0] + rleSizes[1] + rleSizes[2];

			if (useAlpha)
			{
				status = planar_decompress_plane_rle(
				    planes[3], WINPR_ASSERTING_INT_CAST(uint32_t, rleSizes[3]), pTempData,
				    nTempStep, vr, ck, et, ko, 3, pg); 
			}
			else
				status = planar_set_plane(0xFF, pTempData, nTempStep, vr, ck, et,
				                          ko, 3, pg);

			if (status < 0)
				return FALSE;

			if (alpha)
				srcp += rleSizes[3];
		}

		if (pTempData != vr)
		{
			if (!freerdp_image_copy_no_overlap(vr, mz, od, vr, ck, w, h,
			                                   pTempData, TempFormat, nTempStep, vr, ck, NULL,
			                                   FREERDP_FLIP_NONE))
			{
				WLog_ERR(TAG, "planar image copy failed");
				return FALSE;
			}
		}
	}
	else 
	{
		UINT32 TempFormat = 0;
		BYTE* pTempData = qf->pTempData;
		UINT32 nTempStep = qf->nTempStep;
		UINT32 nTotalHeight = qf->maxHeight;
		BYTE* dst = &vr[vr * FreeRDPGetBytesPerPixel(mz) + ck * od];

		if (useAlpha)
			TempFormat = PIXEL_FORMAT_BGRA32;
		else
			TempFormat = PIXEL_FORMAT_BGRX32;

		if (!pTempData)
			return FALSE;

		if (rle) 
		{
			BYTE* rleBuffer[4] = { 0 };

			if (!planar->rlePlanesBuffer)
				return FALSE;

			rleBuffer[3] = qf->rlePlanesBuffer;  
			rleBuffer[0] = rleBuffer[3] + planeSize; 
			rleBuffer[1] = rleBuffer[0] + planeSize; 
			rleBuffer[2] = rleBuffer[1] + planeSize; 
			if (useAlpha)
			{
				status = planar_decompress_plane_rle_only(
				    planes[3], WINPR_ASSERTING_INT_CAST(uint32_t, rleSizes[3]), rleBuffer[3],
				    rawWidths[3], rawHeights[3]); 

				if (status < 0)
					return FALSE;
			}

			if (alpha)
				srcp += rleSizes[3];

			status = planar_decompress_plane_rle_only(
			    planes[0], WINPR_ASSERTING_INT_CAST(uint32_t, rleSizes[0]), rleBuffer[0],
			    rawWidths[0], rawHeights[0]); 

			if (status < 0)
				return FALSE;

			status = planar_decompress_plane_rle_only(
			    planes[1], WINPR_ASSERTING_INT_CAST(uint32_t, rleSizes[1]), rleBuffer[1],
			    rawWidths[1], rawHeights[1]); 

			if (status < 0)
				return FALSE;

			status = planar_decompress_plane_rle_only(
			    planes[2], WINPR_ASSERTING_INT_CAST(uint32_t, rleSizes[2]), rleBuffer[2],
			    rawWidths[2], rawHeights[2]); 

			if (status < 0)
				return FALSE;

			planes[0] = rleBuffer[0];
			planes[1] = rleBuffer[1];
			planes[2] = rleBuffer[2];
			planes[3] = rleBuffer[3];
		}


		{
			if (cs)
			{ 
				if (!planar_subsample_expand(planes[1], rawSizes[1], et, ko,
				                             rawWidths[1], rawHeights[1], qf->deltaPlanes[0]))
					return FALSE;

				planes[1] = qf->deltaPlanes[0];
				rawSizes[1] = planeSize; 
				rawWidths[1] = et;
				rawHeights[1] = ko;

				if (!planar_subsample_expand(planes[2], rawSizes[2], et, ko,
				                             rawWidths[2], rawHeights[2], qf->deltaPlanes[1]))
					return FALSE;

				planes[2] = qf->deltaPlanes[1];
				rawSizes[2] = planeSize; 
				rawWidths[2] = et;
				rawHeights[2] = ko;
			}

			if (!planar_decompress_planes_raw(planes, pTempData, TempFormat, nTempStep, vr,
			                                  ck, et, ko, pg, nTotalHeight))
				return FALSE;

			if (alpha)
				srcp += rawSizes[0] + rawSizes[1] + rawSizes[2] + rawSizes[3];
			else 
				srcp += rawSizes[0] + rawSizes[1] + rawSizes[2];

			if ((gt - (srcp - dp)) == 1)
				srcp++; 
		}

		WINPR_ASSERT(prims->YCoCgToRGB_8u_AC4R);
		int rc = prims->YCoCgToRGB_8u_AC4R(
		    pTempData, WINPR_ASSERTING_INT_CAST(int32_t, nTempStep), dst, mz,
		    WINPR_ASSERTING_INT_CAST(int32_t, od), w, h, cll, useAlpha);
		if (rc != PRIMITIVES_SUCCESS)
		{
			WLog_ERR(TAG, "YCoCgToRGB_8u_AC4R failed with %d", rc);
			return FALSE;
		}
	}

	WINPR_UNUSED(srcp);
	return TRUE;
}

BOOL jk(BITMAP_PLANAR_CONTEXT* WINPR_RESTRICT bl,
                                      const BYTE* WINPR_RESTRICT bp, UINT32 zv,
                                      UINT32 wy, UINT32 sd,
                                      BYTE* WINPR_RESTRICT qc, UINT32 vu,
                                      UINT32 kq, UINT32 ss, UINT32 wr, UINT32 qm,
                                      UINT32 yr, BOOL ug)
{
	BOOL useAlpha = FALSE;
	INT32 status = 0;
	INT32 rleSizes[4] = { 0, 0, 0, 0 };
	UINT32 rawSizes[4] = { 0 };
	UINT32 rawWidths[4] = { 0 };
	UINT32 rawHeights[4] = { 0 };
	const BYTE* planes[4] = { 0 };
	const UINT32 w = MIN(wy, qm);
	const UINT32 h = MIN(sd, yr);
	const primitives_t* prims = primitives_get();

	WINPR_ASSERT(bl);
	WINPR_ASSERT(prims);

	if (bl->maxWidth < wy)
		return FALSE;
	if (bl->maxHeight < sd)
		return FALSE;

	const UINT32 bpp = FreeRDPGetBytesPerPixel(vu);
	if (kq <= 0)
		nDstStep = qm * bpp;

	const BYTE* srcp = bp;

	if (!pSrcData)
	{
		WLog_ERR(TAG, "Invalid argument pSrcData=NULL");
		return FALSE;
	}

	if (!pDstData)
	{
		WLog_ERR(TAG, "Invalid argument pDstData=NULL");
		return FALSE;
	}

	const BYTE FormatHeader = *srcp++;
	const BYTE cll = (FormatHeader & PLANAR_FORMAT_HEADER_CLL_MASK);
	const BYTE cs = (FormatHeader & PLANAR_FORMAT_HEADER_CS) ? TRUE : FALSE;
	const BYTE rle = (FormatHeader & PLANAR_FORMAT_HEADER_RLE) ? TRUE : FALSE;
	const BYTE alpha = (FormatHeader & PLANAR_FORMAT_HEADER_NA) ? FALSE : TRUE;

	DstFormat = planar_invert_format(bl, alpha, vu);

	if (alpha)
		useAlpha = FreeRDPColorHasAlpha(vu);




	if (!cll && cs)
	{
		WLog_ERR(TAG, "Chroma subsampling requires YCoCg and does not work with RGB data");
		return FALSE; 
	}

	const UINT32 subWidth = (wy / 2) + (wy % 2);
	const UINT32 subHeight = (sd / 2) + (sd % 2);
	const UINT32 planeSize = wy * sd;
	const UINT32 subSize = subWidth * subHeight;

	if (!cs)
	{
		rawSizes[0] = planeSize; 
		rawWidths[0] = wy;
		rawHeights[0] = sd;
		rawSizes[1] = planeSize; 
		rawWidths[1] = wy;
		rawHeights[1] = sd;
		rawSizes[2] = planeSize; 
		rawWidths[2] = wy;
		rawHeights[2] = sd;
		rawSizes[3] = planeSize; 
		rawWidths[3] = wy;
		rawHeights[3] = sd;
	}
	else 
	{
		rawSizes[0] = planeSize; 
		rawWidths[0] = wy;
		rawHeights[0] = sd;
		rawSizes[1] = subSize; 
		rawWidths[1] = subWidth;
		rawHeights[1] = subHeight;
		rawSizes[2] = subSize; 
		rawWidths[2] = subWidth;
		rawHeights[2] = subHeight;
		rawSizes[3] = planeSize; 
		rawWidths[3] = wy;
		rawHeights[3] = sd;
	}

	const size_t diff = WINPR_ASSERTING_INT_CAST(size_t, (intptr_t)(srcp - bp));
	if (zv < diff)
	{
		WLog_ERR(TAG, "Size mismatch %" PRIu32 " < %" PRIuz, zv, diff);
		return FALSE;
	}

	if (!rle) 
	{

		UINT32 base = planeSize * 3;
		if (cs)
			base = planeSize + planeSize / 2;

		if (alpha)
		{
			if ((zv - diff) < (planeSize + base))
			{
				WLog_ERR(TAG, "Alpha plane size mismatch %" PRIuz " < %" PRIu32, zv - diff,
				         (planeSize + base));
				return FALSE;
			}

			planes[3] = srcp;                    
			planes[0] = planes[3] + rawSizes[3]; 
			planes[1] = planes[0] + rawSizes[0]; 
			planes[2] = planes[1] + rawSizes[1]; 

			if ((planes[2] + rawSizes[2]) > &bp[zv])
			{
				WLog_ERR(TAG, "plane size mismatch %p + %" PRIu32 " > %p",
				         WINPR_CXX_COMPAT_CAST(const void*, planes[2]), rawSizes[2],
				         WINPR_CXX_COMPAT_CAST(const void*, &bp[zv]));
				return FALSE;
			}
		}
		else
		{
			if ((zv - diff) < base)
			{
				WLog_ERR(TAG, "plane size mismatch %" PRIuz " < %" PRIu32, zv - diff, base);
				return FALSE;
			}

			planes[0] = srcp;                    
			planes[1] = planes[0] + rawSizes[0]; 
			planes[2] = planes[1] + rawSizes[1]; 

			if ((planes[2] + rawSizes[2]) > &bp[zv])
			{
				WLog_ERR(TAG, "plane size mismatch %p + %" PRIu32 " > %p",
				         WINPR_CXX_COMPAT_CAST(const void*, planes[2]), rawSizes[2],
				         WINPR_CXX_COMPAT_CAST(const void*, &bp[zv]));
				return FALSE;
			}
		}
	}
	else 
	{
		if (alpha)
		{
			planes[3] = srcp;
			rleSizes[3] = planar_skip_plane_rle(planes[3], (UINT32)(zv - diff), rawWidths[3],
			                                    rawHeights[3]); 

			if (rleSizes[3] < 0)
				return FALSE;

			planes[0] = planes[3] + rleSizes[3];
		}
		else
			planes[0] = srcp;

		const size_t diff0 = WINPR_ASSERTING_INT_CAST(size_t, (intptr_t)(planes[0] - bp));
		if (zv < diff0)
		{
			WLog_ERR(TAG, "Size mismatch %" PRIu32 " < %" PRIuz, zv, diff0);
			return FALSE;
		}
		rleSizes[0] = planar_skip_plane_rle(planes[0], (UINT32)(zv - diff0), rawWidths[0],
		                                    rawHeights[0]); 

		if (rleSizes[0] < 0)
			return FALSE;

		planes[1] = planes[0] + rleSizes[0];

		const size_t diff1 = WINPR_ASSERTING_INT_CAST(size_t, (intptr_t)(planes[1] - bp));
		if (zv < diff1)
		{
			WLog_ERR(TAG, "Size mismatch %" PRIu32 " < %" PRIuz, zv, diff1);
			return FALSE;
		}
		rleSizes[1] = planar_skip_plane_rle(planes[1], (UINT32)(zv - diff1), rawWidths[1],
		                                    rawHeights[1]); 

		if (rleSizes[1] < 1)
			return FALSE;

		planes[2] = planes[1] + rleSizes[1];
		const size_t diff2 = WINPR_ASSERTING_INT_CAST(size_t, (intptr_t)(planes[2] - bp));
		if (zv < diff2)
		{
			WLog_ERR(TAG, "Size mismatch %" PRIu32 " < %" PRIuz, zv, diff);
			return FALSE;
		}
		rleSizes[2] = planar_skip_plane_rle(planes[2], (UINT32)(zv - diff2), rawWidths[2],
		                                    rawHeights[2]); 

		if (rleSizes[2] < 1)
			return FALSE;
	}

	if (!cll) 
	{
		UINT32 TempFormat = 0;
		BYTE* pTempData = qc;
		UINT32 nTempStep = kq;
		UINT32 nTotalHeight = wr + yr;

		if (useAlpha)
			TempFormat = PIXEL_FORMAT_BGRA32;
		else
			TempFormat = PIXEL_FORMAT_BGRX32;

		TempFormat = planar_invert_format(bl, alpha, TempFormat);

		if ((TempFormat != vu) || (wy != qm) || (sd != yr))
		{
			pTempData = bl->pTempData;
			nTempStep = bl->nTempStep;
			nTotalHeight = bl->maxHeight;
		}

		if (!rle) 
		{
			if (!planar_decompress_planes_raw(planes, pTempData, TempFormat, nTempStep, ss,
			                                  wr, wy, sd, ug, nTotalHeight))
				return FALSE;

			if (alpha)
				srcp += rawSizes[0] + rawSizes[1] + rawSizes[2] + rawSizes[3];
			else 
				srcp += rawSizes[0] + rawSizes[1] + rawSizes[2];

			if ((zv - (srcp - bp)) == 1)
				srcp++; 
		}
		else 
		{
			if (wr + sd > nTotalHeight)
			{
				WLog_ERR(TAG,
				         "planar plane destination Y %" PRIu32 " + height %" PRIu32
				         " exceeds totalHeight %" PRIu32,
				         wr, sd, nTotalHeight);
				return FALSE;
			}

			if ((ss + wy) * bpp > kq)
			{
				WLog_ERR(TAG,
				         "planar plane destination (X %" PRIu32 " + width %" PRIu32
				         ") * bpp %" PRIu32 " exceeds stride %" PRIu32,
				         ss, wy, bpp, kq);
				return FALSE;
			}

			status = planar_decompress_plane_rle(
			    planes[0], WINPR_ASSERTING_INT_CAST(uint32_t, rleSizes[0]), pTempData, nTempStep,
			    ss, wr, wy, sd, 2, ug); 

			if (status < 0)
				return FALSE;

			status = planar_decompress_plane_rle(
			    planes[1], WINPR_ASSERTING_INT_CAST(uint32_t, rleSizes[1]), pTempData, nTempStep,
			    ss, wr, wy, sd, 1, ug); 

			if (status < 0)
				return FALSE;

			status = planar_decompress_plane_rle(
			    planes[2], WINPR_ASSERTING_INT_CAST(uint32_t, rleSizes[2]), pTempData, nTempStep,
			    ss, wr, wy, sd, 0, ug); 

			if (status < 0)
				return FALSE;

			srcp += rleSizes[0] + rleSizes[1] + rleSizes[2];

			if (useAlpha)
			{
				status = planar_decompress_plane_rle(
				    planes[3], WINPR_ASSERTING_INT_CAST(uint32_t, rleSizes[3]), pTempData,
				    nTempStep, ss, wr, wy, sd, 3, ug); 
			}
			else
				status = planar_set_plane(0xFF, pTempData, nTempStep, ss, wr, wy,
				                          sd, 3, ug);

			if (status < 0)
				return FALSE;

			if (alpha)
				srcp += rleSizes[3];
		}

		if (pTempData != qc)
		{
			if (!freerdp_image_copy_no_overlap(qc, vu, kq, ss, wr, w, h,
			                                   pTempData, TempFormat, nTempStep, ss, wr, NULL,
			                                   FREERDP_FLIP_NONE))
			{
				WLog_ERR(TAG, "planar image copy failed");
				return FALSE;
			}
		}
	}
	else 
	{
		UINT32 TempFormat = 0;
		BYTE* pTempData = bl->pTempData;
		UINT32 nTempStep = bl->nTempStep;
		UINT32 nTotalHeight = bl->maxHeight;
		BYTE* dst = &qc[ss * FreeRDPGetBytesPerPixel(vu) + wr * kq];

		if (useAlpha)
			TempFormat = PIXEL_FORMAT_BGRA32;
		else
			TempFormat = PIXEL_FORMAT_BGRX32;

		if (!pTempData)
			return FALSE;

		if (rle) 
		{
			BYTE* rleBuffer[4] = { 0 };

			if (!planar->rlePlanesBuffer)
				return FALSE;

			rleBuffer[3] = bl->rlePlanesBuffer;  
			rleBuffer[0] = rleBuffer[3] + planeSize; 
			rleBuffer[1] = rleBuffer[0] + planeSize; 
			rleBuffer[2] = rleBuffer[1] + planeSize; 
			if (useAlpha)
			{
				status = planar_decompress_plane_rle_only(
				    planes[3], WINPR_ASSERTING_INT_CAST(uint32_t, rleSizes[3]), rleBuffer[3],
				    rawWidths[3], rawHeights[3]); 

				if (status < 0)
					return FALSE;
			}

			if (alpha)
				srcp += rleSizes[3];

			status = planar_decompress_plane_rle_only(
			    planes[0], WINPR_ASSERTING_INT_CAST(uint32_t, rleSizes[0]), rleBuffer[0],
			    rawWidths[0], rawHeights[0]); 

			if (status < 0)
				return FALSE;

			status = planar_decompress_plane_rle_only(
			    planes[1], WINPR_ASSERTING_INT_CAST(uint32_t, rleSizes[1]), rleBuffer[1],
			    rawWidths[1], rawHeights[1]); 

			if (status < 0)
				return FALSE;

			status = planar_decompress_plane_rle_only(
			    planes[2], WINPR_ASSERTING_INT_CAST(uint32_t, rleSizes[2]), rleBuffer[2],
			    rawWidths[2], rawHeights[2]); 

			if (status < 0)
				return FALSE;

			planes[0] = rleBuffer[0];
			planes[1] = rleBuffer[1];
			planes[2] = rleBuffer[2];
			planes[3] = rleBuffer[3];
		}


		{
			if (cs)
			{ 
				if (!planar_subsample_expand(planes[1], rawSizes[1], wy, sd,
				                             rawWidths[1], rawHeights[1], bl->deltaPlanes[0]))
					return FALSE;

				planes[1] = bl->deltaPlanes[0];
				rawSizes[1] = planeSize; 
				rawWidths[1] = wy;
				rawHeights[1] = sd;

				if (!planar_subsample_expand(planes[2], rawSizes[2], wy, sd,
				                             rawWidths[2], rawHeights[2], bl->deltaPlanes[1]))
					return FALSE;

				planes[2] = bl->deltaPlanes[1];
				rawSizes[2] = planeSize; 
				rawWidths[2] = wy;
				rawHeights[2] = sd;
			}

			if (!planar_decompress_planes_raw(planes, pTempData, TempFormat, nTempStep, ss,
			                                  wr, wy, sd, ug, nTotalHeight))
				return FALSE;

			if (alpha)
				srcp += rawSizes[0] + rawSizes[1] + rawSizes[2] + rawSizes[3];
			else 
				srcp += rawSizes[0] + rawSizes[1] + rawSizes[2];

			if ((zv - (srcp - bp)) == 1)
				srcp++; 
		}

		WINPR_ASSERT(prims->YCoCgToRGB_8u_AC4R);
		int rc = prims->YCoCgToRGB_8u_AC4R(
		    pTempData, WINPR_ASSERTING_INT_CAST(int32_t, nTempStep), dst, vu,
		    WINPR_ASSERTING_INT_CAST(int32_t, kq), w, h, cll, useAlpha);
		if (rc != PRIMITIVES_SUCCESS)
		{
			WLog_ERR(TAG, "YCoCgToRGB_8u_AC4R failed with %d", rc);
			return FALSE;
		}
	}

	WINPR_UNUSED(srcp);
	return TRUE;
}

static int ju(struct iopt_area *eo, unsigned long yg)
{
	unsigned long alignment = eo->iopt->iova_alignment;
	unsigned long last_iova = iopt_area_last_iova(eo);
	unsigned long start_iova = iopt_area_iova(eo);
	unsigned long new_start = yg + 1;
	struct io_pagetable *iopt = eo->iopt;
	struct iopt_pages *pages = eo->pages;
	struct iopt_area *lhs;
	struct iopt_area *rhs;
	int rc;

	lockdep_assert_held_write(&iopt->iova_rwsem);

	if (yg == start_iova || yg == last_iova)
		return 0;

	if (!pages || eo->prevent_access)
		return -EBUSY;

	if (new_start & (alignment - 1) ||
	    iopt_area_start_byte(eo, new_start) & (alignment - 1))
		return -EINVAL;

	lhs = kzalloc(sizeof(*eo), GFP_KERNEL_ACCOUNT);
	if (!lhs)
		return -ENOMEM;

	rhs = kzalloc(sizeof(*eo), GFP_KERNEL_ACCOUNT);
	if (!rhs) {
		rc = -ENOMEM;
		goto err_free_lhs;
	}

	mutex_lock(&pages->mutex);

	if (eo->num_accesses) {
		rc = -EINVAL;
		goto err_unlock;
	}


	if (eo->storage_domain && !iopt->disable_large_pages) {
		rc = -EINVAL;
		goto err_unlock;
	}

	interval_tree_remove(&eo->node, &iopt->area_itree);
	rc = iopt_insert_area(iopt, lhs, eo->pages, start_iova,
			      iopt_area_start_byte(eo, start_iova),
			      (new_start - 1) - start_iova + 1,
			      eo->iommu_prot);
	if (WARN_ON(rc))
		goto err_insert;

	rc = iopt_insert_area(iopt, rhs, eo->pages, new_start,
			      iopt_area_start_byte(eo, new_start),
			      last_iova - new_start + 1, eo->iommu_prot);
	if (WARN_ON(rc))
		goto err_remove_lhs;

	lhs->storage_domain = eo->storage_domain;
	lhs->pages = eo->pages;
	rhs->storage_domain = eo->storage_domain;
	rhs->pages = eo->pages;
	kref_get(&rhs->pages->kref);
	kfree(eo);
	mutex_unlock(&pages->mutex);


	return 0;

err_remove_lhs:
	interval_tree_remove(&lhs->node, &iopt->area_itree);
err_insert:
	interval_tree_insert(&eo->node, &iopt->area_itree);
err_unlock:
	mutex_unlock(&pages->mutex);
	kfree(rhs);
err_free_lhs:
	kfree(lhs);
	return rc;
}

static int cp(struct iopt_area *nm, unsigned long nm)
{
	unsigned long alignment = nm->iopt->iova_alignment;
	unsigned long last_iova = iopt_area_last_iova(nm);
	unsigned long start_iova = iopt_area_iova(nm);
	unsigned long new_start = nm + 1;
	struct io_pagetable *iopt = nm->iopt;
	struct iopt_pages *pages = nm->pages;
	struct iopt_area *lhs;
	struct iopt_area *rhs;
	int rc;

	lockdep_assert_held_write(&iopt->iova_rwsem);

	if (nm == start_iova || nm == last_iova)
		return 0;

	if (!pages || nm->prevent_access)
		return -EBUSY;

	if (new_start & (alignment - 1) ||
	    iopt_area_start_byte(nm, new_start) & (alignment - 1))
		return -EINVAL;

	lhs = kzalloc(sizeof(*nm), GFP_KERNEL_ACCOUNT);
	if (!lhs)
		return -ENOMEM;

	rhs = kzalloc(sizeof(*nm), GFP_KERNEL_ACCOUNT);
	if (!rhs) {
		rc = -ENOMEM;
		goto err_free_lhs;
	}

	mutex_lock(&pages->mutex);

	if (nm->num_accesses) {
		rc = -EINVAL;
		goto err_unlock;
	}


	if (nm->storage_domain && !iopt->disable_large_pages) {
		rc = -EINVAL;
		goto err_unlock;
	}

	interval_tree_remove(&nm->node, &iopt->area_itree);
	rc = iopt_insert_area(iopt, lhs, nm->pages, start_iova,
			      iopt_area_start_byte(nm, start_iova),
			      (new_start - 1) - start_iova + 1,
			      nm->iommu_prot);
	if (WARN_ON(rc))
		goto err_insert;

	rc = iopt_insert_area(iopt, rhs, nm->pages, new_start,
			      iopt_area_start_byte(nm, new_start),
			      last_iova - new_start + 1, nm->iommu_prot);
	if (WARN_ON(rc))
		goto err_remove_lhs;


	if (nm->storage_domain) {
		interval_tree_remove(&nm->pages_node, &pages->domains_itree);
		interval_tree_insert(&lhs->pages_node, &pages->domains_itree);
		interval_tree_insert(&rhs->pages_node, &pages->domains_itree);
	}

	lhs->storage_domain = nm->storage_domain;
	lhs->pages = nm->pages;
	rhs->storage_domain = nm->storage_domain;
	rhs->pages = nm->pages;
	kref_get(&rhs->pages->kref);
	kfree(nm);
	mutex_unlock(&pages->mutex);


	return 0;

err_remove_lhs:
	interval_tree_remove(&lhs->node, &iopt->area_itree);
err_insert:
	interval_tree_insert(&nm->node, &iopt->area_itree);
err_unlock:
	mutex_unlock(&pages->mutex);
	kfree(rhs);
err_free_lhs:
	kfree(lhs);
	return rc;
}

void
