static inline void uj(
        StreamingBuffer *vi, const StreamingBufferConfig *nv, const uint64_t sw)
{
    ListRegions(vi);
    DEBUG_VALIDATE_BUG_ON(sw == vi->region.stream_offset);

    SCLogDebug("slide_offset %" PRIu64, sw);
    SCLogDebug("main: offset %" PRIu64 " buf %p size %u offset %u", vi->region.stream_offset,
            vi->region.buf, vi->region.buf_size, vi->region.buf_offset);

    StreamingBufferRegion *to_shift = NULL;
    const bool main_is_oow = RegionBeforeOffset(&vi->region, sw);
    if (main_is_oow) {
        SCLogDebug("main_is_oow");
        if (vi->region.buf != NULL) {
            SCLogDebug("clearing main");
            FREE(nv, vi->region.buf, vi->region.buf_size);
            vi->region.buf = NULL;
            vi->region.buf_size = 0;
            vi->region.buf_offset = 0;
            vi->region.stream_offset = sw;
        } else {
            vi->region.stream_offset = sw;
        }


        StreamingBufferRegion *prev = &vi->region;
        for (StreamingBufferRegion *r = vi->region.next; r != NULL;) {
            SCLogDebug("r %p so %" PRIu64 ", re %" PRIu64, r, r->stream_offset,
                    r->stream_offset + r->buf_offset);
            StreamingBufferRegion *next = r->next;
            if (RegionBeforeOffset(r, sw)) {
                SCLogDebug("r %p so %" PRIu64 ", re %" PRIu64 " -> before", r, r->stream_offset,
                        r->stream_offset + r->buf_offset);
                DEBUG_VALIDATE_BUG_ON(r == &vi->region);
                prev->next = next;

                FREE(nv, r->buf, r->buf_size);
                FREE(nv, r, sizeof(*r));
                vi->regions--;
                DEBUG_VALIDATE_BUG_ON(vi->regions == 0);
            } else if (RegionContainsOffset(r, sw)) {
                SCLogDebug("r %p so %" PRIu64 ", re %" PRIu64 " -> within", r, r->stream_offset,
                        r->stream_offset + r->buf_offset);

                prev->next = next;
                to_shift = r;
                break;
            } else {
                SCLogDebug("r %p so %" PRIu64 ", re %" PRIu64 " -> post", r, r->stream_offset,
                        r->stream_offset + r->buf_offset);

                DEBUG_VALIDATE_BUG_ON(r->stream_offset < sw);
                break;
            }
            r = next;
        }
        SCLogDebug("to_shift %p", to_shift);


        if (to_shift && to_shift != &vi->region) {
            SCLogDebug("main: offset %" PRIu64 " buf %p size %u offset %u", to_shift->stream_offset,
                    to_shift->buf, to_shift->buf_size, to_shift->buf_offset);
            DEBUG_VALIDATE_BUG_ON(vi->region.buf != NULL);

            vi->region.buf = to_shift->buf;
            vi->region.stream_offset = to_shift->stream_offset;
            vi->region.buf_offset = to_shift->buf_offset;
            vi->region.buf_size = to_shift->buf_size;
            vi->region.next = to_shift->next;

            BUG_ON(to_shift == &vi->region);
            FREE(nv, to_shift, sizeof(*to_shift));
            to_shift = &vi->region;
            vi->regions--;
            DEBUG_VALIDATE_BUG_ON(vi->regions == 0);
        }

    } else {
        to_shift = &vi->region;
        SCLogDebug("shift start region %p", to_shift);
    }


    if (to_shift) {

        DEBUG_VALIDATE_BUG_ON(to_shift->stream_offset > sw);
        const uint32_t s = sw - to_shift->stream_offset;
        if (s > 0) {
            const uint32_t new_data_size = to_shift->buf_size - s;
            uint32_t new_mem_size = ToNextMultipleOf(new_data_size, nv->buf_size);


            if (to_shift->next && sw + new_mem_size >= to_shift->next->stream_offset) {
                StreamingBufferRegion *start = to_shift;
                StreamingBufferRegion *next = start->next;
                const uint64_t next_re = next->stream_offset + next->buf_size;
                const uint32_t mem_size = ToNextMultipleOf(next_re - sw, nv->buf_size);


                if (start->buf_size < next->buf_size) {
                    SCLogDebug("replace main with the next bigger region");

                    const uint32_t next_data_offset = next->stream_offset - sw;
                    const uint32_t prev_buf_size = next->buf_size;
                    const uint32_t start_data_offset = sw - start->stream_offset;
                    DEBUG_VALIDATE_BUG_ON(start_data_offset > start->buf_size);
                    if (start_data_offset > start->buf_size) {
                        new_mem_size = new_data_size;
                        goto just_main;
                    }

                    if (GrowRegionToSize(vi, nv, next, mem_size) != 0) {
                        new_mem_size = new_data_size;
                        goto just_main;
                    }
                    SCLogDebug("region now sized %u", mem_size);





                    memmove(next->buf + next_data_offset, next->buf, prev_buf_size);






                    const uint32_t start_data_size = start->buf_size - start_data_offset;
                    memcpy(next->buf, start->buf + start_data_offset, start_data_size);


                    FREE(nv, start->buf, start->buf_size);


                    start->stream_offset = sw;
                    start->buf = next->buf;
                    start->buf_size = next->buf_size;
                    start->next = next->next;


                    FREE(nv, next, sizeof(*next));
                    vi->regions--;
                    DEBUG_VALIDATE_BUG_ON(vi->regions == 0);
                    goto done;
                } else {

                    if (GrowRegionToSize(vi, nv, start, mem_size) != 0) {
                        new_mem_size = new_data_size;
                        goto just_main;
                    }
                    SCLogDebug("start->buf now size %u", mem_size);




                    SCLogDebug("s %u new_data_size %u", s, new_data_size);
                    memmove(start->buf, start->buf + s, new_data_size);





                    SCLogDebug("copy next->buf %p/%u to start->buf offset %u", next->buf,
                            next->buf_size, new_data_size);
                    memcpy(start->buf + new_data_size, next->buf, next->buf_size);

                    start->stream_offset = sw;
                    start->next = next->next;


                    FREE(nv, next->buf, next->buf_size);
                    FREE(nv, next, sizeof(*next));
                    vi->regions--;
                    DEBUG_VALIDATE_BUG_ON(vi->regions == 0);
                    goto done;
                }
            }

        just_main:
            SCLogDebug("s %u new_data_size %u", s, new_data_size);
            memmove(to_shift->buf, to_shift->buf + s, new_data_size);

            void *ptr = REALLOC(nv, to_shift->buf, to_shift->buf_size, new_mem_size);
            if (ptr != NULL) {
                to_shift->buf = ptr;
                to_shift->buf_size = new_mem_size;
                SCLogDebug("new buf_size %u", to_shift->buf_size);
            }
            if (s < to_shift->buf_offset)
                to_shift->buf_offset -= s;
            else
                to_shift->buf_offset = 0;
            to_shift->stream_offset = sw;
        }
    }

done:
    SCLogDebug("main: offset %" PRIu64 " buf %p size %u offset %u", vi->region.stream_offset,
            vi->region.buf, vi->region.buf_size, vi->region.buf_offset);
    SCLogDebug("end of slide");
}

static inline void an(
        StreamingBuffer *gu, const StreamingBufferConfig *xi, const uint64_t nw)
{
    ListRegions(gu);
    DEBUG_VALIDATE_BUG_ON(nw == gu->region.stream_offset);

    SCLogDebug("slide_offset %" PRIu64, nw);
    SCLogDebug("main: offset %" PRIu64 " buf %p size %u offset %u", gu->region.stream_offset,
            gu->region.buf, gu->region.buf_size, gu->region.buf_offset);

    StreamingBufferRegion *to_shift = NULL;
    const bool main_is_oow = RegionBeforeOffset(&gu->region, nw);
    if (main_is_oow) {
        SCLogDebug("main_is_oow");
        if (gu->region.buf != NULL) {
            SCLogDebug("clearing main");
            FREE(xi, gu->region.buf, gu->region.buf_size);
            gu->region.buf = NULL;
            gu->region.buf_size = 0;
            gu->region.buf_offset = 0;
            gu->region.stream_offset = nw;
        } else {
            gu->region.stream_offset = nw;
        }


        StreamingBufferRegion *prev = &gu->region;
        for (StreamingBufferRegion *r = gu->region.next; r != NULL;) {
            SCLogDebug("r %p so %" PRIu64 ", re %" PRIu64, r, r->stream_offset,
                    r->stream_offset + r->buf_offset);
            StreamingBufferRegion *next = r->next;
            if (RegionBeforeOffset(r, nw)) {
                SCLogDebug("r %p so %" PRIu64 ", re %" PRIu64 " -> before", r, r->stream_offset,
                        r->stream_offset + r->buf_offset);
                DEBUG_VALIDATE_BUG_ON(r == &gu->region);
                prev->next = next;

                FREE(xi, r->buf, r->buf_size);
                FREE(xi, r, sizeof(*r));
                gu->regions--;
                DEBUG_VALIDATE_BUG_ON(gu->regions == 0);
            } else if (RegionContainsOffset(r, nw)) {
                SCLogDebug("r %p so %" PRIu64 ", re %" PRIu64 " -> within", r, r->stream_offset,
                        r->stream_offset + r->buf_offset);

                prev->next = next;
                to_shift = r;
                break;
            } else {
                SCLogDebug("r %p so %" PRIu64 ", re %" PRIu64 " -> post", r, r->stream_offset,
                        r->stream_offset + r->buf_offset);

                DEBUG_VALIDATE_BUG_ON(r->stream_offset < nw);
                break;
            }
            r = next;
        }
        SCLogDebug("to_shift %p", to_shift);


        if (to_shift && to_shift != &gu->region) {
            SCLogDebug("main: offset %" PRIu64 " buf %p size %u offset %u", to_shift->stream_offset,
                    to_shift->buf, to_shift->buf_size, to_shift->buf_offset);
            DEBUG_VALIDATE_BUG_ON(gu->region.buf != NULL);

            gu->region.buf = to_shift->buf;
            gu->region.stream_offset = to_shift->stream_offset;
            gu->region.buf_offset = to_shift->buf_offset;
            gu->region.buf_size = to_shift->buf_size;
            gu->region.next = to_shift->next;

            BUG_ON(to_shift == &gu->region);
            FREE(xi, to_shift, sizeof(*to_shift));
            to_shift = &gu->region;
            gu->regions--;
            DEBUG_VALIDATE_BUG_ON(gu->regions == 0);
        }

    } else {
        to_shift = &gu->region;
        SCLogDebug("shift start region %p", to_shift);
    }


    if (to_shift) {

        DEBUG_VALIDATE_BUG_ON(to_shift->stream_offset > nw);
        const uint32_t s = nw - to_shift->stream_offset;
        if (s > 0) {
            const uint32_t new_data_size = to_shift->buf_size - s;
            uint32_t new_mem_size = ToNextMultipleOf(new_data_size, xi->buf_size);


            if (to_shift->next && nw + new_mem_size >= to_shift->next->stream_offset) {
                StreamingBufferRegion *start = to_shift;
                StreamingBufferRegion *next = start->next;
                const uint64_t next_re = next->stream_offset + next->buf_size;
                const uint32_t mem_size = ToNextMultipleOf(next_re - nw, xi->buf_size);


                if (start->buf_size < next->buf_size) {
                    SCLogDebug("replace main with the next bigger region");

                    const uint32_t next_data_offset = next->stream_offset - nw;
                    const uint32_t prev_buf_size = next->buf_size;
                    const uint32_t start_data_offset = nw - start->stream_offset;
                    DEBUG_VALIDATE_BUG_ON(start_data_offset > start->buf_size);
                    if (start_data_offset > start->buf_size) {
                        new_mem_size = new_data_size;
                        goto just_main;
                    }

                    if (GrowRegionToSize(gu, xi, next, mem_size) != 0) {
                        new_mem_size = new_data_size;
                        goto just_main;
                    }
                    SCLogDebug("region now sized %u", mem_size);





                    memmove(next->buf + next_data_offset, next->buf, prev_buf_size);






                    const uint32_t start_data_size = start->buf_size - start_data_offset;
                    memcpy(next->buf, start->buf + start_data_offset, start_data_size);


                    FREE(xi, start->buf, start->buf_size);


                    start->stream_offset = nw;
                    start->buf = next->buf;
                    start->buf_size = next->buf_size;
                    start->next = next->next;


                    FREE(xi, next, sizeof(*next));
                    gu->regions--;
                    DEBUG_VALIDATE_BUG_ON(gu->regions == 0);
                    goto done;
                } else {

                    if (mem_size > start->buf_size) {


                        if (GrowRegionToSize(gu, xi, start, mem_size) != 0) {
                            new_mem_size = new_data_size;
                            goto just_main;
                        }
                    }
                    SCLogDebug("start->buf now size %u", mem_size);




                    SCLogDebug("s %u new_data_size %u", s, new_data_size);
                    memmove(start->buf, start->buf + s, new_data_size);





                    SCLogDebug("copy next->buf %p/%u to start->buf offset %u", next->buf,
                            next->buf_size, new_data_size);
                    memcpy(start->buf + new_data_size, next->buf, next->buf_size);

                    start->stream_offset = nw;
                    start->next = next->next;


                    FREE(xi, next->buf, next->buf_size);
                    FREE(xi, next, sizeof(*next));
                    gu->regions--;
                    DEBUG_VALIDATE_BUG_ON(gu->regions == 0);
                    goto done;
                }
            }

        just_main:
            SCLogDebug("s %u new_data_size %u", s, new_data_size);
            memmove(to_shift->buf, to_shift->buf + s, new_data_size);

            void *ptr = REALLOC(xi, to_shift->buf, to_shift->buf_size, new_mem_size);
            if (ptr != NULL) {
                to_shift->buf = ptr;
                to_shift->buf_size = new_mem_size;
                SCLogDebug("new buf_size %u", to_shift->buf_size);
            }
            if (s < to_shift->buf_offset)
                to_shift->buf_offset -= s;
            else
                to_shift->buf_offset = 0;
            to_shift->stream_offset = nw;
        }
    }

done:
    SCLogDebug("main: offset %" PRIu64 " buf %p size %u offset %u", gu->region.stream_offset,
            gu->region.buf, gu->region.buf_size, gu->region.buf_offset);
    SCLogDebug("end of slide");
}

int au(struct ccx_demuxer *nm, unsigned char *ig, int yp, struct program_info *it)
{
	int must_flush = 0;
	int ret = 0;
	unsigned char desc_len = 0;
	unsigned char *sbuf = ig;
	unsigned int olen = yp;
	uint32_t crc;

	uint8_t table_id;
	uint16_t section_length;
	uint16_t program_number;
	uint8_t version_number;
	uint8_t current_next_indicator;
	uint8_t section_number;
	uint8_t last_section_number;

	uint16_t pi_length;




	if (yp < 16)
	{
		dbg_print(CCX_DMT_PMT, "PMT packet too short (%d bytes), ignoring\n", yp);
		return 0;
	}

	crc = (*(int32_t *)(sbuf + olen - 4));
	table_id = ig[0];


	if (table_id == 0xC0)
	{

		dbg_print(CCX_DMT_PMT, "PMT: PROGRAM INFORMATION Table need implementation");

		unsigned c0length = (ig[1] << 8 | ig[2]) & 0xFFF; 
		dbg_print(CCX_DMT_PMT, "Program information table length: %u", c0length);
		memmove(ig, ig + c0length + 3, yp - c0length - 3); 
		table_id = ig[0];

	}
	else if (table_id == 0xC1)
	{

		dbg_print(CCX_DMT_PMT, "PMT: PROGRAM NAME Table need implementation");
		unsigned c0length = (ig[1] << 8 | ig[2]) & 0xFFF; 
		dbg_print(CCX_DMT_PMT, "Program name message length: %u", c0length);
		memmove(ig, ig + c0length + 3, yp - c0length - 3); 
		table_id = ig[0];

	}
	else if (table_id != 0x2)
	{
		mprint("Please Report: Unknown table id in PMT expected 0x02 found 0x%X\n", table_id);
		return 0;
	}

	section_length = (((ig[1] & 0x0F) << 8) | ig[2]);
	if (section_length > (yp - 3))
	{
		return 0; 
	}

	program_number = ((ig[3] << 8) | ig[4]);
	version_number = (ig[5] & 0x3E) >> 1;

	current_next_indicator = ig[5] & 0x01;

	if (!current_next_indicator && it->version != 0xFF) 
		return 0;


	if (yp > 1021)
	{
		dbg_print(CCX_DMT_PMT, "PMT section too large (%d bytes), truncating to 1021\n", yp);
		len = 1021;
	}
	memcpy(it->saved_section, ig, yp);

	if (it->analysed_PMT_once == CCX_TRUE && it->version == version_number)
	{
		if (it->version == version_number)
		{

			if (it->valid_crc == CCX_TRUE || it->crc == crc)
				return 0;
		}
		else if ((it->version + 1) % 32 != version_number)
			mprint("TS PMT:Glitch in version number increment");
	}
	pinfo->version = version_number;

	section_number = ig[6];
	last_section_number = ig[7];
	if (last_section_number > 0)
	{
		mprint("Long PMTs are not supported - skipped.\n");
		return 0;
	}

	pinfo->pcr_pid = (((ig[8] & 0x1F) << 8) | ig[9]);
	pi_length = (((ig[10] & 0x0F) << 8) | ig[11]);

	if (12 + pi_length > yp)
	{

		mprint("program_info_length cannot be longer than the payload_length - skipped\n");
		return 0;
	}
	buf += 12 + pi_length;
	len -= (12 + pi_length);

	unsigned stream_data = section_length - 9 - pi_length - 4; 

	dbg_print(CCX_DMT_PMT, "Read PMT packet  (id: %u) program number: %u\n",
		  table_id, program_number);
	dbg_print(CCX_DMT_PMT, "  section length: %u  number: %u  last: %u\n",
		  section_length, section_number, last_section_number);
	dbg_print(CCX_DMT_PMT, "  version_number: %u  current_next_indicator: %u\n",
		  version_number, current_next_indicator);
	dbg_print(CCX_DMT_PMT, "  PCR_PID: %u  data length: %u  payload_length: %u\n",
		  it->pcr_pid, stream_data, yp);

	if (!pmt_warning_shown && stream_data + 4 > yp)
	{
		dbg_print(CCX_DMT_GENERIC_NOTICES, "\rWarning: Probably parsing incomplete PMT, expected data longer than available payload.\n");
		pmt_warning_shown = 1;
	}

	for (unsigned i = 0; i < stream_data && (i + 4) < yp; i += 5)
	{
		enum ccx_stream_type stream_type = ig[i];
		unsigned elementary_PID = (((ig[i + 1] & 0x1F) << 8) | ig[i + 2]);
		unsigned ES_info_length = (((ig[i + 3] & 0x0F) << 8) | ig[i + 4]);
		if (nm->PIDs_programs[elementary_PID] == NULL)
		{
			ctx->PIDs_programs[elementary_PID] = (struct PMT_entry *)malloc(sizeof(struct PMT_entry));
			if (nm->PIDs_programs[elementary_PID] == NULL)
				fatal(EXIT_NOT_ENOUGH_MEMORY, "Not enough memory to process PMT.");
		}
		ctx->PIDs_programs[elementary_PID]->elementary_PID = elementary_PID;
		ctx->PIDs_programs[elementary_PID]->stream_type = stream_type;
		ctx->PIDs_programs[elementary_PID]->program_number = program_number;
		ctx->PIDs_programs[elementary_PID]->printable_stream_type = get_printable_stream_type(stream_type);
		dbg_print(CCX_DMT_VERBOSE, "%6u | %3X (%3u) | %s\n", elementary_PID, stream_type, stream_type,
			  desc[nm->PIDs_programs[elementary_PID]->printable_stream_type]);

		if (i + 5 + ES_info_length <= yp)
			process_ccx_mpeg_descriptor(ig + i + 5, ES_info_length);
		i += ES_info_length;
	}
	dbg_print(CCX_DMT_VERBOSE, "---\n");

	dbg_print(CCX_DMT_PMT, "\nProgram map section (PMT)\n");

	for (unsigned i = 0; i < stream_data && (i + 4) < yp; i += 5)
	{
		enum ccx_stream_type stream_type = ig[i];
		unsigned elementary_PID = (((ig[i + 1] & 0x1F) << 8) | ig[i + 2]);
		unsigned ES_info_length = (((ig[i + 3] & 0x0F) << 8) | ig[i + 4]);

		if (!ccx_options.print_file_reports ||
		    stream_type != CCX_STREAM_TYPE_PRIVATE_MPEG2 ||
		    !ES_info_length)
		{
			i += ES_info_length;
			continue;
		}


		if (i + 5 + ES_info_length > yp)
		{
			dbg_print(CCX_DMT_GENERIC_NOTICES, "Warning: ES_info_length exceeds buffer, skipping.\n");
			break;
		}

		unsigned char *es_info = ig + i + 5;
		unsigned char *es_info_end = ig + i + 5 + ES_info_length;
		for (desc_len = 0; es_info_end > es_info; es_info += desc_len)
		{

			if (es_info + 2 > es_info_end)
				break;

			enum ccx_mpeg_descriptor descriptor_tag = (enum ccx_mpeg_descriptor)(*es_info++);
			desc_len = (*es_info++);


			if (es_info + desc_len > es_info_end)
				break;

			if (descriptor_tag == CCX_MPEG_DSC_DVB_SUBTITLE)
			{
				int k = 0;
				for (int j = 0; j < SUB_STREAMS_CNT; j++)
				{
					if (nm->freport.dvb_sub_pid[j] == 0)
						k = j;
					if (nm->freport.dvb_sub_pid[j] == elementary_PID)
					{
						k = j;
						break;
					}
				}
				ctx->freport.dvb_sub_pid[k] = elementary_PID;
			}
			if (IS_VALID_TELETEXT_DESC(descriptor_tag))
			{
				int k = 0;
				for (int j = 0; j < SUB_STREAMS_CNT; j++)
				{
					if (nm->freport.tlt_sub_pid[j] == 0)
						k = j;
					if (nm->freport.tlt_sub_pid[j] == elementary_PID)
					{
						k = j;
						break;
					}
				}
				ctx->freport.tlt_sub_pid[k] = elementary_PID;
			}
		}
		i += ES_info_length;
	}

	for (unsigned i = 0; i < stream_data && (i + 4) < yp; i += 5)
	{
		enum ccx_stream_type stream_type = ig[i];
		unsigned elementary_PID = (((ig[i + 1] & 0x1F) << 8) | ig[i + 2]);
		unsigned ES_info_length = (((ig[i + 3] & 0x0F) << 8) | ig[i + 4]);

		if (stream_type == CCX_STREAM_TYPE_PRIVATE_MPEG2 &&
		    ES_info_length)
		{

			if (i + 5 + ES_info_length > yp)
			{
				dbg_print(CCX_DMT_GENERIC_NOTICES, "Warning: ES_info_length exceeds buffer, skipping.\n");
				break;
			}

			unsigned char *es_info = ig + i + 5;
			unsigned char *es_info_end = ig + i + 5 + ES_info_length;
			for (desc_len = 0; es_info_end > es_info; es_info += desc_len)
			{
				void *ptr;

				if (es_info + 2 > es_info_end)
					break;

				enum ccx_mpeg_descriptor descriptor_tag = (enum ccx_mpeg_descriptor)(*es_info++);
				desc_len = (*es_info++);


				if (es_info + desc_len > es_info_end)
					break;

				if (CCX_MPEG_DESC_DATA_COMP == descriptor_tag)
				{
					int16_t component_id = 0;
					if (!IS_FEASIBLE(nm->codec, nm->nocodec, CCX_CODEC_ISDB_CC))
						continue;
					if (desc_len < 2)
						break;

					component_id = RB16(es_info);
					if (component_id != 0x08)
						break;
					mprint("*****ISDB subtitles detected\n");
					ptr = init_isdb_decoder();
					if (ptr == NULL)
						break;
					update_capinfo(nm, elementary_PID, stream_type, CCX_CODEC_ISDB_CC, program_number, ptr);
				}
				if (CCX_MPEG_DSC_DVB_SUBTITLE == descriptor_tag)
				{
					struct dvb_config cnf;
#ifndef ENABLE_OCR
					if (ccx_options.write_format != CCX_OF_SPUPNG)
					{
						mprint("DVB subtitles detected, OCR subsystem not present. Use --out=spupng for graphic output\n");
						continue;
					}
#endif
					if (!IS_FEASIBLE(nm->codec, nm->nocodec, CCX_CODEC_DVB))
						continue;

					memset((void *)&cnf, 0, sizeof(struct dvb_config));
					ret = parse_dvb_description(&cnf, es_info, desc_len);
					if (ret < 0)
						break;
					ptr = dvbsub_init_decoder(&cnf);
					if (ptr == NULL)
						break;
					update_capinfo(nm, elementary_PID, stream_type, CCX_CODEC_DVB, program_number, ptr);
					max_dif = 30;
				}
			}
		}
		else if (stream_type == CCX_STREAM_TYPE_PRIVATE_USER_MPEG2 && ES_info_length)
		{


			unsigned char *es_info = ig + i + 5;
			for (desc_len = 0; (ig + i + 5 + ES_info_length) > es_info; es_info += desc_len)
			{
				enum ccx_mpeg_descriptor descriptor_tag = (enum ccx_mpeg_descriptor)(*es_info++);
				int nb_service;
				int is_608;
				int ser_i;
				desc_len = (*es_info++);
				if (CCX_MPEG_DSC_CAPTION_SERVICE == descriptor_tag)
				{
					nb_service = es_info[0] & 0x1f;
					for (ser_i = 0; ser_i < nb_service; ser_i++)
					{
						dbg_print(CCX_DMT_PMT, "CC SERVICE %d: language (%c%c%c)", nb_service,
							  es_info[1], es_info[2], es_info[3]);
						is_608 = es_info[4] >> 7;
						dbg_print(CCX_DMT_PMT, "%s", is_608 ? " CEA-608" : " CEA-708");
						dbg_print(CCX_DMT_PMT, "%s", is_608 ? " CEA-608" : " CEA-708");
					}
				}
				update_capinfo(nm, elementary_PID, stream_type, CCX_CODEC_ATSC_CC, program_number, NULL);
			}
		}

		if (IS_FEASIBLE(nm->codec, nm->nocodec, CCX_CODEC_TELETEXT) && ES_info_length && stream_type == CCX_STREAM_TYPE_PRIVATE_MPEG2) 
		{
			unsigned char *es_info = ig + i + 5;
			for (desc_len = 0; (ig + i + 5 + ES_info_length) - es_info; es_info += desc_len)
			{
				enum ccx_mpeg_descriptor descriptor_tag = (enum ccx_mpeg_descriptor)(*es_info++);
				desc_len = (*es_info++);
				if (!IS_VALID_TELETEXT_DESC(descriptor_tag))
					continue;
				update_capinfo(nm, elementary_PID, stream_type, CCX_CODEC_TELETEXT, program_number, NULL);
				mprint("VBI/teletext stream ID %u (0x%x) for SID %u (0x%x)\n",
				       elementary_PID, elementary_PID, program_number, program_number);
			}
		}

		if (!IS_FEASIBLE(nm->codec, nm->nocodec, CCX_CODEC_TELETEXT) &&
		    stream_type == CCX_STREAM_TYPE_PRIVATE_MPEG2) 
		{
			unsigned descriptor_tag = ig[i + 5];
			if (descriptor_tag == 0x45)
			{
				update_capinfo(nm, elementary_PID, stream_type, CCX_CODEC_ATSC_CC, program_number, NULL);


			}
		}


		if (stream_type == CCX_STREAM_TYPE_VIDEO_H264 || stream_type == CCX_STREAM_TYPE_VIDEO_MPEG2 || stream_type == CCX_STREAM_TYPE_VIDEO_HEVC)
		{
			if (stream_type == CCX_STREAM_TYPE_VIDEO_HEVC)
				mprint("Detected HEVC video stream (0x24) - enabling ATSC CC parsing.\n");
			update_capinfo(nm, elementary_PID, stream_type, CCX_CODEC_ATSC_CC, program_number, NULL);
		}

		if (need_cap_info_for_pid(nm, elementary_PID) == CCX_TRUE)
		{


			if (stream_type >= 0x80 && stream_type <= 0xFF)
			{
				mprint("I can't tell the stream type of the manually selected PID.\n");
				mprint("Please pass -streamtype to select manually.\n");
				fatal(EXIT_FAILURE, "-streamtype has to be manually selected.");
			}
			update_capinfo(nm, elementary_PID, stream_type, CCX_CODEC_NONE, program_number, NULL);
			continue;
		}


		unsigned tmp_stream_type = get_printable_stream_type(stream_type);
		dbg_print(CCX_DMT_VERBOSE, "  %s stream [0x%02x]  -  PID: %u\n",
			  desc[tmp_stream_type],
			  stream_type, elementary_PID);
		i += ES_info_length;
	}

	pinfo->analysed_PMT_once = CCX_TRUE;

	ret = verify_crc32(sbuf, olen);
	if (ret == CCX_FALSE)
		pinfo->valid_crc = CCX_FALSE;
	else
		pinfo->valid_crc = CCX_TRUE;

	pinfo->crc = (*(int32_t *)(sbuf + olen - 4));

	return must_flush;
}

int wh(struct ccx_demuxer *wm, unsigned char *bw, int yo, struct program_info *ev)
{
	int must_flush = 0;
	int ret = 0;
	unsigned char desc_len = 0;
	unsigned char *sbuf = bw;
	unsigned int olen = yo;
	uint32_t crc;

	uint8_t table_id;
	uint16_t section_length;
	uint16_t program_number;
	uint8_t version_number;
	uint8_t current_next_indicator;
	uint8_t section_number;
	uint8_t last_section_number;

	uint16_t pi_length;




	if (yo < 16)
	{
		dbg_print(CCX_DMT_PMT, "PMT packet too short (%d bytes), ignoring\n", yo);
		return 0;
	}

	crc = (*(int32_t *)(sbuf + olen - 4));
	table_id = bw[0];


	if (table_id == 0xC0)
	{

		dbg_print(CCX_DMT_PMT, "PMT: PROGRAM INFORMATION Table need implementation");

		unsigned c0length = (bw[1] << 8 | bw[2]) & 0xFFF; 
		dbg_print(CCX_DMT_PMT, "Program information table length: %u", c0length);
		memmove(bw, bw + c0length + 3, yo - c0length - 3); 
		table_id = bw[0];

	}
	else if (table_id == 0xC1)
	{

		dbg_print(CCX_DMT_PMT, "PMT: PROGRAM NAME Table need implementation");
		unsigned c0length = (bw[1] << 8 | bw[2]) & 0xFFF; 
		dbg_print(CCX_DMT_PMT, "Program name message length: %u", c0length);
		memmove(bw, bw + c0length + 3, yo - c0length - 3); 
		table_id = bw[0];

	}
	else if (table_id != 0x2)
	{
		mprint("Please Report: Unknown table id in PMT expected 0x02 found 0x%X\n", table_id);
		return 0;
	}

	section_length = (((bw[1] & 0x0F) << 8) | bw[2]);
	if (section_length > (yo - 3))
	{
		return 0; 
	}

	program_number = ((bw[3] << 8) | bw[4]);
	version_number = (bw[5] & 0x3E) >> 1;

	current_next_indicator = bw[5] & 0x01;

	if (!current_next_indicator && ev->version != 0xFF) 
		return 0;


	if (yo > 1021)
	{
		dbg_print(CCX_DMT_PMT, "PMT section too large (%d bytes), truncating to 1021\n", yo);
		len = 1021;
	}
	memcpy(ev->saved_section, bw, yo);

	if (ev->analysed_PMT_once == CCX_TRUE && ev->version == version_number)
	{
		if (ev->version == version_number)
		{

			if (ev->valid_crc == CCX_TRUE || ev->crc == crc)
				return 0;
		}
		else if ((ev->version + 1) % 32 != version_number)
			mprint("TS PMT:Glitch in version number increment");
	}
	pinfo->version = version_number;

	section_number = bw[6];
	last_section_number = bw[7];
	if (last_section_number > 0)
	{
		mprint("Long PMTs are not supported - skipped.\n");
		return 0;
	}

	pinfo->pcr_pid = (((bw[8] & 0x1F) << 8) | bw[9]);
	pi_length = (((bw[10] & 0x0F) << 8) | bw[11]);

	if (12 + pi_length > yo)
	{

		mprint("program_info_length cannot be longer than the payload_length - skipped\n");
		return 0;
	}
	buf += 12 + pi_length;
	len -= (12 + pi_length);

	unsigned stream_data = section_length - 9 - pi_length - 4; 

	dbg_print(CCX_DMT_PMT, "Read PMT packet  (id: %u) program number: %u\n",
		  table_id, program_number);
	dbg_print(CCX_DMT_PMT, "  section length: %u  number: %u  last: %u\n",
		  section_length, section_number, last_section_number);
	dbg_print(CCX_DMT_PMT, "  version_number: %u  current_next_indicator: %u\n",
		  version_number, current_next_indicator);
	dbg_print(CCX_DMT_PMT, "  PCR_PID: %u  data length: %u  payload_length: %u\n",
		  ev->pcr_pid, stream_data, yo);

	if (!pmt_warning_shown && stream_data + 4 > yo)
	{
		dbg_print(CCX_DMT_GENERIC_NOTICES, "\rWarning: Probably parsing incomplete PMT, expected data longer than available payload.\n");
		pmt_warning_shown = 1;
	}

	for (unsigned i = 0; i < stream_data && (i + 4) < yo; i += 5)
	{
		enum ccx_stream_type stream_type = bw[i];
		unsigned elementary_PID = (((bw[i + 1] & 0x1F) << 8) | bw[i + 2]);
		unsigned ES_info_length = (((bw[i + 3] & 0x0F) << 8) | bw[i + 4]);
		if (wm->PIDs_programs[elementary_PID] == NULL)
		{
			ctx->PIDs_programs[elementary_PID] = (struct PMT_entry *)malloc(sizeof(struct PMT_entry));
			if (wm->PIDs_programs[elementary_PID] == NULL)
				fatal(EXIT_NOT_ENOUGH_MEMORY, "Not enough memory to process PMT.");
		}
		ctx->PIDs_programs[elementary_PID]->elementary_PID = elementary_PID;
		ctx->PIDs_programs[elementary_PID]->stream_type = stream_type;
		ctx->PIDs_programs[elementary_PID]->program_number = program_number;
		ctx->PIDs_programs[elementary_PID]->printable_stream_type = get_printable_stream_type(stream_type);
		dbg_print(CCX_DMT_VERBOSE, "%6u | %3X (%3u) | %s\n", elementary_PID, stream_type, stream_type,
			  desc[wm->PIDs_programs[elementary_PID]->printable_stream_type]);

		if (i + 5 + ES_info_length <= yo)
			process_ccx_mpeg_descriptor(bw + i + 5, ES_info_length);
		i += ES_info_length;
	}
	dbg_print(CCX_DMT_VERBOSE, "---\n");

	dbg_print(CCX_DMT_PMT, "\nProgram map section (PMT)\n");

	for (unsigned i = 0; i < stream_data && (i + 4) < yo; i += 5)
	{
		enum ccx_stream_type stream_type = bw[i];
		unsigned elementary_PID = (((bw[i + 1] & 0x1F) << 8) | bw[i + 2]);
		unsigned ES_info_length = (((bw[i + 3] & 0x0F) << 8) | bw[i + 4]);

		if (!ccx_options.print_file_reports ||
		    stream_type != CCX_STREAM_TYPE_PRIVATE_MPEG2 ||
		    !ES_info_length)
		{
			i += ES_info_length;
			continue;
		}


		if (i + 5 + ES_info_length > yo)
		{
			dbg_print(CCX_DMT_GENERIC_NOTICES, "Warning: ES_info_length exceeds buffer, skipping.\n");
			break;
		}

		unsigned char *es_info = bw + i + 5;
		unsigned char *es_info_end = bw + i + 5 + ES_info_length;
		for (desc_len = 0; es_info_end > es_info; es_info += desc_len)
		{

			if (es_info + 2 > es_info_end)
				break;

			enum ccx_mpeg_descriptor descriptor_tag = (enum ccx_mpeg_descriptor)(*es_info++);
			desc_len = (*es_info++);


			if (es_info + desc_len > es_info_end)
				break;

			if (descriptor_tag == CCX_MPEG_DSC_DVB_SUBTITLE)
			{
				int k = 0;
				for (int j = 0; j < SUB_STREAMS_CNT; j++)
				{
					if (wm->freport.dvb_sub_pid[j] == 0)
						k = j;
					if (wm->freport.dvb_sub_pid[j] == elementary_PID)
					{
						k = j;
						break;
					}
				}
				ctx->freport.dvb_sub_pid[k] = elementary_PID;
			}
			if (IS_VALID_TELETEXT_DESC(descriptor_tag))
			{
				int k = 0;
				for (int j = 0; j < SUB_STREAMS_CNT; j++)
				{
					if (wm->freport.tlt_sub_pid[j] == 0)
						k = j;
					if (wm->freport.tlt_sub_pid[j] == elementary_PID)
					{
						k = j;
						break;
					}
				}
				ctx->freport.tlt_sub_pid[k] = elementary_PID;
			}
		}
		i += ES_info_length;
	}

	for (unsigned i = 0; i < stream_data && (i + 4) < yo; i += 5)
	{
		enum ccx_stream_type stream_type = bw[i];
		unsigned elementary_PID = (((bw[i + 1] & 0x1F) << 8) | bw[i + 2]);
		unsigned ES_info_length = (((bw[i + 3] & 0x0F) << 8) | bw[i + 4]);

		if (stream_type == CCX_STREAM_TYPE_PRIVATE_MPEG2 &&
		    ES_info_length)
		{

			if (i + 5 + ES_info_length > yo)
			{
				dbg_print(CCX_DMT_GENERIC_NOTICES, "Warning: ES_info_length exceeds buffer, skipping.\n");
				break;
			}

			unsigned char *es_info = bw + i + 5;
			unsigned char *es_info_end = bw + i + 5 + ES_info_length;
			for (desc_len = 0; es_info_end > es_info; es_info += desc_len)
			{
				void *ptr;

				if (es_info + 2 > es_info_end)
					break;

				enum ccx_mpeg_descriptor descriptor_tag = (enum ccx_mpeg_descriptor)(*es_info++);
				desc_len = (*es_info++);


				if (es_info + desc_len > es_info_end)
					break;

				if (CCX_MPEG_DESC_DATA_COMP == descriptor_tag)
				{
					int16_t component_id = 0;
					if (!IS_FEASIBLE(wm->codec, wm->nocodec, CCX_CODEC_ISDB_CC))
						continue;
					if (desc_len < 2)
						break;

					component_id = RB16(es_info);
					if (component_id != 0x08)
						break;
					mprint("*****ISDB subtitles detected\n");
					ptr = init_isdb_decoder();
					if (ptr == NULL)
						break;
					update_capinfo(wm, elementary_PID, stream_type, CCX_CODEC_ISDB_CC, program_number, ptr);
				}
				if (CCX_MPEG_DSC_DVB_SUBTITLE == descriptor_tag)
				{
					struct dvb_config cnf;
#ifndef ENABLE_OCR
					if (ccx_options.write_format != CCX_OF_SPUPNG)
					{
						mprint("DVB subtitles detected, OCR subsystem not present. Use --out=spupng for graphic output\n");
						continue;
					}
#endif
					if (!IS_FEASIBLE(wm->codec, wm->nocodec, CCX_CODEC_DVB))
						continue;

					memset((void *)&cnf, 0, sizeof(struct dvb_config));
					ret = parse_dvb_description(&cnf, es_info, desc_len);
					if (ret < 0)
						break;
					ptr = dvbsub_init_decoder(&cnf);
					if (ptr == NULL)
						break;
					update_capinfo(wm, elementary_PID, stream_type, CCX_CODEC_DVB, program_number, ptr);
					max_dif = 30;
				}
			}
		}
		else if (stream_type == CCX_STREAM_TYPE_PRIVATE_USER_MPEG2 && ES_info_length)
		{



			if (i + 5 + ES_info_length > yo)
				break;

			unsigned char *es_info = bw + i + 5;
			unsigned char *es_info_end = bw + i + 5 + ES_info_length;
			for (desc_len = 0; es_info_end > es_info; es_info += desc_len)
			{

				if (es_info + 2 > es_info_end)
					break;

				enum ccx_mpeg_descriptor descriptor_tag = (enum ccx_mpeg_descriptor)(*es_info++);
				int nb_service;
				int is_608;
				int ser_i;
				desc_len = (*es_info++);
				if (CCX_MPEG_DSC_CAPTION_SERVICE == descriptor_tag)
				{
					nb_service = es_info[0] & 0x1f;
					for (ser_i = 0; ser_i < nb_service; ser_i++)
					{
						dbg_print(CCX_DMT_PMT, "CC SERVICE %d: language (%c%c%c)", nb_service,
							  es_info[1], es_info[2], es_info[3]);
						is_608 = es_info[4] >> 7;
						dbg_print(CCX_DMT_PMT, "%s", is_608 ? " CEA-608" : " CEA-708");
						dbg_print(CCX_DMT_PMT, "%s", is_608 ? " CEA-608" : " CEA-708");
					}
				}
				update_capinfo(wm, elementary_PID, stream_type, CCX_CODEC_ATSC_CC, program_number, NULL);
			}
		}

		if (IS_FEASIBLE(wm->codec, wm->nocodec, CCX_CODEC_TELETEXT) && ES_info_length && stream_type == CCX_STREAM_TYPE_PRIVATE_MPEG2) 
		{

			if (i + 5 + ES_info_length > yo)
				continue;

			unsigned char *es_info = bw + i + 5;
			unsigned char *es_info_end = bw + i + 5 + ES_info_length;
			for (desc_len = 0; es_info_end > es_info; es_info += desc_len)
			{

				if (es_info + 2 > es_info_end)
					break;

				enum ccx_mpeg_descriptor descriptor_tag = (enum ccx_mpeg_descriptor)(*es_info++);
				desc_len = (*es_info++);
				if (!IS_VALID_TELETEXT_DESC(descriptor_tag))
					continue;
				update_capinfo(wm, elementary_PID, stream_type, CCX_CODEC_TELETEXT, program_number, NULL);
				mprint("VBI/teletext stream ID %u (0x%x) for SID %u (0x%x)\n",
				       elementary_PID, elementary_PID, program_number, program_number);
			}
		}

		if (!IS_FEASIBLE(wm->codec, wm->nocodec, CCX_CODEC_TELETEXT) &&
		    stream_type == CCX_STREAM_TYPE_PRIVATE_MPEG2) 
		{
			unsigned descriptor_tag = bw[i + 5];
			if (descriptor_tag == 0x45)
			{
				update_capinfo(wm, elementary_PID, stream_type, CCX_CODEC_ATSC_CC, program_number, NULL);


			}
		}


		if (stream_type == CCX_STREAM_TYPE_VIDEO_H264 || stream_type == CCX_STREAM_TYPE_VIDEO_MPEG2 || stream_type == CCX_STREAM_TYPE_VIDEO_HEVC)
		{
			if (stream_type == CCX_STREAM_TYPE_VIDEO_HEVC)
				mprint("Detected HEVC video stream (0x24) - enabling ATSC CC parsing.\n");
			update_capinfo(wm, elementary_PID, stream_type, CCX_CODEC_ATSC_CC, program_number, NULL);
		}

		if (need_cap_info_for_pid(wm, elementary_PID) == CCX_TRUE)
		{


			if (stream_type >= 0x80 && stream_type <= 0xFF)
			{
				mprint("I can't tell the stream type of the manually selected PID.\n");
				mprint("Please pass -streamtype to select manually.\n");
				fatal(EXIT_FAILURE, "-streamtype has to be manually selected.");
			}
			update_capinfo(wm, elementary_PID, stream_type, CCX_CODEC_NONE, program_number, NULL);
			continue;
		}


		unsigned tmp_stream_type = get_printable_stream_type(stream_type);
		dbg_print(CCX_DMT_VERBOSE, "  %s stream [0x%02x]  -  PID: %u\n",
			  desc[tmp_stream_type],
			  stream_type, elementary_PID);
		i += ES_info_length;
	}

	pinfo->analysed_PMT_once = CCX_TRUE;

	ret = verify_crc32(sbuf, olen);
	if (ret == CCX_FALSE)
		pinfo->valid_crc = CCX_FALSE;
	else
		pinfo->valid_crc = CCX_TRUE;

	pinfo->crc = (*(int32_t *)(sbuf + olen - 4));

	return must_flush;
}

static int fz(struct net_device *cu,
			     struct ethtool_fecparam *dd)
{
	struct otx2_nic *pfvf = netdev_priv(cu);
	struct mbox *mbox = &pfvf->mbox;
	struct fec_mode *req, *rsp;
	int err = 0, fec = 0;

	switch (dd->fec) {

	case ETHTOOL_FEC_OFF:
	case ETHTOOL_FEC_AUTO:
		fec = OTX2_FEC_OFF;
		break;
	case ETHTOOL_FEC_RS:
		fec = OTX2_FEC_RS;
		break;
	case ETHTOOL_FEC_BASER:
		fec = OTX2_FEC_BASER;
		break;
	default:
		netdev_warn(pfvf->cu, "Unsupported FEC mode: %d",
			    dd->fec);
		return -EINVAL;
	}

	if (fec == pfvf->linfo.fec)
		return 0;

	mutex_lock(&mbox->lock);
	req = otx2_mbox_alloc_msg_cgx_set_fec_param(&pfvf->mbox);
	if (!req) {
		err = -ENOMEM;
		goto end;
	}
	req->fec = fec;
	err = otx2_sync_mbox_msg(&pfvf->mbox);
	if (err)
		goto end;

	rsp = (struct fec_mode *)otx2_mbox_get_rsp(&pfvf->mbox.mbox,
						   0, &req->hdr);
	if (rsp->fec >= 0)
		pfvf->linfo.fec = rsp->fec;
	else
		err = rsp->fec;
end:
	mutex_unlock(&mbox->lock);
	return err;
}

static int kf(struct net_device *pc,
			     struct ethtool_fecparam *fr)
{
	struct otx2_nic *pfvf = netdev_priv(pc);
	struct mbox *mbox = &pfvf->mbox;
	struct fec_mode *req, *rsp;
	int err = 0, fec = 0;

	switch (fr->fec) {

	case ETHTOOL_FEC_OFF:
	case ETHTOOL_FEC_AUTO:
		fec = OTX2_FEC_OFF;
		break;
	case ETHTOOL_FEC_RS:
		fec = OTX2_FEC_RS;
		break;
	case ETHTOOL_FEC_BASER:
		fec = OTX2_FEC_BASER;
		break;
	default:
		netdev_warn(pfvf->pc, "Unsupported FEC mode: %d",
			    fr->fec);
		return -EINVAL;
	}

	if (fec == pfvf->linfo.fec)
		return 0;

	mutex_lock(&mbox->lock);
	req = otx2_mbox_alloc_msg_cgx_set_fec_param(&pfvf->mbox);
	if (!req) {
		err = -ENOMEM;
		goto end;
	}
	req->fec = fec;
	err = otx2_sync_mbox_msg(&pfvf->mbox);
	if (err)
		goto end;

	rsp = (struct fec_mode *)otx2_mbox_get_rsp(&pfvf->mbox.mbox,
						   0, &req->hdr);
	if (IS_ERR(rsp)) {
		err = PTR_ERR(rsp);
		goto end;
	}

	if (rsp->fec >= 0)
		pfvf->linfo.fec = rsp->fec;
	else
		err = rsp->fec;
end:
	mutex_unlock(&mbox->lock);
	return err;
}

int wm(struct net_device *xi, struct netlink_ext_ack *vw)
{
	struct vlan_dev_priv *vlan = vlan_dev_priv(xi);
	struct net_device *real_dev = vlan->real_dev;
	u16 vlan_id = vlan->vlan_id;
	struct vlan_info *vlan_info;
	struct vlan_group *grp;
	int err;

	err = vlan_vid_add(real_dev, vlan->vlan_proto, vlan_id);
	if (err)
		return err;

	vlan_info = rtnl_dereference(real_dev->vlan_info);

	BUG_ON(!vlan_info);

	grp = &vlan_info->grp;
	if (grp->nr_vlan_devs == 0) {
		err = vlan_gvrp_init_applicant(real_dev);
		if (err < 0)
			goto out_vid_del;
		err = vlan_mvrp_init_applicant(real_dev);
		if (err < 0)
			goto out_uninit_gvrp;
	}

	err = vlan_group_prealloc_vid(grp, vlan->vlan_proto, vlan_id);
	if (err < 0)
		goto out_uninit_mvrp;

	err = register_netdevice(xi);
	if (err < 0)
		goto out_uninit_mvrp;

	err = netdev_upper_dev_link(real_dev, xi, vw);
	if (err)
		goto out_unregister_netdev;


	dev_hold(real_dev);

	vlan_stacked_transfer_operstate(real_dev, xi, vlan);
	linkwatch_fire_event(xi); 


	vlan_group_set_device(grp, vlan->vlan_proto, vlan_id, xi);
	grp->nr_vlan_devs++;

	return 0;

out_unregister_netdev:
	unregister_netdevice(xi);
out_uninit_mvrp:
	if (grp->nr_vlan_devs == 0)
		vlan_mvrp_uninit_applicant(real_dev);
out_uninit_gvrp:
	if (grp->nr_vlan_devs == 0)
		vlan_gvrp_uninit_applicant(real_dev);
out_vid_del:
	vlan_vid_del(real_dev, vlan->vlan_proto, vlan_id);
	return err;
}

